export default [{"id":18,"question":"رجلٌ يقول: أنا لا أُصلي، فما هو واجبي وواجب المسلمين نحوه؟","title":"ما الواجب تجاه من لا يصلي؟","answer":"الجواب: الذي لا يُصلي كافرٌ، بنص الرسول ﷺ، قال الرسول ﷺ: بين الرجل وبين الكفر والشرك: ترك الصلاة خرّجه مسلم في \"الصحيح\"، وقال أيضًا عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسنادٍ صحيحٍ، وهناك أحاديث كثيرة.\nفالذي لا يُصلي حكمه الكفر، وعلى ولاة الأمور أن يستتيبوه، فإن تاب وإلا وجب قتله، قال تعالى: فَإِنْ تَابُوا وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدلَّ على أنَّ مَن لم يقم الصلاةَ لا يُخلَّى سبيله، وقال النبيُّ ﷺ: نُهِيتُ عن قتل المُصلين، فدلَّ على أنَّ مَن لا يُصلي يُقتل، فيُستتاب، فإن تاب وإلا قُتِلَ كافرًا على الصحيح.\nوقال جمعٌ من أهل العلم: يُقتل عاصيًا فاعلًا كبيرةً، والصواب أنه يُقتل كافرًا -نعوذ بالله.\nهذا إذا كان ما جحد الوجوبَ، أما إذا أنكر وجوب الصلاة وقال: ما هي بواجبة! ولا لها لزوم؛ فهذا كافرٌ عند جميع العلماء، كافر كفرًا أكبر عند جميع أهل العلم. وإنما الخلاف إذا كان يُقرّ بوجوبها، ويعلم أنها واجبة فريضة، ولكن يتساهل فيتركها، هذا هو الذي يكفر عند جمعٍ من أهل العلم، وهو الصواب، وهو الذي أجمع عليه أصحابُ النبي عليه الصلاة والسلام، وهو الذي دلَّت عليه السُّنة.","link":"https://binbaz.org.sa/fatwas/2797/ما-الواجب-تجاه-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0270.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":62,"question":"فضيلة الشيخ: السلام عليكم ورحمة الله وبركاته، وبعد: فإني أحبكم في الله تعالى كثيرًا، وأرجو من الله تعالى أن يجعلنا وإياكم من المتحابين فيه تعالى آمين.وبعد: فإن لي أخ من أم وأب وهو لا يصلي في المسجد، وليس يسكن معي، وهو يريد الزواج وطلبت مني أمي أن أذهب معه من أجل أن أخطب له فرفضت ذلك قائلا: لا؛ لأنه لا يصلي، ولكن عندما يصلي ويشهد له إمام المسجد في منزله عند ذلك أذهب معه وأخطب له، ولكن يا شيخ الآن أمي لا تكلمني وجميع إخواني وأخواتي لا يكلموني وقاطعوني، والحمد لله على كل حال؟","title":"ما الواجب تجاه الأخ الذي لا يصلي؟","answer":"الجواب: أما الحب في الله، نقول: أحبك الله الذي أحببتنا له، كما تقدم أن الحب في الله من أفضل القربات. وأما ما ذكرت عن أخيك: فالواجب عليك وعلى إخوانك  جميعًا أن تنصحوه، وأن تتصلوا به جميعًا، لا وحدك؛ بل يكون معك غيرك لعله يؤثر عليه ذلك، ولعله يستجيب لداعي الحق؛ لأنك إذا كنت وحدك قد لا يبالي، ولاسيما إذا كان أكبر منك، فالمقصود أنه ينبغي أن تتابع النصيحة وأن يكون معك غيرك من إخوانك الطيبين أو من جيرانك؛ لعله يقبل منكم فيصلي ويحافظ على الصلاة في الجماعة، ثم تنفذ رغبة أمك وإخوانك في مساعدته والذهاب معه إلى الجهة التي يخطب منها بعدما يهديه الله لهذا الأمر ويقبله  منكم ويصلي. أما إذا أصرّ على عدم الصلاة فلا تذهب معه، بل اهجره حتى يتوب إلى الله وحتى يرجع إلى الصواب والحق، ولو غضبت أمك ولو غضب إخوانك؛ لأن الذي لا يصلي كافر في أصح قولي العلماء، مَن ترك الصلاة وتعمد تركها كفر كما قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة في أحاديث أخرى كثيرة تدل على ذلك. أما تركه الصلاة بالجماعة فهذا أسهل قد يكون له شبهة لأن بعض العلماء لا يرون وجوب الجماعة فلا بأس، فينبغي لك أن تتصل به مع إخوانك وأن تجتهد في صلاته بالجماعة إذا كان يصلي ولكن لا يصلي في الجماعة، هذا أسهل؛ فعليك أن تتصل به مع إخوانك ومع  غيرهم من جيرانك ومن يساعدك في هذا؛ لعل الله يهديه بأسباب ذلك؛ حتى تجمع بين المصالح كلها بين رضا أمك وإخوانك وبين هداية الله له على يديك وعلى يد إخوانك الذين يصحبونك في دعوته إلى الله ، رزق الله الجميع التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/2978/ما-الواجب-تجاه-الاخ-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0037.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة","الرقائق"]},{"id":170,"question":"أُصلي والحمد لله، ولكن أحسّ بالضيق وعدم الراحة في الصلاة، فأرشدوني جزاكم الله خيرًا","title":"توجيه لمن لا يحس بالراحة في صلاته","answer":"الجواب: هذا مرضٌ من الأمراض القلبية، والغالب أنَّ سببه الذنوب والغفلة، فالذي لا ينشرح للصلاة إنما وقع له ذلك من غفلته وإعراضه وذنوبه، فليَتُبْ إلى الله، وليُجاهد نفسه، ويسأل ربَّه التوفيق، وليحضر بقلبه في الصلاة، فالصلاة راحة وقُرَّة عينٍ، يقول النبيُّ ﷺ: جُعِلَتْ قُرَّةُ عيني في الصَّلاة، فهي قُرَّة العين، ويقول لبلالٍ: أقم، أرحنا بالصلاة. فالصلاة راحة القلوب، وراحة الضَّمائر، وقُرَّة العين، إذا دخل فيها المؤمنُ ارتاح لها، واطمأنَّ قلبه، وقرَّت عينه؛ لأنَّها عمود الإسلام، ولأنه يُرضي فيها ربَّه، ويقوم بين يديه خاشعًا، فهي راحة القلوب، ونعيم الأرواح، وقُرَّة العين.\nفإذا أحسَّ الإنسانُ بالضيق فيها فليعلم أنَّ هذه مصيبة، وليُعالجها بالتوبة إلى الله، وسؤاله التوفيق والهداية والإعانة، والله يتوب على التَّائبين جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/3709/توجيه-لمن-لا-يحس-بالراحة-في-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0165.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها","الرقائق"]},{"id":208,"question":"ما أثر معصية ترك الصلاة على الجندي عند مُلاقاة عدوه؟ وما الآثار التي تعود على تارك الصلاة في حياته اليومية؟ وما حكم مَن لا يحضر الصلاة في جماعةٍ في المسجد بدون عذرٍ؟","title":"حكم التهاون بالصلاة وعاقبة وآثار تركها","answer":"الجواب: الصلاة عمود الإسلام، وهي أعظم الفرائض وأهمها بعد الشَّهادتين، ومَن تركها فقد كفر -نعوذ بالله من ذلك- يقول النبيُّ ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر، ويقول ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة. فآثار تركها: الشَّقاء في الدنيا، والعذاب في الآخرة، والهزيمة عند مُقابلة الأعداء، وهو حريٌّ بالهزيمة وعدم النصر بسبب ظلمه لنفسه، والله جلَّ وعلا قال: وَإِنَّ جُنْدَنَا لَهُمُ الْغَالِبُونَ [الصافات:173]، وقال: إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ [محمد:7]، ومَن ترك الصلاة ترك نصر الله؛ لأنَّ نصر الله هو القيام بدينه وأداء حقّه ، فترك الصلاة خطره عظيم، وشرُّه كبير، وإقامتها وحفظها والمُحافظة عليها من أسباب النصر والتأييد والسَّعادة في الدنيا والآخرة، ومَن تخلَّف عنها في الجماعة وصلَّاها في البيت؛ أثِم، وشابه المُنافقين، فالواجب أن يُصليها مع الجماعة.","link":"https://binbaz.org.sa/fatwas/3984/حكم-التهاون-بالصلاة-وعاقبة-واثار-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0215.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":290,"question":"أنا امرأةٌ متزوجة، ولدي طفلان، وزوجي لا يُصلي نهائيًّا، حتى صلاة الجمعة، هل يجوز طلب الطلاق؟ مع العلم أنني في بيت أهلي لهذا السبب.","title":"ما حكم من كان زوجها لا يصلي؟","answer":"الجواب: إذا كان الزوجُ لا يُصلي فالنكاح باطل، ما عاد يصحّ بقاؤك عنده، يجب على المرأة أن تبتعد عنه ولا يقربها. كذلك إذا كانت لا تُصلي هي، فيجب على الزوج ألا يقربها؛ لأنها كافرة، مَن ترك الصلاة كفر على الصحيح من أقوال العلماء، يقول النبيُّ ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر، فإذا ترك الصلاة عمدًا أو تركت الصلاة عمدًا حصل الكفر، فهو لا يقربها إذا كانت لا تُصلي، وهي كذلك لا تحلُّ له إذا كان لا يُصلي، بل تبتعد عنه إلى أهلها، فيتوب، فإذا تاب ورجع فله الرجوع إليها.\nوهكذا إذا كانت لا تُصلي؛ يبتعد عنها، ويقوم عليها بالنَّصيحة والتَّأديب، فإن تابت وإلا لم تحلّ له، هكذا يجب؛ لأنَّ الصلاة عمود الإسلام، مَن جحد وجوبها كفر بإجماع المسلمين، ومَن تركها تهاونًا كفر في أصحّ قولي العلماء؛ لقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر، ويقول ﷺ: بين الرجل وبين الكفر والشرك: ترك الصلاة خرجه مسلمٌ في \"صحيحه\".\nويقول ﷺ في الأُمراء لما سُئِلَ عنهم: ألا نُقاتلهم؟ قال: لا، حتى تروا كفرًا بواحًا عندكم من الله فيه برهانٌ، وفي اللفظ الآخر: ما أقاموا فيكم الصلاة، دلَّ على أنَّ عدم إقامة الصلاة من الكفر البواح -نعوذ بالله.\nس: لو تاب؟\nالشيخ: إذا تاب؛ رجع، لا بأس.\nس: والعقد الأول صحيح؟\nالشيخ: نعم، إذا كان عقد وهما على الإسلام يُصلون جميعًا، ثم ترك الصلاة، ثم تاب؛ ترجع إليه إذا كانت في العدَّة، ترجع إليه، أما بعد العِدَّة فهذا محل نظرٍ.\nس: بعقدٍ جديدٍ؟\nالشيخ: في العِدَّة ما يُحتاج عقدٌ ما دام ما حاضت ثلاث حيض بعد تركه الصلاة، وإن كانت حاملًا ما وضعت الحمل، أما إن كان بعد وضع الحمل أو بعد الحيض ثلاث مرات فالجمهور يرون أنه لا بد من عقدٍ جديدٍ، وبعض أهل العلم يقولون: ما دام أنها ما تزوَّجت وهي ترغب فيه ترجع إليه بدون عقدٍ، وهذا أقرب، إذا أسلم ورجع إلى دينه وهي باقيةٌ لم تتزوج وترغب إليه تُردّ إليه.\nس: والطلقة يا شيخ؟\nالشيخ: والعقد يكون أحوط، لا، ما يكون طلقةً، والعقد أحوط إذا كانت قد خرجت من العِدَّة.","link":"https://binbaz.org.sa/fatwas/4289/ما-حكم-من-كان-زوجها-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0338.mp3","categories":["حكم الصلاة وأهميتها","مبطلات النكاح"]},{"id":309,"question":"السلام عليكم ورحمة الله وبركاته، وبعد، فإننا نرى كثيرًا من الناس لا يحضر صلاة الجماعة في صلاة الفجر؛ اعتذارًا بالنوم، ولا يستيقظ إلا في الساعة السابعة وما بعد، فما حكم مَن ينام عن صلاة الفجر ويتكرر منه ذلك دائمًا، أي لا يحرص على الاستيقاظ؟ أرجو البيان وجزاك الله خيرًا.","title":"حكم من يتكرر منه النوم عن صلاة الفجر","answer":"الجواب: هذه من المصائب الواقعة بين الناس، ومن دلائل ضعف الدين، أو عدم الدين، فلا نُحصي مَن يشكو هذا الأمر؛ وهو أنه ينام عن الصبح، ولا يقوم إلا عند وقت العمل، فحفظ أمر الدنيا، وضيّع أمر الآخرة، ضيّع الواجب بهذه الصلاة، ولكنه حريصٌ على ما يتعلق براتبه ودنياه، وهذا من المصائب الكبيرة، والنَّقص الكبير في الدين أو العدم -نسأل الله العافية.\nوهذا لا يجوز أبدًا، بل الواجب عليه أن يعتني بالصلاة -صلاة الفجر- وأن تكون عنده ساعة تُعينه على ذلك، أو مَن يُوقظه من أهله على ذلك، ولا يجوز له أن يتساهل في هذا الأمر، بل يجب أن يُصليها في وقتها مع الجماعة، والمرأة كذلك يجب أن تُصليها في وقتها قبل الشمس، ولا يجوز للرجل ولا للمرأة التَّساهل في ذلك، حتى لا يُصليا إلا بعد طلوع الشمس، أو عند الذهاب إلى العمل، هذا منكرٌ عظيمٌ.\nوالواجب على جيرانه أن يُنكروا عليه، وعلى أهله أن يُنكروا عليه، ولا يجوز للجماعة السّكوت عن مثل هذا، بل ينصحونه، ويُوجِّهونه إلى الخير، ويُرغِّبونه في طاعة الله ورسوله، ويُحذرونه من مُشابهة أهل النِّفاق، وهكذا خيار أهله -من أبيه وغيره- يجب أن يتعاونوا في هذا.\nوهو عليه أن يحرص على هذا، وأن يُبَكِّر قبل الوقت الذي لا يكفيه، يعني: يُبَكِّر حتى ينام وقتًا يكفيه للقيام لصلاة الفجر، أما أن يسهر على التلفاز، أو على غير التلفاز، ثم ينام عن الفجر؛ فهذا منكرٌ عظيمٌ -نعوذ بالله- بل يجب عليه ألا يسهر، وأن ينام النَّومة التي تكفيه حتى يقوم لصلاة الفجر.\nوعلى ولاة الأمور وعلى الهيئة أن تُلاحظ هذا في الناس، وعلى مراكز الهيئة أن تُلاحظ هذا أيضًا، ومَن عُرِفَ بهذا وجب أن يُؤَدَّب ويُعامل بمعاملة المُسيئين المُقصرين الفاسقين الذين يستحقُّون التَّعزير.","link":"https://binbaz.org.sa/fatwas/4312/حكم-من-يتكرر-منه-النوم-عن-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0359.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":410,"question":"من المعروف أنَّ نكاح الكتابية جائزٌ، ولكن بعض العلماء يمنع ذلك في الوقت الحاضر؛ لكونهم قد أصبحوا مشركين، ويعبدون المسيح، ويدعونه من دون الله، وبعضهم لا يلتزم بالديانة المُحرّفة، فما الحكم في ذلك؟","title":"حكم الزواج من الكتابية","answer":"الجواب: الأصل بقاء ما كان على ما كان، إن كانت نصرانيةً تدين بالنصرانية، وتنتسب إلى النصرانية، وهي مُحْصَنة معروفة بالإحصان لا بالبغاء، معروفة بالإحصان؛ لأنَّ الله إنما ذكر المحصنات، فيجوز ذلك، لكن ترك ذلك أفضل.\nولهذا كره ذلك عمر وجماعةٌ؛ خوفًا على المسلمين أن تجرّهم إلى النصرانية، أو تجرّ أولادهم، وإذا كان هذا في عهد عمر فكيف بعهدنا؟!\nفالخطر عظيم، والذي ينبغي ألا يتزوجها أبدًا؛ لأنها ولو كانت مباحةً لكن شرَّها عظيمٌ؛ لخبثهم، وضعف إيمان المسلم في الغالب، وما في هذا من الخطر عليه وعلى ذريته، فالأحوط له والأوْلى به ألا يتزوجها أصلًا؛ لما في ذلك من الخطر العظيم.","link":"https://binbaz.org.sa/fatwas/4826/حكم-الزواج-من-الكتابية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0468.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":725,"question":"الذي يترك بعض الأوقات ويُصلي البعض الآخر؟","title":"حكم من يصلي أحياناً ويترك الصلاة أحياناً","answer":"الجواب: مثل مَن تركها كلها، مَن تركها بعض الأوقات مثل مَن ترك الجميع، بعض الناس يُصلي إذا حضر عنده ضيفٌ، أو صار عند الناس صلَّى، وإذا كان في بيته أو في مكانٍ آخر ما صلَّى، هذا كذلك كافرٌ؛ لأنه لا يُبالي بالصلاة، ولا يهتم بها، أو يُصلي المغرب والعشاء ولا يُصلي الظهر والعصر، أو ما يُصلي الفجر، أو يُصلي الجمعة فقط، كل هؤلاء من أنواع الكفرة -نعوذ بالله- صدق عليهم الحديثُ والآيات الكريمات.","link":"https://binbaz.org.sa/fatwas/20588/حكم-من-يصلي-احيانا-ويترك-الصلاة-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0541فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":767,"question":"فضيلة الشيخ، إني أحبُّك حبًّا شديدًا، وأكاد أبكي إذا سمعتُ كلامك، فضيلة الشيخ، إنَّ لي أولادًا قد آذوني بصلاة الفجر وغيرها، فهم لا يُصلون، فما أفعل معهم؟ وقد جاهدتُهم كثيرًا، ما الحكم الشَّرعي في ذلك؟ أفيدونا أثابكم الله.","title":"ما حكم الشرع في الأولاد الذين لا يصلون؟","answer":"الجواب: أحبَّك الله الذي أحببتنا له، وأسأل الله أن يجعلنا وإيَّاكم مُتحابين بجلاله، يقول عليه الصلاة والسلام: يقول الله يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلُّهم في ظلِّي يوم لا ظلَّ إلا ظلِّي، ويقول عليه الصلاة والسلام: يقول الله : وجبت محبَّتي للمُتحابين فيَّ، والمتباذلين فيَّ، والمتجالسين فيَّ، والمتزاورين فيَّ، هذا كله مما يُحبُّه الله ، ومن أسباب محبَّة الله للعبد.\nفينبغي للمؤمن أن يكون يُحبّ في الله، ويبغض في الله، ويُوالي في الله، ويُعادي في الله، هكذا المؤمن.\nويقول ﷺ: سبعةٌ يُظلّهم الله في ظلِّه يوم لا ظلَّ إلا ظلّه: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجلٌ قلبه مُعلَّقٌ بالمساجد يعني: كلما خرج من المسجد قلبه مُعلَّقٌ به حتى يُؤدي الصلاة الأخرى، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، والخامس: رجل دعته امرأةٌ ذات منصبٍ وجمالٍ أي: دعته إلى الزنا فقال: إني أخاف الله، وفي معنى ذلك: امرأة دعاها رجلٌ للزنا فقالت: إني أخاف الله، فهي من السبعة الذين يُظلّهم الله في ظلِّه يوم لا ظلَّ إلا ظله، والسادس: رجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شمالُه ما تُنفق يمينُه من حرصه على الإخلاص، والسابع: رجل ذكر الله خاليًا ما عنده أحدٌ، خاليًا في غرفته، أو في منزله، أو في أي مكانٍ، ففاضت عيناه خوفًا من الله، وتعظيمًا له، هؤلاء السبعة الذين يُظلّهم الله في ظلِّه.\nأما أولادك يا أخي الذين يعصونك ولا يُصلون فعليك بالعصا، اضربهم، يقول النبيُّ ﷺ: مروا أولادكم بالصلاة لسبعٍ، واضربوهم عليها لعشرٍ، كيف إذا بلغوا؟ إذا بلغ ولم يُصلِّ يُقتل، يُرفع أمره إلى ولي الأمر ويُقتل، الذي يبلغ الحلم ولا يُصلي يُرفع إلى ولاة الأمور -إلى المحكمة والإمارة- حتى يُقتل إن لم يستجب ولم يستقم، وإذا كان دون البلوغ وقد بلغ العشر يُضْرَب، فإذا كنتَ ما تستطيع ضربه ارفع أمره إلى الهيئة، إلى المحكمة، إلى أمير بلدك، حتى يقوموا عليه، وإذا كنتَ تستطيع إبعاده أبعده، قل له: لا تأتِ إلى بيتي مرة واحدة، لا تقربني، ولا أعرفك. إذا صدقتَ في هذا نجوتَ من شرِّهم، أما التَّساهل معهم فما ينفع، إن كنت تستطيع الضرب اضربهم حتى يستقيموا، ارفع أمرهم إلى ولاة الأمور: إلى الحسبة، إلى المحكمة، إلى الإمارة، إن كانت تنفع، فإن لم تستطع فأبعدهم عن بيتك، لا يجلسون في بيتك بالكلية، يروحون حتى يهديهم الله، أو النار أمامهم.\nس: ادعوا لهم بالهداية.\nالشيخ: نسأل الله لهم الهداية، نسأل الله لنا ولهم الهداية، ولكل مسلم، وهذا ما هو بخاصٍّ بك، هذا الكلام أقوله للحاضرين جميعًا، ولكل مَن بلغه هذا الكلام، نصيحتي للجميع ولكل مَن بلغه هذا الكلام من رجلٍ أو امرأةٍ: الجد في الأولاد، والصدق في الأولاد، إما أن يستقيموا، أو يبعدوا، وإلا يرفع أمرهم إلى ولاة الأمور، أما أن يُتركوا لا يُصلون فهذا منكرٌ عظيمٌ، وكفرٌ ظاهرٌ -نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/20702/ما-حكم-الشرع-في-الاولاد-الذين-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0598ما حكم الشرع في الأولاد الذين لا يصلون؟ ابن باز فتاوى المحاضرات.mp3","categories":["حكم الصلاة وأهميتها","تربية الأولاد"]},{"id":781,"question":"هل يجوز أن نقول لتارك الصلاة: أنت كافر؟","title":"ما حكم قول \"كافر\" لتارك الصلاة؟","answer":"الجواب: لا بأس، هو كافرٌ، سواء قلته أو ما قلته، مَن ترك الصلاة فهو كافرٌ، لكن إذا تركتها عند النَّصيحة تقول له: اتَّقِ الله، الصلاة عمود الإسلام، مَن تركها كفر، ولا تقل: \"أنت كافرٌ\" حتى تنصحه؛ لعلَّ هذا يكون أقبلَ وأقربَ إلى قبول النَّصيحة. لا تبدأ بالتَّكفير، تقول له: يا فلان، اتَّقِ الله، الصلاة عمود الإسلام، ركن الإسلام، مَن تركها كفر، اتَّقِ الله، حافظ عليها، بادر إليها، وما أشبه ذلك يكون أوْلى من البداءة بقوله: \"أنت كافر\"، يعني: يبدأه بهذا، ويجبهه بهذا، قد يكون سببًا للنُّفرة وعدم قبول النَّصيحة، ولكن يبدأه بالنَّصيحة.","link":"https://binbaz.org.sa/fatwas/20723/ما-حكم-قول-كافر-لتارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0607هل يجوز أن نقول لتارك الصلاة أنت كافر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":928,"question":"يقول: خادمة من الفلبين أسلمتْ، ولها أولاد، ولكن زوجها ما زال نصرانيًّا، فقيل لها: أنه لا بد ألا ترجع إلى زوجها، فقالت: لا أستطيع، فما الحكم في هذا؟","title":"ما حكم مَن أسلمت وزوجها ما زال نصرانيَّا؟","answer":"الجواب: إذا أسلمت وزوجها باقٍ على النصرانية ليس لها الرجوعُ إليه، بل تمتنع منه حتى يُسلم، فإن أسلم وهي في العدَّة فهي زوجته، وإن خرجت من العدَّة فهي بانت منه حينئذٍ.\nوقال بعضُ أهل العلم: إنها لا تبين منه إذا أسلم بعد ذلك وهي لم تتزوج، ولم تفسخ منه، ولم يُطلِّق. فعلى كل حال بخروجها من العدة انتهت، لها أن تتزوج، وللحاكم الشرعي أن يُزوّجها؛ لأنَّ نكاحها انتهى بخروجها من العدَّة، لكن لو انتظرت لعله يُسلم هذا الصواب، أنه يرجع إليها ولو بعد العدَّة؛ لأن الرسول ﷺ أعاد ابنته زينب على أبي العاص ابن الربيع لما أسلم عام الفتح، وقد مضى عليها سنوات؛ لأنها تنتظره، فهذا هو الصواب. وإن تزوجت بعد العدَّة ولم تنتظره فلا بأس عليها، وعليها أن تتَّقي الله جلَّ وعلا، وأن تعلم أنَّ هذا هو الحكم الشرعي، وعلى إخوانها المسلمين أن يُعلِّموها ويُوجِّهوها، حتى لا ترجع إليه، وحتى لا ترتدَّ عن دينها، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/20956/ما-حكم-من-اسلمت-وزوجها-ما-زال-نصرانيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0752أمرأة من النصارى أسلمت ولها أولاد لكن زوجها مازال نصرانياً فما الحكم؟ ابن باز فتاوى المحاضرات.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":1004,"question":"ما حكم مَن تهاون بالصلاة وأخَّرها عن أوقاتها؟","title":"ما حكم التهاون بالصلاة وتأخيرها عن وقتها؟","answer":"الجواب: التَّهاون بالصلاة من أكبر الكبائر، ومن أعظم الجرائم، فيجب عليه التوبة. أما إن تركها بالكلية فهذا كفرٌ أكبر، ولو لم يجحد وجوبها. لكن إذا تهاون بها: تارةً يُصليها مع الجماعة، وتارةً في البيت، وربما أخَّرها عن وقتها؛ هذه جريمة عظيمة، فيجب الحذر.","link":"https://binbaz.org.sa/fatwas/21049/ما-حكم-التهاون-بالصلاة-وتاخيرها-عن-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0845ما حكم من تهاون في الصلاة وأخرها عن وقتها؟ ابن باز فتاوى المحاضرات.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":1006,"question":"رجلٌ كان مسيحيًّا فأسلم والحمد لله، وزوجته لا تزال باقيةً على دينها السابق، فما حكم بقائها على ذمَّته وهي لم تُسلم؟ جزاكم الله خيرًا.","title":"ما حكم بقاء زوجة النصراني معه بعد إسلامه؟","answer":"الجواب: ما دامت مسيحية لا بأس؛ لأن المسلم لا بأس أن يبقى مع الكتابية، وينكحها أيضًا من جديدٍ، يتزوجها إذا كانت محصنةً، فإذا كانت زوجته محصنةً وأحبَّ أن يبقى معها فلا بأس، لعلَّ الله يهديها للإسلام بأسبابه، وإن أحبَّ أن يُطلقها فلا بأس. أما إن كانت غير نصرانية بل وثنية؛ فإنه ينفسخ النكاحُ، إذا انتهت العدَّةُ ينفسخ النكاح بإسلامه، فإن أسلمت فهي زوجته، وإلا انفسخ النكاحُ، فلها أن تنكح بعد ذلك بعد خروجها بعد العدَّة. أما إذا كانت كتابيةً -يهودية أو نصرانية- تبقى معه؛ لأن المسلم يجوز له نكاح الكتابية المحصنة. وعدم نكاحه لها أسلم له وأبعد عن الشرِّ، فإذا فارقها احتياطًا خوفًا أن تجرَّه إلى دينها فهذا طيبٌ. وإن كان يطمع في إسلامها ويرجو إسلامها لا يعجل، لعلَّ الله يهديها بأسبابه، فإذا انتهت العدَّةُ -حاضت ثلاث حيضٍ- ولم تُسلم؛ انتهت من النكاح، وصار لها أن تنكح مَن شاءت.","link":"https://binbaz.org.sa/fatwas/21047/ما-حكم-بقاء-زوجة-النصراني-معه-بعد-اسلامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0843رجل كان نصرانياً فاسلم وزجته ما زالت باقيةعلى دينها فما حكم بقاؤها على ذمته وهي لم تسلم؟ ابن باز.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":1163,"question":"ما حكم مَن يُصلي الفروض كلها، ولكنه يترك صلاةَ الفجر مع الجماعة؛ لأنه نائمٌ، أقصد أنه لا يتركها كل الأيام، ولكنه بعض الأيام، فما حكمه؟ هل له عذرٌ ما دام ينام مُتأخِّرًا؟","title":"حكم من يصلي الفروض إلا الفجر لسهره","answer":"الجواب:\nليس له عذرٌ، وليس بالنوم عذرٌ مع العناية، إذا كان يشقّ عليه النومُ يعتني: يُبَكِّر ويجعل ساعةً عند رأسه، حتى يستعين بذلك، أما أن يدَّعي النوم ويتساهل فليس بعذرٍ، النوم مع التساهل من دون عنايةٍ ليس بعذرٍ.\nالنبي ﷺ يقول: ليس في النوم تفريطٌ يعني: مع العناية، النبي لما أراد النومَ في بعض أسفاره مُتأخِّرًا أمر بلالًا أن يكلأ الصبحَ، فلا يجوز للإنسان أن يتساهل ويقول: النوم عذرٌ، يجب أن يترك السَّهر والأسباب التي تجعله ينام الفجر، ويجعل الساعة قُرب الأذان تُعينه على ذلك، أو يُوصي أهله الجيدين الذين يقومون ويُوقظونه، وليس له عذرٌ في التَّساهل بهذا الأمر، بل هذا من مُشابهة أعداء الله المنافقين، فيجب الحذر، يقول النبيُّ ﷺ: أثقل الصلاة على المنافقين: صلاة العشاء، وصلاة الفجر، ولو يعلمون ما فيهما لأتوهما ولو حَبْوًا، ويقول ابنُ مسعودٍ : \"لقد رأيتُنا وما يتخلَّف عنها –يعني: الجماعة- إلا منافقٌ معلوم النِّفاق، ولقد كان الرجلُ يُؤتى به يُهادى بين الرجلين حتى يقف بين الصفِّ\" يعني: يعضده حتى يقف في الصف. رواه مسلم في \"الصحيح\".\nفالواجب على المسلم تقوى الله، وأن يحذر التساهل بالجماعة، لا بالصبح ولا بغيرها، وعلى النساء كذلك أن يتَّقين الله في الصَّلوات كلها، وألا تؤخّر الصبح إلى بعد طلوع الشمس، بل يجب أن تُؤدَّى في الوقت على الرجال والنساء، ولكن يزداد على الرجال وجوب أدائها في الجماعة، والمرأة يجب أن تُؤديها في وقتها قبل الشمس، بعض الناس -والعياذ بالله- يُؤخِّر غسل الجنابة، حتى لا يغتسل إلا الضُّحى، يُؤخر الفجر، هذا بلاءٌ عظيمٌ، ومُشابهةٌ لأعداء الله المنافقين، فيجب الحذر.","link":"https://binbaz.org.sa/fatwas/21220/حكم-من-يصلي-الفروض-الا-الفجر-لسهره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1016من حكم من يصلي الفروض كلها إلاَّ صلاة الفجر يتركها احياناً بسبب السهر؟.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":1164,"question":"إنَّ أبي وبعض جماعتنا يمنعونني من الذهاب مع الشباب، مع أنهم شباب طيبون، فهل أُطيعه أم أعصيه، مع أنني إذا منعني من الذهاب معهم تتغير حالي، ونرجع إلى الفساد والمعصية؟ أفيدونا جزاكم الله خيرًا.","title":"ما حكم من أمره والداه بترك صحبة الأخيار؟","answer":"الجواب:\nأما مَن أمرك بأن تترك صحبة الأخيار فليس عليك طاعته، يقول النبيُّ ﷺ: إنما الطاعة في المعروف، لكن إذا كان الآمرُ الوالد أو الوالدة فعليك بالحكمة والكلام الطيب، ولا تُظهر المعصية، ولكن تصحب الأخيار من غير علمهما، وتجتهد في صحبة الأخيار من غير علمهما، إذا كان علمُهما يضرّك أو يُسبب ضربهم لك أو نحو ذلك لا تُعلمهما، ولكن لا تترك صحبة الأخيار، والتمس الأخيار في كل وقتٍ أمكنك، واحذر صحبة الأشرار أبدًا، ولا تُطع أحدًا في ذلك أبدًا، لا أبًا، ولا أمًّا، ولا غير ذلك، لكن مع الوالدين تأدَّب بكل طريقةٍ تمكنك، ولو بإخفاء ذلك عليهما في الأوقات المناسبة، حتى لا يكون بينك وبينهما سوءُ تفاهمٍ، وحتى لا تترك صحبة الأخيار، فاتَّقِ الله: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].","link":"https://binbaz.org.sa/fatwas/21219/ما-حكم-من-امره-والداه-بترك-صحبة-الاخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1015ما حكم من أمرهُ والديه بترك الصالحين والأخيار؟ابن باز.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":1533,"question":"قول النبي ﷺ: مَن ترك صلاة العصر فقد حبط عمله على ماذا يدل؟","title":"معنى حبوط العمل لمن ترك صلاة العصر","answer":"الجواب:\nعلى كفر صاحبه، مثلما جاء في الحديث الآخر: بين الرجل وبين الكفر والشرك ترك الصلاة، العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر، والكفر يُحبط الأعمال، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21633/معنى-حبوط-العمل-لمن-ترك-صلاة-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دلالة حديث من ترك صلاة العصر فقد حبط عمله.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":1582,"question":"هذا رجل ابتُلِيَ بأن أبناءه لا يخرجون إلى بيت الله ، يصلون في بيوتهم، وتعب معهم في توجيههم ونصحهم حتى وصل إلى ضربهم، فما الواجب في حقِّه؟","title":"حكم تأديب الأبناء لتقصيرهم في الصلاة","answer":"الجواب:\nهذا هو الواجب: التأديب، وإذا عجز يرفعهم إلى الهيئة، أو الإمارة إذا كان في بلده إمارة، أو الهيئة أقوى منها.\nس: وابتُلِيَ أحدُهم بأن ابنته لا تُصلي البتة؟\nج: كذلك يُؤدِّبها حتى تستقيم، ومع الأدب تستقيم إن شاء الله.","link":"https://binbaz.org.sa/fatwas/21685/حكم-تاديب-الابناء-لتقصيرهم-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب تأديب الأبناء عند تقصيرهم في الصلاة.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":1587,"question":"رجلٌ يذهب مع جماعة التبليغ، وأولاده لا يُصلُّون، فيقول: ماذا أعمل فيهم قد نصحتهم مرةً ومرتين؟","title":"حكم مَنْ يدعو الناس وأولاده لا يُصلُّون","answer":"الجواب:\nيجلس مع أولاده يُجاهدهم، ولا يذهب يُعلِّم الناسَ ويترك مَن كان تحت يده، مَن كان تحت يده أبْدَى، فيقوم عليهم ويستعين بالله ثم بالهيئة عليهم، فالهيئة ما جُعِلَتْ إلا لهذا.\nس: خروجه أحسن الله إليك؟\nج: إذا كانت الجماعة التي معه أهل سنة ما في بأس إذا كان خروجه لا يترتب عليه شرٌّ، إذا كان ما يُضَيِّع ما يجب عليه، أما هذا فلا يخرج، يجاهد الذين عنده.\nس: بعضهم يقول: أنا مجنون؟! أُعْلِم الهيئة على عيالي أو الإمارة؟!\nج: إذا ما أطاق يُعلِّمهم، هذا من التعاون على البر والتقوى.\nس: قال أخاف؟\nج: لا، ما في جنون، يقول: إني عجزتُ عنهم، عجزتُ عن أولادي، فعاونوني عليهم. يقول لرئيس الهيئة، أو لبعض أعضاء الهيئة، فلعلهم إن شاء الله إذا جاءوا معه يتأدَّبون.\nس: سكوته عن ذلك يأثم به؟\nج: هو الظاهر.","link":"https://binbaz.org.sa/fatwas/21690/حكم-من-يدعو-الناس-واولاده-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تربية الأبناء ومجاهدتهم للصلاة وحكم سكوته عنهم.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":1659,"question":"حكم الأكل مع تارك الصلاة؟","title":"هل يجوز الأكل مع تارك الصلاة؟","answer":"الجواب:\nإذا كان ضيفًا فلا بأس، وتنصحه، أما إذا كان من جيرانك وغيرهم فلا، وعليك أن تنصحه، ويستحق الهجر إن لم يقبل النَّصيحة، وإلا فاستمر على النصيحة والتَّذكير والترغيب في الخير لعلهم يهتدون.","link":"https://binbaz.org.sa/fatwas/21764/هل-يجوز-الاكل-مع-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأكل مع تارك الصلاة.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":1698,"question":"ما الحكمة من أنَّ عتبان طلب من رسول الله ﷺ أن يُصلي في بيته؟","title":"لماذا طلب عتبانْ من النبيﷺالصلاة ببيته؟","answer":"الجواب:\nلأجل أن يتَّخذ مُصلًّى؛ لأنه إذا قصد محلًّا وصلَّى فيه صار محلًّا مناسبًا وشريفًا، مثل: لما صلَّى عند مقام إبراهيم صار سنةً، فالمحل الذي يقصد الصلاةَ فيه حتى يتّخذ مُصلًّى يكون محلَّ عبادةٍ، ويكون محلًّا مباركًا وطيبًا، أما الصلاة العابرة في الطُّرقات فلا.","link":"https://binbaz.org.sa/fatwas/21804/لماذا-طلب-عتبان-من-النبيﷺالصلاة-ببيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا طلب عتبانْ من رسول الله ﷺ أن يُصلي في بيته.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":1770,"question":"هجر الذي يُصلي صلاةً ويتركها في أوقاتٍ؟","title":"حكم هجر من يصلي أحيانًا ويترك أحيانًا","answer":"الجواب:\nيستحق الهجر؛ لأنه كافرٌ، ترك الصلاة كفر -نعوذ بالله- يُستتاب، فإن تاب وإلا قُتِلَ من جهة ولاة الأمور.","link":"https://binbaz.org.sa/fatwas/21877/حكم-هجر-من-يصلي-احيانا-ويترك-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم هجر من يصلي أحيانا ويترك أحيانا.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":1989,"question":"يقول السائل: هل يجوز الحكم على الشخص بدخول النار إذا علم منه أنه لا يصلي ويعمل عمل الكفار؟","title":"هل يُحكم بالنار لمن لا يصلي؟","answer":"الجواب:\nالنبي ﷺ حكم عليه، وقال ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر والكفار مقطوع لهم بالنار، نسأل الله العافية، من مات على الكفر فهو من أهل النار، نسأل الله العافية.\nس: التعيين؟\nالشيخ: عام، التعيين وغير التعيين، من عُلِم بالكفر يقال كافر، أبو جهل كافر ومن أهل النار، وعتبة بن ربيعة وأبو طالب كلهم من أهل النار؛ لأنه ثبت كفرهم، ماتوا على الكفر، نسأل الله العافية.\nس: لكن ما اشتهر في كتب العقيدة أنه لا يُشهد لمعين بجنة ولا نار ولكن نرجو للمحسن ونخاف على المسيء؟\nالشيخ: يعني في حياته، فإذا مات على الكفر نشهد له بالكفر والنار، والمؤمنون على العموم مشهود لهم بالجنة، والكفار على العموم مشهود لهم بالنار، ومن عُلِم أنه مات على الكفر فهو من أهل النار، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22105/هل-يحكم-بالنار-لمن-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من لا يصلي ويعمل عمل الكفار هل يحكم عليه بدخول النار.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2307,"question":"مَن عدَّ ترك الصلاة كُفرًا عمليًّا؟","title":"هل تَرْكُ الصلاة كُفْر عمليٌّ؟","answer":"الجواب:\nهو كفرٌ عمليٌّ.\nس: مُخْرِجٌ من المِلَّة؟\nج: نعم.\nس: مَن قال أنه لا يُخرج من الملَّة؟\nج: الجمهور يرون أنَّه لا يُخرج من الملَّة؛ لأنَّ في بعض روايات عُبادة ما يدل على ذلك، وحديث عُبادة في سنده مقال.","link":"https://binbaz.org.sa/fatwas/22431/هل-ترك-الصلاة-كفر-عملي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ترك الصلاة هل هو كُفر عملي.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2380,"question":"من لم يحافظ على صلاة الفجر يُطلق عليه النفاق؟","title":"هل يُعدّ منافقًا مَن لا يحافظ على الفجر؟","answer":"الجواب:\nشابه المنافقين، نعم، أثقل الصلاة على المنافقين صلاة العشاء وصلاة الفجر ولو يعلمون ما فيهما لأتوهما ولو حبوًا، نسأل الله العافية، هذا من النفاق العملي، يُقال له: احذر صفات المنافقين، هذه صفات المنافقين، نسأل الله العافية.\nس: يُقاس على المرأة أنها تكون في ذمة الله؟\nالشيخ: مثله، الرجل والمرأة جميعًا.","link":"https://binbaz.org.sa/fatwas/22505/هل-يعد-منافقا-من-لا-يحافظ-على-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من لم يحافظ على صلاة الفجر يعد منافقا.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2381,"question":"لو ترك تهاونًا وكسلًا صلاة واحدة؟","title":"حكم مَن ترك صلاة واحدة تهاونًا وكسلًا","answer":"الجواب:\nيكفر على الصحيح، الصحيح من أقوال العلماء يكفر ولو بواحدة إذا تركها عمدًا حتى خرج وقتها، عليه التوبة والإنابة إلى الله فإذا تاب تاب الله عليه.\nس: ترك صلاة العصر؟\nالشيخ: أو الفجر أو الظهر أو غيرها.","link":"https://binbaz.org.sa/fatwas/22506/حكم-من-ترك-صلاة-واحدة-تهاونا-وكسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من ترك تهاونًا وكسلا صلاة واحدة.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2383,"question":"بعض الناس لا يصلي إلا في رمضان فإذا انتهى رمضان ترك الصلاة؟","title":"حكم مَن لا يصلي إلا في رمضان","answer":"الجواب:\nوبعض الناس من الجمعة إلى الجمعة، نسأل الله العافية، حكمهم الكفر، حكمهم أنهم كفار على الصحيح من أقوال العلماء، من تركها ولو ما جحدها كَفَر؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، من ترك صلاة العصر فقد حبط عمله، حبوط العمل يكون بالكفر وَمَنْ يَكْفُرْ بِالْإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ [المائدة:5]، وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22508/حكم-من-لا-يصلي-الا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لا يصلي إلا في رمضان فإذا انتهى رمضان ترك الصلاة.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2384,"question":"الذين يتهاونون، يعني ينامون عن صلاة الفجر وصلاة العصر، ما جحدوها، بس إذا قاموا صلوها؟","title":"ما حكم التهاون بصلاتي الفجر والعصر؟","answer":"الجواب:\nإذا تعمد يكفر بذلك، أما إذا غلبه النوم عليه أن يبادر بالصلاة إذا استيقظ، أما إذا تعمد يوقت الساعة لوقت ذهابه إلى عمله جازمًا ما هو مصلٍّ إلا بعد الوقت، أو العصر يجزم كذلك يتركها عمدًا، هذا يكفر بذلك.\nس: ولو كان شبه يومي؟\nالشيخ: ولَوْ، يَكْفُر بأول مرة، وكل ما زاد تركه زاد كفره.","link":"https://binbaz.org.sa/fatwas/22509/ما-حكم-التهاون-بصلاتي-الفجر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التهاون عن صلاة الفجر وصلاة العصر وعدم جحدها.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2385,"question":"بعضهم يقول أن من لا يصلي أو يصلي تارة ويترك تارة أنه لا يكفر ولكنه عاصٍ؟","title":"حكم مَن لا يصلي ومن يتركها أحيانًا","answer":"الجواب:\nهذا قول بعض العلماء، لكن الصواب أنه يكفر بذلك؛ للأحاديث المذكورة، نسأل الله السلامة.\nس: من يقول أنهم لا يكفرون لأنهم يقولون لا إله إلا الله؟\nالشيخ: يرد عليهم بأن من قال لا إله إلا الله لا بدّ أن يؤدي حقها، فمن حقها المحافظة على الصلوات الخمس.","link":"https://binbaz.org.sa/fatwas/22510/حكم-من-لا-يصلي-ومن-يتركها-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من لا يصلي أو يصلي تارة ويترك تارة كافر.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2394,"question":"أحيانًا العوام يرون واحدًا يسمع أغاني ويصلي يقولون: لا تصلي ما دام أنت تسمع أغاني فأنت تصير من المنافقين؟","title":"حكم مَن يقول لمَن يسمع الأغاني: لا تصلي؟","answer":"الجواب:\nالشيخ: لا، هذا غلط، أعوذ بالله، يصلي ويحافظ على الصلاة ويهديه الله، يبتعد عمّا حرم الله، والصلاة تنهاه عن هذا إذا حافظ عليها، منتهاه يترك هذه الأشياء إِنَّ الصَّلَاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45] فمن حافظ عليها صادقًا؛ نهته عن الشر.","link":"https://binbaz.org.sa/fatwas/22519/حكم-من-يقول-لمن-يسمع-الاغاني-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يقال لمن يسمع الأغاني لا تصلي.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2417,"question":"سمعتك تقول غير مرة أن الذي يتعمد تأخير صلاة الفجر يكون كافرًا، فهل بناء على هذا إذا عقد عقد زواج وهو ما يصلي الفجر صحيح؟","title":"هل يصح زواج وعَقْدُ مَن لا يصلي الفجر؟","answer":"الجواب:\nهذا على خلاف، الجمهور على أنه إذا كان ما جحد وجوبها لا يكفر وإنما يكفر كفرًا أصغر، والصحيح أنه كفر أكبر إذا تعمد ترك الصلاة حتى خرج وقتها عمدًا بغير شُبهة، والكافر لا يعقد للمسلمة، إذا كان وليها لا يصلي فيلتمس وليًّا آخر، الذي لا يصلي لا يتولى عقدها، الذي ما يصلي أبوها ما يصلي يعقد لها أخوها أو ابن أو عم؛ الأقرب فالأقرب.\nس: هو سوف يتزوج الآن؟\nالشيخ: وهي ما تصلي وهو يصلي؟\nس: هو الذي ما يصلي، يترك صلاة الفجر عمدا.\nالشيخ: لا، لا يُزَوَّج ينبغي لهم ألا يزوجوه، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22545/هل-يصح-زواج-وعقد-من-لا-يصلي-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة عقد من لا يصلي الفجر.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":2478,"question":"تحديد السبع لتعليم الصبيان الصلاة؟","title":"ما حكم تعليم الصغار الصلاة قبل سبع سنين؟","answer":"الجواب:\nنعم قبله ما يصلح، عَلِّموهم الصلاة لسبع واضربوهم عليها لعشر، قبلها يُعَدُّ من غير  العقلاء.\nس: طيب لو وجدهم في الصف يؤخِّرهم؟\nالشيخ: إن تيسَّر وإلا يخلِّيهم مِثْل الحَجَر.\nس: ولو مَيَّز قبل السبع؟\nالشيخ: ولو، جاء الحديث، جاء بالسبع حَدّ.","link":"https://binbaz.org.sa/fatwas/22607/ما-حكم-تعليم-الصغار-الصلاة-قبل-سبع-سنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليم الصبيان للصلاة.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2480,"question":"بعض الناس ما يصلي إلا مِن الجمعة إلى الجمعة؟","title":"ما حكم مَنْ لا يصلي إلا الجمعة؟","answer":"الجواب:\nهذا يكون كافرًا؛ لأنه ترك الصلاة، ترك ستة أيام وزيادة.\nس: ولو صلى الجمعة؟\nالشيخ: ولو صلى الجمعة، إذا ترك الصلاة الأخرى؛ كَفَر.","link":"https://binbaz.org.sa/fatwas/22609/ما-حكم-من-لا-يصلي-الا-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكفر من لا يصلي إلا من الجمعة إلى الجمعة.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2618,"question":"ما حكم التهاون بالصلاة؟","title":"ما حكم التهاون بالصلاة؟","answer":"الجواب: من خصال المنافقين، حكمه التحريم، من خصال أهل النفاق: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَى [النساء:142]، هذه من صفاتهم الخبيثة، فالواجب على المؤمن أن يكون نشيطًا في الصلاة، حريصًا عليها، مسارعًا إليها، حتى لا يتشبَّه بأعداء الله.","link":"https://binbaz.org.sa/fatwas/22753/ما-حكم-التهاون-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التهاون بالصلاة.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":2722,"question":"يحصل له هذا الأجر العظيم (الرباط) الذي حافظ على الصلاة؟","title":"هل يرجى أجر الرباط للمحافظ على الصلاة؟","answer":"الجواب: يرجى له؛ لأن النبي ﷺ سماه رِباطا فذلكم الرباط، فذلكم الرباط يرجى له فضل المرابطة.","link":"https://binbaz.org.sa/fatwas/22868/هل-يرجى-اجر-الرباط-للمحافظ-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فذلكم الرباط هل يحصل الأجر لمن حافظ على الصلاة ومن كان في الثغور.mp3","categories":["شروح الحديث","حكم الصلاة وأهميتها"]},{"id":3038,"question":"بالنسبة للمعلمات اللائي يعملن خارج مدينة الرياض، يخرجون من قبل صلاة الفجر ولا يصلون إلى مدارسهم إلا بعد طلوع الشمس، متى يُصَلُّون، يُصَلُّون في السيارة أم كيف الصلاة؟","title":"حكم صلاة الفجر لمعلماتٍ يخرجن مبكرًا","answer":"الجواب: هذا سُئل عنه وأجبناهم، الواجب عليهم أن يصلوا في السيارة وإلا تُوقَف، إذا أمكن تُوقَف وينزلون إذا أمكن توقيفها، ينزلون حتى يصلون ثم يركبون، وقد كتبنا للمسؤولين تغيير النظام هذا، يُغيّر النظام بأن يكون سفرهم بعد الصلاة، كتبنا للمسؤولين في هذا لعلهم يستجيبون إن شاء الله.","link":"https://binbaz.org.sa/fatwas/23198/حكم-صلاة-الفجر-لمعلمات-يخرجن-مبكرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المعلمات اللاتي يخرجن من قبل صلاة الفجر ولا يصلن إلى مدارسهم إلا بعد طلوع.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":3151,"question":"تسأل من فرنسا تقول: تخشى على ابنها أن يكون في الشارع فهل لا بأس أن تأخذه إلى المدرسة الفرنسية؟ يعني تخشى عليه أن يتعلم بعض الكلام في الشارع فتقول: الآن هل يُسمح لي أن يدخل في المدرسة لكي يتعلم؟ علمًا بأن في هذه المدرسة يعلمون من الأساس توحيدهم يعني؟","title":"كيف تكون تربية أبناء المسلمين في الغرب؟","answer":"الجواب: ما يجوز، تحفظه في بيتها، تصونه في بيتها، أو تدوّر \"مركز إسلامي\"، تلتمس المراكز الإسلامية، فرنسا فيها مراكز إسلامية كثيرة، وإنجلترا كذلك.\nس: أكثرهم يطلبون مالًا لدخول الأبناء؟\nالشيخ إذا اجتهدت يسّر الله أمرها وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] يُيَسِر الله له مَنْ يرحمه ويقبله.","link":"https://binbaz.org.sa/fatwas/23313/كيف-تكون-تربية-ابناء-المسلمين-في-الغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تربية الأبناء في بلاد الغرب.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":3588,"question":"غير المصلين لا يخرجون من النار حتى وإن كانوا موحدين؟تارك الصلاة؟","title":"هل يُخلّد تارك الصلاة في النار؟","answer":"الجواب: إذا ترك الصلاة عمدًا هذا الصحيح أن كفره أكبر، نسأل الله العافية.\nس: يخلد في النار؟\nالشيخ: على القول بأنه كفر أكبر كما هو ظاهر الحديث: بين الرجل وبين الكفر والشرك ترك الصلاة نسأل الله العافية.\nس: من تركها تكاسلا؟\nالشيخ: هذا هو محل الخلاف، لكن الصواب أنه يكفر، أما إذا جحد وجوبها إجماع، إذا جحد وجوبها قد أجمع العلماء على كفره.\nس: هل يفهم من الحديث أن تاركها تكاسلاً ليس له أثر سجود فلا يخرج من النار؟\nالشيخ: هذا من حجة تكفير تارك الصلاة.\nس: لو تركها بعض الأوقات؟\nالشيخ: ظاهر السنة أنه يكفر.","link":"https://binbaz.org.sa/fatwas/23770/هل-يخلد-تارك-الصلاة-في-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يخلد تارك الصلاة في النار.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":3776,"question":"الطفل الذي عمره سبع سنوات، ذَكَر، يُبعد عن قضية الإسبال في الثياب ويُربَّى عليه؟","title":"متى يُؤمر الطفل بتجنب الإسبال في الثياب؟","answer":"الجواب: نعم، يمنع من الإسبال وإن كان صغيرًا.","link":"https://binbaz.org.sa/fatwas/23972/متى-يومر-الطفل-بتجنب-الاسبال-في-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يمنع الطفل الذي عمره سبع سنوات من الإسبال.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":3777,"question":"تأمره بالصلاة لسبع: هل مع التشديد عند بالصلاة، أم أمر فقط؟","title":"هل أمر الأبناء بالصلاة لسبع على الوجوب؟","answer":"الجواب: على وليه أن يأمره بالصلاة لسبعٍ، يجب على وليه وجوبًا، الرسول قال: مُرُوا، والأصل في الأوامر الوجوب، واضربوهم عليها لعشرٍ حتى يتمرَّنوا على الخير، وبعض الصبيان قد يبلغ بعد العشر، قد يبلغ في الحادي عشر والثاني عشر.","link":"https://binbaz.org.sa/fatwas/23973/هل-امر-الابناء-بالصلاة-لسبع-على-الوجوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مروا أبنائكم بالصلاة لسبع.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":3806,"question":"هجر تارك الصلاة بعد النَّصيحة؟","title":"هل يُهجر تارك الصلاة بعد النَّصيحة؟","answer":"الجواب: يُشرع لك أن تهجره، يُشرع، بل يجب عند قومٍ، أقل الأحوال أنه يُشرع. اللهم إلا أن يكون الهجرُ يُسبب شرًّا أكثر؛ فهذا محل نظرٍ، فالهجر دواء وعلاج، فإذا كان يترتب عليه خيرٌ فُعل، أو لا يترتب عليه شرٌّ فُعل، فإن كان يترتب عليه ما هو أنكر؛ تُرك إلى وقتٍ آخر.","link":"https://binbaz.org.sa/fatwas/24007/هل-يهجر-تارك-الصلاة-بعد-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هجر تارك الصلاة بعد النَّصيحة.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":3878,"question":"نجد كثيرًا من الناس يتركون الصلاة، ومع ذلك يقولون: لا إله إلا الله، ورجّح جماعة من العلماء بأن من ترك الصلاة تهاونًا وكسلًا؟","title":"هل يخرجُ الموحّدُ تاركُ الصلاة من النار؟","answer":"الجواب: يعني يقولون: \"لا إله إلا الله\" وليس عندهم ما يكفّر فلا مانع، يقولون: \"لا إله إلا الله\" وليس معهم ما يكفّرهم، هذا المعنى يعني معهم معاصٍ، لكن ما معهم ما يكفّرهم، أما من قال: \"لا إله إلا الله\" وهو يسبُّ محمدًا، ينفعه؟ لو قال: \"لا إله إلا الله\" كل يوم مائة مرة لكن يقول: محمد كذاب، وأيش يصير؟ مخلد في النار وإلا ما هو مخلد؟ مخلد. هذا المعنى. أو يقول إن الصلاة ما هي بواجبة على الناس، يُبيَّن له الأدلة ويقول: لا ما هي واجبة، والصيام ما هو واجب، والحج ما هو واجب، والزكاة ما هي واجبة، يُخلّد وإلا ما يخلد؟ ولو قال: \"لا إله إلا الله\"، أو يسب الدين أو يستهزئ بالإسلام.  فالحاصل: أن من يقول: \"لا إله إلا الله\" ويخرج من النار: هذا ممن يقولها وليس معه ناقض من نواقض الإسلام، أما من كان عنده ناقض فهو مرتد، والمرتد شَر ٌّمن الكافر الأصلي مخلّد في النار.\nس: لكن البحث في الذي يتركها وهو لا يقول: ليست واجبة هذا هو محل البحث؟\nالشيخ: هذا شيء آخر، الصواب أنه كافر؛ لكن هو مثل غيره، إذا قلنا إنه كافر صار مثل من استهزأ بالدين أو كذب محمدًا ﷺ، المعنى: صار معه ناقض من نواقض الإسلام، أرأيت لو كان إنسانًا يصوم النهار ويقوم الليل ولا يزني ولا يسرق ولكنه أخذ المصحف وبال عليه احتقارًا له أو جلس عليه، وأيش يصير؟ ما في خلاف بين أهل العلم أنه كافر مرتد، نسأل الله العافية، ولو أنه يصوم النهار، ويقوم الليل، ويشهد ألا إله إلا الله وأن محمدًا رسول الله.  فلا بدّ في الإسلام من عدم النواقض، يكون معه الإسلام ولكن ليس معه ناقض من نواقض الإسلام، ليس معه شيء من أسباب الردة، بنو حنيفة يصلون ويصومون ويشهدون أن محمدًا رسول الله وغيرها من أعمال الدين، ومع هذا من أكفر الناس، قاتلهم الصحابة لماذا؟ لأنهم شهدوا بنبوة مسيلمة، وصار معهم ناقض من نواقض الإسلام؛ لأنه لا نبي بعد محمد ﷺ، محمد خاتم الأنبياء، وهكذا أصحاب طليحة الأسدي، وهكذا أصحاب الأسود العنسي في اليمن، الدرب واحد، القاعدة أنه ما لم يكن معه ناقض.","link":"https://binbaz.org.sa/fatwas/24093/هل-يخرج-الموحد-تارك-الصلاة-من-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يخرج من النار كل من مات على التوحيد، فكيف الحال بتارك الصلاة.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":3879,"question":"الذي يصلي ويصوم في رمضان فقط ثم في سائر السنة يصلي الجمعة؟","title":"حكم من يصلي ويصوم في رمضان فقط","answer":"الجواب: هذا كافر، الصحيح من أقوال العلماء أنه كافر من لا يصلي إلا في رمضان فقط أو في الجمعة فقط، كافر بلا شك: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر رواه أحمد وأهل السنن بإسناد صحيح، وفي حديث جابر عند مسلم: بين الرجل وبين الكفر والشرك ترك الصلاة وفي الصحيحين لما قيل: يا رسول الله في الأمراء الذين يخالفون الأوامر ألا نقاتلهم؟ قال: لا، إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان، ثم قال في اللفظ الآخر: ما أقاموا فيكم الصلاة! فدل على أن إقامة الصلاة تعصم، وترك الصلاة يسمى كفرًا بواحًا لا يعصم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24094/حكم-من-يصلي-ويصوم-في-رمضان-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يصلي ويصوم في رمضان فقط.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":3880,"question":"إذا مات في خلال رمضان وهو يصلي ويصوم؟","title":"حكم من مات برمضان وهو لا يصلي في غيره","answer":"الجواب: إن كان عن توبة نفعه ذلك، وإن كان مجرد عادة ما هو عن توبة ما ينفعه.","link":"https://binbaz.org.sa/fatwas/24095/حكم-من-مات-برمضان-وهو-لا-يصلي-في-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من مات في خلال رمضان وهو لا يصلي ويصوم إلا في رمضان فقط.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":3918,"question":"من ترك الصلاة تهاونًا وكسلًا يكون كفرًا؟","title":"حكم ترك الصلاة تهاونًا وكسلًا","answer":"الجواب: هذا الصحيح من أقوال العلماء.\nس: كفر مخرج عن الملة؟\nالشيخ: نعم، كفرًا أكبر مخرجًا عن الملة، أما إذا جحد وجوبها كفر بإجماع المسلمين، ما في خلاف، ولو صلاها مع الناس، ولو أنه تقدم في الصف الأول، إذا جحد وجوبها كفر إجماعًا.\nس: كسلًا وتهاونًا يعني؟\nالشيخ: الخلاف في التهاون هو يقول هي واجبة ولكني عندي كذا وعندي كذا وعندي ظروف ويتكاسل.\nس: الحكم في هذا؟\nالشيخ: يكفر كفرًا أكبر؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر رواه الإمام أحمد وأهل السنن بإسناد صحيح، ولقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، ولقوله عليه الصلاة والسلام في الأئمة أمر ألا ينازعوا قال: إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان ثم قال: ما أقاموا فيكم الصلاة فدل على أنهم إذا لم يقيموها فقد أتوا كفرًا بواحًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24136/حكم-ترك-الصلاة-تهاونا-وكسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ترك الصلاة تهاونا وكسلا.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":3919,"question":"الرد على من قال أنه لم يشتهر عن السلف أنهم أخرجوه (تارك الصلاة) من الملة؟","title":"ما الرد على من أنكر كفر تارك الصلاة؟","answer":"الجواب: يراجع كلام أهل العلم، يراجع كلام ابن القيم في الصلاة، وفي المغني، والمحلى لابن حزم، وأشباههم الذين ذكروا الخلاف، وذكروا أدلة الفريقين، يراجع كتب أهل العلم ويستفيد.\nوأكثر ما يحتجون به من لا يكفر تارك الصلاة أكثر ما يحتج به أحاديث التوحيد وفضل التوحيد وأنه من لقي الله بالتوحيد دخل الجنة، ومن لقاه بالشرك دخل النار، والجواب عن هذا أن يقال إن المراد من لقيه بالتوحيد سالمًا من نواقض الإسلام، من لقيه بالتوحيد وهو سالم من نواقض الإسلام، هذا هو الذي يدخل الجنة، أما من لقي الله بالتوحيد ولكن معه ناقض من نواقض الإسلام فقد بطل توحيده، وذلك له أمثلة كثيرة نقول لهم: لقي الله بالتوحيد ولكنه يجحد وجوب الصلاة؟ وأيش تقولون؟ يكفر وإلا ما يكفر؟ يبطل توحيده وإلا ما يبطل توحيده؟ لقي الله وهو موحد ولكنه يقول: الزكاة غير واجبة على المسلمين يكفر وإلا ما يكفر؟ يكفر، لقي الله وهو يقول: شهر رمضان ما هو بواجب يكفر وإلا ما يكفر؟ يكفر، لقي الله وهو يقول الحج ما هو واجب ولو استطاع الناس لا يجب الحج؛ يكفر عند جميع أهل العلم فلا ينفعه التوحيد ما دام معه ناقض، فهكذا إذا لقي الله وهو لا يصلي، كذلك الحكم واحد، أو لقي الله موحدًا مخلصًا وهو يقول محمد كاذب ويش يصير؟ يكون كافرًا عند جميع أهل العلم، أو لقي الله موحدًا مخلصًا ولكنه يستهزئ بشرع الله في الجهاد أو في الصيام أو في تحريم الزنا، يستهزئ بهذا ويقول هذا تحريم الزنا عبث، ويش يصير؟ كافر وهكذا، الرد عليهم ميسر، الرد عليهم ميسر.","link":"https://binbaz.org.sa/fatwas/24137/ما-الرد-على-من-انكر-كفر-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرد على من أنكر كفر تارك الصلاة نهاونا وكسلا.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":3959,"question":"إذا كان الجار كافرًا لا يصلي؟","title":"هل يُكرم الجار إذا كان لا يصلي؟","answer":"الجواب: ولو، لا يُؤذى، يُدعى إلى الله، ويوجه إلى الخير، ولكن لا يؤذى ما دام أنه في عهد وأمان.\nس: وُجه إلى الخير وأصبح يهزأ بالدين ويسب ويلعن؟\nالشيخ: يرفع أمره إلى ولاة الأمور فيعاقبوه بما يستحق، إذا كان يستهزئ بالدين لا يترك، لكن الكلام.... لا يتكلم فيما يتعلق بالدين، له أمان وله عهد؛ لأن الجيران أقسام: جار مسلم له حقان.  وجار مسلم قريب له ثلاثة حقوق: حق الجوار والإسلام والقرابة. وجار كافر له حق واحد وهو حق الجوار.  أما إذا سب الدين أو خرج منه... يُنقض عهده، يُقتل، على ولي الأمر أن يقتله إذا ظهر منه ما يوجب قتله، لكن هذا إذا كان كافًّا أذاه وله عهد وله أمان ومستأمن فيعطى حقه من جهة الإحسان إليه، وهذا من أسباب دخوله في الإسلام إذا أحسن إليه ورأى من المسلمين إكرام الجار؛ كان هذا من أسباب دخوله في الإسلام وتعظيمه للإسلام ورغبته فيه.","link":"https://binbaz.org.sa/fatwas/24184/هل-يكرم-الجار-اذا-كان-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُكرم الجار إذا كان لا يصلي.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":4211,"question":"س: الذي تعمد ترك الصوم وبعض الصلوات.. وبعدين تاب..؟","title":"ما حكم قضاء الصلاة والصوم لمن تاب؟","answer":"الجواب: التوبة تكفي، إذا تاب تاب الله عليه، إذا كان ترك الصلاة أو أتى بنوع من الكفر أو ناقض من نواقض الإسلام التوبة كافية، إذا تاب تاب الله عليه ولا يحتاج إلى القضاء، لكن الصوم يقضيه..... وهكذا لو تأخر بالحج يأتي بالحج ولا يكفر، أما ترك الصلاة كفر على الصحيح ولو ما جحد الوجوب، فإذا ترك الصلاة ثم هداه الله فليس عليه القضاء يكفيه التوبة.\nس: يعني الصوم والصلاة سواء؟\nالشيخ: لا غير سواء، ترك الصلاة كفر، من مات عليه مات كافرًا، وإذا أسلم وتاب إلى الله ما عليه قضاء، أما إذا كان يصلي وهو طيب ولكن ترك بعض الصيام فهذا يقضي عليه القضاء مع التوبة، الصيام ما هو تركه كفر أكبر، لا، وقال بعض السلف إنه يكفر، لكن الصحيح أنه لا يكفر بذلك، يكون عاصيًا، من أفطر عامدًا يكون عاصيًا لا يكفر، وعليه القضاء والتوبة، والصلاة أعظم.\nس: لكن إذا لا يصلي ولا يصوم في نفس الوقت؟\nالشيخ: إذا كان لا يصلي ولا يصوم ما عليه قضاء، لا صيام ولا صلاة، عليه التوبة بس؛ لأنه مرتد، والمرتد لا يقضي، أما إذا كان يصلي وترك بعض الصيام يقضي الصوم.\nس: لكن إذا كان يترك بعض الصلوات فقط..؟\nالشيخ: ترك بعض الصلاة كفر، إن ترك بعض الصلاة مرة يصلي ومرة لا يصلي هذا يكون كافرًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24474/ما-حكم-قضاء-الصلاة-والصوم-لمن-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أتى بنوع من الكفر أو ناقض من نواقض الإسلام، ثم تاب.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":4287,"question":"ما المقصود بأن الذي يشرب الخمر أنه لا تقبل صلاته أربعين يومًا، وهل يترك الصلاة؟","title":"ما معنى عدم قبول صلاة شارب الخمر؟","answer":"الجواب: لا، لا يتركها، لكن يفوته ثوابها، مثل من أتى عرافًا فسأله عن شيء لم تُقبل له صلاة أربعين ليلة، تجزئه ويفوته ثوابها. أما إذا ترك الصلاة كَفَر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24559/ما-معنى-عدم-قبول-صلاة-شارب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بأن الذي يشرب الخمر أنه لا تقبل صلاته أربعين يوما.mp3","categories":["شروح الحديث","حكم الصلاة وأهميتها"]},{"id":4491,"question":"يترك فرضًا دون فرضٍ، مرة يُصلي، ومرة لا يُصلي؟","title":"حكم من يصلي ويترك ومن يؤخرها عن وقتها؟","answer":"الجواب: الظاهر أنه يكفر نعم، الذي يُصلي ولا يُصلي تارةً حكمه حكم مَن ترك.\nس: أو يُؤخِّرها عن وقتها كصلاة الفجر؟\nج: ظاهر النصوص أنه إذا أخَّرها عن وقتها عمدًا كفر بذلك، لكن بعض أهل العلم فرَّق بين المجموعة وغير المجموعة: كالظهر والعصر، والمغرب والعشاء، فالأمر في هذا أسهل، بخلاف مَن يُؤخِّر الفجر إلى بعد طلوع الشمس، أو العصر إلى بعد غروب الشمس، هذه لا شبهةَ له فيها.\nس: قد يكون نائمًا مثلًا؟\nج: إذا كان معذورًا هذا شيء آخر، إذا كان معذورًا ما هو داخلًا في هذا.\nس: إذا ما اهتم يعني: ما وضع .....؟\nج: يُخشى عليه الكفر، إذا كان يتساهل ولا يجعل ساعةً ولا يأمر ..... متساهل، هذا ظاهره التَّعمد، والقصد مسألة خطيرة، ولا سيما في هذا العصر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24771/حكم-من-يصلي-ويترك-ومن-يوخرها-عن-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يترك فرضًا دون فرضٍ أو يُؤخِّرها عن وقتها.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":4493,"question":"المسلم إذا ترك الصلاة سنوات عديدة ثم رجع؟","title":"حكم من ترك الصلاة سنوات عديدة ثم تاب","answer":"الجواب: التوبة تكفي.\nس: ما يقضي؟\nج: لا، لا، ترك الصلاة كفر، وإذا تاب لم يقضِ.\nس: هذا الصواب؟\nج: هذا الصواب نعم.","link":"https://binbaz.org.sa/fatwas/24773/حكم-من-ترك-الصلاة-سنوات-عديدة-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من ترك الصلاة سنوات عديدة ثم تاب.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":5058,"question":"بعضهم يجيء إلى المدرسة وما صلَّى الفجر، وهو في الصف السادس، وفي الصف الخامس، يعني: تجاوز سنَّ البلوغ؟","title":"ما كيفية النصح للطلاب الذين لا يصلون الفجر؟","answer":"الجواب: نسأل الله العافية، هذا في ذمة أهله يُعلِّمونه، والمدرس يُعلِّمه.\nس: هل يجب على المدرس أن يُخرجه؟\nج: يجب أن يُنبهه إلى صلاة الفجر في وقتها إن كان مُمَيِّزًا، وإن لم يكن مميزًا فما عليه شيء، لكن يُعَلَّم إذا كان ابن سبعٍ فأكثر، وإن كان ابن عشرٍ فأكثر فإنه يستحق الضرب، والواجب على المدرسين أن يُعلِّموهم ويُوجِّهوهم.","link":"https://binbaz.org.sa/fatwas/29325/ما-كيفية-النصح-للطلاب-الذين-لا-يصلون-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما كيفية التوجية للطالب الذي لم يصلّ الفجر؟.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":5078,"question":"لي والدة كبيرة في سنِّها، بها مرضٌ مُزمنٌ منذ عشرين سنةً، ومرضها نفسي، وعند حدوث المرض لا تُميز، ولا تُصلي، ويخفّ عنها المرض بعض الوقت وتُصلي، ولكن عندما تنام لا أُوقظها للصلاة حتى ترتاح، فهل عليَّ إثمٌ في ذلك؟ علمًا بأنَّها إذا صحت لا يرجع إليها المرضُ إلا بعد يومٍ أو يومين.","title":"ما حكم صلاة وصدقة المُسِنّة التي لا تمييز لها؟","answer":"الجواب: هذا يختلف: فإذا كانت في حالةٍ لا تُميز فيها فإنه لا قضاء عليها، فإذا مضى عليها يومان أو ثلاثة أو أكثر وهي لا تُميز؛ فلا شيء عليها؛ لأنَّ التكليف مناط الأحكام، فإذا زال عنها التَّمييز زال عنها التَّكليف. وإذا صَحَت في بعض الأوقات ورجع إليها عقلها صلَّت؛ لو صحت الضُّحى وجاء الظهر وهي عاقلة صلَّت الظهر، وإن جاء العصر وهي عاقل صلَّت العصر، وهكذا. وإذا غاب عنها عقلُها يومين أو ثلاثة أو أربعة أو أقل أو أكثر فإنها لا تُؤمر بالقضاء، وإذا نامت في الليل فينبغي إيقاظها آخر الليل عند أذان الفجر، تنام مبكرةً، وعليك أن تُوقظها للفجر، فإن كان عقلها معها صلَّت، وإن كانت ما عندها عقل فليس عليها شيءٌ، إذا أيقظتها سوف يبين لك أمرها، فإن بان لك أن عقلها معها سوف تقوم وتُصلي، وإن بان لك أنه ليس معها عقلها لا تُشدد عليها.\nس: ما حكم الصَّدقة من مالها أيضًا؟\nالشيخ: لا، لا تعرّض المال للصدقة، المال يكون محفوظًا حتى يتم أمر الله؛ إذا ماتت يكون للورثة، أما في حال حياتها يكون محفوظًا، إلا من باب الإنفاق عليها، فإذا أنفقتَ عليها منه -من ملابس مثلًا أو دواء-؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/29419/ما-حكم-صلاة-وصدقة المسنة-التي لا-تمييز-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صلاة وصدقة الكبيرة التي لا تمييز لها.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":5080,"question":"يقول: ما حكم صلاة مَن سمع الأذان وهو نائم، وحاول القيام للصلاة ولكن النوم غلبه والكسل، وبعد فراغ الناس من الصلاة قام وصلَّى في منزله لوحده؟","title":"حكم مَن سمع الأذان للصلاة ثم غلبه النوم","answer":"الجواب: هذا منكرٌ، لا يجوز له ذلك، يجب أن يُبادر إذا سمع النداء، يبادر ويقوم، وعليه أن يُبَكِّر في النوم حتى ينشط، ويوقِّت الساعة، أما إذا سهر فسوف يقع هذا الكسل؛ فالواجب عليه تقوى الله، وأن يقوم بالواجب من جهة الأعمال التي تُعينه على القيام، فلا يسهر، بل ينام مُبكرًا، وإذا سمع النداء أو دقَّت الساعة يقوم ويُصلي مع المسلمين في المساجد.\nيقول النبيُّ ﷺ: مَن سمع النداء فلم يأتِ فلا صلاةَ له إلا من عذرٍ، قيل لابن عباس: ما هو العذر؟ قال: خوفٌ أو مرضٌ.\nوجاءه رجلٌ أعمى فقال: يا رسول الله، ليس لي قائدٌ يقودني إلى المسجد، فهل لي رخصة أن أُصلي في بيتي؟ قال: هل تسمع النِّداء بالصلاة؟ قال: نعم، قال: فأجب، فإذا كان الأعمى الذي ليس له قائد يُؤمر أن يُجيب، فيتلمَّس الجدار ويمشي حتى يصل إلى المسجد، فكيف بالبصير القادر؟!\nوقد همَّ ﷺ أن يحرق على المُتخلّفين بيوتهم بسبب تركهم الصلاة في المساجد.\nفالواجب على المؤمن أن يتَّقي الله، وأن يُراقب الله، وأن يُسارع إلى المساجد في الليل والنهار، ويُصلي مع الناس، ولا يتساهل في الصلاة في البيت، إلا إذا كان مريضًا -نسأل الله الهداية.","link":"https://binbaz.org.sa/fatwas/29421/حكم-من-سمع-الاذان-للصلاة ثم-غلبه-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من سمع الأذان للصلاة ثم غلبه النوم.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":5194,"question":"يقول: إني أُصلي والحمد لله، ولكن أحسّ بالضيق وعدم الراحة في الصلاة، فأرشدوني جزاكم الله خيرًا.","title":"حكم من يحسّ بالضيق وعدم الراحة في الصلاة","answer":"الجواب: هذا مرضٌ من الأمراض القلبية، والغالب أنَّ سببه الذنوب والغفلة، فالذي لا ينشرح للصلاة إنما وقع له ذلك من غفلته وإعراضه وذنوبه، فليَتُبْ إلى الله، وليُجاهد نفسه، ويسأل ربَّه التوفيق، وليحضر بقلبه في الصلاة، فالصلاة راحة وقُرَّة عينٍ، يقول النبيُّ ﷺ: جُعِلَتْ قُرَّةُ عيني في الصَّلاة، فهي قُرَّة العين، ويقول لبلالٍ: أقم، أرحنا بالصلاة. فالصلاة راحة القلوب، وراحة الضَّمائر، وقُرَّة العين، إذا دخل فيها المؤمنُ ارتاح لها، واطمأنَّ قلبه، وقرَّت عينه؛ لأنَّها عمود الإسلام، ولأنه يُرضي فيها ربَّه، ويقوم بين يديه خاشعًا، فهي راحة القلوب، ونعيم الأرواح، وقُرَّة العين، فإذا أحسَّ الإنسانُ بالضيق فيها فليعلم أنَّ هذه مصيبة، وليُعالجها بالتوبة إلى الله، وسؤاله التوفيق والهداية والإعانة، والله يتوب على التَّائبين جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/30136/حكم-من-يحس-بالضيق-وعدم-الراحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 165.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":5198,"question":"يوجد لي أقارب لا يُصلُّون، فهل يجوز لي أن أُجالسهم وأن آكل معهم؟ وماذا عليَّ إذا فعلتُ ذلك؟","title":"ما حكم مجالسة ومؤاكلة الأقارب تاركي الصلاة؟","answer":"الجواب: إذا كان لك أقارب لا يُصلون تُنكر عليهم، وتدعوهم إلى الله بالحكمة والأسلوب الحسن والكلام الطيب، وتُخوفهم من الله وتقول: اتَّقوا الله، الصلاة عمود الإسلام، مَن تركها كفر، وتستعين بالله أيضًا عليهم، وسلْ ربَّك العون أن يُمدهم بالهداية، ويُعينهم على الخير، ويمنّ عليهم بالتوبة: في سجودك، وفي آخر صلاتك، وفي الأوقات الأخرى تدعو لهم. وكذلك تذهب إليهم بجماعةٍ من الإخوان الطيبين –اثنين، ثلاثة- يُساعدونك، فتنصحونهم؛ لأنك إذا جئتَ مع جماعةٍ كان أحرى للتأثير من مجيئك وحدك، فيكون معك اثنان أو ثلاثة، تنصحونهم وتُوجِّهونهم، لعلَّ الله أن يهديهم بأسبابكم، يقول النبيُّ ﷺ: مَن دلَّ على خيرٍ فله مثل أجر فاعله أخرجه مسلم في \"الصحيح\"، ويقول أيضًا ﷺ لأن يهدي الله بك رجلًا واحدًا خيرٌ لك من حمر النعم متفق على صحَّته، يقوله لعليٍّ ، والله يقول في كتابه العظيم: وَتَوَاصَوْا بِالْحَقِّ [العصر:3]، فوصف أهلَ الإيمان بالتَّواصي بالحقِّ، وقال: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. فالواجب عليك أن تُعينهم على البرِّ والتقوى، وأن تنصح لهم، وإذا لم يستجيبوا تهجرهم، فلا تُجالسهم، ولا تُجيب دعوتهم، ولا تدعوهم إلى طعامك حتى يُصلوا، ولكن لا يمنعك هذا من النَّصيحة مع الهجر، تنصح أنت وإخوانك الذين تستطيع أن تذهب بهم إليه، بالنصيحة والتوجيه والإرشاد والأمر بالمعروف والنهي عن المنكر. وفَّق الله الجميع.","link":"https://binbaz.org.sa/fatwas/30142/ما-حكم-مجالسة-ومواكلة-الاقارب-تاركي-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 171.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":5475,"question":"الذي يُصلي رغمًا عن أنفه يموت كافرًا إذا مات على هذا؟","title":"ما حكم مَن يُصلي رغمًا عنه أو لأمر أبيه؟","answer":"الجواب: المقصود أنه إذا كان ما هو لله، ما صلَّى لله، صلَّى من أجل المخلوقين ما تُقبل.\nس: بالنسبة للضغط عليه وهو يُصلي غصبًا عنه؟\nج: وَلا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا [الكهف:110]، لا بد أن يكون العملُ لله وحده.\nس: فائدة إلزام الأب ابنه ليُصلي؟\nج: تعاون، الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، فإذا صلَّى لله لما أمره أبوه ما صار رياءً، صلى لله لأنَّ أباه أمره بهذا، مثلما قال الله جلَّ وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، الإنسان يُجاهد على نفسه، يُعان على نفسه.[1]","link":"https://binbaz.org.sa/fatwas/31361/ما-حكم-من-يصلي-رغما-عنه-او-لامر-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al_moaqeyn 002.mp3","categories":["الرقائق","حكم الصلاة وأهميتها"]},{"id":5581,"question":"قول بعض أهل العلم أنَّ مَن ترك الصلاة تعمدًا لا يقضيها؛ لقول الرسول ﷺ: مَن عمل عملًا ليس عليه أمرنا فهو ردٌّ، فتعمد تركها ترد عليه، لا يُصلي؟","title":"هل يقضي الصلاة مَن تركها تعمدًا؟","answer":"الجواب: هذا إن قلنا: كفر، فلا قضاء عليه، وإن قلنا: لم يكفر، يقضي؛ لأنَّه من باب إن كان يقضي مَن نام فالذي يتركها عمدًا من باب أولى أن يقضي، عند الجمهور يقضي. س: لو ترك حتى فرضًا واحدًا؟ ج: ظاهر الحديث عام، إذا تعمَّده حتى خرج الوقت.[1]","link":"https://binbaz.org.sa/fatwas/31538/هل-يقضي-الصلاة-من-تركها-تعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 021.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":5583,"question":"جاءت والدة الصبي بعد العشاء وهو قد نام، هل تُوقظه؟ ابن سبع سنين، يعني: لم يبلغ العاشرة؟","title":"هل يجب إيقاظ الصبي النائم إذا فاتته الصلاة؟","answer":"الجواب: ظاهر الأحاديث أنه يعمُّه ذلك. س: يأمره بالجماعة؟ ج: الظاهر حتى يتمرن عليها يُؤمر بالصلاة في الجماعة. س: إذا فاتت الصبي ابن سبعٍ؟ ج: ما في قضاء، الظاهر ما عليه قضاء، وإذا أمره بالقضاء حتى يتمرن طيب، حسن، قد يُقال: يعمّه الأمر، لكن ظاهر الحديث أنه يأمره في أوقاتها يعني. س: يُضرب على الجماعة أم على الأداء -ابن سبع؟ ج: لا، يُضرب عليها إذا بلغ عشرًا. س: هل يُضرب على الأداء؟ ج: هو الظاهر، الأداء في الجماعة حتى يتمرن.[1]","link":"https://binbaz.org.sa/fatwas/31541/هل-يجب-ايقاظ-الصبي-الناىم-اذا-فاتته-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 023.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":5606,"question":"القول بأنَّ مَن ترك الصلاة متعمدًا لا يقضيها؟","title":"ما حكم قضاء الصلاة لمن تركها متعمدًا؟","answer":"الجواب: هذا شيء آخر، هذا ينبني على القول بالكفر: إذا تركها عمدًا؛ كَفَر ولا قضاء، إذا قلنا بكفره لم يقضِ، عليه التوبة فقط، أما إذا قلنا: لا يكفر، فعليه القضاء. أما النوم عن الصلاة فليس بكفرٍ، مَن نام عن الصلاة أو نسيها معذور، لكن لا يجوز التَّعمُّد، النبي ﷺ يقول: بين الرجل وبين الكفر والشرك ترك الصلاة، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر نسأل الله العافية. س: مَن ترك الصلاة عمدًا؟ ج: يكفر، يكفر. س: ولا يقضي؟ ج: إن قضى خروجًا من الخلاف لا بأس، وإن لم يقضِ فلا قضاءَ عليه، وإن قضى خروجًا من خلاف العلماء احتياطًا لدينه فلا بأس. س: المختار أنه يقضي؟ ج: إن قضى احتياطًا فلا مانع.[1]","link":"https://binbaz.org.sa/fatwas/31573/ما-حكم-قضاء-الصلاة-لمن-تركها-متعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 046.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":5674,"question":"ما نصيحتكم للذين لا يحضرون صلاةَ الفجر مع الجماعة؟","title":"ما النصيحة لمن لا يحضر صلاة الفجر؟","answer":"الجواب: الواجب على المؤمن وعلى المؤمنة الحرص على أداء الصلاة في وقتها، وعدم التَّشبه بالمنافقين، المنافق هذه حاله: أثقل الصلاة على المنافقين: صلاة العشاء، وصلاة الفجر، والواجب الحذر من التَّشبه بهم، وأن يقوم لصلاة الفجر مع المسلمين، وعلى أهله أن يُوقظوه حتى يُصلي مع المسلمين، ولا يجوز له التَّساهل في هذا. والمرأة كذلك عليها أن تُصلي في الوقت، كل هذا واجبٌ، من أهم المهمَّات، والواجب الحذر من مُشابهة المنافقين. والذي يتعمد ترك الصلاة حتى يُصليها في الضُّحى هذا كافر -نعوذ بالله-، مَن تعمَّد تركها، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر، ويقول ﷺ: بين الرجل وبين الكفر والشِّرك ترك الصلاة. فالواجب الحذر من ذلك، الواجب أن يُوقظ ويُوقت السَّاعة على الوقت؛ حتى يُصلي مع المسلمين، حتى يُصلي الصلاة في وقتها، والمرأة كذلك يجب عليها أن تحرص حتى تُصلي الصلاة في وقتها: الفجر، وغير الفجر، نسأل الله للجميع الهداية والعافية.[1]","link":"https://binbaz.org.sa/fatwas/31767/ما-النصيحة-لمن-لا-يحضر-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 020.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":5867,"question":"يوجد بعض المجاورين للمساجد، وغير المجاورين، ولا يشهدون الصلاة، فلماذا لا يؤكد على أئمة المساجد المتساهلين بالرفع عنهم إلى الجهة المختصة؟","title":"ما كيفية مناصحة تاركي الصلاة المجاورين للمساجد؟","answer":"الجواب: نسأل الله أن يعينهم هذا كثير، والمنكرات إذا كثرت قل القيام بواجب الإنكار لها، ولكن نسأل الله أن يعين الهيئات، والأئمة على القيام بواجبهم؛ لأن التاركين للصلاة في  الجماعة كثروا جدًا حتى شق على الأئمة تتبعهم، والعناية بهم، وحتى قل أن يوجد من يساعدهم من الهيئات على رد هؤلاء إلى الحق، وعلى قيامهم بأمر الله، فنسأل الله أن يعين المسؤولين، وأن يعيذهم من الكسل، والضعف، وأن يمنحهم التوفيق، والهداية، والشجاعة لإقامة الحق، ونصر الحق، والدعوة إليه، ولا شك أن هؤلاء الذين يدعون الصلاة في الجماعة قد أتوا منكرًا، وشابهوا أعداء الله المنافقين، وأحدثوا حدثًا في الإسلام يضر المسلمين. فالواجب على من له قدرة من آبائهم، وإخوانهم، وجيرانهم أن ينصحهم، وأن يرفع بأمرهم عند الامتناع إلى ولاة الأمور إلى الهيئة؛ لعلها تفعل ما تستطيع في دعوتهم إلى الحق، وإلزامهم بالحق، ووعيدهم إذا تخلفوا بالسجن، والأدب.  ومتى تكاتف الأولياء أولياء الأمور، أي أولياء الأولاد، وأشباههم من آباء، وإخوة كبار، ونحو ذلك، متى تكاتفوا مع الهيئات في هذا، ومع أئمة المساجد يحصل الخير الكثير -إن شاء الله- لكن نسأل الله أن يهديهم؛ حتى ينكروا المنكر، وحتى يرفعوا أمر المتخلفين، وحتى يتساعدوا مع الهيئة في هذا الأمر العظيم.","link":"https://binbaz.org.sa/fatwas/1215/ما-كيفية-مناصحة-تاركي-الصلاة-المجاورين-للمساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_212.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":5898,"question":"ما الحكم في ذبيحة تارك الصلاة؟ هل يجوز الأكل منها؟","title":"هل يجوز الأكل من ذبيحة تارك الصلاة؟","answer":"الجواب: الصحيح أن تارك الصلاة متعمدًا، ولو كسلًا من غير جحد للوجوب كافر كفرًا أكبر، هذا الصحيح من قول العلماء، ودليل ذلك قول النبي -عليه الصلاة والسلام- في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال -عليه الصلاة والسلام- : بين الرجل وبين الكفر، والشرك ترك الصلاة.  وقال في أمراء السوء لما سأله الصحابة عن جهادهم، قال: إلا إن تروا كفرًا بواحًا، عندكم من الله فيه برهان وفي لفظ آخر: ما أقاموا فيكم الصلاة. فدل على أن ترك إقامة الصلاة كفر بواح؛ لأنه جعله بمنزلة الكفر البواح، فعلم أن عدم إقامة الصلاة كفر بواح، ما قال ما جحدوا الصلاة، قال: ما أقاموا، فالذي يتركها، ولا يقيمها ليس من المسلمين، هذا هو الصواب.  وذهب جمع من أهل العلم إلى أنه كفره كفر أصغر، لا كفر أكبر، وأن ذبيحته تحل، ونكاحه صحيح للمسلمة؛ لأن كفره كفرًا أصغر، مثل كفر يسير الرياء، ومثل كفر من حلف بغير الله، من جرى على لسانه الحلف بغير الله، أو مثل من قال: لولا الله وفلان، أو ما أشبه ذلك، وقالوا: إن هذا معنى الحديث، وليس معناه أنه كافر كفرًا أكبر. والصواب: القول الأول؛ لأن الرسول أطلق الكفر، وجاء بلفظ (أل) بينه وبين الكفر، والشرك، والكفر المعرف، والشرك المعرف هو الشرك الأكبر، ولأدلة أخرى، والله جعل الصلاة على لسان نبيه عمود الإسلام. فالمقصود: أن تاركها على الأصح كافر كفرًا أكبر؛ وعلى هذا تكون ذبيحته غير شرعية، تكون ذبيحته ميتة، ولا ينبغي أن يواكل، ولا تجاب دعوته، ولا يرد عليه السلام، يهجر.","link":"https://binbaz.org.sa/fatwas/1235/هل-يجوز-الاكل-من-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_232.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":5915,"question":"ما الحكم في ذبيحة تارك الصلاة؟ هل يجوز الأكل منها؟","title":"هل يجوز الأكل من ذبيحة تارك الصلاة؟","answer":"الجواب: الصحيح أن تارك الصلاة متعمدًا، ولو كسلًا من غير جحد للوجوب كافر كفرًا أكبر، هذا الصحيح من قول العلماء، ودليل ذلك قول النبي -عليه الصلاة والسلام- في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال -عليه الصلاة والسلام- : بين الرجل وبين الكفر، والشرك ترك الصلاة.  وقال في أمراء السوء لما سأله الصحابة عن جهادهم، قال: إلا إن تروا كفرًا بواحًا، عندكم من الله فيه برهان وفي لفظ آخر: ما أقاموا فيكم الصلاة. فدل على أن ترك إقامة الصلاة كفر بواح؛ لأنه جعله بمنزلة الكفر البواح، فعلم أن عدم إقامة الصلاة كفر بواح، ما قال ما جحدوا الصلاة، قال: ما أقاموا، فالذي يتركها، ولا يقيمها ليس من المسلمين، هذا هو الصواب.  وذهب جمع من أهل العلم إلى أنه كفره كفر أصغر، لا كفر أكبر، وأن ذبيحته تحل، ونكاحه صحيح للمسلمة؛ لأن كفره كفرًا أصغر، مثل كفر يسير الرياء، ومثل كفر من حلف بغير الله، من جرى على لسانه الحلف بغير الله، أو مثل من قال: لولا الله وفلان، أو ما أشبه ذلك، وقالوا: إن هذا معنى الحديث، وليس معناه أنه كافر كفرًا أكبر. والصواب: القول الأول؛ لأن الرسول أطلق الكفر، وجاء بلفظ (أل) بينه وبين الكفر، والشرك، والكفر المعرف، والشرك المعرف هو الشرك الأكبر، ولأدلة أخرى، والله جعل الصلاة على لسان نبيه عمود الإسلام. فالمقصود: أن تاركها على الأصح كافر كفرًا أكبر؛ وعلى هذا تكون ذبيحته غير شرعية، تكون ذبيحته ميتة، ولا ينبغي أن يواكل، ولا تجاب دعوته، ولا يرد عليه السلام، يهجر.","link":"https://binbaz.org.sa/fatwas/1235/هل-يجوز-الاكل-من-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_232.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":5952,"question":"","title":"درجة حديث: \"كان النبي ﷺ يتحدث معنا ونتحدث معه\"","answer":"الجواب: الحديث الثاني: حديث عائشة أنها قالت: \"كان النبي ﷺ نتحدث معه، ويتحدث معنا، فإذا حضرت الصلاة؛ قام حتى كأنا لا نعرفه، ولا يعرفنا\" أنا لا أعرف حاله، ولا أذكر حاله، وسنراجعه -إن شاء الله- ويكون فيه بحث في ليلة الجمعة الآتية -إن شاء الله- ولأني ما أذكر حاله، ولعل الشيخ محمد رأفت قد وقف عليه، وعرف حاله. لكن من باب الفائدة؛ لأن الظاهر من حال النبي ﷺ أنه كان لينًا مع أهله، ولينًا مع المسلمين، وإذا حضرت الصلاة؛ قام إليها، وليس حضورها فيما يظهر موجبًا لأن يتغير حاله مع أهله، ومع من حوله، بل يقوم إليها في رغبة، وشوق -عليه الصلاة والسلام- ولكن هل يتغير منه شيء مع أهله، أو مع مجالسيه، هذا محل نظر ينبني على صحة الحديث، هذا الذي أشار إليه أخونا الشيخ محمد رأفت. وأسأل الله للجميع التوفيق، وقد أطلت بعض الإطالة، وأسأل الله لنا، ولكم التوفيق، والهداية، وأسأل الله أن يجزي إخوتنا أصحاب الندوة جزاء حسنًا، وأن يثيبهم، ويزيد من علمهم، وتوفيقهم، وأن ينفعنا بما سمعنا، وصلى الله وسلم على نبينا محمد، وعلى آله وأصحابه.","link":"https://binbaz.org.sa/fatwas/1328/درجة-حديث-كان-النبي-ﷺ-يتحدث-معنا-ونتحدث-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_297.mp3","categories":["حكم الصلاة وأهميتها","الحكم على الأحاديث"]},{"id":5961,"question":"","title":"درجة حديث: \"كان النبي ﷺ يتحدث معنا ونتحدث معه\"","answer":"الجواب: الحديث الثاني: حديث عائشة أنها قالت: \"كان النبي ﷺ نتحدث معه، ويتحدث معنا، فإذا حضرت الصلاة؛ قام حتى كأنا لا نعرفه، ولا يعرفنا\" أنا لا أعرف حاله، ولا أذكر حاله، وسنراجعه -إن شاء الله- ويكون فيه بحث في ليلة الجمعة الآتية -إن شاء الله- ولأني ما أذكر حاله، ولعل الشيخ محمد رأفت قد وقف عليه، وعرف حاله. لكن من باب الفائدة؛ لأن الظاهر من حال النبي ﷺ أنه كان لينًا مع أهله، ولينًا مع المسلمين، وإذا حضرت الصلاة؛ قام إليها، وليس حضورها فيما يظهر موجبًا لأن يتغير حاله مع أهله، ومع من حوله، بل يقوم إليها في رغبة، وشوق -عليه الصلاة والسلام- ولكن هل يتغير منه شيء مع أهله، أو مع مجالسيه، هذا محل نظر ينبني على صحة الحديث، هذا الذي أشار إليه أخونا الشيخ محمد رأفت. وأسأل الله للجميع التوفيق، وقد أطلت بعض الإطالة، وأسأل الله لنا، ولكم التوفيق، والهداية، وأسأل الله أن يجزي إخوتنا أصحاب الندوة جزاء حسنًا، وأن يثيبهم، ويزيد من علمهم، وتوفيقهم، وأن ينفعنا بما سمعنا، وصلى الله وسلم على نبينا محمد، وعلى آله وأصحابه.","link":"https://binbaz.org.sa/fatwas/1328/درجة-حديث-كان-النبي-ﷺ-يتحدث-معنا-ونتحدث-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_297.mp3","categories":["حكم الصلاة وأهميتها","الحكم على الأحاديث"]},{"id":5989,"question":"رجل مقر بأن الصلاة واجبة، لكنه لا يصلي، هل تجوز مواكلته، ومجالسته؟","title":"حكم ترك الصلاة مع الإقرار بوجوبها","answer":"الجواب:  إذا كان يقر بأن الصلاة واجبة، ولكنه لا يصلي؛ فقد تنازع العلماء في ذلك؛ هل يكون كافرًا كفرًا أكبر، أم يكون كفره كفرًا أصغر؟ على قولين. المعروف عن الصحابة -رضي الله عنهم وأرضاهم- أنه كافر كفر أكبر، لا أصغر، وأنه لا تجوز مناكحته، ولا السلام عليه، بل يجب هجره، ويجب استتابته، فإن تاب؛ وإلا قتل كافرًا. وقال آخرون: إنه كفر دون كفر، وأنه أعظم من الزنا، وأعظم من شرب الخمر، ونحو ذلك، لكنه ليس كفرًا أكبر إذا كان مقرًا بأنها واجبة عليه، ولكن غلب عليه الهوى، فتركها، قال كثير منهم: إنه كفر أصغر، ولكنه فوق الزنا، وفوق شرب الخمر، وفوق بقية المعاصي، ولكنه يغسل إذا مات، ويصلى عليه، هكذا قال جماعة من أهل العلم. والصواب: القول الأول، والأرجح: القول الأول، وأنه كفر أكبر، وأنه ما دام لا يصلي؛ فإنه يعتبر كافرًا، ويجب أن يستتاب، فإن تاب، وإلا قتل كافرًا، ويفرق بينه، وبين أهله، وألا يغسل، ولا يدفن في مقابر المسلمين، ولا يرثه أولياؤه من المسلمين، بل يكون لبيت المال إذا كان له مال.  والدليل على هذا أحاديث، بل آيات الله -جل وعلا- أخبر في كتابه العظيم عن الصلاة، وشأنها، وأمر بها، وحث عليها في مواضع كثيرة، كما قال : وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى [البقرة:238] إلى غير ذلك، وأخبرنا النبي ﷺ أنها عمود الإسلام، قال: رأس الأمر الإسلام، وعموده الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر رواه أهل السنن بإسناد صحيح.  ورواه مسلم في الصحيح عن جابر  عن النبي ﷺ أنه قال: بين الرجل، وبين الكفر، والشرك ترك الصلاة ولما قيل للنبي ﷺ في الأمراء الذين يعرف منهم، وينكر، يعني قد خلطوا قالوا: يا رسول الله، أفلا نقاتلهم؟ قال: لا ما أقاموا فيكم الصلاة وفي رواية أخرى قال: ما لم تروا كفرًا بواحًا ففسر الكفر البواح بعدم إقامة الصلاة، فمن لم يقم الصلاة، ولم يصل؛ فقد أتى كفرًا بواحًا، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1403/حكم-ترك-الصلاة-مع-الاقرار-بوجوبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_357.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":5990,"question":"ما حكم من قتل أرنبًا، أو غزالة، أو طيرًا بحجر، أو عصا، أو صدمه بالسيارة، فما حكم الأكل من هذا؟","title":"حكم أكل صيد قتل بغير محدد","answer":"الجواب: ما يأكل منه إذا صدمه بالسيارة، أو بحجر، أو بعصا، ما يأكل، يكون موقوذًا لا يحل، لكن إذا قتله بمسدس، أو أطلق عليه كلب معلم، وقتله، أو رماه بالرصاص، ويقول: بسم الله والله أكبر عند الرمي. السؤال: وبالحجر طيب؟ الجواب: إذا كان الحجر له حد؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1370/حكم-اكل-صيد-قتل-بغير-محدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_328.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":5991,"question":"ما حكم من قتل أرنبًا، أو غزالة، أو طيرًا بحجر، أو عصا، أو صدمه بالسيارة، فما حكم الأكل من هذا؟","title":"حكم أكل صيد قتل بغير محدد","answer":"الجواب: ما يأكل منه إذا صدمه بالسيارة، أو بحجر، أو بعصا، ما يأكل، يكون موقوذًا لا يحل، لكن إذا قتله بمسدس، أو أطلق عليه كلب معلم، وقتله، أو رماه بالرصاص، ويقول: بسم الله والله أكبر عند الرمي. السؤال: وبالحجر طيب؟ الجواب: إذا كان الحجر له حد؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1370/حكم-اكل-صيد-قتل-بغير-محدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_328.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":6003,"question":"ما حكم أكل اللحوم المستوردة مثل لحوم الدجاج، والأغنام، وغيرها، نرجو أن يكون الجواب كافيًا شافيًا؟ وإذا كان في الجواب تفصيل بالنسبة لطريقة، وكيفية الذبح، فكيف نحصل على المعلومات في ذلك؟","title":"حكم أكل اللحوم المستوردة من بلاد الكفار","answer":"الجواب:  هذا يكثر عنه السؤال كثيرًا، أكل المستورد من اللحوم هذا السؤال.. كثير جدًا، والحاجة ماسة إلى إحكام هذا الأمر من جهتين: من جهة ضبط المستورد، والعناية بالمستورد، ومن جهة تكليف الحكومة في كل بلد للمستوردين أن يستوردوا على بصيرة، وألا يستوردوا إلا لحومًا معروفة، قد ذبحت على الطريقة الإسلامية، وتولى ذبحها من يباح ذبحه من المسلمين، أو أهل الكتاب. هذه المسألة لا بدّ فيها من التفصيل، والذين يستوردون اللحوم الآن ليس عندنا معلومات كافية على أنهم قد اعتنوا بالشروط الكافية، وإن كان المعلوم من وزارة التجارة هنا: أن المستورد قد عني به، وأنه لا يستورد إلا الشيء الذي يباح أكله، هذا هو قولهم.  ولكن المؤمن، والمسلم قد يشك في كثير من هذه الأشياء؛ لأن المستورد من البلاد الشيوعية فيه خطر؛ ولأن المسلمون هناك مستضعفون، ومضطهدون؛ فيخشى أن لا يكونوا تولوا هذا الشيء، ويخشى أن لا يكون تولاه منهم من هو معروف بالتوحيد، والاستقامة، هذه أشياء توجب التبصر في هذا المقام. وكذلك ما يستورد من جهة الغرب من بلاد النصارى فيه شركات تذبح ذبح غير إسلامي، وفي شركات تذبح ذبحًا إسلاميًا، فالمقام فيه خطورة، والاحتياط للمؤمن ترك هذه الأشياء، وألا يأكل إلا من شيء معروف من بلاده، أو مذبوح في بلاده، أو ذبحه هو. ولكن إذا عرف أن هذا المستورد من طعام أهل الكتاب، ومما ذبحه أهل الكتاب، ولم يبلغه عن شيء يوجب تحريمه فالأصل إباحته؛ لأن الله أباح لنا طعام أهل الكتاب، فإذا عرف أن هذا المستورد من بلاد النصارى، من لندن، من فرنسا، من الدنمارك، من أشباه ذلك، وهو مقطوع الرؤوس، ولا يعلم عن هذه الشركة التي استوردت، أو هذه الجهة التي استوردت، لا يعرف ذلك، فالأصل الحل في هذا، هذا هو الأصل. ومتى عرف أن هذه الشركة التي وردت هذا اللحم أنها لا تقطع الرأس إلا بعد ذلك، بعد الموت، أو أنها تذبح بالطريقة غير الإسلامية، كالخنق، ونحو ذلك، أو رض رأسه حتى يموت، أو ما أشبه ذلك؛ فإنه لا يأكل  ما علم حرمته، إذا علم أنه منخنقة، أو موقوذة، وإذا شك في ذلك، وأحب أن يحتاط لنفسه، فمثل ما قال النبي: دع ما يريبك إلى ما لا يريبك من اتقى الشبهات؛ فقد استبرأ لدينه، وعرضه.  ولكن لا نحرم ما أحله الله، فلا نحرم طعام أهل الكتاب، بل هو حل لنا حتى نعلم أنه ...، وأما طعام الشيوعيين، والوثنين من المجوس، وغيرهم؛ فهو حرام بلا شك، إلا أن يتولاه مسلم، أو كتابي، يتولى ذبحه.","link":"https://binbaz.org.sa/fatwas/1416/حكم-اكل-اللحوم-المستوردة-من-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_360.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":6006,"question":"ما حكم أكل اللحوم المستوردة مثل لحوم الدجاج، والأغنام، وغيرها، نرجو أن يكون الجواب كافيًا شافيًا؟ وإذا كان في الجواب تفصيل بالنسبة لطريقة، وكيفية الذبح، فكيف نحصل على المعلومات في ذلك؟","title":"حكم أكل اللحوم المستوردة من بلاد الكفار","answer":"الجواب:  هذا يكثر عنه السؤال كثيرًا، أكل المستورد من اللحوم هذا السؤال.. كثير جدًا، والحاجة ماسة إلى إحكام هذا الأمر من جهتين: من جهة ضبط المستورد، والعناية بالمستورد، ومن جهة تكليف الحكومة في كل بلد للمستوردين أن يستوردوا على بصيرة، وألا يستوردوا إلا لحومًا معروفة، قد ذبحت على الطريقة الإسلامية، وتولى ذبحها من يباح ذبحه من المسلمين، أو أهل الكتاب. هذه المسألة لا بدّ فيها من التفصيل، والذين يستوردون اللحوم الآن ليس عندنا معلومات كافية على أنهم قد اعتنوا بالشروط الكافية، وإن كان المعلوم من وزارة التجارة هنا: أن المستورد قد عني به، وأنه لا يستورد إلا الشيء الذي يباح أكله، هذا هو قولهم.  ولكن المؤمن، والمسلم قد يشك في كثير من هذه الأشياء؛ لأن المستورد من البلاد الشيوعية فيه خطر؛ ولأن المسلمون هناك مستضعفون، ومضطهدون؛ فيخشى أن لا يكونوا تولوا هذا الشيء، ويخشى أن لا يكون تولاه منهم من هو معروف بالتوحيد، والاستقامة، هذه أشياء توجب التبصر في هذا المقام. وكذلك ما يستورد من جهة الغرب من بلاد النصارى فيه شركات تذبح ذبح غير إسلامي، وفي شركات تذبح ذبحًا إسلاميًا، فالمقام فيه خطورة، والاحتياط للمؤمن ترك هذه الأشياء، وألا يأكل إلا من شيء معروف من بلاده، أو مذبوح في بلاده، أو ذبحه هو. ولكن إذا عرف أن هذا المستورد من طعام أهل الكتاب، ومما ذبحه أهل الكتاب، ولم يبلغه عن شيء يوجب تحريمه فالأصل إباحته؛ لأن الله أباح لنا طعام أهل الكتاب، فإذا عرف أن هذا المستورد من بلاد النصارى، من لندن، من فرنسا، من الدنمارك، من أشباه ذلك، وهو مقطوع الرؤوس، ولا يعلم عن هذه الشركة التي استوردت، أو هذه الجهة التي استوردت، لا يعرف ذلك، فالأصل الحل في هذا، هذا هو الأصل. ومتى عرف أن هذه الشركة التي وردت هذا اللحم أنها لا تقطع الرأس إلا بعد ذلك، بعد الموت، أو أنها تذبح بالطريقة غير الإسلامية، كالخنق، ونحو ذلك، أو رض رأسه حتى يموت، أو ما أشبه ذلك؛ فإنه لا يأكل  ما علم حرمته، إذا علم أنه منخنقة، أو موقوذة، وإذا شك في ذلك، وأحب أن يحتاط لنفسه، فمثل ما قال النبي: دع ما يريبك إلى ما لا يريبك من اتقى الشبهات؛ فقد استبرأ لدينه، وعرضه.  ولكن لا نحرم ما أحله الله، فلا نحرم طعام أهل الكتاب، بل هو حل لنا حتى نعلم أنه ...، وأما طعام الشيوعيين، والوثنين من المجوس، وغيرهم؛ فهو حرام بلا شك، إلا أن يتولاه مسلم، أو كتابي، يتولى ذبحه.","link":"https://binbaz.org.sa/fatwas/1416/حكم-اكل-اللحوم-المستوردة-من-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_360.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":6140,"question":"كثير من الناس لا يصلون إلا الجمعة، وأوقات رمضان فقط، ويحتجون بحديث: الجمعة إلى الجمعة ورمضان إلى رمضان مكفرات لما بينهما فهل هذا العمل صحيح؟","title":"حكم ترك الواجبات احتجاجاً بحديث: «الجمعة إلى الجمعة»","answer":"الجواب: هذا الاستدلال جهل جهل صرف، الله أوجب علينا صلاة الجماعة، وأوجب علينا الجمعة، وأوجب علينا صوم رمضان، فعلينا أن نؤدي الواجبات، والصلوات كلها، وأن نؤدي الجمعة، ونصوم رمضان، ونفعل كل ما أوجب الله علينا، ولنا في هذا أجر عظيم، وعسانا إذا فعلنا هذا كله، واجتهدنا، وابتعدنا عما حرم الله؛ عسى أن ننجو، لعلنا ننجو من عذاب الله، لعلنا نقبل. أما أن نحتج بصلاة الجمعة، وما رتب الله عليها من كفارة، أو رمضان، ثم نضيع الواجبات هذا لا يقوله من يؤمن بالله، واليوم الآخر، هذا لا يقوله من يعقل، ومن اعتقد أن صلاة الجمعة تكفي عن بقية الصلوات؛ فهو كافر ضال مضل، نسأل الله العافية. ومن اعتقد أن صوم رمضان يسقط عنه التكاليف، وله أن يفعل ما شاء من المعاصي، فهذا أيضًا ضال مضل، وكافر بالله، نعوذ بالله!. أجمع المسلمون قاطبة على أن رمضان لا يسقط الواجبات عن الآخرين، وأن صلاة الجمعة لا تسقط الواجبات الأخرى، فصلاة الجمعة لا تسقط صلاة الفجر، ولا صلاة العصر، والفجر، ولا صلاة العصر، والمغرب، والعشاء في وقتها في يومها، إذ لا يسقط بها إلا صلاة الظهر فقط الجمعة، وأما بقية الأيام فعند جميع أهل العلم لا بدّ منها، لا بدّ من الصلوات الخمس في بقية الأيام، كما أنه لا بدّ من الصلوات الأربع في يوم الجمعة العصر، والمغرب، والعشاء، والفجر يوم الجمعة هذه لا بدّ منها.  فمن زعم أن صلاة الجمعة تسقط عنه هذه الفرائض كلها، واعتقد ذلك؛ فهذا كفر، وضلال، وعليه أن يبادر بالتوبة إلى الله  لأن هذا إسقاط للواجبات، واستحلال للمحرمات، فمن فعله معتقدًا له بعدما تقام عليه الحجة، ويبين له كفر، وضل بذلك، وهكذا رمضان صوم رمضان لا يسقط الواجبات، لا صلاة، ولا زكاة، ولا غير ذلك مما يجب. صوم رمضان فريضة على العبد أن يقوم بها، وأن يؤدها، والله -جل وعلا- جعل له في ذلك أجرًا، وثوابًا، فلا يكون ثواب رمضان مسقطًا لبقية الواجبات، وقد قال -عليه الصلاة والسلام-: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان مكفرات لما بينهن ما لم تغش الكبائر فإذا غشي الكبيرة؛ حرم ثواب الصيام -نسأل الله العافية- حرم ثواب الصلوات، حرم ثواب الجمعة، فلا يحصل له ثوابها إلا باجتنابه الكبائر، يعني المعاصي كما قال -جل وعلا-: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31] فلا يحصل تكفير السيئات، وإدخال الجنة إلا لمن تجنب الكبائر. فالمقصود: أن هذا كلام جاهل، الذي يقول: إن صلاة الجمعة، ورمضان تكفي عن بقية الواجبات، ويكفّر بها من جميع المحرمات، هذا من الجهل العظيم الذي لا يعقل له معنى، بل هو مخالف للنصوص، ومخالف لإجماع المسلمين، نسأل الله العافية. ولعله إذا أدى الواجبات كلها، وترك المحارم كلها، لعله يوفق، لعله يقبل، لعله تكفر سيئاته، لعله يفوز بالجنة، وإذا أعجب بذلك، ومنَّ على الله بذلك؛ فهو حري بالحرمان، وعدم القبول، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1614/حكم-ترك-الواجبات-احتجاجا-بحديث-الجمعة-الى-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_508.mp3","categories":["شروح الحديث","حكم الصلاة وأهميتها"]},{"id":6148,"question":"بعض الأولاد في الرابعة، والخامسة يحضرهم أباؤهم إلى المسجد، ثم بعدما ينتهي الإمام الصلاة يشوشون على المصلين، ويتكلمون، ويخرجون؟","title":"حكم إحضار الأطفال إلى المساجد","answer":"الجواب: الأولى أن لا يحضرهم حتى يعقلوا، إذا بلغوا سبعًا، وعقلوا يحضرهم، أما وهم دون ذلك، أو ما عندهم عقل يعبثون، ويؤذون فهذا لا ينبغي إحضارهم؛ لأنهم يؤذون المصلين، ويشوشون عليهم، أما إذا كان عاقلًا يفهم، ولا يؤذي، ويصلي؛ فلا بأس. السؤال: طيب يقطع الصلاة؟ الجواب:  لا ما يقطع، ما يقطع الصلاة إلا ثلاثة (المرأة، والحمار، والكلب الأسود) بس هذا الذي يقطع الصلاة، لكن لا تجعله يمر الرجل، والصبي لا يمر، والدابة لا تمر إذا تيسر منع ذلك، لكن لو مر الرجل، أو البعير، أو الغنم ما قطعت الصلاة، يقطع الصلاة: الحمار خاصة، والكلب الأسود، والمرأة.","link":"https://binbaz.org.sa/fatwas/1584/حكم-احضار-الاطفال-الى-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_483.mp3","categories":["صلاة الجماعة","حكم الصلاة وأهميتها","تربية الأولاد"]},{"id":6150,"question":"كثير من الناس لا يصلون إلا الجمعة، وأوقات رمضان فقط، ويحتجون بحديث: الجمعة إلى الجمعة ورمضان إلى رمضان مكفرات لما بينهما فهل هذا العمل صحيح؟","title":"حكم ترك الواجبات احتجاجاً بحديث: «الجمعة إلى الجمعة»","answer":"الجواب: هذا الاستدلال جهل جهل صرف، الله أوجب علينا صلاة الجماعة، وأوجب علينا الجمعة، وأوجب علينا صوم رمضان، فعلينا أن نؤدي الواجبات، والصلوات كلها، وأن نؤدي الجمعة، ونصوم رمضان، ونفعل كل ما أوجب الله علينا، ولنا في هذا أجر عظيم، وعسانا إذا فعلنا هذا كله، واجتهدنا، وابتعدنا عما حرم الله؛ عسى أن ننجو، لعلنا ننجو من عذاب الله، لعلنا نقبل. أما أن نحتج بصلاة الجمعة، وما رتب الله عليها من كفارة، أو رمضان، ثم نضيع الواجبات هذا لا يقوله من يؤمن بالله، واليوم الآخر، هذا لا يقوله من يعقل، ومن اعتقد أن صلاة الجمعة تكفي عن بقية الصلوات؛ فهو كافر ضال مضل، نسأل الله العافية. ومن اعتقد أن صوم رمضان يسقط عنه التكاليف، وله أن يفعل ما شاء من المعاصي، فهذا أيضًا ضال مضل، وكافر بالله، نعوذ بالله!. أجمع المسلمون قاطبة على أن رمضان لا يسقط الواجبات عن الآخرين، وأن صلاة الجمعة لا تسقط الواجبات الأخرى، فصلاة الجمعة لا تسقط صلاة الفجر، ولا صلاة العصر، والفجر، ولا صلاة العصر، والمغرب، والعشاء في وقتها في يومها، إذ لا يسقط بها إلا صلاة الظهر فقط الجمعة، وأما بقية الأيام فعند جميع أهل العلم لا بدّ منها، لا بدّ من الصلوات الخمس في بقية الأيام، كما أنه لا بدّ من الصلوات الأربع في يوم الجمعة العصر، والمغرب، والعشاء، والفجر يوم الجمعة هذه لا بدّ منها.  فمن زعم أن صلاة الجمعة تسقط عنه هذه الفرائض كلها، واعتقد ذلك؛ فهذا كفر، وضلال، وعليه أن يبادر بالتوبة إلى الله  لأن هذا إسقاط للواجبات، واستحلال للمحرمات، فمن فعله معتقدًا له بعدما تقام عليه الحجة، ويبين له كفر، وضل بذلك، وهكذا رمضان صوم رمضان لا يسقط الواجبات، لا صلاة، ولا زكاة، ولا غير ذلك مما يجب. صوم رمضان فريضة على العبد أن يقوم بها، وأن يؤدها، والله -جل وعلا- جعل له في ذلك أجرًا، وثوابًا، فلا يكون ثواب رمضان مسقطًا لبقية الواجبات، وقد قال -عليه الصلاة والسلام-: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان مكفرات لما بينهن ما لم تغش الكبائر فإذا غشي الكبيرة؛ حرم ثواب الصيام -نسأل الله العافية- حرم ثواب الصلوات، حرم ثواب الجمعة، فلا يحصل له ثوابها إلا باجتنابه الكبائر، يعني المعاصي كما قال -جل وعلا-: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31] فلا يحصل تكفير السيئات، وإدخال الجنة إلا لمن تجنب الكبائر. فالمقصود: أن هذا كلام جاهل، الذي يقول: إن صلاة الجمعة، ورمضان تكفي عن بقية الواجبات، ويكفّر بها من جميع المحرمات، هذا من الجهل العظيم الذي لا يعقل له معنى، بل هو مخالف للنصوص، ومخالف لإجماع المسلمين، نسأل الله العافية. ولعله إذا أدى الواجبات كلها، وترك المحارم كلها، لعله يوفق، لعله يقبل، لعله تكفر سيئاته، لعله يفوز بالجنة، وإذا أعجب بذلك، ومنَّ على الله بذلك؛ فهو حري بالحرمان، وعدم القبول، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1614/حكم-ترك-الواجبات-احتجاجا-بحديث-الجمعة-الى-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_508.mp3","categories":["شروح الحديث","حكم الصلاة وأهميتها"]},{"id":6628,"question":"هل تارك الصلاة تكاسلًا كافر؟ وإذا كان نعم فهل يخرج من الملة؟ وإذا كان نعم، فقول الله تعالى: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] نرجو توضيح ذلك؟","title":"حكم من ترك الصلاة تكاسلاً","answer":"الجواب: قد سمعتم المحاضرة، والتعليق في هذا، وأن من تركها؛ كفر، من تركها عمدًا؛ كفر على الصحيح من أقوال العلماء، من تركها؛ كفر، وارتد عن الإسلام، ولا يأتي زوجته حتى يتوب إلى الله من ذلك، ولا يغسل، ولا يصلى عليه، ولا يدفن مع المسلمين، هذا هو الأظهر، وأصح ما قيل فيه من أهل العلم. وبعض أهل العلم يرى أنه كفر دون كفر، وأنه مثل سائر الكبائر، ولكن ترك الصلاة أكبر، وأعظم، ولكن لا يكون ردة، ولكنه قول مرجوح.  والصواب: أنه كفر أكبر، وردة كبرى داخل في قوله -جل وعلا-: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] لأن تركها كفر، هو شرك -نسأل الله العافية- وداخل في قوله سبحانه: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ [النساء:48]. فإن تارك الصلاة مشرك كافر، وداخل في الآية الكريمة، وليس داخل في قوله: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] ترك الصلاة ليس دون الشرك، بل هو من الشرك، ولهذا قال النبي ﷺ بين الرجل، وبين الكفر، والشرك ترك الصلاة نسأل الله العافية، ولما النبي ﷺ الناس سألوه عن قتال الأمراء، والخروج عليهم، قال: لا، إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان ثم قال في الحديث الآخر: لا، ما أقاموا فيكم الصلاة فدل ذلك على أن ترك الصلاة كفر بواح، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2471/حكم-من-ترك-الصلاة-تكاسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_998.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":6643,"question":"هل تارك الصلاة تكاسلًا كافر؟ وإذا كان نعم فهل يخرج من الملة؟ وإذا كان نعم، فقول الله تعالى: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] نرجو توضيح ذلك؟","title":"حكم من ترك الصلاة تكاسلاً","answer":"الجواب: قد سمعتم المحاضرة، والتعليق في هذا، وأن من تركها؛ كفر، من تركها عمدًا؛ كفر على الصحيح من أقوال العلماء، من تركها؛ كفر، وارتد عن الإسلام، ولا يأتي زوجته حتى يتوب إلى الله من ذلك، ولا يغسل، ولا يصلى عليه، ولا يدفن مع المسلمين، هذا هو الأظهر، وأصح ما قيل فيه من أهل العلم. وبعض أهل العلم يرى أنه كفر دون كفر، وأنه مثل سائر الكبائر، ولكن ترك الصلاة أكبر، وأعظم، ولكن لا يكون ردة، ولكنه قول مرجوح.  والصواب: أنه كفر أكبر، وردة كبرى داخل في قوله -جل وعلا-: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] لأن تركها كفر، هو شرك -نسأل الله العافية- وداخل في قوله سبحانه: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ [النساء:48]. فإن تارك الصلاة مشرك كافر، وداخل في الآية الكريمة، وليس داخل في قوله: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] ترك الصلاة ليس دون الشرك، بل هو من الشرك، ولهذا قال النبي ﷺ بين الرجل، وبين الكفر، والشرك ترك الصلاة نسأل الله العافية، ولما النبي ﷺ الناس سألوه عن قتال الأمراء، والخروج عليهم، قال: لا، إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان ثم قال في الحديث الآخر: لا، ما أقاموا فيكم الصلاة فدل ذلك على أن ترك الصلاة كفر بواح، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2471/حكم-من-ترك-الصلاة-تكاسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_998.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":6729,"question":"ما حكم من نام عن صلاة العصر، ويقول: أنا معذور بسبب عملي، ومن سهري، ومن أول الليل حتى قرب الفجر، ثم ينام عن صلاة الفجر، ويقول: إنه في شغل دائم؟","title":"حكم التهاون في الصلاة بحجة العمل","answer":"الجواب: هذا غلط عظيم، كيف يكون معذورًا عن الصلاة؟! ولا هو معذور في عمله الذي تقوم به الدنيا، هذا من الغلط العظيم، ومن عدم الإيمان، أو ضعف الإيمان، نسأل الله العافية.  فالواجب على المؤمن أن يصلي مع الناس، ولا يمنعه عمله، ولا غيره عن الصلاة، وإذا خرج من العمل قبل الصلاة صلى مع الناس، في الطريق، في المساجد التي يمر عليها قبل أن يأتي بيته، ولا يذهب إلى بيته، ويدع الصلاة، هذا منكر عظيم، وهذه مشابهة لأهل النفاق نعوذ بالله، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2615/حكم-التهاون-في-الصلاة-بحجة-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1111.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":6782,"question":"إذا كان الميت في مرض موته لم يتمكن من أداء فروض صلاته لعدم استطاعته، هل تقضى عنه بعد وفاته؟","title":"حكم قضاء الصلاة عن الميت","answer":"الجواب: يغلط بعض الناس في هذا مثل ما سمعتم في الندوة، بعض الناس إذا مرض يتساهل في الصلاة، ولا يصلي، يقول: إذا شفيت؛ أقضي، وهذا غلط، قد يموت في المستشفى، هذا غلط، الواجب عليه أن يصلي على حسب حاله قائمًا، أو قاعدًا، أو على جنبه، أو مستلقيًا كما سمعتم في المحاضرة، هكذا أمر النبي ﷺ وإن عجز عن الماء؛ يصلي بالتيمم، وإذا كان ما تيسر له التيمم، ولا الماء؛ صلى على حسب حاله، ولو أن ثيابه نجسة.. يصلي على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إن استطاع الوضوء؛ توضأ، التيمم تيمم، إن استطاع يغير ثيابه؛ غير ثيابه، إن استطاع يغير مصلاه؛ غير مصلاه.  أما أن يتساهل، ويقول: بعدين إذا عافاني الله أصلي؛ هذا غلط، لا يجوز، النبي ﷺ قال للمريض: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا والذي لا يجد الماء؛ يتيمم، والعاجز يتيمم، ليس له عذر، هذا غلط.  فالواجب على المسلم أن ينبه إخوانه في مثل هذا، إذا زار أخاه المريض ينبهه على هذه المسائل، يقول له، إذا كان يخشى أنه يغلط في هذا؛ ينبهه، ويبين له حتى يكون هذا من باب التعاون على البر، والتقوى، وإذا مات، ولم يصل؛ ما عليه قضاء، يدعى له بالمغفرة، والعفو؛ لأنه تركها لشبهة، يصير جاهلًا، يظن أن هذا هو الأفضل، فليس في حكم من تعمد تركها مكابرة، أو تساهلًا، بعض الناس يتركها، يظن أن هذا هو المشروع، وأنه إذا صلاها بعد المرض يكون أحسن.. أكمل، وهذا من الجهل العظيم، والله المستعان. السؤال: إذا تركها ...  الجواب: كل هذا غلط. الطالب: لكن تركها، ومات وهو..؟ الجواب: لا ما تقضى عنه، لكن -إن شاء الله- يرجى له العفو من الله. الطالب: إذا كان ترك الصلاة عامدًا متعمدًا..؟ الجواب: إذا كان تساهلًا؛ يكون كافرًا -نعوذ بالله- لا يغسل، ولا يصلى عليه، أما إذا كان قصده أنه نجس، ويرى أن تأخيرها أفضل لجهله هذا ...","link":"https://binbaz.org.sa/fatwas/2631/حكم-قضاء-الصلاة-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1127.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":6893,"question":"تارك الصلاة عامدًا متعمدًا، ولكنه يقر بها؟","title":"حكم ترك الصلاة مع الإقرار بها","answer":"الجواب: ترك الصلاة عمدًا، مع الإقرار بها، والإيمان بها، فيه قولان لأهل العلم:  أحدهما: أنه كافر كفر أكبر، ومرتد عن الإسلام؛ لكونه تهاون بها، وهي عمود الإسلام، وهذا القول أرجح لأدلة كثيرة، منها: قوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة ومنها ما جاء في القرآن الكريم من ثناء الله على المصلين، وأمرهم بإقامة الصلاة، وقوله عن الكفار لما سئلوا: مَا سَلَكَكُمْ فِي سَقَرَ  ۝  قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42، 43] فذكروا أن من أسباب دخولهم النار وسلوكهم فيها أنهم ليسوا من المصلين، ومنها قوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وقوله ﷺ: بين الرجل، وبين الكفر، والشرك ترك الصلاة إلى أدلة أخرى. وقال آخرون: إنه كافر كفرًا أصغر، لا أكبر، لأن أدلة التوحيد تدل على أن ترك الصلاة هلاك، وردة عن الإسلام، وذكروا أشياء في هذا النمط تدل على ما اعتقدوه على أن كفره كفر أصغر، لا أكبر، وأنه إذا كان يعتقد وجوبها عليه، وأنها فريضة، ولكن تهاون بها أنه يكون كفره كفرًا أصغر، ويكون فاسقًا، ويكون فسقه أعظم من الزاني، والسارق، ولكنه لا يكون كفرًا أكبر، قالوا: وبهذا يصلى عليه، ويدفن مع المسلمين، وهذا قول جماعة من أهل العلم .  والقول الأول أظهر في الدليل، وأقوى في الحجة أنه كفر أكبر -نعوذ بالله من ذلك-.","link":"https://binbaz.org.sa/fatwas/2778/حكم-ترك-الصلاة-مع-الاقرار-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1270.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":7106,"question":"إذا كان هناك حاكم يدعي الإسلام، ولكنه لا يصلي، فما حكم العلماء تجاهه؟ وماذا يجب عليه في هذا؟","title":"حكم الحاكم الذي لا يصلي","answer":"الجواب:\n\nترك الصلاة كفر أكبر -نعوذ بالله- سواء كان كبيرًا، أو صغيرًا، المقصود من ترك الصلاة وهو مكلف، فترك الصلاة كفر أكبر على الصحيح.\n\nبعض أهل العلم يراها كفرًا أصغر، ويراها كالمعاصي، ولكن الصحيح أنه كفر أكبر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر لكن جماعة من أهل العلم يقولون: إنها كفر دون كفر، ولكنه قول ضعيف.\n\nأما إذا جحد وجوبها قال: ما تجب؛ هذا كفر أكبر عند جميع العلماء، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3135/حكم-الحاكم-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1493.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":7145,"question":"إذا دعاني إلى وليمة تارك صلاة، هل أذهب إليه، أم لا؟ وهل تارك الصلاة تؤكل ذبيحته؟","title":"حكم إجابة دعوة تارك الصلاة للوليمة","answer":"الجواب:\n\nإذا دعاك من هو معروف عندك بأنه يترك الصلاة؛ لا تجاب دعوته، يجب ألا تجاب دعوته، وعلى من عرف حاله أن ينصحه وأن يأمره بالمعروف وينهاه عن المنكر، فإن تاب؛ فالحمد لله، وإن لم يتب؛ وجب رفع أمره إلى ولاة الأمور، إلى الهيئة إذا استطاعت أن تقوم بشيء، أو إلى المحكمة إن استطاعت أن تقوم بشيء، أو إلى أمير البلد الذي فيه هذا التارك للصلاة، ولا يجوز تركه، بل يجب الإنكار عليه، فأولًا يبدأ بالنصيحة، والتوجيه، وأمره بالمعروف، وتحذيره من مغبة عمله السيئ، وبيان أن هذا من الكفر -نسأل الله العافية-. \n\nقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد، وأبو داود، والترمذي، والنسائي، وابن ماجة بإسناد صحيح عن بريدة  وروى مسلم في الصحيح، عن جابر، عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فجعل الفارق بينه وبين الكفار والمشركين ترك الصلاة. \n\nفالمقصود: أن ترك الصلاة موجب للكفر الأكبر في أصح قولي أهل العلم، وقال آخرون من أهل العلم: إنه كفر دون كفر، وشرك دون شرك، وأنه لا يكون كفرًا أكبر، ولكن يكون قد أتى ذنبًا عظيمًا، ونوعًا من الكفر أعظم من الزنا، وأعظم من السرقة، وأعظم من كذا وكذا، ولكن لا يكون كفرًا أكبر، والصحيح: أنه كفر أكبر إذا تعمد ذلك، وهو مما يعرف الأحكام الشرعية ... الصلاة، أما إذا كان جاهلًا بعيدًا عن المسلمين في غابات أفريقيا، أو في غابات أمريكا، في محلات بعيدة عن المسلمين، لا يعرف؛ يبين له، فإذا بين له وأصر؛ كفر.  \n\nوأما إذا تركها عن سهو، أو عن نوم؛ هذا عليه القضاء، والمبادرة بالقضاء؛ لقوله ﷺ: من نام عن الصلاة، أو نسيها؛ فليصلها إذا ذكرها لا كفارة لها إلا ذلك.  \n\nأما من يتعمد تركها، فالواجب هجره عند المسلمين، يجب على المسلمين أن يهجروهن وأن ينكروا عليه، وألا يزوروه، وألا يعودوه إذا مرض، وألا يجيبوا دعوته للوليمة، وألا يدعوه إلى وليمة، وألا يجالسوه، بل يجب إبعاده كالجرباء تبعد عن الإبلن حتى يهديه الله، ويمن عليه بالتوبة، أو يقام عليه حد ذلك، وحده القتل، حده إن لم يتب القتل، قال الله -جل وعلا- في كتابه العظيم: فَإِنْ تَابُوا وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على إن من لم يقم الصلاة لا يخلى سبيله.\n\nوقال ﷺ: إني نهيت عن قتل المصلين فدل على أن من لم يصل؛ لم ينه عن قتله، بل يؤمر بقتله، فيستتاب، فإن تاب وإلا قتل، قُتل كافرًا على الصحيح، وقال آخرون: يقتل عاصيًا ذميمًا آثما، لكن لا يرتقي إلى الكفر الأكبر.\n\nوالصواب: الأول، أنه كفر أكبر -والعياذ بالله-.  \n\nالسؤال: ولا تؤكل ذبيحته؟\n\nالجواب: ولا تؤكل ذبيحته نعم؛ لأنه كافر.","link":"https://binbaz.org.sa/fatwas/3190/حكم-اجابة-دعوة-تارك-الصلاة-للوليمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1548.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":7156,"question":"إذا دعاني إلى وليمة تارك صلاة، هل أذهب إليه، أم لا؟ وهل تارك الصلاة تؤكل ذبيحته؟","title":"حكم إجابة دعوة تارك الصلاة للوليمة","answer":"الجواب:\n\nإذا دعاك من هو معروف عندك بأنه يترك الصلاة؛ لا تجاب دعوته، يجب ألا تجاب دعوته، وعلى من عرف حاله أن ينصحه وأن يأمره بالمعروف وينهاه عن المنكر، فإن تاب؛ فالحمد لله، وإن لم يتب؛ وجب رفع أمره إلى ولاة الأمور، إلى الهيئة إذا استطاعت أن تقوم بشيء، أو إلى المحكمة إن استطاعت أن تقوم بشيء، أو إلى أمير البلد الذي فيه هذا التارك للصلاة، ولا يجوز تركه، بل يجب الإنكار عليه، فأولًا يبدأ بالنصيحة، والتوجيه، وأمره بالمعروف، وتحذيره من مغبة عمله السيئ، وبيان أن هذا من الكفر -نسأل الله العافية-. \n\nقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد، وأبو داود، والترمذي، والنسائي، وابن ماجة بإسناد صحيح عن بريدة  وروى مسلم في الصحيح، عن جابر، عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فجعل الفارق بينه وبين الكفار والمشركين ترك الصلاة. \n\nفالمقصود: أن ترك الصلاة موجب للكفر الأكبر في أصح قولي أهل العلم، وقال آخرون من أهل العلم: إنه كفر دون كفر، وشرك دون شرك، وأنه لا يكون كفرًا أكبر، ولكن يكون قد أتى ذنبًا عظيمًا، ونوعًا من الكفر أعظم من الزنا، وأعظم من السرقة، وأعظم من كذا وكذا، ولكن لا يكون كفرًا أكبر، والصحيح: أنه كفر أكبر إذا تعمد ذلك، وهو مما يعرف الأحكام الشرعية ... الصلاة، أما إذا كان جاهلًا بعيدًا عن المسلمين في غابات أفريقيا، أو في غابات أمريكا، في محلات بعيدة عن المسلمين، لا يعرف؛ يبين له، فإذا بين له وأصر؛ كفر.  \n\nوأما إذا تركها عن سهو، أو عن نوم؛ هذا عليه القضاء، والمبادرة بالقضاء؛ لقوله ﷺ: من نام عن الصلاة، أو نسيها؛ فليصلها إذا ذكرها لا كفارة لها إلا ذلك.  \n\nأما من يتعمد تركها، فالواجب هجره عند المسلمين، يجب على المسلمين أن يهجروهن وأن ينكروا عليه، وألا يزوروه، وألا يعودوه إذا مرض، وألا يجيبوا دعوته للوليمة، وألا يدعوه إلى وليمة، وألا يجالسوه، بل يجب إبعاده كالجرباء تبعد عن الإبلن حتى يهديه الله، ويمن عليه بالتوبة، أو يقام عليه حد ذلك، وحده القتل، حده إن لم يتب القتل، قال الله -جل وعلا- في كتابه العظيم: فَإِنْ تَابُوا وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على إن من لم يقم الصلاة لا يخلى سبيله.\n\nوقال ﷺ: إني نهيت عن قتل المصلين فدل على أن من لم يصل؛ لم ينه عن قتله، بل يؤمر بقتله، فيستتاب، فإن تاب وإلا قتل، قُتل كافرًا على الصحيح، وقال آخرون: يقتل عاصيًا ذميمًا آثما، لكن لا يرتقي إلى الكفر الأكبر.\n\nوالصواب: الأول، أنه كفر أكبر -والعياذ بالله-.  \n\nالسؤال: ولا تؤكل ذبيحته؟\n\nالجواب: ولا تؤكل ذبيحته نعم؛ لأنه كافر.","link":"https://binbaz.org.sa/fatwas/3190/حكم-اجابة-دعوة-تارك-الصلاة-للوليمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1548.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":7217,"question":"إذا كان ولد له أم ما تصلي إلا أنها يعني مقرة بالتوحيد يعني، وماتت، وهي تاركة للصلاة نهائيًا، وعارفة الحكم في ترك الصلاة، وعلى عقيدة شرك في الأولياء والصالحين وشيء من هذا، تعتقد فيهم، هل يضحي لها، يستغفر لها؟","title":"إهداء الثواب للميت إذا كان مقرًا بالتوحيد ولكنه لا يصلي","answer":"الجواب:\n\nلا لا، من مات على الشرك لا يستغفر له، النبي ﷺ استأذن ربه أن يستغفر لأمه -وماتت في الجاهلية- فلم يأذن له  أذن له أن يزورها، ولم يأذن له أن يستغفر لها، وهكذا لم يأذن له أن يستغفر لعمه أبي طالب، مع أنه نصره وحماه، وأنزل الله في هذا: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى [التوبة:113].\n\nفلا يستغفر للمشرك، ولو أنها أمه إذا ماتت على الشرك، أو على ترك الصلاة، لا يستغفر لها، ولا يدعى لها، لكن لا يدعى عليها، لا يدعى لها ولا يدعى عليها، لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا، لكن من مات على الشرك ولو كان والدًا، ولو كان أمًا، ولو كان أخًا، لا يدعى له، ولا يستغفر له، نسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/3275/اهداء-الثواب-للميت-اذا-كان-مقرا-بالتوحيد-ولكنه-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1600.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها","إهداء القرب للميت"]},{"id":7235,"question":"ما حكم مجالسة من لم يصلوا، بالرغم من أنهم أقارب لنا؟ ونفس السؤال ما حكم زيارة القبور؟","title":"حكم مجالسة أقارب لا يصلون ودعاء الموتى","answer":"الجواب:\n\nهذا له تعلق بالمحاضرة، وكذلك السؤال الذي قبله متعلق بالشيعة، له تعلق بالمحاضرة. \n\nأما أقاربك الذين لا يصلون، هؤلاء الواجب مقاطعتهم، وألا تزورهم، وألا يزوروك، وألا تدعهم إلى وليمة، وألا تقبل دعوتهم إلى وليمة، بل عليك أن تقاطعهم؛ حتى يهديهم الله، ويصلوا؛ لأن ترك الصلاة منكر عظيم، بل كفر، وضلال كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة.\n\nفالواجب عليك أن تقاطعهم، وأن تبتعد عنهم، إلا إذا قبلوا النصيحة، فعليك أن تنصح، وتبين لهم أنهم قد فعلوا منكرًا عظيمًا، وكفرًا بواحًا، وشرًّا مستطيرًا.\n\nفعليك أن تنصحهم، وتبين لهم خطأ ما وقعوا فيه، وأنه منكر عظيم، وأنه كفر وضلال، لعل الله يهديهم بأسبابك، وعليك أيضًا أن تحرض من له كلمة يقدرونها منه، أن ينصحهم، ويوجههم إلى الخير، فإن أجابوا؛ فالحمد لله، وإلا فوجبت مقاطعتهم، وهجرانهم حتى يتوبوا من هذا العمل السيئ. \n\nأما زيارة القبور لطلب الموتى، والاستغاثة بالموتى هذا كفر أكبر، هذا شرك أكبر، الذي يزور الموتى كالذي يزور الحسين في مصر، أو عبدالقادر في العراق، أو غيرهم، يسألونهم قضاء الحاجات، أو المدد، المدد هذا كفر أكبر.\n\nوهكذا في أي بلاد من يزور الموتى لطلب الحاجات منهم، وشفاء المرضى، أو المدد، أو العون هذا كفر أكبر، هذا دين المشركين الأولين -نعوذ بالله- هذا دين قريش الكفار، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/3302/حكم-مجالسة-اقارب-لا-يصلون-ودعاء-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1627.mp3","categories":["الدعوة والدعاة","حكم الصلاة وأهميتها"]},{"id":7475,"question":"أيضاً في رسالة عبد الله السليمان من الرياض سؤال يقول: قال الله تعالى: فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ [الضحى:9]، هل تأديب اليتيم وضربه إذا أخطأ، ولو أدى إلى بكائه الشديد يعتبر من قهره؟","title":"هل يجوز ضرب اليتيم لتأديبه وتوجيهه إلى الخير؟","answer":"الجواب:  لا، المقصود من قهره: ظلمه والتعدي عليه والتكبر عليه، أما تأديبه وتوجيهه إلى الخير فهو غير داخل في هذا، بل واجب على الولي، يجب على الولي أن يؤدبه وألا يهمله حتى تسوء أخلاقه، إذا أهمل اليتيم ساءت أخلاقه، وصار كلاً على الناس وثقيلاً على الناس. لكن الواجب على وليه أن يلاحظه، كعمه، وأخيه.. ونحو ذلك، أن يلاحظه إذا ساءت أخلاقه أدبه حتى يستقيم، حتى يكون شاباً مؤدباً، مثلما يؤدب أولاده، فالإصلاح لهم لابد منه، فكما تؤدب أولادك تؤدب اليتيم الذي عندك، وليس هذا من ظلمه ولا من قهره ولا من الإساءة إليه، بل هذا من الإصلاح والإحسان إليه حتى تستقيم أخلاقه، وحتى يكون شاباً جيداً مؤدباً يضع الأمور في مواضعها ويضع الكلام في مواضعه. نعم.","link":"https://binbaz.org.sa/fatwas/4320/هل-يجوز-ضرب-اليتيم-لتاديبه-وتوجيهه-الى-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_003/00305.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":7513,"question":"هذا سؤال من المرسل عزيز الغامدي يسأل عن الذبيحة يقول: السلام عليكم ورحمة الله وبركاته، وبعد: لقد حدث علي قصة وقصدي أستفسر من سماحتكم، ومشكلتي: أنا في ثلاثة عشر سنة من عمري وذبحت ذبيحة العيد أي: عيد النحر، وعندما قطعت الجلد فقط جاءتني حرمة وأكملت ما في هذه الذبيحة، أي: أنها قطعت البلعوم ومخته والرقبة، أي وتقول: ومخة الرقبة وذكتها، فما هو رأي سعادتكم أو سماحتكم هل ذبيحتي حلال؟ وتكملة هذه الأنثى ما يضر بصحة الحلال؟ نرجو إفادتنا عن ذلك وحفظكم الله.","title":"حكم تولي الصبي والمرأة الذبح","answer":"الجواب: لا حرج في تولي الصبي العاقل ابن سبع سنين فأكثر العاقل الذبح، ولا حرج تولي النساء الذبح، كل ذلك لا حرج فيه، المرأة تذبح مثل الرجل، والصبي كذلك العاقل يذبح مثل الكبير، لا حرج في ذلك، ذبيحة الصبي العاقل والمرأة كلها صحيحة وحلال إذا قطعت القطع الشرعي؛ قطعت الحلقوم والمري، أو كملت ذلك بقطع الودجين، كل ذلك قطع حسن، فالمقصود: أنه ليس في ذبيحة المرأة شيء ولا ذبيحة الصبي العاقل شيء. نعم.","link":"https://binbaz.org.sa/fatwas/4477/حكم-تولي-الصبي-والمراة-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00813.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":7521,"question":"هذه رسالة من المستمع عادل ناصر الفصام يقول فيها: ما حكم أكل الدجاج الذي يأتينا من فرنسا، والذي نسمع أنه يذبح بالكهرباء، وما هو واجب وزارة التجارة منه، أفيدونا وفقكم الله؟","title":"حكم ذبائح أهل الكتاب","answer":"الجواب: هذا موضوع قد طرق غير مرة، قد تكلمنا فيه غير مرة، وقد تكلمنا مع وزارة التجارة في ذلك غير مرة، وجرى في ذلك مكاتبة بيننا وبينها، والمعلوم منها: أن كل ما يرد إلى هذه البلاد كله معروف حله، وأنه ليس فيه شك، وأنه من الأشياء الطيبة المعلومة من جهة الذبح ومن جهة غيره، والأصل أيضاً حل ما يأتي من بلاد أهل الكتاب، هذا هو الأصل، ما جاءنا من بلاد أهل الكتاب؛ من النصارى واليهود ، فالأصل حله؛ لأن الله سبحانه أباح لنا طعام أهل الكتاب، وطعامهم ذبائحهم، فالذي يأتي من فرنسا، أو من إنجلترا، أو من الدنمارك، أو ما أشبه ذلك من بلاد النصارى وهكذا بلاد اليهود -لو كان بيننا وبينهم صلة- فهو حل لنا؛ لأنه من طعامهم، وليس علينا أن نفتش ونقول: لعل كذا، لعل كذا، أما إذا علمنا أنه ذبح على غير الشريعة مثل الخنق والصعق بالكهرباء، ونحو ذلك، إذا علمنا هذا في هذه الذبيحة أو في هذا اللحم، لا نأكله، أما إذا لم نعلم فالأصل الحل مثل ذبائح المسلمين، الأصل فيها الحل حتى نعلم أن هذا مسلم ذبحها ذبحاً غير شرعي كالخنق، وبهذا نكون قد أخذنا بالرخصة والتيسير وتركنا الحرج والتكلف. نعم.","link":"https://binbaz.org.sa/fatwas/4495/حكم-ذباىح-اهل-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_009/00906.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":7580,"question":"هذه الرسالة وردت من قطر من الدوحة يقول مقدمها محمد عبد الله الدوسري: السلام عليكم ورحمة الله وبركاته، وأرجو حل مشكلتي فأنا حائر في أمري هذا، والسؤال كما يلي: عندي ابن أخت عاهدته وحلفت له أنني أزوجه ابنتي إذا كان مواظباً على الصلاة، وإذا لم يصل فليس له عندي أي شيء، أعني: لم أزوجه، وثم جاء يخطب، قلت له: يا ولدي! كل أعمالك طيبة إلا ترك الصلاة، وأنا ليس أوافق عليك، فظل في عناده ثم راح وتزوج ولا زال مصراً على عدم المبالاة بالصلاة، فهل علي حرج من قبل العهد واليمين، وهل علي كفارة في ذلك؟ أفيدونا مأجورين أثابكم الله تعالى؟","title":"حكم تزويج تارك الصلاة","answer":"الجواب: أولاً تزويج الشخص الذي لا يصلي لا يجوز، لا يجوز أن يزوج شخص لا يصلي بالمسلمة؛ لأن ترك الصلاة كفر، كما قال النبي عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالذي لا يصلي كافر ولا يجوز أن يزوج بمسلمة، كما قال الله جل وعلا في الكفار: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]، وقال سبحانه وتعالى: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221]، ثم قال بعده: )وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا( [البقرة:221]. \nفالذي عليه المحققون من أهل العلم: أن تارك الصلاة كسلاً وتهاوناً كافر بنص الرسول عليه الصلاة والسلام، أما من تركها جاحداً لوجوبها هذا كافر عند الجميع، هذا كافر عند جميع أهل العلم، كل من جحد ما أوجب الله مما هو معلوم من الدين بالضرورة كالصلاة، والزكاة، والصيام رمضان، والحج.. وما أشبه ذلك، فإنه يكون كافراً كفراً أكبر ناقلاً من الملة عند جميع أهل العلم، لكن الصلاة بوجه أخص إذا تركها تكاسلاً مع إيمانه بوجوبها فإنه يكفر بذلك كفراً أكبر على الراجح من أقوال العلماء، وبهذا يعلم أن هذا الرجل الذي لا يصلي لا يجوز تزويجه، وعليك كفارة، أن تكفر عن يمينك بإطعام عشرة مساكين؛ لأنك فعلت خلاف يمينك ونقضتها، فعليك الكفارة بإطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد أو كسوتهم على قميص قميص، أو إزار ورداء، هذه كفارة اليمين. \nوعليك أيضاً أن تسعى في تخليص ابنتك منه، إما أن يطلقها بدون محاكمة، وإما أن تحاكمه إلى المحكمة الشرعية وهي تنظر في أمره وتعمل ما يقتضي الشرع في فسخ النكاح إذا ثبت أنه لا يصلي، ولا حول ولا قوة إلا بالله. \nونوصي جميع أولياء النساء أن يتقوا الله في النساء، وأن لا يزوجوهن ممن يعرف بترك الصلاة، فإن ترك الصلاة كفر أكبر؛ لأن الصلاة عمود الإسلام، فمن ضيعها فقد ضيع دينه، ومن حفظها فقد حفظ دينه، فالواجب على أولياء النساء وعلى النساء أنفسهن، الواجب على الجميع الحذر من التزوج ممن يترك الصلاة، فإن تارك الصلاة لا يؤمن وخيره قليل وشره كثير وليس مع الكفر ذنب من ترك الصلاة فقد كفر نسأل الله العافية. \nفنسأل الله أن يهدي جميع المسلمين، نسأل الله أن يهدينا جميعاً وجميع المسلمين، شباباً وشيباً، رجالاً ونساء، وأن يمن على الجميع بالتوفيق والثبات على الحق، والعافية من نزغات الشيطان. نعم. \nالمقدم: سماحة الشيخ! هو لم يزوجه ابنته؛ لأنه يقول: ظل في عناده ثم راح وتزوج ولا زال مصراً على عدم المبالاة بالصلاة، فهل علي حرج؛ لأنه قال في أول رسالته: ابن أخت عاهدته وحلفت له أنني أزوجه ابنتي إذا كان مواظباً على الصلاة، فهو يسأل: هل عليه في حلفه إذ لم يزوجه ابنته؟ \nالشيخ: لا، مادام ما زوجه فقد أحسن، زوجه من غير البنت فهذا ... \nالمقدم: نعم، زوجه من غير ابنته.\nالشيخ: فقد أحسن ولا يزوجه؛ لأن هذا لا يزوج، وليس عليه في يمينه شيء، قد أحسن وأفاد وأجاد، وهذا هو الواجب عليه أن لا يزوج شخصاً يضيع عمود الإسلام، نسأل الله العافية. نعم. \nالمقدم: لكن هل يلزمه كفارة في..؟\nالشيخ: ما دام ما زوجه ما عليه كفارة؛ هذاك لو زوجه.\nالمقدم: لأنه يقول: عاهدته وحلفت له أنني أزوجه ابنتي إذا كان مواظباً؟\nالشيخ: هذا ما واظب ولا زوجه.","link":"https://binbaz.org.sa/fatwas/4586/حكم-تزويج-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_018/01804.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":7646,"question":"هذه أيضاً رسالة فيها استفسار عن التهاون بالصلاة، بعث بها المستمع محمد بن حزام بن موسى الشهري من نجران، يقول: ما حكم من ترك الصلاة تكاسلاً حتى يخرج وقتها؟ هل عليه إثم في ذلك، وهل تنطبق عليه صفات المنافقين، أفتونا مشكورين؟","title":"ما حكم ترك الصلاة تكاسلًا؟","answer":"الجواب: تأخير الصلاة جريمة عظيمة ومنكر عظيم، وقد ذهب جمع من أهل العلم إلى من أن ترك الصلاة عمداً حتى خرج وقتها أنه يكفر بذلك كفراً أكبر وردة عن الإسلام -نعوذ بالله- ويحتجون على هذا بما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، هذا ظاهره أنه يكفر بذلك إذا أخرها حتى خرج وقتها، وقال أيضاً عليه الصلاة والسلام العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله فتأخيرها جريمة عظيمة ومنكر عظيم، فالذي -مثلاً- يؤخر الفجر حتى يصليها الضحى، هذا منكر عظيم يجب أن يصليها قبل طلوع الشمس، ويجب أن يهتم بذلك، وهو مع كونه أتى جريمة قد تشبه بالمنافقين، وقد كفره جماعة من أهل العلم بذلك.\nفالواجب على المسلم أن يعتني بالصلاة وأن يؤديها في الوقت مع المسلمين في الجماعة في المساجد، وليس له تأخيرها أبداً لا مع المسلمين ولا في البيت بل يجب أن يبادر حتى يؤديها في الوقت مع المسلمين في مساجد الله، والمرأة كذلك عليها أن تبادر بأن تصلي الصلاة في وقتها في بيتها، ولا يجوز لها التأخير، كما يفعل بعض الطالبات تؤخر الصلاة حتى تقوم بعد طلوع الشمس للمدرسة ثم تصلي، هذا لا يجوز، هذا منكر عظيم، وهكذا بعض المدرسات تؤجل الصلاة صلاة الفجر إلى أن تطلع الشمس ثم تقوم للتدريس وللصلاة، هذا منكر عظيم يجب أن تصلى الصلاة في وقتها قبل طلوع الشمس، وإذا كانت يغلبها النوم فيجب أن تتخذ ما يعينها على اليقظة مثل ساعة منبهة تؤكد على وقت الصلاة، أو تستعين بأهل البيت يوقظونها حتى تصلي الصلاة بوقتها، وهكذا العشاء لا تؤخر إلى بعد نصف الليل، وقت العشاء ينتهي إلى نصف الليل، هذا وقتها الاختياري، وكذلك المغرب لا تؤخر حتى يغيب الشفق وتصلى قبل الشفق، والشفق: الحمرة التي تكون في المغرب، يجب أن تصلي المغرب قبل ذلك قبل أن يغيب الشفق، وهكذا عند الظهر لا تؤجل حتى يصير ظل كل شيء مثله ما بعد فيء الزوال بل تصلى في أول الوقت بعد الزوال، والعصر لا تؤجل حتى تصفر الشمس بل تؤدى في وقتها، النبي ﷺ كان يؤديها في الوقت، ولما سئل عن ذلك صلى الصلاة يوماً في أول وقتها ثم صلاها في آخر وقتها، يعني الصلوات الخمس، ثم قال:: الصلاة بين هذين الوقتين، والله يقول سبحانه: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103] يعني مفروضاً في الأوقات، فالله يخبر أنها مفروضة في الأوقات، فلا يجوز لأهل الإسلام أن يؤخروها عن أوقاتها، بل يجب أن تؤدى في الوقت، ويروى عن عمر  ما يدل على الشدة في ذلك وهو كما قال  وأرضاه، وثبت عنه ﷺ أيضاً في حديث عبد الله بن عمرو بن العاص أنه قال عليه الصلاة والسلام: من حافظ على الصلاة كانت له نوراً وبرهاناً ونجاة يوم القيامة، ومن لم يحافظ عليهاا لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف-نسأل الله العافية- هؤلاء كبار الكفار ومن صناديدهم -نعوذ بالله-.\nقال بعض أهل العلم: إنه يحشر من ضيع الصلاة مع هؤلاء؛ لأنه إذا ضيعها من أجل الرياسة حشر مع فرعون ، وإن ضيعها من أجل الوزارة ونحوها حشر مع هامان وزير فرعون ، وإن ضيعها من أجل الشهوات والنعم والمال حشر مع قارون الذي أعطاه الله المال، فبطر وتكبر وعصى نبي الله موسى ، فخسف الله به وبداره الأرض -نسأل الله العافية- عقوبة عاجلة مع النار، وإن ترك الصلاة وضيعها بسبب أعمال التجارة والبيع والشراء حشر يوم القيامة مع أبي بن خلف تاجر أهل مكة.\nفالواجب على أهل الإسلام الحذر غاية من التساهل بالصلاة، والواجب أن تؤدى في أوقاتها، المرأة تؤديها في الوقت، والرجل يؤديها في جماعة في المساجد، ولا يجوز التشبه بالمنافقين في التساهل بالصلاة، وعرفت أن بعض أهل العلم يقول: إن من تركها تهاوناً حتى خرج الوقت كفر بذلك، وهذا القول قول صحيح، ترك الصلاة تهاون وتساهل بها كفر أكبر -نسأل الله العافية- فإن السنة تؤيده، السنة عن رسول الله ﷺ تؤيد هذا القول، فإن الباب فيه أحاديث صحيحة كما تقدم، فيجب على المسلم أن يحذر هذا الأمر الخطير، وأن يحافظ على الصلاة في وقتها، وأن يستعين على ذلك بكل ما يستطيع من ساعة وغيرها، حتى يؤدي الصلاة في وقتها مع إخوانه المسلمين، وحتى تؤدي المرأة صلاتها في وقتها في بيتها قبل خروج الوقت، فهي عمود الإسلام وهي أهم الفرائض بعد الشهادتين، نسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/4786/ما-حكم-ترك-الصلاة-تكاسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03507.mp3","categories":["الشروط والعيوب في النكاح","حكم الصلاة وأهميتها"]},{"id":7784,"question":"أيضاً يقول: هل ضرب إخواني وسبهم لتأديبهم حلال أم حرام، وكيف تربية النبي ﷺ؟","title":"مشروعيةضرب الأولاد لتأديبهم","answer":"الجواب: تربية الإخوان والأولاد أمر واجب، ضربهم وتوجيههم إلى الخير أمر واجب، النبي ﷺ قال: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فضرب الأولاد والإخوة الصغار وتوجيههم إلى الخير أمر لازم لك إذا كنت أنت القائم عليهم، أما السب فلا، لا تسبهم، لكن تقول لهم الكلام الطيب تحذرهم، وتأتي بالكلام الذي فيه زجرهم من دون سب: يا عدو نفسه، يا ظالم نفسه، يا كذا.. يا كذا، بالكلمات التي ليس فيها سب، ومع توبيخه، مع ضربه الضرب الذي لا يضره، ضرب غير مبرح، يحصل به المقصود من توجيهه إلى الخير ومنعه من الشر، وأما السب: لعنك الله أو أخزاك الله، هذا لا يجوز، أما بعبارات أخرى مثل يا حمار! أو يا كلب! أو يا كذا فالأولى ترك هذه الألفاظ أيضاً؛ لأنها نابية، وقد تفضي إلى ما لا تحمد عقباه، فالأولى تركها وأن يستعمل ألفاظاً غير هذه الألفاظ: يا عدو نفسه، يا ظالم نفسه، يا كذا.. من الكلمات التي ليس فيها ما يجرح الشعور أو يسبب مشاكل. نعم.","link":"https://binbaz.org.sa/fatwas/5126/مشروعية-ضرب-الاولاد-لتاديبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_048/04806.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":7872,"question":"في سؤاله الأخير سؤال أحمد بن محمد اليحيى يقول: وردت أحاديث في الحضانة بأنه ﷺ قد جعل الابن مرة للأب ومرة للأم ومرة جعلهما يستويان، ومرة خير الابن، فما هو القول في هذه المسألة أعني القول الراجح؟","title":"إرجاع أمر حضانة الأبناء إلى القضاء","answer":"الجواب: هذه المواضع هذه مسائل الحضانة فيها خلاف بين أهل العلم وفيها أحاديث متعددة، فهي ترجع إلى العلماء القضاة وينظروا فيها عند الحادثة بما يدلهم الله عليه حسب ظاهر الأدلة، وحسب حال الزوج وحال الأم المرأة، فقد يكون الزوج صالحاً وهي غير صالحة، وقد تكون صالحة هي وهي أولى بالأولاد دونه لعدم صلاحه، فالمسائل هذه تحتاج إلى نظر وعناية، فالأولى أن تترك للقضاة حتى ينظروا فيها وقت حدوثها. نعم.","link":"https://binbaz.org.sa/fatwas/5323/ارجاع-امر-حضانة-الابناء-الى-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05610.mp3","categories":["حكم الصلاة وأهميتها","الحضانة","نكاح الكفار"]},{"id":7907,"question":"سؤاله الأخير، سؤال الأخ المؤمن يقول: من له أولاد ومات عنهم، هل يبقون مع أمهم حتى ولو تزوجت أجنبياً أو أنهم يلحقون بأقاربهم كأعمامهم ونحوهم شرعاً، وهل لآراء الأطفال دور في هذا، أعني: هل لهم خيار بين أمهم وأقاربهم وفقكم الله؟","title":"حكم الطفل عند التنازع في حضانته","answer":"الجواب: هذه المسألة تحال للقضاة، إذا وقعت أمرها عند القضاة، أن المحاكم الشرعية تنظر في ذلك مع الزوجة أم الأطفال ومع أقارب الميت إذا تحاكموا إلى القضاة؛ لأنها تختلف المسائل هذه، نعم، تختلف والقضاة لهم النظر في هذا.","link":"https://binbaz.org.sa/fatwas/5405/حكم-الطفل-عند-التنازع-في-حضانته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06211.mp3","categories":["حكم الصلاة وأهميتها","الحضانة","نكاح الكفار"]},{"id":7922,"question":"ونبدأ يا سماحة الشيخ برسالة أحمد ضيف حسين من الجمهورية العراقية محافظة نينوى قضاء الشرقاط، يقول المستمع أحمد في رسالته، يقول: عندي ولد عمي توفي وعنده بنت، وبقيت هي ووالدتها في الدار بعد وفاته، يقول: وبعد وفاته تزوجت زوجته وأخذت زوجاً غريباً عن عشيرتي ولا من أقربائي، فأخذت البنت معها ولم تعطنيها وأنا أقرب الأقربين إليها، فذهبت إلى المحكمة الشرعية، فقدمت شكوى وجرت المرافعة بيني وبين أم البنت، والقاضي أعطى الحق إلى أم البنت، هل هذا صحيح، أرجو الحل السريع وشكراً، وأمد الله في عمركم؟","title":"مراعاة مصلحة الطفل عند التنازع في حضانته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفالحضانة للأطفال الصغار من الذكور والإناث تدور في الأغلب على رعاية المصلحة للطفل سواء كانت المصلحة في جانب الأم أو في جانب الولي الذي هو من جهة الأب، والقاضي هو الذي ينظر في هذه المسائل ويقدر المصلحة للطفل، وهذه القضية التي ذكرتها -أيها السائل- وهي كون ابن عمك توفي وخلف ابنة، وهذه الابنة تزوجت أمها ورأى القاضي أن تكون مع أمها هذه من جملة مسائل الحضانة التي ينظر فيها القاضي ويراعي الأصلح، فإذا رأى القاضي أن الأصلح بقاؤها مع أمها المزوجة فلا بأس ويقدم ذلك على ابن عمها، بل وعلى عمها، بل وعلى أبيها إذا رأى القاضي أن بقاءها مع أمها أصلح من تسليمها لأبيها لو كان موجوداً مطلقاً، مثل لو طلق أمها وكان موجوداً ورأى القاضي أن دفعها إلى أبيها لا يصلح؛ لفسقه وبدعته أو نحو ذلك، أو لأسباب أخرى، فهكذا من باب أولى إذا رأى ألا تسلم لعمها أو جدها أو ابن عمها، فبكل حال ينبغي لك يا أخي ألا تتأثر بهذا وأن تحسن الظن بما فعله القاضي، فهو إن شاء الله موفق؛ لأن وجودها عند أمها فيه مصالح كثيرة، ولاسيما إذا كان زوجها طيباً ولا يخشى منه عليها شر. نعم.","link":"https://binbaz.org.sa/fatwas/5421/مراعاة-مصلحة-الطفل-عند-التنازع-في-حضانته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_064/06401.mp3","categories":["حكم الصلاة وأهميتها","الحضانة","نكاح الكفار"]},{"id":7973,"question":"وبقي له سؤال أيضاً يقول: هل يجوز الأكل والشرب في بيت شخص لا يؤدي الصلاة ولا الصيام علماً أن عمره يتجاوز أربعين سنة، فما حكم ذلك وفقكم الله، هذا ولكم الشكر؟","title":"حكم مؤاكلة ومجالسة تارك الصلاة والصيام","answer":"الجواب: الذي لا يصلي لا يجوز أن تجاب دعوته ولا أن يقصد شرب قهوته ولا الأكل من وليمته، بل يجب أن يهجر ويجب أن يستتاب حتى يرجع عن باطله، فإن الصلاة هي عمود الإسلام، ومن تركها كفر نسأل الله العافية، فالذي يتركها يجب أن يهجر بين المسلمين، ولا يزار، ولا تجاب دعوته، ولا يسلم عليه، ولا يرد عليه السلام؛ لأنه ترك عمود الإسلام، ولأنها أعظم الأركان بعد الشهادتين؛ ولهذا قال عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة وقال عليه الصلاة والسلام أيضاً: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفالذي يتركها عمداً كافر نسأل الله العافية، يجب أن يهجر وألا يسلم عليه، ولا يرد عليه السلام، ولا تجاب دعوته، ويجب على ولي الأمر أن يستتيبه، فإن تاب ورجع عن باطله وإلا وجب أن يقتل، هذا هو الصواب فيه، وهذا هو الذي عليه جمهور أهل العلم، نسأل الله السلامة والعافية. نعم.","link":"https://binbaz.org.sa/fatwas/5522/حكم-مواكلة-ومجالسة-تارك-الصلاة-والصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_071/07103.mp3","categories":["الشروط والعيوب في النكاح","حكم الصلاة وأهميتها"]},{"id":8061,"question":"هذه الرسالة وردتنا من مسفر لافي العتيبي يقول: أرجو عرض رسالتي هذه على سماحة الشيخ عبد العزيز بن باز، يقول: ما معنى هذه الآية التي وردت في سورة الروم: وَأَقِيمُوا الصَّلاةَ وَلا تَكُونُوا مِنَ الْمُشْرِكِينَ ۝ مِنَ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا [الروم:31-32]؟ وهل يقال لتارك الصلاة: أنه مشرك؟","title":"هل يقال لتارك الصلاة: أنه مشرك؟","answer":"الجواب: ثبت عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، وثبت عنه عليه الصلاة والسلام أيضاً أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة، أخرجه مسلم في صحيحه من حديث جابر ، هذا يدل على أن تارك الصلاة يسمى: كافراً، ويسمى: مشركاً، وهو الحق، وهو المعروف عن الصحابة رضي الله عنهم، فإن عبد الله بن شقيق العقيلي رضي الله عنه ورحمه التابعي الجليل قال: (لم أر أصحاب رسول الله ﷺ يعدون شيئاً تركه كفر إلا الصلاة)، فهذا يدل على أن الصلاة عند الصحابة يعتبر تركها كفراً، يعني: كفراً أكبر، ويسمى: كافراً مشركاً، فالذي ترك الصلاة قد فرق دينه، وقد خرج عن جماعة المسلمين، واستحق أن يقتل إن لم يتب؛ لقول النبي ﷺ : لا يحل دم امرئ مسلم يشهد أن لا إله إلا الله، وأني رسول الله، إلا بإحدى ثلاث: الثيب الزاني، والنفس بالنفس، والتارك لدينه المفارق للجماعة.\nفالذي يترك الصلاة يعتبر تاركاً لدينه مفارقاً للجماعة، نسأل الله العافية والسلامة. نعم.","link":"https://binbaz.org.sa/fatwas/5857/هل-يقال-لتارك-الصلاة-انه-مشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_083/08302.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":8062,"question":"لكن هل يقال لمن ترك الصلاة: إنه مشرك؟","title":"حكم وصف تارك الصلاة بالكافر والمشرك","answer":"الجواب: نعم يقال له: مشرك، ويقال له: كافر في أصح قولي العلماء، لكن الجمهور قالوا: كفر دون كفر، وشرك دون شرك، والصواب الذي عليه جمع من أهل العلم، أنه كفر أكبر وشرك أكبر، كما حقق ذلك ابن القيم رحمه الله في كتاب: الصلاة، وذكره الذهبي عن جماعة في الكبائر، وذكره آخرون رحمهم الله، ودل عليه الحديث السابق الذي رواه مسلم في الصحيح من حديث جابر أن النبي ﷺ قال: بين الرجل وبين الكفر والشرك ترك الصلاة، فسماه: كفراً وشركاً، والكفر المعرف والشرك المعرف بأداة التعريف هو الكفر الأكبر والشرك الأكبر: بين الرجل وبين الكفر والشرك ترك الصلاة، رواه مسلم في الصحيح. نعم.","link":"https://binbaz.org.sa/fatwas/5858/حكم-وصف-تارك-الصلاة-بالكافر-والمشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_083/08303.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":8186,"question":"ونبدأ برسالة المستمع، مستمع من ضواحي الخرج، يقول في رسالته المستمع -وقد كتب اسمه في.. لكنه غير واضح جداً- يقول: إنه من ضواحي مدينة الخرج، يقول في رسالته: هل لحوم الدجاج والأغنام المستوردة من الخارج حلال أم هي حرام، مع ذكر الدليل إن وجد وفقكم الله؟","title":"تفصيل الحكم في اللحوم المستوردة","answer":"الجواب: ... أما بعد: هذه اللحوم المستوردة فيها تفصيل: إن كانت من بلاد أهل الكتاب كـاليهود والنصارى فيحل لنا، مثل ما يستورد من فرنسا، إنجلترا، أمريكا، الدنمارك وأشباه ذلك؛ لأن الله أباح لنا طعام أهل الكتاب، حيث قال : وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ [المائدة:5]، وطعامهم ذبائحهم، الله أباح لنا طعامهم وهي ذبائحهم، وقد أجمع أهل العلم على ذلك، فما كان من بلاد أهل الكتاب وهم من اليهود والنصارى فهو حل لنا، إلا إذا علمنا أنه ذبح على غير الشرع، كأن يكون ذبح بالخنق والوقذ، هذا لا يحل، مثل ذبيحة المسلم التي يذبحها بالخنق والوقذ لا تحل، أما مادمنا نجهل ذلك فالأصل الحل، ما دمنا لا نعلم أنها ذبحت على غير الشرع، فالأصل حل ذلك، مثل ذبيحة المسلم، أما الذبائح الأخرى التي ترد من البلاد الشيوعية أو الوثنية كالهند، أو الشيوعية كبلغاريا والسوفيت هذه لا تحل، إلا إذا علمنا أنه ذبحها مسلم أو كتابي، إذا علمنا ذلك لا بأس، وأما إذا لم نعلم فالأصل تحريم ذبائحهم، ....... تحريم ذبائح الوثنيين وتحريم ذبائح الملحدين، ذبائح الملحدين من الشيوعيين ، فينبغي التفريق والتفصيل. نعم.","link":"https://binbaz.org.sa/fatwas/5995/تفصيل-الحكم-في-اللحوم-المستوردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_092/09201.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":8238,"question":"تقول: تقدم لها شاب هو ابن عمتها لكنه لا يصلي، بم تنصحونهم والحالة هذه شيخ عبد العزيز ؟","title":"هل يجوز تزويج التارك للصلاة؟","answer":"الجواب: أنصحها ألا تتزوج هذا الشاب؛ لأن من ترك الصلاة كفر - نسأل الله العافية- في أصح قولي العلماء؛ لقول النبي المصطفى عليه الصلاة والسلام في الحديث الصحيح الذي رواه مسلم في الصحيح عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة ، وروى الإمام أحمد في المسند وأصحاب السنن؛ أبو داود و الترمذي و النسائي و ابن ماجة بإسناد صحيح عن بريدة رضي الله عنه، عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ، في أحاديث أخرى تدل على كفر تارك الصلاة.\nفنصيحتي لهذه الفتاة ألا تتزوج هذا، وأن تلتمس رجلاً يخاف الله ويقيم الصلاة ويؤدي فرائض الإسلام، هذا هو الواجب عليها وعلى غيرها، وسوف يعوضها الله خيراً منه، فإن الله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وفي الحديث: من ترك شيء لله؛ عوضه الله خيراً منه فهي إن شاء الله على خير، ويرجى لها أن توفق لمن هو أصلح منه ولمن هو خير لها في دنياها وفي أخراها. نعم.","link":"https://binbaz.org.sa/fatwas/6050/هل-يجوز-تزويج-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09710.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8242,"question":"تقول: تقدم لها شاب هو ابن عمتها لكنه لا يصلي، بم تنصحونهم والحالة هذه شيخ عبد العزيز ؟","title":"هل يجوز تزويج التارك للصلاة؟","answer":"الجواب: أنصحها ألا تتزوج هذا الشاب؛ لأن من ترك الصلاة كفر - نسأل الله العافية- في أصح قولي العلماء؛ لقول النبي المصطفى عليه الصلاة والسلام في الحديث الصحيح الذي رواه مسلم في الصحيح عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة ، وروى الإمام أحمد في المسند وأصحاب السنن؛ أبو داود و الترمذي و النسائي و ابن ماجة بإسناد صحيح عن بريدة رضي الله عنه، عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ، في أحاديث أخرى تدل على كفر تارك الصلاة.\nفنصيحتي لهذه الفتاة ألا تتزوج هذا، وأن تلتمس رجلاً يخاف الله ويقيم الصلاة ويؤدي فرائض الإسلام، هذا هو الواجب عليها وعلى غيرها، وسوف يعوضها الله خيراً منه، فإن الله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وفي الحديث: من ترك شيء لله؛ عوضه الله خيراً منه فهي إن شاء الله على خير، ويرجى لها أن توفق لمن هو أصلح منه ولمن هو خير لها في دنياها وفي أخراها. نعم.","link":"https://binbaz.org.sa/fatwas/6050/هل-يجوز-تزويج-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09710.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8292,"question":"الرسالة الأخيرة في حلقة هذا المساء رسالة الأخ محمد محمود إدريس من الرياض، أخونا يقول: إنه متزوج من حرمة وله منها أربعة أولاد، وهي الآن حاملة بالخامس، لكن حرمته لا تصلي منذ أن تزوجها حتى الآن، بم تنصحونه سماحة الشيخ؟","title":"حكم من تزوج بامرأة لا تصلي وأنجب منها","answer":"الجواب: هذا منكر عظيم؛ لأن الصلاة عمود الإسلام، وهي أعظم الفرائض وأهمها بعد الشهادتين، كما قال الله جل وعلا: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]، وقال سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعََ الرَّاكِعِينَ[البقرة:43]، وقال سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238]، وقال جل وعلا: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَإِخْوَانُكُمْ فِي الدِّينِ[التوبة:11] فدل ذلك على أن من لم يصل لا يخلى سبيله بل يقتل، وهكذا ليس أخاً في الدين من لم يصل، فالواجب استتابتها وتأديبها حتى تصلي، ومن تاب تاب الله عليه، فإن أبت لا يجوز بقاؤها في حباله، بل يرفع بأمرها إلى المحكمة حتى تستتيبها فإن تابت وإلا قتلت مرتدة عن الإسلام في أصح قولي العلماء؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال جماعة من أهل العلم: إنها تقتل حداً لا ردة، وبكل حال فالواجب استتابتها فإن تابت وإلا وجب على ولى الأمر وهو القاضي النائب عن ولي الأمر الأمر بقتلها إذا لم تتب، وعلى الزوج أن يفارقها إذا لم تتب؛ لأنها كافرة، والمسلم لا يتزوج كافرة ولا يبقي بحبال كافرة، هي كافرة في أصح قولي العلماء، وقال قوم: إنه كفر دون كفر، ولكن الصواب أنه كفر أكبر، فلا ينبغي للزوج ولا يجوز له أن يبقي في حبال امرأة لا تصلي، بل يجاهدها ويؤدبها ويقوم عليها لعلها تتوب ولعلها تصلي، فإن لم تفعل فارقها وسوف يعوضه الله خيراً منها، والواجب عليه أن يؤدبها هو وأبوها وأهلها حتى تقوم بالواجب حتى تصلي، فإن دعته الحاجة إلى رفعها إلى ولي الأمر كالمحكمة رفعت إليه إلى المحكمة حتى تستتيبها فإن تابت وإلا قتلت مرتدة كافرة عند جمع من أهل العلم، أو حداً عند آخرين من أهل العلم كما هو معلوم. ولا حول ولا قوة إلا بالله، نعم.\nالمقدم: جزاكم الله خيراً، الواقع سماحة الشيخ المدة طويلة جداً كونها تنجب خمسة أو أربعة، وإلى الآن لم يفكر في هذا الموضوع، يبدو لي أنه مقصر كثيراً، لكن لعله يستدرك ما فات ويتوب فجزاكم الله خيراً إذ نصحتموه ... ؟\nالشيخ: لا شك أنه مقصر، لا شك أن سكوته عنها وعدم قيامه عليها منكر عظيم، الرسول ﷺ يقول: من رأى منكم منكراً فليغيرهه بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان وهو قادر على أن ينكر بلسانه ويده جميعاً، والله يقول جل وعلا في كتابه العظيم: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] فإنكار المنكر أمر لازم على الرجال والنساء جميعاً، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/6105/حكم-من-تزوج-بامراة-لا-تصلي-وانجب-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_107/10708.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":8314,"question":"أخت من جيزان اسمها دعاء جبريل -كما سمت نفسها- تسأل مجموعة من الأسئلة، خمسة أسئلة في الواقع.. سماحة الشيخ، في سؤال لها تقول: عندما تذبح ذبيحة لنا أحياناً يذبحها إنسان لا يصلي، ولكنه مسلم، وقد سمعت في هذا البرنامج أن الذي لا يصلي يعتبر كافر، فهل علي إثم إذا أكلت من لحم هذه الذبيحة، أفيدونا أفادكم الله؟","title":"هل تجوز ذبيحة تارك الصلاة؟","answer":"الجواب: اختلف العلماء رحمة الله عليهم في الرجل الذي يدع الصلاة وهو لا يجحدها، يعلم أنها فرض وأنها واجبة عليه، ولكنه يتساهل فيصلي تارة ويدع الصلاة أخرى، أو لا يصلي بالكلية؟\nفذهب جمع من أهل العلم إلى أنه قد أتى منكراً عظيماً أعظم من الزنا وأعظم من السرقة وأعظم من العقوق، لكنه لا يكفر كفراً أكبر بل كفر أصغر، هكذا قال جمع من أهل العلم، وبهذا قالوا: تحل ذبيحته؛ لأنه لا يزال مسلماً.\nوذهب آخرون من أهل العلم إلى أنه يكفر بذلك، متى ترك الصلاة عمداً ولو لم يجحد وجوبها فإنه يكفر بذلك، وهذا هو الصواب هذا هو الحق، وهذا هو المروي عن الصحابة ، قال عبد الله بن شقيق العقيلي التابعي الجليل: لم يكن أصحاب رسول الله ﷺ يرون شيئاً من الأعمال تركه كفر إلا الصلاة . فجعلوا ترك الصلاة كفراً، وإن لم يجحد وجوبها، وهكذا يقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ويقول عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، والأحاديث الصحيحة في هذا كثيرة تدل على أن من تركها كفر وإن لم يجحد وجوبها، سواءً كان رجلاً أو امرأة.\nهذا هو الصواب وبهذا تكون ذبيحته غير حل، إذا ذبح ذبيحة تكون ذبيحته ميتة كذبيحة المجوسي وشبهه، ذبيحة اليهودي حل، ذبيحة النصراني حل؛ لأنه من أهل الكتاب، أما ذبيحة الكافر بترك الصلاة أو بعبادة الأموات والاستغاثة بالأموات أو بسب الدين أو بالاستهزاء بالدين هؤلاء كفار أشد من اليهود والنصارى ، تكون ذبيحتهم غير صحيحة وغير ذكية وغير مباحة.\nفينبغي الانتباه لهذا، والحذر من التساهل في هذا الأمر، أما من جحد وجوبها وقال: ما هي بواجبة، أو استهزأ بها فهذا كافر عند جميع أهل العلم، إذا جحد وجوبها واستهزأ بالمصلين ورأى أنهم ناقصو العقول بأداء هذه الصلاة، فهذا كفر أكبر نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/6119/هل-تجوز-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10809.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":8323,"question":"بقي له سؤال في رسالته يقول: هل إذا تزوج رجل امرأة ظن أنها تقيم الصلاة، وتبين له بعد ذلك أنها لا تصلي، فهل هذا الزواج باطل، وهل إذا تابت وأصبحت تقيم الصلاة يستمر معها؟","title":"حكم الزواج بامرأة لا تصلي","answer":"الجواب: هذه المسألة مبنية على أصل وهو الحكم في تارك الصلاة، فمن قال: إنه كافر كفراً أكبر وإن لم يجحد وجوبها قال: إن هذا النكاح باطل؛ لأن الكافرة لا تصلح للمسلم، والله يقول في حقهن: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] وقال: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221] فالتاركة للصلاة مشركة على القول الحق، فلا تنكح حتى تتوب إلى الله عز وجل؛ لقوله سبحانه: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221] ولقوله في سورة الممتحنة: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10].\nأما على القول الآخر وهو: أن تارك الصلاة تهاوناً وكسلاً ليس بكافر كفراً أكبر ولكنه كفر أصغر وعاصي وحكمه حكم أهل الكبائر، فعلى هذا القول يكون النكاح صحيحاً، ويكون له عذر إذا فارقها؛ لأن ترك الصلاة عيب عظيم.\nولكن الصواب أنه كفر أكبر، وأنها إذا كانت لا تصلي فهي كافرة فلابد من تجديد النكاح، إذا تابت ورجعت إلى الله لابد من تجديد النكاح، هذا هو الصواب؛ لأنها ليست كالكتابية، بل ترك الصلاة ردة، فلابد من توبة صادقة، توبة نصوح، فإذا تابت جدد نكاحها إذا رغب فيها، وإلا تركها ومتى خرجت من العدة ساغ لها أن تتزوج وينبغي له أن يطلقها طلقة واحدة خروجاً من الخلاف حتى لا يبقى هناك خلاف، وحتى تتزوج على بصيرة، فإن المسألة خلافية فإذا طلقها طلقة واحدة كان ذلك قطعاً للتعلق بها وقطعاً لتعلقها به، وخروجاً من خلاف العلماء القائلين بأن النكاح ليس بفاسد؛ لأن ترك الصلاة عندهم ليس بكفر أكبر.\nوالمقصود في هذا: بيان الحكم الذي هو أولى بالدليل وأحق بالدليل، ولا شك أنه القول بكفر تارك الصلاة كفراً أكبر إذا كان تركها تهاوناً غير جاحد لوجوبها، أما من جحد وجوبها فإنه يكفر بإجماع المسلمين كفراً أكبر نسأل الله العافية؛ لأنه مكذب لله ولرسوله عليه الصلاة والسلام، وإنما النزاع فيمن تركها تهاوناً وهو يؤمن بوجوبها هذا هو محل النزاع، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر رواه أهل السنن والإمام أحمد بإسناد صحيح، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وهذا دليل على أن تركها كفر أكبر، نسأل الله السلامة. نعم.\nالمقدم: يعني: المستمع في هذه الحالة إن كان يرغب في البقاء معها فعليه أن يجدد عقد نكاحه؟\nالشيخ: بعد توبتها. نعم.\nالمقدم: جزاكم الله خير.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6140/حكم-الزواج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20205.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8330,"question":"شيخ عبدالعزيز! أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة يقول: الرياض (م. م. ع. م) أخونا يقول: أرجو من سماحتكم التكرم بالإجابة عن هذا السؤال وهو: أن الكثير من الناس تساهلوا بأمر الصلاة، وكثير من الناس يؤخرها عن و قتها، والبعض أيضاً لا يصليها مع الجماعة، نرجو أن تتفضلوا بالإجابة والتوجيه جزاكم الله خيراً؟","title":"التحذير من التهاون بالصلاة والتكاسل عنها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن الصلاة أمرها عظيم، وهي عمود الإسلام كما صح بذلك الحديث عن رسول الله عليه الصلاة والسلام أنه قال: رأس الأمر الإسلام وعموده الصلاة وذروة سنامه الجهاد في سبيل الله، وقد أكثر الله من ذكرها في كتابه العظيم في مواضع كثيرة؛ لعظم شأنها فقال تعالى: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238]، وقال : وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] في آيات كثيرات. فالواجب على كل مسلم وعلى كل مسلمة العناية بالصلاة والمحافظة عليها في وقتها، والحذر من التثاقل عنها والتكاسل؛ فإن ذلك من صفات أهل النفاق كما قال الله سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوََ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142]، وكذلك يجب على الرجل أن يصليها مع الجماعة في بيوت الله سبحانه وتعالى، كما قال تعالى: وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43].\nفالواجب أن يصلي مع إخوانه المسلمين، وقال النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، واستأذنه رجل أعمى فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي الكريم عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟قال: نعم، قال: فأجب، فإذا كان أعمى ليس له قائد يلائمه لا يرخص له في ترك الجماعة فكيف بحال من عافاه الله وأعطاه البصر والقوة؟! فالواجب على أهل الإسلام أن يعنوا بالصلاة وأن يعظموا أمرها كما عظمها الله ورسوله، وأن يجتهدوا في أدائها كما شرع الله، فالرجل يؤديها في الوقت في المسجد مع إخوانه المسلمين، ويحذر غاية الحذر من التثاقل، والمرأة كذلك عليها أن تؤديها في بيتها في وقتها بالطمأنينة والخشوع وعدم التثاقل عنها، وكثير من الناس يؤديها بغير خشوع وبغير طمأنينة بل بالعجلة، وهذا خطأ عظيم، فإن الصلاة لا بد فيها من الطمأنينة، ولما رأى النبي ﷺ رجلاً يصلي ولا يتم ركوعه ولا سجوده أمره أن يعيد قال: ارجع فصل فإنك لم تصل.\nفالواجب على الجميع العناية بالصلاة فرضاً ونفلاً، وأن تكون عن طمأنينة وإقبال عليها لا عن عجلة ونقر، وأعظم ذلك الفريضة، فالواجب العناية بها أكثر وأن تؤدى كما شرع الله  في أوقاتها بالطمأنينة، واستكمال ما شرع الله فيها من الأركان والواجبات، والأفضل أيضاً أن يعتني بالمستحبات حتى يؤديها كاملة، وليس له تأخيرها عن وقتها؛ لأن تأخيرها عن وقتها محرم وفيه إضاعة أدائها في الجماعة أيضاً، وكذلك في حق المرأة لا يجوز لها أن تؤخرها عن وقتها، بل يجب أن تصلى الصلاة في وقتها، وكثير من الناس الآن قد يؤخرها عن وقتها كصلاة الفجر فيسهر الليل ويتأخر عن صلاة الفجر، وهذه مصيبة عظيمة ولا حول ولا قوة إلا بالله.\nفالواجب الحذر من ذلك في حق الرجال والنساء، وكل سهر يفضي إلى هذا فهو محرم، فلا يجوز السهر الذي يفضي إلى ترك الصلاة في وقتها، أو تركها في الجماعة في حق الرجل، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/6143/التحذير-من-التهاون-بالصلاة-والتكاسل-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11101.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":8337,"question":"أختنا في الواقع لها سؤال آخر سماحة الشيخ ويبدو لي أنه ثمرة هذا الزواج غير الموفق ولا حول ولا قوة إلا بالله، تقول: إن لها ابناً لا يصلي، وقد نصحته وهددته ولم يبال، عمره ست عشرة سنة، تقول: إنها تنصحه وهو يستهزئ بها وفي بعض الأحيان يصلي ويعود ويقول: إن الشيطان يوسوس فوق رأسه، وتستمر من مثل هذه العبارات سماحة الشيخ وتسأل وتقول: إنني مستجيرة بالله ثم بكم تنقذوني مما أنا فيه وتقودوني إلى الصواب، وما العمل لأرملة لا حول لها ولا قوة إلا بالله، ثم تريد العون منكم. وجزاكم الله عنها خير الجزاء؟","title":"ما واجب الأم تجاه ولدها الذي لا يصلي؟","answer":"الجواب: هذا الولد الذي ليس بمواظب على الصلاة الواجب نصيحته وتوجيهه إلى الخير، ووعظه وتذكيره، وتحذيره من غضب الله، قال الله جل وعلا في حق أهل النار: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42-43]، فترك الصلاة من أعظم الأسباب في دخول النار؛ لأن تركها كفر أكبر، قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالصلاة لها شأن عظيم، وهي عمود الإسلام، وهي الفارقة بين المسلم والكافر.\nفالواجب على كل مسلم ومسلمة قد بلغ الحلم وبلغت الحلم أن يؤدي الصلاة، وهو مأمور بها قبل أن يبلغ الحلم حتى يعتادها ويتمرن عليها، كما أمر النبي ﷺ بأن نأمر أبناءنا بالصلاة إذا بلغوا سبعاً ونضربهم عليها إذا بلغوا عشراً، وهكذا الفتيات، أما من بلغ فيجب عليه أن يصلي، وإذا تأخر عن الصلاة وجب أن يستتاب فإن تاب وإلا وجب على ولي الأمر قتله؛ لأن الصلاة أمرها عظيم، وهي الركن الثاني من أركان الإسلام. فعليك أيها الأخت في الله أن تنصحيه وأن تجتهدي في توجيهه إلى الخير، وتحذيره من مغبة عمله السيئ، فإن أصر فتبرئي منه واطلبي منه الخروج، مريه بالخروج عنك والبعد عنك حتى لا يضرك أمره وحتى لا تحل بك العقوبة وهو عندك.\nفيجب عليه أن ينصاع لأمرك وأن يتقي الله ، وأن يطيع أمره سبحانه وأمر رسوله عليه الصلاة والسلام في أداء الصلاة، فإذا لم يمتثل وأصر على عناده وكفره فإن الواجب عليك هجره وكراهة لقائه والتمعر في وجهه بالكراهة، وأمره بالخروج من بيتك وعدم اعتباره ابناً لك، لعل الله يهديه بعد ذلك، وعليك مع هذا أن تأمري من له شأن من أقاربك كأبيك أو أخيك الكبير أو أخواله الآخرين أن يوجهوه وأن ينصحوه وأن يؤدبوه إذا استطاعوا، لعل الله يهديه بأسبابهم.\nالمقدم: اللهم آمين. سماحة الشيخ بقي من وقت البرنامج ما يقرب من دقيقتين أرجو أن تتكرموا فيها بمعالجة نفسية أختنا، حيث ألحظ أن فيها الألم والحسرة لو تكرمتم؟\nالشيخ: نوصيك أيها الأخت في الله! بالصبر، فالأمر ليس إليك الأمر إلى الله، يقول الله سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، ويقول سبحانه لنبيه ﷺ: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56]، لما اجتهد في هداية عمه أبي طالب لم يتيسر له ذلك، فأنزل الله عليه سبحانه وتعالى قوله سبحانه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُُ [القصص:56] ففي هذا عزاء، وفيه تسلية لك ولأمثالك، إذا أبى ابنك أن يهتدي ولم يوافق فلك في رسول الله عليه الصلاة والسلام الأسوة الحسنة، فإذا نصحت ووجهت وأمرت فالأمر إلى الله سبحانه وتعالى.","link":"https://binbaz.org.sa/fatwas/6152/ما-واجب-الام-تجاه-ولدها-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11109.mp3","categories":["حكم الصلاة وأهميتها","تربية الأولاد"]},{"id":8413,"question":"الرسالة التالية وصلت إلى البرنامج من الكويت، وباعثها أخونا (ف. ج. ع) أخونا يسأل ويقول: إن له جداً، وهذا الجد يبلغ من العمر سبعين عاماً إلا أنه لم يصل، ماذا تقولون سماحة الشيخ؟","title":"ما واجب المسلم تجاه قريبه الذي لا يصلي؟","answer":"الجواب: الواجب نصيحة هذا الجد قبل أن ينزل به الأجل، فقد بلغ من العمر عتياً، قد كبرت سنه وهو على خطر من هجوم الأجل، فالواجب أن ينصح ويوجه إلى الخير، ويوعظ ويذكر؛ لعل الله يهديه حتى يؤدي الصلاة، فإذا تاب وصلى؛ فليس عليه قضاء ما فات، ولكن عليه البدار بالتوبة، والمسارعة إلى التوبة قبل هجوم الأجل، وعليه أن يصلي من حين يتوب إلى الله جل وعلا، عليه أن يصلي مستقبلاً، ويستغفر ربه جل وعلا عما مضى، وينبغي له أن يستكثر من العمل الصالح، والله يتوب على التائبين، كما قال الله سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] وقال : وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا [الفرقان:68]  ۝  يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا[الفرقان:69]  ۝  إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا [الفرقان:70] فعليه أن يتوب إلى الله توبةً صادقة، بالندم على ما مضى، والإقلاع من ترك الصلاة، والعزيمة أن لا يعود في ذلك، وأن يحافظ عليها في أوقاتها مع المسلمين، وعليه أن يكثر من العمل الصالح؛ لعل الله يتوب عليه، فيبدل سيئاته حسنات. نعم.","link":"https://binbaz.org.sa/fatwas/6297/ما-واجب-المسلم-تجاه-قريبه-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11804.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":8429,"question":"رسالة أخرى من أحد الإخوة أيضاً يقول جمال سعد مصلي مصري يعمل بالعراق: قد سمعت حلقة من هذا البرنامج، وأنا من يومها لا أنام، ولا أعرف طعماً لهذه الحياة، أريد حكم الإسلام فيمن تزوج امرأة وكانت لا تصلي، وأنا أيضاً كنت لا أصلي قبل زواجي، وعندما أتممنا موضوع الزواج عرفنا الله حق المعرفة، وكنا نصلي جماعة أنا وزوجتي أحياناً، وكنا في قمة الإيمان، ولكن شاء القدر أن توفيت زوجتي وأنا أدعو لها بالجنة، وحيث أنني لا أكسل عن أي فرض وجميع صلاتي جماعة، وأنجبت منها ثلاثة أطفال، فما حكم الإسلام في هذه الزوجة؟ وما حكم الإسلام معي، أرجو الرد منكم لأنني لا أعرف النوم بعد سماع تلك الحلقة؟","title":"حكم نكاح الزوجين إذا كانا تاركين للصلاة ثم تابا","answer":"الجواب: الحمد لله الذي من عليكما بالتوبة، فتبت أنت وتابت هي كذلك، وكنتما تصليان جميعاً حتى توفيت، الحمد لله، التوبة يمحو الله بها ما قبلها، كما قال الله :  وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وجعل الفلاح ناتج عن التوبة؛ فمن تاب أفلح، قال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا عَسَى رَبُّكُمْ أَنْ يُكَفِّرَ عَنْكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَاا الأَنْهَارُ... [التحريم:8] الآية، فالتوبة من أسباب محو الذنوب، ومن أسباب دخول الجنة، وقال : وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا [الفرقان:68]  ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:69]  ۝  إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًاا رَحِيمًا [الفرقان:70].\nفمن تاب توبة صادقة، واستقام على الإيمان والعمل الصالح محا الله سيئاته وأبدلها حسنات فضل منه سبحانه وتعالى، فاحمد الله يا أخي! أنك تبت وهي تابت والحمد لله، واجتهد في الدعاء لها بالمغفرة والرحمة وأنت على خير، وزواجكما صحيح؛ لأنك وإياها كنتما لا تصليان، فصلاتكما صحيحة، مثل صلاة الكفار الذين أسلموا في عهد النبي ﷺ، وأقر النبي ﷺ نكاحهم على حاله، أسلم الناس في عهده ﷺ وأقر نكاحهم على ما كان في حال كفرهم، ولم يغير نكاحهم، فأنت وهي كنتما لا تصليان، فنكاحكما صحيح؛ لأنكما على حال واحدة، فنكاحكما صحيح والحمد لله كسائر أنكحة الذين تناكحوا في الكفر ثم أسلموا، وترك الصلاة لا شك أنه كفر، ولكن الحمد لله قد تبتما والحمد لله، وهي كافرة ذاك الوقت، وأنت كذلك بترك الصلاة، في أصح قولي العلماء الذين يقولون: إن تركها كفر أكبر، وقال آخرون من أهل العلم: إن تركها كفر دون كفر، وأن تركها لا يخرج من الإسلام إذا كان تاركها مؤمناً بها وأنها حق وأنها واجبة، ولكن حمله الكسل والتهاون، فعند جمع من أهل العلم: أنه لا يكون كافراً بذلك كفراً أكبر، ولكنه يكون كافراً كفراً أصغر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، لكن الصواب والأرجح: أنه كفر أكبر، كما بينا في غير حلقة، ولكنك تزوجتها وأنت لا تصلي وهي لا تصلي فأنتما سواء، فنكاحكما صحيح والحمد لله، والتوبة صحيحة إن شاء الله ما دامت صادقة، وقد تبتما إلى الله، والله يمحو عنكما ما سبق، فنسأل الله لك ولها المغفرة والرحمة، وعليك يا أخي أن تستقيم وأن تسأل ربك الثبات على الحق حتى تموت على ذلك إن شاء الله.\nوعليك أيضاً أن تجتهد في أدائها في الجماعة، أداء الصلاة في الجماعة، مع العناية بالخشوع والإقبال عليها والاجتهاد فيها، حتى تؤديها كاملة، رزقنا الله وإياك التوفيق والهداية والثبات على الحق.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/6313/حكم-نكاح-الزوجين-اذا-كانا-تاركين-للصلاة-ثم-تابا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11906.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":8517,"question":"السائل: يقول: هذه الزوجة المعقود قراني عليها الآن لا تطيع أمري ولا تؤدي الصلاة، وكان هذا شرط لي قبل عقد القران، فبعد العقد تمردت علي، فتركتها منذ خمسة عشر شهراً، فما حكم الشرع في هذه الزوجة المتمردة علي، أفتوني؟","title":"حكم فراق الزوجة التاركة للصلاة","answer":"الجواب: التي لا تصلي لا تعتبر مسلمة بل تعتبر كافرة في أصح قولي العلماء؛ لأن ترك الصلاة كفر أكبر؛ لأنها عمود الإسلام، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وهذا يعم الرجال والنساء، والصحيح أنه كفر أكبر، هذا هو الصواب، وهو الذي أجمع عليه أصحاب النبي ﷺ، كما قال عبد الله بن شقيق العقيلي: لم يكن أصحاب رسول الله ﷺ يرون شيئاً تركه كفر إلا الصلاة هذا يدل على أنهم أجمعوا على هذا ، فالتي لا تصلي لا خير فيها، بل عليك فراقها بالكلية، الله قال: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] وقال: وَلا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ [الممتحنة:10] فهذه المرأة لا خير فيها بل يجب فراقها. نعم.\nالمقدم: جزاكم الله خير. وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6590/حكم-فراق-الزوجة-التاركة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20307.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8521,"question":"يقول: أنا متزوج اثنتين، ولكنهما لا تصليان، فقط تصومان شهر رمضان، وقد أمرتهن بالصلاة أكثر من مرة، فإحداهن صلت أياماً، وعندما رجعت من السعودية إلى مصر وجدتها قد تركت الصلاة، والثانية تقول: إنها لا تعرف شيئاً من القرآن حتى الفاتحة، فأفيدوني ماذا أفعل؟","title":"حكم الزوجة التي لا تصلي أو لا تعرف قراءة الفاتحة","answer":"الجواب: عليك أن تستتيبهما، وتبين لهما عظم شأن الصلاة وأنها عمود الإسلام، وأن تركها كفر، فإن تابتا فالحمد لله بقيتا معك، وإن لم تتوبا وجب عليك فراقهما، وسوف يعطيك الله خيراً منهما، فمن ترك شيئاً لله عوضه الله خيراً منه، والله سبحانه يقول: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] والجاهلة تعلم الفاتحة، تعلم السور القصيرة في الأوقات المناسبة التي يكون قلبها فارغاً حاضراً، تعلمها وتجتهد في ذلك، ولك أجر عظيم، وإذا عجزت عن الفاتحة، تأتي بدلاً منها بالأذكار تقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، حال قيامها في الصلاة، النبي صلى الله عليه وسلم أمر من عجز عن الفاتحة أن يأتي بهذا الذكر، فإذا عجزت تأتي بهذا الذكر، ولكن مع المحاولة إن شاء الله في الأوقات المناسبة إن شاء الله تحفظ تتعلم. نعم.\nالمقدم: جزاكم الله خير، يعني: الاستتابة لهما تكون بتأديتهما للصلاة يعني؟\nالشيخ: نعم.\nالمقدم: وإن لم تتوبا فعليه أن يفارقهما؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خير","link":"https://binbaz.org.sa/fatwas/6592/حكم-الزوجة-التي-لا-تصلي-او-لا-تعرف-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20309.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":8572,"question":"شيخ عبد العزيز اجتمع لي في هذه الحلقة ثلاث رسائل يسأل أصحابها عن تارك الصلاة: فأخونا أحمد عبد الله أحمد علي من جمهورية مصر العربية، ويقيم وقت كتابة رسالته في الطائف، أخونا يقول: سمعت في برنامج نور على الدرب المذاع في (25/ صفر / 1407هـ) من أحد المشايخ، بأنه إذا عقد المسلم عقد النكاح على إحدى الفتيات المسلمات وهي لا تصلي يكون العقد باطلاً ولو صلت بعد الزواج، وعندنا في قرى مصر 50% لا يصلون قبل الزواج، وخاصة البنات، أرجو من سماحتكم توضيحًا كاملاً لهذا السؤال، جزاكم الله خيرًا، أما أخونا (م. ل) من بنجلادش فيسأل أيضاً نفس السؤال عن أولئك الذين لا يصلون ولا سيما إذا كانوا من قرابته.ثم هناك مستمعة تقول الراسلة (ع. م) من المملكة، أختنا تسرد جملة صفات في أخت لها ومن أسوئها تركها للصلاة، ثم أيضاً تقول: إن حتى والدتها لا تصلي إلا إذا أتت عندها في البيت، كل هؤلاء يرجون سماحة الشيخ التوجيه بخصوص هذا الركن الثاني من أركان الإسلام لو تكرمتم؟","title":"القول الراجح في حكم تارك الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد دل الكتاب والسنة على أن الصلاة أهم عبادة وأعظم عبادة بعد الشهادتين، وأنها عمود الإسلام، وأن الواجب على جميع المكلفين من المسلمين المحافظة عليها، وإقامتها كما شرع الله ، كما قال : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238] الآية من سورة البقرة، وقال سبحانه أيضاً في سورة البقرة: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] وقال في سورة براءة (التوبة) لما ذكر قتال المشركين قال: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّواا سَبِيلَهُمْ [التوبة:5] فدل ذلك على أن الذي لا يصلي لا يخلى سبيله بل يقاتل، قال جل وعلا: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةََ فَإِخْوَانُكُمْ فِي الدِّينِ [التوبة:11] دل على أن من لم يصل ليس بأخ في الدين.\nوالآيات في هذا المعنى كثيرة جداً، وثبت عن رسول الله عليه الصلاة والسلام أنه قال: رأس الأمر الإسلام وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله وصح عنه أيضاً عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفرخرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة بن الحصيب ، وخرج مسلم في صحيحه عن جابر بن عبد الله رضي الله تعالى عنهما عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة والتعبير بالرجل لا يخرج المرأة فإن الحكم إذا ثبت للرجل فهو للمرأة كذلك، وهكذا ما يثبت للمرأة يثبت للرجل، إلا بدليل يخص أحدهما.\nفهذه الأحاديث وما جاء في معناها كلها تدل على أن تارك الصلاة يكون كافراً من الرجال والنساء بعد التكليف.\nوثبت في الحديث الصحيح أيضاً أن النبي ﷺ لما سئل عن الأمراء الذين لا يقيمون الدين كما ينبغي هل نقاتلهم؟ قال: لا، إلا أن تروا كفراً بواحاً عندكم من الله فيه برهان وفي لفظ آخر قال: ما أقاموا فيكم الصلاة فدل على أن من لم يقم الصلاة قد أتى كفراً بواحا.\nوقد اختلف العلماء في هذه الأحاديث، فقال بعضهم: إنها على الزجر والتحذير والترهيب وليس المراد الكفر الأكبر، بل المراد كفر دون كفر، وإلى هذا ذهب الأكثرون من الفقهاء، وقالوا: إنه كفر دون كفر.\nوذهب جمع من أهل العلم إلى أن المراد به الكفر الأكبر؛ لأن الرسول ﷺ قال: بين الرجل وبين الكفر والشرك ترك الصلاةة والكفر متى عرف، والشرك متى عرف فالمراد به الكفر الأكبر والشرك الأكبر، وقال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر فدل ذلك على أنه أراد الكفر الأكبر؛ لأنه أطلقه عليه الصلاة والسلام على أمر واضح وهو أمر الصلاة، فإن أمر الصلاة أمر عظيم وهي عمود الإسلام فكون تركها كفراً أكبر لا يستغرب؛ ولهذا ذكر عبد الله بن شقيق العقيلي التابعي الجليل عن أصحاب النبي ﷺ، قال: كان أصحاب النبي ﷺ لا يرون شيئاً تركه كفر غير الصلاة فهذا يدل على أنه يرونه الكفر الأكبر؛ لأن هناك أشياء يعرفون أنها كفر لكنها كفر دون كفر، مثل البراءة من النسب، مثل القتال قال النبي ﷺ: سباب المسلم فسوق وقتاله كفر هذا كفر دون كفر إذا لم يستحله، وهكذا قوله ﷺ: إن كفراً بكم تبرؤ من آبائكم وقوله عليه الصلاة والسلام: اثنتان في الناس هما بهما كفر: النياحة والطعن بالنسب هذا كله معناه كفر دون كفر عند أهل العلم؛ لأنه جاء منكراً ودلت الأدلة الأخرى على أن المراد به غير الكفر الأكبر.\nبخلاف الصلاة فإن أمرها عظيم، وهي أول ركن بعد الشهادتين، وهي عمود الإسلام، وقد بين الرب  لما شرع قتال الكفار قال: فَإِنْْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على أنهم لا يخلى سبيلهم وهم يتركون الصلاة، وقال ﷺ: نهيت عن قتل المصلين فدل على أن من لم يصل يقتل.\nوالخلاصة: أن القول الصواب والذي تقتضيه الأدلة هو أن ترك الصلاة كفر أكبر، ولو قال الجمهور بخلافه، فإن المناط هو الأدلة وليس المناط كثرة القائلين، الحكم معلق بالأدلة، والترجيح يكون بالأدلة، وقد قامت الأدلة على كفر تارك الصلاة كفراً أكبر.\nوأما قوله ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، فإذا قالوها عصموا مني دماءهم وأموالهم إلا بحقها فيفسره قوله في الحديث الآخر: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، وأني رسول الله ويقيموا الصلاة ويؤتوا الزكاة، فإذا فعلواا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام فلا عصمة إلا بإقامة الصلاة؛ ولأن من لم يقم الصلاة ما أدى حق التوحيد، فالمراد بقول: لا إله إلا الله وأنها تعصم من قالها إذا التزم بحقها، ومن حقها أن يؤدي الصلاة؛ ولأن الموحد الذي يقول: لا إله إلا الله إذا أتى بناقض من نواقض الإسلام لم ينفعه قول: لا إله إلا الله، فلو قال: أشهد أن لا إله إلا الله وأن محمداً رسول الله ثم جحد وجوب الصلاة كفر إجماعاً، أو جحد وجوب الزكاة كفر إجماعاً، أو جحد وجوب صوم رمضان كفر إجماعاً، أو سب الدين كفر إجماعاً، أو سب الرسول كفر إجماعاً، أو استهزأ بالدين كفر إجماعاً، ولم ينفعه قول: لا إله إلا الله، فعلم بذلك أن إتيانه بالتوحيد والشهادة للرسول ﷺ بالرسالة إنما ينفعه إذا لم يأت بناقض من نواقض الإسلام، فأما إذا أتى بناقض من نواقض الإسلام فإنه لا تنفعه الشهادة، كالأمثلة التي ذكرنا، كسب الدين، كالاستهزاء بالدين، كجحد وجوب الصلاة، كجحد وجوب الزكاة، كالاستهزاء بدين الله.\nولو أن إنساناً يشهد أن لا إله إلا الله، وأن محمداً رسول الله، ويصلي ويصوم ويتعبد ثم جحد تحريم الزنا، قال: الزنا حلال، كفر عند جميع المسلمين، أو قال: إن الخمر حلال كفر عند جميع المسلمين، أو قال: إن اللواط حلال كفر عند جميع المسلمين، أو بال على المصحف متعمداً أو وطئه برجله متعمداً استهانة له، أو جلس عليه استهانة له كفر عند جميع المسلمين، باستهانته بكتاب الله، ولم ينفعه شهادة أن لا إله إلا الله، وأن محمداً رسول الله، فكيف يستنكر أن يكون كافراً بترك الصلاة إذا تركها وتساهل بها، وهي أعظم أركان الدين وأهمها بعد الشهادتين؟\nليس هذا بمستغرب؛ ولهذا القول الصواب أن المسلم إذا تزوج امرأة لا تصلي فالنكاح باطل، وهكذا إذا تزوجت المسلمة إنساناً لا يصلي فالنكاح باطل، فمتى تاب إلى الله جدد العقد، متى تاب الذي لا يصلي يجدد العقد.\nأما إذا كانا جميعاً لا يصليان فالنكاح صحيح، لأنهما كافران جميعاً، نسأل الله السلامة، ونسأل الله للجميع الهداية والتوفيق نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6652/القول-الراجح-في-حكم-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_128/12801.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":8591,"question":"سماحة الشيخ! إذا ابتلي الإنسان بمثل من ذكر في الرسائل والدة لا تصلي، أو أخت، أو حتى أنساب أو إخوة، كيف يتصرف؟","title":"ما الواجب تجاه من يترك الصلاة من الأقارب؟","answer":"الجواب: الواجب نصيحتهم وتخويفهم من الله عز وجل تحذيرهم من مغبة أعمالهم الخبيثة، فإن تابوا فالحمد لله وإلا وجب هجرهم، لا يزارون ولا تجاب دعوتهم، ولا يدعون إلى وليمة ولا غيرها بل يهجرون حتى يتوبوا إلى الله، هكذا ذكر أهل العلم، يجب هجرهم؛ لأنهم أتوا منكراً عظيماً حتى يوفق الله ولاة الأمور لإقامة الحد عليهم باستتابتهم، فإن تابوا وإلا وجب على ولي الأمر قتلهم، وهذا لا إشكال فيه وهو الذي عليه جمهور أهل العلم، أن من لم يتب يقتل، إذا ترك الصلاة واستتيب ولم يتب فإنه يقتل لقوله سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على أن الذي لا يصلي لا يخلى سبيله؛ ولقوله ﷺ: إني نهيت عن قتل المصلين فدل على أن من لا يصلي لا يترك بل يقتل إذا لم يتب، في أدلة كثيرة دلت على هذا المعنى. نعم.\nأما الوالدة فلها شأن، الوالدة والوالد لهما شأن، يجتهد في نصيحتهما ولكن لا يهجرهما، الوالدان لهما حق عظيم ولو كانا كافرين؛ لأن الله قال جل وعلا في حق الوالدين الكافرين: وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَاثم قال بعدها: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فأمر بمصاحبتهما في الدنيا معروفاً مع أنهما كافران، وما ذاك إلا لعظم حق الوالدين، فالولد إذا كان أبوه لا يصلي أو أتى بكفر آخر أو أمه كذلك فإنه ينصحهما كثيراً ولا يقطعهما بل يحسن إليهما، ويجتهد في دعوتهما إلى الخير والإسلام والاستقامة لعل الله يهديهما بأسبابه، وبكل حال يتلطف معهما، ويحسن إليهما ويدعوهما إلى الخير، حتى يموتا أو يهديهما الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6697/ما-الواجب-تجاه-من-يترك-الصلاة-من-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_128/12802.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":8592,"question":"سماحة الشيخ أخونا من جمهورية مصر العربية أحمد عبد الله أحمد علي يقول: إن عندهم في قرى مصر 50% لا يصلون قبل الزواج وخاصة البنات، نسبة كبيرة سماحة الشيخ، ولاسيما أنه يقول إنهن مسلمات.","title":"ما الحكم إذا كان أحد الزوجين لا يصلي أو كلاهما؟","answer":"","link":"https://binbaz.org.sa/fatwas/6698/ما-الحكم-اذا-كان-احد-الزوجين-لا-يصلي-او-كلاهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_128/12803.mp3","categories":["حكم الصلاة وأهميتها","شروط وأركان الزواج"]},{"id":8653,"question":"هذه رسالة وردتنا من السائل محمد السيد أحمد ، من مصر يسكن في العراق يقول في رسالته: أنا أعمل في العراق وأقوم من الصباح ولا أرجع إلا بعد المغرب، ولا يظل عندي وقت لأجل أن أصلي، ومكان الماء بارد جداً ولا أستطيع الوضوء فأؤجل الصلاة، فما الحكم في ذلك؟","title":"حكم من يؤجل الصلاة بسبب العمل أو برودة الماء","answer":"الجواب: الواجب على المسلم أن يتقي الله أينما كان، وأن يذكر أنه موقوف بين يديه سبحانه ومسئول يوم القيامة عما قصر فيه وعما ارتكبه من حرام وعما ضيعه من واجب، والله يقول سبحانه: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا لا يَجْزِي وَالِدٌ عَنْ وَلَدِهِ وَلا مَوْلُودٌ هُوَ جَازٍ عَنْ وَالِدِهِ شَيْئًا إِنَّ وَعْدَ اللَّهِ حَقٌّ فَلا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا وَلا يَغُرَّنَّكُمْ بِاللَّهِ الْغَرُورُ [لقمان:33] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ [الحشر:18] والصلاة هي عمود الإسلام، وهي أعظم واجب بعد الشهادتين، فلا يجوز للمسلم أن يضيعها في الوقت من أجل حظه العاجل ودنياه العاجلة.\nفيجب عليك -أيها السائل- أن تصلي الصلوات في أوقاتها، وليس لك تأخيرها من أجل أعمالك الدنيوية، بل عليك أن تصليها حسب الطاقة، فإذا استطعت أن تتوضأ بالماء ووجدت ماءً تستطيع الوضوء به ولو بالتسخين وجب عليك ذلك، فإن لم تجد إلا ماءً قد تناهى في البرودة لا تستطيع الوضوء به ولا تستطيع تسخينه بالنار فعليك أن تصلي بالتيمم في الوقت وليس لك التأجيل، عليك أن تصلي في الوقت ولو بالتيمم عند العجز عن الماء كالمسافر الذي يكون في البر ليس عنده ماء يتيمم ويصلي.\nأما تأجيل الصلاة من أجل الرفاهية أو من أجل الحظ العاجل من الدنيا والأعمال الدنيوية فهذا منكر عظيم وفساد كبير وخطر عظيم لا يجوز للمسلم فعله أبداً. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6789/حكم-من-يوجل-الصلاة-بسبب-العمل-او-برودة-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21304.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8684,"question":"يسأل أيضاً ويقول: يسكن معي بالمنزل شقيقي وهو لا يصلي ويسب الدين، وقد تحدثت معه عدة مرات وقدمت له النصح فأعرض عنه، وقال لي أخيراً -بعد أن ضايقته بالكلام-: لن أصلي أبداً حتى الموت، فهل يجوز لي أن آكل معه بعد ذلك وأن أتعامل معه، والذي أخشى أن يكون هذا العصيان سبب في هلاكه، وما هي الوسيلة التي أحارب بها مثل هذا التصرف مع هذا الأخ، جزاكم الله خير؟","title":"حكم من كان له أخ لا يصلي ويسب الدين","answer":"الجواب: الواجب عليك نصيحته وتحذيره من مغبة عمله، وأن تبين له أن ما فعله ردة عن الإسلام، فإن سب الدين ردة عن الإسلام بإجماع المسلمين، وكذلك ترك الصلاة ردة عن الإسلام في أصح قولي العلماء، فإن كان يجحد وجوبها كان كافراً بالإجماع، وإن كان لا يجحد وجوبها ولكنه يتكاسل ولا يبالي فهو كافر في أصح قولي العلماء، لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة رضي الله عنه، وروى مسلم في صحيحه عن جابر ، عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فالذي لا يصلي ومع هذا -والعياذ بالله- يصمم أنه لا يصلي حتى الموت هذا يظهر منه أنه لا يرى وجوبها وأنه جاحد لوجوبها، فهو كافر بلا شك حتى ولو زعم أنه لا يجحد وجوبها، لهذه الأحاديث ولما جاء في معناها، وإذا كان يسب الدين صار كفره أعظم وصارت ردته أشد والعياذ بالله.\nفالواجب عليك مفارقته ومعاداته في الله، والبراءة منه وأن لا تصاحبه، وأن لا تكلمه، وأن لا تأكل معه، بل تهجره، وتخرجه من بيتك، لا تسكن معه، إن كان البيت له فاخرج عنه، وإن كان بيتك فاطرده عنك لأنه نجس خبيث، فلا ينبغي لك أن يبقى معك، بل تطرده إن كان في بيتك أو تخرج من بيته إن كان البيت له، وتسأل الله له الهداية بينك وبين ربك لعل الله يهديه بأسبابك، وأما البقاء معه فلا أبداً، لا يصاحب ولا تؤكل وليمته ولا تجاب دعوته ولا يبقى معك في محلك؛ لأنه خبيث الحال نجس المقال والعقيدة فينبغي لك أن تحاربه وأن تبتعد عنه.\nوإذا كانت البلاد فيها حكم إسلامي يرفع بأمره إلى ولي الأمر، حتى يستتاب فإن تاب وإلا يقتل؛ لأن الله يقول سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على أن الذي لا يصلي لا يخلى سبيله، بل يقتل إن لم يتب، نسأل الله له الهداية، نسأل الله له الهداية، ونسأل الله لك العون عليه بالحق والصدق والهدى. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6826/حكم-من-كان-له-اخ-لا-يصلي-ويسب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21513.mp3","categories":["حكم الصلاة وأهميتها","نواقض الإسلام"]},{"id":8716,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من القصيم - عنيزة باعثتها إحدى الأخوات من هناك تقول: (م. س. ج) أختنا تسأل سؤالاً هام فيما أرى سماحة الشيخ تقول: هل صحيح أن عدم ذهاب الرجل للصلاة مع الجماعة سبب في نزع البركة من حاله وماله؟ وما الدليل على ذلك؟","title":"ما حكم التهاون بصلاة الجماعة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن الصلاة هي عمود الإسلام وهي أعظم الواجبات والفرائض بعد الشهادتين، وقد دل على ذلك آيات كثيرات وأحاديث صحيحة عن رسول الله عليه الصلاة والسلام، فمن ذلك قوله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ[البقرة:238].\nوقوله سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43].\nوقوله سبحانه: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45].\nوقوله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] إلى أن قال: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:9-11].\nوقال تعالى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ [البينة:5] فجعلها قرينة التوحيد وَمَاا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [البينة:5] هذا هو التوحيد، وهذا هو معنى لا إله إلا الله، ثم قال بعده: وَيُقِيمُواا الصَّلاةَ[البينة:5].\nوقال سبحانه: فَإِنْ تَابُوا [التوبة:5] يعني: من الشرك وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على عظمتها وأنها قرينة التوحيد.\nوقال سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَإِخْوَانُكُمْ فِي الدِّينِ [التوبة:11].\nوقال النبي ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأني رسول الله ويقيموا الصلاة ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام ومن أهم واجباتها وأعظم واجباتها أداؤها في الجماعة في حق الرجل حتى أوجبها الرب سبحانه في حال الخوف، قال جل وعلا: وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ الصَّلاةَ فَلْتَقُمْ طَائِفَةٌ مِنْهُمْ مَعَكَ وَلْيَأْخُذُوا أَسْلِحَتَهُمْ فَإِذَا سَجَدُواا فَلْيَكُونُوا مِنْ وَرَائِكُمْ وَلْتَأْتِ طَائِفَةٌ أُخْرَى لَمْ يُصَلُّوا فَلْيُصَلُّوا مَعَكَ وَلْيَأْخُذُوا حِذْرَهُمْ وَأَسْلِحَتَهُمْ [النساء:102] الآية، فأوجب صلاة الجماعة في حال الخوف وفي حال مصافة المسلمين لعدوهم الكافر فأمرهم أن يصلوا جماعة وأن يحملوا السلاح لئلا يحمل عليهم العدو.\nوقال عليه الصلاة والسلام: من سمع النداء فلم يأت فلا صلاة له إلا من عذر وأتاه ﷺ رجل أعمى فقال: يا رسول الله! إنه ليسس لي قائد يلائمني إلى المسجد فهل لي من رخصة أن أصلي في بيتي؟ فقال المصطفى عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟؟ قال: نعم. قال: فأجب خرجه مسلم في صحيحه، فهذا رجل أعمى لم يأذن له النبي ﷺ في التخلف عن الجماعة، وفي اللفظ الآخر قال: لا أجد لك رخصة فصرح أنه ليس له رخصة وهو أعمى ليس له قائد يلائمه يعني: يحافظ على الذهاب معه، فإذا كان الرجل الأعمى الذي ليس له قائد يعتني به ويحافظ عليه ليس له رخصة بل عليه أن يذهب ويتحرى ويجتهد حتى يصل المسجد، فكيف بحال القوي المعافى فالأمر في حقه أعظم وأكبر.\nثم التخلف عن صلاة الجماعة من أعظم الوسائل في التهاون بها وتركها بعد ذلك، فإنه اليوم يتخلف وغداً يترك ويضيع الوقت؛ لأن قلة اهتمامه بها جعلته يتخلف عن أدائها في الجماعة وفي المساجد التي هي بيوت الله والتي قال فيها سبحانه: فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ [النور:36] وهي المساجد.\nوهذا أمر مجرب فإن الذين يتخلفون عن الجماعة يسهل عليهم ترك الصلاة بأدنى عذر وبأقل سبب، ثم بعد ذلك يتركونها بالكلية لقلة وقعها في صدورهم، ولقلة عظمتها في قلوبهم فيتركونها بعد ذلك، فترك الصلاة في الجماعة وسيلة غريبة وذريعة معلومة لتركها بالكلية، وقد قال عليه الصلاة والسلام في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد في المسند و أبو داود و الترمذي و النسائي و ابن ماجة بإسناد صحيح عن بريدة بن الحصيب .\nوخرج مسلم في الصحيح عن جابر بن عبد الله الأنصاري رضي الله تعالى عنهما عن النبي ﷺ أنه قال: بين الرجل وبين الكفرر والشرك ترك الصلاة وهذا يدل على أنه كفر أكبر قال: الكفر والشرك، فأتى بالكفر المعرف والشرك المعرف، وهذا دليل على أن المراد به الكفر الأكبر، وإن كان بعض أهل العلم رأى أنه كفر دون كفر إذا كان غير جاحد لوجوبها بل يعلم أنها واجبة ولكن تساهل، فقد ذهب جمع كبير من أهل العلم حكاه بعضهم قول الأكثرين: أنه كفر دون كفر، وأنه لا يكفر بذلك الكفر الأكبر لكن الصحيح الذي قامت عليه الأدلة أنه كفر أكبر وهو ظاهر إجماع الصحابة قبل من خالفهم بعد ذلك.\nوقد حكى عبد الله بن شقيق العقيلي التابعي الجليل الثقة عن أصحاب النبي ﷺ: أنهم كانوا لا يرون شيئاً تركه كفر إلا الصلاة. فعندهم الصلاة تركها كفر، ومراده كفر أكبر؛ لأن هناك أشياء عملها كفر لكن ليس هو الكفر الأكبر، مثل الطعن في الأنساب والنياحة على الأموات سماها النبي ﷺ كفر، والصحابة يسمونها كفر لكنه كفر أصغر، فلما أخبر عنهم أنهم لا يرون شيئاً تركه كفر إلا الصلاة علم أنه أراد بذلك كفر أكبر كما جاء به الحديث.\nوأما كون هذه المعصية تسبب محق البركة وتسبب أيضاً شراً كثيراً عليه في بدنه وفي تصرفاته فهذا لا يستغرب، فإن المعاصي لها شؤم كثير ولها عواقب وخيمة في نفس الإنسان وفي قلبه وفي تصرفاته وفي رزقه فلا يستغرب هذا، وقد دلت الأدلة على أن المعاصي لها عواقب وخيمة، وقد قال النبي ﷺ في الحديث الصحيح: إن العبد ليحرم الرزق بالذنب يصيبه.\nومعلوم أن المعاصي تسبب الجدب في الأرض ومنع المطر وحصول الشدة، وهذا كله بأسباب المعاصي كما قال : وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ [الشورى:30] وقال سبحانه: مَا أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ اللَّهِ وَمَا أَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْْ نَفْسِكَ [النساء:79] هذا أمر معلوم بالنصوص وبالواقع، فجدير بالمؤمن أن يحذر مغبة المعاصي وشرها وأن يتباعد عنها وأن يحرص على أداء ما أوجب الله عليه وعلى المسارعة إلى الطاعات فهي خير في الدنيا والآخرة، الطاعات كلها خير في الدنيا والآخرة، والمعاصي شر في الدنيا والآخرة، رزق الله الجميع العافية والسلامة.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6866/ما-حكم-التهاون-بصلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_134/13401.mp3","categories":["صلاة الجماعة","حكم الصلاة وأهميتها"]},{"id":8858,"question":"نعود في بداية لقائنا إلى رسالة الأخ المعلم السوداني من اليمن (ق. ع. س.) عرضنا معظم أسئلته في حلقة مضت وفي هذه الحلقة له سؤال يقول: سمعت في البرنامج أن تارك الصلاة تهاوناً كافراً كفراً مخرجاً من الملة، ولكن الشافعية يقولون في كتاب النفحات الصمدية: إنه -أي: تارك الصلاة- يستتاب ويقتل ويصلى عليه ويغسل ويدفن في مقابر المسلمين، فما رأي سماحتكم وجزاكم الله خير الجزاء؟","title":"حكم تارك الصلاة تهاوناً","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد علم أن ترك الصلاة تهاوناً من أكبر الكبائر ومن أعظم الجرائم؛ لأن الصلاة عمود الإسلام والركن الأعظم بعد الشهادتين فلهذا صار تركها من أقبح القبائح ومن أكبر الكبائر.\nواختلف العلماء رحمة الله عليهم في حكم تاركها هل يكون كافراً كفراً أكبر، أو يكون حكمه حكم أهل الكبائر؟ على قولين لأهل العلم فمنهم من قال: إنه يكون كافراً كفراً أصغر كما ذكره السائل عن الشافعية وهكذا عن المالكية و الحنفية وبعض الحنابلة، وقالوا: إن ما ورد في تكفيره يحمل على أنه كفر دون كفر وتعلقوا بالأحاديث الدالة على أن من مات على التوحيد وترك الشرك فله الجنة، وهذا موحد مات على توحيد الله فلا يكون كافراً كفراً أكبر.\nأما إذا جحد وجوبها قال: إنها غير واجبة، فهذا قد أجمع العلماء على كفره إذا اعتقد أنها غير واجبة وقال: أنها لا تجب من شاء صلى ومن شاء ترك، فهذا قد أجمع علماء المسلمين على أنه كافر كفراً أكبر عند الشافعية والحنبلية والمالكية والحنفية وغيرهم من أهل العلم وإنما الخلاف فيما إذا تركها تهاوناً فقط وهو يؤمن بوجوبها.\nوقال بعض أهل العلم: إنه يكون كافراً كفراً أكبر وهو المنقول عن الصحابة عن أصحاب النبي ﷺ فإنه ثبت من حديث عبد الله بن شقيق العقيلي التابعي الجليل قال: لم يكن أصحاب رسول الله ﷺ يرون شيئاً تركه كفر غير الصلاة ومعلوم أنهم يرون أن الطعن في الأنساب والنياحة على الميت نوع من الكفر، والبراءة من الأنساب نوع من الكفر لكنه كفر أصغر، فعلم أن مراده بذلك أن ترك الصلاة كفر أكبر ليس من جنس ما ورد في النصوص تسميته كفراً وهو كفر أصغر.\nواحتجوا أيضاً بما ثبت في صحيح مسلم عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة، واحتجوا أيضاً بما رواه الإمام أحمد و أبو داود و الترمذي و النسائي و ابن ماجة بإسناد صحيح عن بريدة بن الحصيب رضي الله عنه عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وبقوله ﷺ لما سئل عن الأئمة الذين يتركون بعض ما أوجب الله ويتعاطون بعض ما حرم الله سأله السائل عن قتالهم قال: لا، ما أقاموا فيكم الصلاة، وفي اللفظ الآخر: إلا أن تروا كفراً بواح.\nفدل ذلك على أن ترك الصلاة كفر بواح فيه أدلة أخرى، وهذا هو القول الصواب وإن كان القائلون به أقل من القائلين بأنه كفر أصغر لكن العبرة بالأدلة لا بكثرة الناس، يقول الله : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]، ويقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10].\nفالأدلة الشرعية قائمة على أن تركها كفر أكبر ولو كان ذلك تهاوناً من غير جحد للوجوب، وأما ما يتعلق بالموت على التوحيد فيقال: إن من ترك الصلاة ما يكون مات على التوحيد بل يكون مات على الكفر، قوله ﷺ: أمرت أن أقاتل الناس حتى يقولوا: لا إله إلا الله فإذا قالوها عصموا مني دماءهم وأموالهم إلا بحقها والصلاة من حقها.\nويدل على هذا قوله في الحديث الآخر في الصحيحين يقول ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأني رسول الله ويقيموا الصلاة ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله، ويقول جل وعلا عن أهل النار: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ ۝ وَلَمْ نَكُ نُطْعِمُ الْمِسْكِينَ ۝ وَكُنَّا نَخُوضُ مَعَ الْخَائِضِينَ ۝ وَكُنَّا نُكَذِّبُ بِيَوْمِ الدِّينِ [المدثر:42-46].\nفذكر من موجبات دخولهم النار تركهم الصلاة ذكر أن من موجبات دخولهم النار تركهم الصلاة، نسأل الله العافية، فالواجب على أهل الإسلام من الرجال والنساء الحذر من ترك الصلاة تهاوناً أو جحداً لوجوبها، ومن جحد وجوبها كفر إجماعاً ومن تركها تهاوناً وتساهلاً بها كفر في أصح قولي العلماء، فالواجب الحذر، نسأل الله للمسلمين العافية والسلامة. نعم. المقدم: إذاً ما قيل في البرنامج هو الصحيح وهو الراجح؟\nالشيخ: نعم، هو الصواب. نعم.\nالمقدم: بارك الله فيكم. سماحة الشيخ بالنسبة للمتأولين عن علم أو عن غير علم كقولهم مثلاً: الجمعة إلى الجمعة ورمضان إلى رمضان والعمرة إلى العمرة كفارة لما بينهما، بعضهم مثلاً نوقش في موضوع الصلاة فقال: إن رسول الله ﷺ يقول: الجمعة إلى الجمعة كفارة لما بينهما، أرجو من سماحة الشيخ توجيه الناس في فهم النصوص وكيف يجب عليهم تجاه النصوص التي فيها مثل هذه القواعد.\nالشيخ: يقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، كفارة لما بينهما إذا اجتنب الكبائر، هكذا جاء الحديث: إذا اجتنب الكبائر وترك الصلاة من أكبر الكبائر حتى على القول بأنها ليس تركها كفراً أكبر فتركها من أكبر الكبائر.\nوفي لفظ آخر قال: ما لم تغش الكبائر فمن أتى الكبائر لم تكفر عنه الصلاة ولا الصوم ولا الزكاة ولا الجمعة ولا غير ذلك، ولهذا قال جمهور أهل العلم: إن أداء الفرائض وترك الكبائر يكفر السيئات الصغائر، أما الكبائر فلا يكفرها إلا التوبة إلى الله سبحانه وتعالى، ولهذا قال جل وعلا: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] يعني: الصغائر وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31]، فإذا سمعت النصوص التي فيها ذكر تكفير السيئات ببعض الأعمال الصالحة فاعرف أن هذا بشرط اجتناب الكبائر.\nالمقدم: بشرط.\nالشيخ: اجتناب الكبائر، مثل قوله ﷺ: العمرة إلى العمرة كفارة لما بينهما، وقوله: من حج هذا البيت فلم يرفث ولم يفسق رجع كيوم ولدته أمه، يعني: إذا ترك المعاصي ترك الكبائر، ولهذا قال: لم يرفث ولم يفسق، وهكذا قوله: والحج المبرور ليس له جزاء إلا الجنة، المبرور ليس معه إصرار على الكبائر، وهكذا بقية الأعمال التي يعلق فيها الرسول ﷺ تكفير السيئات بالعمل الصالح يعني: عند اجتناب الكبائر، كقوله ﷺ: إن صوم يوم عرفة يكفر السنة التي قبله والتي بعده، يعني: عند اجتناب الكبائر، هكذا قوله ﷺ في صوم يوم عاشوراء إنه يكفر السنة التي قبله يعني: عند اجتناب الكبائر؛ لقوله سبحانه وتعالى: إِنْ تَجْتَنِبُواا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31]، ولقوله ﷺ: الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان كفارات لما بينهن ما لم تغش الكبائر، إذا اجتنب الكبائر، ما اجتنبت الكبائر ألفاظ جاءت في الحديث عن النبي ﷺ، ولما ذكر الوضوء عليه الصلاة والسلام وأن من توضأ نحو وضوئه ﷺ غفر له قال: ما لم تصب المقتلة قال العلماء: والمقتلة هي الكبيرة يعني عند اجتناب الكبائر، نسأل الله السلامة والعافية. نعم.\nالمقدم: جزاكم الله خيراً. هذه الكبائر التي لا يكفرها إلا الإقلاع عنها حبذا لو تكرمتم بذكر بعض منها وأخطرها سماحة الشيخ؟\nالشيخ: هذه المعاصي العظيمة الكبيرة، المعاصي العظيمة التي جاء فيها الوعيد إما بغضب أو لعنة أو نار أو جاء فيها حد في الدنيا كالسرقة، والزنا، وشرب المسكر، وعقوق الوالدين، وقطيعة الرحم، وأكل الربا، وأكل أموال اليتامى، وقذف المحصنات الغافلات المؤمنات، والقتل للنفس بغير حق، وأشباه ذلك مما جاءت فيه النصوص بالوعيد إما بغضب من الله على فاعله أو لعنة أو وعيد من نار أو حد في الدنيا كحد السرقة والزنا ونحو ذلك، هذه الكبائر في أرجح أقوال أهل العلم أن الكبيرة ما كان فيه حد في الدنيا أو جاء فيه وعيد بنار أو غضب أو لعن.\nوقال بعض أهل العلم: يلحق بذلك المعاصي التي ينفى الإيمان عن صاحبها، أو يتبرأ منه النبي ﷺ فإنه تلحق بالكبائر، كقوله ﷺ: أنا بريء من الصالقة والحالقة والشاقة يعني: عند المصيبة، الصالقة: التي ترفع صوتها عند المصيبة عند موت أبيها أو أخيها، والحالقة: التي تحلق شعرها أو تنتفه، والشاقة: التي تشق ثوبها.\nوفي اللفظ الآخر: ليس منا من شق الجيوب أو ضرب الخدود أو دعا بدعوى الجاهلية، فهذا يدل على أن هذه من الكبائر عند جمع من أهل العلم لأجل هذا الوعيد (ليس منا) (أنا بريء) ونفي الإيمان مثل قوله ﷺ: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه، وقوله ﷺ: والله لا يؤمن! والله لا يؤمن! قيل: من يا رسول الله؟ قال: من لا يأمن جاره بوائقه يعني: ظلمه وعدوانه، وما أشبه ذلك من النصوص.\nهذا يقول بعض أهل العلم: إنها أيضاً تلحق بالكبائر، إذا نفي الإيمان عن صاحبه أو تبرأ منه النبي ﷺ أو قال فيه: (ليس منا)، فيلحق بالذنوب التي فيها اللعنة أو الغضب أو الوعيد بالنار أو فيها الحد؛ حد السرقة وحد الزنا وحد القذف ونحو ذلك. نعم.\nالمقدم: بارك الله فيكم، لا أدري عن السحر عن الغيبة عن النميمة سماحة الشيخ هل تلحق بالكبائر أو لا؟\nالشيخ: السحر كفر أكبر؛ لأنه لا يتوصل إليه إلا بالشرك بعبادة الجن ودعوتهم من دون الله، ولهذا قال سبحانه في السحر عن الملكين: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] فجعلوا تعليم السحر وتعلمه كفر نسأل الله العافية، وقال في هذه الآيات سبحانه وتعالى: وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ [البقرة:102] يعني: السحر مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ [البقرة:102] أي: من حظ ولا نصيب، وقال: وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:103]، فدل على أنه ضد الإيمان وضد التقوى نسأل الله العافية.\nفالسحر يتوصل إليه بعبادة الشياطين عبادة الجن من دون الله، والتقرب إليهم بالذبائح والنذور ونحو ذلك، فلهذا روي عنه ﷺ أنه قال: من سحر فقد أشرك، وقال عليه الصلاة والسلام: اجتنبوا السبع الموبقات. قلنا: وما هن يا رسول الله؟ قال: الشرك بالله، والسحر، وقتل النفس التي حرم الله إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات الغافلات المؤمنات رواه البخاري و مسلم في الصحيحين.\nفجعل السحر قرين الشرك وقدمه على القتل؛ لأنه ضرب من الشرك وعبادة للجن من دون الله والتقرب إليهم مما يريدون منه من دعاء أو استغاثة أو ذبح أو نذر حتى يعلموه بعض الشيء، وهو من طريق الشياطين كما قال سبحانه: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102] فجعل تعليمهم الناس السحر كفراً وضلالاً نسأل الله العافية.\nوكذلك الغيبة والنميمة من الكبائر لما جاء فيهما من الوعيد، والغيبة: ذكر الإنسان أخاه بما يكره؛ بخيل.. جبان.. شرس الأخلاق.. كذا كذا وكذا، والنميمة: نقل الكلام الذي يسبب الفتنة من شخص إلى شخص، أو من جماعة إلى جماعة، أو من قبيلة إلى قبيلة، كأن يقول: سمعت فلان يقول فيكم كذا أنكم بخلاء أنكم جبناء، أو يقول لزيد: سمعت فلان يقول فيك: إنك زناء أنك خبيث أنك جبان أنك تتبع مواقف التهم أنك .. يعني: يأتي بأشياء تسبب الفتنة بينه وبين المنقول عنه، هذه هي النميمة، والله يقول سبحانه: وَلا تُطِعْ كُلَّ حَلَّافٍ مَهِينٍ ۝ هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ [القلم:10-11]، ويقول الله جل وعلا: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] ويقول النبي ﷺ لما سئل عن الغيبة قال: ذكرك أخاك بما يكره قيل: يا رسول الله! إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول فقد اغتبته وإن لم يكن فيه فقد بهته، فصار المغتاب على شر إن صدق فهو مغتاب وإن كذب فهو باهت.\nوقال ﷺ: رأيت ليلة أسري بي رجالاً لهم أظفار من نحاس يخمشون بها وجوههم وصدورهم، فقلت: من هؤلاء؟ فقيل لي: هؤلاء الذي يأكلون لحوم الناس ويقعون في أعراضهم، فهذا يدل على شدة الوعيد في هذا وأنها من الكبائر، وقال عليه الصلاة والسلام: لا يدخل الجنة نمام متفق على صحته، فدل ذلك على أن النميمة والغيبة من الكبائر نسأل الله العافية.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7013/حكم-تارك-الصلاة-تهاونا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_137/13701.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":8901,"question":"هنا رسالة من السودان وباعثها أحد الإخوة من هناك يسأل في الواقع عن زوجته، أخونا يقول: إنه متزوج وزوجته لم تعرف ولا شيئًا من القرآن الكريم، ولم تقم الصلاة، وقد حاول فيها منذ عشر سنوات لكنها لم تستجب حتى الآن، ثم يقول أيضًا: إنها لا تلبس الزي الإسلامي، ولم تقبل له أي نصح أو توجيه حول هذا الموضوع وهو يستشير سماحتكم في أمرها؟","title":"حكم الزوجة التي لا تصلي ولا تلتزم بالحجاب","answer":"فالحاصل أن هذه المرأة علاوة على أنها لا تصلي مع ذلك أيضًا لا تلبس الزي الإسلامي؛ فهذا يدل على مرض في قلبها يميلها إلى الكفرة وزي الكفرة.\nفنصيحتي لك -أيها السائل- فراقها مادمت معها من مدة طويلة عشر سنين وأنت لم تنجح في نصيحتها ولا في توجيهها إلى الخير فماذا ترجو من ورائها؟ النساء كثير والحمد لله وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] ففارقها وأبشر بالخير العظيم والعاقبة الحميدة، ومع هذا تسأل الله لها الهداية، نسأل الله لنا ولها الهداية، وإن نصحتها آخر شيء وبينت لها أنها إن لم تستجب فإنك سوف تفارقها فهذا لعله يجدي فيها بعض الشيء.\nالمقدم: بارك الله فيكم يذكر ارتباطه بالأولاد سماحة الشيخ.\nالشيخ: هو أحق بأولاده لا حضانة لها، مادامت بهذه الصفة لا حضانة لها هو أولى بأولاده بكل حال، هو أولى بأولاده وبقاء أولاده عندها يضرهم وربما جرتهم إلى شر كثير، فالحاصل أن المسلم هو أولى بأولاده مطلقا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7057/حكم-الزوجة-التي-لا-تصلي-ولا-تلتزم-بالحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_168/16803.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8914,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المنطقة الشرقية الخبر، باعثتها إحدى الأخوات من هناك تقول: (أ. م) أختنا تقول: أمي حلفت بالله على شيء، ولكنها رجعت ففعلت، فأخرجت كفارة اليمين خمسين ريالًا وأعطتها أخاها؛ لأنه فقير وخال من العمل، ولكنها لا تصلي، فهل كفارتها صحيحة؟ وإذا كانت غير صحيحة فماذا تفعل؟","title":"حكم كفارة اليمين لتارك الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الله  قد أوضح الكفارة -أعني: كفارة اليمين- في كتابه الكريم، حيث قال سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] .. الآية، فقد أوضح سبحانه كفارة اليمين، وأنها إطعام عشرة مساكين من أوسط ما يطعمه الإنسان أهله، أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ، يعني: عتق رقبة، فَمَنْ لَمْ يَجِدْ ذلك يعني: كان فقيرًا لا يستطيع صام ثلاثة أيام، وبناء على هذا فالذي أخرجته أم السائلة وهو خمسون درهمًا عن كفارة اليمين لا تجزئ؛ لأنه خلاف ما شرعه الله، فلابد من التكفير بما شرعه الله، فعليها أن تخرج الكفارة لعشرة من الفقراء المسلمين، وهي خمسة آصع من الرز أو التمر أو الحنطة لكل واحد نصف الصاع، يعني: كيلو ونصف تقريبًا، وإن عشتهم شيئ مصنوع مطبوخ أو غدتهم كفى ذلك، وإن كستهم على قميص قميص أو إزار ورداء كفى ذلك.\nأما كونها لا تصلي فهذا منكر عظيم، وكفر شنيع، فالواجب عليها التوبة إلى الله سبحانه، والرجوع إليه جل وعلا والندم على ما مضى، والإقلاع من ذلك، والبدار إلى التوبة إلى الله مع فعل الصلاة؛ لأن الصلاة عمود الإسلام، وأعظم أركانه بعد الشهادتين، فمن تركها فقد ترك عمود الإسلام، ومن ترك ذلك كفر كفرًا أكبر في أصح قولي العلماء، وإن كانت تجحد وجوب ذلك أو تستهزئ بالصلاة أو بأهلها كان كفرها كفرًا إجماعيًا بين أهل العلم جميعًا، نسأل الله السلامة.\nوقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة ، وفي صحيح مسلم عن جابر بن عبدالله الأنصاري  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة والمراد: جنس المكلف رجل أو امرأة؛ لأن أحكام الشرع تعم الجميع، فهذا يدل على أن من ترك الصلاة وإن لم يجحد وجوبها يكون كافرًا كفرًا أكبر؛ لأن المصطفى عليه الصلاة والسلام قال: بين الرجل وبين الكفر والشرك... وهذا كفر معرف، وشرك معرف؛ فهو الشرك الأكبر، والكفر الأكبر نسأل الله العافية.\nفالواجب على أمك -أيها السائلة- أن تتوب إلى الله توبة صادقة، وأن تبادر بذلك، والتوبة الصادقة تشمل أمورًا ثلاثة: الندم على الماضي، والحزن على الماضي.\nوترك المعصية والإقلاع منها.\nوالثالث: العزم الصادق على عدم العودة.\nوإذا كانت المعصية تتعلق بأمور الناس فلابد من إعطائهم حقوقهم أو تحلله منها، كما قال عليه الصلاة والسلام: من كان عنده مظلمة لأخيه من عرضه أو شيء فليتحلله اليوم قبل ألا يكون درهم ولا دينار يعني: قبل يوم القيامة، فإنه يوم القيامة ليس هناك دراهم ولا دنانير إنما هي الأعمال؛ ولهذا قال: فإن كان له عمل صالح أخذ من حسناته بقدر مظلمته، فإن لم يكن له حسنات أخذ من سيئات صاحبه فحمل عليه، فهذه حاله يوم القيامة، يجازى بأحد أمرين: إما بالأخذ من حسناته للمظلوم، فإن لم تكن له حسنات أو لم تكفه حسناته؛ لأن المظلمة كبيرة، أخذ من سيئات المظلوم فطرحت على الظالم نسأل الله العافية، فيجب الحذر.\nوأمر الصلاة أمر عظيم، وقد تساهل بها الكثير من الناس وهذا من الفساد العظيم، والخطر العظيم، يقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43]، ويقول سبحانه: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45]، ويقول : قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] إلى أن قال سبحانه: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:9-11]، والفردوس: هو أعلى الجنة وأوسطها وأشرفها، ويقول جل وعلا: إِنَّ الإِنسَانَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا ۝ إِلَّا الْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَلَى صَلاتِهِمْ دَائِمُونَ [المعارج:19-23] إلى أن قال : وَالَّذِينَ هُمْ عَلَى صَلاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ فِي جَنَّاتٍ مُكْرَمُونَ [المعارج:34-35]، وقال : فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا [مريم:59]، الغي عند أهل التفسير هو الخسار والدمار، والعاقبة الوخيمة، وقيل: أنه وادي في جهنم بعيد قعره خبيث طعمه، فتوعد الله من أضاع الصلاة بهذا الوعيد العظيم، وقال سبحانه: فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ [الماعون:4-5]، توعدهم بالسهو عنها فكيف بتركها؟ الترك أعظم، وقال  في المنافقين: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]، فأخبر عن المنافقين أنهم يتكاسلون عن الصلاة، وذمهم على هذا، فكيف بمن تركها؟ يكون أقبح من فعل المنافقين.\nفيجب الحذر على كل مسلم كل مكلف ينتسب إلى الإسلام يجب عليه الحذر، يجب أن يبادر بالمحافظة على الصلوات في أوقاتها في جماعة إذا كان رجلًا، وإن كانت امرأة ففي البيت تحافظ على ذلك وتلزم هذه الصلاة، تسأل الله العون عليها، وما سبق من تقصير ففيه التوبة اللازمة، التوبة النصوح، والله يتوب على التائبين سبحانه وتعالى. نعم.\nالمقدم: جزاكم الله خيرًا، إذا أذنتم لي سماحة الشيخ: هل هناك فرق بين من يترك الصلاة عمدًا أو تهاونًا أو تكاسلًا؟\nالشيخ: نعم مثل ما تقدم، الفرق بينهما: أن من ترك الصلاة عمدًا جاحدًا لوجوبها أو مستهزئًا بها فهذا يكون كافرًا عند جميع العلماء مرتدًا عن الإسلام، يجب قتله؛ لأنه بدل دينه؛ لأنه كذب الله ورسوله باعتقاده عدم وجوبها أو باستهزائه بها، والله يقول: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66].\nأما الذي يتركها تهاونًا، ويقول: أنا أؤمن بها وأنا أعرف أنها واجبة وفريضة، يعترف بهذا ولكنه يتساهل فلا يصلي أو يصلي الجمعة دون غيرها، أو في رمضان دون غيره، فهذا هو الذي محل الخلاف، ذهب جمع من أهل العلم إلى أنه يكون كافرًا كفرًا أصغر أو ظلمًا أصغر وفسقًا أصغر ما دام يقر بالوجوب فلا يكون كفره كفرًا أكبر، مثلما جاء في الحديث الآخر: لا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض، ومثل قوله ﷺ: .... ربكم .... من آبائكم، ومثل قوله ﷺ: اثنتان في الناس هما بهم كفر: الطعن بالنسب والنياحة على الميت قالوا: هذا كفر دون كفر، فيكون قوله ﷺ في حق التارك للصلاة: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر يعني: الكفر الأصغر، وهكذا يقولون في الحديث الآخر: بين الرجل وبين الكفر والشرك ترك الصلاة قالوا: يكون المراد بهذا الكفر والشرك الكفر الأصغر والشرك الأصغر. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7071/حكم-كفارة-اليمين-لتارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_170/17001.mp3","categories":["حكم الصلاة وأهميتها","الأيمان والنذور"]},{"id":9009,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: الجعيدي يماني، أخونا يقول: إنني إذا سمعت القرآن أحلف يميناً أنني لن أترك الصلاة بعد اليوم لكن فاتتني أيام لم أصل فيها، كيف تنصحونني والعمل الذي فات؟","title":"حكم من حلف على عدم ترك الصلاة ثم تركها","answer":"الجواب: أولاً عليك التوبة إلى الله فإن الصلاة عمود الإسلام، وهي أعظم أركانه بعد الشهادتين، وقد قال عليه الصلاة والسلام في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفعليك أن تتوب إلى الله من هذا العمل وهو ترك الصلاة في أيام، وعليك أن تبادر وتسارع إلى المحافظة عليها وإن قضيتها خروجاً من الخلاف فحسن، وإلا فالصواب: أن من تركها عمداً يكفر وليس عليه قضاء، لكن إذا كانت قليلة وقضيتها من باب الاحتياط فلا بأس، وعليك كفارة يمين؛ لأنك حلفت أن لا تترك وقد تركت فعليك كفارة يمين عما فعلت من الترك وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، هذا هو الواجب عليك، وأهم شيء وأعظمه: التوبة إلى الله سبحانه وتعالى والبدار بالمحافظة على الصلاة مع إخوانك في مساجد الله جل وعلا والحذر كل الحذر من تركها بعد ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7167/حكم-من-حلف-على-عدم-ترك-الصلاة-ثم-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14702.mp3","categories":["الأيمان والنذور","حكم الصلاة وأهميتها"]},{"id":9047,"question":"يلاحظ بكل أسف سماحة الشيخ من بعض المسلمين أنهم يصومون لكنهم لا يصلون، كيف تقولون؟","title":"حكم صيام رمضان مع ترك الصلاة","answer":"الجواب: هذه مسألة عظيمة قد تنازع أهل العلم فيمن ترك الصلاة كسلاً وتثاقلاً لا عن جحد الوجوب، فقال جمع: إنه لا يكفر بذلك وقد أتى منكراً عظيماً أعظم من الزنا وأعظم من الربا وأعظم من سائر المعاصي، قالوا: لكن لا يكفر كفراً أكبر، بل يكون فيه كفر وفيه شرك، ولكن لا يكون كفراً أكبر، وهذا هو المشهور من مذهب مالك والشافعي و أبي حنيفة وجماعة، وقال آخرون من أهل العلم: يكفر بذلك إذا ترك الصلاة عمداً وإن لم يجحد وجوبها، وهذا هو المعروف عن الصحابة والمنقول عن أصحاب النبي صلى الله عليه وسلم، قال التابعي الجليل عبد الله بن شقيق العقيلي: (كان أصحاب النبي ﷺ لا يرون شيئاً من الأعمال تركه كفر إلا الصلاة) يعني: كفر أكبر؛ لأن هناك أعمال فيها كفر لكن أصغر، مثل الحلف بغير الله، ومثل البراءة من الأنساب، وما أشبه ذلك، لكن مراده رضي الله عنه أنهم يرونه كفراً أكبر، هذا هو الظاهر من سياق كلام عبد الله بن شقيق العقيلي ، وأعظم من هذا ما ثبت في صحيح مسلم عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة، هذا صريح والكفر معرف بالألف واللام، الكفر والشرك، ومتى عرف الكفر والشرك بالألف واللام فالمراد به الكفر الأكبر والشرك الأكبر، وثبت في المسند والسنن الأربع بإسناد صحيح عن بريدة بن حصيب الأسلمي  عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وفي المسند وسنن الترمذي عن معاذ  عن النبي ﷺ أنه قال: رأس الأمر الإسلام وعموده الصلاة وذروة سنامه الجهاد في سبيل الله فبيت سقط عموده هل يبقى؟ ما يبقى البيت إذا سقط عموده، وثبت أيضاً في الصحيحين أن الرسول ﷺ قيل له لما ذكر الأمراء الذين يؤخرون الصلاة عن أوقاتها وتعرف منهم وتنكر، قال الصحابة: أفلا نقاتلهم؟ قال: لا، ما أقاموا فيكم الصلاة، وفي لفظ آخر: حتى تروا كفراً بواحاً عندكم من الله فيه برهان، فجعل ترك الصلاة كفراً بواحاً فيه البرهان، فهذا هو القول الأرجح أنه متى تركها تكاسلاً عامداً كفر كفراً أكبر لا يصح صومه ولا غيره من عباداته، فمن صام ولم يصل فلا صوم له نسأل الله العافية، أما إذا جحد وجوب ذلك جحدها وقال: ما علينا صلاة، أو استهزأ بها استهزأ بالصلاة واستهزأ بالمصلين فهذا كفره أكبر عند جميع العلماء، إذا استهزأ بها ولو صلى أو جحد وجوبها كفر إجماعاً عند جميع أهل العلم؛ لأنه مكذب لله ورسوله عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/7198/حكم-صيام-رمضان-مع-ترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_148/14805.mp3","categories":["حكم الصلاة وأهميتها","مسائل متفرقة في الصيام"]},{"id":9207,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية عمان، باعث الرسالة أخونا عمر ماجد محمد سعيد طالب في الثانوية العامة، أخونا بدأ رسالته كما يلي:صدرت عدة فتاوى من هذا البرنامج بتكفير تارك الصلاة سواء تركها جاحدًا أم متهاونًا، فتتبعنا الأقوال والأدلة في ذلك فرجح لدينا هذا الحكم، لكن وقفت أمامنا مجموعة من الشبهات نرجو من سماحتكم ردها وهي:أولًا: مصير تارك الصلاة هل هو إلى الجنة أو إلى النار؟ وذلك لتعارض هذا الحكم مع عدة أحاديث منها: حديث أبي ذر وهو قول الرسول ﷺ: ما من عبد قال: (لا إله إلا الله) ثم مات على ذلك إلا دخل الجنة فسأل أبو ذر الرسول ﷺ: وإن زنى وإن سرق؟ قال الرسول ﷺ: وإن زنى وإن سرق، فعل ذلك أبو ذر مرتين فأجابه الرسول ﷺ نفس الإجابة وقال في الثانية: على رغم أنف أبي ذر الحديث رواه البخاري .ثانيًا: صدرت الفتوى بأن تارك الصلاة إن مات لا يصلى عليه ولا يدفن في مقابر المسلمين، وهذا يعارض الحديث الذي رواه الدارقطني و البيهقي وهو قول الرسول صلى الله عليه وسلم: صلوا خلف من قال: (لا إله إلا الله) وعلى من قال: لا إله إلا الله.ثالثًا: تعارض هذه الفتوى مع حديث آخر لا يحضرني نصه، ولكن معناه: أن من أدى الصلاة وحافظ عليها كان له عهد عند الله أن يدخله الجنة، ومن لم يحافظ عليها لم يكن له عهد إن شاء الله غفر له وإن شاء عذبه، فجعل تارك الصلاة في مشيئة الله، إن شاء عذبه وإن شاء غفر له.هذه ثلاث شبهات نرجو ردها مع التفصيل وبيان الأدلة على ذلك جزاكم الله خير الجزاء؟","title":"ما جواب القول بعدم تكفير تارك الصلاة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الأدلة الشرعية من الكتاب والسنة كلها قائمة على كفر تارك الصلاة سواء كان جاحدًا أو متساهلًا، أما من كان جاحدًا لوجوبها فهذا كافر بإجماع المسلمين؛ لأنه مكذب لله ولرسوله عليه الصلاة والسلام، ومن كذب الله أو كذب رسوله كفر بإجماع المسلمين.\nأما من تركها تهاونًا لا جحدًا فهذا هو محل الخلاف بين أهل العلم، والسائل قد عرف ذلك، والصحيح كما عرفه السائل أن تاركها تهاونًا يكفر كفرًا أكبر، وهذا قول جماعة من أهل العلم، وقد حكاه التابعي الجليل عبدالله بن شقيق العقيلي عن الصحابة  أنهم ما كانوا يرون شيئًا تركه كفر إلا الصلاة.\nوقد دل على ذلك أحاديث منها: قوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأبو داود والترمذي والنسائي وابن ماجه بإسناد صحيح عن بريدة بن الحصيب ، ومنها: قوله عليه الصلاة والسلام: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله، ومنها: قوله ﷺ في الصلاة: من حافظ عليها كانت له نورًا وبرهانًا ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون و هامان و قارون و أبي بن خلف وهؤلاء من صناديد الكفرة وكبارهم، فحشر تارك الصلاة معهم يدل على كفره نسأل الله العافية والسلامة، وإن كان لم يتركها بالكلية بل يترك بعضًا ويؤدي بعضًا، وهناك أدلة أخرى دالة على ذلك.\nأما الشبهات الثلاث التي ذكرها السائل فجوابها -بحمد الله- ميسر أما حديث أبي ذر فهو دليل على أن من مات على التوحيد لا يشرك بالله شيئًا فإنه من أهل الجنة وإن زنى وإن سرق، وهكذا لو فعل معاصي أخرى كالعقوق والربا وشهادة الزور ونحو ذلك فإن العاصي تحت مشيئة الله إن شاء ربنا غفر له وإن شاء عذبه على قدر معاصيه إذا مات غير تائب، ولو دخل النار وعذب فيها فإنه لا يخلد بل سوف يخرج منها إلى الجنة بعد التطهير والتمحيص.\nفمراد النبي ﷺ: أنه وإن زنى وإن سرق فمصيره إلى الجنة إذا مات على التوحيد، وإن جرى عليه قبل ذلك ما يجري على بعض العصاة من العقوبات، وهكذا الأحاديث الأخرى الدالة على أن أهل التوحيد من أهل الجنة كما قال ﷺ في حديث عتبان: إن الله حرم على النار من قال: (لا إله إلا الله) يبتغي بها وجه الله متفق عليه، أو في حديث جابر عند مسلم يقول ﷺ: من لقي الله لا يشرك به شيئًا دخل الجنة، ومن لقيه يشرك به شيئًا دخل النار في أحاديث كثيرة.\nفهذا يدل على أن أهل التوحيد مصيرهم إلى الجنة وإن جرى منهم بعض المعاصي فإنهم تحت مشيئة الله فقد يعفى عنهم ويدخل الجنة من أول وهلة لأعمال صالحة اكتسبوها رجحت بها موازينهم، وقد يدخلون النار ويعذبون فيها على قدر المعاصي ثم يخرجون منها كما ثبتت بذلك الأحاديث عن رسول الله ﷺ وتواترت، وأجمع على ذلك أهل السنة أن العصاة لا يخلدون في النار إذا ماتوا مسلمين على التوحيد والإيمان فإنهم لا يخلدون في النار خلافًا للخوارج و المعتزلة ومن سلك مسلكهم.\nفيكون من دخل النار من أهل التوحيد وهو عاصي غير مخلد بخلاف الكفار فإنهم يخلدون في النار أبد الآباد، فحديث أبي ذر وما جاء في معناه إنما في حق العصاة الذين لم تصل معصيتهم إلى الكفر، أما من وصلت معصيته إلى الكفر كتارك الصلاة وساب الدين والمستهزي بالدين وأشباههم هؤلاء نقضوا توحيدهم ونقضوا إسلامهم، فلم يبق معهم إسلام ولم تنفعهم كلمة التوحيد إذا فعلوا ما ينقض الإسلام.\nفالذي ترك الصلاة ليس مثل الزاني والسارق، بل شأنه فوق ذلك وأعظم من ذلك، فهو من جنس من سب الدين أو سب الله أو سب الرسول ﷺ أو استهزأ بالدين أو نحو ذلك، هؤلاء كفار بإجماع المسلمين ولو قالوا: لا إله إلا الله، ولو ماتوا غير مشركين؛ لأن سبهم للدين يدل على احتقارهم له وعدم مبالاتهم به، وهكذا استهزاؤهم به قال الله تعالى: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66]، وهكذا لو جحد وجوب الصلاة كفر وإن كان موحدًا وإن كان يقول: لا إله إلا الله، وإن كان لا يشرك بالله شيئًا عند جميع العلماء إذا جحد وجوبها، أو جحد وجوب الزكاة، أو جحد وجوب الصيام صيام رمضان، أو جحد وجوب الحج مع الاستطاعة، أو جحد تحريم الزنا أو تحريم الخمر كفر إجماعًا ولو قال: لا إله إلا الله، ولو كان لا يشرك بالله شيئًا؛ لأن فعله هذا يجعله كافرًا في حكم المشركين، فيكون داخلًا فيمن أشرك.\nوهكذا تركه للصلاة يجعله داخلًا في الكفار، والرسول ﷺ إنما حكم بالجنة لمن مات لا يشرك بالله شيئًا، يعني: من قال: (لا إله إلا الله) موحدًا غير مشرك، ومن ترك الصلاة خرج من أهل التوحيد إلى أهل الكفر، وهكذا من سب الدين خرج من أهل التوحيد إلى أهل الكفر، وهكذا من استهزأ بالدين، وهكذا من جحد وجوب الصلاة، من جحد وجوب الزكاة، من جحد وجوب صوم رمضان، من جحد تحريم الزنا، من جحد تحريم المسكر، من جحد تحريم العقوق للوالدين، من جحد تحريم دم المسلم بغير حق، من جحد هذه الأمور كفر إجماعًا ولم ينفعه قوله: لا إله إلا الله، ولم ينفعه كونه لا يشرك بالله شيئًا من جهة الأصنام أو القبور أو غير ذلك؛ لأنه أتى بناقض من نواقض الإسلام، ومن أتى بناقض من نواقض الإسلام لن تنفعه بقية الأمور التي عنده.\nوهكذا لو استهان بالمصحف كفر إجماعًا ولو قال: لا إله إلا الله، ولو كان لا يشرك بالله شيئًا، فلو جلس عليه إهانة له أو بال عليه كفر إجماعًا؛ لأنه استهان بكلام الله واحتقر كلام الله فهو يدل على عدم احترامه لله وعدم احترامه لكلامه سبحانه وتعالى، وبهذا تعلم أن قوله ﷺ: من مات لا يشرك بالله شيئًا دخل الجنة .. من قال: (لا إله إلا الله) صدقًا من قلبه دخل الجنة إنما هذا في حق من قالها ولم يأت بناقض من نواقض الإسلام، أما إذا قالها وأتى بناقض كفر إجماعًا ولم تنفعه هذه الكلمة، كما أن من توضأ الوضوء الشرعي فقد أتى بالطهارة الشرعية له أن يصلي، لكن لو أتى بناقض لو خرج منه الريح بعدما توضأ أو بال بطل هذا الوضوء ولم تنفعه هذه الطهارة؛ لأنه أتى بناقض ينقضها، فهكذا من أتى بناقض من نواقض الإسلام لم ينفعه قوله: لا إله إلا الله أو شهادة أن لا إله إلا الله، أو كونه لا يشرك بالله؛ لأنه أتى بشيء ينقض دينه وينقض إسلامه.\nالشبهة الثانية: حديث عبادة في إن على الله عهدًا لمن حافظ على الصلوات أن يدخله الجنة، ومن لم يأت محافظ عليها فليس له عند الله عهد هذا حديث ضعيف لا يصح عن النبي ﷺ، وأيضًا هو من أحاديث الفضائل. وأما الشبهة الثالثة: حديث: صلوا على من قال: لا إله إلا الله.. وصلوا خلف من قال: لا إلـه إلا اللـه، فهذه أحاديث ضعيفة لا تصح عن النبي ﷺ، ولو صحت لكان المعنى: صلوا على خلف من قال: (لا إله إلا الله) إذا قالها بحق واستقام عليها، وهكذا صلوا خلف من قال: لا إله إلا الله، يعني: إذا قالها والتزم معناها وأدى حقها، فأما من قالها ونقضها بالشرك أو نقضها بأنواع من الكفر لم تنفعه، فالمنافقون يقولون: لا إله إلا الله ويصلون مع الناس ويصومون ويحجون وهم كفار؛ لأنهم نقضوها بكفرهم الباطن واعتقادهم الباطن وتكذيبهم لله في الباطن، فهكذا من قالها -كما تقدم- وسب الدين أو سب الرسول ﷺ أو سب الله، أو استهزأ بالدين، أو استهان بالمصحف، أو ما أشبه ذلك، فإن قوله: (لا إله إلا الله) لا ينفعه؛ لأنه أتى بناقض ينقض هذا الكلام ويدل على كفره وأن قوله: (لا إله إلا لله) ليس بصادق بل عنده من الاستهانة بالله وبأحكامه وبشريعته ما يجعله معدوم الإيمان باطل هذا القول؛ لأنه قال قولًا لا حقيقة له، ولا يعضده إيمان وتصديق. نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7367/ما-جواب-القول-بعدم-تكفير-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18201.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9213,"question":"أيضًا من المملكة الأردنية الهاشمية هذه رسالة وصلت إلينا من جرش وباعثتها إحدى الأخوات من هناك تقول: هادية محمد الجبالي، أختنا لها مجموعة من الأسئلة:سؤالها الأول يقول: هل يجوز الترحم والدعاء لتارك الصلاة أو المتهاون فيها وكذلك النصراني أعني: الكافر، وهل يصح الدعاء عليهم ولعنهم أو سبهم بعد الوفاة؟","title":"حكم الدعاء لتاركي الصلاة والكفرة والاستغفار لهم","answer":"الجواب: أما من مات من اليهود أو النصارى أو عباد الأوثان وهكذا من مات تاركًا للصلاة أو جاحدًا لوجوبها هؤلاء كلهم لا يدعى لهم ولا يترحم عليهم ولا يستغفر لهم؛ لقول الله : مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113]، وقد ثبت في الحديث الصحيح عن النبي عليه الصلاة والسلام: أنه استأذن ربه أن يستغفر لأمه فلم يأذن له سبحانه مع أنها ماتت في الجاهلية لم تدرك الإسلام لكنها ماتت على دين قومها على عبادة الأوثان، فاستأذن ربه فلم يأذن له أن يستغفر لها، فإذا كان امرأة ماتت في الجاهلية على دين الأوثان لم يؤذن له أن يستغفر لها وهي أمه، فكيف بغيرها عليه الصلاة والسلام؟ فالذي مات على الكفر لا يستغفر له ولا يدعى له، لا تارك الصلاة، ولا عابد القبور، ولا اليهودي، ولا النصراني، ولا الشيوعي، ولا القادياني، ولا أشباههم ممن يتعاطى ما يكفره ويخرجه من دائرة الإسلام.\nأما سبهم فلا يسبون بعد الموت يقول النبي ﷺ: لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا رواه البخاري في الصحيح عن عائشة رضي الله عنها: لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا أفضوا إلى الله، الله يجازيهم بأعمالهم فلا حاجة إلى سبهم.\nلكن ذكر جماعة من أهل العلم أنه لا بأس بسب من اشتهر بالضلال والكفر والدعوة إلى الباطل من باب التحذير ولو بعد الموت، كما يقال: قاتل الله فرعون .. لعن الله فرعون .. لعن الله دعاة الضلالة، لعن الله أبا جهل وما أشبه ذلك من دعاة الضلالة من باب التنفير من أعمالهم القبيحة، هذا قاله جماعة من أهل العلم من باب التنفير إذا كان الإنسان مشهورًا بالضلالة والكفر والدعوة إلى الضلالة، أو ظلم الناس أجاز بعض أهل العلم سبه من باب التنفير ومن باب التحذير من مثل عمله، وإن ترك سبه عملًا بهذا الحديث: لا تسبوا الأموات فهذا من باب الاحتياط وهو أحسن وأولى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7373/حكم-الدعاء-لتاركي-الصلاة-والكفرة-والاستغفار-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18204.mp3","categories":["إهداء القرب للميت","حكم الصلاة وأهميتها"]},{"id":9227,"question":"السؤال الثاني في رسالة المستمع (ب. ل. د) من العراق محافظة التأميم، يقول فيه: إنني كثيراً ما أذكر الله ذكراً كثيرا، ولكنني لا أصلي، وسمعت من بعض الأصدقاء أن هذا الفعل يعتبر من الكفر بالله ، أي: ذكر الله بدون صلاة، فما حكم الإسلام في ذلك، أفيدونا أفادكم الله؟","title":"هل ذكر الله مع ترك الصلاة ينفع صاحبه؟","answer":"الجواب: الصلاة هي عمود الإسلام، وهي أعظم الأركان بعد الشهادتين، يقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] والآيات في الصلاة كثيرة، ويقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله فجعل الصلاة هي عمود الإسلام، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر ويقول عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة فأنت عليك أن تتقي الله، وأن تبادر بالتوبة.\nأما ذكر الله مع ترك الصلاة ما ينفعك، عليك أن تحافظ على الصلاة، وأن تستقيم عليها في أوقاتها، وأن تصليها مع إخوانك المسلمين في المساجد، هذه هي فريضته العظيمة، وعمود دينك، فاتق الله وراقب الله، وتب إلى الله توبةً صادقة، ومن تاب تاب الله عليه .\nويقول النبي ﷺ: أول ما يحاسب عنه العبد من عمله؛ صلاته، فإن صلحت فقد أفلح وأنجح، وإن فسدت فقد خاب وخس نسأل الله العافية، ويقول عمر  لأمرائه: إن أهم أمركم عندي الصلاة، فمن حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع وجاء في الحديث عنه ﷺأنه قال يوماً بين أصحابه، فذكرهم بالصلاة، وقال: من حافظ عليها كانت له نوراً وبرهاناً ونجاةً يوم القيامة، ومن لم يحافظ عليها لم يكن له نورٌ ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف نسأل الله العافية، هؤلاء من كبار الكفرة، من صناديد الكفرة، نسأل الله العافية، قال بعض أهل العلم: إنما يحشر من ضيع الصلاة مع هؤلاء الكفرة؛ لأنه إن ضيعها من أجل الرئاسة والملك صار شبيهاً بـفرعون ، فيحشر معه يوم القيامة، وإن ضيعها بسبب الوزارة والوظيفة صار شبيهاً بـهامان وزير فرعون فيحشر معه يوم القيامة إلى النار، وإن ضيعها بسبب الأموال والشهوات صار شبيهاً بـقارون تاجر بني إسرائيل الذي بغى وطغى، وحمله حب المال وكثرة المال على الكفر بالله ، فخسف الله به وبداره الأرض، فمن شغل بالمال عن الصلاة حشر مع قارون نعوذ بالله من ذلك، ومن شغل عن الصلاة بالتجارة والبيع والشراء والمعاملات صار شبيهاً بـأبي بن خلف تاجر أهل مكة الكافر، وقد قتل كافراً، فيحشر معه يوم القيامة -نعوذ بالله- إلى النار.\nفالواجب على كل من ضيع الصلاة أن يتوب إلى الله، من الرجال والنساء جميعاً، الواجب على الجميع التوبة إلى الله، والبدار بالمحافظة على الصلاة، والندم على ما مضى، ومن تاب تاب الله عليه، رزق الله الجميع التوفيق والهداية.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7387/هل-ذكر-الله-مع-ترك-الصلاة-ينفع-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_233/23307.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9241,"question":"يسأل أيضاً ويقول: عندي جاري يشرب الخمر ولا يصلي، وحالته ضعيفة في المعايش، وأنا أساعده ببعض الفلوس، فهل يجوز لي مساعدته أم أتوقف ولا أعطيه شيئاً أفيدوني أفادكم الله؟","title":"حكم مساعدة الجار الذي يشرب الخمر ولا يصلي","answer":"الجواب: هذا الجار جار سوء، إذا كان لا يصلي ويشرب الخمر، هذا لا ينبغي أن يساعد على فعله الخبيث، بل ينبغي أن يهجر ويقاطع ولا تتصل به، ولا تسلم عليه، ولا تزوره، إلا إذا تاب ورجع إلى الله عز وجل فلا بأس، أما ما دام في هذه الحالة فيكون مرتداً بتركه للصلاة، يجب أن يقاطع وأن يعلن له البغضاء والكراهة، وأن لا تجاب دعوته، وأن لا يدعى إلى وليمة عندك، وعند إخوانك الطيبين، اتركوه، يجب أن يهجر، لكن مع النصيحة انصحوه ووجهوه إلى الخير، لعل الله يهديه بأسبابكم، فإذا أصر على عمله السيئ فينبغي أن يرفع بأمره إلى الهيئة في البلد، لتحضره وتستتيبه أو إلى ولاة الأمور حتى ينظروا في أمره لئلا يضر المجتمع، لئلا يتأسى به غيره، نسأل الله لنا وله الهداية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7411/حكم-مساعدة-الجار-الذي-يشرب-الخمر-ولا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23510.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9252,"question":"يسأل أيضاً ويقول: عندي جاري يشرب الخمر ولا يصلي، وحالته ضعيفة في المعايش، وأنا أساعده ببعض الفلوس، فهل يجوز لي مساعدته أم أتوقف ولا أعطيه شيئاً أفيدوني أفادكم الله؟","title":"حكم مساعدة الجار الذي يشرب الخمر ولا يصلي","answer":"الجواب: هذا الجار جار سوء، إذا كان لا يصلي ويشرب الخمر، هذا لا ينبغي أن يساعد على فعله الخبيث، بل ينبغي أن يهجر ويقاطع ولا تتصل به، ولا تسلم عليه، ولا تزوره، إلا إذا تاب ورجع إلى الله عز وجل فلا بأس، أما ما دام في هذه الحالة فيكون مرتداً بتركه للصلاة، يجب أن يقاطع وأن يعلن له البغضاء والكراهة، وأن لا تجاب دعوته، وأن لا يدعى إلى وليمة عندك، وعند إخوانك الطيبين، اتركوه، يجب أن يهجر، لكن مع النصيحة انصحوه ووجهوه إلى الخير، لعل الله يهديه بأسبابكم، فإذا أصر على عمله السيئ فينبغي أن يرفع بأمره إلى الهيئة في البلد، لتحضره وتستتيبه أو إلى ولاة الأمور حتى ينظروا في أمره لئلا يضر المجتمع، لئلا يتأسى به غيره، نسأل الله لنا وله الهداية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7411/حكم-مساعدة-الجار-الذي-يشرب-الخمر-ولا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23510.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9305,"question":"سؤالها الثاني: تقول: زوج خالتي تارك للصلاة رغم أنه حج إلى بيت الله، وقد ذكرت له خالتي ما سمعته من البرنامج من حكم تارك الصلاة تهاونًا من أنه يكون كافرًا كفرًا يخرج من الملة ولكنه ظل تاركًا للصلاة، وهي سكتت عن ذلك، فهل معاشرته لها حرام عليها؟ وهل تاركة الصلاة من النساء يجوز كشف الوجه أمامها باعتبار أنها كافرة بتركها للصلاة وخرجت عن ملة الإسلام، أفيدونا عن هذه القضايا وفقكم الله؟","title":"حكم معاشرة الزوج التارك للصلاة وكشف الوجه أمام الكافرة","answer":"الجواب: لا شك أن الذي يترك الصلاة كافر وإن لم يجحد وجوبها في أصح قولي العلماء؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة والمرأة كذلك في الحكم الشرعي؛ لأن القاعدة الشرعية أن الأحكام التي تثبت للرجال تكون للنساء، وهكذا العكس؛ لأن الجميع مكلف، والرسول ﷺ بعث للجميع وهكذا قوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر فالذي لا يصلي ليس لزوجته البقاء معه وهي مسلمة، ليس لها أن تبقى معه، بل عليها أن تفارقه وأن تمنعه من الاتصال بها حتى يتوب فيتوب الله عليه.\nوهكذا المرأة التي تترك الصلاة ليس لزوجها المسلم أن يبقى معها، بل يجتنبها حتى تتوب فإن تابت وإلا فارقها وسوف يعوضه الله خيرًا منها؛ لأن الله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وهذه من المصائب العظيمة، ترك الصلاة من المصائب العظيمة.\nفالواجب على المسلمين جميعًا أن يحذروا ذلك وأن يتناصحوا في ذلك، وأن يهجروا من ترك الصلاة، وأن لا يقبلوا دعوته، وأن لا يسلموا عليه، وأن لا يردوا عليه السلام، وأن لا يدعوه إلى وليمة ولا غيرها، بل يجب أن يهجر كالبعير الأجرب، لا يقرب ولا يزار إلا للدعوة إلى الله، إذا كان للدعوة يدعى وينصح فلا بأس.\nوأما طرح الخمار عند الكافرة فلا بأس على الصحيح، سواء كانت تاركة للصلاة أو يهودية أو نصرانية أو وثنية، لا حرج على المسلمة أن تراها الكافرة ولا تحتجب منها، هذا هو الصواب، وهذا هو الصحيح من قولي العلماء أن التحجب إنما يكون عن الرجل الأجنبي أما عن المرأة فلا، أما قول الله سبحانه: أَوْ نِسَائِهِنَّ [النور:31] فالمراد: نساء بني آدم، فالمرأة لا يحتجب عنها على الصحيح وإنما يحتجب عن الرجل الأجنبي الذي ليس بمحرم، وأما المرأة فإنها من جنس المرأة وإن كانت كافرة لا حرج على المسلمة أن لا تحتجب عنها؛ لأن الرسول ﷺ لم يأمر نساءه أن يحتجبن عن اليهوديات اللاتي كن في المدينة ولا عن غيرهن من الوثنيات، ولا نعلم أن امرأة من أزواج النبي ﷺ أو بناته احتجبت عن امرأة كافرة.\nوقد ثبت في الصحيحين عن أسماء بنت أبي بكر رضي الله تعالى عنهما أن أمها وفدت إليها في المدينة في وقت الصلح بين الرسول ﷺ وبين أهل مكة وهي كافرة، جاءت تطلب من بنتها الرفد والمساعدة، فاستأذنت أسماء الرسول ﷺ في أن تصلها فقال النبي ﷺ: صليها ولم يأمرها أن تحتجب عن أمها لأنها كافرة، والقضايا في هذا كثيرة كلها دالة على أنه ليس على المرأة المسلمة أن تحتجب عن المرأة الكافرة، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7459/حكم-معاشرة-الزوج-التارك-للصلاة-وكشف-الوجه-امام-الكافرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18406.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","نكاح الكفار"]},{"id":9351,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع محسن بن مشعل العتيبي من الرياض، أخونا يقول: تزوجت ابنة عمي في عام ألف وأربعمائة وكان عمرها آنذاك ثنتي عشرة سنة ولم تنجب أولادًا حتى الآن، وأنا أعاملها معاملة حسنة وهي تبادلني هذه المعاملة الحسنة بالمعاملة السيئة حتى أنها لا تقوم بالفرائض الصلاة، وقد نصحتها عدة مرات ولم تستجب بحجة أنها لا تزال صغيرة، وتقول: إنها ستقوم بواجب الصلاة عند بلوغها سن العشرين أو واحد وعشرين، وهي أيضًا لا تقوم بواجبها نحو الزوج ... ويستمر في الشكوى من هذه الزوجة وأهم ما في الموضوع: أنها كانت متربية على غير تأدية الصلاة ويرجو من سماحة الشيخ التوجيه؟","title":"حكم البقاء مع الزوجة التاركة للصلاة","answer":"الجواب: ما دامت بهذه الصفة فلا خير لك فيها، بل يجب أن تفارقها، وليس لك أن تستمتع بها وهي بهذا السن، ما دامت بلغت سن النساء المكلفات، أكملت خمسة عشر سنة، أو أتاها الحيض، أو أنزلت عند الجماع أو في الاحتلام، أو أنبتت الشعر المعروف عند الفرج -الشعرة- فهي بهذه الأمور الأربعة تكون بالغة بأي واحد منها، فإذا كانت لا تصلي فلا يجوز بقاؤها عندك بل يجوز إبعادها وعدم الاستمتاع بها حتى يمن الله عليها بالتوبة.\nولك أن تضربها على هذا وتؤدبها حتى تستقيم؛ لأن ضربها في هذا المقام مهم جدًا، ولعل الله يهديها بأسبابك، ومع ذلك لم تنجب فعيوبها كثيرة، هذه المرأة عيوبها كثيرة والسلامة منها خير لك في الدنيا والآخرة، ولا يجوز لك البقاء معها أبدًا إلا أن تتوب، نسأل الله أن يهديها ويردها للتوبة أو يبدلك خيرًا منها. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7515/حكم-البقاء-مع-الزوجة-التاركة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18507.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":9376,"question":"رسالة من أحد السادة المستمعين بعث بها وهو يقول: أبعث إليكم كتابي هذا وأرجو من الله أن ترشدوني إلى الصواب، أنا رجل مجتهد فيما أمرني ربي وأسرتي -والحمد لله- تشاركني في ذلك حسب استطاعتهم، ولكن يوجد لي أخت لا تصلي من مدة طويلة، وزوجها يشاركها أيضًا في ذلك الحال، وقد أخبرني كثير من الناس أن ذلك هو سلوكهم وأنهم لا يرضون الله في ذلك الجانب، وعندما عرفت بنفسي أنها على ذلكم الحال أخذتها وأخبرتها بما حرم الله ورسوله وأخبرتني بنفسها أنها فعلًا كانت تعمل ذلكم العمل، وبعد هذا الموقف قامت وعاهدتني على كتاب الله ووعدتني أن تتوب من الآن ولكن للأسف لم توفي بالعهد، فعندئذ قاطعتها حتى تعود كسائر المؤمنات اللاتي يردن وجه الله تبارك وتعالى، أفيدوني جزاكم الله خيرا عن حكم ما فعلت، ولا سيما عن حكم مقاطعتي لأختي تلكم جزاكم الله خيرًا؟","title":"ما حكم هجر تارك الصلاة؟","answer":"الجواب: قد أحسنت فيما فعلت من نصيحتها ودعوتها إلى الخير، وقد أساءت في رجوعها إلى الباطل، وعدم صلاتها؛ لأن الصلاة عمود الإسلام، من ضيعها ضيع دينه، ومن تركها كفر نعوذ بالله من ذلك، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وهذا يعم الرجال والنساء، وقال عليه الصلاة والسلام: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله، وقال أيضا عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة فقد أحسنت في مقاطعتها وهجرها حتى تتوب إلى الله ؛ لأن هذا منكر عظيم بل كفر، فالواجب هجرها وهجر زوجها حتى يتوبا إلى الله ، وإن ظهر أمرهما وعرف أنهما لا يصليان فيجب رفع أمرهما إلى ولاة الأمور إذا كانا في بلاد إسلامية يقيمون الصلاة ويعاقبون عليها يرفع بأمرهما حتى يستحقا أن يعاقبا على ذلك بالقتل، فإن من ترك الصلاة يستتاب فإن تاب وإلا قتل، قتله ولي الأمر، ولي أمر المسلمين أو نائبه.\nفالمقصود: أن عليك العناية بنصيحتهما جميعًا ولو من طريق الهاتف أو المكاتبة أو توكيل من ينصحهم، لعل الله يهديهم بأسبابك.\nأما قطعك لهم وهجرك لهم هذا كله طيب وواجب إذا كان يرجى فيه خير، أما إذا كنت لا ترجو من وراء الهجر خيرًا فلا مانع من الاتصال بهم لا للأكل عندهم والشرب والأنس بهم، لا، ولكن لمجرد الدعوة والتوجيه والإرشاد، لا للأكل معهم أو الضحك معهم، أو الأنس معهم، لا، بل تلقاهم بوجه غير منبسط بل وجه مكفهر حتى يرجعا إلى الحق، حتى يتوبا إلى الله .\nوقد هجر النبي ﷺ ثلاثة من الصحابة في أقل من هذا، تخلفوا عن غزو من غير عذر\nفي يوم تبوك، فهجرهم النبي ﷺ وأمر المسلمين بهجرهم، فهجروا خمسين ليلة حتى تاب الله عليهم، فإذا كان من تخلف عن الغزو بغير عذر يهجر فالذي تخلف عن الصلاة التي هي عمود الإسلام أولى وأولى بهذا، لكن إن رجوت فيهم خيرًا فلا مانع من الاتصال بهم ودعوتهم إلى الله ونصيحتهم لعل الله يهديهما بأسبابك. نعم.","link":"https://binbaz.org.sa/fatwas/7540/ما-حكم-هجر-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18614.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9384,"question":"أيضاً نعود في هذه الحلقة إلى رسالة الأخت نوارة سالم من ليبيا، أختنا في هذه الحلقة لها سؤالان، تقول في سؤالها الأول: ما حكم ذبيحة تارك الصلاة سواءً كان جاحداً لوجوبها أو متكاسلاً، وأيضاً إذا علم أنه سمي عليها أو لم يعلم؟","title":"ما حكم ذبيحة تارك الصلاة؟","answer":"الجواب: تارك الصلاة له حالان كما ذكرت السائلة:\nإن كان قد جحد وجوبها فهذا كافر بالإجماع؛ إجماع أهل العلم؛ لأنه مكذب لله ومكذب لرسوله عليه الصلاة والسلام، فقد دل كتاب الله عز وجل في مواضع كثيرة على وجوب الصلاة ودلت السنة عن رسول الله عليه الصلاة والسلام على وجوب الصلاة وأنها أحد أركان الإسلام الخمسة، بل هي الركن الأعظم للإسلام بعد الشهادتين، فمن جحد وجوبها وأنكر ذلك فهو مرتد كافر بالإجماع إذا كان ينتسب إلى الإسلام فذبيحته لا تحل كذبيحة المشركين بل أعظم؛ لأن المرتد أشد كفراً من المشرك الأصلي، وإذا كانت ذبيحة الكافر الأصلي لا تباح فالمرتد من باب أولى، وإنما تباح ذبيحة أهل الكتاب خاصة إذا ذبحوها على الوجه الشرعي وهم اليهود و النصارى .\nأما الذي تركها تكاسلاً فهذا اختلف فيه العلماء، فمنهم من قال: إنه كافر كفراً أكبر ومنهم من قال: إنه كفر دون كفر، فمن قال: إن كفره كفر دون كفر فهذا يبيح ذبيحته كما تباح ذبيحة الزاني والسارق وشارب الخمر إذا كان لم يستحل ذلك بل فعله وهو يعلم أنها معاصي وأنها منكرة.\nوالقول الثاني: أنه كافر كفراً أكبر -كما تقدم- وهذا هو القول الأرجح أن كفره كفر أكبر كالجاحد لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة ، ولما رواه مسلم في الصحيح عن جابر بن عبد الله الأنصاري رضي الله تعالى عنهما أن النبي ﷺ قال: بين الرجل وبين الكفر والشركك ترك الصلاة مع أحاديث أخرى في ذلك، وعلى هذا لا تباح ذبيحته أيضاً؛ لأنه كافر وثني من جنس الوثني بل أغلظ؛ لأنه مرتد نسأل الله العافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7548/ما-حكم-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_157/15702.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9443,"question":"السؤال الثاني في رسالة الأخ (ف. ر. ع) من جمهورية اليمن، يقول فيه: هل يجوز للمسلم أن يتزوج بفتاة لم تصل؟ حيث أنه يعيش في بلاد أكثر أهلها لا يصلون، وأنه مضطر للزواج خوفًا من الفتنة، وسوف يشترط على أهل الفتاة أن تؤدي الصلاة أثناء عقد الزواج، وفي حالة عدم صلاتها يطلقها، فما الحكم في ذلك؟","title":"حكم الزواج بامرأة تاركة للصلاة","answer":"الجواب: ترك الصلاة من الرجال والنساء كفر أكبر في أصح قولي العلماء، وعلى هذا لا يجوز للمسلم أن ينكح امرأة لا تصلي، بل يجب عليه أن يتحرى في الزوجة أن تكون ذات دين، وأن تكون من المصليات، ومن الذين يحترمون الدين ولا يأتون بشيء إلا فيه، هذا هو الواجب على المسلم، ولهذا قال عليه الصلاة والسلام: تنكح المرأة لأربع: لمالها ولحسبها ولجمالها ولدينها، فاظفر بذات الدين تربت يداك متفق على صحته.\nفالمؤمن يتحرى في الزوجة أن تكون طيبة في دينها وأخلاقها وسيرتها، ومن أسرة طيبة، فإذا كانت لا تصلي فهذا من أعظم الكفر بالله في أصح قولي العلماء، وقد خالف في هذا من خالف من أهل العلم وقالوا: إن ترك الصلاة ليس بكفر أكبر إذا كان لا يجحد الرجل وجوبها ولا تجحد المرأة وجوبها ولكن ذلك عن كسل، هذا قول جماعة من أهل العلم، ويحكى قول الأكثرين.\nولكن الصواب الذي عليه الأدلة الشرعية: أن ترك الصلاة كفر أكبر وإن لم يجحد التارك وجوبها، لما ثبت عنه ﷺ أنه قال: رأس الأمر الإسلام، وعموده الصلاة فشيء ترك عموده وذهب عموده كيف يبقى؟!\nأيضًا ثبت عنه ﷺ وهو أصرح في هذا الباب قوله ﷺ: إن بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه، والتعبير بالرجل لا يخصه على طريقة الرسول ﷺ في الأحكام، فإنه إذا عبر بالحكم الشرعي باسم الرجل أو باسم المرأة فالحكم عام، وهكذا ما جاء في كتاب الله من الأحكام بأسماء الرجال أو بأسماء النساء الحكم عام، إلا ما جاء الدليل بالتخصيص، كتخصيص المرأة بنصف ميراث الذكر من الأولاد والإخوة، وغير ذلك مما جاء به التخصيص، وإلا فالأصل أنهما سواء في الأحكام وهذا منها.\nفإذا كفر بترك الصلاة الرجل فالمرأة كذلك، وإن كان ذلك عن تهاون وعن كسل، هذا هو الصواب.\nومن هذا الباب ما ثبت عنه أيضًا عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد في المسند وأهل السنن الأربع بإسناد صحيح عن بريدة ، وهذا عام للرجال والنساء.\nفنصيحتي للرجل السائل أن لا يتزوج إلا امرأة معروفة بالاستقامة والصلاة، والبعد عن كل ما يغضب الله عز وجل ولو بقي أعزب حتى يسهل الله له من يرضى دينها، والكتابية خير من هذه؛ لأن الكتابية أباح الله نكاحها إذا كانت محصنة، أما المشركة فهي محرمة علينا، كما قال الله جل وعلا: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221] وهذه يقال لها: مشركة، فالكتابية خير منها، وإن كان ترك نكاح الكتابية أولى وأفضل بكل حال، وأن يتزوج مسلمة حنيفية مؤمنة هذا هو الذي ينبغي له.\nلكن بكل حال إذا كان ولابد فتزوج كتابية محصنة أولى من كونك تتزوج امرأة لا تصلي، كافرة، نعم.\nلكن في الإمكان أن يشرط صلاتها وتوبتها قبل العقد، فإذا استقامت وهداها الله وتابت، وثبت لديه ذلك بأنها تركت عملها السيئ وأنابت إلى الله وصارت تصلي فليتزوجها والحمد لله.\nولعل رغبتها بالزواج تكون سببًا لتوبتها ورجوعها إلى الله، واستقامتها في الصلاة، فيكون قد أحسن إليها بهذا الزواج الذي جعله الله لها سببًا للتوبة والاستقامة وأداء الصلاة.","link":"https://binbaz.org.sa/fatwas/7604/حكم-الزواج-بامراة-تاركة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19102.mp3","categories":["حكم الصلاة وأهميتها","شروط وأركان الزواج"]},{"id":9491,"question":"هذه أول رسالة في البرنامج بعث بها الأخ صبري الجبوري من الجمهورية العراقية، تحتوي الرسالة على عدة أسئلة؛ السؤال الأول يقول فيه: أرجو أن تبينوا لنا ما حكم تارك الصلاة، وهل يجوز أن يصلى عليه إذا مات أفيدونا أفادكم الله؟","title":"حكم تارك الصلاة وهل يُصلى عليه إذا مات؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الصلاة عمود الإسلام، وهي أهم الفرائض وأعظم الواجبات بعد الشهادتين، وقد اختلف العلماء رحمهم الله في تاركها تهاونًا وكسلًا وهو يقر بوجوبها وأنها حق وأنها فرض ولكنه يتساهل في تركها، فذهب جمع من أهل العلم إلى أنه لا يكفر ولكن يكون قد أتى إثمًا عظيمًا ومعصية عظيمة أعظم من الزنا والسرقة، وأعظم من الربا واللواط وشبه ذلك.\nوذهب آخرون من أهل العلم إلى أنه يكفر بذلك كفرًا أكبر وهذا هو القول الصواب، وهو الحق أنه يكفر كفرًا أكبر لأدلة كثيرة؛ منها:\nقوله جل وعلا عن أهل النار لما سئلوا: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42-43] فدل ذلك على أن من ترك الصلاة فليس من أهل الجنة بل هو من أهل النار.\nومنها قوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة لما تترك العمود سقط ما عليه.\nومنها قوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه.\nوهذا كفر معرف بـ(أل) وشرك معرف بـ(أل)، وذلك يدل على أنه الكفر الأكبر والشرك الأكبر، خرجه مسلم في صحيحه.\nومنها ما رواه الإمام أحمد وأهل السنن بإسناد صحيح عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر في أدلة كثيرة أخرى.\nوعلى هذا لا يصلى عليه ولا يغسل ولا يكفن ولا يدفن في مقابر المسلمين بل يحفر له في أي جهة من الجهات ويدفن كما يدفن غيره من الكفرة حتى لا يتأذى الناس بنتنه وجيفته، هذا هو الصواب في هذه المسألة الخطيرة التي كثر فيها اليوم الكلام، وقل من يحافظ على الصلاة في الجماعة وفي وقتها إلا من هداه الله.\nوالمقصود أن ترك الصلاة أمر خطير، فإن كان عن جحد لوجوبها فهذا كافر بالإجماع، أما إن كان تهاونًا وكسلًا فالصواب أنه كافر كفرًا أكبر، وقد كثر كما تقدم من فعل هذا الأمر ومن تكاسل عن الصلاة فالواجب الحذر الواجب الحذر، الواجب على من يدعي الإسلام أن يتقي الله، وأن يحافظ على الصلاة في وقتها وأن يؤديها في الجماعة طاعة لله ورسوله، فإن الصلاة من حفظها حفظ دينه ومن ضيعها فهو لما سواها أضيع، نسأل الله السلامة. نعم.","link":"https://binbaz.org.sa/fatwas/7656/حكم-تارك-الصلاة-وهل-يصلى-عليه-اذا-مات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19301.mp3","categories":["الصلاة على الميت","حكم الصلاة وأهميتها"]},{"id":9498,"question":"هذه رسالة وردت إلينا من المرسل الحاج جوده السيد الخزامي مصري الجنسية مقيم بالمدينة المنورة، يقول: لي جدة تبلغ من العمر مائة سنة أو تزيد، وكانت تصلي وتقوم بحق الله على الوجه الأكمل من صيام وصلاة، فلكن لما بلغت الكبر تركت الصلاة بعذر كبر السن، علماً بأن وزنها ثقيل، وتطلب مني أن أسقط عنها الصلاة، فهل يجوز ذلك؟","title":"حكم ترك الصلاة بسبب كبر السن","answer":"الجواب: لابد من النظر في أمرها، إن كان عقلها معها لم يتغير عقلها فلابد من الصلاة، ولا تسقط عنها الصلاة، وليس لك ولا لغيرك إسقاط الصلاة عنها، هذا أمر لله، ليس حقاً للناس، فعليها أن تصلي، وإذا كانت عاجزة ثقيلة شبه المريضة يشق عليها العمل صلت الظهر والعصر جميعاً، والمغرب والعشاء جميعاً كسائر المرضى، أما إذا كانت تستطيع أن تصلي كل صلاة في وقتها فإنه يلزمها كسائر المسلمين، وكبر السن لا يمنعها من ذلك إذا كانت بعافية، فعليها أن تصلي الظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، والفجر في وقتها، لكن إذا اشتد بها الأمر لثقلها وكبر سنها وضعفها جاز لها أن تجمع بين الظهر والعصر وبين المغرب والعشاء كالمرضى، أما ترك الصلاة فلا يجوز، يجب عليها أن تصلي وأن تستعين بالله، وأن تراقب الله وتخشاه ولاسيما في هذا السن قد دنت من الأجل، فالواجب عليها أن تعد العدة الصالحة عند لقاء ربها، وليس لها أن تتساهل بالصلاة لا بالليل ولا في النهار، ولكن تتقي الله ما استطاعت، إن كانت تستطيع القيام صلت قائمة، فإن كانت تعجز عن القيام صلت قاعدة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] يقول النبي ﷺ للمريض: صل قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً فإذا كانت تعجز عن الصلاة قائمة صلت وهي جالسة، والله نسأل أن يعينها على الخير. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7658/حكم-ترك-الصلاة-بسبب-كبر-السن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24201.mp3","categories":["صلاة المريض","حكم الصلاة وأهميتها"]},{"id":9623,"question":"أولى رسائل هذه الحلقة وردت من المستمعة (أ. س) من محافظة كركوك من العراق، تقول في رسالتها: عقد قراني على شاب ولم يدخل بي بعد، وأنا الآن أريد الطلاق منه لأسباب عديدة، منها: أنه رجل غير مؤدب وغير مثقف، فأثناء جلوسنا في المجلس يشتمني ويسبني أمام الناس هذا من ناحية، ومن ناحية أخرى: مضى على عقد النكاح بيننا أكثر من خمسة أشهر لكنه لا يصرف علي ولا يعطيني فلساً واحداً، فأضطر إلى أن أمد يدي إلى والدي ووالدتي وأطلب النقود منهما، ومن ناحية ثالثة: فهو رجل لا يصلي وإن صلى فيصلي يومين ويتركها شهر، فماذا عساي أن أفعل فقد نصحته مراراً ولم يفد معه، أفيدوني أفادكم الله هل يجوز لي الطلاق أم أنا آثمة بارك الله فيكم؟","title":"حكم طلب المرأة الطلاق من زوجٍ لا يصلي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا كان حال الزوج هو ما ذكرت أيها السائلة! من كونه يصلي بعض الأحيان ولا يصلي في أكثر الأحيان، فإن هذا لا يجوز لك أن تبقي معه؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء، ولو لم يجحد وجوبها.\nفالواجب عليك التخلص منه، ولا يجوز لك الدخول عليه، ولا يجوز بقاء هذا النكاح، بل هو والحال ما ذكر عقد باطل في أصح قولي العلماء، وعليك أن تحذري أن يمسك أو يقربك، وإذا لم يتيسر الطلاق ففي إمكانك أن ترفعي الأمر إلى المحكمة لهذه العلة، مع كونه أيضاً خبيث اللسان سباباً شتاماً فهذه علة أخرى، لكن علة ترك الصلاة أكبر وأعظم، نسأل الله السلامة والعافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7789/حكم-طلب-المراة-الطلاق-من-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25001.mp3","categories":["الطلاق","حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":9649,"question":"السؤال الرابع في رسالة الأخ (م. ر عبد الرب ) من عدن يقول فيه:شاب مسلم يريد الزواج من فتاة لا يعلم هي هل تصلي أم لا ؟ هل يجوز ذلك الزواج وما حكم ذلك، أفيدونا أفادكم الله؟","title":"حكم خطبة امرأة لا يُعلم أتصلي أم لا","answer":"الجواب: لابد أن يتثبت في الأمر؛ يسأل عنها أهل الخبرة، فإن الزواج من الكافرة لا يجوز والله يقول سبحانه: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] ومن ترك الصلاة كفر على الصحيح من أقوال العلماء ولو كان مقرًا بالوجوب، إذا تركها تهاونًا وكسلًا كفر كما قال النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفإذا كانت لا تصلي لا يتزوجها، وأما إذا عرف أنها تصلي وجيدة يتزوجها قال النبي ﷺ: تنكح المرأة لأربع لمالها ولجمالها ولحسبها ولدينها فاظفر بذات الدين تربت يداك، فذات الدين مطلوبة ... الصلاة التي هي أعظم الأركان وأهمها بعد الشهادتين. نعم.","link":"https://binbaz.org.sa/fatwas/7815/حكم-خطبة-امراة-لا-يعلم-اتصلي-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19411.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":9654,"question":"يسأل أيضاً ويقول: بلغت الاحتلام يعني: خروج الماء مني وأنا في الثالث عشرة من عمري، ولم أصل ولم أصم إلا عندما بلغت الخامسة عشرة، وذلك عن جهل مني، هل علي أن أقضي الصلاة والصيام في هذه السنتين الماضيتين أم لا؟","title":"حكم من كان يترك الصلاة جهلًا ثم تاب","answer":"الجواب: إذا كان الإنسان بلغ الحلم في الثالثة عشر بإنزال المني ثم ترك الصلاة والصيام جهلاً منه فلا قضاء عليه؛ لأن ترك الصلاة كفر وعليك التوبة إلى الله ، ترك الصلاة من البالغ كفر أكبر عند المحققين من أهل العلم، وهو إجماع الصحابة  وأرضاهم، ويدل عليه قول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وهو حديث صحيح رواه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة ، وهكذا قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في الصحيح عن جابر ، فالتوبة كافية متى تبت إلى الله توبة صادقة يكفي وليس عليك قضاء لا صوم ولا صلاة؛ لأن المرتد لا يقضي، وتارك الصلاة يعتبر مرتداً في أصح قولي العلماء فعليه التوبة إلى الله من جديد ولا يقضي شيئاً بل يستقبل أمره استقبالاً بالتوبة النصوح والاجتهاد في العمل الصالح، نسأل الله أن يثبتنا وإياك على التوبة الصحيحة.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7819/حكم-من-كان-يترك-الصلاة-جهلا-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25104.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9784,"question":"هذه رسالة من (م. ح. ق) من الرياض، تقول فيها صاحبتها: أنا امرأة متزوجة من رجل لا يصلي، وقد أنجبت منه ولدين، وأنا امرأة أصلي وأحافظ على عبادتي، وقد دعوته للصلاة كثيراً إلا أنه كان يرفض ويقول لي: إن الدين معاملة وأخلاق وليس حركات ولا ركعات، وهو مستقيم في بقية أموره الحياتية، وسؤالي: هل بقائي مع هذا الرجل حلال أم حرام، علماً بأن افتراقي عنه يشتت أولادي ويهدم أسرتي، ولكن خوف الله يجعلني أسألكم وأريد أن أعرف حكم الله أفادكم الله؟","title":"حكم بقاء المرأة مع زوج يترك الصلاة","answer":"الجواب: لا يجوز البقاء مع هذا الرجل الذي لا يصلي؛ لأن هذا يدل على قلة دينه أو عدم دينه بالكلية، فالصلاة عمود الإسلام من تركها عامداً كفر.\nفالواجب البعد عن هذا وأن لا تمكنيه من نفسك، وأن تذهبي إلى أهلك أو تمنعيه من نفسك بالكلية، حتى يتوب إلى الله وحتى يصلي، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة رضي الله عنه.\nوروى مسلم في الصحيح عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فالصلاة هي عمود الإسلام، فمن تركها عامداً كفر والعياذ بالله.\nأما الناسي فيقضي والنائم يقضي، لكن من تركها عمداً هذا كافر في أصح قولي العلماء.\nوذهب جمع من أهل العلم: إلى أنه لا يكفر بذلك كفراً أكبر، بل يكون كفره كفراً أصغر؛ لأنه الرسول سماه كافراً عليه الصلاة والسلام ولكنه قول ضعيف، قول مرجوح.\nوالصواب أنه كفر أكبر، قال عبد الله بن شقيق العقيلي : كان أصحاب النبي ﷺ لا يرون شيئاً تركه كفر من الأعمال إلا الصلاة فحكى عن الصحابة جميعاً أنهم يعتبرون ترك الصلاة كفراً، وظاهر ما نقله عنهم أنهم يعتبرونه كفراً أكبر.\nفالواجب عليك أيها الأخت في الله التخلص من هذا الرجل، وعدم تمكينه من نفسك وليس لك أن تبقي معه حتى يتوب إلى الله.\nوقوله: إن الدين المعاملة، كلام ليس بصحيح، بل حسن المعاملة من الدين ليس هو الدين، الدين حسن المعاملة مع الله ومع عباده، ما هو بالمعاملة فقط، حسن المعاملة وطيب المعاملة ومن حسن المعاملة أداء الصلاة، فإذا أراد بحسن المعاملة مع الله ومع عباده فلا تكون معاملة حسنة إلا بأداء فرائض الله وترك محارم الله.\nفمن ضيع فرائض الله أو ضيع الصلاة أو ركب المحارم فلم يقم بحسن المعاملة، ولم يأت بحسن المعاملة، فالدين: حسن المعاملة مع الناس في البيع والشراء والاتصال والصحبة ونحو ذلك، وحسن المعاملة مع الله بأداء فرائضه، ليس مجرد حسن معاملة مع الناس بس لا، بل لا بد من حسن المعاملة مع الله، بأداء فرائضه وترك محارمه .\nفالواجب عليك تقوى الله وأن تحذري من البقاء مع هذا الرجل، ونسأل الله له الهداية.\nأما إن جحد وجوبها وقال: ما هي بواجبة، أو استهزأ بالمصلين كفر إجماعاً، بإجماع المسلمين، إذا استهزأ بالمصلين أو جحد وجوبها كفر إجماعاً، نسأل الله العافية نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7956/حكم-بقاء-المراة-مع-زوج-يترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25909.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":9836,"question":"نبدأ أولاً برسالة نعمان علي حسن مقيم في الرياض بجوار المعهد العلمي يسأل عن تارك الصلاة، يقول المستمع نعمان: رجل في قرية لا يصلي ولا يصوم ولا يقوم إلا بما يتنافى مع شريعتنا السمحاء مثل: السرقة، والمشاحنة بين المسلمين، فهل إذا مات يغسل ويكفن ويصلى عليه، نرجو توضيح موقف المسلمين من هذا الشخص، جزاكم الله خير الجزاء؟","title":"حكم الصلاة على من مات تاركاً للصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم على عبده ورسوله نبينا وإمامنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهده إلى يوم الدين.\nأما بعد: فقد دلت سنة رسول الله ﷺ على أن من ترك الصلاة فإنه كافر، ومعلوم أن الكافر لا يغسل ولا يصلى عليه ولا يدفن في مقابر المسلمين بل يجب أن يوارى في الأرض في محل آخر غير مقابر المسلمين؛ لئلا يؤذي الناس بنتنه وجيفته.\nفالحاصل: أن من كان لا يصلي ومعروف بهذا فإنه لا يصلى عليه ولا يغسل، وإذا كان مع ذلك لا يصوم ويؤذي المسلمين صار الشر أكثر، ولكن العمدة في كفره على تركه للصلاة نسأل الله العافية، ومن ذلك مما ورد في ذلك قوله عليه الصلاة والسلام بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وقال عليه الصلاة والسلام العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأبو داود والترمذي والنسائي وابن ماجة بإسناد صحيح، وقال عليه الصلاة والسلام رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله هذه الأحاديث وما جاء في معناها كلها تدل على كفر تارك الصلاة نسأل الله العافية والسلامة، نعم.","link":"https://binbaz.org.sa/fatwas/8000/حكم-الصلاة-على-من-مات-تاركا-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_261/26101.mp3","categories":["حكم الصلاة وأهميتها","الصلاة على الميت"]},{"id":9838,"question":"وردتنا رسالة من المرسلة أم يوسف من القطر العراقي تسأل عن الصلاة وعن قراءة القرآن، تقول: إني كنت قاطعة للصلاة منذ مدة طويلة وفي الوقت الحالي رجعت إلى الصلاة كيف أعوض وأرجو الإجابة على هذا السؤال؟","title":"حكم الصلوات الفائتة بعد التوبة من تركها","answer":"الجواب: الإنسان إذا قطع الصلاة ثم من الله عليه بالتوبة فإن التوبة تجب ما قبلها، فإذا كان الإنسان لا يصلي من رجل أو امرأة ثم هداه الله ورجع إلى الصواب وصلى فإن التوبة تجب ما قبلها فعليه التوبة والندم والاستغفار والإكثار من العمل الصالح ولا قضاء عليه فيما مضى، لأن الكافر لا يقضي إذا أسلم والمرتد لا يقضي إذا أسلم ولكن التوبة تجب ما قبلها كما قاله النبي ﷺ: الإسلام يهدم ما كان قبله، والتوبة تهدم ما كان قبلها والله جل وعلا يعفو عما سلف بالتوبة الصادقة النصوح وهذا من فضله .\nيقول سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] ويقول جل وعلا لما ذكر الشرك والقتل والزنا قال: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70].\nفالمقصود أن التوبة يكفر الله بها ما مضى وليس عليه القضاء بعد إسلامه وتوبته ورجوعه إلى الله سواء كان كافراً أصلياً أو كان مرتداً بتركه الصلاة أو بسبه الله ورسوله أو باستهزائه بالدين أو بغير هذا من المكفرات فإنه متى تاب إلى الله من الناقض الذي نقض إسلامه وصدقت توبته فإن الله سبحانه يمحو عنه ما مضى وليس عليه إعادة لصومه ولا لصلاته نعم.","link":"https://binbaz.org.sa/fatwas/8004/حكم-الصلوات-الفاىتة-بعد-التوبة-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_261/26105.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9866,"question":"هذه رسالة من عبد العزيز علي حسن قناوي مصري يعمل بالعراق، يقول عبد العزيز علي حسن في رسالته: أنا أعمل بالعراق وأسكن وأعمل مع جماعة منهم من يسب دين الله، ونصحتهم ولكن ما زال بعضهم على ما هو عليه..ف ما حكم الشرع فيمن يسب الدين، وإذا كان يصلي هل صلاته صحيحة، وماذا علي تجاههم أفيدوني أفادكم الله؟","title":"حكم من يسب الدين وحكم صلاته، وواجبنا نحوه","answer":"الجواب: إذا رأيت من يسب الدين أو سمعت من يسب الدين تنصحه وتنكر عليه؛ لأن سب الدين كفر أكبر، وردة عن الإسلام إذا كان الساب مسلماً يرتد يكون كافراً، فعليك أن تنصح له وأن تنكر عليه المنكر، لقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ولقوله : وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104] ولقول النبي ﷺ: من رأى منكم منكراً فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان خرجه مسلم في صحيحه.\nفالواجب عليك وعلى غيرك من المؤمنين إنكار المنكر، فإذا رأيتم من يسب الدين أو لا يصلي، أو يشرب الخمر أو يعق والديه، أو يفعل شيئاً من المنكرات الأخرى فإن عليكم الإنكار عليه، وتوجيهه إلى الخير ونصيحته، لعل الله يهديه بأسبابكم، فإذا هداه الله صار لكم مثل أجره، وإن أبى فينبغي السعي في إبعاده من العمل والقضاء عليه، وإذا كان في دولة مسلمة فينبغي الرفع عنه إلى الدولة حتى تعاقبه، فإن تاب وإلا وجب قتله مرتداً عن الإسلام، لقول النبي ﷺ: من بدل دينه فاقتلوه فإن تاب من سبه ورجع جاز عند بعض أهل العلم تركه وعدم قتله، ولكن يؤدب.\nوبعض أهل العلم يرى أنه يقتل مطلقاً ولو تاب، لكن الأرجح إن شاء الله أنه متى تاب إلى الله ورجع وندم واستقام فإنه لا يقتل ، ولكن لا مانع من تأديبه على ما أقدم عليه، وعلى ما فعله، بجلدات أو سجن أو نحو ذلك.\nوالحاصل والخلاصة: أن الواجب على من لديه من المؤمنين الإنكار عليه، الإنكار عليه وتحذيره والاجتهاد في رده إلى الصواب، فإن لم يجد ذلك ولم يتيسر ذلك، فعل المؤمن ما يستطيع من السعي في فصله وإبعاده من العمل، من رفع أمره إلى ولاة الأمور إذا كان في بلد ينكر فيها المنكر، فإن خشيت على نفسك ولم يتيسر الرفع عن هؤلاء ولا توبتهم، فابتعد عن مخالطتهم إلى عمل آخر لعلك تنجو، والله ولي التوفيق.\nالمقدم: أثابكم الله، لكن السائل يقول: إن صاحبه هذا الذي يسب الدين يصلي فيسأل ما حكم صلاته؟\nالشيخ: سب الدين يبطل الأعمال، إذا سب الدين كفر، والكفر يبطل العمل، إذا مات عليه صاحبه، إذا مات الكافر على كفره بطل عمله، أما إن تاب قبل أن يموت بقي له عمله الصالح.","link":"https://binbaz.org.sa/fatwas/8041/حكم-من-يسب-الدين-وحكم-صلاته-وواجبنا-نحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26309.mp3","categories":["حكم الصلاة وأهميتها","نواقض الإسلام"]},{"id":9884,"question":"يسأل أيضاً ويقول: ما الحكم في الصلوات الفائتة علي، هل علي قضاؤها أم ماذا أفعل؛ لأنني سمعت حديثاً عن أنس ، يقول قال رسول لله ﷺ: من فاتته صلاة ولم يحصها فليقم في آخر جمعة من رمضان ويصلي أربع ركعات ويستغفر الله بعدها فهل هذا صحيح؟ أفيدوني أفادكم الله.","title":"حكم قضاء الصلاة على من تركها عمدًا","answer":"الجواب: ليس بصحيح ولا أصل له، ولكن عليه القضاء، إذا ترك صلوات نسياناً أو لأسباب مرض يحسب أنه يسوغ له التأخير أو لنوم فإنه يقضيها.\nأما إن كان عمداً ترك الصلاة عمداً ثم تاب الله عليه فإنه لا يقضي؛ لأن تركها عمداً كفر والكافر لا يقضي، هذا هو الصواب في ترك الصلاة إذا تركها ولو متهاوناً لا جاحداً فإنه يكفر بذلك، أما إن ترك الصلاة عامداً جاحداً لوجوبها هذا يكفر عند جميع أهل العلم، لكن إذا كان يقر بوجوبها، يعلم أنها واجبة عليه ولكنه تركها تهاوناً وتكاسلاً فهذا فيه نزاع بين أهل العلم. والصواب والراجح في هذه المسألة: كفره كفر أكبر فلا قضاء عليه لما ترك عمداً تهاوناً، أما ما تركه عن مرض يظن أنه يسوغ له التأخير، أو تركه عن نسيان أو عن نوم هذا يقضي، لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك.\nوأما الذي يتركها عمداً تهاوناً فهذا هو الذي لا يقضي وعليه التوبة إلى الله جل وعلا؛ لأن تركها تهاوناً عمداً كفر أكبر، والكافر عليه التوبة، وإذا تاب لا يقضي لقوله : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] ولقوله ﷺ: التوبة تهدم ما كان قبلها، والإسلام يهدم ما كان قبله وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله وقال أيضاً عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة.\nخرجه مسلم في صحيحه رحمه الله.\nفهذه النصوص وما جاء في معناها كلها دالة على كفر من ترك الصلاة عمداً، تهاوناً وتكاسلاً لا عن علة من نوم أو مرض يظن أنه يسوغ له معه التأخير، أو عن نسيان فالناسي والنائم والمريض الذي يظن أنه يجوز له التأخير يقضي، وأما المتعمد المتساهل هذا لا يقضي وعليه التوبة إلى الله . نعم.\nالمقدم: أثابكم الله وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8055/حكم-قضاء-الصلاة-على-من-تركها-عمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26412.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":9925,"question":"هذه رسالة وردتنا من مرسلة رمزت لاسمها بأختكم في الله (ص. س) من القيصومة في المملكة تقول في رسالتها: أنا سيدة في الأربعين من عمري لي أطفال سبعة ثلاثة اختارهم الله عز وجل إليه وأربعة أحياء، تقول: تتلخص مشكلتي في عدة أسئلة:أولها: أنني متزوجة منذ عشرين سنة من رجل لا يعرف الصلاة ولا الصيام ويشرب المحرمات من خمر وما شابهه والعياذ بالله، وكلما حاولت الخلاص منه يقول لي: بأنه سوف يتوب، ولكنه بالكلام فقط، وكل من أشكي له حالي يقول: اصبري من أجل أطفالك، وقد صبرت كل هذه السنوات من أجلهم، والآن كبروا وأصبحوا رجال ويطلبون هم مني ذلك ويقولون بأن البيت بيتهم ولا دخل للوالد، وأنا أسألكم الآن: هل علي ذنب في جلوسي معه أم لا، وكذلك جلوس أطفالي عنده؟ أفيدوني أفادكم الله.","title":"حكم البقاء مع زوج لا يصلي ويفعل الكبائر","answer":"الجواب: لا ريب أن ترك الصلاة كفر، ولا ريب أن ترك الصيام من أعظم المعاصي، ولا ريب أن شرب المسكر من أعظم المعاصي والكبائر، فهذا الرجل قد جمع أنواعاً من الخبث والشر وأعظم ذلك ترك الصلاة، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة فهذان حديثان عظيمان صحيحان عن رسول الله عليه الصلاة والسلام كلاهما يدل على كفر هذا الرجل، والمسألة فيها خلاف:\nبعض أهل العلم يقولون: لا يكفر إلا إذا كان لا يعتقد الوجوب، إذا كان ينكر وجوبها، وإلا فإنه يكون عاصياً معصية عظيمة ولكن لا يكفر بذلك.\nوذهب آخرون من أهل العلم: إلى أنه يكفر بترك الصلاة ولو لم ينكر وجوبها، وهذا هو الحق وهو الصواب أنه يكفر بترك الصلاة ولو لم ينكر وجوبها، فالذي أنصحك به وأوصيك به أن تمتنعي منه، وأن لا تمكنيه من نفسك حتى يتوب إلى الله ويرجع إلى الصلاة، والأولاد أولاده للشبهة التي هي شبهة النكاح، والقول بأنه لا يكفر بذلك هذه شبهة، فالأولاد أولاده ولا شك أنهم أولاده، ولكنك تبقين في البيت عند أولادك لأنهم كبار، وتمتنعين من أن يقربك بجماع أو غيره حتى يتوب إلى الله وحتى يدع عمله السيئ ولا سيما ترك الصلاة، فإذا تاب إلى الله وصلى فلا مانع، وعليه أن يتوب إلى الله أيضاً من ترك الصيام ومن شرب الخمر، وعلى أولاده أن يعينوه على الخير وأن ينصحوه ويستعينوا على هذا بأقاربهم الطيبين من أعمام وبني عم طيبين يعينونهم على نصيحة والدهم لعل الله يهديه بأسبابهم، فإن من أعظم بره أن ينصح ويوجه إلى الخير لعل الله يهديه بذلك، ولعله يسمع كلمتي هذه، ولعلكم تسجلونها إذا سمعتموها وتقرءونها عليه، فالله جل وعلا نسأله له الهداية. فالحاصل أن عليك أن تبتعدي عنه وألا يقربك حتى يتوب إلى الله من ترك الصلاة، فإذا تاب من ترك الصلاة فهو زوجك، وأما شرب الخمر وترك الصيام فهما معصيتان عظيمتان، لكنهما لا يوجبان بطلان النكاح عند أهل العلم عند أهل السنة والجماعة ، وعليك وعلى أولادك وعلى أقاربه وعلى الأخيار من جيرانه أن ينصحوه، وعليه أن يتقي الله وأن يبادر إلى التوبة قبل أن يحل به الأجل، قبل أن ينزل به الأجل، والخمر شرها عظيم، وقد صح عن رسول الله عليه الصلاة والسلام: أنه لعن الخمر وشاربها وساقيها وعاصرها ومعتصرها وحاملها والمحمولة إليه وبائعها ومشتريها وآكل ثمنها نعوذ بالله، وصح عن رسول الله أيضاً عليه الصلاة والسلام أنه قال: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن فهذا يدل على ضعف الإيمان أو عدم الإيمان نسأل الله العافية، وقال عليه الصلاة والسلام: إن عهداً على الله لمن مات وهو يشرب الخمر أن يسقيه الله من طينة الخبال، قيل: يا رسول الله! وما طينة الخبال؟ قال: عصارة أهل النار، أو قال: عرق أهل النار.\nوأما ترك صيام رمضان فهو أمر عظيم؛ لأن صيام رمضان من أعظم الواجبات ومن أركان الإسلام، وقد ذهب بعض أهل العلم إلى كفر من ترك الصيام عمداً، فيجب عليه أن يتوب إلى الله وأن يصوم رمضان وأن يحافظ على الصلاة ومن تاب تاب الله عليه، نسأل الله لنا وله ولجميع المسلمين التوفيق للتوبة النصوح والهداية إلى سبيل الخير، والعافية من طاعة الشيطان ومن طاعة قرناء السوء، وينبغي أن يوصى باجتناب قرناء السوء وصحبة الأشرار؛ فإن صحبة الأشرار تجره كثيراً، تضره كثيراً وتجره إلى أسباب الفساد وإلى أسباب غضب الله. فالواجب عليه أن يحذر صحبة الأشرار وأن يبتعد عن قرناء السوء وأن يتوب إلى الله من ترك الصلاة ومن ترك الصيام ومن شرب المسكر، وأن يستقيم على طاعة الله ورسوله، والله يقول جل وعلا: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، والنبي يقول ﷺ: التائب من الذنب كمن لا ذنب له نسأل الله لنا ولكم وله ولجميع المسلمين الهداية والتوفيق والتوبة الصادقة.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8100/حكم-البقاء-مع-زوج-لا-يصلي-ويفعل-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_269/26905.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":9936,"question":"أولى رسائل هذه الحلقة وردت من عبد الحميد أحمد محمد علي جمهورية مصر العربية - قنا، يقول: لم أصل إلا بعد ما بلغت الرابعة والعشرين من عمري، وصرت الآن أصلي مع كل فرض فرضاً آخر، فهل يجوز لي ذلك، وهل أداوم على هذا، أم أن علي حقوقاً أخرى؟ أفيدوني أفادكم الله!","title":"هل على التائب من ترك الصلاة قضاء؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالذي يترك الصلاة عمدًا ليس عليه قضاء على الصحيح وإنما عليه التوبة إلى الله ؛ لأن الصلاة عمود الإسلام، وتركها من أعظم الجرائم، بل تركها نوع من الكفر، إذا تركها عمداً كفر كفرًا أكبر في أصح قولي العلماء؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة رضي الله عنه، ولقوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه عن جابر بن عبد الله رضي الله عنهما في أحاديث أخرى تدل على ذلك، فالواجب عليك يا أخي التوبة إلى الله، التوبة الصادقة وذلك بالندم على ما مضى منك، والإقلاع من ترك الصلاة، والعزم الصادق أن لا تعود في ذلك، وليس عليك أن تقضي لا مع كل صلاة ولا في غير ذلك، بل عليك التوبة فقط، والحمد لله من تاب تاب الله عليه، يقول الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ويقول النبي ﷺ: التائب من الذنب كمن لا ذنب له فعليك أن تصدق في التوبة وأن تحاسب نفسك، وأن تجتهد في المحافظة على الصلاة في أوقاتها في الجماعة، وأن تستغفر الله مما جرى منك، وتكثر من العمل الصالح وأبشر بالخير، يقول الله سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] ولما ذكر الشرك والقتل والزنا قال جل وعلا بعد ذلك: وَمَنْْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا ۝ إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا[الفرقان:68-70] نسأل الله لنا ولك التوفيق وصحة التوبة والاستقامة على الخير. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8106/هل-على-التاىب-من-ترك-الصلاة-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27401.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":9946,"question":"هذا السائل محمد علوي قايد يماني الجنسية يسأل أيضاً ويقول: لي أخ من أبي وأمي لا يصلي وقد نصحته وبينت له ما وعد الله به قاطع الصلاة في الدنيا وفي الآخرة، وما يحل به من عذاب في القبر ولم يستجب للنداء، وقد أمضى معي في الغربة حوالي أربع سنوات وأنا أنصحه ولكن بدون فائدة، و هل يجوز لي مقاطعته؟ وهل يجوز رد السلام عليه؟ وهل إذا قاطعته وكانت هذه المقاطعة سبب في غضب والدتي علي، هل علي في ذلك إثم؟ ويسأل عن الأكل والشرب معه إلى آخره؟","title":"حكم مقاطعة الأخ التارك للصلاة بعد نصحه","answer":"الجواب: قد أحسنت في نصيحته والاستمرار في ذلك، أما كونه استمر في مقاطعة الصلاة ولم يوفق لقبول النصيحة، فهذا إلى الله  هو الذي يهدي من يشاء ويضل من يشاء، فعليك أن تدعو له كثيراً بالهداية وهكذا الوالدة تدعو له بالهداية: أن الله يهديه ويرده إلى الصواب، في السجود في آخر الصلاة، في أوقات الإجابة مثل: آخر الليل مثل: بين الأذان والإقامة لعل الله يهديه ولعل الله يستجيب دعاءك ودعاء الوالدة، أما المقاطعة فالواجب مقاطعته ما دام لم يقبل فالواجب هجره ومقاطعته، لعله يستفيد من هذا الهجر ولعل الله يهديه بذلك، ولا تتخذه جليساً يكون أكيلك أو شريبك ولا تجب دعوته إذا كان في بيت آخر إذا دعاك، بل تظهر له المقاطعة والبغضاء حتى يهديه الله عز وجل، وهكذا الوالدة عليها أن تنكر عليه وعليها أن تبغضه في الله، وعليها أن تقاطعه حتى يهديه الله؛ لأن ترك الصلاة كفر أكبر في الصحيح من قولي العلماء، يقول النبي ﷺ: رأس الأمر الإسلام وعموده الصلاة ويقول النبي أيضاً عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ويقول عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة فالصلاة عمود الإسلام من أضاعها أضاع دينه نسأل الله العافية. ويقول النبي ﷺ لما ذكر الصلاة يوماً قال: من حافظ عليها كانت له نوراً وبرهاناً ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف وهؤلاء من صناديد الكفار ومن أخبث الكفار. فبين ﷺ أن من ضيع الصلاة يحشر مع هؤلاء الكفرة نسأل الله العافية، فالمقصود أن الواجب عليك وعلى الوالدة النصيحة وقد بذلت منك النصيحة، وعلى الوالدة أن تبذل النصيحة وبعد ذلك لا بد من مقاطعة ولا بد من إعلان البغضاء له، حتى يعرف أنكما تبغضانه في الله وأنكما تقاطعانه في هذا الأمر، لعل الله يهديه ويمن عليه بالتوبة ولا مانع من النصيحة بعد ذلك بين وقت وآخر بالكلام أو بالتلفون أو بالبرقيات والكتابة أو نحو ذلك لا مانع أن يستمر المؤمن في النصيحة، لكن مع البغضاء في الله ومع الهجر في الله، كما قال الله : قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ وَالَّذِينَ مَعَهُ إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ أَبَدًا حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ [الممتحنة:4] فترك الصلاة كفر وضلال نسأل الله العافية، نسأل الله له الهداية ونسأل الله أن يعينك والوالدة على كل خير، وأن ينفع بنصيحتكما وأن يقبل دعواتكما له حتى يهديه الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8117/حكم-مقاطعة-الاخ-التارك-للصلاة-بعد-نصحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26709.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":9950,"question":"هذا السائل محمد علوي قايد يماني الجنسية يسأل أيضاً ويقول: لي أخ من أبي وأمي لا يصلي وقد نصحته وبينت له ما وعد الله به قاطع الصلاة في الدنيا وفي الآخرة، وما يحل به من عذاب في القبر ولم يستجب للنداء، وقد أمضى معي في الغربة حوالي أربع سنوات وأنا أنصحه ولكن بدون فائدة، و هل يجوز لي مقاطعته؟ وهل يجوز رد السلام عليه؟ وهل إذا قاطعته وكانت هذه المقاطعة سبب في غضب والدتي علي، هل علي في ذلك إثم؟ ويسأل عن الأكل والشرب معه إلى آخره؟","title":"حكم مقاطعة الأخ التارك للصلاة بعد نصحه","answer":"الجواب: قد أحسنت في نصيحته والاستمرار في ذلك، أما كونه استمر في مقاطعة الصلاة ولم يوفق لقبول النصيحة، فهذا إلى الله  هو الذي يهدي من يشاء ويضل من يشاء، فعليك أن تدعو له كثيراً بالهداية وهكذا الوالدة تدعو له بالهداية: أن الله يهديه ويرده إلى الصواب، في السجود في آخر الصلاة، في أوقات الإجابة مثل: آخر الليل مثل: بين الأذان والإقامة لعل الله يهديه ولعل الله يستجيب دعاءك ودعاء الوالدة، أما المقاطعة فالواجب مقاطعته ما دام لم يقبل فالواجب هجره ومقاطعته، لعله يستفيد من هذا الهجر ولعل الله يهديه بذلك، ولا تتخذه جليساً يكون أكيلك أو شريبك ولا تجب دعوته إذا كان في بيت آخر إذا دعاك، بل تظهر له المقاطعة والبغضاء حتى يهديه الله عز وجل، وهكذا الوالدة عليها أن تنكر عليه وعليها أن تبغضه في الله، وعليها أن تقاطعه حتى يهديه الله؛ لأن ترك الصلاة كفر أكبر في الصحيح من قولي العلماء، يقول النبي ﷺ: رأس الأمر الإسلام وعموده الصلاة ويقول النبي أيضاً عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ويقول عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة فالصلاة عمود الإسلام من أضاعها أضاع دينه نسأل الله العافية. ويقول النبي ﷺ لما ذكر الصلاة يوماً قال: من حافظ عليها كانت له نوراً وبرهاناً ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف وهؤلاء من صناديد الكفار ومن أخبث الكفار. فبين ﷺ أن من ضيع الصلاة يحشر مع هؤلاء الكفرة نسأل الله العافية، فالمقصود أن الواجب عليك وعلى الوالدة النصيحة وقد بذلت منك النصيحة، وعلى الوالدة أن تبذل النصيحة وبعد ذلك لا بد من مقاطعة ولا بد من إعلان البغضاء له، حتى يعرف أنكما تبغضانه في الله وأنكما تقاطعانه في هذا الأمر، لعل الله يهديه ويمن عليه بالتوبة ولا مانع من النصيحة بعد ذلك بين وقت وآخر بالكلام أو بالتلفون أو بالبرقيات والكتابة أو نحو ذلك لا مانع أن يستمر المؤمن في النصيحة، لكن مع البغضاء في الله ومع الهجر في الله، كما قال الله : قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ وَالَّذِينَ مَعَهُ إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ أَبَدًا حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ [الممتحنة:4] فترك الصلاة كفر وضلال نسأل الله العافية، نسأل الله له الهداية ونسأل الله أن يعينك والوالدة على كل خير، وأن ينفع بنصيحتكما وأن يقبل دعواتكما له حتى يهديه الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8117/حكم-مقاطعة-الاخ-التارك-للصلاة-بعد-نصحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26709.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":9958,"question":"أخيراً يسأل ويقول: حدث حوار بيني وبين صديق لي عن الإسلام حيث قال هذا الصديق: إنه لا يصلي على الإطلاق، فقلت له: أنت كافر؛ لأن الله تعالى يقول: أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتَابِ وَتَكْفُرُونَ بِبَعْضٍ فَمَا جَزَاءُ مَنْ يَفْعَلُ ذَلِكَ مِنْكُمْ إِلَّا خِزْيٌ فِي الْحَيَاةِ الدُّنْيَا وَيَوْمَ الْقِيَامَةِ يُرَدُّونَ إِلَى أَشَدِّ الْعَذَابِ [البقرة:85]، وقال لي: أنت أيضاً كذلك وذكر لي القول: من كفر مسلماً فقد كفر وبعد ذلك تركته وذهبت حتى لا يحتدم النقاش إلى أكثر مما ووصل إليه، فما حكم كلامنا هذا الذي تم بيننا؟ وهل نأثم عليه؟","title":"حكم تارك الصلاة عمداً تساهلاً وحكم تكفيره","answer":"الجواب: الصواب أن من ترك الصلاة فهو كافر وإن كان غير جاحد لها، هذا هو القول المختار والمرجح عند المحققين من أهل العلم؛ لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن عن بريدة بن الحصيب ، ولقوله أيضاً صلى الله وسلم عليه وعلى آله وأصحابه: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه، ولقوله أيضاً عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة وذروة سنامه الجهاد في سبيل الله خرجه الإمام أحمد والإمام الترمذي رحمة الله عليهما بإسناد صحيح عن معاذ ، وأحاديث أخرى جاءت في الباب، فالواجب على من ترك الصلاة أن يتوب إلى الله وأن يبادر بفعلها ويندم على ما مضى من تقصيره ويعزم أن لا يعود فهذا هو الواجب عليه. وذهب بعض أهل العلم إلى أنه يكون عاصياً معصية كبيرة يكون عاصياً معصية كبيرة، وجعل هذا الكفر كفراً أصغر واحتج بما جاء في الأحاديث الصحيحة من فضل التوحيد ومن مات عليه فهو من أهل الجنة إلى غير هذا، لكنها لا تدل على المطلوب فإنما جاء في فضل التوحيد وأن من مات عليه فهو من أهل الجنة، إنما يكون بالتزامه أمور الإسلام ومن ذلك أمر الصلاة، فمن التزم بها حصل له ما وعد به المتقون ومن أبى حصل عليه ما توعد به غير المتقين، ولو أن إنساناً قال: لا إله إلا الله ووحد الله ثم جحد وجوب الصلاة كفر ولم ينفعه قوله: لا إله إلا الله، أو توحيده لله مع جحده وجوب الصلاة، فهكذا من تركها تساهلاً وعمداً وقلة مبالاة حكمه حكم من جحد وجوبها في الصحيح ولا تنفعه شهادته بأنه لا إله إلا الله؛ لأنه ترك حق هذه الكلمة فإن من حقها أن يؤدي الصلاة، وهكذا لو وحد الله وأقر بأنه لا إله إلا الله ولكنه استهزأ بشيء من دين الله، فإنه يكفر كما قال الله : قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66] وهكذا لو قال: لا إله إلا الله ووحد الله وجحد وجوب الزكاة أو جحد وجوب صوم رمضان أو جحد الحج مع الاستطاعة أو جحد تحريم الزنا أو جحد تحريم السرقة أو جحد تحريم اللواط أو ما أشبه ذلك، فإنها من جحد هذه الأمور كفر إجماعاً، ولو أنه يصلي ويصوم ولو أنه يقول: لا إله إلا الله؛ لأن هذه النواقض تفسد عليه دينه وتجعله بريئاً من الإسلام بهذه النواقض، فينبغي للمؤمن أن ينتبه لهذا الأمر، فهكذا من ترك الصلاة وتساهل بها يكون كافراً وإن لم يجحد وجوبها، في الأصح من قولي العلماء للأحاديث السابقة وما جاء في معناها. فنسأل الله أن يصلح أحوال المسلمين وأن يرد كافرهم إلى التوبة، ومن ذلك من ترك الصلاة نسأل الله أن يهديه للإسلام ويرده إلى ما أوجب الله عليه من إقامة الصلاة، وأن يمن عليه بالتوبة الصادقة النصوح والله المستعان. نعم.\nالمقدم: أثابكم الله، سماحة شيخنا، لا أدري هذا السائل ذكر أنه كفر هذا الشخص المعين، يعني: أطلق عليه الكفر وهذا رد عليه بقول، ما أدري ما الحكم في هذا؟\nالشيخ: نعم، قوله: من كفر مسلماً فقد كفر هذا إذا كان التكفير في غير محله، كما قال النبي ﷺ: من قال لأخيه: يا عدو الله أو قال: يا كافر وليس كذلك إلا حار عليه لكن هذا الذي قال له: أنت كافر في ترك الصلاة، قد وقعت في محلها قد وقع تكفيره في محله، فهذا يرجع إلى القائل، فلا يكون قائله كافراً، بل القائل قد نفذ أمر الله وأدى حق الله وبين ما أوجبه الله من تكفير هذا الصنف من الناس، فهو مأجور وليس بكافر، وإنما الكافر الذي ترك الصلاة وعاند وكابر، نسأل الله العافية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8151/حكم-تارك-الصلاة-عمدا-تساهلا-وحكم-تكفيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26609.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9963,"question":"وهذه رسالة وردتنا من صلاح عبدالرحمن حسين مصري الجنسية يقيم بالعراق بالبصرة، يقول هذا السائل في رسالته: أسكن في حجرة مع بعض الإخوة المصريين وهم لا يصلون وأنا أصلي والحمد لله، ولكنني أنصحهم بالصلاة فيعتذرون بأعذار غير مقنعة، ولذلك فأنا لا أقبل أن أشترك معهم في الأكل وآكل لوحدي، وعندما تكلموا كثيراً حول سبب أكلي وحدي، ذكرت لهم أني لا آكل مع مسلم لا يصلي، فهل فعلي معهم هذا صحيح أم لا؟","title":"حكم ترك معاشرة تاركي الصلاة ومؤاكلتهم","answer":"الجواب: نعم قد أحسنت وأصبت ما داموا يكابرون في ترك الصلاة ولم يقبلوا نصيحتك، فالواجب بغضهم في الله وعدم مصاحبتهم وعدم الأكل معهم؛ لأن هؤلاء مرتدون عن الإسلام في أصح قولي العلماء، من ترك الصلاة صار مرتداً في أصح قولي العلماء، فالواجب نبذهم وعدم صحبتهم، وينبغي أن لا تبقى معهم في الحجرة أيضاً بل تكون في محل آخر حتى لا يضرك قربهم؛ لأن صحبة الأشرار والقرب منهم فيه الخطر العظيم، فنسأل الله أن يمن عليهم بالتوبة وأن يهديهم لرشدهم وأن يعيذهم من شر الشيطان والنفس الأمارة بالسوء وأن يمن عليهم بالتوبة، أما أنت فقد أحسنت في نصيحتهم وقد أحسنت في مفارقتهم حتى لا يصيبك شيء من شرهم. نعم.\nالمقدم: أثابكم الله، هو في الحقيقة يقول في آخر هذا السؤال: أنا لا أستطيع أن أسكن لوحدي نظراً لارتفاع الأجور وقد بحثت عن أناس يصلون لأسكن معهم حتى أفارق هؤلاء فلم أستطع، فما حكم بقائي مع مفارقتي لهم في الأكل ونحوه؟\nالشيخ: لا حرج عليك حتى تجد مخلصاً، لا حرج عليك من البقاء معهم مع بغضهم في الله ومع النصيحة لهم حتى تجد مكاناً آخر وحتى تجد أصحاباً آخرين وأبشر بالخير، يقول الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، ويقول : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فأبشر سوف يجعل الله لك فرجاً ومخرجاً؛ بسبب صدقك وبسبب جهادك في سبيل الله في نصيحة هؤلاء والبعد من شرهم والبراءة من عملهم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8152/حكم-ترك-معاشرة-تاركي-الصلاة-ومواكلتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26610.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9967,"question":"أخيراً يسأل ويقول: حدث حوار بيني وبين صديق لي عن الإسلام حيث قال هذا الصديق: إنه لا يصلي على الإطلاق، فقلت له: أنت كافر؛ لأن الله تعالى يقول: أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتَابِ وَتَكْفُرُونَ بِبَعْضٍ فَمَا جَزَاءُ مَنْ يَفْعَلُ ذَلِكَ مِنْكُمْ إِلَّا خِزْيٌ فِي الْحَيَاةِ الدُّنْيَا وَيَوْمَ الْقِيَامَةِ يُرَدُّونَ إِلَى أَشَدِّ الْعَذَابِ [البقرة:85]، وقال لي: أنت أيضاً كذلك وذكر لي القول: من كفر مسلماً فقد كفر وبعد ذلك تركته وذهبت حتى لا يحتدم النقاش إلى أكثر مما ووصل إليه، فما حكم كلامنا هذا الذي تم بيننا؟ وهل نأثم عليه؟","title":"حكم تارك الصلاة عمداً تساهلاً وحكم تكفيره","answer":"الجواب: الصواب أن من ترك الصلاة فهو كافر وإن كان غير جاحد لها، هذا هو القول المختار والمرجح عند المحققين من أهل العلم؛ لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن عن بريدة بن الحصيب ، ولقوله أيضاً صلى الله وسلم عليه وعلى آله وأصحابه: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه، ولقوله أيضاً عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة وذروة سنامه الجهاد في سبيل الله خرجه الإمام أحمد والإمام الترمذي رحمة الله عليهما بإسناد صحيح عن معاذ ، وأحاديث أخرى جاءت في الباب، فالواجب على من ترك الصلاة أن يتوب إلى الله وأن يبادر بفعلها ويندم على ما مضى من تقصيره ويعزم أن لا يعود فهذا هو الواجب عليه. وذهب بعض أهل العلم إلى أنه يكون عاصياً معصية كبيرة يكون عاصياً معصية كبيرة، وجعل هذا الكفر كفراً أصغر واحتج بما جاء في الأحاديث الصحيحة من فضل التوحيد ومن مات عليه فهو من أهل الجنة إلى غير هذا، لكنها لا تدل على المطلوب فإنما جاء في فضل التوحيد وأن من مات عليه فهو من أهل الجنة، إنما يكون بالتزامه أمور الإسلام ومن ذلك أمر الصلاة، فمن التزم بها حصل له ما وعد به المتقون ومن أبى حصل عليه ما توعد به غير المتقين، ولو أن إنساناً قال: لا إله إلا الله ووحد الله ثم جحد وجوب الصلاة كفر ولم ينفعه قوله: لا إله إلا الله، أو توحيده لله مع جحده وجوب الصلاة، فهكذا من تركها تساهلاً وعمداً وقلة مبالاة حكمه حكم من جحد وجوبها في الصحيح ولا تنفعه شهادته بأنه لا إله إلا الله؛ لأنه ترك حق هذه الكلمة فإن من حقها أن يؤدي الصلاة، وهكذا لو وحد الله وأقر بأنه لا إله إلا الله ولكنه استهزأ بشيء من دين الله، فإنه يكفر كما قال الله : قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66] وهكذا لو قال: لا إله إلا الله ووحد الله وجحد وجوب الزكاة أو جحد وجوب صوم رمضان أو جحد الحج مع الاستطاعة أو جحد تحريم الزنا أو جحد تحريم السرقة أو جحد تحريم اللواط أو ما أشبه ذلك، فإنها من جحد هذه الأمور كفر إجماعاً، ولو أنه يصلي ويصوم ولو أنه يقول: لا إله إلا الله؛ لأن هذه النواقض تفسد عليه دينه وتجعله بريئاً من الإسلام بهذه النواقض، فينبغي للمؤمن أن ينتبه لهذا الأمر، فهكذا من ترك الصلاة وتساهل بها يكون كافراً وإن لم يجحد وجوبها، في الأصح من قولي العلماء للأحاديث السابقة وما جاء في معناها. فنسأل الله أن يصلح أحوال المسلمين وأن يرد كافرهم إلى التوبة، ومن ذلك من ترك الصلاة نسأل الله أن يهديه للإسلام ويرده إلى ما أوجب الله عليه من إقامة الصلاة، وأن يمن عليه بالتوبة الصادقة النصوح والله المستعان. نعم.\nالمقدم: أثابكم الله، سماحة شيخنا، لا أدري هذا السائل ذكر أنه كفر هذا الشخص المعين، يعني: أطلق عليه الكفر وهذا رد عليه بقول، ما أدري ما الحكم في هذا؟\nالشيخ: نعم، قوله: من كفر مسلماً فقد كفر هذا إذا كان التكفير في غير محله، كما قال النبي ﷺ: من قال لأخيه: يا عدو الله أو قال: يا كافر وليس كذلك إلا حار عليه لكن هذا الذي قال له: أنت كافر في ترك الصلاة، قد وقعت في محلها قد وقع تكفيره في محله، فهذا يرجع إلى القائل، فلا يكون قائله كافراً، بل القائل قد نفذ أمر الله وأدى حق الله وبين ما أوجبه الله من تكفير هذا الصنف من الناس، فهو مأجور وليس بكافر، وإنما الكافر الذي ترك الصلاة وعاند وكابر، نسأل الله العافية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8151/حكم-تارك-الصلاة-عمدا-تساهلا-وحكم-تكفيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26609.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":9976,"question":"هذه رسالة من السائل موسى عبدالحميد سوري الجنسية مقيم في الرياض، الأخ موسى يقول في رسالته: إن زوجتي لا تصلي وقد أمرتها بالصلاة أكثر من مرة لكنها لم تستجب، وكذلك هي لا تتحجب وشعرها ظاهر على كل الناس، أفيدوني ماذا أفعل معها؟","title":"ما يفعل من ابتلي بزوجة تاركة للصلاة والحجاب؟","answer":"الجواب: هذه المرأة قد اجتمع فيها شران عظيمان أحدهما أعظم من الآخر.\nالشر الأول: عدم الصلاة، وهذا كفر أكبر على الصحيح.\nوالشر الثاني: عدم تسترها وحجابها، فالواجب أن تفارقها؛ لأنه ليس للمسلم أن يمسك الكافرة، قال الله تعالى: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] فالواجب عليك فراقها ما دامت لم تستجب للنصيحة فالواجب فراقها وأبشر بأن يعوضك الله خيرًا منها، ونسأل الله لها الهداية.\nفالمقصود أن هذه المرأة فيها شران عظيمان أحدهما أعظم من الآخر وهو ترك الصلاة، هذا أعظم وهذا كفر أكبر، وكونها غير محتجبة لا في شعرها ولا في وجهها هذا أيضًا كبيرة عظيمة وشر عظيم.\nفالواجب عليك فراقها والحذر منها وإعطاؤها طلاقها نسأل الله لنا ولكم العافية، ومن ترك شيئًا لله عوضه الله خيرًا منه وسوف يعوضك الله سبحانه وتعالى فضلًا منه خيرًا منها وأصلح إن شاء الله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8133/ما-يفعل-من-ابتلي-بزوجة-تاركة-للصلاة-والحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20005.mp3","categories":["اللباس والزينة","حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":10001,"question":"تقول: عندما كنت في الثانية عشرة والثالثة عشرة والرابعة عشرة من عمري أفطرت أيامًا كثيرة في رمضان تلك السنين، ولا أعلم كم عدد هذه الأيام، والآن بعد مضي عدة سنوات صحوت من غفلتي ولله الحمد والمنة، وتذكرت تلك الأيام التي أفطرتها فأردت أن أصوم ثلاثة أشهر، فصمت ستة عشر يومًا منها، ولكني الآن توقفت عن صيامها، وذلك بعد أن سمعت في برنامج نور على الدرب: أن الذي لا يصلي بحكم الكافر الذي لا يقبل منه أي عمل حتى الصيام، وحيث أنني في تلك السنوات كنت لا أصلي بعض الصلوات كسلًا، وبالإضافة إلى ذلك كنت بعد العادة الشهرية أجلس يومًا كاملًا لا أصلي فيه بحجة أن أتبين هل تطهرت تطهرًا كاملًا أم لا، فماذا أفعل، أفيدوني جزاكم الله خيرًا؟","title":"حكم من أفطر أيامًا من رمضان مع تركه للصلاة","answer":"الجواب: يكفي التوبة في هذا، يكفيك يا أيها الأخت! في الله التوبة، عليك بالتوبة والحمد لله، التوبة الندم على الماضي، والعزيمة أن لا تعودين مع الاستغفار والحمد لله؛ لأن ترك الصلاة كفر كما قال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فالذي لا يصلي لا صوم له ولا زكاة له ولا غير ذلك، فلا يلزمك القضاء حينئذ وإنما عليك التوبة، والحمد لله الذي من عليك بالتوبة والالتزام.\nالمقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8166/حكم-من-افطر-اياما-من-رمضان-مع-تركه-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33106.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":10035,"question":"يقول: ماذا أفعل مع بعض أفراد البيت الذين لا يصلون، مثل أخي أو زوجة أخي أو أخي زوجتي؟ ماذا أفعل تجاههم إذا لم تنفع فيهم النصيحة؟","title":"ما يفعل من ابتُلي بأقارب لا يصلون","answer":"الجواب: الواجب الاستمرار في النصيحة وأن تنصحهم لأن الصلاة عمود الإسلام من تركها كفر نعوذ بالله من ذلك، فالواجب أن تنصح لهم وأن تجتهد في ذلك حسب الطاقة ولا تضعف ولا تدع النصيحة ولعل الله أن يهديهم بأسبابك، والذي لا يقبل ويعني قد تابعت النصيحة ولم يقبل يستحق أن يهجر حتى لا يسلم عليه ولا يرد عليه السلام ولا تقبل دعوته للطعام ولا يدعى للطعام، يستحق أن يهجر لأن الصلاة عمود الإسلام من تركها كفر نعوذ بالله من ذلك.\nفالواجب عليك أن تناصحهم وأن تستمر في النصيحة والذي لا يقبل النصيحة ويستمر في باطله يستحق أن يهجر، وإذا كنت تستطيع أن تؤدبه لكونه زوجة أو ولد أدبته حتى يستقيم حتى يصلي وحتى تصلي وتقوم بالواجب، وأما زوجة أخيك أو زوجة أبيك أو نحوهما ممن لا تستطيع تأديبه فهذا على أخيك وعلى أبيك أن يقوما بالواجب، على أخيك أن يؤدب زوجته حتى تستقيم وحتى تصلي، وعلى أبيك كذلك وهكذا عمك وهكذا جيرانك تنصحهم وتدعوهم إلى القوة في هذا الأمر، والنشاط في هذا الأمر لعل الله يهديهم بأسباب النشاط والقوة والتوجيه والتأديب من الزوج لزوجته تأديباً ينفعها ويعينها على طاعة الله ولا يسبب خطراً، والله جل وعلا أمر بالتعاون على البر والتقوى قال سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] وقال جل وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71].\nهذا من باب الأمر بالمعروف والنهي عن المنكر، وقال سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3].\nالتواصي بالحق والتناصح أمر واجب أمر لازم، وهكذا الأمر بالمعروف والنهي عن المنكر أمر لازم مع الزوجة مع زوجة الأب مع زوجة الأخ مع الأخوات، مع البنات، لكن من تستطيع تأديبها تأدبها كالزوجة والبنت والولد تؤدب الجميع أدباً يردعهن عن، يردع الزوجة عن التساهل بالصلاة، يردع الولد يردع البنت، كما قال النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر.\nفالأولاد يضربون إذا تخلفوا عن الصلاة وهم أبناء عشر يضربون على ذلك، سواءً كانوا ذكوراً أو إناثاً لأن هذا مما يعينهم على طاعة الله ومما يسبب لهم المبادرة إلى الحق، فعلى وليهم أن يأمرهم بذلك ويضرب من بلغ عشراً على ذلك ضرباً غير مبرح ضرباً يعينهم على طاعة الله، ضرباً يشجعهم على الخير ولا يكون فيه خطر.\nوهكذا له أن يضرب المرأة يؤدبها إذا تساهلت وإذا خاف نشوزها ضربها فكيف إذا تركت الصلاة، ترك الصلاة أعظم فإذا لم يجد فيها النصح والتوجيه والدعوة إلى الخير فله أن يضربها ويؤدبها ضرباً غير مبرح، حتى تصلي حتى تقوم بهذا الواجب العظيم، فإن أصرت ولم تستقم وجب فراقها لأن من ترك الصلاة كفر، ترك الصلاة كفر أكبر نعوذ بالله من ذلك، فالتي لا تصلي تكون كافرة -نعوذ بالله- يجب فراقها بالكلية، وهكذا الزوج الذي لا يصلي وامرأته تصلي لا تبقى معه بل يجب أن تفارقه وأن تطلب الطلاق لأنه لا يجوز بقاؤها معه وهو لا يصلي، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ولقوله عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة.\nفالحاصل أن الصلاة أمرها عظيم وهي عمود الإسلام، فلابد من التأديب عليها من الزوج لزوجته من الوالد لولده والأخ لأخيه الذي الصغير حتى يستقيموا على الصلاة، حتى ولو كانوا دون البلوغ كابن عشر وثنتي عشرة من الأولاد والإخوة، يؤدبون ويعلمون ويوجهون للخير، والزوجة يجب أن تؤدب على هذا الأمر العظيم حتى تستقيم حتى تحافظ على الصلاة، فإذا أصرت على ترك الصلاة فحينئذ يجب أن يفارقها، كما أنه إذا أصر زوجها على ترك الصلاة يجب أن تتركه وتذهب إلى أهلها حتى يتوب توبة صادقة أو يفرق بينهما الحاكم الشرعي، نسأل الله للجميع الهداية، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8199/ما-يفعل-من-ابتلي-باقارب-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30103.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":10111,"question":"مستمع يقول: المرسل (خضر . س. ع)، يقول: إن له أخ لا يصلي وغير ملتزم بشرع الله، وقد نصحته كثيرًا لكنه لا يسمع، وجهوني كيف أتصرف والحال ما ذكرت جزاكم الله خيرا.الجواب: عليك أن تستمر في النصيحة وتجتهد في ذلك، والله هو الذي يهدي من يشاء؟الشيخ: تعيد سؤاله تعيد، أعد السؤال.المقدم: لي أخ لا يصلي وغير ملتزم بشرع الله، وقد نصحته كثيراً لكنه لا يسمع، وجهوني كيف أتصرف معه جزاكم الله خيرا؟","title":"ماذا يفعل من ابتُلي بأخ لا يصلي؟","answer":"الشيخ: عليك أن تنصحه لله، وأن تجتهد في ذلك وتبين له ما يجب على المؤمن، وأن الصلاة فريضة وأنها عمود الإسلام وأن تركها كفر لعله يستجيب، أنت وإخوانك وأعمامك فإن لم يستفد ولم يقبل فارفعوا أمره إلى الهيئة، أو إلى إمارة البلد إن كان ما في هيئة حتى تقيم عليه الأمر، وحتى يستتاب فإن تاب وإلا قتل، لا يجوز بقاءه، بل يجب أن يستتاب فإن تاب وإلا قتل، الذي لا يصلي يقتل كافر نسأل الله العافية، الرسول ﷺ يقول: نهيت عن قتل المصلين، والله يقول: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدل على أن الذي ما يتوب من ترك الصلاة لا يخلى سبيله بل يقتل، هذه جريمة عظيمة، ترك الصلاة جريمة عظيمة، بل كفر وضلال، فإذا لم يقبل النصح فالواجب رفع أمره إلى الهيئة أو إلى المحكمة أو إلى الإمارة حتى يحال للمحكمة إن تاب وإلا قتل. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8282/ماذا-يفعل-من-ابتلي-باخ-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27706.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":10169,"question":"تقول: توفيت والدتي منذ خمسة عشر عاماً وتزوج أبي من أختها ومنذ أن تزوجها أبي وهي لا تصلي ولم أرها صلت ولو مرة واحدة رغم ما قلته لها من عقوبة تارك الصلاة، وهي لا تصلي كسلاً وتهاوناً، وتقول بتهاون شديد: صلي أنت نيابة عني، فماذا أفعل معها؟ وما هو حدود تعاملي معها؟ أرجو أن توجهوني جزاكم الله خيراً.","title":"حكم من تزوج بامرأة لا تصلي","answer":"الجواب: تقدم الكلام في هذا، الجواب السابق وأن الواجب الإنكار عليها وتعليمها وتوجيهها، وعلى الزوج أيضاً أن يؤدبها في ذلك حتى تصلي، وإذا كان حين العقد لا تصلي وجب تجديد العقد كما تقدم، إن كان هو يصلي وهي لا تصلي العقد غير صحيح على الصحيح، بعض أهل العلم يراه صحيحاً إذا كانت لا تنكر وجوبها ولكنها تساهل أو تكاسل، ولكن الصواب أنه -العقد- غير صحيح للأحاديث السابقة، فالواجب امتناعه منها حتى تصلي ويجدد العقد وإلا فليطلقها لأن هذه شرها كثير ولها حكم الكفرة لتركها الصلاة نسأل الله العافية، لكن إذا تابت فإنه يجدد العقد بمهر جديد وعقد جديد وحضرة شاهدين كما تقدم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8349/حكم-من-تزوج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30810.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":10175,"question":"من جمهورية مصر العربية المستمعة (ف. م. م) من دمياط، بعثت برسالة ضمنتها جمعاً من الأسئلة من بينها سؤال ملخصه أنها مخطوبة لابن عمها وترجو أن يكون قد تاب عما كان يرتكب من المعاصي كتركه للصلاة وهي تقول: إنها كانت تاركة للصلاة وغير محتجبة إلا أنها الآن احتجبت وبدأت تصلي، وترجو سماحة الشيخ التوجيه فيما ينبغي للمخطوبين أن يكونا عليه؟ جزاكم الله خيراً.","title":"حكم عقد النكاح بين رجل وامرأة لا يصليان","answer":"الجواب: إذا كنتما جميعاً حين النكاح لا تصليان فالنكاح صحيح كما لو كنتما تصليان النكاح صحيح، وعليكما تقوى الله والاستقامة على دينه، والتعاون على البر والتقوى، وسؤال الله التوفيق سبحانه وتعالى، هكذا المؤمن والمؤمنة يجتهدان في الاستقامة على أمر الله والمحافظة على دينه من الصلاة وغيرها، مع سؤال الله الثبات على الحق والإعانة على الخير، أما إن كان أحدكما حين النكاح لا يصلي والآخر يصلي فإن الراجح من قولي العلماء في هذا أن عليكما أن تعيدا النكاح؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء وإن لم يجحد التارك الوجوب، فإذا كان أحدكما يصلي والآخر لا يصلي عند عقد النكاح فإنه يجدد النكاح بعدما تبتما، بعدما تاب الذي لا يصلي وصلى يجدد النكاح بعقد جديد ومهر جديد وولي وشاهدي عدل يحضران النكاح، والمهر ولو قليلاً الذي ترضى به المرأة ولو قليلاً، ويجدد العقد من الولي يقول: زوجتك، وهو يقول: قبلت، بحضرة شاهدين عدلين، في الحال ما يحتاج تأجيل، متى علما الحكم الشرعي بادرا بعقد النكاح.. يمتنع عنها حتى يجدد النكاح، هذا هو الصواب في هذه المسألة. نعم.\nالمقدم: سماحة الشيخ! هما لا زالا في دور الخطبة، ويسألان عن الشروط الواجب اتباعها أو توفرها في كل من الخاطب والمخطوبة.\nالشيخ: إذا كان لم يتم النكاح ولم يتم العقد فعليهما جميعاً التوبة إلى الله من تقصيرهما، وأن يحافظا على الصلوات الخمس، فإذا علم كل واحد من صاحبه أنه مستقيم فليتزوجا، إذا علم الزوج أن المرأة مستقيمة وهي كذلك علمت أنه مستقيم الحمد لله، بعدين يجرى النكاح، أما ما دام أحدهما لا يصلي فلا يجرى النكاح بل يتوقف فيه حتى يعلم كل واحد صلاح صاحبه وأنه مستقيم، حتى لا يقدم أحدهما على ما يضره، فإذا كانت تشك فيه أو هو يشك فيها فلا ينبغي تعجيل العقد حتى يتم الاطمئنان والعلم بأنهما يصليان جميعاً وأن الحالة مستقيمة حتى يدخلا في العقد على بصيرة، الله جل وعلا قال في كتابه الكريم: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221]، وقال: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221]، وقال في الكفار مع المسلمين: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]، وترك الصلاة كفر أكبر في أصح قولي العلماء وإن لم يجحد الوجوب التارك؛ لقول النبي ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر في أدلة أخرى، وهذه المسألة قد عمت بها البلوى في كثير من الناس، وعظمت المصيبة بترك الصلاة ولا حول ولا قوة إلا بالله من كثير من الناس.\nفالواجب على الخاطب أن يعتني بالمرأة حتى يعلم أنها تصلي، فلا يقدم إلا على بينة وعلى بصيرة، وهي كذلك الواجب عليها ألا تعجل حتى تعرف أنه طيب وأنه يصلي وأنه مستقيم، حتى يكون العقد على بينة وعلى حالة مرضية من الطرفين. أصلح الله حالهما جميعاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8346/حكم-عقد-النكاح-بين-رجل-وامراة-لا-يصليان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30807.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":10194,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع الطويل إدريس إبراهيم، أخونا عرضنا جمعاً من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: نرجو أن تتكرموا بإفادتنا عن قضية تارك الصلاة؛ يكفر، أو لا يكفر، نريد منكم تفصيلاً كاملاً حول هذا، ونريد سرد الأدلة من كتاب الله وسنة رسوله ﷺ وأقوال الصحابة في ذلك جزاكم الله خيراً؛ لأن هذا الموضوع شغل بال الكثير من المسلمين، وفقكم الله؟","title":"حكم ترك الصلاة تهاوناً وكسلاً","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفهذه المسألة من المسائل العظيمة التي اختلف فيها العلماء وهي مسألة ترك الصلاة تهاوناً وكسلاً لا عن جحد لوجوبها، فذهب جمع من أهل العلم إلى أنه يكفر بذلك لأدلة كثيرة، منها: قوله جل وعلا: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ ۝ وَلَمْ نَكُ نُطْعِمُ الْمِسْكِينَ [المدثر:42-44] الآية، ومنها: قوله جل وعلا: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَإِخْوَانُكُمْ فِي الدِّينِ [التوبة:11] فدل على أن من لم يصل ليس بأخ في الدين وإن لم يجحد الوجوب، وقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، وقوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وهذا كفر معرف بأل وشرك معرف بأل يدل على أنه الكفر الأكبر والشرك الأكبر، وقوله ﷺ: رأس الأمر الإسلام وعموده الصلاة فشيء ترك عموده لا يبقى بل يسقط، وقوله صلى الله عليه وسلم لما سئل عن الأمراء الذين يحدثون في الدين ويغيرون: أفنقاتلهم؟ قال: لا ما أقاموا فيكم الصلاة وفي اللفظ الآخر: قال: لا حتى تروا كفراً بواحاً عندكم من الله فيه برهان فجعل ترك الصلاة من الكفر البواح، الذي يوجب كفر من فعله. وقد ذكر عبد الله بن شقيق العقيلي التابعي الجليل عن الصحابة  وأرضاهم أنهم لا يرون شيئاً تركه كفر إلا الصلاة. فحكى عن الصحابة جميعاً أنهم يرون ترك الصلاة كفر، ولم ينقل عنهم اشتراط جحد الوجوب، فدل ذلك على أن تركها من غير جحد للوجوب كفر، وإطلاق الكفر في هذا المقام يقتضي أنه كفر أكبر؛ لأن هناك أعمالاً عند الصحابة تركها كفر وفعلها كفر، لكنه ليس كفراً أكبر مثل: الطعن في النسب والنياحة على الميت سماه النبي ﷺ: كفراً، ولكنه كفر أصغر، وهكذا البراءة من النسب سماه النبي ﷺ: كفراً، براءة الإنسان من أبيه : وإن كفراً بكم تبرؤ من آبائكم هو كفر أصغر، فدل على أن الكفر الذي حكاه عبد الله بن شقيق عن الصحابة أنه الكفر الأكبر، وقال عمر : لا حظ في الإسلام لمن ترك الصلاة هذا القول هو أصح القولين وأرجح القولين من جهة الدليل، أما من جحد الوجوب فهو كافر عند الجميع، من جحد وجوب الصلاة فهو كافر عند الجميع وإن صلى مع الناس؛ لأنه مكذب لله ولرسوله إذا جحد الوجوب.\nفالواجب على كل مسلم وعلى كل مسلمة أن يبادر ويسارع إلى الصلاة ويحافظ عليها في أوقاتها، وأن يتقي الله في ذلك ويحذر أن يكون مع الكافرين ومن ضمن الكافرين وهو لا يدري، فالصلاة عمود الإسلام وأعظم أركانه بعد الشهادتين، فالواجب على المسلمين جميعاً أن يحافظوا عليها، وأن يعتنوا بها، وأن يؤدوها في أوقاتها، وأن يصليها الرجل في الجماعة في مساجد الله طاعة لله ولرسوله ﷺ، وحذراً مما وصف به من تركها من الكفر. ونسأل الله لجميع المسلمين التوفيق والهداية والعافية من كل ما يغضبه.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8357/حكم-ترك-الصلاة-تهاونا-وكسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30901.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":10208,"question":"تقول عن نفسها: أصحو مبكرة دومًا لصلاة الفجر، وأحيانًا تفوت علي الصلاة، ولكن في الأوقات التي أقوم فيها للصلاة لا أقوم بإيقاظ زوجي للصلاة بل يظل نائمًا حتى مواعيد العمل وبعدها يصلي، هل في ذلك إثم علي؟","title":"حكم المرأة التي لا توقظ زوجها لصلاة الفجر","answer":"الجواب: نعم، إثم عليكما جميعًا عليك وعليه، عليك أن توقظيه وأن تتقي الله في ذلك وتعينيه على الخير، وعليه أن يقوم ويصلي في الوقت مع المسلمين في المساجد، وليس له أن ينام حتى وقت العمل هذا منكر، بل كفر إذا تعمد هذا كفر؛ لأنه تعمد ترك الصلاة في وقتها، تعمد إخراجها عن وقتها نعوذ بالله من ذلك.\nفالواجب عليك إيقاظه ونصيحته والحرص في ذلك، والواجب عليه أن يتقي الله وأن يقوم في الوقت، وأن يصلي مع المسلمين في المسجد، هذا هو الواجب على الجميع، والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول سبحانه: وَالْمُؤْمِنُونََ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، ويقول النبي ﷺ: من رأى منكم منكراً فليغيره بيده، فإن لم يستطع فبلسانه وأنت تستطيعين باللسان ولو غضب ولو كره أيقظيه ولو غضب، قولي: اتق الله الصلاة الصلاة، أعينيه على الخير، فإن لم يستقم فاطلبي الفراق اخرجي عنه إلى أهلك فارقيه؛ لأن هذا معناه تعمد ترك الصلاة في وقتها نعوذ بالله، ومن تعمد تركها في وقتها عمداً كفر بذلك في أصح أقوال أهل العلم؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ومن تعمد تركها حتى تطلع الشمس عمدًا كفر بذلك على الصحيح.\nفالواجب عليك أن تتقي الله وأن تعينيه على الخير فإن أجاب وإلا فارقيه، واذهبي لأهلك واتركيه وامنعيه من نفسك، نسأل الله العافية والسلامة، نسأل الله لنا وله الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8379/حكم-المراة-التي-لا-توقظ-زوجها-لصلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27806.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":10236,"question":"هل يجوز لفتاة ملتزمة بدينها أن تتزوج من رجل غير مصلي مع وجود النية بدعوته للعبادة حتى تكسب الأجر والثواب؟","title":"حكم تزوج الفتاة برجل لا يصلي","answer":"الجواب: إذا كان لا يصلي ليس لها التزوج به، الذي لا يصلي كافر، ما يتزوج إلا كافرة ما يتزوج مسلمة؛ لأن ترك الصلاة كفر أكبر نسأل الله العافية؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقوله عليه السلام: رأس الأمر الإسلام وعموده الصلاة، والله يقول جل وعلا: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ [البقرة:43]، ويقول جل وعلا: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، ويقول سبحانه: وَمَا أُمِرُوا إِلَّاا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ [البينة:5]، فالذي لا يصلي ليس لها أن تتزوج منه، وإذا كانت معه تفارقه، تذهب إلى أهلها وتتركه حتى يتوب أو يطلق، نسأل الله العافية والسلامة.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8404/حكم-تزوج-الفتاة-برجل-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27811.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":10256,"question":"من الرياض المستمع حسن بن هادي بعث يسأل ويقول: إن بعض المرضى لا يؤدون الصلاة المكتوبة أثناء المرض، إما لعدم المقدرة عليها، أو أنه يعطي نفسه الأمل بأن يقضيها بعد الشفاء، هل تصح صلاة المريض الذي لا يستطيع القيام من فراشه بدون وضوء، وأينما كان مولٍ وجهه وهو على فراشه، نرجو الإفادة جزاكم الله خيرًا؟","title":"حكم ترك المريض للصلاة أثناء فترة مرضه","answer":"الجواب: الصلاة واجبة على المريض، صلاة الفريضة الظهر والعصر والمغرب والعشاء والفجر واجبة على المريض حسب طاقته، ولا يجوز له تركها، بل يجب أن يصليها على حسب حاله، لقول النبي ﷺ للمريض الذي سأله: صل قائمًا فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب رواه البخاري في صحيحه، من حديث عمران بن حصين ، ورواه النسائي وزاد: فإن لم تستطع فمستلقيا.\nهذا هو الواجب على المريض أن يصلي قائمًا إن استطاع فإن عجز صلى قاعداً، يركع ويسجد فإن عجز عن القعود صلى على جنبه، يقرأ ويأتي بالأذكار القولية، ويأتي بالأفعال الفعلية بالنية، الركوع بالنية والسجود بالنية، والرفع من الركوع بالنية، والرفع من السجود بالنية، مع الأذكار الشرعية، فإن عجز صلى مستلقيًا على ظهره ورجلاه إلى القبلة، يكبر ويقرأ ثم يكبر ويركع بالنية، ثم يقول: سمع الله لمن حمده بالنية رافعًا من الركوع، ثم يكبر ناويًا السجود يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم يكبر ناويًا الرفع من السجود يجلس بين السجدتين بالنية، يقول: رب اغفر لي، رب اغفر لي ، ثم يكبر ناوياً السجدة الثانية وهكذا، لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وهذه طاقته، وليس له ترك الصلاة، فإن عجز عن الماء تيمم بالتراب بالصعيد التراب يمسح وجهه وكفيه. إذا لم يستطع استعمال الماء، أو ليس عنده من يوضئه. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8427/حكم-ترك-المريض-للصلاة-اثناء-فترة-مرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27907.mp3","categories":["صلاة المريض","حكم الصلاة وأهميتها"]},{"id":10289,"question":"رسالة وصلت إلى البرنامج من المستمع صلاح محمد من أسيوط يقول في رسالته: إنني أصلي والحمد لله وعمري يبلغ ثلاثًا وعشرين سنة، وقطعت الصلاة فترة بسبب مرض ولكن شفاني الله، وبعدها استمريت في قطع الصلاة، والآن أصلي والحمد لله، هل علي إثم أو كفارة؟ وما هي الكفارة حتى أؤديها ولكم الشكر؟","title":"حكم ترك الصلاة في فترة المرض","answer":"الجواب: عليك يا أخي التوبة إلى الله والحمد لله لزوم التوبة، ما دمت تبت والحمد لله فعليك أن تلزمها، وأن تكثر من العمل الصالح، وتسأل ربك الثبات على الحق، وعليك أن تحرص على صحبة الأخيار وأن تبتعد عن صحبة الأشرار، وليس عليك سوى ذلك، التوبة تجب ما قبلها، كما قال الله جل وعلا في كتابه العظيم: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، وقال سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31].\nولما ذكر سبحانه الشرك والزنا والقتل في قوله تعالى: وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ [الفرقان:68] قال بعده: وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا ۝ إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا [الفرقان:68-70].\nوقال النبي ﷺ: التائب من الذنب كمن لا ذنب له، فاحمد ربك على التوبة والزمها وسل ربك الثبات واحذر أسباب الفتنة، واحذر العودة إلى ترك الصلاة فإن الصلاة عمود الإسلام، وتركها كفر بالله عز وجل، فاحذر ذلك.\nيقول النبي ﷺ: رأس الأمر الإسلام وعموده الصلاة، ويقول ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، ويقول عليه الصلاة والسلام أيضًا: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر فاحذر يا أخي من تركها ومن مجالسة من يتركها، لعلك تنجو وسل ربك الثبات على الحق حتى تلقاه . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8450/حكم-ترك-الصلاة-في-فترة-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33802.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":10306,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من الأحساء وباعثها مستمع رمز إلى اسمه بحرفين هما (س. ص)، أسئلته مطولة بعض الشيء يقول في الأول: أفيدكم أفادكم الله عن هذه القضية، عمري يتجاوز الثلاثين، كنت لا أعرف صلاةً ولا صياماً والعياذ بالله، وكنت من الذين ضائعين، ولكن الله من علي والحمد لله فالتزمت وشرعت في كتاب الله حفظا، هل في السنين التي انتهت من عمري علي صلاة وصيام، وأنا بديت الصوم قبل ثلاث سنوات فقط وأما بقية السنين فبدون صيام ولا صلاة، وجهوني حول حالتي السابقة جزاكم الله خيراً؟","title":"حكم من ترك الصلاة والصيام سنوات ثم تاب","answer":"الجواب: الحمد لله الذي هداك وردك إلى الصواب، ونوصيك بتقوى الله والصبر والثبات والاستقامة، وسؤال الله سبحانه دائماً أن يثبتك على الحق وأن يعينك على ذكره وشكره وحسن عبادته، وأن يمنحك التوفيق، تدعو ربك كثيراً في السجود، وفي آخر الصلاة، وفي آخر الليل، وبين الأذان والإقامة تجتهد بالدعاء، تسأله سبحانه أن يمنحك التوفيق، وأن يمنحك الاستقامة، وأن يمنحك الفقه في الدين، وأن يعفو عنك عما سلف، وليس عليك قضاء لا صلاة ولا صيام ليس عليك قضاء؛ لأن التوبة تجب ما قبلها؛ ولأن من ترك الصلاة كفر فلا يقضي ما مضى؛ لقوله سبحانه : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]؛ ولقوله ﷺ : التوبة تهدم ما كان قبلها، وقوله ﷺ: التائب من الذنب كمن لا ذنب له، فإذا كان الإنسان على حالة كفرية ثم تاب فإنه لا يقضي ما مضى من صلاة ولا صوم، وإذا أسلم وتاب فهو على ما أسلم من خير، ما كان قبل ذلك من الخير يبقى له وليس عليه القضاء لما ترك من صلاة وصوم في حال كفره بتركه الصلاة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8483/حكم-من-ترك-الصلاة-والصيام-سنوات-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31309.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":10315,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من الأحساء وباعثها مستمع رمز إلى اسمه بحرفين هما (س. ص)، أسئلته مطولة بعض الشيء يقول في الأول: أفيدكم أفادكم الله عن هذه القضية، عمري يتجاوز الثلاثين، كنت لا أعرف صلاةً ولا صياماً والعياذ بالله، وكنت من الذين ضائعين، ولكن الله من علي والحمد لله فالتزمت وشرعت في كتاب الله حفظا، هل في السنين التي انتهت من عمري علي صلاة وصيام، وأنا بديت الصوم قبل ثلاث سنوات فقط وأما بقية السنين فبدون صيام ولا صلاة، وجهوني حول حالتي السابقة جزاكم الله خيراً؟","title":"حكم من ترك الصلاة والصيام سنوات ثم تاب","answer":"الجواب: الحمد لله الذي هداك وردك إلى الصواب، ونوصيك بتقوى الله والصبر والثبات والاستقامة، وسؤال الله سبحانه دائماً أن يثبتك على الحق وأن يعينك على ذكره وشكره وحسن عبادته، وأن يمنحك التوفيق، تدعو ربك كثيراً في السجود، وفي آخر الصلاة، وفي آخر الليل، وبين الأذان والإقامة تجتهد بالدعاء، تسأله سبحانه أن يمنحك التوفيق، وأن يمنحك الاستقامة، وأن يمنحك الفقه في الدين، وأن يعفو عنك عما سلف، وليس عليك قضاء لا صلاة ولا صيام ليس عليك قضاء؛ لأن التوبة تجب ما قبلها؛ ولأن من ترك الصلاة كفر فلا يقضي ما مضى؛ لقوله سبحانه : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]؛ ولقوله ﷺ : التوبة تهدم ما كان قبلها، وقوله ﷺ: التائب من الذنب كمن لا ذنب له، فإذا كان الإنسان على حالة كفرية ثم تاب فإنه لا يقضي ما مضى من صلاة ولا صوم، وإذا أسلم وتاب فهو على ما أسلم من خير، ما كان قبل ذلك من الخير يبقى له وليس عليه القضاء لما ترك من صلاة وصوم في حال كفره بتركه الصلاة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8483/حكم-من-ترك-الصلاة-والصيام-سنوات-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31309.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":10316,"question":"يوجد معي أخي وهو أكبر مني سنًّا ولا يصلي، وأحاول معه أكثر من مرة في أن يصلي وهو يقول: كثير من الناس لا يصلون، ماذا أفعل معه لإرغامه حتى يصلي، مع العلم أنه يعمل في كل شيء حتى في المسكن يعمل معي، أرجو إرشادي جزاكم الله خيرًا؟","title":"ما النصيحة لمن ابتُلي بأخ أكبر منه لا يصلي؟","answer":"الجواب: عليك أن تستمر في نصيحته والاستعانة أيضًا بخواص إخوانك الطيبين حتى ينصحوه معك، مع سؤال الله جل وعلا أن يهديه، تسأل ربك أن يهديه في صلاتك وفي آخر الليل وفي غير ذلك من الأوقات تسأل الله أن يهديه، وأن يشرح صدره للحق وأن يعينه على جهاد نفسه وشيطانه، ولا تيئس بل اجتهد في نصيحته لعل الله يمن عليك بالهداية، فإن أصر فابتعد عنه وقاطعه في الله واهجره في الله، لعل الله ينفع بذلك أيضًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8487/ما-النصيحة-لمن-ابتلي-باخ-اكبر-منه-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33803.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":10317,"question":"يقول: إذا كان الشاب في بداية حياته قد ضيع بعض الصلوات وتركها وكذلك الصيام جهلاً وتكاسلاً، ثم تاب بعد ذلك وندم، فهل عليه إعادة لما ترك من الصلوات والصيام علماً بأنه لا يستطيع تحديدها، أفتونا مأجورين جزاكم الله خيراً؟","title":"حكم من تاب من ترك الصلاة والصيام كسلًا وجهلًا","answer":"الجواب: ليس عليه قضاء، والتوبة كافية، إذا كان لا يصلي ولا يصوم أو عنده أنواع من الكفر الأخرى فإن التوبة تكفي، يقول الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، ويقول جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ يعني: بالشرك والمعاصي لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]، أجمع العلماء على أن الآية المذكورة في التائبين، فإذا كان لا يصلي ولا يصوم، أو كان يسب الدين، أو كان يشرك بغير الله، يدعو الأموات، ويستغيث بأهل القبور، أو بالأصنام والأشجار، فإنه متى تاب توبةً صادقة تاب الله عليه، والتوبة الصادقة تشمل أموراً ثلاثة: الندم على الماضي الندم الصادق، والإقلاع من المعصية أو الشرك وترك ذلك، والعزم الصادق ألا يعود رغبةً فيما عند الله وإخلاصاً له ومحبةً له وتعظيماً له فإن هذه التوبة تمحو ما قبلها، من جميع أنواع الشرك والمعاصي.\nالأمر الأول: الندم على الماضي؛ خوفاً من الله وتعظيماً له.\nالأمر الثاني: الإقلاع من الذنوب من الكفر والمعاصي.\nالأمر الثالث: العزم الصادق ألا يعود في ذلك.\nفمتى فعل هذا خوفاً من الله وتعظيماً له ورغبةً فيما عنده وإخلاصاً له سبحانه تاب الله عليه ومحا عنه جميع الذنوب وليس عليه قضاؤها لا صلاة ولا صيام ولا غير ذلك، التوبة تجب ما قبلها، وإن كان عنده حق للمخلوقين فلابد من الأمر الرابع وهو رد حقوقهم إليهم كالسرقات والغصوب يعطيهم حقوقهم، وهكذا القصاص إذا قتل لهم أحداً يعطيهم حقهم بالقصاص أو الدية، لابد من أداء الحق للمخلوق أو استحلاله إذا أحله وسامحه لا بأس.\nأما إن كان فعله ليس بكفر أكبر كترك الصيام فقط وإلا هو يصلي لكن فرط في بعض الصيام فإنه يقضي، إذا كان يصلي ولكنه فرط في بعض الصيام أو في الزكاة ما زكى، ليس بكافر، ترك الصيام ليس بكفر إذا كان يؤمن بالوجوب وأن رمضان واجب عليه ولكن تساهل ففرط في بعض الصيام يقضي، عليه القضاء والتوبة إلى الله، وعليه أداء الزكاة عما مضى إذا كان لا يزكي، مع التوبة الصادقة والله يتوب على التائبين.\nأما ترك الصلاة فكفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالصلاة أمرها عظيم، وهي عمود الإسلام، من حفظها حفظ دينه ومن ضيعها ضيع دينه، نسأل الله العافية.\nفالواجب على كل مسلم أن يحذر تركها والتساهل بها، على الجميع رجالاً ونساء أن يتقوا الله، وأن يحافظوا على الصلوات الخمس في أوقاتها، وأن يؤديها الرجل في الجماعة، هذا هو الواجب على الجميع، فمن ضيعها وتهاون بها وتركها كفر نسأل الله العافية في أصح قولي العلماء.\nأما من جحد وجوبها وقال: ما هي بواجبة، هذا يكفر عند الجميع عند جميع الأمة عند جميع أهل العلم، من قال: إنها غير واجبة أو إن واحدة منها غير واجبة كالظهر أو العصر أو المغرب أو العشاء أو الفجر كفر إجماعاً، أما إذا كان يؤمن بأنها واجبة ولكن يتساهل ويتركها أو بعضها فإنه يكفر بذلك نسأل الله العافية، أما إن كان يصلي لكن في البيت فهذا يكون عاصي وعليه التوبة إلى الله وأن يصلي في الجماعة، وصلاته مجزئة لا يعيدها لكن عليه أن يصلي في الجماعة ويتوب مما سلف، إذا كان لا يصلي في الجماعة بل يصلي في البيت يجب أن يصلي مع الجماعة، وأن يتوب إلى الله مما سلف.\nأما النساء فعليهن الصلاة في البيت، السنة لهن الصلاة في البيوت، ومن صلت مع الجماعة صلاتها صحيحة، لكن الأفضل في حق النساء الصلاة في البيت. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8494/حكم-من-تاب-من-ترك-الصلاة-والصيام-كسلا-وجهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها","الرقائق"]},{"id":10319,"question":"ما حكم أكل ذبيحة من لا يصلي أو الذي نشك هل يصلي أم لا؟ وكيف نتصرف معهم إذا دعينا إلى ذبائحهم أكثر من مرة؟","title":"حكم أكل ذبيحة من لا يصلي","answer":"الجواب: من يدعي الإسلام تؤكل ذبيحته، من هو معروف بالإسلام ويتسمى بالإسلام وينسب إلى الإسلام ما عرف عنه مكفر تؤكل ذبيحته، أما من عرف أنه لا يصلي فلا تؤكل ذبيحته ولا تجاب دعوته بل يهجر حتى يتوب إلى الله عز وجل، وإذا كنت تشك فالأصل أنه يصلي، هذا هو الأصل في المسلم، فذبيحته حلال ما دمت تشك في ذلك، أما إذا علمت يقيناً أنه لا يصلي فإنه يستحق الهجر، ولا تؤكل ذبيحته، ولا تجاب دعوته، بل يجب على ولي الأمر أن يستتيبه فإن تاب وإلا قتل كافراً نسأل الله العافية، إذا رفع الأمر إلى ولي الأمر أو إلى المحكمة يجب أن يستتاب، فإن تاب وصلى وإلا وجب قتله مرتداً نسأل الله العافية؛ لقول الله جل وعلا: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدل على أن من لم يتب من الشرك لا يخلى سبيله، وهكذا من لم يتب من ترك الصلاة لا يخلى سبيله، وهكذا من ترك الزكاة لا يخلى سبيله بل يطالب، لكن من ترك الصلاة يقتل كافراً، أما من ترك الزكاة يطالب يجبر بإخراج الزكاة ولا يكفر بذلك لأدلة أخرى.\nوهكذا من استمر على الشرك يستتاب فإن تاب وإلا قتل مرتداً نسأل الله العافية، ولما ارتد العرب في عهد الصديق  قاتلهم حتى رجع من رجع إلى الإسلام وحتى قتل من قتل على الردة، فالمرتد الذي يترك الإسلام يترك توحيد الله أو الإيمان بالرسول ﷺ أو يترك الصلاة يستتاب فإن تاب وإلا قتل كافراً.\nأما من ترك الزكاة فإن قاتل دونها يقاتل أيضاً ويكون كافراً إذا قاتل دونها، فإن قتاله دون الزكاة دليل على كفره وإنكاره وجوبها، أما إذا لم يسلمها ولكن ما جحد وجوبها ولا قاتل دونها فإنه يجبر عليها تؤخذ منه ويجبر عليها ويكون عاصياً بذلك، وأمره إلى الله جل وعلا إن مات على ذلك فأمره إلى الله وإن تاب تاب الله عليه؛ لأنه صح عن النبي ﷺ أنه قال: يوم القيامة يؤتى بالرجل الذي لا يؤدي الزكاة فيعذب بماله الذي تركه لم يؤد زكاته ويعذب بإبله وبقره وغنمه التي لم يزكها، ثم يرى سبيله بعد هذا إما إلى الجنة وإما إلى النار، فدل على أنه لا يكفر بذلك، إذا كان ما جحد وجوبها بل هو معرض لدخول النار، لكن من قاتل دونها فقد قاتلهم الصحابة، الصديق والصحابة قاتلوهم قتال المرتدين؛ لأن قتالهم دون الزكاة دليل على إنكارهم لها وإنكارهم لوجوبها، ولهذا عوملوا معاملة الكفار، نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/8500/حكم-اكل-ذبيحة-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31413.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":10329,"question":"يقول: إذا كان الشاب في بداية حياته قد ضيع بعض الصلوات وتركها وكذلك الصيام جهلاً وتكاسلاً، ثم تاب بعد ذلك وندم، فهل عليه إعادة لما ترك من الصلوات والصيام علماً بأنه لا يستطيع تحديدها، أفتونا مأجورين جزاكم الله خيراً؟","title":"حكم من تاب من ترك الصلاة والصيام كسلًا وجهلًا","answer":"الجواب: ليس عليه قضاء، والتوبة كافية، إذا كان لا يصلي ولا يصوم أو عنده أنواع من الكفر الأخرى فإن التوبة تكفي، يقول الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، ويقول جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ يعني: بالشرك والمعاصي لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]، أجمع العلماء على أن الآية المذكورة في التائبين، فإذا كان لا يصلي ولا يصوم، أو كان يسب الدين، أو كان يشرك بغير الله، يدعو الأموات، ويستغيث بأهل القبور، أو بالأصنام والأشجار، فإنه متى تاب توبةً صادقة تاب الله عليه، والتوبة الصادقة تشمل أموراً ثلاثة: الندم على الماضي الندم الصادق، والإقلاع من المعصية أو الشرك وترك ذلك، والعزم الصادق ألا يعود رغبةً فيما عند الله وإخلاصاً له ومحبةً له وتعظيماً له فإن هذه التوبة تمحو ما قبلها، من جميع أنواع الشرك والمعاصي.\nالأمر الأول: الندم على الماضي؛ خوفاً من الله وتعظيماً له.\nالأمر الثاني: الإقلاع من الذنوب من الكفر والمعاصي.\nالأمر الثالث: العزم الصادق ألا يعود في ذلك.\nفمتى فعل هذا خوفاً من الله وتعظيماً له ورغبةً فيما عنده وإخلاصاً له سبحانه تاب الله عليه ومحا عنه جميع الذنوب وليس عليه قضاؤها لا صلاة ولا صيام ولا غير ذلك، التوبة تجب ما قبلها، وإن كان عنده حق للمخلوقين فلابد من الأمر الرابع وهو رد حقوقهم إليهم كالسرقات والغصوب يعطيهم حقوقهم، وهكذا القصاص إذا قتل لهم أحداً يعطيهم حقهم بالقصاص أو الدية، لابد من أداء الحق للمخلوق أو استحلاله إذا أحله وسامحه لا بأس.\nأما إن كان فعله ليس بكفر أكبر كترك الصيام فقط وإلا هو يصلي لكن فرط في بعض الصيام فإنه يقضي، إذا كان يصلي ولكنه فرط في بعض الصيام أو في الزكاة ما زكى، ليس بكافر، ترك الصيام ليس بكفر إذا كان يؤمن بالوجوب وأن رمضان واجب عليه ولكن تساهل ففرط في بعض الصيام يقضي، عليه القضاء والتوبة إلى الله، وعليه أداء الزكاة عما مضى إذا كان لا يزكي، مع التوبة الصادقة والله يتوب على التائبين.\nأما ترك الصلاة فكفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالصلاة أمرها عظيم، وهي عمود الإسلام، من حفظها حفظ دينه ومن ضيعها ضيع دينه، نسأل الله العافية.\nفالواجب على كل مسلم أن يحذر تركها والتساهل بها، على الجميع رجالاً ونساء أن يتقوا الله، وأن يحافظوا على الصلوات الخمس في أوقاتها، وأن يؤديها الرجل في الجماعة، هذا هو الواجب على الجميع، فمن ضيعها وتهاون بها وتركها كفر نسأل الله العافية في أصح قولي العلماء.\nأما من جحد وجوبها وقال: ما هي بواجبة، هذا يكفر عند الجميع عند جميع الأمة عند جميع أهل العلم، من قال: إنها غير واجبة أو إن واحدة منها غير واجبة كالظهر أو العصر أو المغرب أو العشاء أو الفجر كفر إجماعاً، أما إذا كان يؤمن بأنها واجبة ولكن يتساهل ويتركها أو بعضها فإنه يكفر بذلك نسأل الله العافية، أما إن كان يصلي لكن في البيت فهذا يكون عاصي وعليه التوبة إلى الله وأن يصلي في الجماعة، وصلاته مجزئة لا يعيدها لكن عليه أن يصلي في الجماعة ويتوب مما سلف، إذا كان لا يصلي في الجماعة بل يصلي في البيت يجب أن يصلي مع الجماعة، وأن يتوب إلى الله مما سلف.\nأما النساء فعليهن الصلاة في البيت، السنة لهن الصلاة في البيوت، ومن صلت مع الجماعة صلاتها صحيحة، لكن الأفضل في حق النساء الصلاة في البيت. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8494/حكم-من-تاب-من-ترك-الصلاة-والصيام-كسلا-وجهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها","الرقائق"]},{"id":10393,"question":"سوداني مقيم بالعراق هو (د. ح. ج. أ) بعث برسالة ضمنها سؤالين، في سؤاله الأول يقول: تقدمت إلى فتاة أريد أن أتزوجها ولكن والد الفتاة رجل لا يصلي، والأخطر من ذلك أنه رجل مدمن على شرب الخمر، ولذلك فإن الفتاة التي تقدمت إليها لا تصلي -أي: بنت هذا الرجل المدمن على الخمر- هل يجوز أن أتزوج بها أم لا؟","title":"هل يجوز الزواج بامرأة لا تصلي؟","answer":"الجواب: ليس لك أن تتزوج بها حتى تصلي؛ لأن ترك الصلاة كفر، كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة.\nفالمقصود: أن الصلاة عمود الإسلام، وهي الركن الثاني من أركان الإسلام الخمسة، وهي أعظم الأركان بعد الشهادتين، فمن تركها جاحدًا لها كفر بإجماع المسلمين، ومن تركها تهاونًا وتكاسلًا كفر في أصح قولي العلماء، سواء كان رجلًا أو امرأة.\nفلا ينبغي لك ولا يجوز لك أن تنكحها وهي بهذه الحال وأنت مسلم تصلي وتصوم وتخاف الله، ليس لك أن تزوجها، حتى تتوب إلى الله وحتى تستقيم على الصلاة.\nوهكذا المرأة ليس لها أن تزوج الرجل الذي لا يصلي إذا علمت أنه لا يصلي، فإنها لا يحل لها أن تقبله ولا أن ترضى بالعقد عليه، وإذا ترك الصلاة وجب عليها الامتناع منه حتى يتوب إلى الله، فإذا تاب إلى الله وهي في العدة فهو زوجها أو بعد العدة ولم تفسخ منه فهي زوجته على الصحيح، لكن بعد العدة لها أن تطالب بالفسخ منه وتأخذ حقها حتى تزوج من شاءت؛ لأن ترك الصلاة ردة عن الإسلام في أصح قولي العلماء، ولو لم يجحد وجوبها.\nوذهب جملة من أهل العلم: إلى أنه إذا لم يجحد وجوبها لم يكن كافرًا كفرًا أكبر بل يكون كفره كفرًا أصغر، ولكن هذا القول مرجوح، والصواب: أنه كفر أكبر لأنها عمود الإسلام، وقد أطلق النبي ﷺ كفر تاركها عليه الصلاة والسلام فقال: بين الرجل وبين الكفر والشرك ترك الصلاة والكفر المعرف بأل والشرك المعرف بأل يرجع إلى الكفر الأكبر.\nوقال أيضًا عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال في الأئمة الذين لا يصلون لما سئل ﷺ عن الأمراء الذين لا يصلون.. سئل عن الأمراء الذين يؤخرون الصلاة عن أوقاتها، أو تعرف منهم وتنكر من المعاصي، نهى عن قتالهم والخروج عليهم، قال: إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان وفي الرواية الأخرى قال: ما أقاموا فيكم الصلاة فدل على أنهم إذا لم يقيموا الصلاة فقد أتوا كفرًا بواحًا.\nوالمقصود من هذا: أن ترك الصلاة كفر بواح كما بينه النبي عليه الصلاة والسلام، فالواجب على المسلمين الحذر من هذا التهاون والحرص على المحافظة على الصلاة في أوقاتها، والرجل يحرص على أدائها في الجماعة في مساجد الله، والمرأة تصليها في بيتها، ولا يجوز أبدًا التأسي بمن تركها، أو الاقتداء به، بل يجب الحذر من ذلك، فهي عمود الإسلام من حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع.\nوكان عمر بن الخطاب  يكتب إلى عماله ويقول: «إن أهم أمركم عندي الصلاة، فمن حفظها فقد حفظ دينه ومن ضيعها فهو لما سواها أضيع » وذكر النبي ﷺ الصلاة يومًا بين أصحابه فقال: من حافظ عليها كانت له نورًا وبرهانًا ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف وهؤلاء الكفرة شغلتهم دنياهم عن طاعة الله وعبادته، فمن ترك الصلاة فقد شابه هؤلاء فيحشر معهم نعوذ بالله، فإن كان تركها لأجل الرياسة شابه فرعون فيحشر معه يوم القيامة، وإن كان تركها من أجل الوزارة شابه هامان وزير فرعون فيحشر معه يوم القيامة، إلى النار نسأل الله العافية، أما إن كان تركها من أجل المال والشهوات فإنه يشبه قارون الذي شغله ماله وشهواته عن اتباع الحق حتى خسف الله به وبداره الأرض نعوذ بالله من ذلك، أما إن كان تركها لأجل البيع والشراء وتصريف التجارة فإنه شبيهًا بـأبي بن خلف ، تاجر أهل مكة فإنه شغله البيع والشراء والتجارة عن طاعة الله ورسوله، وعن اتباع النبي محمد عليه الصلاة والسلام، فيكون من ترك الصلاة تشاغلًا بالتجارة شبيهًا بهذا نسأل الله العافية، فيحشر معه يوم القيامة نعوذ بالله من ذلك.\nفالواجب الحذر، ومن المصائب العظيمة كثرة من يتركها الآن ويتساهل بها، إما بالكلية وإما في المساجد، وهذا بلاء عظيم وشر كبير، ومنكر عظيم، فالواجب الحذر من ذلك، والواجب التواصي بفعلها والاستقامة عليها بين أهل البيت من الرجال والنساء يجب التواصي بذلك والتعاون في ذلك، حتى يقيم الرجل الصلاة هو وأهله وزوجته وأولاده وخدمه، لا يتساهل في هذا، بل يجب أن يكون قدوة صالحة لزوجته وأولاده وخادمه وسائقه ونحو ذلك، فالصلاة عمود الإسلام من حفظها حفظ دينه ومن ضيعها فهو لما سواها أضيع، والله يقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول : وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] والآيات فيها كثيرة وهكذا الأحاديث لعظم شأنها نسأل الله لنا ولجميع المسلمين الهداية.\nالسؤال: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8565/هل-يجوز-الزواج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/339014.mp3","categories":["حكم الصلاة وأهميتها","شروط وأركان الزواج"]},{"id":10419,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أنا عبدالله إبراهيم من الجمهورية العربية اليمنية مقيم في المملكة في وادي فاطمة -الجموم- وأنا من أحد المستمعين للبرنامج، وقد أفادني كثيرًا في أمور ديني ودنياي، لدي أسئلة بعضها يقول: هل يجوز الإنفاق على المرأة التي لا تصلي ولا تصوم سواءً كانت من القرابة أو من غيرهم؟","title":"حكم النفقة على امرأة لا تصلي ولا تصوم","answer":"الجواب: هذه يجب أن تدعى إلى الله وأن تعلم وتنصح وتوجه إلى الخير؛ لأن ترك الصلاة جريمة عظيمة بل كفر بالله نعوذ بالله من ذلك، فالواجب على وليها كأبيها أو أخيها أو عمها أو نحوهم أن يعلموها ويرشدوها يفقهوها حتى تصلي، أما الإنفاق عليها فينفق عليها إذا كانت فقيرة ينفق عليها لعل الله أن يهديها حتى تهتدي أو تقتل، إذا لم تهتد يرفع بأمرها إلى المحكمة والمحكمة تستتيبها فإن تابت وإلا قُتلت.\nلأن ترك الصلاة جريمة عظيمة توجب القتل لمن لم يتب، ومع ذلك يحكم بكفره في أصح قولي العلماء، وإن لم يجحد الوجوب.\nفالواجب على أولياء هذه المرأة أن ينصحوها ويعظوها ويذكروها، ولا مانع أن يؤدبها أبوها أو أخوها الكبير إذا استطاع ذلك، لعلها تستقيم ولعلها تتوب، فإن أصرت رفع أمرها إلى المحكمة والواجب على القاضي أن يستتيبها ويمهلها ثلاثًا، فإن تابت وإلا وجب قتلها إذا كانت مكلفة قد بلغت الحلم، لقول الله سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدل ذلك: على أن من لم يقم الصلاة لا يخلى سبيله، وقال عليه الصلاة والسلام: إني نهيت عن قتل المصلين فدل على أن من لا يصلي يقتل حتى يستراح من شره، وحتى لا يجر غيره إلى هذه الجريمة، لكن بعد الاستتابة، بعد أن يستتاب ثلاثة أيام فإن تاب وإلا قتل، يسجن ويضيق عليه لعله يتوب فإن تاب وإلا قتل كافرًا، هذا هو الصواب وإن لم يجحد الوجوب لا يغسل، ولا يصلى عليه، ولا يدفن في مقابر المسلمين، وإن كان له مال فماله لبيت المال فيء لا يرثه أقاربه المسلمون، نسأل الله للجميع الهداية ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8592/حكم-النفقة-على-امراة-لا-تصلي-ولا-تصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34105.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":10439,"question":"ينتقل إلى مواضيع أخرى فيسأل ويقول: هل يجوز أكل ذبيحة تارك الصلاة؟","title":"حكم أكل ذبيحة تارك الصلاة","answer":"الجواب: ذبيحة تارك الصلاة من كفره حرم ذبيحته، ومن قال: إنه كفر دون كفر لم يحرم ذبيحته، والعلماء اختلفوا في ذلك في حق من ترك الصلاة ولم يجحد وجوبها ولكن تكاسل، فذهب جمع من أهل العلم إلى أنه يكفر بذلك كفراً أكبر، وهذا هو الأرجح والأقرب للدليل؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.","link":"https://binbaz.org.sa/fatwas/8612/حكم-اكل-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31804.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":10444,"question":"ينتقل إلى مواضيع أخرى فيسأل ويقول: هل يجوز أكل ذبيحة تارك الصلاة؟","title":"حكم أكل ذبيحة تارك الصلاة","answer":"الجواب: ذبيحة تارك الصلاة من كفره حرم ذبيحته، ومن قال: إنه كفر دون كفر لم يحرم ذبيحته، والعلماء اختلفوا في ذلك في حق من ترك الصلاة ولم يجحد وجوبها ولكن تكاسل، فذهب جمع من أهل العلم إلى أنه يكفر بذلك كفراً أكبر، وهذا هو الأرجح والأقرب للدليل؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.","link":"https://binbaz.org.sa/fatwas/8612/حكم-اكل-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31804.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":10560,"question":"السؤال الأخير لأخينا يقول: لي أخت زوجها والدي من ابن خالتي وكان عمرها اثنتين وعشرين سنة، وهي الآن أنجبت منه ولداً وبنتين إنما كانت تاركة للصلاة، ما حكم العقد، وكيف توجهوننا؟ جزاكم الله خيراً.","title":"حكم العقد لمن عقد على امرأة لا تصلي","answer":"الجواب: إذا كان زوجها مثلها يترك الصلاة فالعقد صحيح، كعقود بقية الكفار؛ لأن ترك الصلاة كفر في أصح قولي العلماء، للحديث الصحيح يقول ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه، ويقول عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح.\nفإذا كان الزوجان كلاهما لا يصلي فالعقد صحيح كما لو كانا يهوديين أو نصرانيين أو وثنيين، والنبي صلى الله عليه وسلم أقر الكفار على عقودهم، أما إن كان أحدهما يصلي والآخر لا يصلي، ولكن الذي لا يصلي لا يجحد وجوبها ولكنه يتكاسل فهذا فيه خلاف بين العلماء، فالأكثرون على أن العقد صحيح وأنه ليس بكافر كفراً أكبر، ولكنه كفر أصغر.\nوالقول الصحيح: أنه كفر أكبر وأن العقد غير صحيح، وأنه يجب فسخ النكاح ويجب عليه طلاقها أو يفسخ النكاح، من جهة الحاكم الشرعي؛ لأن الزوجة لا تصلح للمسلم، أن تكون زوجة وهي تترك الصلاة، لكن إن تابت فله أن يعقد عليها عقداً جديداً، إذا كان هو يصلي وهي لا تصلي، ...: له أن يعقد عليها عقداً جديداً إذا تابت، أما بدون توبة فإن العقد غير صحيح فاسد، وعليه أن يطلقها طلقة واحدة، أو يفسخها الحاكم حتى لا تبقى علقة بينهما ولا شبهة بينهما، ومتى تابت أمكنه أن يتزوجها من جديد بالشروط الشرعية.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8734/حكم-العقد-لمن-عقد-على-امراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32204.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":10572,"question":"سماحة الشيخ! مع بداية هذه الحلقة أمامي رسالتان، الأولى: من الأخت المستمعة (ج. أ. ف) من العراق، والثانية: من الأخت نادية آل محمد السعيد من الجزائر، الرسالتان اتحدتا في السؤال عن خطبة زوج لا يصلي ولاسيما إذا تدخل الوالدان في ذلك وأرغما البنت على القبول بهذا الخاطب رغم أنه لا يصلي، كيف يكون تصرف المخطوبة جزاكم الله خيراً، وهل تلجأ إلى الجهات الرسمية كي تسلم من هذه الخطبة؟","title":"حكم الزواج بمن لا يصلي ونُصح الآباء في ذلك","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فأسأل الله  بأسمائه الحسنى وصفاته العلى أن يولي على العراق حاكماً صالحاً يحكم فيهم بشرع الله، وأن يصلح حكام الجزائر ويوفقهم لما فيه رضاه وأن يعينهم على تحكيم شريعته، وأن يصلح أحوال الجميع، نسأله سبحانه أن يصلح أحوال الشعب العراقي وأحوال الشعب الجزائري، وأن يولي على العراق من يحكم فيهم بشرع الله، وأن يولي على جميع بلاد المسلمين من يحكم فيهم بشرع الله.\nأما جواب السائلتين فلاشك أن من لا يصلي لا يجوز للمسلمة أن تقبل الزواج منه؛ لأن ترك الصلاة كفر، والصواب: أنه كفر أكبر، وقال الأكثرون: أنه كفر أصغر.\nوالصواب: أنه كفر أكبر وإن كان لا يجحد الوجوب، أما إذا كان يجحد الوجوب فهذا كفر أكبر عند جميع العلماء ليس فيه خلاف، ولكن الخلاف فيما إذا كان لا يجحد الوجوب ولكنه يتكاسل عن الصلاة يتركها كلها أو بعضها، فالصواب في هذا الصنف وأمثاله أنه كافر كفر أكبر؛ . لقول النبي ﷺ في الحديث الصحيح الذي رواه مسلم في الصحيح عن جابر  : بين الرجل وبين الكفر والشرك ترك الصلاة والأصل في هذا الكفر الأكبر، الكفر المعرف والشرك المعرف بأل فهو كفر أكبر.\nوروى الإمام أحمد رحمه الله وأهل السنن رحمهم الله بإسناد صحيح عن بريدة  عن النبي ﷺ أنه قال : العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وثبت عنه ﷺ أنه لما سئل عن الأمراء الذين تعرف منهم بعض المنكرات وعن الخروج عليهم، قال له: اسمعوا وأطيعوا ونهى عن الخروج عليهم- قال: إلا أن تروا كفراً بواحاً عندكم من الله فيه برهان وفي رواية أخرى قال: ما أقاموا فيكم الصلاة فدل على أن عدم إقامة الصلاة كفر بواح.\nفالحاصل: أن ترك الصلاة مطلقاً أو بعضها كالظهر أو الفجر أو نحو ذلك كفر أكبر، فلا يجوز للولي سواء كان أباً أو غير أب أن يجبر المولية على نكاح من لا يصلي وهي تصلي وهي مسلمة، بل هذا خيانة للأمانة، بل يجب عليه أن يلتمس لها الرجل الصالح الطيب حتى يضع الأمانة في محلها، ولا يجوز للبنت أن تطيعه في ذلك ولو كان أباها؛ لقول النبي ﷺ: إنما الطاعة في المعروف وقوله ﷺ: لا طاعة لمخلوق في معصية الخالق ولها أن ترفع الأمر إلى ولي الأمر إلى الحاكم الشرعي حتى يخلصها من هذا البلاء.\nوالواجب على الأولياء أن يتقوا الله، وأن لا يزوجوا مولياتهم إلا على الأكفاء، وأهم شيء الكفء في الدين إذا كانت المولية مسلمة، والله يقول جل وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ [التوبة:71] فالكافر ليس ولياً للمؤمنة، ولا يجوز لوليها أن يزوجها بتارك للصلاة أو معروف بالفسق إذا لم ترض بذلك، وهذا فيما يتعلق بغير الكفر، أما بالكفر فلا يجوز لها الرضا، ولو رضيت لا يجوز لها أن تزوج بالكافر وهي مسلمة.\nلكن الفسق لو كان عنده بعض الفسق كشرب الخمر وهو يصلي، أو يتعاطى بعض المعاملات الربوية، أو يتهم بشيء من الأعمال المنكرة، الأعمال التي هي تعتبر معصية، هذا يجوز للمسلمة أن تتزوجه، لكن تركه أولى والتماس الطيب أولى بالمؤمنة، أما الكافر فلا ليس لها أن تتزوج الكافر، كالذي يسب الدين، أو يستهزئ بالدين، أو يترك الصلاة أو ما أشبه ذلك مما يوجب كفره، كالذي يستحل الخمر أو يستحل الزنا هذا كفر أكبر نسأل الله العافية، أو يستحل الربا.\nفالحاصل أن الواجب على الأولياء أن لا يزوجوا مولياتهم المسلمات إلا بمسلمين، وليس له أن يزوج موليته المسلمة بمن يترك الصلاة أو يتعاطى ما يوجب كفره نسأل الله السلامة والعافية. نعم.\nالمقدم: جزاكم الله خيراً، إذاً كلمة للوالدين لعله من المناسب أن تتفضلوا بها الآن؟\nالشيخ: تكلمنا سابقاً ليس للوالدين ولا غير الوالدين أن يزوجوا المولية بمن يخالفها في الدين، إذا كانت مسلمة ليس له أن يزوجها كافراً، لا نصرانياً ولا يهودياًَ ولا وثنياً ولا تاركاً للصلاة ولا غيرهم ممن يحكم عليه بكفر، كالساب للدين، والمستهزئ بالرسول أو بالدين ونحو ذلك ممن يحكم بكفره، حتى العاصي ينبغي أن لا يزوجها العاصي وإن كان مسلماً، ينبغي أن يلتمس لها الطيب الكفء، لكن لو تزوجت بمسلم عاصي برضاها صح، لكن كونه يلتمس لها الطيب البعيد عن المعاصي هذا من أداء الأمانة، وإذا كرهت الزواج بالعاصي لم يجبرها على العاصي حتى العاصي لا يجبرها عليه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8741/حكم-الزواج-بمن-لا-يصلي-ونصح-الاباء-في-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32301.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":10581,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ل. و. ك) يقول: أنا شاب تزوجت وكان عمري فوق السادسة عشرة، وكنت في ذلك الوقت لا أصلي، وكانت زوجتي تصلي وأنا لا أصلي، وقد جلست مع زوجتي مدة طويلة حوالي سنة أو أكثر، وبعد ذلك لجأت إلى الله وتبت واستغفرت وندمت على هذا المنكر، وبعد فترة من التوبة حملت زوجتي وأنجبت لي ولداً، وتم بيننا التوفيق بعد ذلك، سؤالي يقول:ما حكم عقد النكاح؟ وهل هو باطل أم هو صحيح؟ وما حكم الوقت الذي قضيته مع زوجتي قبل التوبة وبعد التوبة؟ وما حكم العقد بعد التوبة هل يكفي أم لا يجوز إلا بتجديد العقد؟ وما حكم الولد بعد التوبة؛ لأنه جاء بعدها؟ وهل توبتي تكفي أم علي شروط يجب علي أن أعملها مثل الكفارة أو الصيام أو غير ذلك جزاكم الله خيراً؟","title":"حكم من تزوج بامرأة تصلي وهو لا يصلي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد: فلا شك أن ترك الصلاة من أعظم الجرائم، ومن أكبر المنكرات؛ لأنها عمود الإسلام، من حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع، وقد دل الحديث الصحيح عن رسول الله عليه الصلاة والسلام أن تركها كفر، فقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة رواه الإمام مسلم في صحيحه، وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، والأحاديث في هذا المعنى كثيرة، لكن ينظر في تارك الصلاة، فإن كان قد جحد وجوبها ولم يقر بوجوبها فهذا كافر عند جميع العلماء، والعقد باطل إذا تزوج امرأة تصلي وهو لا يصلي فعقده باطل؛ لأن الله جل وعلا قال في حق الكفرة مع المسلمين: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] فلا يحل للكافر نكاح المسلمة، ولا للمسلمة نكاح الكافر، ويقول جل وعلا: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221]، يعني: لا تزوجوا المشركين حتى يؤمنوا.\nأما إن كان السائل يؤمن بوجوبها ويعلم أنها فريضة، ولكن يتهاون فتركها تهاوناً فهذا النكاح فاسد على الصحيح، ولكن ولدك هذا تابع لك، لأجل الشبهة؛ لأن بعض أهل العلم يرى أنه ليس بكافر، إذا كان يعتقد وجوبها ولكنه تكاسل، فيرى أنه ليس بكافر كفراً أكبر، ولكنه كفر أصغر، ويرى أن النكاح صحيح، وأن ولده لاحق به، فأنت بهذه الحال إذا كنت لا تجحد وجوبها فالولد لاحق بك؛ لأجل الشبهة.\nوالصحيح أن تركها كفر أكبر، لكن من أجل الشبهة الولد لاحق بك، وعليك أن تجدد النكاح، وأن تتوب إلى الله مما سلف توبة صادقة، وعليك أن تجدد النكاح بعقد شرعي ومهر وشاهدين، إذا كانت تريدك وأنت تريدها، فإنك تجدد النكاح هذا هو الصواب.\nوأولادك لاحقون بك الذين ولدوا قبل التجديد، وعليك التوبة إلى الله والندم والإقلاع من هذا العمل السيئ، والعزم الصادق أن لا تعود فيه، ومن تاب تاب الله عليه، كما قال الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وقال النبي ﷺ: التائب من الذنب كمن لا ذنب له، فالحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8753/حكم-من-تزوج-بامراة-تصلي-وهو-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_324/32401.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":10696,"question":"سماحة الشيخ! يشكو كثير من النساء من أنهن ابتلين بأزواج لا يصلون، ولم يكتشفن هذا إلا بعد الزواج؟","title":"حكم بقاء المرأة عند زوج لا يصلي","answer":"الجواب: هذا من البلاء العظيم، فإذا عرفت ذلك تمتنع منه وتذهب إلى أهلها، ولا تمكنه من نفسها، لا من جماع ولا غيره حتى يتوب إلى الله ويستقيم على الصلاة، وإلا فالواجب الفراق. نعم.\nالمقدم: قد تتحجج بالأطفال، وما أدراك ما الأطفال؟\nالشيخ: ليس في هذا حجة، الرزق على الله، هي أولى بأطفالها حتى يهديه الله.\nالمقدم: والحالة هذه.\nالشيخ: نعم.\nالمقدم: جزاكم الله خيراً.\nالشيخ: الله المستعان، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/8861/حكم-بقاء-المراة-عند-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33011.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":10798,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من نينوى في العراق، وباعثتها إحدى المستمعات، تقول المستمعة أم هديل من العراق تقول: استشهد زوجها في الحرب في اليوم العاشر من شهر رمضان المبارك، وكان لا يصلي، ولكنه كان ينوي أن يصلي بعد انتهاء الحرب، ولكنه استشهد قبل أن يصلي، فهل يجوز أن أصلي بدلًا عنه، وإنني أنفق كثيرًا بغية الثواب له، فهل تصله النفقات التي أنفقها من راتبي، وليس من راتب ابنتي الوحيدة التي عمرها سنتان؟ بعض الناس يقولون: لا يجوز أن تنفقي؛ لأن في عصمتك قاصرة، علمًا بأني غير محتاجة، وجهوني جزاكم الله خيرًا.","title":"حكم الدعاء والصدقة عن ميت لا يصلي","answer":"الجواب:  الذي مات وهو لا يصلي لا يصلى له، والصلاة ما يفعلها أحد عن أحد، الصلاة لا تفعل عن أحد، والذي مات وهو لا يصلي تقدم في الجواب السابق أنه كافر -نسأل الله العافية- ترك الصلاة كفر أكبر على الصحيح، وإن لم يجحد الوجوب، كونه يعزم أنه يصلي بالمستقبل، هذا ما هو عذر له، الواجب البدار بالصلاة، فلا تتصدقي عنه، ولا تصلين له، ولا تدعين له ما دام مات على ترك الصلاة -نعوذ بالله من ذلك- ولا تنفقي من مال اليتيمة لا في حقه، لا له ولا لغيره، مال اليتيمة احفظيه لها، وثمريه لها، أو أعطيه إنسانًا من التجار الطيبين يثمره لها، تصدقي من مالك أنت. المقدم: لهذا .... أو لنفسها؟ الشيخ: أما الزوج الذي توفي على هذه الحالة وهو يترك الصلاة لا تتصدقي عنه بشيء، ولا تدعين له، ولا تستغفرين له؛ لأنه مات على الكفر، نسأل الله العافية. أما الصدقة من مالك في وجوه البر للفقراء والمساكين ما هو بعن زوجك، بل لنفسك، مصلحتك أنت، تصدقي على الفقراء والمساكين في عمارة مسجد، في جهاد في سبيل الله، كل هذا لك أجره، أما هو لا، ما دام مات وهو لا يصلي لا تتصدقي عنه.","link":"https://binbaz.org.sa/fatwas/8978/حكم-الدعاء-والصدقة-عن-ميت-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35208.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":10817,"question":"آخر سؤال لفتاة القرية في هذه الحلقة يقول: إن والدتها وهي صغيرة كانت تترك الصلاة، ليس تساهلًا ولكن جهلًا، ولا تعلم كم كان عدد هذه الصلوات، والآن تسأل بعد أن تابت والحمد لله وأصبحت تحافظ على الصلوات، تسأل: كيف التصرف فيما مضى؟ جزاكم الله خيرًا.","title":"حكم من ترك الصلاة جهلاً ثم تاب","answer":"الجواب:  يكفيها التوبة والحمد لله، ليس عليها قضاء، عليها التوبة، والتوبة حصلت والحمد لله؛ لأن ترك الصلاة كفر، والتوبة تكفي في ذلك والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8997/حكم-من-ترك-الصلاة-جهلا-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35408.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":10823,"question":"آخر سؤال لفتاة القرية في هذه الحلقة يقول: إن والدتها وهي صغيرة كانت تترك الصلاة، ليس تساهلًا ولكن جهلًا، ولا تعلم كم كان عدد هذه الصلوات، والآن تسأل بعد أن تابت والحمد لله وأصبحت تحافظ على الصلوات، تسأل: كيف التصرف فيما مضى؟ جزاكم الله خيرًا.","title":"حكم من ترك الصلاة جهلاً ثم تاب","answer":"الجواب:  يكفيها التوبة والحمد لله، ليس عليها قضاء، عليها التوبة، والتوبة حصلت والحمد لله؛ لأن ترك الصلاة كفر، والتوبة تكفي في ذلك والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8997/حكم-من-ترك-الصلاة-جهلا-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35408.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":10881,"question":"سؤال لأحدهما يقول: أنا مواطن مصري أشتغل في الأردن تزوجت من عام (73) ميلادية، وعندي خمسة أولاد، وعقدت عقد الزواج على زوجتي، وهي لا تصلي، وأنا -الحمد لله- أصلي، وكنت لا أعرف أن عقد الزواج باطل إذا كان أحد الزوجين لا يصلي إلا من برنامجكم نور على الدرب، هل يجوز أن أعقد على زوجتي عقدًا جديدًا بشاهدي عدل، وولي بدون المأذون الشرعي والمحكمة، خوفًا من الوقوع في معصية مع زوجتي عند ذهابي إلى مصر؛ لأن المأذون والمحكمة سوف يعقدان بعد إجراءات طويلة ووقت طويل، وما مصير الأولاد الخمسة؟","title":"حكم عقد النكاح بامرأة لا تصلي","answer":"الجواب:  نعم الصواب أن الرجل إذا تزوج امرأة لا تصلي، أو تزوجها وهي تصلي وهو لا يصلي أن العقد لا يصح في أصح قولي العلماء؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء لقوله ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، أخرجه الإمام أحمد، وأهل السنن بإسناد صحيح عن بريدة بن حصيب  ولقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه، وهناك أحاديث أخرى كذلك تدل على هذا المعنى. فإذا وقع هذا النكاح بين رجل يصلي وهي لا تصلي، أو بالعكس فإنه يجدد من شاهدين عدلين، والمأذون الشرعي مع الولي لابد من الولي إما بحضور الولي، وإلا وكيل الولي، وليس هناك ضرورة إلى المحكمة، ولا إلى المأذون، بل إذا حضر الولي والزوج وشاهدين، وزوجه وليها بعدما تاب الله على من لا يصلي، واستقامت الأحوال فإنه يكفي، يقول له الولي: زوجت، ويقول الزوج: قبلت بحضرة شاهدين إذا كان راضية المرأة بذلك فالحمد لله. أما الأولاد فهم يلحقون لأجل شبهة النكاح، وذهب الأكثرون إلى أنه يصح النكاح، ولو كان لا يصلي إذا كان موحدًا لله، مؤمنًا بالإسلام، يؤمن بالآخرة، وليس عنده من النواقض إلا ترك الصلاة، فقال الأكثرون: أن تركها لا يكون كفرًا أكبر، بل يكون كفرًا دون كفر، ولا يكون كفرًا أكبر يبطل النكاح. ولكن الصواب قول من قال بأنه كفر أكبر للأحاديث السابقة وغيرها من الأحاديث الدالة على ذلك، ولأن الصلاة عمود الإسلام، لا يقاس عليها غيرها، هي عمود الإسلام. فالواجب على من تركها أن يبادر بالتوبة، وأن يدخل في الإسلام من جديد بتوبته إلى الله  ويجدد النكاح إذا كانت زوجته طيبة مصلية سليمة وهو المقصر بترك الصلاة يجدد النكاح.  أو بالعكس هي لا تصلي وهو يصلي يجدد النكاح، وليس من شرط ذلك أن يكون عند المحكمة، أو عند المأذون إذا وجد الولي والشاهدان العدلان والزوج وهي راضية كفى والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9065/حكم-عقد-النكاح-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35911.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":10963,"question":"ننتقل إلى رسالة أخرى وصلت إلى البرنامج من المستمع صفاء حميد من العراق، أخونا له جمع من الأسئلة في أحدها يسأل ويقول: ما حكم الإسلام في امرأة تصلي وتصوم، ولكنها لا تتحجب؟","title":"حكم صلاة وصوم امرأة لم تتحجب","answer":"الجواب: صومها صحيح، وصلاتها صحيحة، والحمد لله، وعليها التوبة من ترك التحجب، المعاصي لا تبطل صلاتها، ولا صومها، هذه معصية عدم التحجب، أو كونها قد تتكلم كلامًا ما هو طيب، كالغيبة، أو النميمة، هذا لا يبطل صلاتها، ولكنه نقص في إيمانها، وضعف في إيمانها، وعليها التوبة إلى الله من ذلك. فهكذا الحجاب، وإنما تترك التحجب عن الرجال هذه معصية، لكن صومها لا يبطل، وصلاتها لا تبطل، إنما عليها التوبة من ذلك، ويعتبر عدم التحجب ضعفًا في الإيمان، وكذلك كونها تغتاب الناس، أو تفعل أشياء من المعاصي غير ذلك، هذا نقص في الإيمان، وضعف في الإيمان، فإذا أدت الصلاة بشروطها وواجباتها، في وقتها، صلاتها صحيحة. وهكذا الصوم، إذا صامت عن ما حرم عليها تعاطيه في حال الصوم، صومها صحيح، ويؤدي عنها الفرض، لكن إذا كانت تتعاطى في بعض المعاصي، يكون نقص في صومها، كالغيبة، أو الكذب ونحو ذلك، يكون نقصًا في صومها، وضعفًا في دينها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9142/حكم-صلاة-وصوم-امراة-لم-تتحجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_364/36409.mp3","categories":["حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":11006,"question":"من المملكة الأردنية الهاشمية، هذه رسالة بعث بها مستمع من هناك هو (خ. ش) يقول في أحد أسئلته: أنا شاب عمري خمسة وعشرون عامًا، انقطعت عن الصلاة تهاونًا لمدة تسع سنوات، والآن قد تبت إلى الله، لكنني حائر في أمر الصلوات الماضية هل أقضيها، وإذا كنت سأقضيها هل أصلي مع كل فرض جديد فرضًا قديمًا حتى تنتهي المدة؟ أفيدوني أفادكم الله.","title":"حكم قضاء الصلوات لمن تاب من تركها","answer":"الجواب:  الحمد لله الذي من عليك بالتوبة، ونوصيك بلزوم التوبة والاستقامة عليها، وشكر الله على ذلك  والحذر من صحبة الأشرار الذين قد يجرونك إلى العودة إلى ترك الصلاة. وأما القضاء فليس عليك قضاء، التوبة كافية؛ لأن التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله، والذين ارتدوا في عهد الصحابة  لما تابوا لم يأمرهم الصحابة بالقضاء. فالمقصود: أن التوبة تكفي والحمد لله، يقول النبي ﷺ: الإسلام يهدم ما كان قبله، والتوبة تهدم ما كان قبلها، فليس عليك قضاء للصلوات الماضية، السنوات التسع، وعليك أن تلزم التوبة، وهي الندم على ما مضى، التوبة حقيقتها الندم على الماضي من الفعل السيئ، والإقلاع من ذلك والحذر منه، مع العزم الصادق أن لا تعود في ذلك. فنوصيك يا أخي! بلزوم التوبة، والاستقامة عليها، وسؤال الله الثبات على الحق، والاستقامة عليه، كما نوصيك بالمحافظة على الصلاة، وأداءها في الجماعة في المساجد، والحذر من صحبة الأشرار الذين قد يجرونك إلى ما حرم الله من ترك الصلاة، أو غير ذلك من الشرور، نسأل الله لنا ولك التوفيق والثبات على الحق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9169/حكم-قضاء-الصلوات-لمن-تاب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36503.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":11100,"question":"يقول هذا السائل سماحة الشيخ: رجل يهمل أداء صلاة الفجر؛ لعدم استيقاظه مبكرًا ويصلي الأخريات، الفروض الأخرى في أوقاتهن، فهل يقبل منه هذا العمل؟ وهل يوجد عندكم ما تنصحونه به؟ جزاكم الله خيرًا.","title":"حكم من يهمل الفجر ويحافظ على بقية الصلوات","answer":"الجواب:  لا يجوز للمسلم أن يتساهل في هذا الأمر، لا يجوز له أن يهمل الفجر، ولا غير الفجر، يجب أن يحافظ على الجميع في أوقاتها مع الجماعة، وليس له أن يهمل الفجر ولا الظهر ولا العصر ولا المغرب ولا العشاء، بل يجب أن يحافظ على الجميع في الجماعة، في بيوت الله مع إخوانه المسلمين، فإذا قصر في ذلك كان عاصيًا متشبهًا بالمنافقين، يستحق أن يؤدب من جهة ولاة الأمور. أما إن تركها بالكلية، تركها حتى طلعت الشمس متعمدًا فإنه يكفر في أصح قولي العلماء، نسأل الله العافية، لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، فالذي يتعمدها، ويجعل الساعة على وقت الذهاب إلى عمله بعد الشمس هذا متعمد، فظاهر الحديث كفره، وهو الأصح أن من تعمد ترك واحدة حتى يخرج وقتها كفر، فالواجب الحذر غاية الحذر من هذا العمل السيئ. وإذا كان أسباب ذلك السهر لا يسهر، يبادر بالنوم حتى يقوى على القيام في الفجر، فالغالب على هؤلاء أنهم يسهرون، فإذا جاء الفجر ماتوا، هذا خطأ، هذا منكر، فالواجب عليهم أن يبكروا حتى يناموا نومة تكفيهم، وحتى يستطيعوا القيام للفجر، يوقت له الساعة، ويقوم يصلي مع المسلمين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9278/حكم-من-يهمل-الفجر-ويحافظ-على-بقية-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29008.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11145,"question":"من مكة المكرمة رسالة بتوقيع إحدى الأخوات تقول: المرسلة (أ. ع. ق) أختنا تسأل سؤالين في أحد أسئلتها تقول: ما الحكم إذا قال شخص -عن جهل-: بأن حكم تارك الصلاة كافر دون أن يقصد شخصًا بعينه، هل يلزمه أن يتوب من ذلك، ويأثم على قوله، أم كيف توجهونه؟ جزاكم الله خيرًا.","title":"ما حكم تكفير تارك الصلاة؟","answer":"الجواب:  الذي يقول هذا الكلام مصيب، قد قاله النبي -عليه الصلاة والسلام- قد قاله سيد الخلق -عليه الصلاة والسلام- في الحديث الصحيح، يقول -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة، رواه مسلم في الصحيح. ويقول أيضًا -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، خرجه الإمام أحمد، وأهل السنن: أبو داود والترمذي والنسائي وابن ماجة بإسناد صحيح، عن بريدة بن الحصيب . فالواجب الحذر، فالصلاة عمود الإسلام، من تركها كفر -نعوذ بالله من ذلك- فالواجب على الرجال والنساء الحذر من تركها، والتهاون بها، والواجب المحافظة عليها في أوقاتها بخشوع وطمأنينة كما قال الله سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] وقال سبحانه: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:9-11]. وقال في سورة المعارج: وَالَّذِينَ هُمْ عَلَى صَلاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ فِي جَنَّاتٍ مُكْرَمُونَ [المعارج:34-35] الواجب على جميع المسلمين العناية بالصلاة، والحرص عليها، والمحافظة عليها في أوقاتها بالخشوع والطمأنينة والعناية، وعلى الرجل أن يؤديها في جماعة، في مساجد الله مع إخوانه، وليحذر كل الحذر من صفات المنافقين، الذين يتكاسلون عنها قال الله تعالى في حقهم: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142]. فالواجب عليك يا عبدالله! وعليك يا أمة الله! الحذر من صفة المنافقين، والواجب العناية بالصلاة، والمحافظة عليها غاية المحافظة، بالطمأنينة في ركوعها وسجودها، وسائر أحوالها، وأداؤها في الوقت، والرجل يؤديها مع إخوانه في المساجد في الجماعة، ولا يتشبه بأهل النفاق، نسأل الله للجميع الهداية والتوفيق، نعم. المقدم: اللهم آمين! جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9333/ما-حكم-تكفير-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_370/37009.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11177,"question":"هل يصلح أن أصلي عن شخص متوفٍ ترك صلاته بعض الوقت ولم يصل؟","title":"حكم قضاء الصلاة عن الميت التارك لها","answer":"الجواب:  الصلاة لا تقضى، الصلاة لا تقضى، إن كان تركها عمدًا فهذا كفر أكبر نعوذ بالله، وإن تركها من غير شعوره، اختل شعوره فلا شيء عليه. المقصود أن الصلاة لا تقضى، سواء تركها عن شعور أو عن غير شعور، فإن كان عن شعور وتعمد، هذا كفر أكبر نعوذ بالله، لا يصلى عليه ولا يغسل، ليس بمسلم على الصحيح، أما إن كان تركها لأجل اختلال الشعور، أي: بسبب شدة المرض اختل شعوره فلا شيء عليه، ولا تقضى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9376/حكم-قضاء-الصلاة-عن-الميت-التارك-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37220.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":11182,"question":"هل يصلح أن أصلي عن شخص متوفٍ ترك صلاته بعض الوقت ولم يصل؟","title":"حكم قضاء الصلاة عن الميت التارك لها","answer":"الجواب:  الصلاة لا تقضى، الصلاة لا تقضى، إن كان تركها عمدًا فهذا كفر أكبر نعوذ بالله، وإن تركها من غير شعوره، اختل شعوره فلا شيء عليه. المقصود أن الصلاة لا تقضى، سواء تركها عن شعور أو عن غير شعور، فإن كان عن شعور وتعمد، هذا كفر أكبر نعوذ بالله، لا يصلى عليه ولا يغسل، ليس بمسلم على الصحيح، أما إن كان تركها لأجل اختلال الشعور، أي: بسبب شدة المرض اختل شعوره فلا شيء عليه، ولا تقضى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9376/حكم-قضاء-الصلاة-عن-الميت-التارك-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37220.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":11229,"question":"تقول: والدي رجل كبير في السن، وهو الآن مريض جدًا، ودائمًا يريد أن يجلس عنده أي فرد من الأسرة، ثم تستمر في وصف حاله إلى أن تقول: إنه كان يصلي وكان يقوم الليل، لكنه الآن لا يصلي نتيجة لعدم معرفته للأوقات؛ لكونه لا يسمع ولا يرى، فبماذا توجهوننا ولاسيما وخوفنا عليه شديد جدًا؟","title":"حكم من ترك الصلاة لكبر سنه ومرضه","answer":"الجواب:  إذا كان يعقل عقله معه لم يتغير عقله، يعلم بالكتابة أو بالإشارة التي يفهمها، إذا دخل الوقت حتى يصلي، وهكذا جميع الشؤون التي يحتاج إلى تعليم يعلم إياها، بالإشارة أو بالكتابة أو بأي طريقة يفهمها إذا كان عقله معه، أما إذا كان قد اختل عقله فليس عليه شيء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9420/حكم-من-ترك-الصلاة-لكبر-سنه-ومرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37317.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11257,"question":"من جدة رسالة بعثت بها إحدى الأخوات المستمعات تقول: أم ياسر مصرية أختنا لها قضية تقول فيها: كانت والدتي لا تصلي، ثم إنا علمناها الصلاة والحمد لله، واستجابت وداومت على الصلاة بفضل من الله، ثم إنها أيضًا تخلصت من المعتقدات الشركية مثل الاعتقاد بنفع الموتى وما أشبه ذلك، إلا أن لنا والدًا لا يصلي، ولا زالت ترتبط به نفسيًا ومعنويًا، فما هو رأي سماحتكم في هذا الموضوع جزاكم الله خيرًا؟","title":"حكم تمكين المرأة نفسها من زوج لا يصلي","answer":"الجواب:  الحمد لله على هدايتها، ولكن ليس لها أن تمكن زوجها الذي لا يصلي من نفسها؛ لأن ترك الصلاة كفر أكبر، فعليها أن تبتعد عنه وأن تخبره بأنها لا تحل له، وأخبروه أنتم أيضًا حتى يتوب، فإذا تاب وصلى فهي زوجته، وإن استمر في ترك الصلاة فهي تحرم عليه، ونسأل الله لنا وله الهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا وأحسن وإليكم.","link":"https://binbaz.org.sa/fatwas/9439/حكم-تمكين-المراة-نفسها-من-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37412.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":11291,"question":"من المستمعة (ج. هـ) من القصيم رسالة وضمنتها سؤالين، في سؤالها الأول تقول: قبل ثلاث سنوات كنت مسرفة على نفسي كثيرًا، وكنت مفرطة في الصلوات وفي الصوم، ولكن أنا الآن نادمة وتائبة، وسؤالي: كنت في أيام الغفلة ومضى علي سنتان وأنا لم أصم ولا أصلي، فهل يجب علي قضاء ما فات من صلاة وصيام؟أم كيف توجهونني؟ جزاكم الله خيرًا,","title":"حكم قضاء الصلاة والصيام على من تركها","answer":"الجواب: الصواب التوبة كافية إن شاء الله، ولا قضاء عليك، لا قضاء عليك والحمد لله، التوبة كافية، يقول النبي ﷺ: التوبة تجب ما قبلها.  والتائب من الذنب كمن لا ذنب له فلا قضاء عليك لا للصلاة ولا للصيام؛ لأن ترك الصلاة كفر، والكافر إذا أسلم لا يقضي ما مضى، قال الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [لأنفال: 38]، يغفر لهم ما قد سلف. فالمرتد لا يقضي ما سلف ولكن عليه التوبة والاستقامة والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9483/حكم-قضاء-الصلاة-والصيام-على-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37615.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":11474,"question":"هل يقبل الصيام من رجل لا يصلي؟","title":"حكم قبول الأعمال الصالحة من تارك الصلاة","answer":"الجواب:  لا يقبل، ولا تصح بقية الأعمال؛ لأنه بكفره حبط عمله -نسأل الله العافية-.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9658/حكم-قبول-الاعمال-الصالحة-من-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38204.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11482,"question":"يقول: هناك رجل يصلي صلاة الجمعة فقط دون أن يصلي بقية الفروض، هل تقبل صلاته؟","title":"حكم من يصلي الجمعة فقط ويترك سائر الصلوات","answer":"الجواب:  هو كافر، لا تقبل صلاته، صار كافرًا بذلك، فصلاته الجمعة، وصومه، وسائر أعماله كلها باطلة، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، وقال سبحانه: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ [المائدة:5]، فمن كفر كفرًا أكبر، أو شركًا أكبر؛ حبط عمله -نسأل الله العافية- وترك الصلاة كفر أكبر، نسأل الله العافية، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9657/حكم-من-يصلي-الجمعة-فقط-ويترك-ساىر-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38203.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11531,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من دولة الكويت، باعث الرسالة المستمع: عادل السعيد، الأخ عادل يقول: قصتي أنني أريد شيئًا يمسك بي، ونصيحة منكم تفيدني في ديني ودنياي وآخرتي، مشكلتي: أنني أصلي، وأعزم التوبة النصوح، ثم أعود، وأترك الصلاة، ثم أصلي وأترك حوالي أسبوعًا، وهكذا وهكذا.. أرجو أن توجهوني سماحة الشيخ حتى أستقيم استقامة مستمرة؟ جزاكم الله خيرًا، وأحسن إليكم.","title":"ما النصيحة للشباب المقصِّرين في الصلاة؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فوصيتي لك أن تتقي الله -عز وجل- وأن تراقبه سبحانه في جميع الأحوال، وأن تعلم أن الصلاة هي عمود الإسلام، وأنها الركن الثاني من أركانه، وأن تركها كفر بالله . فالواجب عليك الحذر، وأن تسأل ربك الثبات والتوفيق للاستقامة، وأن تراقبه، وتستحضر أنك مسؤول، وأنك على خطر أن تموت في تلك الحالة التي تركت فيها الصلاة فتكون إلى النار، يقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ويقول أيضًا -عليه الصلاة والسلام-: من حافظ عليها؛ كانت له نورًا، وبرهانًا، ونجاة يوم القيامة، ومن لم يحافظ عليها؛ لم يكن له نور، ولا برهان، ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف يعني: إلى النار، وما ذاك -والله أعلم- إلا لأن التارك للصلاة إما أن يتركها من أجل الرياسة؛ فيحشر مع فرعون إلى النار؛ لأن فرعون شغلته الرياسة عن طاعة الله والرسول، وإما أن يتركها من أجل الوظيفة؛ فيحشر مع هامان وزير فرعون ؛ لأنه شغله عمله مع فرعون عن طاعة الله، وتصديق رسوله -عليه الصلاة والسلام- وإما أن يترك الصلاة من أجل المال والشهوات، فيكون شبيهًا بقارون الذي خسف الله به، وبداره الأرض، فيحشر معه إلى النار، وإما أن يدعها من أجل التجارة والبيع والشراء؛ فيكون شبيهًا بـأبي بن خلف تاجر أهل مكة الكافر؛ فيحشر معه إلى النار. فالواجب على كل مسلم أن يتقي الله، وأن يراقب الله في كل أموره، وأن يجتهد في المحافظة على الصلوات في أوقاتها في الجماعة، فإن من حافظ عليها؛ فقد حفظ دينه، ومن ضيعها؛ فهو لما سواها أضيع، فاتق الله يا عادل، وسل ربك التوفيق، وحافظ عليها في أوقاتها في الجماعة، وتب إلى الله مما سلف توبة صادقة، ومن تاب تاب الله عليه. نسأل الله لك الصلاح والهداية، والتوفيق للتوبة النصوح. المقدم: جزاكم الله خيرًا، وأحسن إليكم. هل يأذن لي سماحة الشيخ أن نقف قليلًا عند هذه القضية؛ لأنها قضية -فيما أعتقد- أنها تهم كثيرًا من الشباب؟ الشيخ: نعم. المقدم: بارك الله فيكم، ما بودي أن تتفضلوا أيضًا بمعالجته سماحته الشيخ ذلكم المؤثر على الشباب: من حيث الجلساء، من حيث القراءة، من حيث السفر -لو تكرمتم-؟ الشيخ: نعم، أوصي الشباب وغير الشباب أوصي الجميع بتقوى الله، وأن يحذروا أسباب التخلف عن طاعة الله، وعن الصلاة، وأن يحذروا صحبة الأشرار الذين يثبطون عن كل خير، وعن الصلاة، وأن يحذروا قراءة المجلات الضارة، والصحف الضارة، والكتب الضارة، وأن يعتنوا بالقرآن الكريم، فإن القرآن هو الشفاء من كل داء إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] فأوصي الجميع بالعناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، فإن ذلك من أسباب صلاح القلوب، وصلاح الأعمال، مع دعاء الله، والضراعة إليه، وسؤاله الهداية والتوفيق، هذه وصيتي للجميع، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين. بارك الله فيكم، وجزاكم الله خيرًا، ماذا عن تأثير الأسفار سماحة الشيخ؟ الشيخ: أما السفر ففيه تفصيل: السفر فيه تفصيل: إن كان لديه حاجة إلى بلد مسلم؛ فلا بأس، قد سافر المسلمون، وسافر الصحابة، كونه يسافر للبيع والشراء في بلاد المسلمين لحاجات أخرى لا بأس، أما أن يسافر لبلاد الكفر؛ فهذا لا يجوز، يحذر! يجب الحذر من السفر إلى بلاد الكفر؛ لأن السفر إليها من أسباب الردة، ومن أسباب الوقوع في معاصي كثيرة، ومن أسباب قسوة القلوب والغفلة، ولهذا يقول النبي ﷺ: أنا بريء من كل مسلم يقيم بين المشركين ويروى عنه  أنه قال: من جامع المشرك، وسكن معه؛ فهو مثله. فالواجب الحذر من السفر إلى بلاد الشرك لما فيه من الخطر العظيم، إلا من كان عنده علم وبصيرة يسافر إلى الدعوة إلى الله، وتعليم الناس في وقت لا خطر فيه، وفي مكان لا خطر فيه؛ فهذا لا بأس به، ولكن الواجب الحذر، مهما كانت ... الواجب الحذر، نعم. المقدم: بارك الله فيكم، قد يكون هناك أمور دنيوية يضطر الإنسان للسفر لبلاد الكفر من أجلها، فما هو توجيه سماحة الشيخ؟ الشيخ: التجارة لا يسافر لأجلها، يحذر! بالمكاتبة تأتيه التجارة من دون السفر. أما المرض فهو محل نظر، إذا لم يتيسر علاجه في بلاد المسلمين، واضطر ضرورة لابد منها؛ فهذا قد يباح له مع الحذر، ومع صحبة الطيبين، كونه يصحب الناس الطيبين، ويحذر التجول، والذهاب إلى مخالطة المشركين، بل يقصد محل العلاج، ويلزم محل العلاج، ويحذر من الاختلاط الضار. المقدم: من ابتلي بالسفر سماحة الشيخ والإقامة في بلاد ليست للمسلمين؟ الشيخ: الواجب الحذر إلا إذا اضطر إليه؛ فيقيم مع إخوانه المسلمين ... حول المراكز الإسلامية، والجمعيات الإسلامية؛ حتى يتعاون معهم على الخير. إذا اضطر إلى ذلك، وإذا كان في مكان سليم؛ فليلزمه. المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9705/ما-النصيحة-للشباب-المقصرين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38501.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11535,"question":"بعد هذا رسالة بعث بها مستمع رمز إلى اسمه بالحروف: (م. ز. ش) يقول: أعمل في مزرعة أحد الأثرياء الذي يزكي وينفق في سبيل الله، ويعطي المحتاجين، وأخلاقه حميدة مع الناس، ولكنه لا يصلي كسلًا منه وتهاونًا في الصلاة، وأنا أقيم في مزرعته على أني حارس، وهو مقيم عن المزرعة في مكان يبعد عشرين كيلو مترًا، ولا يأتي إلى المزرعة إلا يومين في الأسبوع، وكل مرة من هذه المرات حوالي ساعة، أو كلما يأتي إلى المزرعة في الأسبوع هو حوالي ثلاث أو أربع ساعات، فهل علي إثم في العمل في مزرعته؟ علمًا بأنني محافظ على صلواتي، وملتزم والحمد لله، جزاكم الله خيرًا.","title":"حكم العمل عند إنسان لا يصلي","answer":"الجواب:  الذي لا يصلي كافر -نسأل الله العافية- ولو كان طيب الأخلاق، ولو كان يتصدق، ولو كان يفعل أشياء كثيرة من الخير؛ لأن ترك الصلاة كفر أكبر -نعوذ بالله- قال الله -جل وعلا- في كتابه العظيم: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، وقال تعالى: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ [المائدة:5] وقال ﷺ: من ترك صلاة العصر؛ حبط عمله فالإنسان إذا ترك الصلاة؛ حبط عمله، كفر. فالواجب على هذا الرجل أن يتوب إلى الله، ويحذر ترك الصلاة، وأن يستقيم على طاعة الله ورسوله، وأن يشكر الله على نعمته، أما أنت فالجلوس عندك فيه خطر، يخشى عليك من شره، وأن تقتدي به في الباطل. فنصيحتي لك أن تنتقل عنه إلى غيره، وأن تلتمس عملًا آخر؛ لئلا تعمك مصيبته، وشؤمه نسأل الله العافية. المقصود: أن قرب هذا وخدمته أمر لا ينبغي، نسأل الله العافية. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9717/حكم-العمل-عند-انسان-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38513.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11546,"question":"من السودان أحد الإخوة المستمعين رمز إلى اسمه بالحروف: (ب. ش. ب) يقول: تزوجت ابنة عمي بالرغم عني، واكتشفت أنها لا تصلي، وأمرتها بالصلاة لكنها لم تستمع، ولم تسمع إذا طلقتها فسيغضب والدي مني، كيف يكون التصرف مع مثل هذه؟ جزاكم الله خيرًا.","title":"حكم التزوج بامرأة لا تصلي","answer":"الجواب:  إذا تزوج المسلم امرأة لا تصلي، فإن النكاح غير صحيح في أصح قولي العلماء؛ لأن ترك الصلاة كفر، وإن لم يجحد وجوبها التارك، هذا هو الصواب. وذهب جمع من أهل العلم إلى أن تارك الصلاة لا يكفر إذا كان لم يجحد وجوبها، ولكنه أتى منكرًا عظيمًا ومعصية عظيمة وكبيرة شنعاء أعظم من الزنا، وأعظم من العقوق، وأعظم من السرقة، وأعظم من شرب الخمر، لكنه لا يكفر عند جمع من أهل العلم إذا كان لم يجحد وجوبها. لكن الصواب والراجح هو أنه يكفر بذلك، وإن لم يجحد وجوبها، ويكون النكاح غير صحيح إذا كان الزوج يصلي وهي لا تصلي، يكون النكاح غير صحيح، وهكذا العكس لو كانت تصلي هي، وهو لا يصلي كذلك، ما يصح عقدة النكاح، لقول النبي ﷺ في الحديث الصحيح: رأس الأمر الإسلام، وعموده الصلاة إذا ترك العمود؛ سقط الفسطاط، والمعنى: سقط الإسلام. ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ولم يقل: إذا جحد وجوبها أطلق -عليه الصلاة والسلام-وهذا الحديث صحيح رواه الإمام أحمد ، وأهل السنن بإسناد صحيح عن بريدة . وفي صحيح مسلم، عن جابر بن عبدالله -رضي الله عنهما- عن النبي ﷺ أنه قال: بين الرجل، وبين الكفر والشرك ترك الصلاة وهذا الحكم يعم الرجال والنساء؛ لأن القاعدة الشرعية: أن ما ثبت في حق الرجال؛ يثبت في حق النساء، وهكذا العكس إلا بدليل يخص أحدهما، وليس هنا دليل يخص الكفر بالرجل، بل من كفر مطلقًا من الرجال والنساء.  فعليك أيها السائل أن تفارقها، وأن تردها إلى أهلها، ولو لم يرض أبوك؛ لأن المعاصي ليس للإنسان فيها طاعة، الطاعة لله، يقول النبي ﷺ: إنما الطاعة في المعروف ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق فعليك أن تردها إلى أهلها، وأن تعطيها طلقة صكًا بطلقة؛ خروجًا من الخلاف، وحتى يعتمد على الصك في تزويجها لغيرك، ومتى هداها الله، وأردت الرجوع إليها بعد ذلك بعقد جديد؛ فلا بأس، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9729/حكم-التزوج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_296/29602.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":11553,"question":"المستمع هزاع عبدالله الشرف بعث يسأل ويقول: لقد توفيت أم والدي قبل عامين وكانت تاركة للصلاة، لكنها تصوم رمضان، وقد قام والدي العام الماضي وحج لها، فهل هذه الحجة صحيحة؟","title":"حكم الحج عمن مات وهو تارك للصلاة","answer":"الجواب:  التارك للصلاة كافر عند جمع من أهل العلم، ولو كان لا يعلم منه جحود وجوبها؛ لأن ترك الصلاة من الكبائر العظيمة، وقد بين النبي ﷺ أن تاركها يكون كافرًا، يقول -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة والحكم يعم الرجل والمرأة، الأحكام المعلقة بالرجال تعم النساء، والمعلقة بالنساء تعم الرجال، إلا ما خصه الدليل، ولهذا في الحديث الآخر يقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وهذا يعم الرجال والنساء. ........ لا يحج عنه، ولا يعتمر عنه، لكن ذهب جمع من أهل العلم إلى أن من تركها ليس عن جحد لوجوبها، بل عن تكاسل؛ لا يكفر بذلك، ولكن أتى ذنبًا عظيمًا، ومنكرًا عظيمًا، لكن لا يكون كافرًا كفرًا أكبر، بل يكون كفره كفرًا أصغر، فعلى هذا القول: يصح الحج عنه عند جمع من أهل العلم الذين قالوا: إن المسلم لا يكفر بترك الصلاة إلا إذا جحد وجوبها. أما إذا تركها تكاسلًا وهو يعلم أنها واجبة، وأنها فريضة، ولكن حمله الكسل والتساهل على الترك؛ فهذا عند جمع من أهل العلم لا يكفر بذلك كفرًا أكبر، بل يكون كفرًا أصغر. والصواب والأظهر في الدليل أنه يكون كافرًا كفرًا أكبر -والعياذ بالله- لأن الصلاة عمود الإسلام، من حفظها؛ حفظ دينه، ومن ضيعها؛ فقد ضيع دينه، نسأل الله العافية. وبذلك يعلم أن من كان تاركًا للصلاة لا يحج عنه، ولا يدعى له- نسأل الله العافية- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9736/حكم-الحج-عمن-مات-وهو-تارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29702.mp3","categories":["النيابة في الحج","حكم الصلاة وأهميتها"]},{"id":11569,"question":"بعد هذا رسالة وصلت إلى البرنامج من بريدة في القصيم، باعثها مستمع رمز إلى اسمه بالحروف (ح. م. س) أخونا رسالته مطولة بعض الشيء، يقول فيها: إنني شاب متزوج، ولي ثلاثة أولاد أعيش في بيتي، وفي بيت والدي المتوفى مع والدتي وجدتي وإخوتي، ومشكلتي تتلخص: بأن أخي الأكبر الذي يسكن معنا في البيت لا يصلي، ولا يشهد الصلاة في المسجد في كل الأوقات، ويشرب الخمر أغلب الأوقات، وعاطل عن العمل، لقد تشاجرت معه كثيرًا، ولكن لا فائدة، بل يصرح بأنه لن يصلي، ولم تفد معه النصيحة، فقد فكرت في الخروج في البيت، ولكن والدتي بكت كثيرًا، واتهمتني بالعقوق وقالت: احمد ربك حتى لا يعاقبك الله بولد مثله، فضيلة الشيخ! إنني أعيش في حيرة، فهل يجوز لي الخروج من البيت، وترك والدتي؟ بالرغم من أنني أنا الذي أصرف على البيت، وإذا تغاضيت عنه من أجل والدتي، هل أكون شريكًا في الإثم والمعاصي؟وجهوني جزاكم الله خيرًا.","title":"ما النصيحة لمن ابتلي بأخ سكير لا يصلي؟","answer":"الجواب:  الذي لا يصلي كافر -نعوذ بالله- يقول النبي ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر، وشرب الخمر من أقبح الكبائر، وأعظم الذنوب، والله -جل وعلا- قال في الخمر: إنما الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ [المائدة:90] وقد ثبت عنه ﷺ: أنه لعن الخمر، وشاربها وساقيها، وعاصرها ومعتصرها، وحاملها والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها نسأل الله العافية، وقال -عليه الصلاة والسلام-: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن فالخمر أم الخبائث، ومن أعظم القبائح والكبائر. وننصحك أن تستمر في نصيحته، وتخويفه من الله -عز وجل- بالأسلوب الحسن، والترغيب والترهيب، وأن تستعين على ذلك -أيضًا- بسؤال الله -جل وعلا- أن يهديه، وأن يشرح صدره للحق، اسأل ربك، سل ربك أن الله يهديه، وأن الله يعيذه من شر نفسه وهواه، وأن الله يلهمه الصواب، ويوفقه لقبول الحق، فهو أخوك له حق عليك، تسأل ربك له أن الله يهديه في أوقات الإجابة: في سجودك، وفي آخر الصلاة، وفي آخر الليل، سل ربك أن الله يهديه، ويعيذه من الشيطان، وهكذا تستعين عليه أيضًا بإخوانك في الله الطيبين، الذين قد يؤثرون عليه؛ حتى ينصحوه، ويوجهوه، ولا تخرج من البيت، اجلس مع والدتك، وأحسن إليها. فإن لم تفد فيه النصيحة، ولم يقبل، فارفع أمره إلى الهيئة، أو إلى المحكمة؛ حتى يقام عليه الحد، ارفع أمره إلى الهيئة؛ لعلها تعالج الموضوع، فإن لم يحصل ذلك فالمحكمة؛ لأن هذا أمر عظيم، ترك الصلاة، وشرب الخمر أمر عظيم، فالذي يجاهر بهذا، ولا يبالي؛ لا يترك إذا لم يقبل النصيحة، نسأل الله لنا ولك وله الهداية، ولجميع المسلمين. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9752/ما-النصيحة-لمن-ابتلي-باخ-سكير-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38602.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":11676,"question":"رسالة موضوعها في غاية الأهمية -سماحة الشيخ- كتبت بأسلوب عامي بحت صاحبة الرسالة تقول: أختكم في الله التي رمزت إلى اسمها بالحروف (م. ع. س) من المنطقة الجنوبية، سأحاول قراءة الرسالة كما وردت.تقول عن نفسها: إني فتاة أبلغ من العمر السادسة والعشرين، لا أقرأ، ولا أكتب، وطلبت من كان عنده علم كتابة هذه الرسالة: أفيدكم أننا بدو من بوادي أهل الجنوب، وإننا أهل أغنام كثيرة، ولازم نخرج أمام الرجال ونحضر لهم الأكل والشرب ونكلمهم، ولكننا والحمد لله رب العالمين، متقيدين بالإسلام قلوبنا طاهرة، ونحن أمرنا بالحجاب، ونحن متسترون، وقد ذاعت الندوات بالأمر بالحجاب، ولكننا لم نقدر إلا على الغطوة -المراد: غطاء الوجه- ولم نقدر على باقي الحجاب من الجلباب ونحوه، وقد سمعنا أشرطة فيها أحاديث تقول:إن المرأة إذا تغطت، يعني: غطت عيناها، ولم ترتدي الحجاب كاملًا، وتخرج أمام الرجال، وتكلمهم؛ فإنه لا يصح لها أبدًا التحجب؛ لأنها تخرج أمام الرجال وتكلمهم، فنرجو من الله، ثم منكم -جزاكم الله خير الجزاء- أن تفيدونا، هل نمنع الغطوة، أم نخليها؟ لأنها لم توف الحجاب كاملًا بالجلباب؛ لأن هناك أناس كثيرين تركوا الغطوة؛ لأنها ليست من الحجاب الكامل، جزاكم الله خيرًا.","title":"حكم الحجاب وصفته","answer":"الجواب:  الحجاب للمرأة عند غير محارمها أمر لازم؛ لأنها فتنة، والنظر إليها فتنة، فوجب عليها الحجاب ابتعادًا من الفتنة لها ولغيرها، وقد قال الله  في أزواج النبي ﷺ وغيرهن من باب أولى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. والحجاب يكون بالجلباب، ويكون بغيره من الملابس التي تغطي البدن، وتستر البدن ومنه الوجه، والوجه هو أعظم الزينة، فستره هو أهم المهمات، هو أعظم الزينة، تستر رأسها، أو وجهها، وسائر بدنها، ولا مانع أن تبدي عينًا، أو عينين للنظر، أو لنظر الطريق، والحاجات التي تريد أخذها وحملها. فالحاصل: أن الحجاب لابد منه في حق المرأة بالنسبة إلى غير محارمها، وقال -جل وعلا-: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب ثوب تلقيه المرأة على رأسها وبدنها زيادة في التحجب والستر، فإذا كانت ملابسها ضافية، وغطت وجهها ورأسها؛ كفى ذلك، لكن الجلباب يكون من مزيد التستر، وهكذا قوله -جل وعلا- في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، فإذا سترت الزينة وهي الوجه، وبقية البدن بالجلباب أوغيره، حصل المقصود.  ليس المقصود الجلباب وحده، المقصود ما يسترها، ويبعد الخطر والفتنة، فإن تيسر الجلباب وهو الثوب الضافي، تضعه على بدنها، وتستر به وجهها، وبدنها؛ فالحمد لله، وإن ما تيسر فالحجاب بما يسمى الشيلة، أو غير الشيلة مما توضع على الرأس والوجه، ويستر ذلك يكفي ذلك، وإذا سترت الرأس وجعلت على وجهها برقعًا ترى منه حاجاتها، تبدي العين الواحدة، أو عينين، والباقي مستور، لا حرج في ذلك، وإن تيسر الستر للجميع كان ذلك أكمل بالنسبة إلى البعد عن الخطر؛ لأن الناس يختلفون، بعضهم يتأثر بالعين أيضًا، ولكن هديه ﷺ وسنته دل على أن النقاب جائز، ولهذا قال النبي ﷺ في حق المحرمة: ولا تنتقب المرأة، ولا تلبس القفازين فدل على أن غير المحرمة تنتقب، ولا حرج، غير المحرمة تنتقب، أما المحرمة لا تلبس النقاب، والنقاب ما يوضع على الوجه، وفيه نقب للعين والعينين، ويسمى: البرقع، فإذا .... جعلته على وجهها ..... أو نقبت فيه نقبًا، أو نقبين للعينين فقط، مع ستر الوجه كله، الجبهة والخدين؛ فلا بأس بذلك، الله -جل وعلا- يقول: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185]، ويقول سبحانه: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]. بعض النساء لو جعلت الحجاب ساترًا لعينيها لم تهتدي الطريق، ولم تعرف أن تسير، فلا بد من شيء يعينها على قضاء حاجاتها، وأن يعينها على سيرها في الأسواق وفي بيتها، وحول غنمها، وحول مزرعتها إلى غير ذلك، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، نعم، إذًا ذلك الفهم الذي يقول: إن غطاء الوجه، إما أن يكون كاملًا للبدن كله، أو ليس له أثر فهم خاطئ؟ الشيخ: خاطئ نعم، المهم الستر من جلباب وغيره. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9864/حكم-الحجاب-وصفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29905.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","فتاوى متنوعة"]},{"id":11681,"question":"بحكم طبيعة عملي ومشقته فإنني لا أستيقظ من النوم إلا بعد طلوع الشمس، فأصلي الصبح ركعتين فقط، أفيدوني، جزاكم الله خيرًا.","title":"حكم من لا يصلي الفجر إلا بعد طلوع الشمس","answer":"الجواب:  هذا منكر عظيم، يجب عليك أن تصلي في الوقت، يجب عليك أن تنام مبكرًا حتى تقوم في وقت الصلاة الفجر، أو تشتري ساعة، وتوكدها على قرب الفجر؛ حتى تعينك على القيام، ولا يجوز لك التساهل حتى تصلي بعد الشمس، هذا منكر عظيم، وتعمده كفر في أصح قولي العلماء؛ لأن تعمد هذا ترك للصلاة في وقتها، فالواجب الحذر، قال الله -جل وعلا-: فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا [مريم:59] قال جماعة من السلف: أضاعوا الصلاة، يعني: أخروها عن وقتها، فالواجب الحذر، وذلك بأحد أمرين:  إما أن تبكر حتى تستيقظ للفجر، وإما أن تتخذ ساعة تعينك أو ..... من يوقظك، ولا يجوز لك التساهل في هذا أبدًا، بل يجب أن تهتم بهذا حتى تصلي الصلاة في وقتها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9862/حكم-من-لا-يصلي-الفجر-الا-بعد-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39011.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11946,"question":"رسالة بعث بها أحد الإخوة المستمعين يقول المرسل (راشد . ع) من سكاكا الجوف، يسأل عددًا من الأسئلة من بينها يقول: أخبركم بأنني كنت أصلي، ولكن لم أحافظ على الصلوات، ولله الحمد أحمده حمدًا كثيرًا طيبًا مباركًا كافئًا بأن من علي بالهداية، وأنا الآن أحافظ على صلواتي الخمس في أوقاتها، وأقوم الليل لأداء صلاة التهجد، وأقرأ كل يوم جزأين، أو ثلاثة أجزاء، ويوم الجمعة أقرأ فيه من ستة إلى سبعة أجزاء، وأتصدق بعض المال إذا كان معي، وأصوم الإثنين والخميس والأيام البيض، أحمد الله على ذلك، سؤالي: بماذا تنصحونني بزيادة العمل الصالح؟ جزاكم الله خيرًا.","title":"ما النصيحة لمن كان متساهلًا بالصلاة ثم تاب؟","answer":"الجواب:  الحمد لله الذي من عليك بالتوبة والرجوع إليه -جل وعلا- ونوصيك بشكر الله والثناء عليه، وسؤاله الثبات على الحق، وسؤاله التوفيق للاستقامة على الحق، وأبشر بالخير، نوصيك بالاستمرار في هذه الأعمال الطيبة، والاستزادة من الخير مهما استطعت، والله -جل وعلا- لا يضيع للعاملين أعمالهم، بل يوفرها لهم، ويضاعفها لهم على حسب إخلاصهم وصدقهم، فاستعن بالله، واجتهد في عمل الخير -وأنت على خير- من الصدقة، والأمر بالمعروف، والنهي عن المنكر، والدعوة إلى الله  والعناية ببر الوالدين، وصلة الرحم، وإكرام الجار، وغير هذا من وجوه الخير، وأبشر بالخير، رزقنا الله وإياك الاستقامة والقبول. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10131/ما-النصيحة-لمن-كان-متساهلا-بالصلاة-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42810.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":11990,"question":"يقول: إذا كان له صديق لا يصلي وكذلك زوجته لا تصلي، فهل تستمر تلكم الصداقة؟ وهل له أن يدعوهما إلى منزله كضيوف؟ جزاكم الله خيرًا.","title":"ما حكم مصاحبة من لا يصلي؟","answer":"الجواب:  إذا كان الرجل لا يصلي، لا يجوز أن يتخذ صديقًا، بل يجب أن يتخذ عدوًا وبغيضًا حتى يتوب، هذا من الولاء والبراء، من المعاداة في الله والبغضاء في الله، فالجار أو القريب الذي لا يصلي؛ يجب بغضه في الله، وهجره حتى يتوب ويرجع عن الباطل، أو يرفع أمره إلى الجهة المختصة حتى يستتاب، فإن تاب وإلا قتل، إذا كان في بلاد إسلامية تحكم شرع الله، ولا يجوز أن يصادقه. وهكذا زوجته إذا كانت لا تصلي؛ يفارقها، لا يجوز بقاءها، المؤمن لا ينكح المشركة، تارك الصلاة كافر، نسأل الله العافية، والله يقول -جل وعلا-: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] يعني: كافرة، ويقول: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221] فالذي تترك الصلاة كافرة، يقول النبي ﷺ: «العهد الذي بيننا وبينهم الصلاة؛ فمن تركها؛ فقد كفر» فالرجل الذي لا يصلي والمرأة التي لا تصلي كلاهما كافر، وإذا جحدا الوجوب؛ صارا كافرين بإجماع المسلمين. أما إذا كان الترك تكاسلًا -تهاونًا- فهذا كفر أكبر على الصحيح من أقوال العلماء، يجب أن يستتاب صاحبه، فإن تاب وإلا قتل في المحكمة الشرعية، ويجب على الزوج أن يفارقها إذا لم تتب، ويلتمس زوجة صالحة. وهكذا الزوجة؛ إذا كان زوجها لا يصلي؛ تخرج، تبتعد عنه تذهب إلى أهلها، تطلب فراقه من المحكمة، من أوليائها يقومون بذلك، لأن الكافرة ما تصلح تحت المسلم، ولأن المسلمة لا تصلح تحت الكافر، الله يقول: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]. فالواجب على المؤمن ألا يتزوج إلا مسلمة تصلي، وعلى المسلمة أن تبتعد عن الزوج الذي لا يصلي، ولا ترضى به زوجًا، وإذا ترك الصلاة؛ تخرج إلى بيت أهلها، وتطلب فراقه، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10175/ما-حكم-مصاحبة-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43104.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12054,"question":"المستمع محمود صالح بعث يسأل ويقول: من ترك الصلاة بخدعة الشيطان لمدد قد تصل لأشهر عديدة، هل يقضيها؟ وكيف يكون القضاء؟ وهل يصلي كل فرض مع فرضه، أم كيف يكون الحال؟ جزاكم الله خيرًا.","title":"حكم قضاء الصلوات المتروكة عمدًا","answer":"الجواب:  من تعمد ترك الصلاة؛ فقد كفر في أصح قولي العلماء، وإن لم يجحد الوجوب، إذا تعمد تركها؛ كفر بذلك؛ لقوله ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وهناك أحاديث أخرى تدل على هذا المعنى، فإذا تاب ورجع؛ فالتوبة تجب ما قبلها، والحمد لله، وليس عليه قضاء ما فات، الصحيح أنه لا قضاء عليه، الإسلام يجب ما قبله والنبي ﷺ لم يأمر الذين أسلموا أن يقضوا، ولم يأمر الذين ارتدوا، ثم أسلموا أن يقضوا، بل التوبة تكفي، والحمد لله، تجب ما قبلها، ولا قضاء عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10239/حكم-قضاء-الصلوات-المتروكة-عمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43403.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":12110,"question":"يقول عن والدته سماحة الشيخ، والدتي تبلغ من العمر خمسين سنة، إلا أنها هداها الله ضعيفة في أداء الصلوات الخمس، هكذا يقول، وأردت نصحها عدة مرات، وسنين طويلة، ووالدي كذلك وهو الآن حي، والحمد لله، لكني ألاحظ أن الأمر كما هو، فبماذا توجهوننا جميعًا؟ جزاكم الله خيرًا.","title":"واجب الابن تجاه أمه المتساهلة بأداء الصلاة","answer":"الجواب:  الواجب عليها أن تتقي الله، وأن تحافظ على الصلاة في أوقاتها؛ لأن الصلاة عمود الدين، وأعظم الفرائض، وأهمها بعد الشهادتين، فالواجب على كل مسلم، وعلى كل مسلمة المحافظة على الصلوات في أوقاتها بكل عناية، لقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، وقوله سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونََ [النور:56] وقوله -جل وعلا-: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، ثم قال في آخر الآيات: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ [المؤمنون:9]. فالمقصود: أن الواجب على المؤمن والمؤمنة العناية بالصلاة، والمحافظة عليها أينما كان في السفر والإقامة، في الشدة والرخاء، في الصحة والمرض، في الغنى والفقر، حتى ولو كان على فراشه يصلي، إن كان يستطيع يصلي قاعدًا؛ صلى قاعدًا، فإن عجز؛ صلى على جنبه، فإن عجز؛ صلى مستلقيًا، ليس له عذر في الترك أبدًا ما دام عقله معه، ويقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة ويقول أيضًا -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة يعني: والمرأة، المعنى واحد، يعني: الخطاب للرجل والمرأة، هذا يعم الجميع، ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. والواجب عليك أنت يا ولدها النصيحة، وهكذا زوجها يجب عليه أن ينصحها، وأن يؤدبها أيضًا، ولو بالضرب حتى تستقيم على المحافظة، وإذا تعمدت تركها؛ تكفر بذلك -نسأل الله العافية- وينبغي له فراقها حينئذٍ إذا كفرت، الواجب عليه فراقها، لا يبقى المسلم مع الكافرة غير الكتابية. المقصود: الواجب عليكما جميعًا أنت وأبوك العناية بها، أنت تنصح بالكلام الطيب، والأسلوب الحسن، وأبوك كذلك، وله سلطان عليها بأن يؤدبها إذا .... وتساهلت بالصلاة -نسأل الله لها الهداية- وأن يعيذها مولاها من الشيطان، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10295/واجب-الابن-تجاه-امه-المتساهلة-باداء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43713.mp3","categories":["حكم الصلاة وأهميتها","بر الوالدين"]},{"id":12135,"question":"أرجو إفادتي هل هذا الحديث صحيح، يقول رسول الله ﷺ: \"تارك الصلاة لا يقبل منه عمل، وإن مات لا يغسل، ولا يصلى عليه، ولا يدفن في مقابر المسلمين\"؟","title":"ما صحة حديث: (تارك الصلاة لا يقبل منه عمل..)؟","answer":"الجواب:  ليس هذا حديثًا، هذا من كلام بعض العلماء، وليس حديثًا عن النبي ﷺ هذا من كلام من يرى أن تارك الصلاة كافر كفرًا أكبر، يقول: لا يغسل، ولا يصلى عليه، ولا يدفن مع المسلمين؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، ولقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر هذا الكلام يقوله من قال: بأن تارك الصلاة كافر، يقول: لا يغسل، ولا يكفن، ولا يصلى عليه، ولا يدفن مع المسلمين، لكن يدفن في محل بعيد عن مقابر المسلمين، بأرض يحفر فيها، ويدفن كسائر الكفار، مثلما قال النبي ﷺ لأبي طالب لعلي ... لما مات أبو طالب، وجاء علي  إلى النبي ﷺ فقال: يا رسول الله! إن عمك الشيخ الضال قد مات، قال: اذهب فواره يعني: فادفنه، ما قال: كفنه وصل عليه، لا؛ لأنه مات على الكفر، مات أبو طالب على دين قومه، اجتهد النبي ﷺ في إسلام أبي طالب، لكن لم يهتد، وأنزل الله في ذلك: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56] لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُُ [البقرة:272]. فالمقصود: أن الكافر من أقارب، أو غيرهم لا يغسل، ولا يصلى عليه، ولا يدفن مع المسلمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10320/ما-صحة-حديث-تارك-الصلاة-لا-يقبل-منه-عمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43904.mp3","categories":["الحكم على الأحاديث","حكم الصلاة وأهميتها"]},{"id":12204,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية، باعثها المستمع: فتحي عاشور السيد، ومقيم في بغداد عندما بعث الرسالة، يقول في رسالته: إنني شاب هناك بعض فروض الصلاة لم أقوم بتأديتها من قبل، هل أقضيها الآن، وكيف يكون القضاء إذا كان واجبًا وكيف تكون النية؟","title":"حكم قضاء الصلوات لمن تركها عمدًا","answer":"الجواب:  الصلاة هي عمود الإسلام، وهي أعظم الفرائض، وأهم الفرائض بعد الشهادتين، ومن تركها جاحدًا لها؛ كفر بإجماع المسلمين، ومن تركها تكاسلًا، وليس بجاحد؛ فإنه كافر في أصح قولي العلماء؛ لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهمم الصلاة، فمن تركها؛ فقد كفر ولقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه في أحاديث أخرى تدل على ذلك، ومن ضيعها، أو ضيع بعضها، ثم تاب؛ فلا قضاء عليه، عليك أن تستقيم أيها السائل! وتسأل ربك التوفيق والإعانة، وتتوب إلى الله مما مضى من الترك، وليس عليك قضاء؛ لأن الكافر إذا أسلم ليس عليه قضاء، وتاركها تهاونًا كافر في الأصح، فليس عليه قضاء. ولكن عليه التوبة الصادقة، عليه أن يندم على ما مضى، ويحزن على ما مضى، ويعزم عزمًا صادقًا على أنه يستقيم في المستقبل، ويحافظ عليها، وبذلك يتوب الله عليه  كما قال : وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وقال النبي ﷺ: التائب من الذنب من الذنب كمن لا ذنب له فأنت يا أخي ليس عليك قضاء، هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10390/حكم-قضاء-الصلوات-لمن-تركها-عمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_444/44411.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":12245,"question":"هل يجوز أن يعقد العقد على زوجة لا تصلي؟","title":"حكم العقد على زوجة لا تصلي أو كتابية","answer":"الجواب:  إذا كان الزوج يصلي؛ فليس له أن يعقد عليها حتى تتوب إلى الله، أما إذا كان لا يصلي؛ فهو من جنسها، لكن إذا كان يصلي وهي لا تصلي؛ فليس له العقد عليها حتى تتوب، هكذا إذا كان لا يصلي، وهي تصلي، ليس لها أن تزوجه حتى يتوب إلى الله ويصلي؛ لأن ترك الصلاة كفر أكبر عند المحققين من أهل العلم، لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ولأدلة أخرى من الكتاب والسنة تدل على كفر تارك الصلاة، فمن تركها من الرجال والنساء، -وإن لم يجحد وجوبها- كفر في أصح قولي العلماء، لكن إن جحد وجوبها، أو استهزأ بها؛ كفر عند الجميع، نعوذ بالله، إذا قال: ما هي بواجبة، أو استهزأ بها، وسخر منها، أو من أهلها؛ إنكارًا لها، واستهزاءً بها؛ كفر -نسأل الله العافية- عند جميع العلماء؛ لأن الله يقول سبحانه: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66] ولأنه إذا جحد وجوبها؛ فقد كذب الله ورسوله؛ فيكون كافرًا، نسأل الله العافية.  وهكذا لو جحد وجوب الزكاة، أو جحد وجوب صوم رمضان، أو جحد وجوب الحج مع الاستطاعة، أو استهزأ بذلك؛ كفر عند جميع المسلمين، وهكذا لو جحد تحريم الزنا قال: الزنا حلال، أو الخمر حلال وهو مثله لا يجهل ذلك، أو علم وبين، ثم أصر على جحد تحريم الزنا، أو جحد تحريم الخمر؛ يكون كافرًا، نسأل الله العافية. والحاصل أن كل من أنكر ما أوجب الله مما هو معلوم عند الجميع كالصلاة والصوم ونحو ذلك، أو أنكر تحريم ما حرمه الله مما هو معلوم عند جميع أهل العلم، معلوم بالنصوص، كالزنا، والخمر؛ فإن هذا يكون كافرًا عند جميع العلماء نسأل الله العافية، ومثل ذلك من ترك الصلاة، وإن لم يجحد وجوبها؛ فهو كافر في أصح قولي العلماء؛ لأن الصلاة أمرها عظيم، ليست من جنس غيرها من الواجبات، بل هي أعظم الواجبات، وأهمها بعد الشهادتين، فتركها والتساهل بها ليس من جنس غيرها، بل يكون صاحب ذلك كافرًا -نسأل الله العافية- من الرجال والنساء، نعم.  المقدم: جزاكم الله خيرًا، حدثوني لو تكرمتم عن حكم الزواج بالمسيحية؟  \nالشيخ: يجوز للمسلم أن ينكح المسيحية، واليهودية إذا كانت محصنة، غير معروفة بالسفاح، بالزنا، قال سبحانه: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلا مُتَّخِذِي أَخْدَانٍ [المائدة:5] فإذا تزوجها وهي محصنة، غير مسافحة، معروفة بالستر، وعدم الزنا؛ فإنه يجوز له أن ينكحها مسلم، لكن تركها أفضل، والحرص على المسلمة أسلم له ولذريته؛ ولأنها قد تجره إلى الكفر، أو تجر ذريته، فالأولى بالمؤمن ألا ينكح الكتابية، وأن يعدل عنها إلى المسلمة؛ احتياطًا لدينه، وخوفًا على نفسه وذريته، نسأل الله السلامة والعافية، نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10434/حكم-العقد-على-زوجة-لا-تصلي-او-كتابية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44809.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":12312,"question":"المستمع (بشير . ح. ح) من ليبيا بعث برسالةٍ ضمنها عددًا من الأسئلة، عرضنا بعضًا منها في حلقاتٍ مضت، وفي هذه الحلقة يسأل ويقول: أخي الأصغر مني، وهو بالغٌ، تاركٌ للصلاة، فهو لا يُصلي إلا صلاة الجمعة، ونصحته، ولكن بدون فائدةٍ، ماذا أفعل تجاهه؟ أرجو الإفادة، جزاكم الله خيرًا.","title":"كيفية التعامل مع الأخ الذي يترك الصلاة","answer":"الجواب: الواجب عليك نصيحته، والتكرار في ذلك، والجد في ذلك، لعل الله يهديه بأسبابك، ولا تملّ، ولا تيأس؛ لأن المسلم عليه النصيحة لغيره، وعليه التوجيه، والله يقول -جلَّ وعلا-: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] ويقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33].  فأحسن إليه بالنصيحة، واجتهد، وليكن ذلك عن صدقٍ، وعن عنايةٍ، تبين له أن ترك الصلاة كفرٌ، وأنه ضلالٌ، وأن الواجب على كل مُكلَّفٍ أن يتقي الله، وأن يُؤدي الصلاة إذا كان ينتسب إلى الإسلام، وإلا فلا صحةَ لدعواه الإسلام، فإن إسلامه بدون صلاةٍ ليس بإسلامٍ، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلمٌ في \"صحيحه\" ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمَن تركها؛ فقد كفر.  فالواجب على أخيك أن يتقي الله، وأن يصلي، وعليك أن تنصحه كثيرًا، وتُبلغه كثيرًا، لعل الله يهديه بأسبابك، فإن أصرَّ ولم يُبالِ؛ فعليك أن تهجره إذا رأيت الهجر أصلح، وإن رأيت عدم الهجر أصلح، وأن تستمر معه في الدعوة والتوجيه، مع كراهة عمله، وإظهار الكراهة والغضب على عمله؛ فلعل الله يهديه بأسبابك، وإن رأيت هجره أصلح، والبعد عنه؛ لأنه لم يمتثل، ولم يقبل النصيحة، ورجوت أن هذا الهجر يُؤثر عليه، لعل الله يهديه بأسباب ذلك؛ فاهجره، فالهجر الذي يفيد مطلوبٌ، مشروعٌ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10512/كيفية-التعامل-مع-الاخ-الذي-يترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45403.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":12336,"question":"المستمع أحمد سعيد الحربي من الطائف بعث برسالة يقول فيها: أنا جدتي كانت في آخر أيامها في الحياة، وكانت عجوزًا طاعنة في السن، ولقد كانت تحب الصلاة حبًا شديدًا، والصيام أيضًا، والتقرب إلى الله، ولكن لم تكن تستطع في الشهور الأخيرة من عمرها أداء الصلاة، وذلك لعدم طهارتها، وعدم استطاعتها أن تقرأ، أو أن تفعل أي فعل من أفعال الصلاة، رغم أنها تملك عقلها كاملًا، فهل عليها إثم في ذلك؟ وعندما كنا نقول لها: حاولي أن تؤدي الصلاة، كانت تقول: إنني أشعر بقناعة تامة عن الصلاة، وكانت تلهث بشدة عند أي حركة تؤديها، وكأن روحها ستخرج،  وجهونا جزاكم الله خيرًا.","title":"حكم من تركت الصلاة لكِبَر سِنها","answer":"الجواب:  الواجب عليها أن تصلي على حسب حالها ما دام عقلها موجودًا، فالواجب عليها أن تصلي، قائمة، أو قاعدة، أو على جنبها، أو مستلقية بالماء، أو بالتيمم، هذا هو الواجب عليها، ولا يجوز لها ترك الصلاة؛ لأن الله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والنبي ﷺ قال لعمران لما كان مريضًا قال: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيًا.  فالمؤمن والمؤمنة هكذا يقومون بالواجب حسب الطاقة، ولا يجوز ترك الصلاة من أجل الضعف، أو كبر السن، فعلى المريض، وكبير السن أن يصلي على حسب حاله، حتى ولو على جنبه، حتى ولو مستلقيًا إذا عجز عن الجنب، يقرأ ويكبر يقول: الله أكبر ناويًا الصلاة، ثم يقرأ الفاتحة، وما تيسر معها، ثم يكبر ناويًا الركوع يقول: سبحان ربي العظيم، ثم يقول: سمع الله لمن حمده ناويًا الرفع يقول: ربنا ولك الحمد، إلى آخره، ثم يكبر ناويًا السجود، يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم يكبر ناويًا الجلسة بين السجدتين، يقول: رب اغفر لي، رب اغفر لي، ثم يكبر ناويًا السجدة الثانية، وهكذا بالقول إذا عجز عن الفعل. وأما هذه التي تأخرت عن الصلاة وهي تعقل فقد أثمت، وهي على خطر عظيم، ويخشى عليها أن تكون كافرة بذلك؛ لأنها تركت الصلاة مع القدرة، ومع العقل. فالحاصل: أن هذا العمل عمل سيئ، ومنكر، والواجب عليها أن تصلي على حسب حالها: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إذا كان عقلها موجودًا. نعم. المقدم: جزاكم الله خيرًا، يسأل في نهاية الرسالة: ماذا علينا أن نفعل؟ الشيخ: ما دامت توفيت ليس عليكم شيء، أمرها إلى الله، ظاهر حالها الكفر، نسأل الله العافية؛ لأنها ضيعت الصلوات من أجل جهلها، والله -جل وعلا- يتولى أمرها سبحانه، ما دام تركت الصلاة وهي عاقلة لا تدعوا لها، ولا تصدقوا عنها؛ لأنها تركت الصلاة وهي عاقلة كما ذكرتم، وترك الصلاة مع العقل، ومع التكليف كفر أكبر على أصح قولي العلماء؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10538/حكم-من-تركت-الصلاة-لكبر-سنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45409.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12342,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من المستمع: محمد حامد يوسف، أخونا يقول -في سؤال له طويل بعض الشيء- يقول: أفيدوني في سؤالي عن تارك الصلاة، فلقد سمعنا أن تارك الصلاة لا يورث في مال أبيه؛ لأن الحديث الذي سمعناه قال رسول الله ﷺ: بين العبد، وبين الكفر ترك الصلاة  وسمعنا: أن تارك الصلاة يسمى مسلمًا عاصيًا، فأرجو أن تفيدونا في هذه الأسئلة، هل الإنسان تارك الصلاة مسلم عاصٍ؟ وهل يرث في مال أبيه، أم لا؟ جزاكم الله خير الجزاء.","title":"الراجح من أقوال أهل العلم في تارك الصلاة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد تنازع العلماء -رحمة الله عليهم- في حكم تارك الصلاة، إذا لم يجحد وجوبها، فذهب جمع منهم إلى أنه لا يكفر بذلك؛ لأنه موحد، يشهد أن لا إله إلا الله، وأن محمدًا رسول الله، وتعلقوا بالأحاديث العامة في ذلك، وذهب جمع من أهل العلم آخرون: إلى أنه يكفر بذلك كفرًا أكبر، لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر أخرجه الإمام أحمد، وأهل السنن بإسناد صحيح، ولما سئل ﷺ عن الأمراء الذين يعملون ما لا يرتضى من الأعمال، قال السائل: هل نقاتلهم؟ قال: لا، ما أقاموا فيكم الصلاة وفي اللفظ الآخر: حتى تروا كفرًا بواحًا، عندكم من الله فيه برهان فدل ذلك على أن ترك الصلاة من الكفر البواح. أما إذا جحد وجوبها، وقال: إنها غير واجبة؛ فهذا يكفر عند الجميع، كافر بإجماع المسلمين. وبذلك يعرف السائل أن تارك الصلاة مطلقًا كافر، على الصحيح، ولو لم يجحد الوجوب، لكن متى جحد الوجوب؛ صار كافرًا عند الجميع، أما إذا لم يجحد الوجوب، ولكنه ترك الصلاة، فإن الصحيح من قولي العلماء: أنه يكفر بذلك، للأحاديث الواردة في ذلك، نعم. المقدم: جزاكم الله خيرًا، يسأل عن الميراث حينئذٍ سماحة الشيخ؟ الشيخ: ومتى كفر لا يرث من أبيه، ولا غيره من المسلمين، لا يرث من أحد، لقول النبي ﷺ: لا يرث المسلم الكافر، ولا الكافر المسلم يكون ماله لبيت المال، هو إذا مات ماله لبيت المال، لا يرثه المسلمون، وهو لا يرث من المسلمين. المقدم: الله المستعان، جزاكم الله خيرًا، إذا كان يصلي بعض الفروض، ويترك البعض؟ الشيخ: حكمه حكم التارك، حتى يصلي الجميع، نعم. المقدم: الله المستعان، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10540/الراجح-من-اقوال-اهل-العلم-في-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39901.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12354,"question":"مستمعة من الجزائر بعثت تسأل وتقول: لي أخ تارك للصلاة، مع أنه كان في صغره يحافظ عليها، ولكنه الآن تركها، وقد نصحته، وخوفته من تركها، فما هو توجيهكم، وبماذا تنصحونه؟ وجزاكم الله خيرًا.","title":"ما النصيحة تجاه الأخ التارك للصلاة؟","answer":"الجواب:  نسأل الله لنا وله الهداية، ننصح أخوك بأن يؤدي الصلاة، ويتقي الله، ويتوب إلى الله مما سلف، فإن ترك الصلاة كفر أكبر، يقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فالواجب عليه أن يصلي، وأن يتوب إلى الله مما سلف، وعليك بنصيحته، والاستمرار في نصيحته، فإن أصر؛ فالواجب هجره، المشروع لك هجره؛ حتى يتوب إلى الله، وإذا أمكن؛ رفع أمره إلى الهيئة، أو إلى المحكمة حتى ..... ما يلزم شرعًا، فعليك أن تفعلي ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10560/ما-النصيحة-تجاه-الاخ-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39918.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":12518,"question":"أحد الإخوة المستمعين من الرياض رمز إلى اسمه بالحروف (م. م. ع) يقول: ما حكم ترك صلاة الفجر؟","title":"حكم ترك صلاة الفجر","answer":"الجواب:  هذا فيه تفصيل: ترك صلاتها في جماعة لا يجوز، مشابهة لأهل النفاق، الواجب أن تصلى في الجماعة في المساجد، هذا هو الواجب، ويأثم من تأخر عن ذلك كبقية الصلوات، الواجب أن تؤدى في الجماعة، يقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: خوف أو مرض، وجاءه ﷺ رجل أعمى يستأذنه أن يصلي في بيته، فقال -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب هذا أعمى يستأذن أن يصلي في البيت، ليس له قائد، فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فإذا كان الأعمى الذي ليس له قائد يؤمر بالصلاة في الجماعة في المسجد!! فالبصير من باب أولى. المقصود: أن الواجب على المسلم أن يصلي في المسجد جميع الصلوات الخمس مع الجماعة، ولو كان كفيفًا، يجب عليه أن يصلي مع الناس، ولا يجوز له الجلوس في البيت والصلاة في البيت، أما تركها بالكلية هذا كفر، ترك الفجر، أو الظهر، أو العصر، أو المغرب، أو العشاء كفر؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر فالواجب الحذر.  وصيتي لكل مسلم ولكل مسلمة المحافظة على الصلاة في وقتها، وعلى الرجل أن يؤديها في الجماعة في المساجد، وأن يتقي الله، وأن يحذر مشابهة المنافقين، وأن يحذر تركها، أما تعمد تركها؛ فهذا من الكفر -نعوذ بالله- نعم، نسأل الله العافية.  المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10732/حكم-ترك-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40811.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12643,"question":"يقول: كثيرًا ما تفوتني صلاة الظهر والعصر؛ بحكم العمل الذي نقضي فيه ما يقرب من ثمان ساعات، فبم تنصحونني؟ وهل يجوز القضاء؟","title":"حكم من ترك بعض الصلوات بسبب العمل","answer":"الجواب:  الواجب عليك المحافظة على جميع الصلوات، وأن تتقي الله -عز وجل- في ذلك، وأن تتوب إليه مما سلف، ومن تركها عامدًا تاركًا لها قصدًا يكفر بذلك، وعليه التوبة إلى الله من ذلك، ولا يقضي عليه التوبة، وإن قضى؛ فلا بأس خروجًا من خلاف من كلام من قال: لا يكفر إذا كان لم يجحد وجوبها. أما من جحد وجوب الصلاة؛ كفر بإجماع المسلمين، لكن من لم لا يجحد وجوبها، ولكن يتكاسل في بعض الأحيان؛ فهذا جملة من أهل العلم يقولون: لا يكفر، وعليه القضاء، ولكن الصواب أنه يكفر بذلك، وأن التوبة تكفي، فإذا قضى؛ فلا بأس، نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10853/حكم-من-ترك-بعض-الصلوات-بسبب-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45713.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12755,"question":"إذا كان الإنسان لا يصلي إلا يوم الجمعة، فهل يعتبر كافرًا؟","title":"حكم من لا يصلي إلا الجمعة","answer":"الجواب:  نعم، الذي لا يصلي إلا يوم الجمعة يعتبر كافرًا؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وهذا قد تركها؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وقوله ﷺ: من ترك صلاة العصر؛ حبط عمله وحبوط العمل يكون بالكفر بالله، هذا هو الأغلب، حبوط العمل يكون بالكفر، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] قال تعالى: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ[المائدة:5]. فالواجب عليه التوبة إلى الله، والندم على ما مضى منه، وأن يستقيم على الصلاة في جميع الأوقات حتى يموت، ومن تاب تاب الله عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10969/حكم-من-لا-يصلي-الا-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41904.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12845,"question":"الملاحظ سماحة الشيخ أن تارك الصيام يقضي، ولا يقضي تارك الصلاة ....؟","title":"حكم قضاء الصيام والصلاة لمن تركهما","answer":"الجواب:  لأن تارك الصلاة كافر، والكافر ليس له دواء إلا التوبة، كما قال -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] وأما تارك الصوم فالصحيح أنه لا يكفر، لكن يكون عاصيًا؛ فعليه القضاء، وهكذا تارك الزكاة، وهكذا تارك الحج مع الاستطاعة أخر الحج، عليه التوبة إلى الله، وأن يصوم ويحج ويزكي، أما تارك الصلاة فهي عمود الإسلام، من تركها؛ كفر، نسأل الله العافية. فإذا منّ الله عليه بالتوبة؛ كفت التوبة، ولا قضاء عليه، هذا هو الصح، هذا هو الصحيح من قول... أهل العلم؛ لأن الرسول  قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وقال ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولم يقل مثل هذا في الزكاة، ولا في الصوم، ولا في الحج -عليه الصلاة والسلام- فدل على أن الصلاة لها شأن عظيم أعظم من شأن الزكاة والصيام والحج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11059/حكم-قضاء-الصيام-والصلاة-لمن-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46411.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12851,"question":"مستمع بعث يسأل ويقول: ما حكم الإسلام في رجل يصلي في رمضان، ويصوم، ولكنه في بقية الأيام لا يصلي رغم تعداد النصح له؟","title":"حكم من لا يصلي إلا في رمضان","answer":"الجواب:  من لا يصلي إلا في رمضان هو كافر، أو ما يصلي إلا الجمعة فقط كافر، حتى يصلي الجميع؛ لأن الصلاة عمود الإسلام، فرض على كل مسلم ومسلمة، فالذي يتركها إلا في رمضان، أو إلا في الجمعة؛ هذا كافر، يجب أن يستتاب، يجب على ولي الأمر أن يستتيبه، يعني: الأمير، أو المحكمة، فإن تاب وإلا قتل، قتل كافرًا هذا هو الصحيح من أقوال العلماء. وقال بعضهم: إنه يقتل، إنما يكفر إذا جحد الوجوب، أما إذا كان لا يجحد، فإنه يستتاب، فإن تاب وإلا قتل، لكن يقتل حدًا لا كفرًا.  والصواب أنه يقتل كفرًا، أما القتل فيقتل على كل حال، إذا لم يتب يقتل على كل حال من جهة ولي الأمر، ولو كان لم يجحد الوجوب، لكن الصحيح أنه يكفر أيضًا، حتى ولو ما جحد الوجوب؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وهذا يعم من تركها جاحدًا، أو تركها متساهلًا، ويعم الرجال والنساء جميعًا. فالواجب على كل مسلم ومسلمة المحافظة على الصلاة في وقتها، والحذر من تركها، فلو صلى المغرب والظهر والعصر والعشاء، ولكن ترك الفجر؛ كفر، حتى يصلي الجميع، أو صلى الجميع وترك الجمعة؛ كفر حتى يصلي الجميع، لابد أن يصلي الجميع، هذا هو الصواب الذي عليه المحققون من أهل العلم؛ لقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وهذا يعم الواحدة والثنتين والثلاث والأكثر.  فالواجب..... التوبة إلى الله ممن ترك ذلك، أن يتوب إلى الله، وأن يقلع، وأن يستقبل توبةً صادقة نصوحًا، ولا يلزمه قضاء ما فات، بالتوبة يكفر الله ما فات، ويعفو الله عما فات إذا تاب توبة صادقة نصوحًا؛ لقوله -جل وعلا- في كتابه العظيم: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] ولقوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8] وقوله -جل وعلا-: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وهذه مصيبة عظيمة وقع فيها كثير من الناس، التهاون بالصلاة وقع فيها الكثير من الناس، من الرجال والنساء.  فالواجب الحذر، والواجب التوبة إلى الله من ذلك، وألا يغتر الإنسان بقول بعض الناس: إنه لا يكفر، حتى ولو كان ما كفر هي معصية عظيمة، أعظم من الزنا، وأعظم من اللواط، وأعظم من الخمر حتى ولو ما كفر على قول الآخرين، هي أعظم من الزنا، ترك الصلاة أعظم من الزنا، وأعظم من شرب الخمر، وأعظم من اللواط، أكبر الكبائر، من أكبر الكبائر ترك الصلاة، ما بعد الكفر بالله والشرك بالله إلا ترك الصلاة. والصحيح: أنه من الكفر بالله أيضًا، وأنه كفر أكبر -نسأل الله العافية- فهي عمود الإسلام، يقول النبي ﷺ: من حفظها؛ كانت له نورًا وبرهانًا ونجاة يوم القيامة، ومن لم يحافظ عليها؛ لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون، وأبي بن خلف نسأل الله العافية.. ويقول ﷺ بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاةـ فمن تركها؛ فقد كفر وكان عمر  أمير المؤمنين يكتب إلى أمرائه، ويقول: إن أهم أمركم عندي الصلاة، فمن حفظها؛ فقد حفظ دينه، ومنن ضيعها؛ فهو لما سواها أضيع نسأل الله السلامة، ويقول : لا حظ في الإسلام لمن ترك الصلاة نسأل الله العافية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11066/حكم-من-لا-يصلي-الا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46417.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12903,"question":"السؤال الأخير الذي نعرضه لأخينا في هذه الحلقة يقول: زوجتي لا تصلي، وبناتي أيضًا، ولا يتحجبون، فماذا أفعل؟ وجهوني، جزاكم الله خيرًا.","title":"كيفية التعامل مع زوجة وبنات لا يصلين","answer":"الجواب:  الواجب عليك نصيحة الزوجة، والبنات، وتأديبهن على ترك الصلاة حتى يستقمن، هذا واجب عليك، الصلاة عمود الإسلام، وهي الركن الثاني من أركان الإسلام الخمسة، وهي أعظم الأركان بعد الشهادتين، من حفظها؛ حفظ دينه، ومن ضيعها؛ فهو لما سواها أضيع، والله يقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول -جل وعلا-: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71]. فالواجب على المؤمنين والمؤمنات التناصح، والتآمر بالمعروف، والتناهي عن المنكر، وزوجتك وبناتك من أحق الناس بنصيحتك وإرشادك، وأمرك لهن بالمعروف، ونهيك لهن عن المنكر، ولا يجوز التساهل في هذا أبدًا، ولو بالضرب، ولو بضرب الزوجة ضربًا غير مبرح، وضرب البنات ضربًا غير مبرح حتى يستقمن؛ لأن هذه الصلاة عمود الإسلام، من تركها؛ كفر -نسأل الله العافية- يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر نسأل الله العافية. فاتق الله يا أيها السائل! واحرص على هداية زوجتك وبناتك، واستعن على ذلك أيضًا بأقاربك، مثل أخوال بناتك، إخوان الزوجة، أبيها، أعمامها يساعدونك، اتفق معهم على أن يساعدوك على زوجتك، وعلى بناتك؛ حتى يقمن الصلاة؛ حتى يستقمن في دينهن، لا تساهل في هذا الأمر. فإن لم تستقم؛ ففارقها، طلقها، ولا يجوز بقاؤها معك، وهي لا تصلي، بل إما أن تتوب، وإما أن تفارقها، وهكذا البنات لابد من تأديبهن؛ حتى يتبن إلى الله، حتى يستقمن على الصلاة، نعم. المقدم: جزاكم الله خيرًا. ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/11118/كيفية-التعامل-مع-زوجة-وبنات-لا-يصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46805.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":12919,"question":"يقول: إنني أعاني من مشكلة ربما يعاني منها الكثير من الناس، ألا وهي أن معظم أصدقائي، ومن أعاشرهم في المدرسة، وأحيانًا في البيت لا يؤدون الصلاة، وكثيرًا ما أسمع في برنامجكم أن الذي لا يصلي يعتبر كافرًا، فلا يسلم عليه، وما إلى هنالك، ولقد قمت بنصحهم، ولكن بدون جدوى، مع أنهم ذوي خلق عالي، ومعاملتهم لي ولغيري كلها جيدة، ولم أر منهم إلا كل خير غير ما ذكرت، أفيدوني في هذا الأمر الذي طالما يضايقني، وما هي نصيحتكم لتارك الصلاة، وماذا أعمل معهم، جزاكم الله خيرًا؟","title":"حكم تارك الصلاة وكيفية التعامل معه","answer":"الجواب:  الواجب نصيحة من عرف بترك الصلاة، وتحذيره من مغبة ذلك؛ لأن ترك الصلاة كفر أكبر، وإن لم يجحد وجوبها في أصح قولي العلماء؛ لقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة وقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة، وقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر هذه الأحاديث العظيمة تدل على أن من تركها يكفر، وإن لم يجحد وجوبها. أما إن جحد وجوبها؛ فإنه كافر عند جميع العلماء -نسأل الله العافية- والله يقول -جل وعلا- في كتابه العظيم: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] ويقول : قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] إلى أن قال سبحانه: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:6-11].  هذه نعمة عظيمة، وفضل كبير لمن حافظ على الصلاة أنه يكون من أهل الفردوس، من أهل أعلى الجنة، الفردوس أعلى الجنة وأوسطها وخيرها، فمن تخلق بهذه الأخلاق التي ذكرها الله في سورة المؤمنون في قوله -جل وعلا-: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ ۝ وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ ۝ وَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ ۝ وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ ۝ وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ ۝ وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:1-11]. هذه صفات عظيمة، من حافظ عليها؛ صار من أهل الفردوس، وأعظمها الصلاة، وقال في سورة المعارج: إِنَّ الإِنسَانَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا ۝ إِلَّا الْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَلَى صَلاتِهِمْ دَائِمُونَ ۝ وَالَّذِينَ فِي أَمْوَالِهِمْ حَقٌّ مَعْلُومٌ ۝ لِلسَّائِلِ وَالْمَحْرُومِ ۝ وَالَّذِينَ يُصَدِّقُونَ بِيَوْمِ الدِّينِ ۝ وَالَّذِينَ هُمْ مِنْ عَذَابِ رَبِّهِمْ مُشْفِقُونَ ۝ إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ ۝ وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ ۝ وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ ۝ وَالَّذِينَ هُمْ بِشَهَادَاتِهِمْ قَائِمُونَ ۝ وَالَّذِينَ هُمْ عَلَى صَلاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ فِي جَنَّاتٍ مُكْرَمُونَ [المعارج:19-35] هذه صفة الأخيار، هذه صفة أهل السعادة، وعلى رأسهم المحافظون على الصلوات. والمحافظة على الصلاة من أسباب الاستقامة، فإن من حافظ عليها؛ حفظ دينه، ومن ضيعها؛ فهو لما سواها أضيع. قال نافع مولى ابن عمر -رضي الله تعالى عنهما-: كان عمر  يعني: عمر بن الخطاب -رضي الله عنه- أمير المؤمنين- كان يكتب إلى عماله، ويقول، يعني: أمرائه -يكتب إليهم- ويقول: إن أهم أمركم عندي الصلاة، فمن حفظها؛ حفظ دينه، ومن ضيعها؛ فهو لما سواها أضيع. فالذي لا يصلي؛ يجب أن يهجر، إذا لم تجد فيه النصيحة؛ يجب أن يهجر، ولا يسلم عليه، ولا تجاب دعوته، ولا يدعى إلى وليمة، ولا إلى غيرها؛ لأنه أتى منكرًا عظيمًا، وكفرًا بواحًا، نسأل الله العافية.  ويجب أن يرفع أمره إلى ولاة الأمور حتى يستتاب، فإن تاب وإلا قتل، فإن أمره عظيم وخطير، وهو يجر غيره، أيضًا إلى مثل فعله، يجر غيره من زملائه، وجلسائه إلى مثل فعله.  فالواجب أن يناصح، وأن ينكر عليه من أقاربه وجلسائه وزملائه إنكارًا واضحًا، إنكارًا شديدًا حتى يعلم خطورة ما هو عليه، وحتى يعلم بشاعة ما فعل، وحتى يعلم أنه أتى كفرًا بواحًا، ومنكرًا عظيمًا؛ لعله يستجيب، لعله يهتدي، فإن أبى؛ وجب هجره، ورفع أمره إلى ولاة الأمور حتى يستتاب، فإن تاب وإلا قتل كافرًا على الصحيح، وإن لم يجحد الوجوب، أما إن جحد وجوبها؛ فإنه يكون كافرًا مرتدًا عن الإسلام عند جميع العلماء، نسأل الله العافية. والغالب أن الذي لا يصلي، ولا يبالي، ولا يهتم بالصلاة، الغالب عليه أنه لا يقر بالوجوب، ولا يبالي بوجوبها، ولا يهتم بوجوبها، فهو في عمله يدل على أنه مكذب. فالواجب على المسلمين جميعًا أن يعنوا بهذا الأمر، وأن ينكروا على من تخلف عن الصلاة، وأن يبينوا له خطورة ما فعل، وشناعة ما فعل؛ لعله يهتدي؛ لعله يرجع إلى الصواب، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/11134/حكم-تارك-الصلاة-وكيفية-التعامل-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46904.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":12990,"question":"ننتقل إلى رسالة بعث بها مستمع يقول: هل يجوز السلام على تارك الصلاة، وإذا لم نسلم عليه ماذا يجب علينا؟","title":"إلقاء السلام على تارك الصلاة","answer":"الجواب:  تارك الصلاة يجب أن يهجر، ويرفع أمره إلى ولي الأمر إذا كان في البلد حكومة إسلامية يرفع الأمر إليها حتى يستتاب، فإن تاب، ولا قتل، تارك الصلاة لا يترك، يرفع إلى المحكمة، إلى الإمارة الشرعية، حتى يلزم بالحق، أو يستتاب، فإن تاب وإلا قتل؛ لقول الله سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] دل على أنهم إذا لم يتوبوا لا يخلى سبيلهم. وهكذا الزاني إذا عرف زناه؛ يقام عليه الحد، وهكذا سائر المعاصي إذا أظهرها صاحبها؛ يقام عليه حدها، أو تعزيرها، ولا يترك، إذا أعلنها، وأظهرها، نعم.","link":"https://binbaz.org.sa/fatwas/11206/القاء-السلام-على-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50404.mp3","categories":["الآداب والأخلاق المحمودة","حكم الصلاة وأهميتها"]},{"id":12999,"question":"السائلة (ج. ع. ع) المدينة المنورة كتبت هذه الرسالة بأسلوبها الخاص المطول تذكر -يا سماحة الشيخ- وتقول: عندي مشكلة بسبب إحدى قريباتي التي جاءت من إحدى القرى لتعيش معنا في منزل واحد في بيتنا؛ من أجل إكمال الدراسة بالكلية، فمنذ حضورها زادت من همومي، وذلك لإهمالها الكثير من أوامر الإسلام، وخاصة الصلاة، وقد حاولت معها بشتى الوسائل ببيان خطر ذلك، تارة بالنصح، وتارة بالكتب، وتارة بالأشرطة الإسلامية، فهي قد تصلي فرضًا، وتترك أيامًا عدة، وعندما أذكرها بالصلاة؛ تغضب مني، وتقول: أنا التي سوف أدخل النار، لست أنت، وإنك بريئة من ذنبي، اتركيني لوحدي، مع العلم بأنها تعرف عقاب ذلك في الدنيا والآخرة، هل أستمر معها في ذلك النصح، واستمريت معها أكثر من سنتين دون فائدة، فهي لم تلتزم بذلك، ثم تعود لما كانت عليه، وبعد تلك المحاولات تركتها، فهل علي إثم في تركي لها، وجهوني سماحة الشيخ؟","title":"كيفية التعامل مع تارك الصلاة","answer":"الجواب:  الواجب إبعادها منكم، وألا تبقى عندكم، هذه تستحق الإبعاد، وتستحق أن يرفع أمرها إلى ولي الأمر، إلى المحكمة، فإن تابت وإلا قتلت، ترك الصلاة يوجب القتل، ردة عن الإسلام -نعوذ بالله- فالواجب عدم تركها لديكم، وإبعادها، ورفع أمرها إلى ولي الأمر؛ حتى يستتيبها، فإن تابت وإلا قتلت. ما يجوز التساهل في هذا الأمر، فالصلاة عمود الإسلام، من ضيعها؛ فقد ضيع الإسلام، ومن حفظها؛ حفظ الإسلام، وهذه امرأة خبيثة، يجب أن تجاهد، فإن استقامت، وصلت؛ فالحمد لله، وإلا وجب أن يقام عليها حد الشرع بالقتل؛ حتى يستراح منها ومن أمثالها. وقد أحسنت في نصيحتها، ولك الأجر العظيم، ولكن يجب أن تستمري في نصيحتها، والسعي في إبعادها عنك، وعن بيتك، ورفع أمرها إلى ولي الأمر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11216/كيفية-التعامل-مع-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50412.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13018,"question":"رسالة وصلت إلى البرنامج من المستمع: رسمي شفيق عبدالنصير، يقول في أحد أسئلته: إنني أقوم صباحًا في بعض الأيام متأخرًا، ولم يبق على طلوع الشمس سوى ست، أو سبع دقائق، وأتوضأ، فهل أبدأ بصلاة الفرض، أم بسنة الصبح؛ لأنني أخشى إن صليت السنة أن تطلع الشمس، ويخرج وقت صلاة الفرض؟","title":"هل يبدأ براتبة الفجر من استيقظ قبيل طلوع الشمس؟","answer":"الجواب:  الواجب عليك أن تركب الساعة على وقت الفجر قبله بقليل حتى تقوم قبل الأذان، وتتهيأ للصلاة، وتصلي مع المسلمين في الجماعة، ولا يجوز لك التأخير حتى يفوت وقت الجماعة، أو يفوت الوقت، هذا حرام، ومنكر، وتشبه بأعداء الله المنافقين. بل الواجب على كل مسلم أن يعتني بالصلاة في الجماعة في الفجر وغيرها، ويستعين بالله، ثم بالساعة، الساعة نافعة، ما كان ما عنده من يوقظه، أو يخشى أن يغفلوا، يشتري الساعة ويجعلها عند رأسه، ويوكدها على قرب الأذان؛ حتى يستيقظ مع الأذان، فيتمكن من الوضوء والغسل إن كان عنده زوجة، والحضور مع المسلمين في المساجد حتى يصلي الجماعة، هذا هو الواجب على المسلم، ولا يجوز له التأخر عن هذا والتساهل بهذا، والتساهل بهذا من مشابهة المنافقين، الذين قال الله فيهم سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142] ثم يتوجه إلى المسجد، فيصلي مع الناس.  وإذا كان فاتته الصلاة؛ يبدأ بالسنة الراتبة يصلي ركعتين خفيفتين السنة الراتبة، ثم يصلي الفريضة، كان النبي ﷺ يصليهما ولو فات الوقت، ربما نام عن الصلاة في بعض أسفاره ﷺ فلم يستيقظوا إلا بحر الشمس، فإذا قام أمر بالأذان، وصلى السنة الراتبة، وصلى الفجر، عليه الصلاة والسلام. فالمؤمن إذا غلبه النوم، ولم يقم إلا متأخرًا؛ فإنه يصلي سنة الفجر، ثم يصلي الفريضة، ولو طلع الفجر، ولو طلعت الشمس، ولو بعد طلوع الشمس؛ السنة أن يقدمها قبل الصلاة، ولو عند طلوع الشمس، لكن لا يجوز له أبدًا أن يتأخر في القيام إلى الصلاة إلى أن تفوته صلاة الجماعة، بل يجب وجوبًا، ويتعين عليه أن يفعل الأسباب التي تجعله يستيقظ حتى يحضر الصلاة مع المسلمين في أوقاتها في الفجر، وفي غيرها، رزق الله الجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11235/هل-يبدا-براتبة-الفجر-من-استيقظ-قبيل-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47114.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13051,"question":"السائلة هدى من الدمام تقول: جدتي في الخامسة والثمانين من العمر تصلي، ولكن بدون طهارة، وتزيد في الركعات وتنقص، وتصلي وهي جالسة حيث أنها اختلطت عليها الأمور، وكانت قبل ذلك تصلي صلاة صحيحة، ووضوءًا صحيحًا، فهل علينا حرج في ذلك؟","title":"من اختل عقله بسبب الكبر هل عليه صلاة؟","answer":"الجواب:  ليس عليكم شيء الحمد لله، قد يختل شعورها، ولا عليها شيء، لا عليها صلاة ولا صيام، هذه المرأة بهذا العمل اتضح أنها اختل شعورها، وسقط عنها التكليف، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/11268/من-اختل-عقله-بسبب-الكبر-هل-عليه-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50511.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13067,"question":"على بركة الله نبدأ هذا اللقاء بسؤال للسائل من سوريا (م . ش) يقول: هل يقضي المسلم الصلاة التي فاتته وكانت بإرادته، وكان عامدًا متعمدًا، ماذا يلزمه في هذه الحالة، وهل يقضي ما فاته؟ مأجورين.","title":"ماذا يلزم تارك الصلاة بعد التوبة؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فالصلاة أمرها عظيم، وهي عمود الإسلام، وهي الركن الثاني من أركان الإسلام، قال الله -جل وعلا-: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238] وقال تعالى: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56] وقال -جل وعلا-: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45] والآيات في أمر الصلاة كثيرة جدًا. ويقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة ويقول -عليه الصلاة والسلام-: بني الإسلام على خمس  يعني: على خمس دعائم: شهادة أن لا إله إلا الله، وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت ويقول -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه عن جابر بن عبدالله الأنصاري -رضي الله عنهما- ويقول أيضًا -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر أخرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة . فالذي يتعمد ترك الصلاة؛ يكفر بذلك -نسأل الله العافية- على الصحيح، وإن لم يجحد وجوبها، أما إذا جحد وجوبها؛ يكفر عند الجميع، ولو صلى، إذا قال: إنها غير واجبة؛ فهو كافر، ولو صلى عند جميع أهل العلم. لكن إذا تكاسل، هو يعلم أنها واجبة، ويدري أنها واجبة، يعترف، ولكن يتكاسل، ولا يصلي؛ هذا أيضًا كافر على الصحيح؛ لهذه الأحاديث السابقة، فإذا تاب الله عليه؛ ما عليه قضاء، إذا تاب الله عليه؛ يبتدئ من جديد، يصلي من جديد، وليس عليه قضاء إذا كان تركها عمدًا عدوانًا، أما إذا كان ناسيًا، أو نائمًا؛ يقضي، أما إذا تركها عمدًا متساهلًا؛ فعليه التوبة، وليس عليه القضاء، فإن قضى؛ فلا بأس، لكن ليس عليه قضاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11285/ماذا-يلزم-تارك-الصلاة-بعد-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50701.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13133,"question":"مستمع سمى نفسه: العبد الفقير إلى الله محمد محمد عبدالله مصري، ويعمل بالعراق حين كتب الرسالة يقول: أنا أعمل بالعراق، وأصبت بالعمل في قدمي؛ مما تسبب لي بعملية تجبيس، وبعدها علاج طبيعي، وقد استغرق هذا مدة أربعة شهور، انقطعت فيها عن الصلاة، علمًا أنني قبلها -والحمد لله- كنت مستمرًا على الصلاة، والآن -الحمد لله- مداوم عليها، هل يجب علي إعادة هذه الصلاة، أم أنه يعتبر عذر شرعي؟","title":"حكم من ترك الصلاة لمرض أصابه","answer":"الجواب:  إن كنت تركت الصلاة تعتقد أن هذا عذر، وأنه لا شيء عليك من أجل هذا المرض؛ فعليك القضاء، وإن كنت متساهلًا متعمدًا ترك الصلاة لقلة مبالاتك؛ فعليك التوبة إلى الله  والرجوع إليه، ولا قضاء عليك على الصحيح، بل عليك التوبة إلى الله؛ لأن تركها كفر، والكافر ليس عليه إلا التوبة، ومن ترك الصلاة؛ كفر إذا تعمد ذلك، لقول الله -عز وجل-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] وقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فإذا كنت عامدًا تركها، متساهلًا؛ فالواجب عليك التوبة إلى الله، والندم، والعزم ألا تعود في ذلك، ولا قضاء عليك على الصحيح. أما إن كنت تظن أنك معذور، وأنك بهذا المرض ليس عليك أن تفعل؛ فأنت مثل من نسيها، أو نام عنها يقضي، تقضيها، ولا شيء عليك، نعم.  المقدم: جزاكم الله خيرًا، ولعله يعتقد أنه معذور سماحة الشيخ؟  الشيخ: لعله لعله.  المقدم: لعله يعتقد.  الشيخ: لعله إن شاء الله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11370/حكم-من-ترك-الصلاة-لمرض-اصابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47411.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13140,"question":"لها سؤال طويل أيضًا تقول: إن والدها لا يهتم بإخوانها من حيث الصلاة، وإنها تصلي بهم من أجل تعويدهم، وأحيانًا تصلي بهم وإن كانت معذورة شرعًا، لئلا تبين لهم عذر النساء، فما رأيكم؟","title":"ما واجب الآباء نحو الأبناء في الصلاة، وحكم إمامة المرأة؟","answer":"الجواب:  الواجب على أبيهم العناية بهم، إن كانوا ذكورًا يلزمهم بالصلاة مع الجماعة في المساجد، ولو بالضرب حتى يستقيموا، لقوله ﷺ: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع فالوالد مسؤول عن أولاده، وعليه أن يجتهد في إقامتهم الصلاة، وصلاتهم مع الناس في المساجد حتى يعتادوها، ويستقيموا عليها. أما إن كان الأولاد بنات؛ فإنه أيضًا يقوم عليهن، ويلزمهن بالصلاة، ويؤدبهن إذا تكاسلوا عن الصلاة. أما أنت فلا مانع من أن تصلي بهن إذا كن بنات، تعلمينهن، وتقفي وسطهن، وتعلمينهن الصلاة؛ لأنهن بنات، أما الأولاد لا، الذكور يلزمهم الخروج إلى المسجد، وليس للمرأة أن تصلي بهم، المرأة لا تصلي بالرجال، ولكن تقومين عليهم، وتوجهينهم إلى الصلاة في المسجد، ولو بالتوبيخ إذا دعت الحاجة إلى ذلك، ولو بالضرب إذا كنت الكبيرة وهم الصغار إذا أهملهم أبوهم، ولا تصلي بهم، لا تصلي أنت بهم إذا كانوا ذكورًا، ولكن تأمرينهم وتجاهدينهم حتى يصلوا في الجماعة، وتشجعين الوالد على القيام عليهم، وتطلب منه العناية بهم، من باب التعاون على البر والتقوى. أما البنات فلا بأس أن تصلي بهن وتعلمينهن حتى يعتدن ذلك، والإمامة تكون وسط النساء، لا قدامهن. أما أن تصلي بهم وأنت في الحيض لا يجوز هذا، هذا منكر، ليس لك أن تصلي بهن وأنت حائض، أو نفساء، ولو قصدت الخير، ليس لك هذا، بل الحائض لا تصلي، ولا تستعمل أعمال الصلاة توهم الصلاة، ولا تصلي وهي نفساء، ويحرم عليها هذا العمل، هذا شر عظيم، ومنكر -نسأل الله السلامة- نعم. المقدم: جزاكم الله خيرًا، بالنسبة للمعلم إذا أراد أن يعلم الصبيان وهو على غير وضوء، يجوز له ذلك سماحة الشيخ، يعلمهم كيفية الصلاة، لكنه على غير وضوء؟ الشيخ: ما هو بهذه الصلاة، يعلم يقول: الركوع كذا، والسجود كذا، ما في بأس. المقدم: لا بأس بهذا. الشيخ: لا يصلي بهم على أنها صلاة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11394/ما-واجب-الاباء-نحو-الابناء-في-الصلاة-وحكم-امامة-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47415.mp3","categories":["حكم الصلاة وأهميتها","تربية الأولاد"]},{"id":13189,"question":"إحدى الأخوات المستمعات سمت نفسها حليمة تقول: إنني أم لعدد كبير من الأبناء، وأنا والحمد لله على قدر لا بأس به من الإيمان، ولكن زوجي لا يعرف أي شيء عن ذلك، فهو منذ زواجنا منذ خمسة وعشرين عامًا وهو تارك للصلاة، وتصفه بأوصاف أخرى يترفع البرنامج عن ذكرها وترجو توجيهكم سماحة الشيخ.","title":"حكم المرأة إذا كان زوجها لا يصلي","answer":"الجواب:  هذا زوج لا خير فيه، ولا يجوز البقاء معه، بل يجب أن تعتزليه، وأن تمتنعي منه، وأن لا يقربك لا بجماع، ولا غيره، وهذا العمل الذي فعلتيه معه منكر، صبرت معه خمسة وعشرين سنة، وهو لا يصلي، هذا منكر، والعياذ بالله.  عليك التوبة إلى الله من ذلك، والندم من هذا العمل السيئ، هذا هو الصحيح من أقوال العلماء، لقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وإذا كانت عنده سيئات أخرى، ومعاصي أخرى صار شرًا إلى شر، نسأل الله العافية. فالواجب عليك البعد منه، وتركه، وعدم تمكينه من نفسك، والامتناع منه، فإن طلقك، وأعطاك وثيقة بذلك؛ فالحمد لله، وإلا فارفعي الأمر إلى الحاكم الشرعي إذا كنت في بلاد إسلامية. نعم. المقدم: جزاكم الله خيرًا، ألاحظ سماحة الشيخ في نهاية رسالتها أنها تتعلل بالأولاد، وتخشى أن يضيعوا، ولا سيما وأنهن من البنات؟ الشيخ: ليس هذا بعذر، أولادك لك، وأنت أحق بأولادك من هذا الكافر، والله يرزقك وإياهم سبحانه، والرزق عليه -جل وعلا- وعلى الحاكم الشرعي أن يلزمه بما يلزم من جهة النفقة، أن هذا إلى الحاكم الشرعي، وأنت أولى بأولادك. فالحاصل: أن هذا لا يمنع من البعد منه، والحذر منه، وعدم تمكينه من نفسك والأولاد رزقهم على الله، والحاكم الشرعي ينظر في الأمر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11444/حكم-المراة-اذا-كان-زوجها-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_475/47506.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13342,"question":"تقول: بعض الأشخاص لا يصلون صلاة الفجر، ويصلون الصلوات الأخرى، فهل صلاتهم هذه مقبولة؟","title":"حكم من يترك صلاة الفجر","answer":"الجواب: الصحيح من أقوال العلماء أن من ترك واحدة من الصلوات؛ كفر، ولا تقبل بقية الصلوات، ولا بقية أعماله؛ لأن الصلاة عمود الإسلام، من حفظها؛ حفظ دينه، ومن ضيعها؛ فهو لما سواها أضيع، وقد صح عن رسول الله ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وقال -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة وليس لقوله: بين الرجل وبين الكفر مفهوم، الأحكام تعم الرجال والنساء، فكل حكم يرد في الرجل؛ فهو للنساء، وكل حكم يرد في النساء؛ فهو للرجل، إلا ما خصه الدليل. والخلاصة: أن من ترك الصلاة من الرجال والنساء كفر بذلك، ولو لم يجحد وجوبها، هذا هو الصواب من قولي العلماء، وهو المعروف عن أصحاب النبي ﷺ. فالواجب على من ترك الصلاة، أو ترك فرضًا منها أن يتوب إلى الله، وأن يبادر بالرجوع إليه، والتوبة إليه توبة نصوحًا، والله يتوب على التائبين، سواء كانت صلاة الفجر، أو المغرب، أو العشاء، أو الظهر، أو العصر، أو الجمعة. والواجب على أقاربه وإخوانه وزملائه أن ينصحوه، وأن يوجهوه إلى الخير، وأن ينكروا عليه ما تساهل فيه من الصلاة، فإن لم يبال؛ رفع أمره إلى ولي الأمر؛ حتى يعاقب بما يستحق، ولا يجوز السكوت عنه، ولا التساهل معه؛ لأن الله يقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول النبي ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه وذلك أضعف الإيمان.  وترك الصلاة أعظم المنكرات بعد الشرك، أعظم الذنب بعد الشرك ترك الصلاة، وتركها من الكفر داخل في الشرك، والكفر للحديث السابق، وهو قوله ﷺ:  بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. وثبت عنه ﷺ أنه لما سئل عن بعض الأمراء الذين يخالفون بعض الشرع سأله السائل: هل نقاتلهم؟ قال: لا، ما أقاموا فيكم الصلاة وفي رواية: إلا أن تروا كفرًا بواحًا، عندكم من الله فيه برهان فجعل ترك الصلاة برهانًا على الكفر الأكبر، أنه يبيح الخروج على ولاة الأمور. وجعل إقامتها برهانًا على الإسلام، وأنه لا يجوز الخروج على من أقام الصلاة. فالحاصل: أن الواجب على كل مسلم أن يؤدي الصلاة، في أوقاتها، وهكذا المسلمات من النساء يجب على كل مسلم ومسلمة مكلف أن يؤدي الصلاة في أوقاتها، ومتى ترك واحدة منها من الصلوات الخمس كفر بذلك، فإن تركها كلها كفر أيضًا من باب أولى، نسأل الله السلامة. وقد يفعل بعض الناس منكرًا آخر، وهو أنه يصلي في رمضان، ولا يصلي في غير رمضان، أو يصلي الجمعة، ولا يصلي غيرها، وهذا أشد كفرًا ممن ضيع صلاة الفجر، نسأل الله العافية. فالحاصل: أن من ترك الصلاة يومًا، أو شهرًا، أو سنة، أو في الأسبوع مرة، أو في الأسبوع مرتين؛ فهو كافر بكل حال، بل كلما كان الترك أكثر؛ صار الكفر أشد -نسأل الله العافية- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11628/حكم-من-يترك-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47702.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13361,"question":"هذا السائل أبو محمد من الزلفي يقول في هذا  أثناء فترة الشباب كان يفوتني البعض من الصلوات، مثل العصر والفجر على سبيل المثال، والحمد لله الآن أقضي جميع الصلوات الخمس في المسجد، وأصلي مع الجماعة، وأحرص على ألا يفوتني أي فرض، وأفكر كيف أقضي ما فاتني في فترة الشباب؟ هل ممكن أن أقضي مع كل فرض فرضًا بما فاتني، حتى ولو بين الأذان والإقامة، أرجو منكم بيان ذلك؟","title":"حكم قضاء الصلاة بعد التوبة من تركها","answer":"الجواب: ليس عليك قضاء، والتوبة تجب ما قبلها، والحمد لله؛ لأن ترك الصلاة كفر، ولا خلاص منه إلا بالتوبة، ما دمت تبت من ذلك، والحمد لله فلا قضاء عليك، التوبة تجب ما قبلها؛ لأن من ترك الصلاة كفر، فإذا تاب، ورجع إلى الحق والهدى؛ فليس عليه قضاء، ولم يأمر النبي ﷺ المرتدين أن يقضوا، والصحابة لم يأمروا المرتدين أن يقضوا، فلما أسلموا لم يأمرهم أن يقضوا ما فاتهم من صيام أو صلاة، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11646/حكم-قضاء-الصلاة-بعد-التوبة-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52404.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":13394,"question":"في فقرته الثانية يقول عن الصوم: كيف تصوم الجوارح في رمضان؟","title":"بيان كيفية صيام الجوارح","answer":"الجواب: صوم الجوارح بعدها عما حرم الله عليها، فاللسان يصوم عما حرم الله عليه من الغيبة والنميمة، والكذب، ونحو ذلك، واليد تصوم عما حرم الله عليها من السرقة من الظلم والعدوان، ونحو ذلك. والقدم أيضًا تبتعد عما حرم الله عليها، فلا يسير إلى ما حرم الله، لا يمشي إلى ما حرم الله، وهكذا البطن يصان عن أكل الحرام، فيصوم بطنه عن أكل الحرام، ويصوم سمعه عن سماع ما حرم الله من آلات الملاهي.. من الغيبة والنميمة إلى غير هذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11684/بيان-كيفية-صيام-الجوارح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52513.mp3","categories":["حكم الصلاة وأهميتها","مسائل متفرقة في الصيام"]},{"id":13459,"question":"في أسئلة هذه السائلة (ع. ع. م) من الأردن تقول: سماحة الشيخ! رجل لا يصلي، ويأكل الربا، فهل يجوز للابن أن يسكن في بيت والده؟ وهل تقبل هدية الذي لا يصلي؟ أو يصلي ولكن يأكل الربا إذا كنا نعلم عن حاله ذلك، وإذا كنا لا نعلم فهل نسأل عن حاله قبل قبول الهدية؟ وجهونا في ذلك.","title":"كيفية التعامل مع تارك الصلاة وآكل الربا","answer":"الجواب: الذي لا يصلي ينكر عليه، ترك الصلاة كفر -نعوذ بالله- أكبر، يقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر فالأمر عظيم، فالذي لا يصلي ينكر عليه، وينصح، ويوجه إلى الخير، فإن استقام وإلا رفع أمره إلى ولي الأمر حتى يستتاب، فإن تاب وإلا قتل، ويستحق الهجر، وألا يكلم حتى يتوب إلى الله . وهكذا من يأكل الربا قد تعاطى معصية، يستحق أن يهجر عليها، لكن ينصح ويوجه إلى الخير؛ لعله يدع الربا، هذا هو الواجب على إخوانه المسلمين من أقاربه، وغيرهم أن ينصحوه ويوجهوه؛ لأن أكل الربا من المحرمات، والرسول ﷺ: لعن آكل الربا وموكله والله يقول -جل وعلا-: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ [البقرة:278-279] فالواجب الحذر.  ومن أصر على أكل الربا أو تخلف عن الصلاة استحق أن يهجر، واستحق أن يؤدب حتى يتوب إلى الله  نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11762/كيفية-التعامل-مع-تارك-الصلاة-واكل-الربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51707.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":13475,"question":"تسأل أختنا سؤالها الأخير في هذه الحلقة وتقول: ما رأيكم إذا كان الزوج لا يصلي، أو الزوجة لا تصلي والزوج يصلي، ما الأذى على من يصلي والحال ما ذكر؟ جزاكم الله خيرًا.","title":"ما حكم النكاح إذا كان أحد الزوجين لا يصلي؟","answer":"الجواب: إذا تزوج إنسان امرأة، ثم بان بعد الزواج أن أحدهما لا يصلي؛ يفسخ النكاح؛ لأن من لا يصلي كافر على الصحيح من أقوال العلماء، ولو لم يجحد الوجوب، ولو كان كسلًا، ترك الصلاة كفر أكبر -نسأل الله العافية- في أصح قولي العلماء، فإذا كان لا يصلي؛ فسخ النكاح، أو كانت هي لا تصلي وهو يصلي؛ فسخ النكاح، أما إن كانا لا يصليان جميعًا؛ فالنكاح صحيح كسائر الكفرة، كنكاح سائر الكفرة. أما إذا كان أحدهما يصلي والآخر لا يصلي؛ فإنه يفسخ النكاح حتى يتوب من لا يصلي، فإذا تاب ورجع؛ جدد النكاح له عليها إذا رضيت بذلك، وإن كانت هي التي لا تصلي، فإذا تابت ورجعت؛ جدد لها النكاح عليه إذا رغب في ذلك. والدليل على هذا قول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة مع أدلة أخرى في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/11778/ما-حكم-النكاح-اذا-كان-احد-الزوجين-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47804.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":13487,"question":"في سؤاله الثاني يقول سماحة الشيخ: هل تارك الصلاة متعمدًا مع شهادته بأن لا إله إلا الله وأن محمدًا رسول الله، يعد كافرًا مخلدًا في النار؟","title":"حكم ترك الصلاة تعمدًا","answer":"الجواب: نعم، من ترك الصلاة تعمدًا؛ يعد كافرًا، هذا هو الصحيح، إلا أن بعض أهل العلم قال: يكون أتى كبيرة إذا لم يجحد وجوبها، ولكن ظاهر النصوص أنه يكفر بذلك إذا تركها، ولو شهد أن لا إله إلا الله، ولو زكى، ولو صام، إذا ترك الصلاة؛ يكفر بذلك تساهلًا وكسلًا؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وقوله ﷺ: من ترك صلاة العصر؛ حبط عمله والله يقول: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] فعاملهم معاملة الكافر. أما إذا جحد وجوبها، قال: ما هي بواجبة الصلاة؛ هذا يكفر عند الجميع، عند جميع المسلمين .. عند جميع العلماء، ولو صلى، إذا قال: ما هي بواجبة؛ كفر عند الجميع؛ لأنه مكذب لله ولرسوله، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11790/حكم-ترك-الصلاة-تعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51801.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13536,"question":"تقول السائلة أم عثمان من اليمن: هل تصح زكاة قاطع الصلاة؟","title":"هل تصح زكاة تارك الصلاة؟","answer":"الجواب: من لم يصل فهو كافر -نسأل الله العافية- يقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وإن لم يجحد وجوبها لعموم الحديث، أما من جحد وجوبها قال: ما تجب؛ هذا كافر عند الجميع، لا تصح صلاته، ولا زكاته، ولا غير ذلك ولو صلى، ما دام يجحد وجوبها؛ فهو كافر. أما إذا كان يقول: إنها واجبة، ولكن يتكاسل، ولا يصلي؛ فهذا فيه خلاف بين العلماء، والصواب: أنه كافر كفر أكبر؛ لقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة أخرجه مسلم في الصحيح، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر أخرجه أهل السنن والإمام أحمد بإسناد صحيح، ولقوله ﷺ: من ترك صلاة العصر؛ حبط عمله ولقوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11852/هل-تصح-زكاة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53202.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":13539,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، وقع في نهايتها توقيعًا غير مقروء، كل الرسالة وفيها ستة أسئلة تدور حول تارك الصلاة، ولا سيما إذا كان أبًا أو عمًا، وتارك الصلاة هذا قد يصلي الجمعة فقط، وقد يصلي بعض الفروض، ويترك الفروض الأخرى.ويسأل سماحة الشيخ هل يجوز تقبيل رؤوسهم، وهل يجوز بدؤهم بالسلام، ويرجو التوجيه حول هذا الموضوع الخطير؛ لأنه يلاحظ انتشاره في الكثير من المحلات. جزاكم الله خيرًا.","title":"هل يجوز تقبيل رأس تارك الصلاة؟","answer":"الجواب: ترك الصلاة جريمة عظيمة ومنكر شنيع، وقد اختلف العلماء -رحمة الله عليهم- في كفر صاحبه إذا لم يجحد وجوبها، وإنما تكاسلًا، فعله تكاسلًا وتهاونًا، فقال بعضهم: يكون كفرًا أصغر، وقال بعضهم: بل يكفر كفرًا أكبر، وهذا هو الصواب، ولو صلى الجمعة بعض الأحيان، ولو صلى بعض الأوقات؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها؛ فقد كفر؛ وقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة. فالصواب: أنه يكون كفرًا أكبر، لكن إذا كان التارك الوالدين، أو أحدهما فإنك ترفق بهما، وتنصحهما، كما قال الله  في الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] لأن الوالد له حق عظيم، ولو كان كافرًا عليك أن ترفق به، وأن تصحبه بالمعروف؛ لعل الله يهديه بأسبابك، ولو قبلت رأسه ترجو أن الله يهديه بسبب ذلك؛ فلا بأس بذلك، هذا من المعروف وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] والدعاء له أن الله يوفقه، ويهديه، ويشرح صدره إلى الحق، والإنفاق عليه إذا كان محتاجًا، كل ذلك من أسباب هدايته. أما غير الوالدين إذا لم يقبل الحق؛ فإنه يهجر، يستحق الهجر، لا تجاب دعوته إلى عرس، ولا غيره، ولا يدعى إلى وليمة، ولا يصافح، ولا يسلم عليه، بل يهجر حتى يتوب، وينبغي أن يرفع أمره إلى ولي الأمر إذا كان في بلاد إسلامية، يرفع أمره إلى ولي الأمر حتى يستتاب، فإن تاب وإلا وجب قتله عند جمهور أهل العلم.","link":"https://binbaz.org.sa/fatwas/11853/هل-يجوز-تقبيل-راس-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47909.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":13607,"question":"هذا سائل للبرنامج إسماعيل سوداني يعمل بالمملكة يقول: هل تارك الصلاة يعيد ما عليه، تارك للصلاة، ثم تاب، هل يقضي ما ترك من الصلوات؟","title":"هل تارك الصلاة يقضي ما ترك من الصلوات؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالتارك للصلاة عامدًا الصواب أنه لا إعادة عليه، وعليه التوبة؛ لأنه يكفر بذلك، والكافر يكفيه الإسلام والتوبة، فمن كفر فلا يعيد ما مضى من صلاة، ولا رمضان، ولا غير ذلك، وعليه العمل من جديد، هذا هو الواجب على من ارتد عن دينه، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال تعالى: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ [المائدة:5]. فالواجب عليه التوبة إلى الله، والرجوع إليه، والإنابة إليه، والعناية بالصلاة، والمحافظة عليها مستقبلًا، وليس عليه قضاء ما مضى؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه؛ ولقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر أخرجه الإمام أحمد، وأهل السنن بإسناد صحيح، وقوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة والأدلة في هذا كثيرة. فالواجب على كل مسلم، وعلى كل مسلمة العناية بالصلاة، والمحافظة عليها في أوقاتها، هذا هو الواجب على جميع المسلمين رجالًا ونساء، الواجب العناية بالصلاة، والمحافظة عليها في الوقت؛ لقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] يعني: العصر. وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238]؛ ولقوله -جل وعلا-: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]؛ ولقوله -عليه الصلاة والسلام-: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45]؛ ولما تقدم من الأحاديث. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11946/هل-تارك-الصلاة-يقضي-ما-ترك-من-الصلوات ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52801.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":13733,"question":"في ثاني أسئلة هذا السائل من الدمام يقول: ما حكم التعامل مع شخص تارك للصلاة، ومتهاون في أداء العبادات؟ جزاكم الله خيرًا.","title":"حكم التعامل مع تارك الصلاة","answer":"الجواب: يكره التعامل مع هذا، ومع بقية الكفرة؛ لأن فيه خطر، قد يجرك إلى ما هو عليه من الباطل، فلا ينبغي التعاون معه، بل ينبغي هجره؛ حتى يتوب إلى الله، وإن كان كافرًا أصليًا؛ ينبغي إبعاده، وعدم صحبته؛ حتى لا يجرك إلى الباطل، وإن كان مسلمًا، ثم ارتد فهو أقبح وأقبح، يجب الحذر منه، لكن مع دعوته إلى الله مع نصيحته؛ لعله يرجع، لعله يتوب إلى الله، لعله يرجع إلى الإسلام، وإن كان كافرًا أصليًا؛ لعله يتوب، لعله يقبل الحق، فإذا نصحته لله، ورجع؛ فالحمد لله، وإلا فاتركه، والتمس الطيب من المسلمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12104/حكم-التعامل-مع-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54518.mp3","categories":["حكم الصلاة وأهميتها","نصائح وتوجيهات"]},{"id":13735,"question":"امتدادًا للسؤال السابق سماحة الشيخ هذا السائل يقول في سؤاله -وهو قريب من السؤال السابق-: كثير من أولياء الأمور هداهم الله لا يحرصون على حث أولادهم على أداء الصلوات المفروضة، فهم يتساهلون كثيرًا معهم في ذلك، هل من كلمة سماحة الشيخ حول هذا الموضوع؟الشيخ: أعد.المقدم: يقول: كثير من أولياء الأمور -هداهم الله- لا يحرصون على حث أولادهم، وبناتهم على أداء الصلوات المفروضة، فهم يتساهلون في ذلك، فهل يأثمون في ذلك؟","title":"ما النصيحة في حث الأولاد على الصلاة؟","answer":"الجواب: نعم، الواجب على جميع المسلمين العناية بالصلاة، وتوجيه أولادهم إليها، الواجب على الآباء والأمهات والإخوة العناية بهذا الأمر، الأب يوجه أولاده، والأم كذلك، والأخ الكبير والعم.. كلهم يتعاونون على البر والتقوى؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول -جل وعلا-: وَالْعَصْرِ [العصر:1] إِنَّ الإِنسَانَ لَفِي خُسْرٍ [العصر:2]، إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:3] إذا تساهلوا يأثمون. الله -جل وعلا- يقول: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132] ويقول : يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6]، ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ [آل عمران:110].  فالواجب على الآباء والأمهات والإخوة وغيرهم التعاون في هذا، وأن يستقيموا على الحق، وأن يلزموا أولادهم بالصلاة، والمحافظة عليها، وأن يؤدبوا من تخلف. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12106/ما-النصيحة-في-حث-الاولاد-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54519.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":13942,"question":"من العراق محافظة نينوى هذه رسالة بعث بها المستمع محسن مرفوء أحمد لأخينا سبعة أسئلة يسأل في سؤاله الأول ويقول: إن أكثر الشباب عندما أنصحهم بالصلاة يقولون: لا نستطيع أن نصلي؛ لأننا ننظر إلى النساء وخاصة المتبرجات، فهل النظر يمنع الصلاة؟ أو يبطلها؟ جزاكم الله خيرًا.","title":"حكم الامتناع عن الصلاة بسبب المعاصي","answer":"الجواب: هذا عذر باطل، الواجب عليهم أن يصلوا مع المسلمين وأن يحافظوا على ما أوجب الله عليهم من الصلاة ومن غض البصر، والصلاة في الجماعة في المساجد فريضة، يقول ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وهي عمود الإسلام يجب على المسلم أن يؤديها إذا كان مكلفًا يجب عليه أن يؤديها، وتركها كفر بالله وضلال، وليس رؤية النساء في الطريق أو في المسجد إذا كن يصلين في المسجد ليس هذا عذرًا في ترك الصلاة أو ترك الجماعة، بل هذا غلط ومنكر، واعتذار بمنكر عن منكر، وهو ترك الصلاة. نسأل الله العافية. والواجب على المسلم غض البصر أن يتقي الله ويغض بصره عن النساء في الأسواق وفي كل مكان، وليس عذرًا له أن يذهب إلى الصلاة أن يصادفه في الطريق نساء، إذا صادف في الطريق نساء يغض بصره ويجاهد نفسه، قال الله : قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30].\nفالمسلم يغض بصره ويتقي الله ويحفظ فرجه ويؤدي ما أوجب الله عليه من الصلاة في مساجد الله مع المسلمين يخاف الله ويرجوه، قال تعالى: فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ [النور:36]، وقال عليه الصلاة والسلام: من سمع النداء فلم يأت فلا صلاة له إلا من عذر وقال في شأن الصلاة وعظمتها: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه رحمه الله، في أحاديث أخرى دالة على عظم شأنها، ويقول ﷺ: رأس الأمر الإسلام وعموده الصلاة وقد هم عليه الصلاة والسلام أن يحرق على المتخلفين بيوتهم، المتخلفين عن الصلاة في الجماعة.\nفالواجب على كل مسلم وعلى كل مسلمة أن يتقي الله وأن يحافظ على الصلاة في أوقاتها، وأن يحذر التخلف عنها فإن التخلف عنها من صفات أهل النفاق ومن صفات الكفرة، ومن أسباب دخول النار، قال الله تعالى في كتابه العظيم عن الكفار: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:43]، فأجابوا بأنهم دخلوا النار لأنهم لم يكونوا من المصلين، نسأل الله العافية. فالمؤمن يتقي الله في كل شيء فيغض البصر ويحفظ الفرج ويحفظ الجوارح مما حرم الله ويؤدي ما أوجب الله من الصلاة والزكاة وبر الوالدين وصلة الرحم وغير ذلك، يجمع بين هذا وهذا، هذه الدار دار العمل دار التكليف دار الابتلاء والامتحان، فالواجب على كل مسلم وعلى كل مسلمة أن يتقي الله وأن يحافظ على ما أوجب الله وأن يتباعد عن محارم الله وأن يقف عند حدود الله يرجو ثواب الله ويخشى عقاب الله، ولهذا خلق، يقول سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]. وهذه هي العبادة؛ الصلاة الزكاة الصيام الحج الجهاد الأمر بالمعروف والنهي عن المنكر الدعوة إلى الله بر الوالدين صلة الرحم.. إلى غير هذا مما شرعه الله، وهكذا ترك المحارم التي حرم الله على عباده تركها طاعة لله وتعظيمًا له من أفضل القربات. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12353/حكم-الامتناع-عن-الصلاة-بسبب-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60404.mp3","categories":["حكم الصلاة وأهميتها","نصائح وتوجيهات"]},{"id":13968,"question":"يسأل أخونا سؤال ويقول: هل تارك الصلاة يكفر كفرًا يخرجه من ملة الإسلام؟ أم لا؟","title":"حكم تارك الصلاة كسلًا وتعمدًا","answer":"الجواب: تارك الصلاة على حالين:\nإحداهما: أن يترك الصلاة مع جحد الوجوب، يرى أنها غير واجبة عليه، وهو مكلف، هذا يكون كافرًا نعوذ بالله، لأن: من جحد وجوبها؛ كفر بالإجماع بإجماع المسلمين، وهكذا من جحد وجوب الزكاة أو جحد وجوب صوم رمضان على المكلفين، أو جحد وجوب الحج مع الاستطاعة، أو جحد تحريم الزنا، وقال: إنه حلال، أو جحد تحريم الخمر وقال: إنه حلال، أو جحد تحريم الربا وقال: إنه حلال؛ كل هؤلاء يكفرون نعوذ بالله بإجماع المسلمين.\nأما من تركها تهاونًا وكسلًا وهو يعلم أنها واجبة؛ فهذا فيه خلاف بين أهل العلم، منهم من كفره كفرًا أكبر، وقال: إنه يخرج من الإسلام ويكون مرتدًا، كمن جحد وجوبها، لا يغسل ولا يصلى عليه إذا مات، ولا يدفن مع المسلمين، ولا يرثه المسلمون من الأقارب؛ لقوله ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة، رواه مسلم، وهذا صريح منه ﷺ في تكفيره يقول: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه، والكفر والشرك إذا أطلق بالتعريف؛ فهو كفر أكبر وشرك أكبر، وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة ، مع أحاديث أخرى جاءت في الباب.\nوقال آخرون من أهل العلم: إنه لا يكفر بذلك كفر أكبر، بل كفر أصغر؛ لأنه موحد يشهد أن لا إله إلا الله وأن محمدًا رسول الله، ويؤمن بأنها فريضة عليه، وجعلوها كالزكاة والصيام والحج، لا يكفر من تركها، وإنما هو عاصي، وأتى جريمة عظيمة، ولكنه لا يكفر بذلك.\nوالصواب: القول الأول؛ لأن الصلاة لها شأن عظيم، غير شأن الزكاة والصيام والحج، فهي أعظم من الصيام، وأعظم من الزكاة، وأعظم من الحج، وهي تلي الشهادتين، وهي عمود الإسلام، كما قال عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة، فلها شأن عظيم.\nومن ذلك: ما ثبت في الحديث عن عبد الله بن عمرو بن العاص رضي الله تعالى عنهما، في مسند أحمد بإسناد جيد، عن النبي ﷺ: أنه ذكر الصلاة يومًا بين أصحابه وقال: من حافظ عليها؛ كانت له نورًا وبرهانًا ونجاة يوم القيامة، ومن لم يحافظ عليها؛ لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون و هامان و قارون و أبي بن خلف.\nقالوا: وهذا يدل على أن الحشر مع هؤلاء يكون كفرًا بالله، يكون تاركها كافرًا بالله، فإن حشره مع هؤلاء الكفرة -بل رءوس الكفرة- يدل على أنه قد كفر كفرًا أكبر. نسأل الله السلامة والعافية. نعم.","link":"https://binbaz.org.sa/fatwas/12385/حكم-تارك-الصلاة-كسلا-وتعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60509.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":14060,"question":"من المملكة الأردنية الهاشمية خريبة السوق هذه رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (م. س. ع) ، أختنا تقول في سؤال لها: إنني كنت في رمضان أفطر دائمًا، وعندما هداني الله، وأحسست بالإيمان لم أعد إلى ذلك، هل هنا أحاسب على جميع ما أفطرته قبل الهداية والتوبة إلى الله؟ أم علي القضاء لجميع ما أفطرت؟ مع العلم أنني لا أحصي ما أفطرت، بماذا تنصحونني أن أفعل؟ كذلك الصلاة لم أكن أصلي من قبل، والحمد لله الآن مداومة عليها وملتزمة بها، أرجو منكم التوضيح. جزاكم الله خيرًا.","title":"حكم قضاء الصلاة والصيام على من تركهما","answer":"الجواب: الواجب عليك التوبة، وقد من الله عليك بذلك والحمد لله، فعليك أن تلزمي التوبة، وأن تكثري من الاستغفار والعمل الصالح وصلاة النافلة، والصدقات إذا استطعت، كثرة التسبيح والتهليل والتحميد والتكبير والاستغفار، كل ذلك من أسباب كمال التوبة، ومن أسباب المغفرة، وليس عليك قضاء الصلاة ولا الصوم؛ لأن ترك الصلاة كفر، والكافر إذا أسلم ليس عليه قضاء، وقد قال عليه الصلاة والسلام في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة؛ فمن تركها فقد كفر، خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة بن الحصيب رضي الله تعالى عنه، وقال عليه الصلاة والسلام أيضًا: بين الرجل وبين الكفر والشرك ترك الصلاة، خرجه الإمام مسلم في صحيحه عن جابر بن عبد الله رضي الله تعالى عنهما، في أحاديث أخرى تدل على كفر تارك الصلاة.\nوقد ذكر عبد الله بن شقيق العقيلي التابعي الجليل عن الصحابة  -أصحاب النبي ﷺ- أنهم كانوا يرون أن ترك الصلاة كفر، وقال: كانوا لا يرون شيئًا من الأعمال تركه كفر إلا الصلاة، فالصلاة أمرها عظيم وهي عمود الإسلام، من حافظ عليها فقد حفظ دينه، ومن ضيعها فقد ضيع دينه.  فأنت إذا من الله عليك بالتوبة من ترك الصلاة وترك الصوم؛ فليس عليك قضاء والحمد لله، وإنما عليك التوبة الصادقة والاستقامة عليها، وحمد الله على ذلك وشكره على ذلك، والاستكثار من أعمال الخير: من صدقات -ولو بالقليل- من الاستغفار الكثير، التسبيح والتهليل والتحميد والتكبير، وغير ذلك من وجوه الخير: كصوم التطوع، وكثرة الدعاء والضراعة إلى الله أن يتقبل منك وأن يعفو عنك.  أما من ترك الصوم، ولكنه يصلي، مسلم يصلي لكن تساهل في الصيام؛ فإنه يقضي، يقضي ما عليه من الصيام؛ لأن ترك الصيام ليس ردة عن الإسلام، ولكنه معصية عظيمة، فمن ترك الصوم شهرًا أو أكثر أو أقل؛ فعليه القضاء؛ مادام مسلمًا يصلي، وليس معه ما يوجب ردته وكفره، فإن عليه القضاء؛ لأن الرسول ﷺ أمر الحيض بقضاء الصوم فعليهن القضاء، وهكذا من تعمدت ترك الصوم بغير عذر، ولكنها تصلي؛ فإن عليها القضاء أيضًا، وهكذا الرجل الذي تساهل في الصيام وهو مسلم يصلي؛ فإنه يقضي أيضًا ويتحرى الأيام التي تركها إذا كان لا يعلمها، يتحرى، ويعمل بظنه في ذلك ويقضي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12485/حكم-قضاء-الصلاة-والصيام-على-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60805.mp3","categories":["قضاء الصيام","قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":14082,"question":"شخص يصلي وينقطع مرارًا عنها وهذا حاله، ما هي نصيحتكم له؟","title":"ما النصيحة لمن يصلي أحيانا ويترك أحيانًا؟","answer":"الجواب: الواجب على كل مسلم ومسلمة تقوى الله في كل شيء، والصلاة عمود الإسلام وهي أعظم الفرائض وأهم الفرائض بعد الشهادتين، فالواجب على كل مسلم وعلى كل مسلمة العناية بالصلاة والمحافظة عليها كما قال الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى[البقرة:238]، وقال تعالى: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ[البقرة:43]، وقال سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ[النور:56]، والصلاة أهم عمل وأعظم عمل بعد الشهادتين، من حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع، والذي يفعلها تارة ويضيعها تارة كافر في أصح قولي العلماء -نسأل الله العافية- ولو ما جحد وجوبها، ولو لم يجحد وجوبها؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر أخرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة  ابن الحصيب، ولقوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، ولأحاديث أخرى جاءت في الباب. فالواجب على المسلمين ذكورًا وإناثًا الحذر من التهاون بالصلاة والتساهل بها، والواجب المحافظة عليها في الوقت والعناية بها والطمأنينة والخشوع حتى تؤدى كما أمر الله.\nوعلى الرجل أن يحافظ عليها في الجماعة في مساجد الله مع إخوانه المسلمين، وأن يحذر من التشبه بالمنافقين الذين لا يؤدونها في الصلاة إلا رياء.. لا يؤدونها في الجماعة إلا رياءً، وإذا غابوا عن الناس تساهلوا بها وتركوها، يقول الله سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا  ۝  مُذَبْذَبِينَ بَيْنَ ذَلِكَ لا إِلَى هَؤُلاءِ وَلا إِلَى هَؤُلاءِ[النساء:142-143] أي: ليسوا مع المسلمين حقًا ولا مع الكفار حقًا، بل هكذا وهكذا مترددون في شكهم وريبهم وكفرهم وضلالهم، ويقول سبحانه: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ وَلَنْ تَجِدَ لَهُمْ نَصِيرًا[النساء:145] لكفرهم ونفاقهم وشكهم وريبهم وإبطانهم الكفر، فالوجب الحذر من صفاتهم والحذر من أخلاقهم الذميمة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12516/ما-النصيحة-لمن-يصلي-احيانا-ويترك-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61404.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":14094,"question":"رسالة وصلت إلى البرنامج من الرياض وباعثها المستمع (م. عبد الله)، أخونا يقول: إنني تزوجت امرأة، وقد رزقني الله منها بولد، وأنا أفكر في طلاقها من ثاني أيام العرس، سبب ذلك أنني لم أحضر لخطبتها، والسبب الثاني: أنها كانت لا تصلي قبل الزواج، وبعد الزواج أمرتها تصلي فصلت، وعندما سافرت للعمل؛ قطعت الصلاة. سؤالي: هل إذا طلقتها أكون آثم؟ وهل إذا صبرت عليها أكون مأجور؟ وهل هذا ابتلاء من الله  لعباده بهذا النوع من النساء؟ نرجو أن تفيدونا حول هذه القضايا. جزاكم الله خيرًا.","title":"حكم طلاق الرجل للمرأة التي لا تصلي","answer":"الجواب: إذا كانت لا تصلي؛ فالنكاح غير صحيح، مادمت تصلي والحمد لله أنت، فهي لتركها الصلاة تعتبر كافرة في أصح قولي العلماء، ولو كانت تقر بالوجوب.\nفالواجب تجديد العقد إذا تابت إلى الله وأنابت إليه توبة صادقة، وأنت ترغب فيها، يجدد العقد، أما الآن فالواجب عليك فراقها، ما دامت تصلي إذا حضرت وتترك الصلاة إذا غبت؛ فهذه لا خير فيها، هذه فاسدة، عقيدتها فاسدة، وخوفها من الله معدوم أو ضعيف، تراعيك ولا تراعي حق الله! فهذه ينبغي فراقها وإبعادها، وأنت مأجور، بل واجب عليك طلاقها وإبعادها؛ لفساد دينها، بسبب تضييعها الصلاة. وقد ذهب جمع من أهل العلم من أئمة الحديث وغيرهم من المحققين إلى كفر تارك الصلاة كفرًا أكبر، ولو أقر بوجوبها، مع أن إقراره بوجوبها في الغالب لا يكون صحيحًا بل مجاملة، لو كان يقر بوجوبها إقرارًا صحيحًا لما تركها؛ لأن إقراره بالوجوب يدفعه إلى أن يصلي، ولكن عدم إقراره بالوجوب أو ضعف عقيدته في ذلك جرأته على تركها -نسأل الله العافية- وهكذا المرأة.\nفالواجب عليك وعلى أمثالك تطليق المرأة التي لا تصلي وإبعادها، ومتى تابت توبة صادقة وشهد لها بالخير؛ أمكنك أن تزوجها من جديد بعقد جديد، وهكذا المرأة التي عند زوج لا يصلي؛ تبتعد عنه، وتذهب إلى أهلها، ولا تبقى معه؛ لأنه متى ترك الصلاة كفر، وهذه مصيبة عظيمة اليوم وقعت في الناس.\nفالواجب على الرجل أن يبعد المرأة التي لا تصلي، وعلى المرأة أن تبتعد عن الرجل الذي لا يصلي، وأن تذهب إلى أهلها، حتى ولو كان معها أولاد، رزقهم على الله، وهي أحق بأولادها من هذا الزوج الذي لا يصلي، وعلى القاضي أن يجعل أولادها عندها، ويلزمه بنفقتهم، حتى يتوب إلى الله ويرجع إلى الله، ثم بعد ذلك يجدد العقد، إذا كان بعد خروجها من العدة، وإن كان تاب في العدة؛ فهي زوجته إذا كان حين الزواج يصلي وهي تصلي، أما البقاء مع زوج لا يصلي أو مع زوجة لا تصلي؛ فهذا لا يجوز، نسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12523/حكم-طلاق-الرجل-للمراة-التي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61002.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","نصائح وتوجيهات"]},{"id":14099,"question":"أولى رسائل هذه الحلقة رسالة المستمع حسن عثمان حسن من الإقليم الشمالي في السودان، أخونا عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة يسأل ويقول: ما حكم من يصلي أحيانًا ويترك الصلاة أحيانًا؟ وجهونا ووجهوا الناس جزاكم الله خيرًا.","title":"حكم من يصلي أحيانًا ويدع أحيانًا","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالصلاة هي أعظم أركان الإسلام بعد الشهادتين، وهي عمود الإسلام، وقد نزل فيها من الآيات الكريمات الشيء الكثير، كما قال تعالى: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43]، حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238]، وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]، وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45]، إلى غير ذلك، مثل قوله سبحانه: فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا [مريم:59]، في آيات كثيرات. فمن تركها تهاون بها؛ فهو دليل على فساد دينه، وفساد عقيدته، وأنه ليس من الإسلام في شيء، ولو زعم أنه يقر بها وأنها واجبة، مادام لا يحافظ عليها، بل يدعها تارة ويصليها أخرى، أو يدعها بالكلية؛ فهذا كافر في أصح قولي العلماء، حتى يتوب إلى الله ويحافظ عليها.\nوالحجة في ذلك: ما ثبت عنه عليه الصلاة والسلام أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة، خرجه الإمام مسلم في صحيحه، ولم يقل ﷺ: (إذا جحد وجوبها)، وهو أفصح الناس عليه الصلاة والسلام، وأنصح الناس، لو كان جحد الوجوب شرطًا لبينه، فهو المبلغ عن الله، وهو الدال على الحق عليه الصلاة والسلام، ومع هذا يقول: بين الرجل وبين الكفر والشرك ترك الصلاة. والمرأة مثل الرجل سواء، ولهذا في الحديث الثاني يقول عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، خرجه الإمام أحمد و أبو داود و الترمذي و النسائي و ابن ماجه بإسناد صحيح عن بريدة بن الحصيب ، وهذا عام يعم الرجال والنساء، ويعم من جحد الوجوب أو أقر بالوجوب، وأي فائدة في إقراره بالوجوب إذا كان لا يصلي؟ ويش ينفع به هذا الإقرار إذا كان ضيعها وأهملها، واتصف بصفات المعرضين عنها؟ ولهذا يقول ﷺ فيما تقدم: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر.\nفالواجب على كل مسلم وعلى كل مسلمة: العناية بالصلاة، والمحافظة عليها، والاستقامة عليها في جميع الأوقات؛ خوفًا من الله وتعظيمًا له وطلبًا لمرضاته، وحذرًا من عقابه ، وابتعادًا عن مشابهة المشركين التاركين لها، وعلى الرجل مع ذلك أن يحافظ عليها في المساجد في بيوت الله مع إخوانه المسلمين، لا يصلي في بيته، الصلاة في البيت فيه مشابهة لأهل النفاق، يقول النبي ﷺ: أثقل الصلاة على المنافقين: صلاة العشاء وصلاة الفجر، ولو يعلمون ما فيهما لأتوهما ولو حبوا، يعني: لأتوهما في المساجد.\nويقول عليه الصلاة والسلام: لقد هممت أن آمر بالصلاة فتقام، ثم آمر رجلًا فيصلي بالناس، ثم أنطلق برجال معهم حزم من حطب إلى رجال لا يشهدون الصلاة؛ فأحرق عليهم بيوتهم، وما ذاك إلا لعظم الخطر وعظم الجريمة في تركهم الصلاة مع الجماعة في مساجد الله، وقال عليه الصلاة والسلام: من سمع النداء فلم يأت، فلا صلاة له إلا من عذر، وهذا وعيد شديد، وجاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم. قال:  فأجب!، رواه مسلم في صحيحه، وفي رواية أخرى خارج مسلم يقول ﷺ: لا أجد لك رخصة، فإذا كان رجل أعمى ليس له قائد يلائمه، ومع هذا يقول له النبي ﷺ: أجب، ويقول: لا أجد لك رخصة، فكيف بحال الرجل البصير الصحيح، فالأمر عظيم.\nفالواجب على الرجال أن يتقوا الله، وأن يحضروا الصلاة مع المسلمين في مساجد الله، فهي شعيرة عظيمة يقيمها مع إخوانه في بيوت الله ...... هذا العلم العظيم من أعلام الإسلام، ويجتمع بإخوانه ويشاهدهم، ويتعاون معهم على الخير، ويشجع الكسول، فإنه إذا صلى هذا في المسجد وهذا في المسجد وهذا؛ تشجع الناس، وتعاونوا على الخير، وأدوا هذه الفريضة العظيمة في بيوت الله، وإذا كسل هذا وكسل هذا؛ تابعه غيره من أولاد وإخوة وخدم وغير ذلك؛ فيكون عليه مثل آثامهم في اقتدائهم به؛ لأنه قد دعاهم بالفعل إلى ترك هذه الفريضة في المساجد.\nفالواجب على كل إنسان أن يتقي الله وأن يراقب الله، وأن يصلي في المسجد مع المسلمين، وإن كان كبيرًا في نفسه، وإن كان تاجرًا، وإن كان أميرًا، فأمر الله فوق الجميع، الواجب على كل إنسان من المؤمنين أن يتقي الله، وأن يراقب الله، وأن يؤدي هذه الصلاة في بيوت الله مع إخوانه، وأن يقوم على أولاده وخدمه حتى يصلوا معه في المساجد، هكذا المسلم يتقي الله ويوصي بتقوى الله، ويلزم من تحت يده بتقوى الله. وهكذا المرأة تعتني بذلك، تصلي الصلاة في وقتها، وتعتني ببناتها وخادماتها وأخواتها، تقوم عليهن، وتلزمهن بما أوجب الله عليهن من الصلاة في وقتها. ولعظم شأنها ولكونها عمود الإسلام؛ بين النبي ﷺ أنه من تركها كفر، حتى ولو أقر بالوجوب، هذا هو الصحيح الذي عليه أئمة الحديث المعروفون، وقد ذكره التابعي الجليل عبد الله بن شقيق العقيلي عن الصحابة قال: كانوا لا يرون شيئًا تركه كفر من الأعمال غير الصلاة، يعني: لعظم شأنها، نسأل الله لإخواننا المسلمين ولنا جميعًا الهداية والتوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12521/حكم-من-يصلي-احيانا-ويدع-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61001.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":14102,"question":"رسالة وصلت إلى البرنامج من الجمهورية التونسية وباعثها مستمع من هناك، يقول (ص. ح) أخونا صدر رسالته بثناء وتقدير على هذا البرنامج وعلى المشاركين فيه، وأخذ في أسئلته ليسأل ويقول: هل يجوز الأكل من ذبائح تارك الصلاة عمدًا؟ علمًا أنه إذا أخبر بذلك احتج بأنه ينطق بالشهادة، كيف العمل إذا لم يوجد أي جزار يصلي؟","title":"هل تحل ذبيحة تارك الصلاة؟","answer":"الجواب: الذي لا يصلي لا تؤكل ذبيحته، هذا هو الصواب، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقوله ﷺ: رأس الأمر الإسلام وعموده الصلاة شيء ترك عموده هل يستقيم؟ وهل يبقى؟ متى ترك العمود سقط الفسطاط، فالذي لا يصلي لا دين له ولا تؤكل ذبيحته، وإذا كنت في بلد ليس فيها جزار مسلم فاذبح لنفسك واستعمل يدك فيما ينفعك أو التمس جزارًا مسلمًا ولو في بيتك حتى يذبح لك، وهذا بحمد الله ميسر، وليس لك أن تتساهل في الأمر، وعليك أن تنصح هذا الرجل وأن يتقي الله وأن يصلي. وقوله: إنه يكتفى بالشهادتين هذا غلط، الشهادتان لا بد من حقهما معهما، يقول النبي ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأني رسول الله ويقيموا الصلاة ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله متفق على صحته، فذكر الصلاة والزكاة مع الشهادتين، وفي اللفظ الآخر قال: أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله فإذا قالوها عصموا مني دماءهم وأموالهم إلا بحقها وحسابهم على الله فالصلاة من حقها والزكاة من حقها.\nفالواجب على المؤمن أن يتقي الله، والواجب على كل من ينتسب للإسلام أن يتقي الله وأن يصلي الصلوات الخمس وأن يحافظ عليها، هي عمود الإسلام وهي الركن الأعظم من أركان الإسلام بعد الشهاتين فمن ضيعها ضيع دينه ومن تركها خرج من دينه نسأل الله العافية، هذا هو الحق والصواب. وقال بعض أهل العلم: إنه لا يكون كافرًا كفرًا أكبر بل يكون كفره كفرًا أصغر ويكون عاصيًا معصية عظيمة أعظم من الزنا وأعظم من السرقة وأعظم من شرب الخمر ولكنه لا يكون كافرًا كفرًا أكبر، هكذا قال جمع من أهل العلم، ولكن الصواب ما دل عليه قول الرسول ﷺ أن مثل هذا يكون كافر كفرًا أكبر؛ لأنه ضيع عمود الإسلام وهو الصلاة، فلا ينبغي التساهل في هذا الأمر، وقال عبد الله بن شقيق العقيلي التابعي الجليل : لم يكن أصحاب النبي ﷺ يرون شيئًا تركه كفر إلا الصلاة، فذكر إجماع الصحابة على أن تاركها كافر، نسأل الله العافية.\nفالواجب الحذر، والواجب المحافظة على هذه الفريضة العظيمة وعدم التساهل مع من تركها، فلا يؤكل طعامه ولا تؤكل ذبيحته ولا يدعى للوليمة، ولا تجاب دعوته بل يهجر حتى يتوب إلى الله وحتى يصلي، نسأل الله الهداية للجميع.\nالمقدم: جزاكم الله خيرًا، شيخ عبد العزيز! لا شك أنكم تفضلتم بإبداء بعض ما يجب أن يكون عليه المسلمون تجاه تارك الصلاة وهو ذلكم الذي يدعي الإسلام، هل من زيادة على هذا يا شيخ عبد العزيز ؟\nالشيخ: لعل هذا يكفي، يكفينا أنه كافر، نسأل الله العافية، بنص الرسول ﷺ، وهل بعد الكفر ذنب؟! ما بعد الكفر شيء، أعظم الذنوب الكفر بالله ، نسأل الله العافية.\nالمقدم: اللهم آمين. لكن ماذا على من يعرفه في هذه الصفة؟\nالشيخ: عليه أن ينصح له وعليه أن يهجره إذا لم يقبل النصيحة، فلا يجيب دعوته لو دعاه، ولا يدعوه إلى وليمة، ولا يسلم عليه إذا لقيه، ويحذر الناس من شره حتى يتوب إلى الله. نعم.","link":"https://binbaz.org.sa/fatwas/12535/هل-تحل-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61409.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":14117,"question":"أخونا له سؤال آخر مفهومه: أنه يعلم أن طاعة الوالدين واجبة، فيقول مثلًا: إن والده خطب له إحدى الفتيات لكنه علم أنها لا تصلي، فإذا ما رفض هذه المخطوبة هل يكون هذا من العقوق أو لا يا شيخ عبد العزيز؟","title":"حكم مخالفة الوالدين في خطبة فتاة لا تصلي؟","answer":"الجواب: ليس هذا من العقوق ولا يجوز نكاح امرأة لا تصلي؛ لأن ترك الصلاة كفر أكبر على الصحيح، لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ولأنها عمود الإسلام، وذهب جمع من أهل العلم إلى أنه كفر أصغر، وإلى أنها معصية، وأنها لا تكفر بذلك، ولا يكفر الرجل بذلك إذا كان يقر بالوجوب ويعلم أنها واجبة، وبكل حال فالتي لا تصلي لا تنكح حتى ولو قلنا بعدم كفرها، لا ينبغي أن تنكح ولا يطاع الوالد فيها ولا الوالدة ولا غيرهما، يقول النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. مع أن الصواب أن من ترك الصلاة يعتبر كافرًا وإن كان تركها تهاونًا، أما إذا جحد وجوبها فهذا كافر عند جميع أهل العلم نسأل الله العافية، وهكذا لو جحد وجوب الزكاة أو وجوب الصيام أو جحد وجوب الحج مع الاستطاعة يكون كافرًا عند أهل العلم. فينبغي للمؤمن أن يتحرى في الزواج المرأة الصالحة الطيبة كما قال النبي ﷺ في الحديث الصحيح: تنكح المرأة لأربع: لمالها ولجمالها ولحسبها ولدينها فاظفر بذات الدين تربت يداك، فالرجل يطلب المرأة الصالحة، وهكذا المرأة تطلب الرجل الصالح الطيب، لا تنكحي الذي لا يصلي أو يشرب الخمر أو .. تجتنبه، تلتمس الطيب، فهكذا الرجل يطلب المرأة الصالحة المعروفة بالدين والاستقامة والمحافظة على الصلاة حتى تستقيم العشرة بينهما على خير وهدى، وهكذا حتى تكون الذرية إن شاء الله كذلك صالحة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12561/حكم-مخالفة-الوالدين-في-خطبة-فتاة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61502.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار "]},{"id":14121,"question":"أخونا له سؤال آخر مفهومه: أنه يعلم أن طاعة الوالدين واجبة، فيقول مثلًا: إن والده خطب له إحدى الفتيات لكنه علم أنها لا تصلي، فإذا ما رفض هذه المخطوبة هل يكون هذا من العقوق أو لا يا شيخ عبد العزيز؟","title":"حكم مخالفة الوالدين في خطبة فتاة لا تصلي؟","answer":"الجواب: ليس هذا من العقوق ولا يجوز نكاح امرأة لا تصلي؛ لأن ترك الصلاة كفر أكبر على الصحيح، لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ولأنها عمود الإسلام، وذهب جمع من أهل العلم إلى أنه كفر أصغر، وإلى أنها معصية، وأنها لا تكفر بذلك، ولا يكفر الرجل بذلك إذا كان يقر بالوجوب ويعلم أنها واجبة، وبكل حال فالتي لا تصلي لا تنكح حتى ولو قلنا بعدم كفرها، لا ينبغي أن تنكح ولا يطاع الوالد فيها ولا الوالدة ولا غيرهما، يقول النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. مع أن الصواب أن من ترك الصلاة يعتبر كافرًا وإن كان تركها تهاونًا، أما إذا جحد وجوبها فهذا كافر عند جميع أهل العلم نسأل الله العافية، وهكذا لو جحد وجوب الزكاة أو وجوب الصيام أو جحد وجوب الحج مع الاستطاعة يكون كافرًا عند أهل العلم. فينبغي للمؤمن أن يتحرى في الزواج المرأة الصالحة الطيبة كما قال النبي ﷺ في الحديث الصحيح: تنكح المرأة لأربع: لمالها ولجمالها ولحسبها ولدينها فاظفر بذات الدين تربت يداك، فالرجل يطلب المرأة الصالحة، وهكذا المرأة تطلب الرجل الصالح الطيب، لا تنكحي الذي لا يصلي أو يشرب الخمر أو .. تجتنبه، تلتمس الطيب، فهكذا الرجل يطلب المرأة الصالحة المعروفة بالدين والاستقامة والمحافظة على الصلاة حتى تستقيم العشرة بينهما على خير وهدى، وهكذا حتى تكون الذرية إن شاء الله كذلك صالحة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12561/حكم-مخالفة-الوالدين-في-خطبة-فتاة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61502.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار "]},{"id":14145,"question":"السائلة من المدينة المنورة الحقيقة كتبت هذه الرسالة المطولة بأسلوبها الخاص ومختصرها سماحة الشيخ: تذكر بأنها امرأة متزوجة منذ تسع سنوات تقول: ولي من زوجي ولد واحد وزوجها لا يعمل دائمًا فكان يعمل في التجارة وخسر جميع ما يملك من أمواله وأموال الناس الشركاء، ثم عمل في شركة وتركها بعد ثلاثة شهور، وهو دائم الاستلاف، وأصبح مديون للناس بمائة وخمسين ألف ريال، وهو الآن لا يعمل، علمًا بأنني دائمًا أقف إلى جواره في كل أزماته، والآن مرضت هذه الزوجة ولا تطيق أن ترى هذا الزوج تقول بسبب تصرفاته وبسبب الديون التي تراكمت عليه وعدم الاستقرار العائلي، سؤالها سماحة الشيخ تقول: لو طلبت الطلاق من هذا الرجل هل أكون آثمة علمًا بأن أهلي يريدون أن يطلقوني منه؛ لأن زوجي باع جميع ما يخصني من منزل وأثاث وذهب، فهل طلبي للطلاق حرام أم حلال؟","title":"حكم طلب المرأة الطلاق من الزوج المديون","answer":"الجواب: إذا كان يقوم بما يجب من النفقة فلا يجوز الطلب، إذا كان لا يظلمك فيقوم بما تحتاجين إليه من النفقة ولو أنه مدين فليس لك طلب الطلاق، أما إذا كان يظلمك وتخافين على نفسك منه من ضربه أو أخذ بقية مالك، يطالبك بأخذ بقية مالك فلك طلب الطلاق.\nالمقصود إذا كان يضرك في دينك أو في مالك فلك طلب الطلاق، أما إذا كان لا، قد قام بحقك ولكن عليه ديون فلا يضره ذلك عليك السمع والطاعة والبقاء في حسابه والحذر من طلب الطلاق بغير حق.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12586/حكم-طلب-المراة-الطلاق-من-الزوج-المديون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54610.mp3","categories":["الطلاق","حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":14245,"question":"السائل الذي رمز لاسمه (س. ع. ع) ، الرياض، يقول: سماحة الشيخ! أنا شاب في العشرين من العمر ذهبت إلى الدراسة خارج المملكة، وقد مر علي شهر رمضان في إحدى السنوات الأولى في بعثتي ولم أصم ذلك الشهر للأسف من باب التفريط، وكذلك لم أكن أؤدي الصلوات في تلك السنة، ولكن بعدما رجعت تبت إلى الله والحمد لله، ماذا أفعل في هذا الشهر الذي لم أصمه، هل أقضيه متواصل أم متفرق؟ أم ماذا ترون سماحة الشيخ؟","title":"هل يقضي الصلاة والصيام من تاب من تركهما؟","answer":"الجواب: مادمت لا تصلي فالذي ما يصلي كافر، والتوبة تجب ما قبلها، فلا صوم ولا صلاة لا تقضي الصوم ولا الصلاة؛ لأن من ترك الصلاة كفر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، لكن لو قضيت الصيام خروجًا من خلاف من قال: إنه لا يكفر كفرًا أكبر إذا كان لا يجحد وجوبها فلا بأس، لكن الصواب أنه يكفر تارك الصلاة وإن لم يجحد وجوبها، والكافر يكفيه التوبة، قال الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، وقال جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا [الزمر:53]، فالتوبة تجب ما قبلها وليس عليك قضاء إذا كنت لا تصلي كما قلت في السؤال. نعم.\nالمقدم: وبالنسبة للصلوات التي تركها.\nالشيخ: لا يقضي الصوم ولا الصلاة التوبة تجب ما قبلها.\nالمقدم: طيب جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12701/هل-يقضي-الصلاة-والصيام-من-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53015.mp3","categories":["قضاء الصيام","قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":14318,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من إثيوبيا، باعث الرسالة مستمع من هناك يقول: سليمان بن حميد بن عبد السلام، أخونا سليمان يقول: سمعت بعضًا من الناس يقولون: إن من فاتته صلاة العصر يعزيه الناس بالتعزية المعروفة لأهل الميت، وبعضهم - أقصد من الناس - من قال: نعم. يعزى إذا فاتته الصلاة لكن هو في الصلوات كلها عام، وقالوا في هذه المسألة: موجود حديث يروى عن رسول الله ﷺ، هل ما ذكره أولئك صحيح؟ وما المقصود بهذه التعزية؟ جزاكم الله خيرًا.","title":"هل يشرع تعزية من فاتته صلاة العصر؟","answer":"الجواب: قد ثبت عن النبي ﷺ أنه قال: من فاتته صلاة العصر فكأنما وتر أهله وماله يعني: سلب أهله وماله، فالمعنى: أنها مصيبة عظيمة، ولكن لا أذكر الآن أن السلف كانوا يعتادون التعزية في ذلك، وثبت عنه أيضًا عليه الصلاة والسلام أنه قال: من ترك صلاة العصر حبط عمله.\nفالحاصل أن فوت الصلوات الخمس أو إحداها كل ذلك من المصائب العظيمة، فينبغي للمؤمن أن يحرص على المحافظة عليهن والاستقامة في ذلك، والحرص على ذلك بالمسابقة إليه حتى لا تقع هذه المصيبة العظيمة. أما كونه يشرع للمؤمن أن يعزي أخاه إذا علم أنه فاتته صلاة العصر أو غيرها من الصلوات فلا أعلم شيئًا ثابتًا في هذا عن النبي ﷺ ولا عن الصحابة سوى ما ذكرته، فقد صح عنه ﷺ أنه قال: من ترك صلاة العصر حبط عمله وصح عنه عليه الصلاة والسلام أنه قال: من فاتته صلاة العصر فكأنما سلب أهله وماله نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا المقصود من مثل هذا الحديث سماحة الشيخ؟\nالشيخ: التحذير والترهيب من التساهل بترك الصلاة أو فواتها بالجماعة، أو فوات وقتها، ولا حول ولا قوة إلا بالله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12793/هل-يشرع-تعزية-من-فاتته-صلاة-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61808.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":14324,"question":"هل الإنسان الذي لم يصل أبدًا في حياته ثم وفق إلى التلفظ بالشهادتين قبل وفاته، هل يصبح هذا مسلمًا ويعامل في الآخرة معاملة المسلمين ويحشر مع المسلمين؟","title":"حكم تلفُّظ تارك الصلاة بالشهادتين عند وفاته","answer":"الجواب: إذا كان أتى بها توبة ودخولًا في الإسلام يمحو الله بها ما مضى، إذا كان لا يقولها سابقًا ثم جاء بها تائبًا موحدًا مخلصًا لله عارفًا لمعناها، معناه: ترك الشرك وترك المعاصي والعزم على ترك الجميع، فهذا توبة معناه توبة يمحو الله ما سلف وأسلف ..... أسلف بالخير. أما إذا كان يقولها كالعادة ما تنفع؛ لأنه مات على الشرك، هو يقولها في حياته وعند وفاته، إذا كان يقولها وهو يعبد القبور ويستغيث بالأموات ويأتي المعاصي، لم يقلها عن توبة ولا عن رجوع؛ فهي مثل قوله لها في حياته وصحته، لا تؤثر شيئًا، فهو على كفره وضلاله، كالمنافقين يقولونها وهم على كفرهم ونفاقهم، وكعباد القبور اليوم يقولونها في المجالس وفي كل مكان وهم يعبدون أصحاب القبور، يستغيثون بهم وينذرون لهم ويذبحون لهم كعباد البدوي وعباد الحسين وعباد الشيخ عبد القادر وعباد غيرهم. نسأل الله العافية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12795/حكم-تلفظ-تارك-الصلاة-بالشهادتين-عند-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55009.mp3","categories":["حكم الصلاة وأهميتها","مسائل متفرقة في العقيدة"]},{"id":14325,"question":"كثر الترغيب في صلاة العصر شيخ: عبد العزيز لعل لكم توجيه؟","title":"ما سبب كثرة الترغيب في صلاة العصر؟","answer":"الجواب: الظاهر والله أعلم؛ لأنها أفضل الصلوات؛ لأنها الصلاة الوسطى وهي صلاة العصر، فلذا جاء فيها ما لم يجئ في غيرها، ولعل أيضًا من الأسباب أنها صلاة تأتي بعد إنهاك العمل للإنسان وتعب الإنسان، فقد يتساهل في عدم أدائها في وقتها أو في الجماعة، فكان من حكمة الله أن بيَّن عظم شأنها حتى لا يتساهل بها أحد، لا في جماعة ولا في وقتها، وهي ختام النهار، والأعمال بالخواتيم، فجاء فيها من الأحاديث ما لم يأت في غيرها، والحكم واحد، يجب على المؤمن أن يحافظ على الجميع، وأن يحرص على الجميع؛ لأنها كلها فرض على المؤمن، وكلها عمود الإسلام، فالواجب المحافظة، ولكن تخص صلاة العصر بمزيد عناية، كما قاله النبي عليه الصلاة والسلام، كما جاء في الحديث الآخر: أثقل الصلوات على المنافقين صلاة العشاء وصلاة الفجر، ولو يعلمون ما فيهما لأتوهما ولو حبوًا .\nفالمقصود أن المؤمن يجب عليه أن يحافظ على الجميع، وأن يتخذ الأسباب التي تعينه على ذلك، وأن يخص العصر والفجر والعشاء بمزيد عناية، حتى لا يشبه المنافقين وحتى لا تفوته صلاة العصر التي فيها الوعيد الشديد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12797/ما-سبب-كثرة-الترغيب-في-صلاة-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61809.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":14454,"question":"من الأردن المستمعة (ع. غ. ش) تقول عن نفسها: أنا امرأة مسلمة في الرابعة والعشرين من عمري، لم أكن أصوم ولم أكن أصلي، حتى بلغت العشرين، حينئذٍ بدأت أصوم رمضان، ولكني لم أقض الأيام التي كنت أفطرها بسبب العذر الشرعي، فكيف تنصحونني والحال ما ذكر؟الشيخ: أعد.المقدم: تقول: إنها امرأة مسلمة في الرابعة والعشرين من عمرها، لم تكن تصوم، ولم تكن تصلي، حتى بلغت العشرين وحينئذٍ بدأت تصوم وبدأت تصلي، لكنها لم تكن تقضي الأيام التي تفطرها بسبب العذر الشرعي، وترجو التوجيه، جزاكم الله خيرًا.","title":"ما حكم من بلغت العشرين وهي لا تصلي؟","answer":"الجواب: ليس عليك قضاء، وإنما عليك التوبة إلى الله؛ لأنك تركتيها عمدًا، وهذا كفر، نعوذ بالله من ذلك، فعليك التوبة مما فعلت من ترك الصلاة والصوم، وعليك أن تستقبلي الزمان بالتوبة إلى الله والصلاة والصوم في المستقبل. أما إذا كنت ما تعلمين أحكام الله، ولا تعرفين الصلاة ولا الصوم، فهذا إن صمت ما مضى فلا حرج، ولكن الأصل أنه لا شيء عليك، بل التوبة تكفي، الله يقول: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] وهذه الأمور ما تجهل، معروفة من الدين بالضرورة، فكون أهلك أو غير أهلك لم يشجعوك ولم ينبهوك هذا ما يمنع من علمك بالصلاة وأنت تشاهدين الناس يصلون. فالحاصل: أنه ليس عليك صلاة ولا صوم، التوبة كافية -إن شاء الله-، التوبة كافية، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12931/ما-حكم-من-بلغت-العشرين-وهي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48806.mp3","categories":["حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":14455,"question":"في سؤال طويل حول زوجها أيضًا تذكر أنه لا يصلي حتى الآن، وتسأل في النهاية: هل على المرأة المسلمة أن تنفصل عن الرجل الذي لا يصلي؟","title":"هل تنفصل المرأة عن الزوج الذي لا يصلي؟","answer":"الجواب: نعم عليها أن تنفصل؛ لأن ترك الصلاة ردة، كفر أكبر في أصح قولي العلماء، وقد تقدم قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة إذا ضيع الصلاة ويش بقي عنده، نسأل الله السلامة، من ضيعها ضاع، وكان عمر  يكتب إلى عماله ويقول: «إن أهم أمركم عندي الصلاة، فمن حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع».\nويقول : «لا حظ في الإسلام لمن ترك الصلاة» وقد جاء هذا المعنى مرفوعًا إلى النبي ﷺ: لا حظ في الإسلام لمن ترك الصلاة. فالحاصل: أنّ من ضيع الصلاة فلا دين له، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12932/هل-تنفصل-المراة-عن-الزوج-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48807.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":14487,"question":"الأخت: (أ. ح. ن. ر) من اليمن - إب، بعثت برسالة، وضمنتها هذا السؤال، تقول: إن زوجي لا يغتسل من الحدث الأكبر إلا بعد يوم أو يومين، وأحيانًا يجلس من العصر إلى اليوم الثاني صباحًا، وفي بعض الأوقات يذهب إلى عمله.الشيخ: أعد، نسأل الله العافية، أعد.المقدم: تقول: إن زوجي لا يغتسل من الحدث الأكبر إلا بعد يوم أو يومين، وأحيانًا يجلس من العصر إلى اليوم الثاني صباحًا، وفي بعض الأوقات يذهب إلى عمله ويعود في المساء، ثم يغتسل من الحدث بالرغم من توفر الماء والوقت للاغتسال وهو لا يصلي، وإني دائمًا أنصحه بالصلاة والاغتسال، ولكنه لا يستمع إلى كلامي، وهذا يعذبني كثيرًا، وأنا امرأة مصلية، وأعرف أمور ديني.","title":"حكم البقاء مع زوج لا يصلي ولا يغتسل من الجنابة","answer":"الجواب: هذا الرجل يظهر من حاله أنه ليس بمؤمن، ولا يعرف أحكام الدين، أو يعرفها ويعاندها، فلا يحل لك البقاء معه، هذا الرجل يعتبر كافرًا؛ لأنه ترك الصلاة عمدًا، ولم يبال بها، ولم يبال بغسل الجنابة، فهذا يعتبر كافرًا، وليس للمسلمة أن تبقى مع كافر، والله يقول : لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ[الممتحنة:10] ويقول -جل وعلا-: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا[البقرة:221] يعني: لا تزوجوهم حتى يؤمنوا، وترك الصلاة كفر أكبر في أصح قولي العلماء، وإن لم يجحد وجوبها، فإن جحد وجوبها صار كافرًا عند جميع العلماء. والذي يظهر من حال زوجك أنه مع تركه لها لا يؤمن بها، لو كان يؤمن بها لما فعل هذا الفعل القبيح؛ لأن الإيمان يدعوه إلى أن يحترم الصلاة، وأن يبادر إليها، وأن يغتسل من الجنابة، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة .\nوقال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في الصحيح من حديث جابر ، ولم يقل: إذا جحد وجوبها، أطلق، فدل ذلك على أنه يكفر، وإن لم يجحد الوجوب؛ ولما سئل ﷺ عن الأئمة الذين يتخلفون عن الدين، ويظلمون الناس، سألوه: هل يخرجون عليهم؟ قال: لا، إلا أن تروا كفرًا بواحًا، عندكم من الله فيه برهان فإنه أخبرهم ﷺ: أنه يأتي في آخر الزمان أمراء جورة يعرف منهم وينكر -من أعمالهم- فسألوه: هل يخرجون عليهم؟ هل يقاتلونهم؟ فقال: لا، ما أقاموا فيكم الصلاة، ما صلوا وفي اللفظ الآخر: إلا أن تروا كفرًا بواحًا، عندكم من الله فيه برهان فهذا يدل على أن من ترك الصلاة ولم يقمها فقد أتى كفرًا بواحًا، يستحل، يحل معه الخروج عليه من ولاة الأمر أهل الحل والعقد، حتى يزال عن الرئاسة والإمامة ويجعل مكانه من يقوم بالإمامة. فالحاصل: أنّ هذا الرجل الذي ذكرت صفاته كافر إذا صح ما قلت عنه، وليس لك البقاء معه، بل يجب أن تخرجي إلى أهلك، أو تبقي مع أولادك إن كان عندك أولاد، وتمتنعين منه، وترفعين أمره إلى الحاكم الشرعي، حتى يفرق بينك وبينه، وحتى يقام عليه حد الله. نسأل الله له الهداية، نسأل الله أن يرده إلى الهدى، نعم. المقدم: آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12971/حكم-البقاء-مع-زوج-لا-يصلي-ولا-يغتسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63207.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","مبطلات النكاح","قضايا المرأة"]},{"id":14496,"question":"يقول: أصلي -والحمد لله- في المسجد كل وقت، ما عدا صلاة الفجر، ومع كل صلاة أصلي وقتًا مثله مما فاتني صغيرًا، وسؤالي بالنسبة لصلاة العصر هل أصليها قبل الفرض أو بعده، وأعني تلك التي أقضيها؟","title":"حكم قضاء ما فات من الصلاة قبل البلوغ وبعده","answer":"الجواب: الواجب عليك أن تصلي الصلوات في أوقاتها مع المسلمين في مساجد الله، والفجر كذلك يجب أن تصلي مع المسلمين، ولا تتشبه بالمنافقين، يقول النبي ﷺ: أثقل الصلاة على المنافقين صلاة العشاء وصلاة الفجر والله يقول سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142] فلا يجوز التشبه بالمنافقين، لا في الفجر، ولا في غيرها، بل الواجب عليك أن تصلي مع الناس الفجر وغيره في الجماعة في المساجد. والذي مضى عليك من الصلوات إذا كنت تركت ذلك فالتوبة كافية، ليس عليك قضاء ما مضى، سواء كان ذلك قبل البلوغ، أي فإنه ليس عليك شيء، أو بعد البلوغ، ثم تاب الله عليك فالتوبة تجب ما قبلها، وليس عليك القضاء، عليك أن تستقبل أمرك بالتوبة النصوح، والعمل الصالح، وأداء الفرائض في المستقبل، وما تركت من الصلوات سابقًا فليس عليها قضاء في أصح قولي العلماء؛ لأن الكافر لا يقضي، يقول الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] وترك الصلاة كفر أكبر في أصح قولي العلماء؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح؛ ولقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر الصلاة عمود الإسلام، من تركها من الرجال والنساء كفر إذا كان عمدًا، أما إذا كان نسيانًا أو عن نوم، فإذا استيقظ أو ذكر يصلي، يقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك وليس لأحد أن يتأخر عنها عمدًا، سواء كانت الفجر أو غير الفجر، يجب على المؤمن أن يحافظ عليها، وهكذا المؤمنة، يجب على الجميع المحافظة على الصلاة في أوقاتها، والعناية بذلك، والحرص على أدائها في الوقت، الرجل يؤديها في الجماعة في مساجد الله، والمرأة تؤديها في البيت، فمن تعمد تركها من غير عذر شرعي، بل للتساهل فهو كافر في أصح قولي العلماء، وإن كان جحدًا لوجوبها كفر بإجماع المسلمين، نسأل الله العافية.\nوقال جماعة من أهل العلم: إنه لا يكفر إذا تركها تساهلًا لا جحدًا لوجوبها، ولكنه قد أتى كبيرة عظيمة أعظم من الزنا والسرقة، كونه يترك الصلاة عمدًا وإن كان غير جاحد لوجوبها، هو أتى منكرًا عظيمًا، سماه النبي ﷺ كفرًا، لكن الأكثرون على أنه كفر دون كفر، ولكن الأصح من قولي العلماء: أنه كفر أكبر، وهو المروي عن الصحابة  وأرضاهم أنه كفر أكبر. فالصلاة عمود الإسلام من أضاعها أضاع دينه، ومن حفظها حفظ دينه، لكن من تركها ثم هداه الله، وتاب الله عليه، عليه أن يستقبل أمره، وليس عليه قضاء ما فات، بل التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12967/حكم-قضاء-ما-فات-من-الصلاة-قبل-البلوغ-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48813.mp3","categories":["حكم الصلاة وأهميتها","صلاة الجماعة"]},{"id":14502,"question":"يقول: صدر جهلًا مني ترك الصلاة، فهل علي قضاؤها؟","title":"ما يجب على من ترك الصلاة جهلًا؟","answer":"الجواب:\n\nنعم عليك أن تقضي الصلاة إذا كنت جاهلًا في أول شبابك، ثم فهمت، عليك أن تقضيها، وتصلي ما تركت جهلًا، أما إذا كنت متعمدًا قصدك عدم المبالاة بالصلاة، فأنت كافر بهذا، وليس عليك قضاء إلا التوبة. \n\nأما إذا كان لها أسباب، الجهل له أسباب، مريض، أو شبه ذلك، ظننت أنه لا صلاة عليك، فتقضي، إذا بيّن لك، وعلمت تقضي ما فاتك، كالمريض الذي ظن أنه لا يصلي حتى يطيب، حتى يستطيع يصلي وهو واقف، هذا يصلي ما ترك إذا شفي، فإن لم يشف يصلي وهو على حاله، قائمًا، أو قاعدًا، أو على جنبه.\n\nوهكذا بعض الناس إذا ظن أنه إذا ما حصل الماء ما يصلي حتى يحصل الماء شبهة، هذا يصلي أيضًا يقضي ما فات؛ لأن تركه له شبهة، ما هو لقصد التعمد والمخالفة.\n\nفالحاصل: أنّ الإنسان إذا تركها عمدًا لتأويل وشبهة فهذا يقضي، أما إذا تركها عمدًا لقلة المبالاة، وعدم المبالاة بالصلاة، وعدم العناية بها، والزهد فيها، وعدم المبالاة فهذا عليه التوبة إلى الله فقط، فقد كفر، وعليه التوبة، وليس عليه قضاء في أصح قولي العلماء، نعم.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12988/ما-يجب-على-من-ترك-الصلاة-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48818.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":14535,"question":"رسالة وصلت إلى البرنامج من العراق، باعثتها إحدى الأخوات المستمعات تقول: (م. ن) في بداية رسالتها تقول: إني مواطنة مسلمة من القطر العراقي الشقيق، لا أزال غير محجبة، ولكن ملابسي محتشمة، وإني موظفة في إحدى المؤسسات، وأختلط بالرجال، زملاء لي في العمل ومواطنين لديهم مصالح تقتضي مقابلتهم في مؤسستنا.وإنني -والحمد لله- أؤدي فريضة الصلاة، وأصوم شهر رمضان منذ حوالي سبعة أشهر فقط، لم أكن في السابق من المصلين. أرجو إفادتي -حفظكم الله-: هل يصح عملي -أي الصلاة والصوم- بدون حجاب؟علمًا أني أنوي ارتداء الحجاب الإسلامي خلال فترة قريبة.","title":"حكم صلاة وصوم من لا ترتدي الحجاب","answer":"الجواب: الحمد لله الذي منَّ عليك بالتوبة، وقمت بالصلاة، هذه أعظم النعم؛ لأن ترك الصلاة كفر أكبر نسأل الله العافية، فنوصيك بالثبات على الحق، ولزوم ما أوجب الله عليك، وترك ما حرم الله عليك، ومن ذلك الحجاب، فإنه يجب على المرأة أن تحتجب عن الرجال، قال الله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] فالحجاب أطهر لقلبك وقلب الرجال، فنوصيك بلزوم الحجاب، والحذر من مخالطة الرجال، وأن يكون عملك مع النساء، أو في محل مستقل وحدك دون الرجال، ولا تختلطي بالرجال؛ فإن ذلك من أسباب الفتنة، وعليك التوبة مما مضى، ومن تاب تاب الله عليه، والتوبة الندم على الماضي، والإقلاع من الذنب، والعزم على عدم العود إليه عزمًا صادقًا، بنية الإخلاص لله، ومحبته وتعظيمه. وما فعلت من الأعمال الطيبة فهو صحيح من صلاة وصوم لا يبطله عدم الحجاب، عدم الحجاب لا يبطل الأعمال لكنه معصية، فعليك التوبة إلى الله من ذلك، والاستقامة على الحجاب في الطريق، وعند الرجال أينما كنت؛ ولهذا يقول : يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا[الأحزاب:59] ويقول سبحانه: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا[النور:31] وما ظهر منها هي الملابس الظاهرة كالعباءة والجلباب ونحو ذلك. وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ[النور:31] والجيب مخرج الرأس، والمعنى: تضرب بالجلباب على رأسها ووجهها وصدرها حتى لا يبين منها شيء عند الرجال، ثم قال مؤكدًا سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ[النور:31] والبعولة: الأزواج: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ ..[النور:31] الآية. فعليك أن تتقي الله في هذا الأمر، وأن تحذري التساهل في أمر الحجاب، رزقنا الله وإياك الاستقامة والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13030/حكم-صلاة-وصوم-من-لا-ترتدي-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63412.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","نكاح الكفار"]},{"id":14565,"question":"السائلة من جمهورية مصر العربية تقول: هل لنا أن نطالب الأبناء والبنات الذين لم يتجاوزوا الثانية عشرة إذا كانوا مصابين بالإرهاق أو التعب أو مصابين بأحد الجروح أو الكسور، هل لنا أن نوقظهم للصلاة، ونطلب منهم أن يقضوا هذه الصلاة؟","title":"هل يوقظ الأولاد للصلاة إذا كانوا مرضى؟","answer":"الجواب: نعم، يعلمون، ويوقظون للصلاة، ويصلون على حسب أحوالهم؛ لقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فيوقظ في وقت الصلاة، ويصلي على حسب حاله، إن استطاع قائمًا صلى قائمًا، وإن عجز صلى قاعدًا، وإن لم يستطع صلى على جنب، كما قال النبي ﷺ لـعمران بن حصين لما مرض: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هذا هو الواجب على الوالدين مع أولادهم تنفيذًا لأمر النبي -عليه الصلاة والسلام- على حسب الطاقة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ولو كان غير بالغ ما دام قد بلغ سبعًا فأكثر، فالذي بلغ السبع ودون العشر يؤمر أمرًا ولا يضرب.  أما إذا بلغ عشرًا فأكثر فإنه يؤمر ويضرب إذا تخلف ويصلي على حسب حاله إذا كان مريضًا، أو به جرح أو نحو ذلك يعلم ويوجه ويصلي على حسب حاله كالبالغ، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/13062/هل-يوقظ-الاولاد-للصلاة-اذا-كانوا-مرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55603.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":14578,"question":"سماحة الشيخ، هذا سائل لم يذكر الاسم في هذه الرسالة، ويقول: أريد من سماحة الشيخ الإجابة على هذا السؤال، يقول:قال رسول الله ﷺ فيما رواه الشيخان: إنكم سترون ربكم عيانًا كما ترون هذا القمر لا تضامون في رؤيته، فإن استطعتم أن لا تغلبوا على صلاة قبل طلوع الشمس وقبل غروبها فافعلوا والسؤال هو: لماذا قرن في هذا الحديث بين رؤية الله  وبين صلاة الفجر والعصر، هل المحافظة على هذه الصلاة في هذين الوقتين سبب لرؤية الله ؟وجهونا سماحة الشيخ.","title":"السر في اقتران رؤية الله بصلاتي الفجر والعصر","answer":"الجواب: رؤية الله سبحانه في الجنة ويوم القيامة حق يراه المؤمنون، وهو أعلى نعيم أهل الجنة، إذا كشف الحجاب عن وجهه ورأوه ما أعطوا شيئًا أحب إليهم من النظر إلى وجهه ، وقد أخبر -جل وعلا- أنهم يرونه يوم القيامة عيانًا، كما يرون الشمس صحوة ليس دونها سحاب، وكما يرون القمر ليلة البدر، لا يضامون في رؤيته، هذا حق عند أهل السنة والجماعة، يقول ﷺ: فإن استطعتم أن لا تغلبوا على صلاة قبل طلوع الشمس وقبل غروبها فافعلوا يعني: صلاة العصر وصلاة الفجر، ذكر أهل العلم أن السر في ذلك أن من حافظ عليهما يكون ممن ينظر إلى الله بكرة وعشيًا في الجنة، يعني في مقدار البكرة والعشي؛ لأن الجنة ليس فيها ليل كلها نهار مطرد، لكن في مقدار البكرة والعشي، كما قال تعالى: وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا [مريم:62] يعني: في مقدار البكرة والعشي في الدنيا، وهكذا في الرؤية في مقدار البكرة والعشي يعني: خواص أهل الجنة لهم رؤية ما بين البكرة والعشي، يعني رؤية كثيرة بسبب أعمالهم الطيبة، وإيمانهم الصادق.  ومن أسباب ذلك محافظتهم على صلاة العصر، وصلاة الصبح لها خصوصية هاتان الصلاتان، والمحافظة عليهما من دلائل قوة الإيمان وكمال الإيمان مع بقية الصلوات. فالواجب أن يحافظ على الجميع، ولكن يخص العصر والفجر بمزيد عناية؛ لأنها ضد ما عليه المنافقون، وضد ما عليه الكسالى، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.\nتساهل كثير من الناس فضيلة الشيخ بهذين الوقتين وهما العصر والفجر هل من نصيحة لهؤلاء؟ جزاكم الله خيرًا.\nالشيخ: نعم، الواجب على كل مؤمن ومؤمنة الحرص على المحافظة على الصلاة في وقتها جميع الصلوات الخمس، وأن يخص الفجر والعصر بمزيد عناية، فالفجر في الحقيقة كثير من الناس يتكاسل عنها، وينام حتى طلوع الشمس، وربما لا يقوم لها إلا إذا قام لعمله إن صلى، وهذه مصيبة عظيمة، ومنكر عظيم.  فالواجب أن يصلى في الوقت، وقد ذهب جمع من أهل العلم أنه إذا تعمد تركها حتى تطلع الشمس كفر؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وهذا قد تعمد تركها حتى خرج وقتها، وهكذا من تعمد ترك صلاة العصر حتى غابت الشمس يكفر عند جمع من أهل العلم لهذا الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فالواجب على المؤمن وعلى المؤمنة العناية بالصلوات الخمس، والمحافظة عليها في أوقاتها، وأن يخص الفجر بمزيد عناية حتى يقوم لها، ويصليها مع المسلمين في وقتها، وتصليها المرأة في وقتها، وهكذا العصر بعض الناس إذا جاء من عمل سقط نائمًا، وترك صلاة العصر، وهذا منكر عظيم، والعياذ بالله، وكفر أكبر عند بعض أهل العلم إذا تعمد ذلك، فالواجب الحذر. وهكذا بعض الناس يسهر على القيل والقال أو اللعب، ثم إذا طاح نام عن صلاة الفجر، وهذا منكر عظيم، الواجب عدم السهر وأن يتحرى بنومه ما يعينه على القيام لصلاة الفجر، وأن يصليها في الجماعة، ولا يجوز له التشبه بالمنافقين أثقل الصلاة على المنافقين صلاة العشاء وصلاة الفجر وهكذا صلاة العصر، كل الصلوات ثقيلة عليهم: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]. فالواجب الحذر من مشابهتهم، والواجب المحافظة عليها في وقتها كلها الصلوات الخمس جميعًا، يجب أن يحافظ عليها في أوقاتها، مع إخوانه في المساجد، وأن يخص الفجر والعصر والعشاء بمزيد عناية، حتى يحذر من صفات المنافقين، نسأل الله للجميع العافية والهداية. المقدم: اللهم آمين، جزاكم الله عنا كل خير سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13075/السر-في-اقتران-روية-الله-بصلاتي-الفجر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55704.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":14624,"question":"يقول في سؤاله هذا سماحة الشيخ: تارك الصلاة لو أن جاري معاندًا وقمت بدعوته أكثر من مرة ونصحته وهو يزداد سخرية، فهل هذا الشخص يقاطع؟","title":"هل يهجر قاطع الصلاة المتكبر؟","answer":"الجواب: نعم، يستحق الهجر، ما دام نصحته ولا يأبى ويتكبر يستحق الهجر، مثلما هجر النبي -عليه الصلاة والسلام- كعب بن مالك وصاحبيه خمسين ليلة حتى تاب الله عليهم، لكن إن تيسر النصح، وأنه ينفع النصح فانصح، وإذا يئست منه ولم ينفع فيه النصح فهو يستحق الهجر، نسأل الله العافية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13117/هل-يهجر-قاطع-الصلاة-المتكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55912.mp3","categories":["حكم الصلاة وأهميتها","الآداب والأخلاق المحمودة"]},{"id":14657,"question":"المستمع (ح. س. ن) من سوريا، بعث برسالة يقول فيها: توفيت زوجتي وهي تلد، وكثير من الناس عندنا يقولون: إنها شهيدة، والشهيد إلى الجنة، مع أن زوجتي لا تصلي، هل تعتبر من الشهداء؟","title":"حكم من توفيت في الولادة وهي لا تصلي","answer":"الجواب: الموت بسبب الولادة شهادة جاء بذلك بعض الأحاديث عن رسول الله ﷺ إذا ماتت المرأة بسبب الولادة، لكن التي لا تصلي ليست مسلمة، والشهادة إنما هي للمسلم، فالتي لا تصلي جاء في النص عن النبي ﷺ أنه كافر، قال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وهذا هو الأصح من قولي العلماء أن الذي يتعمد ترك الصلاة، ولا يصلي لا يعتبر مسلمًا، سواء كان رجلًا أو امرأة، فلا يصلى عليه، ولا يدفن مع المسلمين، ولا يغسل، ولا يكفن؛ لأنه ترك عمود الإسلام، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13161/حكم-من-توفيت-في-الولادة-وهي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63703.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":14747,"question":"المستمع يحيى عبدالمحسن، من مصر، بعث برسالة يقول فيها: أنا -والحمد لله- أصلي منذ أن كان عمري عشر سنين، ولكن تأتي علي أيام أكون فيها إما تعبان أو مشغولًا، فلا أصلي، ولا أقضي، فما الحكم في ذلك؟ أرجو الإفادة، جزاكم الله خيرًا.","title":"حكم ترك الصلاة بسبب التعب والانشغال","answer":"الجواب: الواجب عليك التوبة إلى الله من ذلك، والبدار بالصلاة دائمًا، ولزوم ذلك، وليس لك عذر بالتعب والكسل، بل يجب أن تصلي وإن كنت تعبان أو كسلان، عليك أن تبادر بالصلاة، وتصليها في وقتها مع المسلمين.  وإذا كنت عاجزًا عن الصلاة في المسجد لمرض صليت في البيت، ولو على جنبك أو مستلقيًا إذا عجزت عن القيام والقعود.  أما تركها فلا يجوز لك أبدًا ما دمت عاقلًا تستطيع أن تصلي، ولو على جنبك أو مستلقيًا، وعليك التوبة إلى الله عما سلف والتوبة تجب ما قبلها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13233/حكم-ترك-الصلاة-بسبب-التعب-والانشغال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63716.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":14749,"question":"المستمع يحيى عبدالمحسن، من مصر، بعث برسالة يقول فيها: أنا -والحمد لله- أصلي منذ أن كان عمري عشر سنين، ولكن تأتي علي أيام أكون فيها إما تعبان أو مشغولًا، فلا أصلي، ولا أقضي، فما الحكم في ذلك؟ أرجو الإفادة، جزاكم الله خيرًا.","title":"حكم ترك الصلاة بسبب التعب والانشغال","answer":"الجواب: الواجب عليك التوبة إلى الله من ذلك، والبدار بالصلاة دائمًا، ولزوم ذلك، وليس لك عذر بالتعب والكسل، بل يجب أن تصلي وإن كنت تعبان أو كسلان، عليك أن تبادر بالصلاة، وتصليها في وقتها مع المسلمين.  وإذا كنت عاجزًا عن الصلاة في المسجد لمرض صليت في البيت، ولو على جنبك أو مستلقيًا إذا عجزت عن القيام والقعود.  أما تركها فلا يجوز لك أبدًا ما دمت عاقلًا تستطيع أن تصلي، ولو على جنبك أو مستلقيًا، وعليك التوبة إلى الله عما سلف والتوبة تجب ما قبلها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13233/حكم-ترك-الصلاة-بسبب-التعب-والانشغال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63716.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":14774,"question":"هناك من الأصدقاء من أسير معهم وأعتبرهم كالإخوة، فهم أوفياء ومخلصون، ولكنهم لا يصلون، والعياذ بالله، وبعضهم يصلي في رمضان فقط، والبعض الآخر يأتي الفواحش ما نهى الله ورسوله ﷺ عنه. وأنا بصفتي مسلم أحاول مع بعض الأصدقاء جذبهم إلى الصلاة والعبادة، فهل أقاطعهم التزامًا بقول رسول الله ﷺ: بين المسلم والكافر ترك الصلاة، فمن تركها فقد كفر صدق رسول الله؟ وإن قاطعتهم فهل معنى ذلك أن أقاطع معظم الزملاء من منطقتي، ومن مرحلتي الدراسية الذين لا يصلون، وأبقى منعزلًا عن هؤلاء الناس؟أفيدوني، جزاكم الله خيرًا.","title":"حكم مجالسة وصُحبة من لا يصلي","answer":"الجواب: نعم، نعم، عليك أن تقاطعهم إذا لم يقبلوا النصح، ولم يستفيدوا منك، ولم يسترشدوا منك، فعليك أن لا تصحبهم، وأن لا يكونوا زملاء لك في الزيارات، أو الأكل، ونحو ذلك، بل تقاطعهم ولا يضرك أن تدرس في المدرسة التي هم فيها، لكن لا تتخذهم أصحابًا، ولا زملاء في الأكل والشرب، والزيارة للإخون الآخرين لا، قاطعهم حتى يعلموا أنك تهجرهم، وأنك تبغضهم في الله؛ لأن ترك الصلاة كفر أكبر على الصحيح، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة. فالذين لا يصلون وقد نصحتهم لله، وأعذرت فيهم عليك أن تقاطعهم، لا تجب دعوتهم، ولا تدعوهم إلى وليمة عندك، ولا تكن معهم في الزيارات، قاطعهم حتى يعلموا صدقك في بغضهم في الله، وإنكارك عليهم، وتسأل الله مع هذا أن الله يهديهم في صلاتك، وفي سجودك، وفي أوقات أخرى، تسأل الله أن الله يهديهم، ويمن عليهم بالتوبة، فأنت تحب لهم الخير تسأل الله لهم الهداية، لكن تظهر لهم الجفاء والكراهة والهجر لعلهم يهتدون. فإن رجوت إسلامهم، ورجوت هدايتهم فلا تقطع عنهم الزيارة للدعوة فقط، تزورهم بين وقت وآخر للدعوة، لا لأنهم أصحاب، بل للدعوة والتوجيه لعلهم يهتدون، نعم. السائل: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13269/حكم-مجالسة-وصحبة-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49017.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":14792,"question":"السائلة: التي رمزت لاسمها بالحائرة (س. ع) من جازان، كتبت في الحقيقة رسالة مطولة مختصرها -يا سماحة الشيخ- تقول: أحيطكم علمًا -يا سماحة الشيخ- بأنني امرأة متزوجة من رجل يسيء في معاملتي، فهو قليل الصلاة، كثير السهر، كثير السب والشتم، يمنعني من زيارة أقاربي، يهددنني إن فعلت ذلك بالطلاق، ومن آخر ما وقع منه بأنه خطب لابنه الأكبر، وبعد عقد قرانه تخلى عنه، ورفض أن يعينه على تكاليف الزواج. فأنا الآن حائرة كما أنه لا يصرف علينا كما يجب، بل يضيع الأموال فيما لا يرضي الله  في السهرات وغيرها.فأنا الآن بين نارين وبناتي أصبحن كبيرات، لا أستطيع تركهن معه، ولا أستطيع الوقوف مع ابني ضده، فلسنا له أندادًا، وجهونا -يا سماحة الشيخ- في ضوء هذه الرسالة؟","title":"حكم البقاء مع زوج تارك للصلاة سيئ الخُلُق","answer":"الجواب: إن كان الرجل لا يصلي، أو يدع الصلاة في بعض الأحيان، فهذا كفر وضلال، الصحيح أن من ترك الصلاة كفر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فالواجب عليك فراقه، والذهاب إلى أهلك، والمطالبة بالطلاق من جهة المحكمة. أما إن كان يصلي، ولكن قد يتأخر عن صلاة في الجماعة، وإلا يصلي في البيت فهو عاصٍ، وقد تشبه بالمنافقين، ولكن لا يكفر بذلك. أما ما كان من جهة النفقة، ومن جهة السب والشتم فهذا عليك نصيحته أنت وأقاربه كإخوانه أو أبيه إن كان له أب أو جد، أو أقارب جيدين، أو جيران صالحين، تقولين لهم، وتستعين بالله، ثم بهم على نصيحته؛ لعل الله يهديه بأسبابكم، وإذا لم يقبل النصيحة ففي إمكانك الرفع إلى المحكمة، أو الذهاب إلى أهلك، وطلب الطلاق؛ لأن هذه الحال لا عيشة معها، حالة سيئة، فإذا لم يستقم على الطريق السوي، فلك أن تعافيه، وتطلبي الطلاق لسوء أخلاقه وسوء أعماله، ولكن إذا تيسر منك ومن أبيه أو جده أو إخوانه أو أعمامه أو جيرانه الطيبين، إذا تيسر نصيحته، لعله يهتدي، لعله يستقيم، لعل أخلاقه تصلح، لعله يترك السهر، إذا تيسر هذا فأبشري بالخير، واحتسبي الأجر.  فإن لم يتيسر هذا، فلك أن تذهبي إلى أهلك، وتطلبي الطلاق؛ لأن هذه أخلاق سيئة، لا يلزمك الصبر عليها، نسأل الله العافية، ونسأل الله لنا وله الهداية. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/13282/حكم-البقاء-مع-زوج-تارك-للصلاة-سيى-الخلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56115.mp3","categories":["الطلاق","حكم الصلاة وأهميتها","الأنكحة المحرمة"]},{"id":14960,"question":"أيضًا لديه سؤال آخر يقول: أفيدكم أن والدتي عاجزة عن الصلاة بعض الأوقات، هل أنوب عنها بالصلاة أم لا؟","title":"حكم النيابة في الصلاة عن العاجز","answer":"الجواب: الصلاة لا ينوب فيها أحد عن أحد، الصلاة لا ينوب فيها أحد عن أحد، فإن كانت عاجزة عن الصلاة قائمة صلت قاعدة؛ إذا كان عقلها معها، فإن عجزت عن القعود تصلي على جنبها، فإن عجزت عن الجنب تصلي مستلقية ورجلاها إلى القبلة، هذا هو الواجب عليها فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].  أما إن كانت عاجزة بمعنى أنها قد تغير عقلها، خرف، يعني: خرفت، وصارت كبيرة السن لا تعي؛ فلا صلاة عليها، ولا تصلي عنها، وهكذا لو كانت معتوهة مجنونة ليس عليها صلاة.  أما العاقل فعليه الصلاة على حسب حاله، العاقل المكلف عليه أن يصلي على حسب حاله: قائمًا أو قاعدًا، أو على جنبه، أو مستلقيًا، هكذا أمر النبي -عليه الصلاة والسلام- فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] نعم.","link":"https://binbaz.org.sa/fatwas/13463/حكم-النيابة-في-الصلاة-عن-العاجز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_650/nour_65003.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15037,"question":"يقول: زوج أختي لا يصلي، وقد ألححت عليه كثيرًا للصلاة، فلم يجب، ويقول: إن الإسلام ليس الصلاة، وهم يسكنون في قرية بعيدة عني، وأقوم بصلتهم، علمًا أن والدي متوفى، وأنا الذي أحل محله، فإذا أحضروا لي الطعام، فهل يصح أن آكل منه؟الشيخ: أعد؟المقدم: يقول: زوج أختي لا يصلي، وقد ألححت عليه كثيرًا للصلاة، فلم يجب، ويقول: إن الإسلام ليس صلاة، هذا شق من السؤال إذا تفضلتم بالإجابة عليه؟","title":"حكم من لا يصلي ويقول: الإسلام ليس صلاة؟","answer":"الجواب: هذا لا يجوز، هذا غلط كبير، فالإسلام هو التوحيد والصلاة والزكاة والصيام والحج، فهذا الرجل جاهل، يجب أن يعلم ويرشد ويوجه إلى الخير، فالإسلام مبني على أركان، والصلاة أعظم عمود بعد التوحيد، فهي عموده العظيم بعد الشهادتين، كما قال النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة. فالواجب أن يحذر من ذلك، وعلى الزوجة أن تفارقه حتى يتوب، على أختك أن تفارقه حتى يتوب، ولا تبقى عنده، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وينبغي أن يرفع أمره إلى ولي الأمر إذا لم يتب، حتى يحال إلى المحكمة، وحتى تجري المحكمة ما يلزم من استتابته، فإن تاب وإلا قتل، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13538/حكم-من-لا-يصلي-ويقول-الاسلام-ليس-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49309.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15080,"question":"هذا سائل سوداني، ومقيم بالمنطقة الشرقية، يقول سماحة الشيخ، يذكر في أنه في الحادية والثلاثين من العمر، يقول: كنت لا أصلي، ولا أصوم إلا القليل، وكنت لا أبالي في ارتكاب الآثام قبل ثماني سنين، وقد من الله علي  بالتوبة والاستقامة، أحمد الله على ذلك. فأرجو من سماحتكم أن توضحوا لي ماذا أعمل بالصوم الذي لم أصمه، ولا أدري عدد الشهور والأيام، وهل يلزمني إعادة الصلوات وهل علي الحج؟","title":"حكم قضاء الصلاة والصوم لمن تاب من تركهما","answer":"الجواب: التوبة تكفي، والحمد لله، التوبة تكفي، يقول النبي ﷺ: التوبة تجب ما قبلها ويقول ﷺ: التائب من الذنب كمن لا ذنب له وهذا هو معنى قوله سبحانه: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] أجمع العلماء على أن هذه الآية الكريمة في التائبين، وأن من تاب إلى الله من شركه وكفره تاب الله عليه، وهكذا من جميع المعاصي، فليس عليك -يا أخي- قضاء للصلاة الفائتة التي تركتها، ولا للصوم، الحمد لله، قد عفا الله عنك ذلك بتوبتك، وعليك بالجد والاجتهاد في طاعة ربك، والإكثار من العمل الصالح، والله يقول سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13571/حكم-قضاء-الصلاة-والصوم-لمن-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15095,"question":"أحمد سلمان زيدان من الجمهورية العراقية، من بغداد، بعث بهذا السؤال يقول: ما حكم تارك الصلاة لمدة سنتين، ثم العودة إلى الصلاة دون انقطاع؟ وكيف يعوض هاتين السنتين التي لم يصليهما؟","title":"كيف يعوض التارك للصلاة ما تركه؟","answer":"الجواب: إذا ترك المسلم الصلاة سنة أو أكثر أو أقل، ثم تاب الله عليه، فإن التوبة تجب ما قبلها، وليس عليه أن يعيد ما ترك، بل عليه التوبة إلى الله، والصدق في ذلك، بالندم على ما مضى من عمله، والعزم ألا يعود، ثم الاستكثار من العمل الصالح، من ذكر الله، واستغفاره، والتطوع بالصلوات وغيرها من الصدقات والصيام، ونحو ذلك، ويكفي هذا؛ لأن الله قال -جل وعلا- في كتابه العظيم لما ذكر المشرك والقاتل بغير حق والزاني، قال بعد ذلك: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ[الفرقان:70] وقال سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى[طه:82] وقال النبي ﷺ: التوبة تجب ما قبلها وقال: التائب من الذنب كمن لا ذنب له. فالذي ترك الصلاة، ثم هداه الله، ورجع إلى دينه، وإلى إسلامه، فإن توبته صحيحة إذا كان صادقًا نادمًا عازمًا ألا يعود في ذلك، فإن توبته صحيحة، والله سبحانه يمحو بها ذنبه الماضي، ويغفره له، وليس عليه أن يقضي تلك الصلوات، هذا هو الصواب من أقوال أهل العلم، نعم.","link":"https://binbaz.org.sa/fatwas/13597/كيف-يعوض-التارك-للصلاة-ما-تركه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66405.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15118,"question":"أيضًا نعود إلى رسالة المستمع: أحمد عبدالله محمد علي جمعة، من السودان، عرضنا بعض أسئلته في حلقات مضت، وفي هذه الحلقة يسأل عن حكم تارك الصلاة؟","title":"ما حكم تارك الصلاة؟","answer":"الجواب: حكم تارك الصلاة فيه تفصيل عند أهل العلم: إن تركها جاحدًا لوجوبها، يقول: ما هي بواجبة، وهو عاقل كفر إجماعًا، بإجماع المسلمين؛ لأنه مكذب لله ولرسوله، الله سبحانه يقول: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ [البقرة:43] ويقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول -جل وعلا-: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103] والنبي ﷺ يقول: بني الإسلام على خمس: شهادة أن لا إله إلا الله، وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت متفق عليه. ولما سأله جبرائيل عن الإسلام، قال -عليه الصلاة والسلام-: الإسلام أن تشهد أن لا إله إلا الله، وأن محمدًا رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت، إن استطعت إليه سبيلًا فالصلاة عمود الإسلام، فمن جحد وجوبها كفر بإجماع المسلمين، فإن كان بعيدًا عن الإسلام في محلات لا تعرف الإسلام بين له، وأقيمت عليه الحجة، وتذكر له الآيات، فإن أصر على جحده وجوبها كفر إجماعًا. أما الذي بين المسلمين، يسمع القرآن والسنة هذا إذا جحدها كفر. أما إذا تركها وهو لا يجحد، لكن تكاسل، فذهب جمع من أهل العلم إلى أنه يكفر أيضًا، إذا تركها ولو لم يجحد وجوبها؛ لأنها عمود الإسلام، وقد صح فيها أحاديث تدل على كفر من تركها، ونقل ذلك عبدالله بن شقيق العقيلي عن الصحابة ، أصحاب النبي ﷺ: أنهم كانوا لا يرون شيئًا تركه كفر إلا الصلاة؛ ولقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة ولقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه. والكفر والشرك إذا عرف، فالمراد به الكفر الأكبر والشرك الأكبر؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وهذا هو الأرجح وأصح القولين: أنه يكفر كفرًا أكبر، نعوذ بالله، ولو ما جحد وجوبها، سواء تركها كلها، أو ترك الفجر أو الظهر، أو العصر، أو تارة يصلي، وتارة لا يصلي، يكفر بذلك، وعليه أن يجدد توبة نصوحًا. وذهب الأكثرون من الأئمة الأربعة، من المالكية، والحنفية، والشافعية إلى عدم كفره، وأنه كفر أصغر، وشرك أصغر، وهو قول جماعة من الحنابلة أيضًا، ولكن الصواب الأول: أنه كفر أكبر؛ لأن الأدلة الشرعية تدل على كفره؛ لأنها عمود الإسلام، فيجب الحذر من ذلك. فالواجب على كل مسلم أن يحذر ترك الصلاة، وأن يحافظ عليها في جميع الأوقات، المغرب، والعشاء، والفجر، والظهر، والعصر، يجب أن يحافظ عليها جميعًا، وأن يصليها في الجماعة أيضًا إذا كان رجلًا؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر ولما سأله رجل أعمى، قال: يا رسول الله، ليس لي قائد يقودني للمسجد، فهل لي من رخصة أن أصلي في بيتي؟ قال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب أعمى ليس له قائد يلائمه، ومع هذا يقال له: أجب صل في الجماعة، كيف بحال البصير، يكون الوجوب عليه أشد وأعظم. ولأن ترك الجماعة وسيلة إلى الترك، عدم الصلاة في الجماعة وسيلة إلى تركها بالكلية والتهاون بها. فالواجب على كل مكلف وكل مسلم الحذر من ذلك، وأن يصليها في الجماعة، ويحافظ عليها، وأن يحذر التأسي بأهل الباطل، يحذر صحبة الأشرار الذين يتركونها، ويتهاونون بها؛ ليحذرهم غاية الحذر. والتهاون بها من صفات المنافقين، فلا يجوز لمسلم أن يتأسى بهم، يقول الله سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142] فاحذر أن تشابه أعداء الله المنافقين، يقول الله في حقهم: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ وَلَنْ تَجِدَ لَهُمْ نَصِيرًا [النساء:145]. فالواجب الحذر من صفات المنافقين، والواجب على الرجال والنساء جميعًا المحافظة عليها في أوقاتها، والرجل يؤديها في الجماعة، والمرأة تؤديها في بيتها، وتحافظ عليها في وقتها، وتحذر الكسل والتهاون فهي عماد الإسلام، وهي الفارقة بين الكفر والإسلام، في الحديث الصحيح يقول ﷺ أول ما يحاسب عنه العبد من عمله صلاته  -يعني يوم القيامة- فإن صلحت فقد أفلح وأنجح، وإن فسدت فقد خاب وخسر وهذا من الأدلة على كفر تاركها. فالواجب على كل مسلم أن يتقي الله، وأن يحافظ على الصلاة في الجماعة، وهكذا كل مسلمة عليها أن تتقي الله أن تراقب الله، وأن تحافظ على الصلاة في وقتها كل وقت، ولا يجوز تأخير الفجر إلى طلوع الشمس، إلى أن يذهب إلى العمل لا، يجب أن يصليها في الوقت مع الجماعة في مساجد الله، فإن صلاها في البيت صحت مع الإثم، لكن ليس له أن يؤخرها إلى طلوع الشمس، ولا يؤخر العصر إلى أن تصفر الشمس، ولا يؤخر المغرب إلى أن يغيب الشفق، يجب أن يصلي في الوقت، ويجب أن يصلي في الجماعة إذا كان رجلًا في المساجد، فإذا أهملها وضيعها كفر، نسأل الله العافية، بنص الرسول ﷺ حيث قال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة والحكم عام للرجل والمرأة؛ ولهذا في الحديث الآخر: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فالأحكام مشتركة، ما ثبت في حق الرجل ثبت في حق المرأة، وما ثبت في حق المرأة ثبت في حق الرجل، إلا ما دل عليه الدليل بالخصوصية. فنصيحتي لكل مسلم ومسلمة تعظيم الصلاة، والعناية بها، والمحافظة عليها، وعلى طهارتها، وعلى جميع شؤونها، وعلى السترة فيها، الطهارة شرط لا بد منها، والوقت كذلك، واستقبال القبلة كذلك لا بد، فالواجب على الجميع العناية بهذه الأمور، وأن يعتني بالطهارة والسترة، يستر العورة، وأن يعتني باستقبال القبلة، وأن يصليها في الوقت، والرجل يؤديها في الجماعة في مساجد الله مع إخوانه. كان عمر  يكتب إلى عماله إلى أمرائه، ويقول: إن أهم أمركم عندي الصلاة، فمن حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع يعني: متى ضيع الصلاة ضيع دينه نسأل الله العافية، ولا تجد إنسانًا يتهاون بالصلاة إلا وهو متهاون بدينه، فهي علامة التهاون، وعلامة المحافظة، من حافظ عليها حافظ على بقية الدين، واستقام أمره، ومن ضيعها وتهاون بها تهاون ببقية الدين، ولا حول ولا قوة إلا بالله. وقد ثبت في المسند -مسند أحمد رحمه الله- عن النبي ﷺ أنه قال يومًا لأصحابه: من حافظ على الصلاة كانت له نورًا وبرهانًا ونجاة يوم القيامة، ومن لم يحافظ عليها، لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف نسأل الله العافية، وإنما يحشر مع هؤلاء الكفرة؛ لأنه إن ضيعها من أجل الرياسة؛ لأنه ملك، أو لأنه رئيس جمهورية، أو شيخ قبيلة، فقد شابه فرعون، فيحشر مع فرعون إلى النار يوم القيامة.\nوإن ضيع الصلاة من أجل الوزارة، شابه هامان وزير فرعون، فيحشر معه إلى النار يوم القيامة، نسأل الله العافية.\nوإن ضيع الصلاة بأسباب الأموال والشهوات شابه قارون، الذي خسف الله به الأرض وبأهله، فيكون معه يوم القيامة في النار، نسأل الله العافية.\nوإن ضيعها بأسباب المعاملات والتجارة شابه أبي بن خلف، تاجر أهل مكة، أبي بن خلف كان من تجار أهل مكة قتل يوم أحد قتله النبي ﷺ بيده الشريفة -عليه الصلاة والسلام-، كافرًا، فمن ضيع الصلاة من أجل البيع والشراء والمعاملات شابه عدو الله أبي بن خلف، فيحشر معه إلى النار يوم القيامة. فيجب الحذر -أيها الإخوة- في الله، يجب الحذر أيها المسلمون، أيها المسلمون نوصيكم بالصلاة، احرصوا عليها، حافظوا عليها في أوقاتها، بالخشوع والطمأنينة، وعدم النقر، وعدم العجلة، اتقوا الله في صلاتكم، حافظوا عليها، اركدوا فيها، اخشعوا فيها لله، لا تعجلوا أدوها بالطمأنينة، والخشوع في القراءة، وفي الركوع، وفي السجود، وفي الرفع بعد الركوع، وبين السجدتين، إذا ركع يقول: سبحان ربي العظيم، لا يعجل، سبحان ربي العظيم، سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، لا يعجل يطمئن، وإذا رفع يقول: سمع الله لمن حمده، إن كان إمامًا أو منفردًا، وإن كان مأمومًا يقول: ربنا ولك الحمد، حمدًا كثيرًا طيبًا مباركًا فيه، ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد، يكون مطمئنًا يعتدل، واقفًا. ثم ينحط ساجدًا، ويعتدل في السجود على سبعة الأعضاء، على جبهته وعلى أنفه ويديه وركبتيه وأطراف قدميه ويطمئن، يطمئن يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، يدعو ربه في سجوده، ويخشع لله في السجود، يقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، ويقول -عليه الصلاة والسلام-: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء وهكذا بين السجدتين يطمئن، ولا يعجل، يقول: رب اغفر لي، رب اغفر لي، اللهم اغفر لي، وارحمني، واهدني، واجبرني، وارزقني، وعافني، لا يعجل، ثم يسجد الثانية، ويكبر، ويسجد الثانية، ويطمئن، يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ويدعو بما تيسر لا يعجل، هكذا المؤمن، فالرجل يؤديها في الجماعة، في مساجد الله، ويسارع إليها إذا سمع الأذان حي على الصلاة، حي على الفلاح، بادر سارع إلى هذه العبادة العظيمة، والمؤمنة كذلك في بيتها، تصليها في بيتها في وقتها، بخشوع وطمأنينة، وإقبال، وإحضار قلب، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13618/ما-حكم-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49502.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15267,"question":"السائلة أم محمد، من الرياض، في آخر أسئلتها تقول: زوجي يعاني من سلس البول، وأعرف حكم الوضوء وحكم الصلاة في الشرع، ولكنه يترك الصلاة بسبب وسوسة الشيطان له بعد طهارته، ولقد جاهدت في ذلك كثيرًا، وهو لا يصلي إلا الجمعة، وهو حريص على الصلاة، وعلى صلاتي أنا والأولاد. و ما حكم بقائي معه سماحة الشيخ عبدالعزيز ؟","title":"حكم مَن زوجها لا يصلي بسبب سلس البول","answer":"الجواب: ما يجوز البقاء معه، من ترك الصلاة كفر، نعوذ بالله، فالواجب عليه أن يصلي مع السلس، يتوضأ لكل صلاة، والحمد لله، ويصلي مع الناس، ولو خرج منه بول معذور، إذا أذن المؤذن يتوضأ ويصلي مع الناس، والحمد لله، ولا يجوز ترك الصلاة من أجل السلس، كالمستحاضة الذي معها الدم الدائم، تصلي، تتوضأ لكل صلاة وتصلي كما أمر النبي ﷺ بذلك. أما البقاء مع إنسان لا يصلي إلا الجمعة هذا ضلال وكفر، نسأل الله العافية، ما يجوز، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ويقول ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13765/حكم-من-زوجها-لا-يصلي-بسبب-سلس-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56513.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15302,"question":"هذا سؤال من المستمعة (ن. أ. ف) من حائل، تقول: سؤالي عن الصلاة؛ حيث أنني كنت مريضة لمدة ثلاث سنوات، ولم أصل في هذه الفترة إلا بعض الأوقات، أما الأوقات الأخرى فإني لم أستطع أن أصليها؛ لأنني كنت في حالة غيبوبة.وأيضًا أسأل عن الصيام فقد مضت سنتان لم أصم شهر رمضان فيهما من شدة المرض، وإلى الآن لم أستطع الصيام، أرجو إفادتي عماذا يجب علي فعله نحو الصيام والصلاة؟جزاكم الله خيرًا.","title":"حكم من تركت الصلاة والصيام لشدة المرض","answer":"الجواب: أما الصيام فعليك قضاء الصيام، فإذا كان تركه من أجل شدة المرض، فعليك قضاء الصيام إذا شفاك الله ؛ لأن الله قال : وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ[البقرة:185] أما إذا كان تركهما عن زوال عقل أصابك مرض أزال العقل، وصادف رمضان وأنت غير عاقلة قد زال العقل منك، فلا صيام عليك، إذا كانت المدة التي في رمضان والعقل مفقود فلا صيام؛ لأن التكليف مربوط بالعقل، فإذا زال العقل زال التكليف، أما إذا كان من شدة المرض فقط فعليك القضاء. وهكذا الصلاة؛ إن كنت تركت الصلاة من أجل زوال العقل، بسبب ما أصابك من الإغماء الذي فقدت معه العقل، حتى مضى عليك سنة أو سنتان وأنت غير عاقلة، قد ذهب عقلك فلا قضاء؛ لأن من ذهب عقله فهو شبه المجنون والمعتوه، لا قضاء عليه، أما إن كان من أجل المرض شدة المرض تساهلت ولم تصلي تحسبين أنه يجوز لكِ ذلك فعليك أن تقضي ما تركت من الصلوات التي غلب على ظنك أنك تركتيها بسبب شدة المرض، تقضينها حسب الطاقة، تسردين ما ظننت أنك تركتيه في كل وقت، تجمعين جملة من الصلوات فتقضينها لأنك تركتيها عن جهل منك وعن غلط منك بسبب المرض. والمريض يصلي على حسب حاله، يصلي قاعدًا، فإن عجز صلى على جنبه، فإن عجز صلى مستلقيًا لا يتساهل، النبي ﷺ قال للمريض: صل قائمًا فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هكذا يجب على المؤمن إذا مرض إن استطاع القيام صلى قائمًا، فإن عجز صلى وهو قاعد، ويركع ويسجد في الأرض، فإن عجز عن القعود صلى على جنبه، والأفضل على جنبه الأيمن، يقرأ ويكبر ويتعاطى ما شرع الله بالكلام، وينوي الأفعال بالنية، ينوي الركوع بالنية، ينوي السجود، ينوي الجلوس بين السجدتين بالنية، ينوي الجلوس في التحيات بالنية، ويأتي بالأقوال المشروعة من القراءة وغيرها، فإن عجز صلى مستلقيًا، يستلقي ويجعل رجليه إلى القبلة، ويصلي وهو مستلقي يكبر ويقرأ، يكبر ويركع بالنية، يقول: سمع الله لمن حمده بالنية، ويرفع بالنية، يقول: ربنا ولك الحمد، ثم يكبر ناويًا السجود، وهكذا من المضطجع على جنبه ومن المستلقي. أما إذا كنت قد فقدت الشعور قد فقدت عقلك فالمدة التي فقدت فيها عقلك المدة الطويلة، هذه لا صلاة فيها لا قضاء فيها، أما إذا كان المدة قليلة اليوم واليومين التي فقدت فيها عقلك، والباقي صاحية، فاليوم واليومين والثلاث تقضى كالنائم يقضي، فإذا طالت المدة أكثر من ثلاثة أيام طالت المدة بسبب فقد العقل والإغماء فلا قضاء على الصحيح. المقصود: أن عليك قضاء المدة التي تركت فيها الصلاة من أجل شدة المرض لا من أجل زوال العقل، فإذا كان من أجل شدة المرض هذا تساهل منك، وعليك القضاء مرتبًا؛ ظهر عصر مغرب عشاء فجر ظهر عصر، وهكذا مرتب، ولو في أيام قلائل، كل وقت تصلي فيه عدة صلوات حسب ظنك وغلبة ظنك تجتهدين وتصلينها -إن شاء الله-، هذا هو الأحوط لك والأفضل لك، نعم.\nالمقدم: بالنسبة للصيام؟\nالشيخ: والصيام كذلك، ما ترك من أجل شدة المرض تقضيه، وما كان عن زوال العقل يعني: ذهب عقلها، ولم يكن معها عقل فلا قضاء مثل المعتوه. المقدم: لا يلزمها شيء مع القضاء.\nالشيخ: ولا يلزمها إلا الصيام؛ لأنها معذورة. أما إذا كان تركك -أيها السائلة- للصلاة عن عمد وقلة مبالاة ما هو عن شبهة، وتظنين أن المرض عذر، فتركتها قلة مبالاة، وتساهلًا بها، هذا كفر وضلال، فلا تقضى بعد ذلك، التوبة تكفي، التوبة تكفي فقط؛ لأن الرسول ﷺ أخبر أن ترك الصلاة كفر، فقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فإذا كنت تركتها عمدًا لا عن شبهة، ولا عن ظن أنه يجوز لك تأخيرها من أجل المرض، فهذا منكر عظيم، وكفر صريح، فالتوبة تكفي، ولا قضاء عليك لما مضى؛ لأن تركها من غير عذر كفر وضلال وردة عن الإسلام في أصح قولي العلماء، فإذا تاب العبد من ذلك كفته التوبة فقط، نعم، نسأل الله السلامة، نعم.\nالمقدم: نسأل الله السلامة، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13821/حكم-من-تركت-الصلاة-والصيام-لشدة-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_682/nour_68205.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":15365,"question":"السائلة (م. م. م) الرياض، تقول: والدي يريد أن يزوجني من ابن عمي، مع أنه لا يصلي أبدًا، ويقول: إذا لم تطيعي أمري فأنا غاضب عليك إلى يوم الدين، ولقد وسطت أهل الخير، فلم أفلح، وعمي يقول لوالدي: إذا لم تزوج ابنتك لولدي، فالفراق بيني وبينك، فما هو الحل يا سماحة الشيخ؟","title":"حكم طاعة الوالد في الزواج بمن لا يصلي","answer":"الجواب: لا يجوز لهم جبرها على هذا، ولا يجوز لها أيضًا فعل ذلك ولا لهم أيضًا، الواجب أن يعينوها على الخير، فليس لها أن توافق على إنسان لا يصلي، وليس لهم أن يجبروها على ذلك، الذي ما يصلي كافر، نعوذ بالله، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر. فلا يجوز لها هي أن تقبل، حتى لو رضوا ليس لها أن تقبل، هي يجب عليها أن تمتنع، وهم لا يجوز لهم جبرها، لا عمها ولا أبوها، وهذا يدل على قلة دينهما، قلة دين الأب، وقلة دين العم، كيف يجبرونها على رجل لا يصلي، أعوذ بالله، بل لا يجوز أن يزوجوها إياه، ولا يجوز لها أن ترضى هي، والنكاح باطل، لو زوجوها، الكافر لا يزوج مسلمة، الله يقول -جل وعلا-: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221] ويقول: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]. فالصحيح الذي عليه الأدلة الشرعية: أن تارك الصلاة يكون كافرًا، هذا هو الصواب، وهو الذي قامت عليه الأدلة الشرعية، منها قوله ﷺ في صحيح مسلم عن جابر  يقول ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ويقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة ويقول عبدالله بن شقيق العقيلي : \"لم يكن أصحاب النبي ﷺ يرون شيئًا تركه كفر إلا الصلاة\" يرون أن تركها كفر، يعني: كفر أكبر. فالمقصود: أنها مشكورة، وقد أحسنت، وهذا الواجب عليها، ولو زوجوها لأثموا، والعقد باطل، نعم. المقدم: بارك الله فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13868/حكم-طاعة-الوالد-في-الزواج-بمن-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49908.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15403,"question":"السائل (عدنان . م. ع) من الأردن يقول: بأنه متزوج منذ عامين، وعرف من بعض الأصدقاء بأنه إذا عقد الزواج، وهو لا يؤدي فريضة الصلاة، فالعقد باطل، مع العلم بأنني عقدت العقد ولم أكن أصلي ولا أركع ركعة، وأنا الآن التزمت بالصلوات الخمس التزامًا تامًا، هل يجب علي أن أعيد مرة ثانية؟ وكيف يكون ذلك بعد طلاقي من زوجتي وعقد جديد؟فأفيدونا يا سماحة الشيخ.","title":"ما حكم عقد النكاح لمن كان لا يصلي؟","answer":"الجواب: إذا كنت لا تصلي وهي تصلي فالعقد غير صحيح على الصحيح؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة فإذا كنت لا تصلي والمرأة طيبة تصلي، فالعقد غير صحيح، يجدد بعد توبتك يجدد، أما إذا كانت مثلك لا تصلي، فالعقد صحيح، كنكاح الكافر للكافرة.  أما إذا كانت تصلي وأنت لا تصلي فالعقد غير صحيح ويجدد على الصحيح بعد توبتك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13901/ما-حكم-عقد-النكاح-لمن-كان-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56722.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","مبطلات النكاح"]},{"id":15438,"question":"سؤاله الثالث يقول: أنا الآن أبلغ من العمر الثامنة والعشرين، ومنذ كان عمري سبع عشرة سنة، وأنا أصلي وأصوم، ولكن أحيانًا أترك الصلاة مدةً، ثم أعود إليها، فماذا علي الآن؟ هل يلزمني قضاء أم تكفي التوبة؟ وكيف أعمل وأنا ربما أجهل عدد الأيام التي تركت الصلاة فيها؟ وكذلك بالنسبة للصيام فقد أفطرت بعض الأيام بدون عذر، وأفطرت خلال أربع سنوات بسبب مرض، ولم يمنعني الأطباء من الصيام، ولكني أنا شعرت بضعف شديد، وهبوط في صحتي، فأفطرت، فماذا أفعل الآن؟أرشدوني، بارك الله فيكم.","title":"حكم قضاء الصيام والصلاة لمن يترك أحيانًا","answer":"الجواب: ترك الصلاة كفر أكبر، نعوذ بالله، تعمد ترك الصلاة كفر أكبر، يقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر ويقول -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة فترك الصلاة وإن كان تهاونًا كفر أكبر في أصح قولي العلماء. \nأما إن كان عن جحد لوجوبها، فهذا كفر أكبر عند جميع العلماء، لكن إذا كان عن تساهل وعن تهاون، فهذا كفر أكبر في أصح قولي العلماء. فعليك التوبة إلى الله، وليس عليك القضاء عليك التوبة الصادقة النصوح بالندم على ما مضى منك، والعزم الصادق على ألا تعود إلى هذا الشيء، والاستمرار في الصلاة، وليس عليك قضاء ما فات من الصيام والصلوات السابقة التي تركتها تهاونًا، فالصوم تابع لذلك؛ لأن ترك الصلاة كفر فليس عليك قضاء الصلاة، ولا قضاء الصيام. أما ما تركت من الصيام وأنت تصلي بعدما تاب الله عليك، وتركت هذا الذنب العظيم، فإنك تقضي الصيام. وأما إذا كان ترك الصيام في وقت ترك الصلاة، فإنك لا تقضيه، ولا تقضي الصيام؛ لأن المسلم إذا ارتد عن دينه لا يقضي، قال الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ[الأنفال:38] والنبي ﷺ يقول: الإسلام يهدم ما كان قبله، والتوبة تجب ما قبلها فإذا تاب الرجل من ترك الصلاة بعدما تركها تاب ورجع إلى الله، فإنه يستمر في العبادة، والعمل الصالح، ويسأل ربه المغفرة والعفو، وليس عليه قضاء، لا لصلاته ولا لصومه السابق الذي تركه في حال ترك الصلاة، نسأل الله السلامة. وعليك الصدق مع الله ودعائه -جل وعلا- أن يثبتك على الحق، وعليك الإكثار من العمل الصالح، كما قال الله -جل وعلا-: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى[طه:82] ولما ذكر سبحانه الشرك والقتل والزنا قال بعد هذا: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا[الفرقان:70]. فنوصيك وجميع المسلمين بالتوبة إلى الله الصادقة النصوح من جميع الذنوب، ولا سيما ترك الصلاة، فإنه ذنب عظيم، وكفر عظيم، فعليك بالمبادرة والمسارعة إلى التوبة الصادقة، والعزم الصادق أن لا تعود، والاستمرار في الصلاة، وهكذا نوصي جميع من ترك الصلاة أن يتوب إلى الله، وأن يبادر بالتوبة الصادقة النصوح، وليس عليه قضاء لما ترك قبل ذلك، نعم. المقدم: بالنسبة لتعين القضاء هل بالنسبة للعدد هو يجهل عدد الأيام التي أفطرها؟\nالشيخ: ما دام أنه في حال ترك الصلاة ما عليه قضاء، أماإذا كان مسلمًا وهو يصلي، ما عنده ناقض من نواقض الإسلام فإنه يصوم ما غلب على ظنه. المقدم: يجتهد في التقدير. الشيخ: يجتهد ويصوم ما غلب على ظنه أنه تركه، أنه أفطر فيه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13965/حكم-قضاء-الصيام-والصلاة-لمن-يترك-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_686/nour_68603.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15470,"question":"هذان سؤالان بعثت بهما الأخت (ر. ف. ي. ل) من العراق، تقول: كانت والدتي تصوم وتصلي، وقد مرضت مرضًا شديدًا منذ سنتين توفيت على إثره، ولم تكن تصوم ولا تصلي في وقت مرضها؛ لعدم الاستطاعة، فهل يلزمني دفع كفارة عنها، أو الصيام والصلاة عنها؟أفيدوني، بارك الله فيكم.","title":"حكم قضاء الصلاة والصيام عمن مات مريضًا","answer":"الجواب: ما دامت ماتت وهي مريضة ما استطاعت الصيام، فليس عليك صيام عنها، إذا كانت ماتت وهي في مرضها، لم تستطع صيامها المدة الطويلة، فإنك لا تقضين عنها شيئًا، وليس عليك إطعام أيضًا، والحمد لله. أما الصلاة فقد غلطت في ترك الصلاة، كان الواجب عليها أن تصلي، ولو كانت مريضة، ولا تؤجل الصلاة، الواجب على المريض أن يصلي على حسب حاله، إن استطاع القيام صلى قائمًا، وإن عجز صلى قاعدًا، فإن لم يستطع القعود صلى على جنبه الأيمن -وهو الأفضل- أو الأيسر على حسب طاقته، فإن لم يستطع الصلاة على جنبه صلى مستلقيًا، هكذا أمر النبي ﷺ، لما شكا إليه بعض الصحابة  المرض قال له: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا. هذا هو الواجب على المريض ذكرًا كان أو أنثى، أن يصلي قاعدًا إذا عجز عن القيام، سواء قاعدًا مستوفزًا أو متربعًا، أو كجلسته بين السجدتين، كل ذلك جائز، فإن عجز عن القعود صلى على جنبه الأيمن أو الأيسر، والأيمن أفضل إذا استطاع، ينوي أذكار الصلاة وواجباتها، ويتكلم بما يستطيع يكبر، يقرأ الفاتحة أول  شيء، يقرأ ما تيسر ثم يكبر، وينوي الركوع، ثم يقول: سمع الله لمن حمده ناويًا الرفع: ربنا ولك الحمد، إلى آخره، ثم يكبر ناويًا السجود، يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم يرفع مكبرًا، ناويًا الجلوس بين السجدتين يقول: رب اغفر لي، رب اغفر لي، ثم يكبر ناويًا السجدة الثانية، وهكذا بالنية والكلام حسب طاقته. ولا تقضى الصلاة، الصلاة لا تقضى، وإنما عليك الدعاء لها، والترحم عليها، والاستغفار إذا كانت موحدة، إذا كانت مسلمة موحدة، أما إن كانت تدعو الأموات تستغيث بالأموات والقبور، تدعو غير الله، هذه لا يدعى لها؛ لأن هذا شرك أكبر، فإذا كانت في حياتها تدعو الأموات، تستغيث بالأموات، أو بأصحاب القبور، أو تسأل البدوي، أو عبد القادر، أو غير عبد القادر الجيلاني، هذا من الشرك الأكبر؛ لأن دعاء الأموات، والاستغاثة بالأموات، كأن يقول: يا سيدي عبد القادر، اشف مريضي، أو انصرني، أو عافني، أو يا سيدي فلان -من الأموات- افعل بي كذا، أو يا رسول الله، افعل بي كذا، أو يا سيدي البدوي، افعل كذا، أو يا فلان افعل كذا من الأموات، كل هذا من الشرك الأكبر، والذي يموت على هذه الحالة لا يدعى له؛ لأنه مات على ظاهر الشرك، نسأل الله السلامة. أما إن كانت موحدة بحمد الله، لا تدعو غير الله، بل تعبد الله وحده، يدعى لها، ويستغفر لها، ولا يصلى عنها؛ لأن الصلاة لا تقضى، نعم.","link":"https://binbaz.org.sa/fatwas/14000/حكم-قضاء-الصلاة-والصيام-عمن-مات-مريضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68803.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15545,"question":"هذه سائلة تقول: أنا امرأة مصرية، وزوجي يعمل بالمملكة، وأنا أقيم معه، فهو لا يستيقظ لصلاة الفجر حاضرًا، ويصليها متأخرًا بعد شروق الشمس، وحوالي الساعة التاسعة صباحًا، ويقول: بأنه لا يستطيع القيام للصلاة؛ لأنه يكون تعبان، أما باقي الفروض فهو يصليها في أوقاتها، فما حكم عمل هذا الرجل سماحة الشيخ؟","title":"حكم تأخير الفجر إلى بعد طلوع الشمس","answer":"الجواب: هذا العمل منكر، لا يجوز، يجب أن يصلي الفجر في وقتها كبقية الصلوات، ويجب أن ينام مبكرًا حتى يقوم لها في وقتها، والتعمد لتأخيرها كفر عند جمع من أهل العلم؛ لأنه تعمد تركها في الوقت، وقد قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة فالواجب عليه أن يفعل الأسباب التي تعينه على القيام حتى يصليها في الوقت، وعليه أن يصليها مع الجماعة في المساجد، لا يصليها في البيت، يصليها مع إخوانه المسلمين في المساجد، هذا واجب عليه، ولا يجوز له التساهل في هذا الأمر، نسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/14083/حكم-تاخير-الفجر-الى-بعد-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56930.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15555,"question":"تقول سماحة الشيخ الأخت أم عبدالله من الرس: ما الأسباب المعينة على قيام صلاة الفجر؟","title":"ما الأسباب المعينة للقيام لصلاة الفجر؟","answer":"الجواب: الأسباب المعينة: التبكير النوم بعد صلاة العشاء، كون الإنسان يبكر بالنوم لا يسهر، ويرقد الساعة قبل الفجر، يرقد الساعة قبل الأذان حتى يستفيد منها وينتفع بها، أو يوصي من حوله من أهل بيته بإيقاظه، لا بد يبذل الأسباب، إما يوصي أهل بيته بإيقاظه، وإلا يحط الساعة إن كان عنده ساعة يوقتها، وينام مبكرًا حتى يأخذ حظه من النوم، هذه هي الأسباب، نعم، مع سؤال الله الإعانة والتوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14091/ما-الاسباب-المعينة-للقيام-لصلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69127.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15637,"question":"من المستمع إدريس علي، عامل في أبها، رسالة وضمنها جمعًا من الأسئلة، في أحدها يسأل سماحتكم شيخ عبد العزيز، فيقول: ما رأيكم في المسلم الذي يؤدي بعض أركان الإسلام، ويترك البعض الآخر، كأن يزكي ولا يصوم، أو يصوم ولا يصلي، وهكذا؟","title":"حكم من يؤدي بعض أركان الإسلام دون بعض","answer":"الجواب: أما ترك الصلاة فكفر أكبر في أصح قولي العلماء، ترك الصلاة كفر أكبر -والعياذ بالله- ردة عن الإسلام.  أما الزكاة والصوم والحج فليس بردة، بل كبيرة من كبائر الذنوب، ولا يكفر بذلك إلا إذا جحد الوجوب مثلًا جحد وجوب الصلاة أو الصوم أو الزكاة أو الحج، مع الاستطاعة؛ كفر بإجماع المسلمين.  أما إذا كان لا، لا يجحد الوجوب، فهذا يختص بالصلاة، يكفر إذا تركها، ولولم يجحد وجوبها في أصح قولي العلماء. أما الزكاة فلا يكفر إذا كان يؤمن بوجوبها، لكن يتساهل ويبخل بها، هذا متوعد بالنار، وجاء في الحديث الصحيح عن النبي ﷺ أنه يعذب يوم القيامة بالمال الذي بخل بزكاته، يعذب به يوم القيامة من نقود تحمى عليه، وهكذا الإبل والبقر والغنم، يبطح لها بقاع قرقر تمر عليه تطؤه بأخفافها وتعضه بأفواهها وتطؤه الإبل البقر والغنم بأظلافها تنطحه بقرونها، كلما مرت عليه أخراها عادت عليه أولاها -نسأل الله العافية- في يوم كان مقداره خمسين ألف سنة، ثم يرى سبيله إما إلى الجنة، وإما إلى النار، فقوله ﷺ: ثم يرى سبيله إما إلى الجنة، وإما إلى النار يدل على عدم الكفر، يدل على أنه قد يدخل الجنة، قد يعفى عنه ويدخل الجنة، فدل على أنه ليس بكافر إذا كان تركها بخلاً لا جحدًا للوجوب. وهكذا صوم رمضان إذا ترك الصوم تساهلًا، ولم يجحد وجوبه، وهكذا الحج، أما من جحد وجوب الزكاة أو جحد وجوب الصيام، مثل صيام رمضان أو جحد وجوب الحج مع الاستطاعة هذا يكفر؛ لأنه مكذب لله ولرسوله، نسأل الله العافية، فهذا يكفر عند الجميع؛ لأنه بجحده الوجوب قد كذب الله ورسوله، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14179/حكم-من-يودي-بعض-اركان-الاسلام-دون-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70507.mp3","categories":["حكم الصلاة وأهميتها","مسائل متفرقة في العقيدة"]},{"id":15648,"question":"أسأل سماحتكم عمن أفطر في نهار رمضان عامدًا متعمدًا، هل يقضي ذلك اليوم؟ وهل هناك كفارة؟","title":"حكم من أفطر في رمضان بغير عذر","answer":"الجواب: عليه التوبة إلى الله؛ لأنها جريمة، ومنكر عظيم، وكبيرة من الكبائر؛ فعليه التوبة إلى الله، وعليه القضاء، وليس عليه كفارة، الكفارة في الجماع خاصة في نهار رمضان، أما الفطر بالأكل والشرب ونحو ذلك؛ ليس فيه كفارة، بل فيه التوبة إلى الله، والندم والعزم ألا يعود في ذلك، وكثرة الاستغفار مع القضاء، قضاء اليوم الذي أفطره.  أما حديث: من أفطر في يوم من رمضان عامدًا لم يقضه صيام الدهر وإن صامه هذا حديث ضعيف عند أهل العلم، ليس بصحيح، حديث مضطرب ليس بصحيح، والصواب: أنه يقضي يومًا فقط، مع التوبة إلى الله ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14184/حكم-من-افطر-في-رمضان-بغير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70512.mp3","categories":["حكم الصلاة وأهميتها","قضاء الصيام","الرقائق"]},{"id":15760,"question":"إنني -ولله الحمد- أصلي جميع الصلوات في المسجد إلا الفجر، فإني دائمًا أصليها بعد شروق الشمس؛ والسبب في ذلك أنني أكون نائمًا، فهل أنا آثم على ذلك؟أفتوني مأجورين، وصاحب هذه الرسالة هو المستمع عبدالله عودة من الأردن، عمان.","title":"هل يأثم مَن أخَّر الفجر إلى بعد الشروق؟","answer":"الجواب: يجب عليك يا عبدالله أن تصلي في المسجد في الفجر مع الجماعة، مثل بقية الصلوات، ولا يجوز لك أن تؤخرها إلى طلوع الشمس، بل هذا منكر عظيم، بل كفر أكبر عند جمع من أهل العلم، نسأل الله العافية، إذا عزمت عليه، وصممت عليه، فالواجب عليك أن تتقي الله، وأن تصلي مع الناس الصلاة في وقتها، الفجر وغيره، وعليك أن تتقي الله بعدم السهر حتى تقوم إلى الصلاة، وعليك أيضًا أن تستعين بالساعة التي تعينك على ذلك، أو ببعض أهل بيتك حتى يوقظونك، أو توقت الساعة على قرب الفجر حتى تقوم؛ لأنها من أسباب العون على هذا الخير الساعة الدقاقة...، توقتها على قبل الفجر حتى تستعين بها على ذلك. فالواجب عليك أن تتخذ الأسباب التي تعينك على أن تصلي مع الجماعة الفجر وغيره، ولا يجوز لك أبدًا أن تتساهل في هذا الأمر، بل هذا من صفات أهل النفاق، هذا العمل من صفات أهل النفاق، نعوذ بالله، قال تعالى: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى[النساء:142] فالواجب عليك الحذر من صفاتهم، وقال فيهم سبحانه: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ وَلَنْ تَجِدَ لَهُمْ نَصِيرًا[النساء:145] وقال ﷺ: أثقل الصلاة على المنافقين صلاة العشاء وصلاة الفجر، ولو يعلمون ما فيهما لأتوهما ولو حبوًا. فاتق الله، واحذر التساهل بشيء من الصلوات الخمس، الفجر وغيرها، وعليك أن تتقي الله في أدائها في المسجد في الجماعة، مع إخوانك؛ لقول النبي ﷺ: من سمع النداء فلم يأتِ فلا صلاة له إلا من عذر قيل لابن عباس: «ما هو العذر؟ قال: خوف أو مرض» وجاءه ﷺ رجل أعمى وقال: «يا رسول الله، ليس لي قائد يقودني إلى المسجد فهل لي من رخصة أن أصلي في بيتي؟ فقال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب رجل أعمى ليس له قائد يقال له: أجب؟! كيف بهذا البصير الطيب الصحيح؟! فالواجب على كل مسلم أن يتقي الله، وأن يصلي في الجماعة جميع الأوقات، وأن يحذر تأخيرها عن وقتها، حتى ولو كان مريضًا يصليها في الوقت، لا يؤخرها عن الوقت ولو كان مريضًا، في البيت يصليها في وقتها، فكيف بالصحيح؟! نسأل الله السلامة والعافية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14347/هل-ياثم-من-اخر-الفجر-الى-بعد-الشروق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74107.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15779,"question":"ما حكم الذي لا يصلي إلا الجمعة فقط؟","title":"حكم من يصلي الجمعة ويترك بقية الصلوات","answer":"الجواب: الصواب أنه يكفر بذلك، من ترك الصلوات كفر، وإن لم يجحد وجوبها في أصح قولي العلماء، أما إن جحد وجوبها كفر عند الجميع، إذا قال: الصلاة ما هي بواجبة كفر عند الجميع، أما إذا كان يتساهل يصلي وقتًا، ويدع وقتًا، أو يصلي الجمعة فقط، أو في رمضان فقط، فهذا كافر في أصح قولي العلماء؛ لقول النبي ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة والكفر والشرك المعرف هو الكفر الأكبر، والشرك الأكبر؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر كلها أحاديث صحيحة؛ ولأنه ﷺ لما سأله المسلمون عن الأمراء الذين توجد لهم بعض المعاصي: «هل يقاتلونهم؟ قال: لا؛ ما أقاموا فيكم الصلاة وفي اللفظ الآخر قال: إلا أن تروا كفرًا بواحًا، عندكم من الله فيه برهان فدل على أن ترك الصلاة يعتبر من الكفر البواح، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14367/حكم-من-يصلي-الجمعة-ويترك-بقية-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74204.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15859,"question":"هل على الإنسان الذي كان لا يصلي سابقًا، هل عليه قضاء الأوقات التي لم يصلها سابقًا؟ وهل يجوز القضاء في الأوقات الخمسة التي نهى النبي ﷺ عن الصلاة فيها؟","title":"هل يلزم تارك الصلاة قضاء الأوقات التي لم يصلها؟","answer":"الجواب: ليس عليه قضاء، إذا تاب اللهُ عليه، ليس عليه قضاء، إذا كان لا يصلي ثم تاب اللهُ عليه ليس عليه قضاء، التوبة تكفي، تجب ما قبلها، والحمد لله. والذي عليه قضاء الصلاة يقضيها ما لها وقت نهي، يقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك فإذا نسي -مثلًا- صلاة الظهر، ولم يذكرها إلا بعد العصر يبادر بقضائها، أو نسي صلاة العشاء فلم يذكرها إلا بعد صلاة الفجر يبادر بقضائها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14450/هل-يلزم-تارك-الصلاة-قضاء-الاوقات-التي-لم-يصلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57621.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":15882,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين آثر فيها عدم ذكر اسمه يسأل سؤالًا فيقول فيه: أنا شاب وعازب، في فترة شبابي الأولى كنت أصلي فترة، وأقطع الصلاة، والحمد لله، الآن تبت إلى الله وحده، إنني لا أقطع الصلاة، ومحافظ عليها في أوقاتها، فهل أقضي ما فاتني في تلك الفترة التي ذكرتها لكم، أو كيف يكون التوجيه؟جزاكم الله خيرًا.","title":"حكم قضاء الصلاة لمن كان يتركها أحيانًا","answer":"الجواب: الحمد لله الذي منَّ عليك بالتوبة، وهذه من نعم الله العظيمة، فعليك أن تشكر الله على ذلك، وأن تلزم التوبة، وتستقيم عليها.  وأما ما فات في بعض الصلوات التي أضعتها، فإنه لا قضاء عليها على الصحيح؛ لأن ترك الصلاة ولو كسلًا كفر أكبر على الصحيح، فإذا تاب العبد من ذلك ورجع إلى الله -جل وعلا- كفاه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14475/حكم-قضاء-الصلاة-لمن-كان-يتركها-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74502.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":15893,"question":"من محافظة مطروح، المستمع محمد علي من جمهورية مصر العربية، رسالة يقول فيها: لي إخوة ذكور وإناث، آمرهم بالصلاة، ولكنهم يتهاونون فيها، فهل عليّ إثم؟ وهل عليّ أن أغير هذا الأسلوب؟ علمًا بأن والدي موجود، وأنا أعتقد أن ولاية الأمر له. جزاكم الله خيرًا.","title":"ما واجب الأب تجاه أبنائه في أمرهم بالصلاة؟","answer":"الجواب: عليك أن تستمر في النصيحة، وأن تشجع الوالد على القيام بما يجب عليه من أمرهم بالمعروف، ونهيهم عن المنكر، وللوالد ضربهم إذا بلغوا العشر فأكثر، كما قال النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فالوالد عليه واجب عظيم أن يعتني بهم، وأن يتكلم عليهم، وينصحهم، ويأمرهم وينهاهم، فإذا لم ينفع الكلام وجب عليه أن يؤدبهم ويضربهم حتى يستقيموا، وعليك أن تكون عونًا له في ذلك بالكلام الطيب، والأسلوب الحسن، فالله يقول -جل وعلا-: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى[المائدة:2] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71] ويقول النبي ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه؛ وذلك أضعف الإيمان.\nفالواجب على الوالد أن يعتني بهذا الأمر إذا كان الأولاد بلغوا عشرًا فأكثر أن يعتني بهم، وأن يؤدب من تخلف، ولو بالضرب الذي يردعه وأمثاله من دون أن يكون فيه خطر، يعني: ضربًا غير مبرح، ضربًا مناسبًا يحصل به المقصود. أما إذا كانوا قد بلغوا الحلم، فالأمر أشد، إذا كانوا قد بلغوا الحلم فالأمر أشد إن لم يستقيموا يرفع أمرهم إلى المحكمة حتى تستتيبهم فإن تابوا وإلا وجب قتل من لم يتب؛ لأن ترك الصلاة كفر أكبر، ومن لم يتب من تركها وجب أن يقتل مرتدًا في أصح قولي العلماء، وإن لم يجحد وجوبها. فالمقصود: أن الأمر عظيم، فعلى الوالد وعليكم أنتم أيها الأولاد أن تساعدوه في نصيحة الأبناء والبنات الذين لا يصلون، وهم قد بلغوا العشر فأكثر، وعلى الوالد أن يعتني بذلك أكثر لأنه المسؤول الأول، وعليه أن يضرب من تخلف الضرب المناسب الذي يحصل به المقصود.  أما إذا بلغوا الحلم فالأمر أشد، يزيد في ضربهم وتأديبهم، وإذا لم يحصل المقصود رفع بأمرهم إلى ولي الأمر إلى المحكمة الشرعية حتى تستتيبهم، فإن تابوا وإلا وجب قتلهم على ترك الصلاة، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14486/ما-واجب-الاب-تجاه-ابناىه-في-امرهم-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74513.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":15895,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها جمعًا من الأسئلة في أحدها يقول: إذا تزوج الرجل بامرأة وهو لا يحافظ على الصلاة حفاظًا تامًا، بمعنى أنه يصلي فرضًا، ويترك آخر، ثم إنه بعد ذلك تاب وحافظ على الصلاة، هل يلزمه إعادة كتابة العقد -عقد الزواج- أم أن ما مضى صحيح؟جزاكم الله خيرًا.","title":"يجدد عقد الزواج للمتساهل في أداء الصلاة","answer":"الجواب: إذا كان الزوج لا يصلي بعض الأحيان أما الزوجة فهي محافظة، فإن عليه أن يعيد العقد في أصح قولي العلماء؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء.  وذهب الأكثرون: إلى أنه لا حاجة إلى إعادة العقد إذا كان لا يجحد وجوبها، بل يعلم أنها فرض عليه، ويؤمن بذلك، ولكنه يتساهل في بعض الأحيان، يقولون: لا يلزمه تجديد العقد؛ لأنه لا يكون كافرًا كفرًا أكبر بذلك، ولكنه كفر أصغر. والصواب: أنه كفر أكبر، هذا هو الأصح من قولي العلماء؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، ولأدلة أخرى تدل على كفر تارك الصلاة وإن لم يجحد وجوبها. فعليه أن يعيد العقد إذا كانت المرأة تصلي ومحافظة، أما إذا كانت مثله فلا إعادة، فالعقد صحيح؛ لأن الرسول ﷺ أقر الكفار على عقودهم لما أسلموا، لكن إذا كانت هي محافظة، وهو ليس محافظ يعاد العقد أو بالعكس إن كان محافظًا، هو وهي لا تحافظ يعاد العقد، يجدد العقد بعد التوبة، ممن كان غير محافظ عليه أن يجدد العقد ولو فيما بينهم من دون حاجة إلى القاضي أو إلى المأذون، إذا جددوا في البيت بينهم بحضرة شاهدين، وقال الولي زوجتك، وقال له: قبلت، على مهر ولو قليلًا، بحضرة شاهدين عدلين كفى، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14488/يجدد-عقد-الزواج-للمتساهل-في-اداء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74515.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":15926,"question":"من ضمن أسئلة هذا السائل يقول: التارك للصلاة هل يخلد في النار؟","title":"هل تارك الصلاة يخلد في النار؟","answer":"الجواب: التارك للصلاة إن كان قد جحد وجوبها كفر عند جميع أهل العلم، ويخلد في النار إذا مات على ذلك، أما إذا كان لا، يعلم أنها واجبة، ولكن يتساهل ويتركها بعض الأحيان، فهذا قد أتى ذنبًا عظيمًا، وكبيرة عظيمة؛ لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله ﷺ: رأس الأمر الإسلام وعموده الصلاة ولأن الله يقول سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]. فالتثاقل عنها والكسل من صفات المنافقين، لكن إذا تركها جحدًا لوجوبها كفر عند الجميع، وصار مخلدًا في النار، إذا مات على ذلك، أما إذا تركها وهو يعلم أنها واجبة، ولكن يتركها تكاسلًا وتهاونًا فهذا عند الأكثرين لا يكفر كفرا أكبر، يكون كفرًا أصغر، وذهب جمع من أهل العلم إلى أنه يكفر كفرًا أكبر؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فالواجب الحذر من ذلك، نسأل الله العافية والسلامة. المقدم: اللهم آمين، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14521/هل-تارك-الصلاة-يخلد-في-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57716.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":15954,"question":"ما حكم الإسلام في الذي يصلي ولا يصوم؟","title":"حكم من يصلي ولا يصوم؟","answer":"الجواب: حكمه أنه عاصٍ يجب أن يتوب إلى الله، وإذا علم به ولاة الأمور وجب أن يؤدب ويضرب حتى يتأدب، ولا يعود، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14572/حكم-من-يصلي-ولا-يصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74615.mp3","categories":["حكم الصلاة وأهميتها","مسائل متفرقة في الصيام"]},{"id":16066,"question":"يسأل في سؤال آخر فيقول: كيف يقضي المسلم صلاته التي لم يؤدها منذ بلوغه، والتي فاتت عليه، وهل يحاسب على تركها؟ جزاكم الله خيرًا.","title":"ما حكم من ترك الصلاة فترة من الزمن؟","answer":"الجواب: عليه أن يتوب إلى الله من ذلك، وليس عليه قضاء، ومتى تاب توبة صادقة؛ محا الله عنه ذلك الكفر، وذلك الضلال، يقول الله -جل وعلا-: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فمن تاب صادقًا أفلح، ويقول النبي ﷺ: التوبة تمحو ما قبلها والتائب من الذنب كمن لا ذنب له.  والصحيح أن تارك الصلاة تكاسلًا كافر كفرًا أكبر، أما إن كان تركها جحدًا لوجوبها؛ فإنه يكون كافرًا بإجماع المسلمين، والكافر إذا أسلم لا يؤمر بالقضاء لما ترك من صلاة، وصوم، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14702/ما-حكم-من-ترك-الصلاة-فترة-من-الزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74902.mp3","categories":["حكم الصلاة وأهميتها","قضاء الصيام","الرقائق"]},{"id":16087,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المرسل أبو عمرو عزيز أحمد كلبي، أبو عمرو يسأل جمعًا من الأسئلة من بينها سؤال يقول: هناك أحاديث لرسول الله ﷺ يبين فيها أن تارك الصلاة كافر، فهل هذا الكفر يخرج من الملة؟ جزاكم الله خيرًا.","title":"ما معنى الكفر في أحاديث تارك الصلاة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد.  فالصلاة عمود الإسلام، وأعظم أركان الإسلام بعد الشهادتين، وتركها كفر أكبر عند جميع العلماء إذا جحد وجوبها، وإن صلى، إذا جحد وجوبها؛ كفر بإجماع المسلمين؛ لأنه مكذب لله ولرسوله، الله يقول سبحانه: وَأَقِيمُوا الصَّلاةَ [البقرة:43] ويقول -جل وعلا-: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول -جل وعلا-: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45]. وإن تركها، ولم يجحد وجوبها، أو ترك بعضها كفر أيضًا في أصح قولي العلماء، سواء ترك الخمس، أو ترك الظهر وحدها، أو العصر وحدها، أو الفجر وحدها، أو الجمعة وحدها يكفر بذلك؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، والكفر والشرك إذا أطلق المعرف، فهو الكفر الأكبر، هذا هو أصح قولي العلماء في هذا. وقال -عليه الصلاة والسلام-: العهد الذي بيننا، وبينهم الصلاة، فمن تركها فقد كفر أخرجه الإمام أحمد، وأهل السنن بإسناد صحيح عن بريدة . وسأل الصحابة النبي ﷺ عن الأمراء الذين لا يقيمون الصلاة... الذين يؤخرون الصلاة عن أوقاتها، قالوا: أفنقاتلهم يا رسول الله؟ قال: لا، ما أقاموا فيكم الصلاة في لفظ: إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان فدل على أن الأمراء -الملوك والخلفاء- الذين لا يقيمون الصلاة كفرهم كفر بواح، أي: لا شبهة فيه. فالواجب على جميع المسلمين من الأمراء، والملوك، والوزراء، وغيرهم، رجالًا ونساء، الواجب على الجميع العناية بالصلاة، والمحافظة عليها في أوقاتها، فمن تركها، وأعرض عنها، فقد كفر كفرًا أكبر في أصح قولي العلماء. وقال جماعة من أهل العلم: إنه كفر دون كفر، وظلم دون ظلم، إذا كان يقر بوجوبها، ولا يجحده، ولكن هذا القول ضعيف. والصواب أنه كفر أكبر، فيجب الحذر من ذلك، ويجب التواصي بالمحافظة عليها، وإقامتها في الجماعة في أوقاتها، يجب على الرجال أن يقيموها في الجماعة في بيوت الله، جميع الأوقات الخمسة: الفجر الظهر والعصر المغرب والعشاء، كثير من الناس قد يتساهل بالفجر، فيصليها في البيت، أو بعد الشمس، وهذا منكر عظيم، يجب الحذر من ذلك، والتواصي بترك ذلك؛ فإن هذا من عمل المنافقين. وهكذا النساء يجب عليهن أن يصلوها في الوقت، يجب على النساء أن يصلينها في الوقت، جميع الأوقات الخمسة، مع المحافظة على الطمأنينة، والخشوع، فإن الصلاة عمود الإسلام، من حفظها؛ حفظ دينه، ومن ضيعها؛ فهو لما سواها أضيع.  وثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: من حافظ على الصلاة؛ كانت له نورًا وبرهانًا ونجاةً يوم القيامة، ومن لم يحافظ عليها؛ لم يكن له نور، ولا برهان، ولا نجاة، وحشر يوم القيامة مع فرعون، و هامان، وقارون، وأبي بن خلف خرجه الإمام أحمد -رحمه الله- بإسناد صحيح عن عبد الله بن عمرو بن العاص، رضي الله عنهما. وهذا الحديث يبين أن تارك الصلاة قد أتى جريمةً عظيمة، وأنه كافر، يحشر مع فرعون، وقارون، وأبي بن خلف، هؤلاء من صناديد الكفرة، ومن رؤساء الكفرة، ووجه حشره معهم؛ لأنه إن ضيعها من أجل الرئاسة، والملك؛ صار شبيهًا بفرعون، شغله ملكه، وكبره عن اتباع الحق، وإن شغله عن الصلاة، الوزارة، والوظيفة شابه هامان وزير فرعون؛ فيحشر معه يوم القيامة، نسأل الله العافية. وإن شغله عن الصلاة المال والشهوات شابه قارون الذي خسف الله به وبداره الأرض بسبب كبره، واشتغاله بالمال عن طاعة الله ورسوله، وإن شغلته التجارة، والبيع والشراء عن الصلاة شابه أبي بن خلف تاجر أهل مكة من الكفرة الذي قتل يوم أحد، قتله النبي ﷺ بنفسه. فالواجب الحذر من التساهل بالصلاة، وقد أخبر الله سبحانه في كتابه العظيم أن التكاسل عنها، والتثاقل عنها من صفات أهل النفاق، قال تعالى في سورة النساء: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142] هذه من صفاتهم الخبيثة، وقال -جل وعلا- في سورة التوبة: وَمَا مَنَعَهُمْ أَنْ تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ إِلَّا أَنَّهُمْ كَفَرُوا بِاللَّهِ وَبِرَسُولِهِ وَلا يَأْتُونَ الصَّلاةَ إِلَّا وَهُمْ كُسَالَى وَلا يُنفِقُونَ إِلَّا وَهُمْ كَارِهُونَ [التوبة:54]. فالواجب الحذر، والعناية بالصلاة، والمحافظة عليها في أوقاتها من الرجال والنساء، ويجب الحذر بوجه خاص من تضييع صلاة الفجر في الجماعة بسبب السهر، يجب الحذر من السهر الذي يحملك على ترك الصلاة في الوقت، أو في الجماعة، وهذا عام للرجال والنساء، يجب الحذر من ترك الصلاة كلها، والحذر من إضاعتها في الجماعة في حق الرجل، والحذر بوجه أخص من إضاعة صلاة الفجر من الرجال، والنساء جميعًا؛ لأنه تشبه ظاهر بأهل النفاق، ويجب التواصي بهذا؛ لأن الله سبحانه يقول: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] ويقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول النبي ﷺ: الدين النصيحة، الدين النصيحة، الدين النصيحة، قيل: لمن يا رسول الله؟! قال: لله، ولكتابه، ولرسوله، ولأئمة المسلمين وعامتهم. فمن النصيحة لأهل بيتك ولإخوانك أن تحذرهم من السهر، والعكوف على التلفاز، أو الدش، أو غير ذلك. أما السهر في طاعة الله، التهجد قراءة القرآن في مطالعة العلم، في الدراسة؛ فلا بأس سهرًا قليلًا، لا يحمل على ترك الصلاة في الجماعة، إذا سهر قليلًا في العلم في طاعة الله ورسوله، في دراسة العلم، في التهجد، هذا أمر مطلوب، وهو مأجور، لكن يحذر أن يكون هذا السهر يشغله عن الفريضة، وقد أوصى النبي ﷺ أبا هريرة، و أبا الدرداء أن يوترا في أول الليل لما كانا يدرسان العلم، فيشق عليهما القيام في آخر الليل. لكن من قوي أن يقوم في آخر الليل؛ فلينم مبكرًا؛ حتى يقوم آخر الليل، ويصلي من الليل، ويصلي صلاة الفجر في الجماعة حتى يجمع بين الخير كله، نسأل الله لنا ولجميع المسلمين التوفيق والهداية، وصلاح النية والعمل، ولا حول ولا قوة إلا بالله.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14722/ما-معنى-الكفر-في-احاديث-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_712/nour_71201.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":16088,"question":"من سوريا الرقة السائل يوسف إبراهيم يقول: سماحة الشيخ! أسأل عن قضاء الصلاة في حال كون الإنسان لم يكن يصلي، وبلغ من العمر بعد سن البلوغ، والتكاليف، وهداه الله إلى الصلاة؛ هل يجب عليه أن يقضي ما فاته من صلاة؟ أم أن حديث الرسول ﷺ: الإسلام يجب ما قبله يشمله؟","title":"ما الواجب على من تاب من ترك الصلاة؟","answer":"الجواب: نعم، إذا كان الإنسان لا يصلي، ثم هداه الله؛ فالتوبة تجب ما قبلها، والإسلام يجب ما قبله، وهكذا المرأة إذا كانت لا تصلي، ثم هداها الله؛ ليس عليهما قضاء، التوبة تكفي، والحمد لله. يقول ﷺ: الإسلام يجب ما قبله، والتوبة تجب ما قبلها فمن كان لا يصلي؛ فالواجب عليه التوبة إلى الله، والرجوع إلى الله، والإنابة إليه، وليس عليه قضاء ما فات.. والحمد لله. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14728/ما-الواجب-على-من-تاب-من-ترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57908.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":16134,"question":"تسأل أختنا عن الشخص الذي يصلي بعض الأيام صلاة الفجر بعد طلوع الشمس، أو يصلي صلاة العصر في البيت، ما حكم صلاته؟ وهل تجب مقاطعته؟ أو تجب نصيحته؟ أرشدونا لذلك، ولا سيما إذا كان من المقربين لنا؟","title":"حكم من يؤخر الصلاة عن وقتها","answer":"الجواب: الواجب على كل مسلم ومسلمة المحافظة على الصلوات الخمس في أوقاتها، يجب على جميع المسلمين المكلفين من رجال، ونساء أن يحافظوا على الصلاة في وقتها، الفجر في وقتها قبل الشمس، والظهر في وقتها بعد الزوال، والعصر في وقتها بعد أن يصير ظل كل شيء مثله، بعد فيء الزوال قبل أن تصفر الشمس، والمغرب بعد غروب الشمس، والعشاء بعد غروب الشفق، والفجر بعد طلوع الفجر، وقبل الشمس لابد من هذا. يجب على جميع المسلمين المكلفين المحافظة على هذه الصلوات الخمس؛ لأنها عمود الإسلام، من تركها؛ كفر، نعوذ بالله من ذلك، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ويقول -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول: إنه يلي عليكم أمراء، فتعرفون وتنكرون، فقيل: يا رسول الله! أفلا نقاتلهم؟ قال: لا، ما أقاموا فيكم الصلاة دل على أن إقامة الصلاة لابد منها، عمود الإسلام، من تركها كفر، ولا يجوز تأخير الفجر إلى بعد طلوع الشمس، ولا تأخير العصر إلى أن تصفر الشمس، بل يجب أن تصليها في الوقت، والصحيح: أنه إذا ترك، ولو صلاة واحدة عمدًا حتى خرج وقتها؛ كفر. نسأل الله العافية، فكيف إذا ترك الصلوات الكثيرة؟ أما إن جحد وجوبها؛ كفر عند جميع العلماء، إذا جحد وجوب الصلاة؛ كفر، ولو فعلها، ولو صلى، إذا قال: ما هي بواجبة؛ كفر عند الجميع، لكن إذا قال: إنها واجبة، وفرض، ولكن يتساهل، يتكاسل، الأكثرون: على أنه لا يكفر كفرًا أكبر، الأكثرون من أهل العلم على أنه لا يكفر كفرًا أكبر، ولكن كفرًا أصغر، ويرونها كبيرة عظيمة، لكن لا يكفر كفرًا أكبر، ولكن يستتاب، فإن تاب، وإلا قتل حدًا، لقول الله تعالى: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على أنه من لم يتب لا يخلى سبيله، بل يقتل، لكن الجمهور على أنه يقتل حدًا، على أنه عاصي، قد أتى كبيرة عظيمة.  والقول الثاني: يقتل كافرًا -والعياذ بالله- لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. ويجب على المؤمن أن يصلي في الجماعة، المرأة تصلي في البيت؛ لأنه خير لها، وأستر لها، لكن الرجل يجب أن يصلي في المسجد مع الناس، الفجر والظهر والعصر والمغرب والعشاء، يقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس : ما هو العذر؟ قال: مرض، أو خوف. وجاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب هكذا أمره النبي ﷺ قال: أجب، وهو أعمى ما له قائد يتلمس الجدارن يدور من يقوده، ومع هذا يجب عليه أن يذهب إلى المسجد، فكيف بالبصير المعافى؟! ويقول ﷺ: لقد هممت أن آمر بالصلاة، فتقام، ثم آمر برجل فيؤم الناس، ثم أنطلق برجال معهم حزم من حطب إلى قوم لا يشهدون الصلاة، فأحرق عليهم بيوتهم هم بهذا وهو لا يهم إلا بالحق -عليه الصلاة والسلام- هم أن يحرق عليهم بيوتهم؛ لأنهم ما يحضروا في الجماعة مع المسلمين، وفي رواية أحمد: لولا ما في البيوت من النساء والذرية لحرقتها عليهم. فالمقصود: أن هذا يدل على وجوب أداء الصلاة في الجماعة، وأنه لا يجوز للمسلم أن يتخلف عنها، لا الفجر، ولا غيره، بل التخلف عن الجماعة من صفات المنافقين، التخلف عن الجماعة في المسجد من صفات أهل النفاق، قال تعالى: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142] الآية، وقال النبي ﷺ: أثقل الصلاة على المنافقين صلاة العشاء، وصلاة الفجر، ولو يعلمون ما فيهما لأتوهما ولو حبوا. فالذي يتكاسل عن صلاة الفجر في الجماعة قد تشبه بأعداء الله المنافقين، وترك واجبًا عظيمًا، فالواجب عليه تقوى الله، وعلى أهله أن يناصحوه، وعلى أبيه أن يقوم عليه إن كان عنده أب، أو جد، أو أخ كبير، يلزمه بذلك، ويؤدبه حتى يصلي في الجماعة، يقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع. فالولد الذي تخلف عن الجماعة، وقد بلغ عشرًا فأكثر يؤدبه أبوه، وهكذا أخوه الكبير، فإذا كان قد بلغ الحلم؛ صار الأمر أعظم، نسأل الله للجميع الهداية، ولا حول ولا قوة إلا بالله، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، سماحة الشيخ! ختمت سؤالها بقولها: هل نقاطعه، أم نستمر على نصيحته؟ الشيخ: اعملوا بالأصلح -إن كان الأصلح المواصلة- لعل الله يهديه بأسبابكم، فواصلوا النصيحة، واستعينوا على ذلك بمن ترون من خواص أقاربه، وأصدقائه لعله ينفع، فإن أصر، ولم تنفع النصيحة؛ فالواجب أن يهجر، وأن يرفع أمره لولي الأمر، للمحكمة، أو للهيئة حتى يعامل بما يستحق من العقوبة، يرفع بأمره من جهة ولي الأمر القاضي المحكمة الهيئة إذا كان في بلدكم هيئة حتى تحضره، وحتى تقيم عليه أمر الله، نعم. المقدم: جزاكم الله خيرًا، إذًا ترجحون سماحتكم النصيحة؟ الجواب: إذا أجدت، وأفادت إذا رجي إفادتها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14806/حكم-من-يوخر-الصلاة-عن-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80406.mp3","categories":["حكم الصلاة وأهميتها","صلاة الجماعة"]},{"id":16150,"question":"يقول: أسكن مع أبناء عمي، ونأكل ونشرب، والأسرة كذلك نأكل ونشرب جميعًا، لكنهم لا يصلون، نصحتهم كثيرًا فلم يستجيبوا لي، كيف يكون العمل؟ جزاكم الله خيرًا.","title":"حكم الأكل والشرب مع من لا يصلون","answer":"الجواب: الواجب عليك نصيحتهم، وإنكار المنكر، هذا منكر عظيم؛ لأن الصلاة عمود الإسلام، وهي الركن الأعظم من أركان الإسلام الخمسة بعد الشهادتين، فيقول فيها النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر، الصلاة أمرها عظيم.  فالواجب نصيحتهم، والإنكار عليهم، فإن استجابوا فالحمد لله، وإلا فلا تجالسهم، لكن لا مانع من تكرار النصيحة إذا طمعت في هدايتهم، تكرر النصيحة مع عدم اتخاذهم أصحابًا، وجلساء، لكن تكرر النصيحة، والدعوة إلى الله؛ لعل الله يهديهم بأسبابك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14805/حكم-الاكل-والشرب-مع-من-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75002.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":16165,"question":"هذا سائل للبرنامج رمز لاسمه بـ (أ. أ) يقول: عندي اثنان من إخواني لا يصلون، أخلاقهم سيئة مع الجميع، حتى مع الوالد والوالدة، وهم منعزلون عنا، فلا يخالطوننا، وما حكم مقاطعتهم أنا وإخوتي لهم؟ جزاكم الله خيرًا يا سماحة الشيخ.","title":"واجب الأب تجاه من يترك الصلاة من أولاده","answer":"الجواب: إذا كان أخواك لا يصليان؛ فالواجب نصيحتهما، والحرص على توجيههما إلى الخير، وعلى والدك أن يجتهد في نصيحتهما، وأنتم معه أيضًا؛ لعل الله يهديهما بأسبابكم، وإن استطاع أبوك تأديبهما؛ أدبهما، يقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فإذا كان ابن عشر يضرب؛ فالكبير يضرب، فإن تاب، وإلا يقتل قتلًا. فإذا كان أبوك الذي لا يستطيع، وأنتم لا تستطيعون؛ ارفعوا الأمر إلى الهيئة، أو إلى المحكمة حتى يقام عليهم أمر الله، فالذي لا يصلي يستتاب، فإن تاب وإلا قتل؛ يقول النبي ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ويقول ﷺ: نهيت عن قتل المصلين. فدل على أن من لا يصلي؛ يقتل، والله يقول -جل وعلا-: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُم [التوبة:5]، دل على أن الذي لا يؤدي الصلاة لا يخلى سبيله، بل يقتل، ويقول ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول ﷺ: رأس الأمر الإسلام، وعموده الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. المقصود: أن الواجب عليكم، وعلى الوالد العناية بهذا، نصيحتهما، وتوبيخهما، والحرص على هدايتهما، فإن استقاما وإلا ارفعوا أمرهما إلى الهيئة حتى يؤدبا؛ لعلهما يصليان، فإن لم يصليا؛ يرفعا إلى المحكمة حتى يجري عليهما حكم الله بالاستتابة، فإن تابا وإلا قتلا.","link":"https://binbaz.org.sa/fatwas/14829/واجب-الاب-تجاه-من-يترك-الصلاة-من-اولاده","audio":"","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":16213,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول في أسئلته في هذه الرسالة: إذا كان الإنسان لا يصلي، ولا يصوم في فترة من حياته، ثم تاب، وأقام الصلاة، وصام رمضان، هل يلزمه قضاء الصلاة، والصيام؟ أم لا؟","title":"حكم قضاء الصلاة والصيام على من تاب من تركهما","answer":"الجواب: الصواب أنه لا يلزمه ذلك، والتوبة تكفي، والحمد لله، التوبة الصحيحة النصوح تكفي، والحمد لله يقول النبي ﷺ: التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله وتارك الصلاة يكفر بذلك، فإذا أسلم، وتاب؛ فليس عليه إعادة كسائر الكفار، إذا أرتد كسائر من ارتد، ثم رجع لا يقضي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14893/حكم-قضاء-الصلاة-والصيام-على-من-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75110.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":16250,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحرف (س) من الرياض، أخونا عنون رسالته بقوله: الموضوع: تكاليف في أوقات الصلاة، يقول: مع الأذان للصلاة يكلفونني بالمشاوير، ومليت كثيرًا من هذه التكاليف في وقت الأذان، وكثيرًا من المرات خرجت عن صوابي، وضاق خلقي؛ لأنهم لا يخرجون إلا مع الأذان، أو وقت الصلاة، كنت دائمًا أشكو لهم هذا، وأبين لهم أن الصلاة لها فضل كبير إذا كانت مع الجماعة، ولا يجوز تأجيلها لغرض من الأغراض التي يمكن تأخيرها، لم يستجيبوا لي، وجهوني ووجهوا أمثال هؤلاء، جزاكم الله خيرًا، وأحسن إليكم، والواقع أمامي رسالة أخرى -سماحة الشيخ- تعرض نفس الغرض، فتوجيهكم، وفقكم الله، وجزاكم خيرًا.","title":"حكم مَن يُلزم بالعمل في أوقات الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا شك أن الواجب على المسلمين العناية بالصلاة، وأن تؤدى في وقتها من الرجال والنساء جميعًا؛ لأنها عمود الإسلام، وأعظم الأركان بعد الشهادتين، ولأنها أول شيء يحاسب عليه العبد يوم القيامة، فإن صلحت له الصلاة؛ صلح له بقية عمله، وإن ردت عليه صلاته؛ رد عليه بقية عمله، ولا حول ولا قوة إلا بالله. فالواجب على أهل البيت، وعلى الموظفين في أي دائرة أن يتقوا الله في ذلك، وأن يتعاونوا على أداء الصلاة في وقتها في الجماعة، وأن يجيبوا المؤذن، وألا يشغل بعضهم بعضًا بأشياء تعوقهم عن الصلاة في الجماعة، أو عن الصلاة في وقتها، هذا يعم الرجال والنساء. الواجب على أهل البيت أن يجتهدوا في أداء الصلاة في وقتها، والحرص على ذلك، وعلى الرجال أن يصلوها في الجماعة، إذا سمعوا النداء؛ بادروا؛ لقوله ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس : ما هو العذر؟ قال: خوف، أو مرض». وثبت عنه ﷺ: «أنه جاءه رجل أعمى، فقال: يا رسول الله! ليس لي قائد يقودني للمسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب. خرجه مسلم في الصحيح. فإذا كان أعمى، ليس له قائد، يقال له: أجب .. يصلي في الجماعة في المسجد، فكيف بغيره من الناس؟! فالواجب على جميع الرجال المستطيعين أن يصلوا في المسجد، وأن يجيبوا المؤذن، وأن يخرجوا من بيوتهم، ومنازلهم، ودوائرهم إلى المساجد، إلا من عذره الله، كالمريض، فالمريض يصلي على حسب حاله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. يقول ابن مسعود  -الصحابي الجليل-: \"لقد رأيتنا، وما يتخلف عنها\" يعني: الصلاة في الجماعة \"إلا منافق معلوم النفاق، أو مريض\" فلا يجوز لمدير الدائرة، أو رئيس الدائرة، أو صاحب البيت أن يشغل أولاده، أو الموظفين؛ بأعمال تمنعهم من صلاة الجماعة، تعوقهم عن الصلاة في الجماعة، بل يجب أن يكونوا متعاونين على المبادرة في أداء الصلاة في الجماعة، وعلى تأجيل الأشغال الأخرى التي قد تعوق إلى ما بعد الصلاة، أو تقديمها قبل الصلاة بوقت. أما أن يشغل الموظفون بها وقت الصلاة حتى يتخلفوا عن صلاة الجماعة؛ فهذا منكر عظيم، فالواجب تركه، والحذر منه، نسأل الله للجميع التوفيق، والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم، ما على العامل، أو السائق، أو الخادم إذا جوبه بمثل هذه القضية سماحة الشيخ! هل له، أو تنصحونه بأن ينتقل إلى جهة أخرى تمكنه من تأدية صلاة الجماعة؟ الشيخ: الواجب على السائق، والعامل، وكل موظف: أن يقدم حق الله، يصلي في الجماعة، يوقف السيارة، ويصلي في الجماعة، والحمد لله، والعامل يوقف العمل، ويصلي مع المسلمين، أوقات الصلاة مستثناة، ما هي داخلة في العمل إلا إذا كان حارسًا يصلي في محل حراسته؛ ولا يهمل محله، أو مريضًا؛ فهو معذور، أو معه في السيارة ما يخشى عليه؛ فلا بأس أن يؤديه إلى جهته، ويحرص مستقبلًا على أن يحتاط لهذا الأمر في جميع الأوقات، نعم. المقدم: جزاكم الله خيرًا، ومن كان عمله في الإمكان أن يؤجل ذلك العمل إلى ما بعد الصلاة، كيف تنصحونه؟ الشيخ: يجب عليه أن يؤجل، وإذا كانت الجهة المسؤولة لا تمكنه؛ ينتقل إلى جهة أخرى، يستقيل، ويطلب جهة أخرى، والله يسهل أمره، يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] ويقول : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] والنبي ﷺ يقول: لا طاعة لمخلوق في معصية الخالق ويقول -عليه الصلاة والسلام-: إنما الطاعة في المعروف. فالرئاسة التي تمنعه من صلاة الجماعة، أو الإدارة، أو رئيس العمل، أو ما أشبه ذلك؛ لا يجوز له أن يطيعه في ذلك. المقدم: أو رئيس العائلة مثلًا!  الشيخ: أو رئيس العائلة: إنما الطاعة في المعروف ليس للمكلف أن يطيع أحدًا في معصية الله -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14928/حكم-من-يلزم-بالعمل-في-اوقات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75201.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":16270,"question":"من محافظة مطروح، في جمهورية مصر العربية المستمع: (ج. م. ع) رسالة يقول فيها: إنني أتخلف أحيانًا عن صلاة الفجر بسبب تكاسل شديد يمنعني من أن أفتح عيني، فلا أقوم من النوم إلا بعد طلوع الشمس، ثم أصلي، ما هو توجيهكم لي؟ جزاكم الله خيرًا.","title":"ما النصيحة لمن يتكاسل عن صلاة الفجر؟","answer":"الجواب: هذا العمل منكر، لا يجوز لك أن تتساهل بصلاة الفجر، ولا بغيرها، بل يجب على المسلم والمسلمة الصلاة في الوقت، وليس للمسلم، ولا للمسلمة تأخير الصلاة عن وقتها، لا الفجر ولا غيرها، بل هذا من خصال أهل النفاق، قال الله  في أهل النفاق: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]. فأنت بهذا العمل، عملك أردى من عمل المنافقين، هم يقومون وأنت ما قمت، أخرتها إلى بعد الشمس، فالواجب عليك أن تصلي في الوقت، وأن تكون نشيطًا قويًا، وأن تصليها مع الجماعة، ولا تتشبه بأهل النفاق، قال النبي ﷺ: أثقل الصلاة على المنافقين: صلاة العشاء، وصلاة الفجر، ولو يعلمون ما فيهما  يعني: من الأجر لأتوهما ولو حبوا وقال النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس ! ما هو العذر؟ قال: مرض أو خوف. وجاء إليه ﷺ رجل أعمى، فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد -وفي لفظٍ: يقودني إلى المسجد- فهل لي من رخصة أن أصلي في بيتي؟ فقال له -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ -يعني: الأذان- قال: نعم، قال: فأجب أمره النبي ﷺ أن يجيب وهو أعمى، ليس له قائد يقود إلى المسجد، فكيف بالصحيح البصير، يكون الأمر عليه أعظم. فالواجب عليك أن تتقي الله، وأن تصلي مع الجماعة، وأن تبادر بالصلاة في وقتها. والذي يتعمد تأخيرها عن وقتها؛ يكفر عند جمعٍ من أهل العلم؛ لأنه متعمد تركها، وقد قال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر فظاهر هذا الحديث أن من تعمد تركها حتى تطلع الشمس بغير عذر؛ يكون كافرًا، نسأل الله العافية. فالواجب الحذر، وأن تصلي في الوقت، وأن تصلي مع الجماعة في المسجد، وعليك أن تفعل الأسباب التي تعينك على ذلك، عليك أن تعتني بالأسباب المعينة على قيامك إلى الصلاة، وذلك بالنوم المبكر، عليك أن تنام مبكرًا، حتى لا تكسل عن الفجر، وعليك أن تحتفظ بالساعة التي تسمع صوتها، ساعة الخراش التي تعينك على ذلك، توكدها على قرب الفجر حتى إذا خرشت؛ قمت، سمعت صوت المنبه، أو يكون عندك امرأة تعينك على ذلك، أو أبوك، أو أخوك. المقصود: لابد من القيام للصلاة، سواء بإيقاظ بعض أهلك، أو بوجود الساعة التي توكدها ... على قرب الوقت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14957/ما-النصيحة-لمن-يتكاسل-عن-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80808.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":16337,"question":"يسأل سؤالًا يقول فيه: ما حكم من يزوج ابنته لشاب لا يصلي لا في البيت، ولا في المسجد بحكم القرابة؟ جزاكم الله خيرًا.","title":"حكم تزويج القريب الذي لا يصلي","answer":"الجواب: ليس لأحد أن يزوج شخصًا لا يصلي، سواء كان شابًا، أو شيخًا، وسواء كان قريبًا، أو بعيدًا، هذا منكر، هذا ظلم للمرأة، وخيانة، ولا يجوز لها أن ترضى... أيضًا هي، ليس للولي ولا لها، ليس لهم جميعًا تزويج المرأة المسلمة المصلية لشخص لا يصلي؛ لأن ترك الصلاة كفر، كفر أكبر على أصح أقوال العلماء، وإن لم يجحد وجوبها؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فترك الصلاة منكر عظيم، وكفر ظاهر، فلا يجوز للمرأة أن تنكح كافرًا بترك الصلاة، أو بغير ذلك، المسلمة لا تنكح الكافر، يقول الله : لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ[الممتحنة:10] ويقول -جل وعلا-: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ وَلَوْ أَعْجَبَكُمْ [البقرة:221] فليس لوليها أن يزوجها إلا للمسلم، إذا كانت تصلي. أما إذا كانت لا تصلي، وتزوجها مثلها من لا يصلي صح، وعليهما التوبة جميعًا، والرجوع إلى الله، والقيام بالصلاة، هذا هو الواجب على الجميع، وعلى الأولياء أن يعتنوا بهذا الأمر، وهكذا من اشتهر بشرب الخمر، أو معاصي أخرى، ينبغي لوليها أن يصونها عنه؛ لأنه قد يضرها، قد يدعوها إلى هذا المنكر، فالولي يختار لها الرجل الصالح الطيب حسب الطاقة، حسب الإمكان، وأما تارك الصلاة فلا يجوز أبدًا، تزويجه؛ لأن تركها كفر، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15031/حكم-تزويج-القريب-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71313.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":16342,"question":"من المدينة المنورة رسالة مؤثرة، بعثت بها إحدى الأخوات المستمعات، تقول المرسلة: (م. س. ح) أختنا تقول: إن زوجي لا يصلي، ولا يصوم، ويشرب الخمر، وكثيرًا ما نصحته، وصبرت عليه، وعلى أفعاله من الضرب المبرح، والشتم عسى أن يهديه الله مدة ثماني سنوات، ولكن دون جدوى، وكان يقول: إذا حصل اجتماع، ومناقشة بيني وبينك في وجود أهلي وأهلك؛ فأنت طالق، وقد تم الاجتماع في مجلس واحد، وبحضور أهلي وأهله، وحصلت مناقشة بيننا، فهل بذلك تعتبر هذه طلقة، أم لا؟ وكم هي عدة المطلقة، هل هي ثلاثة أطهار؟ أم ثلاث حيض؟ ثم ما هو مصير أطفالي؟ هل يكون الأب -وصورته كما وضحتها لكم- هو الولي في تلك الحالة، أم الأم؟ وعلى من تجب النفقة؟ وجهوني جزاكم الله خيرًا.","title":"حكم البقاء مع زوج لا يصلي ويفعل الكبائر","answer":"الجواب: أولًا يجب عليك ترك هذا الزوج، وعدم البقاء معه؛ لأن من لا يصلي كافر، وإن أقر بالوجوب في أصح قولي العلماء، لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر فهي عمود الإسلام، من تركها؛ كفر، وإذا كان لا يؤمن بها صار كافرًا عند جميع أهل العلم. ثم مع هذا فيه شر آخر، شرب الخمور، والسب، والشتم، والإيذاء، والضرب، كل هذه عيوب قبيحة شديدة، لكن أعظمها، وأخطرها ترك الصلاة؛ لأنه كفر. فنصيحتي لك الحذر، والبعد عنه، ولا يجوز لك البقاء معه، بل يجب أن تغادري المكان إلى أهلك. أما ما يتعلق بالطلاق الذي صدر منه، والنفقة على أولاده فهذا تبع المحكمة، عليك مراجعة المحكمة، والمحكمة تنصفك -إن شاء الله- تعطيك حقك؛ لأن هذه خصومات بينك وبينه، فالحاكم ينظر في الأمر، ويعطيك وثيقة الفرقة والطلاق، ويعطيك حقك -إن شاء الله- من جميع الوجوه، والمحكمة فيها الخير والبركة في بلدكم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15036/حكم-البقاء-مع-زوج-لا-يصلي-ويفعل-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71405.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","مبطلات النكاح","قضايا المرأة"]},{"id":16365,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من اليمن وباعثتها إحدى الأخوات المستمعات من هناك، تقول عن نفسها: أنا فتاة في العشرين تقريبًا درست حتى الصف السادس، وتعينت مدرسة للبنات بعد الظهر، وأرجع الرابعة عصرًا ثم أصلي العصر والمغرب، وأجلس أقرأ القرآن، ثم أضطجع، وأقرأ انتظارًا للعشاء، كي أصلي وأنام، ثم أنام بدون صلاة؛ لكثرة التعب، دون أن أصلي، فماذا أفعل والحال هكذا، علمًا بأني أنام دون انتباه حتى الصباح، ثم أقضيه في الليلة التالية فهل علي شيء؟","title":"حكم النوم عن صلاة العشاء لشدة التعب","answer":"الجواب: هذا عمل منكر لا يجوز أبدًا، الواجب عليك أن تصلي العصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، قد كره النبي ﷺ النوم بعد المغرب، \"كان يكره النوم قبل العشاء، والحديث بعدها\" لئلا يكون وسيلة إلى ترك العشاء. فلا يجوز لك التساهل بهذا الأمر، بل يجب عليك أن تشتغلي بما يمنع النوم حتى تصلي العشاء بعد وقتها، إذا دخل وقتها بغروب الشفق الأحمر، إذا غاب الشفق الأحمر؛ دخل وقت العشاء، وليس لك التساهل بهذا الأمر، بل يجب وجوبًا عظيمًا شديدًا أن تحذري النوم الذي يفضي بك إلى ترك صلاة العشاء، اشتغلي بشيء مع أهلك، حتى يدخل وقت العشاء، ثم تصلي العشاء، ولا تصلي العصر إلا في وقتها، لا تؤخريها إلى المغرب، صلي العصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، والفجر في وقتها، والظهر في وقتها، هذا هو الواجب عليك، يقول الله -جل وعلا-: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103] والنبي ﷺ وقت الصلوات، وقال: صلوا كما رأيتموني أصلي عليه الصلاة والسلام. فالواجب عليك، وعلى غيرك العناية بهذا الأمر، وأن تؤدى الصلاة في وقتها، لا قبله ولا بعده، بل في وقتها، الظهر بعد زوال الشمس قبل وقت العصر، والعصر إذا دخل وقتها، وذلك بأن يصير ظل كل شيء مثله بعد الفيء الذي زالت عليه الشمس، وعليك أن تصلي العصر قبل أن تصفر الشمس في وقتها، والمغرب إذا غابت الشمس، والعشاء إذا غاب الشفق الأحمر، والفجر إذا طلع الفجر قبل طلوع الشمس، هذا واجب على جميع المسلمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15084/حكم-النوم-عن-صلاة-العشاء-لشدة-التعب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81104.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":16385,"question":"من مرسى مطروح مصر العربية رسالة وبعث بها أحد الإخوة المستمعين هو عبدالباسط العميري، الأخ عبدالباسط له قضية يقول فيها: عندنا رجل كبير في السن يبلغ من العمر تسعين عامًا، ولديه زوجة لا تصلي، مع العلم أنه أمرها بالصلاة؛ فأبت، فهجرها؛ فصلت حينًا أي: بعض الأيام، وقطعتها، فأعطاها مرتبًا يوميًا، أي: بعض النقود، ثم قطعتها، فقال لها: أنا بريء منك يوم الحساب، وأترك الأمر إلى الله، فقلت له: طلقها، قال: لا أستطيع، أنجبت منها أولادًا كثيرين، وأنا رجل كبير في السن، ولا أستطيع الزواج مرة أخرى، وليس عندي من يعد لي الطعام، ويقوم بواجبي وواجب بيتي، فهل لهذا الرجل أن يبقى مع هذه المرأة والحال ما ذكر، أم توجهونه إلى شيء آخر، علمًا بأنه من المحبين لهذا البرنامج؟ جزاكم الله خيرًا.","title":"حكم بقاء الرجل المُسنِّ مع امرأة لا تصلي","answer":"الجواب: الصحيح من أقوال العلماء في هذه المسألة: أن تارك الصلاة عمدًا يكون كافرًا كفرًا أكبر، فهذه المرأة تعتبر كافرة كفرًا أكبر، وبخروجها من العدة بعد كفرها تكون غير امرأة له، لكن لا مانع من أن تخدمه، وأن تخدم ذريته أولادها، وعليه أمرها بالحجاب، وغض البصر عنها، وأن لا يخلو بها، ولا حرج أن تبقى في خدمة أولادها، وينفق عليها من أجل خدمة أولادها وأولاده، مع الدعاء لها بالهداية، ومع النصيحة؛ لعل الله يهديها فترجع إلى الصواب، وهكذا أهلها ينصحونها، لعل الله يهديها بأسبابهم. وبكل حال هو يعتبرها خادمًا لا زوجة، ولا يخلو بها، ولا ينظر إليها، ويأمرها بالحجاب عنه؛ حتى يهديها الله، ويردها للصواب، فإذا هداها، ورجعت للصواب؛ فهي زوجته، نعم. المقدم: جزاكم الله خيرًا، إذًا لا بد أن يكون موقفه حازمًا والحال ما ذكر؟  الشيخ: هذا الواجب عليه، واختلف العلماء: هل ترجع إليه بنكاح جديد، أم لا ترجع بنكاح جديد؛ لأنه لم يطلقها، وتبقى معلقة متى هداها الله رجعت إليه. الصواب: أنها ما دامت بهذه الحال، ولم ترغب النكاح بغيره، وهو لم يطلقها متى رجعت، وهداها الله فهي زوجته، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15086/حكم-بقاء-الرجل-المسن-مع-امراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75411.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":16466,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من البحرين بتوقيع إحدى المستمعات تقول: بنت الطهماجي، تقول في قضيتها: تزوجت رجلًا ملتزمًا، لكنه تغير في سلوكه الدنيوي والديني، حلق لحيته، وشرب الدخان، والمسكرات حتى إنه يبحث عن وظيفة وإن كانت غير شريفة، تساهل في أمر الصلاة، فمرة يصلي، وأخرى لا يصلي، وما صلاها يصليها نقرًا، كيف أتصرف معه، علمًا بأن لدي منه ولدين، وأنا عند الأهل في الوقت الحاضر؟ وجهوني جزاكم الله خيرًا.","title":"حكم بقاء المرأة مع زوج يصلي أحيانًا","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله، وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فالواجب عليك ترك هذا الزوج، والذهاب إلى أهلك، والرفع عنه إلى المحكمة؛ حتى يفرق بينك وبينه إذا كان تارة يصلي، وتارة لا يصلي، مع ما فيه من العيوب الأخرى من شرب المسكر، وغير ذلك، لكن أعظمها ترك الصلاة، فإن تركها كفر، بخلاف المسائل الأخرى فإنها معصية. وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: بين الرجل، وبين الكفر والشرك ترك الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فالواجب عليك الذهاب إلى أهلك حتى يسهل الله التوبة، أو الفرقة، إما أن يتوب، وإما أن يطلق، ولا يجوز لك البقاء معه ما دامت حاله ما ذكرت من جهة الصلاة. أما المعاصي الأخرى -لو كان يصلي- فهي عيب، وعذر لك أن تطلبي الطلاق؛ لأنها عيب كبير، كونه يشرب الخمر، هذا عيب كبير مع حلق اللحية، ومع شرب الدخان، هذه عيوب، لكن أشدها وأعظمها ترك الصلاة؛ لأنها كفر في أصح قولي العلماء، وإن لم يجحد الوجوب، متى ترك الصلاة بعض الأحيان، وإن لم يجحد وجوبها؛ كفر بذلك في أصح قولي أهل العلم، فنسأل الله له الهداية، وأن يمن الله عليه بالتوبة، نعم. المقدم: اللهم آمين، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15180/حكم-بقاء-المراة-مع-زوج-يصلي-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81301.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":16484,"question":"من القصيم أخوكم الذي رمز لاسمه بـ (س. ر) يقول بأنه شاب يبلغ من العمر الثالثة والعشرين، يقول: وكنت فيما مضى من الأيام من عمري متهاونًا في أداء الصلوات، وحتى الصوم، فقد مرت علي شهور من رمضان أفطرت فيها أيامًا بدون عذر شرعي، وإنما تهاونًا، فإذا شعرت بالجوع، أو العطش؛ أفطرت، وبعد أن من الله علي بالتوبة، والهداية، وأيقنت بخطورة هذا الأمر؛ واظبت على الصلاة، ولكن الذي يؤلمني يا سماحة الشيخ هذه الأيام التي مضت من عمري عن تلك الصلوات، وعن أيام الصيام التي أفطرت فيها، كيف أبرئ ذمتي؟ جزاكم الله خيرًا.","title":"ما الواجب على من ترك الصلاة والصوم ثم تاب؟","answer":"الجواب: الواجب عليك يا أخي التوبة إلى الله، والحمد لله، ما دمت تبت إلى الله، وندمت، وأقلعت، وأصلحت؛ كفى ذلك، والحمد لله، ولا يلزمك قضاء الصلوات، ولا قضاء الصيام؛ لأن ترك الصلاة كفر، والتوبة تكفي، تجب ما قبلها، ما دمت تبت إلى الله؛ فالتوبة تجب ما قبلها، يقول النبي ﷺ: التوبة تجب ما قبلها ويقول ﷺ: التائب من الذنب كمن لا ذنب له. فالذي تاب من ترك الصلاة، وتاب من ترك الصيام، لا قضاء عليه، أما الصيام الذي تركته بعدما حافظت على الصلاة، إذا كنت تركت شيئًا من الصيام بعد أن حافظت على الصلوات؛ فإنك تقضي، أما الصيام الذي تركته مع ترك الصلاة؛ فالتوبة تكفي فيه، والحمد لله، أما إذا كان هناك أيام تركت صومها بعدما من الله عليك بالتوبة من ترك الصلاة؛ فإنك تقضيها. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15191/ما-الواجب-على-من-ترك-الصلاة-والصوم-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58213.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":16590,"question":"يسأل يقول: كيف تقضي المرأة التي تركت الصلاة، والصيام لعذرها الشرعي، كيف تقضي ما فاتها؟","title":"كيفية القضاء لمن تركت الصلاة لعذر أو متعمدة","answer":"الجواب: إن كان عذرها الحيض والنفاس؛ فليس عليها قضاء الصلاة، إنما تقضي الصوم فقط، صوم رمضان، أما إن كان عذرها نومًا، واستيقظت؛ تقضي إذا استيقظت من نومها، وأما إن كانت مجنونة، ثم رد الله عليها العقل؛ فليس عليها قضاء. أما إن كانت مريضة؛ فالواجب عليها أن تصلي في حال المرض، ولو على جنب، ولو مستلقية، فإن تساهلت جهلًا منها، ولم تصل لأجل المرض؛ تقضيها مرتبة، ولو في وقت واحد، حسب طاقتها مرتبة؛ ظهر، عصر، مغرب، عشاء، فجر، هكذا مرتبة، ولو في وقت واحد، ولو في ضحوة، أو في ظهر، أو في ليلة حسب طاقتها، إذا كان تركها لها عن مرض، تجهل أنها تصلي وهي قاعدة، أو على جنبها؛ تقضي. أما إن كان التساهل بالصلاة، تتركها عمدًا؛ فليس عليها قضاء، عليها التوبة، وهكذا الرجل الذي لا يصلي، ثم يتوب، ليس عليه قضاء، عليه التوبة إلى الله، والرجوع إلى الله، والاستقامة على الصلاة، وما فات قبل ذلك مما تركه عمدًا تساهلًا منه؛ فهذا فيه التوبة، وتكفيه التوبة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15323/كيفية-القضاء-لمن-تركت-الصلاة-لعذر-او-متعمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81706.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":16601,"question":"يسأل يقول: كيف تقضي المرأة التي تركت الصلاة، والصيام لعذرها الشرعي، كيف تقضي ما فاتها؟","title":"كيفية القضاء لمن تركت الصلاة لعذر أو متعمدة","answer":"الجواب: إن كان عذرها الحيض والنفاس؛ فليس عليها قضاء الصلاة، إنما تقضي الصوم فقط، صوم رمضان، أما إن كان عذرها نومًا، واستيقظت؛ تقضي إذا استيقظت من نومها، وأما إن كانت مجنونة، ثم رد الله عليها العقل؛ فليس عليها قضاء. أما إن كانت مريضة؛ فالواجب عليها أن تصلي في حال المرض، ولو على جنب، ولو مستلقية، فإن تساهلت جهلًا منها، ولم تصل لأجل المرض؛ تقضيها مرتبة، ولو في وقت واحد، حسب طاقتها مرتبة؛ ظهر، عصر، مغرب، عشاء، فجر، هكذا مرتبة، ولو في وقت واحد، ولو في ضحوة، أو في ظهر، أو في ليلة حسب طاقتها، إذا كان تركها لها عن مرض، تجهل أنها تصلي وهي قاعدة، أو على جنبها؛ تقضي. أما إن كان التساهل بالصلاة، تتركها عمدًا؛ فليس عليها قضاء، عليها التوبة، وهكذا الرجل الذي لا يصلي، ثم يتوب، ليس عليه قضاء، عليه التوبة إلى الله، والرجوع إلى الله، والاستقامة على الصلاة، وما فات قبل ذلك مما تركه عمدًا تساهلًا منه؛ فهذا فيه التوبة، وتكفيه التوبة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15323/كيفية-القضاء-لمن-تركت-الصلاة-لعذر-او-متعمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81706.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":16627,"question":"من إحدى الأخوات المستمعات تقول: المرسلة فاطمة، أختنا تقول عن نفسها: إنني امرأة متزوجة، لم أصل منذ سبعة وثلاثين عامًا، جاء لي الأبناء، وأصبحوا يعلمونني الصلاة -جزاهم الله خيرًا- لكني محتارة في المدة الماضية، هل سيحاسبني الله عليها، أم توصونني بقضائها؟ أم كيف يكون توجيهكم؟ جزاكم الله خيرًا.","title":"ما النصيحة لمن تاب من ترك الصلاة؟","answer":"الجواب: نوصيك بالتوبة النصوح، التوبة التوبة، الندم على الماضي، والعزم على ألا تعودي فيه، والمحافظة على الصلاة من حين هداك الله، الزميها، وحافظي عليها في أوقاتها بالطمأنينة، والخشوع، وأبشري بالخير، التوبة تجب ما قبلها، يقول النبي ﷺ في الحديث الصحيح: التوبة تجب ما قبلها يعني تهدم ما قبلها، تمحوه، ويقول -عليه الصلاة والسلام-: التائب من الذنب كمن لا ذنب له. فأبشري بالخير، التوبة بحمد الله تكفي، ومعناها الندم على ما مضى منك من الترك، والحزن على ذلك، والعزم على ألا تعودي إليه، وتستمري على المحافظة، والاستقامة على الصلاة، وأبشري بالخير، وليس عليك قضاء، والذنب يمحى بالتوبة، والحمد لله. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15356/ما-النصيحة-لمن-تاب-من-ترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71608.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":16651,"question":"ما قول سماحتكم فيمن بلغت في سن صغيرة، ولم تتعرف على أحكام الدين، وأمور الشرع المتعلقة بها بالقدر الذي وصلت إليه من المعرفة بها حاليًا، فلم تصل، ولم تصم، ولم تتحجب عن الأجانب، ثم بعد أن عرفت أحكام الدين في هذا الأمر احتجبت، وأصبحت تصلي، وتصوم بعد أن كانت تصوم صيام الأطفال، تفطر متى شاءت، وتصوم متى طاقت ذلك، الآن هل يلزمها قضاء ما فاتها من الصيام، والصلاة؟ وهل يلزمها إلى جانب قضاء الصيام صدقة؟ وإذا كان هناك صدقة، فما مقدارها؟ علمًا بأن الفترة التي أمضتها، وهي جاهلة بأحكام الشرع، ولا تلتزم بها سنتان ونصف، جزاكم الله خيرًا.","title":"حكم قضاء الصلاة والصوم لمن تركهما بلا عذر","answer":"الجواب: الصواب أنه لا يلزمها شيء، ويكفي التوبة؛ لأن الرسول ﷺ لم يأمر الذين أسلموا أن يقضوا ما فاتهم من صلاة، وصيام؛ولأن ترك الصلاة كفر، فالتوبة تكفي في هذا، فإذا كانت لا تصلي، ولا تصوم، فالتوبة كافية، وليس عليها قضاء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15384/حكم-قضاء-الصلاة-والصوم-لمن-تركهما-بلا-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71714.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":16671,"question":"في الفقرة الثانية من أسئلة السائلة أم عبدالله تقول: سماحة الشيخ! ما تقولون فيمن حج وهو لا يصلي، ثم تاب بعد ذلك، وبدأ يصلي؟ هل يلزمه أن يعيد الحج؟","title":"من حج وهو لا يصلي ثم تاب هل يعيد الحج؟","answer":"الجواب:  نعم يلزمه، إذا كان لا يصلي، ثم تاب الله عليه؛ يعيد الحج؛ لأن الرسول ﷺ قال: بين الرجل، وبين الكفر، والشرك ترك الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر فالحج الذي قبل ذلك لا يجزي، وعليه بعد التوبة أن يعيد الحج، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15402/من-حج-وهو-لا-يصلي-ثم-تاب-هل-يعيد-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58403.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":16672,"question":"الرسالة التالية وصلت إلى البرنامج من اليمن وباعثتها إحدى الأخوات المستمعات تقول: المرسلة أم أيمن عبدالله علي يحيى سعيد من اليمن تعز، رسالتها طويلة بعض الشيء سماحة الشيخ تقول: أنا أستمع إلى برنامج (نور على الدرب) دائمًا، ولي سؤال إذا سمحتم بعرضه، والإجابة عليه: أنا امرأة متزوجة، وعندي أربعة أولاد، وقد هداني الله إلى الصلاة والصيام، وقد علمت أولادي الصلاة، والصيام منذ كانت أعمارهم سبع سنوات، وقد كان زوجي مسافرًا لفترة طويلة، وعندما عاد، واستقر بدأت الحياة تدب فينا من جديد، لكن زوجي منذ عرفته -منذ ستة عشرة سنة- وهو يتهاون بصلاة الفجر، هذا أمامي، وأما عندما كان مسافرًا فالله يعلم، وهو لا يصلي الفجر دائمًا إذا سمعه، أو لم يسمعه، وقد نصحته بأن لا يتهاون بصلاة الفجر، فكان يغضب مني، ويتشاجر معي ويقول: إنه سوف يقضي عندما يستيقظ بعد شروق الشمس، وأنا أتألم لذلك؛ لأنه قدوتنا في البيت، وأيضًا يتهاون أحيانًا بصلاة الجمعة، وأنا أنصحه بعدم التهاون بصلاة الجمعة، ولكنه يغضب مني، ويحاول التشاجر معي، ولكن أبتعد عن التشاجر معه أمام أولادي، وأكتم الغضب في قلبي، وقد أحسست بكراهية وبغضاء تجاهه؛ بسبب تهاونه بالصلاة، فهل علي إثم في كراهيته، وعدم الرغبة في النظر إليه،؟ومعذرة لطول السؤال، جزاكم الله خيرًا.","title":"واجب المرأة تجاه زوجها المتساهل بالصلاة","answer":"الجواب: لقد أحسنت -جزاك الله خيرًا- في تربية الأولاد، وتعليمهم، والاجتهاد في أسباب صلاحهم، وهذا هو الواجب عليك، ولك عند الله الأجر العظيم. كما أنك أحسنت في نصيحة زوجك، والإكثار عليه في المحافظة على صلاة الفجر، وصلاة الجمعة، وهذا هو الواجب عليك، وعلى أمثالك، النصيحة للزوج والنصيحة للأولاد، والأمر بالمعروف، والنهي عن المنكر، يقول الله  في كتابه المبين القرآن: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] هؤلاء المرحومون في الدنيا والآخرة، وأنت منهم -إن شاء الله- لحرصك على الخير. والله -جل وعلا- أخبر عن المؤمنين والمؤمنات جميعًا الذكور والإناث، كلهم مأمورون، وكلهم يجب عليهم أن يأمروا بالمعروف، وينهوا عن المنكر، ويقيموا الصلاة، ويؤتوا الزكاة ويطيعوا الله ورسوله. ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] فالتواصي بالحق واجب مع الأولاد، ومع الزوج، ومع الأقارب، ومع الجيران، ومع المسلمين جميعًا، يجب على الرجال والنساء جميعًا أن يتواصوا بالحق، والصبر عليه، وبذلك تصلح المجتمعات، وتصلح الأسر، ويستقيم أمر الله في عباد الله، ويظهر الحق. ويقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ[المائدة:2] فالواجب عليك الاستمرار في نصيحته، وأنت مأجورة في بغضك له، وكراهتك له؛ لأنه أتى منكرًا عظيمًا، بل كفرًا؛ لأن من تعمد ترك الصلاة عمدًا؛ يكفر بذلك، وهكذا من تعمد ترك الجمعة. فالواجب على زوجك أن يتقي الله، وأن يحافظ على صلاة الجمعة، وعلى صلاة الفجر كبقية الصلوات، وأنا أخشى عليه -إن كان كاذبًا- أن يكون كافرًا إذا كان لا يصلي الفجر، أو لا يصلي الجمعة، يقول النبي ﷺ: لينتهين أقوام عن تركهم الجمعات؛ أو ليختمن الله على قلوبهم، ثم ليكونن من الغافلين رواه مسلم في الصحيح، ويقول ﷺ: من ترك ثلاث جمع بغير عذر؛ طبع الله على قلبه ويقول -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه، ويقول أيضًا -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فأنت شددي عليه، ولا يقربك حتى يستقيم، وإلا فاعتزليه بالكلية، واذهبي إلى أهلك، أو في بيت وحدك أنت وأولادك، وأنت أحق بأولادك منه؛ لأن مثلهم يربيهم على الشر، فأنت أولى بأولادك، وعليك أن تستمري في النصيحة لهذا الزوج مع منع نفسك منه؛ حتى يتوب إلى الله، وحتى يرجع إلى الحق، وحتى يحافظ على الصلوات كلها، نسأل الله له الهداية، وأن يمن عليه بالتوبة، ونسأل الله لك المزيد من التوفيق، وعظيم الأجر، وأن ينفع بجهودك، ودعوتك ونصيحتك، وأن يجعلك مباركة أينما كنت، وأن يهديه لقبول نصيحتك، والهداية بما يعينه على الخير، وبما يعينه على ترك الشر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، سماحة الشيخ! هذه المرأة تقرب من المثالية! الشيخ: الله أكبر، جزاها الله خيرًا، نعم. المقدم: ولا بد لسماحتكم من كلمة إلى كل زوجة تؤمن بالله.  الشيخ: نعم، نعم، على كل زوجة أن تتقي الله، وأن تعين زوجها على طاعة الله، وألا تتساهل معه، وألا تداهنه، وعلى الزوج كذلك أن يتقي الله في زوجته، وأن يعينها على طاعة الله، وأن يلزمها بالصلاة في وقتها، كل منهما عليه أن يعين الآخر، وأن ينصح الآخر. يقول الله لنبيه ﷺ: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6] فالواجب على جميع الأسرة التعاون على الخير، الزوج والزوجة، والأب، والأم، والأخ، والابن، والبنت، كلهم يتعاونون، يجب على الجميع أن يتعاونوا على البر والتقوى، وأن يتواصوا بالحق، فالزوج يأمر زوجته، ويلزمها بالحق، ولو بالتأديب، والزوجة كذلك تنصح زوجها، وتعينه على الحق، وإذا لم يستجب؛ استحق منها الهجر فيما أظهر من المعاصي. والهجر ثلاثة أيام في القول، وإذا كان كفرًا؛ وجب عليها فراقه: كترك الصلاة، أو سب الدين، هذا يكون كفرًا من سب الدين، أو سب الرسول، أو ترك الصلاة يكون كافرًا، يجب عليها أن تتركه، وأن تذهب إلى أهلها، وتمنعه من نفسها. وكذلك إذا كان يجحد شيئًا مما حرمه الله؛ كأن يستحل الخمر، أو الزنا، ويراه حلالًا، أو يرى أن الصلاة ما هي بواجبة يقول: ما هي بواجبة، ما علينا صلاة، أو ما علينا زكاة، .. يكون هذا كفرًا أكبر، أو يستهزئ بالدين: يسخر بالصلاة، أو يسخر بالإسلام، أو يسخر بالزكاة، أو يسخر بالرسول، ويستهزئ به؛ كل هذا كفر أكبر، وردة عن الإسلام، نعوذ بالله. المقصود: الواجب على الزوجين، وعلى الأسرة كلها: التناصح، والتعاون على البر والتقوى، والتواصي بالحق، والصبر في ذلك، والله -جل وعلا- يعينهم إذا صدقوا، وأخلصوا، يعينهم، ويوفقهم، وينفع بجهودهم، هكذا سنته في عباده، أنه سبحانه يوفق من أخلص له، ويعينه، كما قال : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم، وتقبل منكم.","link":"https://binbaz.org.sa/fatwas/15414/واجب-المراة-تجاه-زوجها-المتساهل-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76003.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة","قضايا المرأة"]},{"id":16793,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من العراق، وباعثتها إحدى المستمعات من هناك تقول: أم نجم، أم نجم لها قضيتان، القضية الأولى تقول فيها عن نفسها: أنا سيدة متزوجة، وأصلي وأصوم، وعلى عبادة تامة، وزوجي يسير على غير ما أنا عليه، حيث يحتسي الخمر، ويفعل المجتنبات، وكل ما حرم الله، مع العلم أن لدي أبناء منه، وحاولت إصلاحه، فاهتدى إلى الصواب لمدة أقل من سنة، حيث صلى وصام، ولكن عاد إلى ما كان عليه، وأحاول مرة أخرى أن أصلحه أنا وأولادي، ولكن دون جدوى، فأسألكم: هل تحق لي صلاتي وصيامي؟ أم أتحمل إثمًا معه؟ هذا السؤال الأول، والثاني سأوافيكم به بعد أن أسمع هذه الإجابة، جزاكم الله خيرًا.","title":"حكم البقاء مع زوج لا يصلي ويقارف الكبائر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن الواجب عليك -أيها السائلة- عدم البقاء مع هذا الزوج، نسأل الله لنا وله الهداية، والتوفيق للتوبة النصوح، ما دام بهذه الحال، وأنه لا يصلي؛ فإن الذي لا يصلي يعتبر كافرًا - في أصح قولي العلماء- كفرًا أكبر، فلا يجوز لك البقاء معه، بل يجب اجتنابه، والحذر منه، وعدم تمكينه من نفسك، والواجب أيضًا عدم اعتباره زوجًا؛ حتى يتوب إلى الله مما هو فيه من ترك الصلاة، وغير ذلك مما يعتبر كفرًا. أما ما يتعلق بشرب المسكر فهذه معصية كبيرة، فإن الخمر من كبائر الذنوب، فالواجب عليه التوبة إلى الله من ذلك، وأنت بالخيار إذا صلى، واستقام على الصلاة، وترك ما يوجب كفره؛ فأنت بالخيار، إن شئت بقيت معه، وإن شئت طلبت الطلاق ما دام يتعاطى المسكر؛ لأنه عيب كبير، وخطر عليك وعلى أولادك، نسأل الله لنا وله الهداية، والرجوع إلى الصواب، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15544/حكم-البقاء-مع-زوج-لا-يصلي-ويقارف-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76301.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":16822,"question":"يقول سماحة الشيخ في سؤال آخر: لي خالة تجاوزت العقد الثالث من عمرها، لكنها لا تصلي بالرغم من أنها طيبة المعشر، حميدة الخصال، ولقد أمرتها، ولكن لم تمتثل لأمري، فما هو توجيهكم نحوها؟ وما هو توجيهكم لها؟ جزاكم الله خيرًا.","title":"ما كيفية التعامل مع أقارب لا يصلون؟","answer":"الجواب: الواجب عليها أن تصلي؛ لأن الصلاة عمود الإسلام، وهي فرض على كل مسلم ومسلمة، وهي الركن الثاني من أركان الإسلام الخمسة، قال الله -جل وعلا-: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] وقال سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56] وقال -جل وعلا-: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ.. [المؤمنون:1-2] إلى أن قال في آخر الآيات: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:9-11] وهذا يعم الرجال، والنساء جميعًا. وقال النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فالواجب عليها أن تصلي الصلوات الخمس، وأن تحافظ عليها في أوقاتها، وعليكم أن تنصحوها دائمًا، وعلى أبيها، وأمها، وأعمامها، وأخوالها، وإخوتها عليهم أن ينصحوها، وأن يجتهدوا في ذلك؛ لأن هذا واجب الجميع، وإذا أصرت؛ فالواجب تأديبها من أبيها، وإخوتها الكبار، ولو بالضرب حتى تستقيم، حتى تصلي؛ لأن من ترك الصلاة يستتاب، فإن تاب وإلا قتل، كافرًا -نسأل الله العافية- من الرجال والنساء. فالواجب عليها أن تستمع أمر الله، وأن تبادر إلى الصلاة، وعلى أقاربها أن ينصحوها، وعلى أبيها، أو جدها، أو إخوتها الكبار أن يقوموا عليها في ذلك بالصدق، والقوة، ولو بالتأديب، والضرب حتى تستقيم. وينبغي أيضًا هجرها إذا كان الهجر ينفع، تهجر: كعدم الكلام معها، وعدم السلام عليها، وعدم زيارتها، لكن الأب، ونحوه ما يكفي منه الهجر، بل يجب أن يقوم بما يجب من التأديب، والإلزام، أبوها، وكذا جدها، وكذا أخوها. المقصود: أن على الأقارب العناية بهذا الأمر، والنصيحة؛ لأن هجرها قد يسبب بقاءها على حالها الباطلة، لكن العناية بها، والحرص على استقامتها هذا هو الواجب على الجميع، ولو بالتأديب، والضرب من أبيها، أو أخيها الكبير؛ حتى تستقيم، حتى تصلي، نسأل الله لنا ولها الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا. سماحة الشيخ! ماهو توجيهكم إذا كان لهذه المرأة زوج؟ الشيخ: زوجها إذا كان يصلي ما يحل له أن تبقى معه، يجب أن يفارقها، إن لم تهتد، ولم تتب؛ عليه أن يفارقها؛ لأن ترك الصلاة كفر أكبر، فعليه أن يفارقها بالكلية؛ حتى تتوب، وفي إمكانه أن يؤدبها أيضًا، أن يؤدبها على ذلك؛ لأن هذا من المنكرات العظيمة، فإذا أدبها لحقه، وعصيانها له، فتأديبها لحق الله الذي هو أهم الواجبات، وأعظم الفروض بعد التوحيد، وهو الصلاة أمر مهم. المقدم: جزاكم الله خيرًا، سماحة الشيخ! ماهو رأيكم في الهدية في بداية الأمر لمثل هذه؟ الشيخ: إذا كان قريبها، أو زوجها يرى أن إعطاءها شيئًا من المال يعين على ذلك، يفعل لا بأس، وهذا من باب الإعانة على الخير، إذا أهدى إليها شيئًا، أو أهدى إليها أخوها، أو ابن أخيها، أو أختها هدية من المال؛ لتهتدي فهذا طيب، هذا من التأليف من تأليف القلوب. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15578/ما-كيفية-التعامل-مع-اقارب-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76313.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":16886,"question":"رجل له زوجة، ونصحها بالصلاة عدة مرات، ولم تجب لنصيحته، علمًا بأنها لا تفقه شيئًا من القرآن والسنة، فما حكم ذلك في الإسلام؟ جزاكم الله خيرًا.","title":"ما كيفية نصح الزوجة التي تترك الصلاة لجهلها؟","answer":"الجواب: عليه أن يستمر في نصيحتها، ويعلمها، أقول: عليه الاستمرار في النصيحة، والتعليم، ولا ييأس، ولكن يكون بالكلام الطيب، والأسلوب الحسن، والرفق، وشيئًا شيئًا قليلًا قليلًا حتى تتعلم ما أوجب الله عليها وما حرم الله عليها سبحانه ..... المقدم: وموضوع الصلاة؟ الشيخ: نعم؟ المقدم: يقول: إنها لا تصلي؟ الشيخ: التوبة، التوبة تكفي. المقدم: إذا أبت أن تتوب كما يقول في السؤال؟ يقول: إنها أبت أن تتوب؟ الشيخ: في إمكانه إذا كان له قدرة أن يؤدبها على ذلك حتى تستقيم، وتصلي: كالزوج، والأب، والجد، ونحو ذلك، والأخ الكبير، مع الحرص عليها بالتوجيه، والإرشاد، والترغيب في الخير، والتحذير من النار، وله أن يؤدبها إذا استطاع بضربات تمنعها من الباطل، وتعينها على أداء الحق، نعم. المقدم: إذًا لو استخدم الضرب، والهجر، وما إلى ذلك؟ الشيخ: الذي يرى فيه المصلحة حتى تتم التوبة، والعمل الصالح. المقدم: جزاكم الله خيرًا. إذًا لا يقدم على الطلاق حتى يسلك هذه الطرق. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15645/ما-كيفية-نصح-الزوجة-التي-تترك-الصلاة-لجهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76503.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":16967,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من المنطقة الشرقية، يقول محمد بن علي عيساوي الأخ محمد له جمع من الأسئلة في أحدها يقول: والد لدي، لكنه لم يصل أبدًا، بعد أن نصحناه، وعلمناه، وهجرناه، وكلمناه، وبينا له بأن عقوبة تارك الصلاة الكفر، وله عذاب شديد، لكن دون جدوى، هل إذا قدر الله وتوفي يحق له أن يرثه؟ أفيدونا جزاكم الله خيرًا.","title":"حكم هجر الأولاد لوالدهم التارك للصلاة","answer":"الجواب: الوالد له حق عظيم، سواءً كان رجلًا، أو امرأة، الوالد والوالدة، فالواجب النصيحة، والإرشاد، والمخاطبة الحسنة، ولو كان تاركًا للصلاة، ولو كان كافرًا بأي كفر، لا بد من الصبر، والاستمرار في النصيحة، والتوجيه، وعدم الهجر، لا تهجره، لا يجوز لك هجره، الله يقول سبحانه في كتابه العظيم: وَإِنْ جَاهَدَاكَ [لقمان:15] يعني الوالدين عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] أمره بأن يصاحبهما في الدنيا معروفًا، وألا يطيعهما في المعصية، ولا في الكفر، ولهذا قال بعده: وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:15]. فالمقصود: أن الواجب عليك أيها الولد أن تتقي الله، وأن تنصح والدك أنت وإخوانك، ومن يساعدكم من أهل الخير بنصيحته، وتوجيهه، وعدم اليأس، لكن لا تهجره، ولا تؤذه، ولا ترفع الصوت عليه، ولكن تنصحه بالكلام الطيب، والأسلوب الحسن، كما أنت مأمور بذلك، يقول الله -جل وعلا-: وَوَصَّيْنَا الإِنْسَانَ بِوَالِدَيْهِ حُسْنًا وَإِنْ جَاهَدَاكَ لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا [العنكبوت:8] ويقول -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] ثم قال بعدها: وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:15]. فأنت مأمور بأن تصاحبهما بالمعروف، بالكلام الطيب، لكن مع النصيحة.. مع التوجيه.. مع الإرشاد، عملًا بقول ربك -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ [لقمان:14] وقوله: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وقد يهديهما الله على يديك، ويكون لك بذلك الخير العظيم، والأجر الكبير، وقد قال الله : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:24]. فلا تيأس يا أخي، وترك الصلاة لا شك أنه كفر، وهو كفر أكبر على أصح قولي العلماء، كفر أكبر، وإذا مات على ترك الصلاة لا يرثه المسلم من أولاده، وإنما يكون للكفرة من أقاربه الذين مثله. وقال آخرون من أهل العلم: إنه لبيت المال؛ لأنه مرتد، فيكون ماله لبيت المال، لا لمن كان كافرًا من جماعته، بل يؤخذ ماله، ويوصل لبيت المال؛ لأنه ليس من الكفار الأصليين، وليس من المسلمين، والمرتد يكون ماله فيئًا لبيت مال المسلمين، يصرف في مصالح المسلمين، وهذا قول قوي وجيد، ولعله الأقرب والأولى، فلا يعطاها الكفار، ولا يعطاها المسلمون، ولكن يصرف لبيت المال. إذا ارتد بترك الصلاة، أو بسب الدين، أو بشيء من أنواع الكفر والضلال الأخرى؛ فإنه لا يصلى عليه، ولا يغسل، ولا يدفن مع المسلمين، ويكون ماله فيئًا لبيت مال المسلمين، ومصالح المسلمين، وإذا رأى ولي الأمر أن يعطيه أولاده المسلمين تقديرًا لجهودهم، وأعمالهم في نصيحته، ولئلا يحرموا منه؛ فلا بأس إذا رأى ولي الأمر ذلك مساعدة لهم على التثبيت في الإسلام، وتأليف قلوبهم، هذا أمر حسن. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15764/حكم-هجر-الاولاد-لوالدهم-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_766/nour_76605.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":16984,"question":"رسالة من أحد الإخوة المستمعين له فيها سؤالان، في سؤاله الأول يقول: زوج أختي لا يصلي أبدًا حتى أيام الجمعة، ولا أظنه إنكارًا لوجوب الصلاة، إنما بحجة أنه عامي، لا يقرأ ولا يكتب، فهل في بقاء أختي معه شيء، وإنني عندما أسمع عقوبة تارك الصلاة؛ يشفق عليه قلبي، ويحن، كما أنني أعانقه أحيانًا كأيام الأعياد، وغيرها، انصحوني جزاكم الله خيرًا.","title":"هل يجوز للمرأة البقاء مع زوج لا يصلي؟","answer":"الجواب: ترك الصلاة كفر بنص النبي -عليه الصلاة والسلام- والصحيح من أقوال أهل العلم: أنه كفر أكبر، يخرج من الملة، وإن لم يجحد وجوبها، لكن إن جحد وجوبها؛ كفر عند جميع العلماء. يقول النبي ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول أيضًا -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ولا يجوز بقاء أختك معه، بل يجب التفريق بينهما إلا أن يتوب. والواجب عليك هجره، وعدم معانقته، وعدم صحبته حتى يتوب إلى الله  فهجر مثله من أهم المهمات، وأقل الأحوال أنه سنة مؤكدة، والقول بالوجوب قول قوي، القول بوجوب هجر من أظهر المعصية، والكفر قول قوي. فعليك يا أخي! أن تنصحه لله، وأن تخوفه من الله، وأن تجتهد في توبته؛ لعل الله يهديه بأسبابك، فإن أصر على الباطل، وأبى أن يقبل منك؛ فاهجره هذا هو المشروع. وإن رأيت المواصلة للنصيحة بين وقت وآخر؛ فذلك خير، من باب النصح لله، ولعباده، من دون أن تتخذه صاحبًا، أو صديقًا، أو عشيرًا، لا، ولكن بين وقت وآخر تمر عليه، وتنصحه تقول: اتق الله.. راقب الله يا عبد الله! الصلاة عمود الإسلام، من تركها كفر؛ لعل الله يهديه بأسبابك. وإذا تيسر أن تقول لإخوانه، أو أبيه، أو أصدقائه: أن ينصحوه أيضًا؛ حتى يساعدوك، فهذا أمر مطلوب، والمسلمون إخوة يتناصحون، وهذا إنسان قد تعاطى ما يخرجه من الإسلام، فالواجب نصيحته، وأمره بالمعروف، ونهيه عن المنكر، والأخذ بيده إلى الصواب؛ لعل الله يهديه بأسبابك. وقد قال الله  في كتابه العظيم: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] وقال سبحانه في كتابه العظيم: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] وقال النبي ﷺ في الحديث الصحيح: الدين النصيحة قيل: لمن يا رسول الله؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم. نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، حجته أنه لا يقرأ، ولا يكتب، ما هو توجيهكم حول هذا؟ الشيخ: هذه ليست حجة، يجب عليه أن يصلي وإن كان عاميًا، ليس من شرط الصلاة أن يكون يقرأ ويكتب، عليه أن يصلي، ويتعلم، ويتفقه في دينه، ولا يدع الصلاة، عليه أن يصلي، وعليه أن يؤدي الزكاة، وعليه أن يصوم رمضان، وعليه أن يحج حج البيت إن استطاع، وإن كان غير عالم، وإن كان عاميًا، لكن يلزمه التفقه في دينه، والسؤال عما أشكل عليه؛ لأنه مخلوق لعبادة الله، فواجب عليه أن يتعلم هذه العبادة، ويتبصر فيها، يقول الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] ويقول سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21].  فهذه العبادة الذي خلقنا لها، وأمرنا بها يجب أن نفقهها، وأن نعلمها، وأن نسأل أهل العلم عنها؛ حتى نكون فيها على بصيرة، وحتى نؤديها على علم، ويقول النبي ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين فالذي يعرض، ولا يتفقه هذه من علامة أن الله ما أراد به خيرًا، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ، ذكرتم أن من وسائل التعليم: السؤال، هل تتفضلون بذكر وسائل أخرى؟  الشيخ: نعم، سؤال أهل العلم من وسائل الفقه في الدين، وتدبر القرآن الكريم من وسائل ذلك، وهو أعظم كتاب، وأشرف كتاب، وأنفع كتاب، تدبره، والإكثار من قراءته من أعظم الأسباب في الفقه في الدين، والبصيرة، وهكذا حضور حلقات العلم.. سماع خطب الجمع بإنصات، وحضور قلب.. وسماع النصائح من الناصحين؛ كل هذا من أسباب تحصيل العلم. فالواجب على العامي أن يجتهد في حضور حلقات العلم، وفي الإصغاء لخطب الجمعة، وفي سؤال العلماء عما أشكل عليه، وإذا كان يقرأ القرآن يجتهد في تدبره، والاستفادة منه، وإذا كان لا يقرأ؛ يجتهد في سماع الأشرطة التي فيها تفسير القرآن الكريم، وسماع القرآن من إذاعة القرآن، كل هذا يفيده كثيرًا وينفعه كثيرًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15776/هل-يجوز-للمراة-البقاء-مع-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82905.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","قضايا المرأة"]},{"id":17079,"question":"من أسئلة هذا السائل من الأردن محمد القرالة يقول: ما حكم من مات وهو لا يصلي، ولكنه موحد؟ فهل يصلى عليه؟ وهل يدفن في مقابر المسلمين؟","title":"حكم الصلاة على تارك الصلاة ودفنه مع المسلمين","answer":"الجواب: إذا علم أنه لا يصلي فهو كافر في أرجح القولين، ولا يدفن مع المسلمين إذا علم أنه لا يصلي.  وقال بعض أهل العلم: إنه إذا كان لم يجحد وجوبها أنه يصلى عليه، ويدفن مع المسلمين، ولكن الأرجح أنه إذا علم بالبينة الشرعية أنه يترك الصلاة فإنه يكفر بذلك، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر نسأل الله العافية. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15888/حكم-الصلاة-على-تارك-الصلاة-ودفنه-مع-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58819.mp3","categories":["حكم الصلاة وأهميتها","الصلاة على الميت"]},{"id":17092,"question":"يقول عن نفسه: أنا أصلي منذ خمس سنوات، ولكني تركت الصلاة لمدة عشرة أشهر، بين السنة الثالثة والرابعة، إلا أنني الآن مستمر في الصلاة -والحمد لله- هل علي القضاء؟ أم ماذا؟ جزاكم الله خيرًا.","title":"حكم من ترك الصلاة عشرة أشهر ثم تاب","answer":"الجواب: التوبة كافية؛ لأن ترك الصلاة كفر، والكفر دواؤه التوبة، والنبي ﷺ قال: الإسلام يهدم ما كان قبله، والتوبة تهدم ما كان قبلها والله يقول في كتابه العظيم: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] فعليك الجد في طاعة الله، والاستقامة، والاستكثار من العمل الصالح، والاستغفار، والتوبة الصادقة، ولا قضاء عليك، هذا هو الواجب؛ أن تستقيم على التوبة، وأن تثبت عليها، وأن تحذر ترك الصلاة، وأن تحذر أيضًا جلساء السوء، لا تجالس من يترك الصلاة، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ويقول ﷺ بين الرجل وبين الكفر والشرك ترك الصلاة فالصلاة عمود الإسلام، أعظم فرائض الإسلام الصلاة بعد الشهادتين، يقول النبي ﷺ: رأس الأمر الإسلام وعموده الصلاة. فالواجب على الرجال، والنساء جميعًا المحافظة على الصلوات الخمس، والعناية بها في أوقاتها، وعلى الرجل أن يصليها في الجماعة في المساجد مع المسلمين، وعلى الجميع الحذر من تركها، والتساهل بها؛ لأن تركها كفر أكبر، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15938/حكم-من-ترك-الصلاة-عشرة-اشهر-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83108.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":17153,"question":"إحدى الأخوات المستمعات عرضنا لها سؤالًا قبل هذا السؤال، تقول أختكم في الله (س. ع) من ليبيا، أختنا تسأل في هذه الحلقة عن قضية طولت في السؤال عنها، ملخص ما سألت عنه سماحة الشيخ: أنه مر فترة من عمرها، وكانت تصلي مرة، وتترك مرة حتى أنها أحصت عدد الركعات التي فاتتها، فما هو توجيهكم لها؟ جزاكم الله خيرًا.","title":"حكم قضاء الصلوات المتروكة بعد التوبة","answer":"الجواب: عليها التوبة ويكفي والحمد لله، عليها التوبة مما سلف، ومن تاب تاب الله عليه؛ لأن ترك الصلاة كفر، فالتوبة تكفي، ولا يلزمها القضاء، النبي ﷺ لم يلزم من ارتد، ثم أسلم بالقضاء، والصحابة كذلك لما أسلم من أسلم من المرتدين لم يأمروهم بالقضاء.  فالمقصود: أنه إذا أسلم بعد تركه الصلاة فإن عليه التوبة الصادقة والحمد لله، والعمل الصالح، ويكفي، يقول الله سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] فليس على من أسلم قضاء ما ترك من صيام ولا صلاة، إذا كان قد أتى ناقضًا من نواقض الإسلام كترك الصلاة، أو جحد بعض ما أوجب الله من صلاة، أو زكاة، أو نحو ذلك مما هو معروف من الدين بالضرورة، وقد أجمع عليه المسلمون، كل من حكمنا بكفره، ثم أسلم فإنه لا يقضي ما سلف. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15977/حكم-قضاء-الصلوات-المتروكة-بعد-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72213.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":17160,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل فيها جمعًا من الأسئلة في أحد أسئلته يقول: شاب كان تاركًا للصلاة، فمنَّ الله عليه بالتوبة، أفتى له بعض العلماء أن يقضي الصلاة التي فاتته، وإن لم يقضها قضاها في جهنم، أفتونا جزاكم الله خيرًا.","title":"هل يقضي فوائت الصلاة من تاب من تركها؟","answer":"الجواب: إذا كان تاركًا للصلاة، جاحدًا لوجوبها؛ فهذا لا قضاء عليه، وعليه التوبة، الرسول ﷺ لم يأمر الذين أسلموا بأن يقضوا ما مضى من الصلوات، والمرتدون في عهد الصحابة لما أسلموا لم يأمرهم الصحابة أن يقضوا ما تركوا من الصلوات. أما إن كان غير جاحد لوجوبها، بل تساهل، وتكاسل، وترك بعض الصلوات؛ فهذا في كفره خلاف؛ من أهل العلم من قال: يكفر كفرًا أكبر، وهو الأصح لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وذهب الجمهور إلى أنها كفر دون كفر، إذا كان ما جحد الوجوب يكون كفرًا دون كفر، وعليه القضاء، فهذا إن قضى من باب الاحتياط حسن. أما قول هذا المفتي: إنه يقضيها في جهنم! هذا لا أعلم له أصلًا، هذا لا أعلم له أصلًا، لكن على كل حال الصحيح أنه لا يلزمه القضاء، فإن قضى من باب الاحتياط، والخروج من الخلاف إذا كان ما جحد الوجوب، ولكن تكاسل، إن قضى فهذا حسن من باب الاحتياط، وإلا فلا يلزمه القضاء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15981/هل-يقضي-فواىت-الصلاة-من-تاب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76713.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":17215,"question":"يقول: اختلف العلماء -رحمهم الله- في تكفير تارك الصلاة: فقال مالك، والشافعي بأنه ليس بكافر، فما حكم من مات وهو لا يصلي تهاونًا وكسلًا، معتمدًا على هذه الفتوى، ومعتقدًا بصحتها، وما هو مصيره عند الله يوم القيامة، وهل هذا الاعتقاد للتمسك بهذه الفتوى، أو تلك مصدره الحديث القائل: \"ما يراه المسلمون حسنًا فهو عند الله حسن\"؟","title":"ما حكم من مات وهو لا يصلي تهاونًا وكسلًا؟","answer":"الجواب: المسألة مثل ما قال السائل: فيها خلاف بين العلماء، إذا كان التارك للصلاة لم يجحد وجوبها، أما إن كان يجحد وجوبها؛فإنه يكفر عند الجميع -والعياذ بالله- كسائر الكفرة، كفرًا أكبر، أما إذا تركها تكاسلًا دائمًا، أو في بعض الأحيان فهذا هو محل الخلاف. والصواب: أنه يكفر كفرًا أكبر، هذا هو الصواب خلاف قول الأكثر، والصواب قول من قال بكفره كفرًا أكبر، وأنه لا يغسل، ولا يصلى عليه، حكمه حكم الكفار لقول النبي ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر، والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. ولقول عبدالله بن شقيق العقيلي التابعي الجليل: \"لم يكن أصحاب النبي ﷺ يرون شيئًا تركه كفر إلا الصلاة\" ولقوله ﷺ: لما سئل عن الأئمة الذين يؤخرون الصلاة عن أوقاتها، أو يتعاطون بعض المعاصي: هل نقاتلهم؟ نهى عن قتالهم، قال: إلا أن تروا كفرًا بواحًا، عندكم من الله فيه برهان وفي رواية: ما أقاموا فيكم الصلاة فدل على أن ترك الصلاة من الكفر البواح.  فالواجب على كل مسلم أن يحذر ترك الصلاة، وهكذا كل مسلمة يجب عليها المحافظة على الصلاة في وقتها، والحذر من تركها، فإن تركها كفر، ومن هذا قوله ﷺ: من ترك صلاة العصر؛ حبط عمله وحبوط العمل يدل على الكفر الأكبر، فالواجب على كل مسلم ومسلمة المحافظة على الصلاة في أوقاتها، والحذر من تركها لا جحدًا، ولا تهاونًا، نسأل الله للمسلمين الهداية، والتوفيق، والعافية من كل شر. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16041/ما-حكم-من-مات-وهو-لا-يصلي-تهاونا وكسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72311.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":17246,"question":"تقول السائلة -سماحة الشيخ- أم أمل من ينبع: لقد بلغها الحيض، وهي في الرابعة عشرة من العمر، ومنذ أن بلغها الحيض -تقول:- حتى التاسعة عشرة من عمرها، لم تصل، ولم تصم، والآن تقول أم أمل: بأنها تابت إلى الله توبةً نصوحًا، وبدأت تصلي، وتحافظ على الصلوات، وتصوم، وتكثر من النوافل، وتحمد الله، تقول: وجهوني سماحة الشيخ تجاه ما فرطت، هل أقضي الصوم، والصلاة، ما مضى؟","title":"حكم قضاء الصلاة والصوم لمن تركهما عدة سنوات","answer":"الجواب: ليس عليك قضاء، التوبة تكفي، التوبة تجب ما قبلها، أسلمت على ما أسلفت من خير، والحمد لله، ليس عليك قضاء صلاة، ولا صوم، التوبة تجب ما قبلها، نسأل الله لنا ولك الثبات على الحق، الذين أسلموا لم يأمرهم النبي ﷺ بقضاء صوم، ولا صلاة، اللهم صل عليه وسلم.","link":"https://binbaz.org.sa/fatwas/16078/حكم-قضاء-الصلاة-والصوم-لمن-تركهما-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59123.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":17307,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (س. ف) أخونا عرضنا بعض أسئلته في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد يقول فيه: لماذا إذا لم يصل الشخص يكون خارجًا عن الملة؟ وإذا تاب لا يقضي صلواته التي لم يصلها؟ ولماذا يقضي صومه إذا تاب؟ علمًا بأني لم أكن أصلي من قبل، أفيدوني عن هذه القضايا، جزاكم الله خيرًا.","title":"الفرق بين تارك الصلاة وتارك الصيام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.. أما بعد.  فينبغي أن يعلم أن الأحكام الشرعية إنما تؤخذ عن الله، وعن رسوله -عليه الصلاة والسلام- لا عن آراء الناس، فالأحكام التي يحكم بها على العباد في كفر، أو إيمان، أو طاعة، أو معصية إنما تؤخذ عن الله، وعن رسوله -عليه الصلاة والسلام- فمن ترك الصلاة فقد حكم عليه الرسول ﷺ بأنه كافر، كما أن من أشرك بالله، وعبد معه غيره فقد حكم الله عليه ورسوله بأنه كافر، وهكذا من استهزأ بالله، ودينه حكم الله عليه بأنه كافر. وهناك أحاديث أخرى كلها تدل على كفر تارك الصلاة؛ لأنها عمود الإسلام، وأعظم الأركان بعد الشهادتين، فلهذا كفر تاركها، وإذا أسلم لا يؤمر بالقضاء؛ لأن الرسول ﷺ لم يأمر الذين ارتدوا، ثم أسلموا أن يقضوا، بل قبل منهم إسلامهم، ولم يأمرهم بالقضاء، وهكذا الصحابة  لما قاتلوا أهل الردة لم يأمروهم بالقضاء بعدما أسلموا؛ لأن الإسلام يجب ما قبله، الإسلام توبة عظيمة تهدم ما قبلها؛ ولأن مطالبة الإنسان بقضاء ما فاته في حال الردة قد ينفره من الإسلام، قد يحول بينه وبين الدخول في الإسلام، فكان من حكمة الله ومن إحسانه إلى عباده أن جعل الإسلام يهدم ما كان قبله، يقول النبي ﷺ: الإسلام يهدم ما كان قبله فمن أسلم غفر الله له ما مضى من شرك، وغيره. أما من ترك الصيام فإنه مسلم لا يكون كافرًا إذا كان لم يجحد الوجوب، إذا كان ما جحد وجوب صوم رمضان، بل يعلم أنه واجب عليه، ولكن تكاسل، فأفطر في بعض الأحيان، هذا يكون عاصيًا، وعليه القضاء، والتوبة إلى الله . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16152/الفرق-بين-تارك-الصلاة-وتارك-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83301.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17320,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (س. ف) أخونا عرضنا بعض أسئلته في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد يقول فيه: لماذا إذا لم يصل الشخص يكون خارجًا عن الملة؟ وإذا تاب لا يقضي صلواته التي لم يصلها؟ ولماذا يقضي صومه إذا تاب؟ علمًا بأني لم أكن أصلي من قبل، أفيدوني عن هذه القضايا، جزاكم الله خيرًا.","title":"الفرق بين تارك الصلاة وتارك الصيام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.. أما بعد.  فينبغي أن يعلم أن الأحكام الشرعية إنما تؤخذ عن الله، وعن رسوله -عليه الصلاة والسلام- لا عن آراء الناس، فالأحكام التي يحكم بها على العباد في كفر، أو إيمان، أو طاعة، أو معصية إنما تؤخذ عن الله، وعن رسوله -عليه الصلاة والسلام- فمن ترك الصلاة فقد حكم عليه الرسول ﷺ بأنه كافر، كما أن من أشرك بالله، وعبد معه غيره فقد حكم الله عليه ورسوله بأنه كافر، وهكذا من استهزأ بالله، ودينه حكم الله عليه بأنه كافر. وهناك أحاديث أخرى كلها تدل على كفر تارك الصلاة؛ لأنها عمود الإسلام، وأعظم الأركان بعد الشهادتين، فلهذا كفر تاركها، وإذا أسلم لا يؤمر بالقضاء؛ لأن الرسول ﷺ لم يأمر الذين ارتدوا، ثم أسلموا أن يقضوا، بل قبل منهم إسلامهم، ولم يأمرهم بالقضاء، وهكذا الصحابة  لما قاتلوا أهل الردة لم يأمروهم بالقضاء بعدما أسلموا؛ لأن الإسلام يجب ما قبله، الإسلام توبة عظيمة تهدم ما قبلها؛ ولأن مطالبة الإنسان بقضاء ما فاته في حال الردة قد ينفره من الإسلام، قد يحول بينه وبين الدخول في الإسلام، فكان من حكمة الله ومن إحسانه إلى عباده أن جعل الإسلام يهدم ما كان قبله، يقول النبي ﷺ: الإسلام يهدم ما كان قبله فمن أسلم غفر الله له ما مضى من شرك، وغيره. أما من ترك الصيام فإنه مسلم لا يكون كافرًا إذا كان لم يجحد الوجوب، إذا كان ما جحد وجوب صوم رمضان، بل يعلم أنه واجب عليه، ولكن تكاسل، فأفطر في بعض الأحيان، هذا يكون عاصيًا، وعليه القضاء، والتوبة إلى الله . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16152/الفرق-بين-تارك-الصلاة-وتارك-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83301.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17370,"question":"في آخر أسئلة هذا السائل يقول: سماحة الشيخ هل يحق لي أن آخذ رأي والدي في البحث عن زوجة، وبدون أن أراها، أو أعرفها؟","title":"أفضلية مشاورة الأب في اختيار الزوجة","answer":"الجواب: الأفضل أن تشاور أباك، هذا من الأدب، ومن البر أن تشاوره فيمن تخطب، تقول: يا والدي! ممكن أريد فلانة، تشاور فيه، وتشاور من يعلمها من أهل الخير، ولا تعجل حتى تطمئن إلى أنها طيبة صالحة لقوله ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك تسأل عن دينها، وعن أخلاقها، وعما يتعلق بالترغيب فيها؛ حتى تقدم على بصيرة. ويستحب لك النظر إليها، إذا تيسر النظر تنظر إليها بإذن أهلها، أو بغير إذن، إذا تيسر النظر إليها، ولو بغير إذن أهلها في من كوة.. من باب.. من جهة أخرى، وهي في المرعى، من غير خلوة قال جابر  \"خطب امرأة، فلم يزل يتخبأ حتى نظر إليها\" والنبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وقال لرجل تزوج امرأة: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها. فالمقصود: النظر إليها مستحب إذا تيسر، ولو من دون علمها، لكن من دون خلوة، كأن ينظرها من بعيد، وهي في غنمها، أو في مجلس عند أهلها، أو ما أشبه ذلك. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16232/افضلية-مشاورة-الاب-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77009.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17374,"question":"في آخر أسئلة هذا السائل يقول: سماحة الشيخ هل يحق لي أن آخذ رأي والدي في البحث عن زوجة، وبدون أن أراها، أو أعرفها؟","title":"أفضلية مشاورة الأب في اختيار الزوجة","answer":"الجواب: الأفضل أن تشاور أباك، هذا من الأدب، ومن البر أن تشاوره فيمن تخطب، تقول: يا والدي! ممكن أريد فلانة، تشاور فيه، وتشاور من يعلمها من أهل الخير، ولا تعجل حتى تطمئن إلى أنها طيبة صالحة لقوله ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك تسأل عن دينها، وعن أخلاقها، وعما يتعلق بالترغيب فيها؛ حتى تقدم على بصيرة. ويستحب لك النظر إليها، إذا تيسر النظر تنظر إليها بإذن أهلها، أو بغير إذن، إذا تيسر النظر إليها، ولو بغير إذن أهلها في من كوة.. من باب.. من جهة أخرى، وهي في المرعى، من غير خلوة قال جابر  \"خطب امرأة، فلم يزل يتخبأ حتى نظر إليها\" والنبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وقال لرجل تزوج امرأة: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها. فالمقصود: النظر إليها مستحب إذا تيسر، ولو من دون علمها، لكن من دون خلوة، كأن ينظرها من بعيد، وهي في غنمها، أو في مجلس عند أهلها، أو ما أشبه ذلك. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16232/افضلية-مشاورة-الاب-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77009.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17417,"question":"في ثاني أسئلة هذه السائلة أم نايف من حائل تقول: لها ولد في الثامنة عشرة من العمر، تقول: آمره بالصلاة، ولا يعمل بها، ولا يرد علي، وعجزت عن ذلك كثيرًا ومرارًا، ثم تركته، فهل علي إثم في ذلك؟","title":"الواجب على الأم تجاه ابنها التارك للصلاة","answer":"الجواب: الواجب عليك أمره بالصلاة، وتحذيره، ونصيحته، وإذا كان أبوه موجودًا؛ فالواجب على أبيه كذلك، أن يقوم عليه حتى ولو بالضرب، حتى يستقيم، حتى يصلي، يقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فإذا كان ابن عشر يضرب، فالذي قد بلغ أولى وأولى بالضرب، بل يستحق أن يقتل، يستتاب فإن تاب وإلا قتل، الأمر عظيم، فإذا عجزت ارفعي بأمره إلى الهيئة، أو إلى المحكمة، أو إلى الإمارة؛ حتى يؤدبوه. المقصود: أن هذا الأمر عظيم، لا يجوز السكوت عنه، فإن كان أبوه موجودًا، أو له أخ كبير أكبر منه يساعدك في ذلك، وإلا ارفعي أمره، وإلا قولي له: ابعد عني، البيت يتعذر، لا تجلس عندي بالكلية، ترفعين أمره للهيئة، أو للإمارة، أو للمحكمة حتى يؤدب، وحتى يعامل بما يستحق لكونه قد بلغ الحلم، نعم. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16291/الواجب-على-الام-تجاه-ابنها-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77118.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":17421,"question":"في ثاني أسئلة هذه السائلة أم نايف من حائل تقول: لها ولد في الثامنة عشرة من العمر، تقول: آمره بالصلاة، ولا يعمل بها، ولا يرد علي، وعجزت عن ذلك كثيرًا ومرارًا، ثم تركته، فهل علي إثم في ذلك؟","title":"الواجب على الأم تجاه ابنها التارك للصلاة","answer":"الجواب: الواجب عليك أمره بالصلاة، وتحذيره، ونصيحته، وإذا كان أبوه موجودًا؛ فالواجب على أبيه كذلك، أن يقوم عليه حتى ولو بالضرب، حتى يستقيم، حتى يصلي، يقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فإذا كان ابن عشر يضرب، فالذي قد بلغ أولى وأولى بالضرب، بل يستحق أن يقتل، يستتاب فإن تاب وإلا قتل، الأمر عظيم، فإذا عجزت ارفعي بأمره إلى الهيئة، أو إلى المحكمة، أو إلى الإمارة؛ حتى يؤدبوه. المقصود: أن هذا الأمر عظيم، لا يجوز السكوت عنه، فإن كان أبوه موجودًا، أو له أخ كبير أكبر منه يساعدك في ذلك، وإلا ارفعي أمره، وإلا قولي له: ابعد عني، البيت يتعذر، لا تجلس عندي بالكلية، ترفعين أمره للهيئة، أو للإمارة، أو للمحكمة حتى يؤدب، وحتى يعامل بما يستحق لكونه قد بلغ الحلم، نعم. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16291/الواجب-على-الام-تجاه-ابنها-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77118.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":17424,"question":"رسالة وصلت إلى البرنامج من المستمع خالد الحربي يقول في رسالته: يوجد لي جد مصاب بالجلطة، غاب عن ذهنه لمدة ثلاثة أشهر، وهو الآن قد عاد، وبدأ يذكر الصلاة، وبدأ يصلي، لكنه لم يصم بطبيعة الحال، فكيف توجهوننا وحاله ما ذكر؟ جزاكم الله خيرًا.","title":"حكم قضاء الفرائض لمن فقد عقله مدة من الزمن","answer":"الجواب:  ليس عليه قضاء ما فات في حال ذهاب عقله، وليس عليه قضاء الصوم إذا كان رمضان صادفه في المدة التي غاب فيها عقله؛ لأنه قد رفع عنه القلم، وإنما يصلي مستقبلًا بعدما رجع إليه عقله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16286/حكم-قضاء-الفراىض-لمن-فقد-عقله-مدة-من-الزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83515.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17450,"question":"يقول هذا السائل: سماحة الشيخ! والدي هداه الله لا يصلي في المسجد، وإنما يصلي في البيت، ناصحته كثيرًا، فهل علي إثم تجاه والدي؟ وبماذا تنصحونني أن أفعل مأجورين؟","title":"واجب الابن تجاه أبيه التارك لصلاة الجماعة","answer":"الجواب: عليك أن تنصحه بالكلام الطيب، والأسلوب الحسن، ولا تقطع الزيارة؛ لأن حقه عظيم، قال الله في حق الولد مع الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران حق، الوالد عظيم، تزوره، تدعو له بالتوفيق والهداية، توصيه بالصلاة في المسجد، وأبشر بالخير، ولا تفعل بشيء يؤذيه من كلام سيئ، أو وجه معبس، لا، انبسط إليه، وتكلم معه، وانصحه، وادع له بالهداية، والتوفيق، ولا تقطع زيارته، حقه عظيم الوالد والوالدة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16319/واجب-الابن-تجاه-ابيه-التارك-لصلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77207.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17480,"question":"يقول السائل: سماحة الشيخ! حاليًا أعمل هنا في المملكة حيث كنت لا أصلي في جميع الأوقات، والآن -ولله الحمد- التزمت، وأصوم أيام ثلاثة عشر، وأربعة عشر، وخمسة عشر من كل شهر -والحمد لله- كما أداوم على قراءة القرآن الكريم في أكثر الأوقات، و كنت في السابق لم أصل إلا ما ندر، ولا أصوم في رمضان، وهجرت القرآن، هل علي إعادة لتلك الأيام سماحة الشيخ؟","title":"حكم قضاء التائب للصلاة والصوم","answer":"الجواب: ليس عليك إعادة، التوبة تجبُّ ما قبلها، والإسلام يهدم ما كان قبله، والحمد لله، ما دمت رجعت إلى دين الله، وأسلمت وتبت؛ فالذي مضى ليس عليك قضاء، ولكن عليك لزوم التوبة والاستقامة، وكثرة العمل الصالح، والاستغفار، وأبشر بالخير، أبشر بالخير، التوبة تجبُّ ما قبلها، والإسلام يهدم ما كان قبله، والحمد لله، نعم. المقدم: بعض الشباب سماحة الشيخ يتذكر تلك الأيام، ويوسوس له الشيطان عن تلك الأيام التي لم يصلها، أو لم يصم فيها، هل من توجيه لأولئك الذين عادوا إلى الله؟ الشيخ: لا، عليه أن يتعوذ بالله من الشيطان، إذا خطر له هذه الوساوس؛ عليه أن يقول: أعوذ بالله من الشيطان الرجيم، يتعوذ بالله من الشيطان الرجيم، يحسن ظنه بربه، ويكثر من الاستغفار، ويكثر من التعوذ بالله من الشيطان، ولا يضره ذلك، الشيطان يوسوس، ويؤذي المؤمن، ولكن عليه أن يكون قويًا ضد عدو الله، وأن يستعيذ بالله من الشيطان، وأن يحذر الوساوس، ويحمد ربه على ما منَّ به عليه من التوبة. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16388/حكم-قضاء-التاىب-للصلاة-والصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77315.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17484,"question":"بعد هذا ننتقل إلى قضية يثيرها الأخ: يوسف عمر علي الصومالي، الأخ يقول: إنه انتشر في الوقت الحاضر دعوة بين الناس، وفتوى تجيز العقد على المرأة الحامل غير المتزوجة، سواء للذي أحبلها، أو لغيره، ويقول: إن هذا الموضوع انتشر، ويرجو من سماحتكم معالجته، وتنبيه الناس إلى خطورته، وبيان الحكم الشرعي فيه، جزاكم الله خيرًا.","title":"حكم عقد النكاح بامرأة حامل","answer":"الجواب: الحامل من الزنا، أو من غير الزنا، لا يجوز العقد عليها حتى تطهر، لقول النبي ﷺ بل لقول الله : وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] ولقول النبي ﷺ ينهانا: من كان يؤمن بالله واليوم الآخر، فلا يسقي ماءه زرع غيره يعني: منيه زرع غيره يعني حمل غيره.  فإذا كانت حاملًا من المطلق، أو الميت، فليس لها أن تتزوج حتى تضع الحمل، وإذا كانت حاملة من الزنا، فليس لها أن تتزوج لا بالزاني، ولا بغيره حتى تضع؛ لأن حملها مشوب بنطفة لا تنسب للزاني، ولا لغيره، ينسب لأمه، فالزاني لا ينسب إليه الطفل، مثلما قال النبي ﷺ: الولد للفراش، وللعاهر الحجر.  فالولد لأمه إذا كانت ليست فراش، وإن كانت فراشًا فالولد لزوجها، والزاني يأخذ الحد الشرعي، فإذا حملت وهي ليست ذات زوج فإنها لا يجوز تزوجها مطلقًا في أي بلاد الله حتى تضع الحمل، فإذا وضعت الحمل؛ جاز لها التزوج بعد التوبة، والرجوع إلى الله، والإنابة، فيجوز للمسلم أن يتزوجها بعد التوبة. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16387/حكم-عقد-النكاح-بامراة-حامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72511.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","مبطلات النكاح"]},{"id":17634,"question":"رسالة وصلت إلى البرنامج من المستمع عبد الرزاق محمد صالح العلمي من اليمن-بيحان يقول في رسالته: ما حكم من سكن مع مجموعة من الشباب لكنهم لا يصلون صلاة الصبح في وقتها بل يتركونها حتى قيامهم للعمل ثم يصلون، أمرهم بهذا ولم يستجيبوا؟ ويسأل توجيهكم، جزاكم الله خيرًا.","title":"حكم السكن مع أناس يؤخرون صلاة الصبح","answer":"الجواب: الواجب أمرهم بالمعروف ونهيهم عن المنكر والإنكار عليهم وتحذيرهم من مغبة ذلك فإنه لا يجوز تأخير الصلاة عن وقتها، الله كتب على المسلمين الصلاة مؤقتة إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103]، وأمر أن تؤدى في وقتها، أمر الله أن تؤدى في وقتها وهكذا رسوله عليه الصلاة والسلام يقول جل وعلا: أَقِمِ الصَّلاةَ لِدُلُوكِ الشَّمْسِ إِلَى غَسَقِ اللَّيْلِ وَقُرْآنَ الْفَجْرِ [الإسراء:78] يعني: صلاة الفجر إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا [الإسراء:78]. فالواجب أن تؤدى في الوقت ولا يجوز للمسلم أن يؤخر صلاة الفجر إلى بعد طلوع الشمس حتى يقوم لعمله، بل يجب عليه أن يصليها في الوقت، وإذا تعمد ذلك يكفر عند جمع من أهل العلم إذا تعمد ذلك قصد ذلك كفر عند جمع من العلماء، لقوله ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة. ومن أخرها عن الوقت عمدًا فقد تركها، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، فالواجب الحذر الواجب على المؤمن أن يحذر هذه المحارم العظيمة، ولو قيل بعدم كفره يجب عليه أن يحذر؛ لأنها معصية عظيمة وكبيرة عظيمة حتى ولو قلنا بعدم الكفر مع أن القول القوي والقول الراجح كفر من ترك الصلاة، وإن لم يجحد وجوبها؛ لهذا الحديث الصحيح وما جاء في معناه يقول ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، رواه مسلم في الصحيح. فالذي ترك الصبح حتى طلعت الشمس قد تعمد تركها، وإذا ترك العصر حتى غابت الشمس قد تعمد تركها، وإذا ترك العشاء حتى غاب طلع الفجر فقد تعمد تركها، يقال له: إنه ما صلى، ويقال له: ترك الصلاة، وإذا ترك الخمس جميعًا صار أشد في الكفر، فالذي يترك واحدة أو ثنتين حكمه حكم من ترك الجميع، والله يقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، يعني: حافظوا عليها في وقتها، يجب أن يحافظ عليها في وقتها، ولا يجوز التشبه بأهل النفاق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16564/حكم-السكن-مع-اناس-يوخرون-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84406.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":17650,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من الرياض، باعثتها إحدى الأخوات المستمعات تقول: أختكم أم هاجر، أم هاجر لها رسالة، وضمنتها جمعًا من الأسئلة، في أحدها تقول: إنني زوجةٌ والحمد لله مسلمةٌ مصلية، ولي زوجٌ مسلم، أدعو الله أن يجازيه خيرًا عن معاملته الطيبة لي، ولا أعتب عليه يا سماحة الشيخ في شيء، غير أنه يعمل دوامين، ويعود متأخرًا حوالي الحادي عشرة مساءً، ولأنني وحيدة، ولا أخرج تقريبًا أبدًا إلا يوم إجازته، فهو يسهر معي حتى يؤنس وحشة الوحدة، وعندما أستيقظ في الفجر لأصلي، أوقظه، ولكن نومه ثقيل، وطلب مني أن أمسح وجهه بالماء حتى يستيقظ، ولكنه في بعض الأحيان لا يستيقظ نتيجةً لذلك السهر، فهل علي إثم؟ وهل علي أنا إثمٌ في أنني فشلت في إيقاظه؟ وهل هناك أكثر من الماء لإيقاظه؟ وجهوني، ووجهوا ذلك الرجل جزاكم الله خيرًا.","title":"توقظ زوجها لصلاة الفجر فلا ينهض أحيانا من التعب والسهر","answer":"الجواب: أنت مأجورة، جزاك الله خيرًا على عملك، وهذا عملٌ طيب، وهذا من التعاون على البر والتقوى، وليس عليك، ولا عليه شيء، إذا كان غلبه الأمر، وليس باختياره، ولم يتعمد التساهل في ترك الصلاة ذلك الوقت، حين مسحت وجهه بالماء، ومسح الوجه بالماء جاء به النص عن النبي ﷺ، رش الماء، رش الزوج بالماء، وإيقاظه بالماء؛ هذا جاء به النص، فأنت مأجورة، وهو مأجور حين أمرك بذلك، وسمح بذلك، وأنتما على خير إن شاء الله. لكن ينصح هو بأن يترك أحد الدوامين، يستقيل من أحد الدوامين، يطلب من مرجعه أن يسامح أحد الدوامين، حتى لا يتعب نفسه، ولا يشق على نفسه، ولا على أهله، وحتى لا يضيع الصلاة، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، سوف يرزقه الله إن شاء الله ما يغنيه هذا عن الدوام الثاني، حتى يستريح، ويريح أهله، ويحافظ على ما أوجب الله عليه؛ لأن الإنسان طاقته محدودة، فينبغي له أن لا يكلف نفسه دوامين، مادام بهذه الحالة؛ يشق على نفسه، ويشق على أهله، وربما ترك الصلاة في الجماعة بسبب ذلك، ولو كان على غير عمد واختيار، لكن يكون متسبب في هذا الشيء. فالذي ننصحه في هذا؛ أن يدع أحد الدوامين حتى يتفرغ لإيناس أهله، وراحة نفسه وبدنه، وراحة قلبه، وحتى يحافظ على الصلوات مع الجماعة في أوقاتها، هذا فيه خيرٌ عظيم.\nأما إذا كان تركه للقيام للصلاة من أجل غلبة النوم، ولم يتعمد ذلك، ولم يتساهل في ذلك، ولكن غلب في بعض الأحيان، فلا يضره ذلك، إذا غلب في بعض الأحيان، لكن أخشى عليه أن يكون في ظاهر الدوامين نوع من الجشع، والحرص على المال، فيضره ذلك؛ لأنه يسبب له هذه المشاكل، مع أهله، وفي الصلاة، فإنه مطلوب منه أن يؤنس أهله، وأن يجتهد في الإحسان إليهم، وفي إحسان عشرتهم، كما قال تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وباتخاذ الأسباب التي تعينه على الصلاة في الجماعة، وأدائها مع إخوانه، فأخشى أن يكون هذا الدوام الثاني، أن يكون عليه فيه تبعة، إذا كان غير مضطر إليه، نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16582/توقظ-زوجها-لصلاة-الفجر-فلا-ينهض-احيانا-من-التعب-والسهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72703.mp3","categories":["حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":17662,"question":"إذا كان هناك إنسان مات وهو لا يصلي، ولم يكن يعلم أن تارك الصلاة كافر، فهل يغفر الله له، لجهله؟","title":"حكم من مات وهو لا يعلم حكم تارك الصلاة","answer":"الجواب: ظاهر الأدلة الشرعية؛ أنه لا يغفر له؛ لأنه ليس من شرطه أن يعلم الحكم، هو مأمورٌ بالصلاة؛ عليه أن يصلي، مأمورٌ بالزكاة؛ عليه أن يزكي، وهكذا.\nفالحاصل؛ أنه إذا ترك الصلاة عمدًا، فهو كافر على الصحيح من أقوال العلماء، وإن لم يجحد وجوبها، أما إذا جحد الوجوب؛ صار كافرًا عند جميع العلماء، نسأل الله العافية، لكن إذا تركها تكاسلًا، وتساهلًا، فالصحيح أنه يكفر بذلك، لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك، ترك الصلاة خرجه مسلم في صحيحه، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر رواه الإمام أحمد وأهل السنن بإسنادٍ صحيح، ولأدلةٍ أخرى، ولأن تركه لها يدل على قلة الإيمان، أو عدم الإيمان، نسأل الله العافية؛ لأنها عمود الإسلام، نسأل الله العافية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16591/حكم-من-مات-وهو-لا-يعلم-حكم-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72707.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":17955,"question":"سماحة الشيخ! هذه سائلة تقول: عندما كنت صغيرة وحتى كبرت كنت أعيش تحت رعاية أبي ولم أكن أصلي ولم أكن أصوم وذلك جهلًا مني، وعندما تزوجت هذه المرأة تقول: ومن ذلك الوقت وأنا أصوم وأصلي والحمد لله، ماذا يجب علي أن أفعل في الصلاة والصيام السابق أيام شبابي مع العلم بأنني تبت إلى الله وندمت على هذا العمل؟","title":"حكم من كان لا يصلي ولا يصوم ثم تاب","answer":"الجواب: التوبة كافية، إنسان ما يصلي ولا يصوم ثم تاب التوبة كافية وليس عليه قضاء، الحمد لله، يقول جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ[الأنفال:38]، ويقول النبي ﷺ: التوبة تجب ما قبلها فالكافر إذا أسلم وتاب تاب الله عليه، ولم يلزمه قضاء ما مضى، وهكذا الذي لا يصلي إذا تاب تاب الله عليه، ولا يلزمه القضاء، لا صوم، ولا صلاة، ولا غير ذلك، التوبة تجب ما قبلها نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16977/حكم-من-كان-لا-يصلي-ولا-يصوم-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78017.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17960,"question":"سماحة الشيخ! الأخت السائلة أم أحمد من الزلفي تقول: زوجي هداه الله لا يصلي، وقد ناصحته كثيرًا، فهو يترك بعض الأوقات ويصلي بعض الأوقات في البيت، هل من توجيه من سماحة الشيخ عبد العزيز حفظه الله؟","title":"حكم البقاء مع زوج لا يصلي إلا أحيانًا","answer":"الجواب: الواجب على كل مسلم أن يتقي الله، وأن يراقب الله، وأن يصلي الصلوات الخمس كلها في الجماعة في المساجد، ولا يجوز له ترك شيء منها، ولا الصلاة في البيت، هذا منكر، النبي ﷺ يقول: من سمع النداء فلم يأت يعني: إلى المسجد فلا صلاة له إلا من عذر قيل لـابن عباس: ما هو العذر؟ قال: خوف أو مرض»، «وجاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب.\nوقال ﷺ: لقد هممت أن آمر بالصلاة تقام، ثم آمر رجلًا فيؤم الناس، ثم أنطلق إلى رجال لا يشهدون الصلاة فأحرق عليهم بيوتهم، هذا لا يجوز للمؤمن أن يصلي في البيت، بل يجب أن يصلي مع الناس، والذي يترك الصلاة كافر، نسأل الله العافية.\nيقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، ويقول ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة. فإذا كان لا يصلي بعض الأوقات اتركيه، اذهبي إلى بيت أهلك لا تجلسي عنده؛ لأن ترك الصلاة كفر، نسأل الله العافية، فإذا كان هكذا ولم يسمع منك ولم يقبل النصيحة؛ اتركيه واذهبي إلى أهلك، حتى يهديه الله أو يطلق.\nالمقدم: جزاكم الله خيرًا على هذا التوجيه سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16972/حكم-البقاء-مع-زوج-لا-يصلي-الا-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59833.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":17973,"question":"لي أخت عمرها ست وعشرون سنة كانت في بداية عمرها لا تصلي، ثم أصبحت تصلي فقط في شهر رمضان، ولها الآن خمس سنين تصلي عشرة أيام وتترك بقية الشهر، وأحيانًا تصلي الشهر كاملًا، وأحيانًا لا تصلي تقريبًا، قضت أكثر من شطر عمرها لا تصلي، فهل تقضي ما فاتها من الصلوات؟ أم تكفي التوبة؟","title":"ما حكم قضاء الصلاة لمن تاب من تركها؟","answer":"الجواب: هي بعملها هذا كافرة -نعوذ بالله-، فعليها التوبة إلى الله والندم والإقلاع والعزم أن لا تعود، ويكفي هذا والحمد لله، يقول الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، ويقول النبي ﷺ: التائب من الذنب كمن لا ذنب له. فعليها أن تتوب إلى الله توبة صادقة بالندم على الماضي، والعزم الصادق أن لا تعود فيه، والمحافظة على الصلوات الخمس في أوقاتها، ويكفي هذا والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17010/ما-حكم-قضاء-الصلاة-لمن-تاب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84817.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":17979,"question":"لي أخت عمرها ست وعشرون سنة كانت في بداية عمرها لا تصلي، ثم أصبحت تصلي فقط في شهر رمضان، ولها الآن خمس سنين تصلي عشرة أيام وتترك بقية الشهر، وأحيانًا تصلي الشهر كاملًا، وأحيانًا لا تصلي تقريبًا، قضت أكثر من شطر عمرها لا تصلي، فهل تقضي ما فاتها من الصلوات؟ أم تكفي التوبة؟","title":"ما حكم قضاء الصلاة لمن تاب من تركها؟","answer":"الجواب: هي بعملها هذا كافرة -نعوذ بالله-، فعليها التوبة إلى الله والندم والإقلاع والعزم أن لا تعود، ويكفي هذا والحمد لله، يقول الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، ويقول النبي ﷺ: التائب من الذنب كمن لا ذنب له. فعليها أن تتوب إلى الله توبة صادقة بالندم على الماضي، والعزم الصادق أن لا تعود فيه، والمحافظة على الصلوات الخمس في أوقاتها، ويكفي هذا والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17010/ما-حكم-قضاء-الصلاة-لمن-تاب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84817.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":17990,"question":"هذا السائل من اليمن يقول سماحة الشيخ: ما حكم الصيام بلا صلاة، هل صحيح أن الصيام يقبل ويتحمل الإنسان الإثم بعد ذلك بتركه الصلاة؟ أم ماذا مأجورين؟","title":"ما حكم الصيام بلا صلاة؟","answer":"الجواب: الصواب أنه لا يقبل لأنه كافر، من ترك الصلاة كفر، وتبطل أعماله كما قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ[الأنعام:88]، والرسول عليه الصلاة والسلام قال: بين الرجل وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه، وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر أخرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة . وقال عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة وكان أصحاب النبي ﷺ لا يرون شيئًا تركه كفر إلا الصلاة، تركها كفر أكبر، نسأل الله العافية، هذا هو الصواب من قولي العلماء، وقال بعض أهل العلم: لا يكفر بذلك إلا إذا جحد وجوبها، لكن يكون كفرًا أصغر لا كفرًا أكبر، إذا تركها من دون جحد قالوا: هذا كفر أصغر، والصواب أنه كفر أكبر لظاهر الحديث لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17037/ما-حكم-الصيام-بلا-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78103.mp3","categories":["حكم الصلاة وأهميتها","مسائل متفرقة في الصيام"]},{"id":18022,"question":"أيضًا تسأل سؤال طويل وتقول فيه: إنها متزوجة، وعندها أطفال وزوجها يستعمل المنكرات، ولا يحافظ على الصلوات فهو يصلي يومًا ويتركها أسبوع، وأنا لا أستطيع أن أترك البيت بسبب أطفالي، وأنا متبرئة منه ومن فعله، وأنا والحمد لله مسلمة أحافظ على صلواتي وأطيع ربي والحمد لله، ولكن مشكلتي في زوجي.أريد من سماحة الشيخ أن تتفضل بحل مشكلتي؛ ذلكم أنه ساءت معاملته معي وأذنب في حقنا الشيء الكثير، ما حكم جلوسي معه ومع أطفالي؟ جزاكم الله خيرًا.","title":"واجب المرأة تجاه زوجها التارك للصلاة","answer":"الجواب: الواجب عليك الخروج بأطفالك إلى أهلك إذا أمكن ذلك؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء، ولو كان لم يجحد وجوبها، أما إذا جحد وجوبها كفر بالإجماع، لكن إذا لم يجحد وجوبها فإنه يكفر بتركها في أصح قولي العلماء؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه عن جابر  . ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن الأربع بإسناد صحيح عن بريدة ، مع أحاديث أخرى في ذلك. فإن لم تستطيعي الخروج جلست مع أولادك ومنعتيه نفسك لا تمكنيه من نفسك، لا من جماع، ولا تقبيل ولا غير ذلك حتى يستقيم حتى يصلي، وارفعي بأمرك إذا امتنع ارفعي بأمرك إلى المحكمة حتى تفرق بينك وبينه، وإن هداه الله بأسبابك وتاب إلى الله وصلى فالحمد لله، وإلا فالواجب عليك الامتناع منه، وأن لا يقربك لا بقبلة، ولا بجماع ولا بأشباه ذلك، ولك الخروج إلى بيت أهلك إن تيسر ذلك، بل يلزمك الخروج حتى تبتعدي عن طاعة الشيطان في حقه. ونسأل الله له الهداية، نسأل الله أن يمن عليه بالهداية. نعم.","link":"https://binbaz.org.sa/fatwas/17051/واجب-المراة-تجاه-زوجها-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85004.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":18041,"question":"سماحة الشيخ! يسأل أخونا فيصل أحمد عبد الله من حائل ويقول: أرجو أن توضحوا عقوبة تارك الصلاة وهو مؤمن بوجوبها، وأن توضحوا لنا عافاكم الله فضل صلاة الفجر، وعقوبة من لم يؤدها في وقتها، جزاكم الله خيرًا.","title":"ما عقوبة تارك الصلاة تكاسلًا؟","answer":"الجواب: من ترك الصلاة فعقوبته القتل، يستتاب فإن تاب وإلا قتل، قال الله سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدل على أن من لا يقيم الصلاة لا يخلى سبيله بل يقتل، يستتاب فإن تاب وإلا قتل، وقال عليه الصلاة والسلام: إني نهيت عن قتل المصلين فالمصلي لا يقتل إذا استقام، أما من ترك الصلاة فإنه يستتاب، فإن تاب وإلا وجب قتله مرتدًا على أصح القولين، وعند جماعة من أهل العلم لا يكون مرتدًا ولكن يكون قتله حدًا، إذا قلنا بأن تركها ليس بكفر أكبر إذا كان يقر بوجوبها ولا يجحده، والصواب: أنه يقتل كفرًا إذا كان تاركًا لها يستتاب، فإن تاب وإلا قتل كفرًا، لا حدًا، ويبعد جدًا أن يكون يقر بوجوبها ثم يصر على عدم فعلها حتى يقتل، هذا بعيد جدًا. والمقصود أنه يقتل كفرًا مطلقًا مادام أبى أن يصلي واستتيب وأبى؛ فإنه يقتل كفرًا، نسأل الله العافية، لا يكون مسلمًا، سواء كانت الصلاة فجرًا أو ظهرًا أو عصرًا أو مغربًا أو عشاء، والفجر لها شأن خاص؛ لأنه يتكاسل عنها المنافقون، وقد جاء فيها أحاديث كثيرة، ولهذا قال عليه الصلاة والسلام: أثقل الصلاة على المنافقين صلاة العشاء وصلاة الفجر، ولو يعلمون ما فيهما لأتوهما ولو حبوًا، وقال عليه الصلاة والسلام: من صلى الصبح فهو في ذمة الله فلا يطلبنكم الله بشيء من ذمته، فإنه من يطلبه شيئًا من ذمته يدركه، ثم يكبه في النار. الصلاة لها شأن عظيم، سواءً كانت صبحًا أو ظهرًا أو عصرًا أو مغربًا أو عشاء، ولكن للصبح خصائص؛ لأنها تكون في آخر الليل عند حلاوة النوم في الصيف، وعند شدة البرد في الشتاء، فربما تثاقل عنها الكسالى وتشبهوا بأهل النفاق، فجاء فيها تأكيد، يجب على المؤمن أن يعتني بها حتى يتباعد عن مشابهة المنافقين، ولا يجوز له تركها حتى تطلع الشمس، كما يفعل بعض الناس، يصليها إذا قام للعمل، هذا منكر عظيم، وشر مستطير، يجب على صاحبها أن يتقي الله وأن يصليها في الوقت مع المسلمين في جماعة المسلمين في مساجد الله، ومن علم بهذا وجب أن يستتاب، فإن تاب وإلا قتل؛ لأن تركها حتى يخرج وقتها منكر عظيم، بل كفر عند جمع من أهل العلم إذا تعمد ذلك، نسأل الله للجميع الهداية والسلامة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17074/ما-عقوبة-تارك-الصلاة-تكاسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60006.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":18049,"question":"يسأل سماحتكم عن موقف الإسلام من المتخاذلين والمتكاسلين عن الصلاة؟","title":"ما حكم المتكاسلين عن الصلاة؟","answer":"الجواب: موقف الإسلام؛ أنهم متهمون بالنفاق بهذا، إذا عرفوا بالكسل عن الصلوات، فهذا علامة النفاق، موقف الإنسان منهم ذمهم، وعيبهم على هذا، وأن الإسلام يذم من تخلف عن الصلوات، وتكاسل عنها، وصف الله بهذا المنافقين، قال تعالى: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142]. فليفتش الإنسان عن عيوبه، وليتب إلى الله منها، فإذا كان من عيوبه، التكاسل عن الصلاة، فليعلم أن هذا من صفات أهل النفاق، وليبادر بالتوبة إلى الله من ذلك، وليحذر التخلق بأخلاقهم. وهكذا إذا كان من عيوبه التدليس والغش للناس، هذا من أعمال المنافقين أيضًا، يخادعون الله وهو خادعهم، آية المنافق ثلاث، يقول النبي ﷺ: آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا اؤتمن خان، هذه من صفات المنافقين نعوذ بالله. ومن صفاتهم: قلة ذكر الله، من صفاتهم أنهم أهل غفلة، لا يذكرون الله إلا قليلًا، ومن صفاتهم: الرياء في أعمالهم، يصلي يراءي، يقرأ يراءي، يتكلم بالخير يراءي، فالواجب الحذر من صفاتهم، وأن يكون في أعماله مخلصًا لله، تريد وجهه الكريم، لا رياءً ولا سمعة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17082/ما-حكم-المتكاسلين-عن-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72907.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":18097,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من نينوى باعثة الرسالة إحدى الأخوات من هناك تقول السائلة (ل. ع. ج) أختنا تقول: أول سؤالي هو: أنا فتاة تزوجت من رجل لا يصوم ولا يصلي ويشرب الخمر، وكنت أنا أيضًا لا أصلي ولا أصوم، وبعد فترة من زواجي هداني الله  إلى الصلاة والصوم والحمد لله.أما بعد: فإني أريد أن أشرح لك حالتي مع زوجي هو أنني ساكنة في بيت أهله الذي يتكون من أربعة غرف، فكل واحد من إخوانه هو وزوجته ساكن في غرفة وليس لهم أطفال، أما أنا فغرفتي مكان للجلوس والأكل وللزوار، ومع العلم أن لي أربعة أطفال، ومع هذا كله فإن زوجي يعاملني معاملة قاسية ولا يصرف علي، ولا يعطيني أي شيء، ويشتمني ويشتم أهلي، وإذا مرضت أنا أو أطفالي فلا يقبل أن يعطيني أي مصروف، بل هو الذي يطلب مني مصروفًا، مع العلم أنه لا يوجد لي أي مورد.وكذلك فإنه يحرمني من رؤية أهلي وإخواني، أما من ناحيتي أنا فإنني أقوم بواجبه وواجب والدته على كل حال، وكذلك أقوم بواجب إخوانه المتزوجين وعلي مسؤولية البيت كله، وكذلك والدته تعاملني وتعامل أطفالي بقسوة وتقتلهم -لعلها تقصد الضرب- ولا أستطيع أن أعمل شيئًا، أرشدوني ماذا أفعل؟ جزاكم الله خيرًا، وماذا تنصحون هذه الأسرة في هذه المعاملة تجاهي؟","title":"ماذا تفعل مَنْ زوجها لا يصلي ولا يقوم بحقهم؟","answer":"الجواب: الحمد لله الذي هداك للصلاة والصيام وأعاذك من الشيطان، هذه أعظم نعمة وأكبر نعمة والحمد لله على ذلك. أما ما ذكرت من سوء المعاملة من الزوج ومن أم الزوج فعليك يا أيها الأخت في الله الصبر والاحتساب وفعل الخير، وصاحب الخير لا يندم بل عاقبته حميدة، لكن إن كان الزوج لا يصلي كما ذكرت سابقًا فلا خير فيه، ولا ينبغي البقاء معه بل ينبغي أن تذهبي لأهلك مع أطفالك ولا ينبغي البقاء معه مادام بهذه الحالة السيئة، لا يصلي ويشرب الخمر ويسيء العشرة؛ فهذا لا وجه للبقاء معه وسوف يعطيك الله خيرًا منه. فينبغي لك أن تبتعدي عنه وأن تذهبي إلى أهلك، وهو إن هداه الله بعد ذلك نظر في الأمر، وإلا فسوف يعطيك الله خيرًا منه وأفضل: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:1-3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. أما إن هداه الله ورجع إلى الصواب وتاب إلى الله وأدى الصلاة وترك المسكرات وأحسن العشرة فالحمد لله، نسأل الله له الهداية، أما إذا بقي على حاله فنصيحتي لك البعد عنه لئلا يضرك ويضر أولادك، ولئلا يجرك إلى شره، ولئلا يجر أولاده إلى شره أيضًا من ترك الصلاة وشرب المسكرات وسوء الأخلاق، نسأل الله السلامة والعافية. الحاصل من هذا والخلاصة: أني أنصحك أن تذهبي إلى أهلك بأولادك وأن تدعيه مادام على هذه الحالة السيئة من ترك الصلاة وتعاطي المسكرات، ونسأل الله لنا وله الهداية، ونسأل الله لك تيسير الأمور وتفريج الكروب وحسن العاقبة، وأن يثيبك على ما فعلت من الخير، وأن يرده للصواب وأن يهديه للصواب، وأن يهدي أمه أيضًا للصواب وحسن المعاملة إنه جل وعلا جواد كريم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17132/ماذا-تفعل-من-زوجها-لا-يصلي-ولا-يقوم-بحقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90304.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":18168,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. م. ع) يقول فيها: يزورنا أحيانًا بعض الناس التاركين للصلاة ولكن دائم النصيحة لهم والإلحاح عليهم ، ومع ذلك ترق قلوبهم ، فهل لهم حق الضيافة؟ وماذا علي أن أفعل نحوهم جزاكم الله خيرًا.","title":"حكم ضيافة تارك الصلاة المُصِرِّ على ذلك","answer":"الجواب: قد أحسنت في نصيحتهم وأمرهم بالمعروف وإرشادهم إلى الخير ، وإذا لم يتوبوا ولو يرعووا فالواجب هجرهم وعدم إجابة دعوتهم وعدم دعوتهم إلى بيتك ، وعدم اتخاذهم أصحابًا وأصدقاء ، معارفهم من الزيارة ؛ . وفور ترك الصلاة كفر بنص الرسول عليه الصلاة والسلام. والصحيح أنه كفر أكبر ، هذا صحيح من الصحيح  ، وخرج الإمام أحمد وأهل السنن الأربع بإسناد صحيح عن بريدة  عن النبي عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر . هؤلاء الذين عرفتهم بترك الصلاة وقد تكرر منك النصح لهم ، ثم لم يستجيبوا وفهمهم جديرون بالهجر والإنكار وإظهار البغضاء لهم حتى يرجعوا عن باطلهم ، وليس لهم حق الضيافة إذا جاء إليك ؛ لأنهم مرتدون بهذا العمل وقد نصحتهم وكررتهم عليهم ، وليسوا ضيوفًا بذلك ، هؤلاء وأرادوا ذلك أرادوا هذه الزيارة التي أنت تكرههم من أجل ما هم عليه من الباطل ، بخلاف الضيف الكافر الذي لم يقدم له نصح ولم يجر بينك وبينه مذاكرة في هذا الأمر ، فهذا حق الضيافة مع النصيحة. أما بالنسبة لك ، فهكذا عليك أن تشير إلى أن هذا لا يعني أن عليك أن تنكر عليه وأن تهجره حتى يتوب إلى الله ومعهروف ومعهروف عن المنكر ، كما قال عليه الصلاة والسلام: من دل على خير فله مثل أجر فاعله  وقد هجر النبي ، أقل من هذا ، فإن مالك  الأنصاري وصاحبيه لما تخلفوا عن غزوة تبوك وهم قادرون على المشاركة في الغزو وقد أبلغوا وعرفوا وجوب النفير فتخلفوا بدون عذر ، خمسين ليلة ، حتى تاب الله عليهم ، فكيف بحال من ترك الصلاة عمداً بغير عذر شرعي وبغير حق بلقيم التساهل والتهاون بأمرها وهو جدير بالهجر وجدير بالعداوة والبغضاء. \nوجلست تبجيل ، وجل مرة أخرى. : فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ  [التوبة: 5]. ثم قال: إن نهيت عن قتل المصلين  وثبت عنه عليه الصلاة والسلام قال: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا وأني رسول الله ويقيموا الصلاة ويؤتوا الزكاة ، ورسول فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله   متفق على صحته. والخلاصة: أن من ترك الصلاة عمدًا عدوانًا من غير جحد لوجوبها ؛ يبدو أنه كافرًا في أصح قولي العلماء وعلى أمر المسلمين استتابته ، أما إن كان جاحداً في أصح أقوال أهل العلم ، أما إن كان جاحداً لوجوبها لا يؤمن ؛ يجد كافه عند جميع العلماء ولو صلى متى جحد الوجوب كفر إجماعاً ، ولو فعلها نسأل الله العافية والسلامة. نعم.","link":"https://binbaz.org.sa/fatwas/17234/حكم-ضيافة-تارك-الصلاة-المصر-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_855/nour_85504.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":18178,"question":"كنت من قبل لا أواظب على الصلاة والصوم، ثم تبت إلى الله والحمد لله، وقد سمعت في برنامجكم أن الصلاة لا تقضى، فهل الصوم كذلك، أم أن الصوم يجب قضاؤه؟ علمًا بأنني لا أعلم كم صمت وكم أفطرت.","title":"حكم قضاء الصلاة والصوم لمن تاب من تركهما","answer":"الجواب: أما الصلاة فمن تركها عمدًا لا يقضي بل عليه التوبة إلى الله ؛ لأن تركها ردة عن الإسلام والمرتد لا يقضي ما ترك، فعليه أن يتوب إلى الله، وأن يبادر بالصلاة، ويسأل الله العفو عما مضى. أما إذا كان المؤمن يصلي والمؤمنة تصلي ولكن تتساهل في بعض الصيام فإنه يقضي؛ لأن ترك الصيام ليس بردة عن الإسلام، ولكنه معصية كبيرة؛ فإذا تركت المرأة قضاء الصوم أو الرجل قضاء الصوم؛ فإنه يلزمه التوبة إلى الله مع قضاء الصوم، وعليه مع ذلك إطعام مسكين عن كل يوم إذا تأخر القضاء عن رمضان الذي يلي رمضان الذي تركه منه؛ فإنه يقضي ويطعم مسكين عن كل يوم نصف صاع من قوت البلد مقداره كيلو ونص تقريبًا من جهة الوزن مع الصوم ومع التوبة إلى الله  وقد أفتى بالطعام جماعة من أصحاب النبي ﷺ كفارة وتعزيرًا للمتخلف في قضاء صومه. نعم.","link":"https://binbaz.org.sa/fatwas/17223/حكم-قضاء-الصلاة-والصوم-لمن-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":18194,"question":"على بركة الله نبدأ برسالة أم عمار من الجبيل، كتبت هذه الرسالة بأسلوبها الخاص وتذكر يا سماحة الشيخ بأنها امرأة متزوجة ولديها ولد طفل، ملتزمة بأوامر الله، وتحمد الله، وتشكره على ذلك، تذكر بأن زوجها متهاون في الصلاة، ويشرب المسكر، قدمت له النصيحة عدة مرات، ومرة يستجيب ومرة يعاند ويكابر، تقول: الآن لنا سنتين من زواجنا صبرت لعل الله  أن يهديه، والسؤال يبقى يا سماحة الشيخ! هل أخبر أهلي وأنفصل عنه أم ماذا؟أصبر من باب الرضا بالقضاء والقدر على أمل أن يهديه الله، وأخشى إن انفصلت عنه أن يأخذ مني أبنائي أو ابني؟ فأرجو إرشادي سماحة الشيخ إلى ما فيه خير ديني ودنياي.","title":"حكم الزوج المتهاون بالصلاة والشارب للمسكر","answer":"الجواب: بسم الله الرحمن الرحيم،الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: هذا الزوج في أمره تفصيل، إن كان لا يصلي بعض الأحيان فالواجب عليك تركه، والذهاب إلى أهلك، وعدم البقاء معه؛ لأن ترك الصلاة كفر أكبر لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، أما إذا كان يصلي ولكن قد يصلي في البيت ما يصلي مع الجماعة بعض الأحيان فهذا لك الصبر مع النصيحة. وهكذا شربه الخمر منكر عظيم، فلك الصبر لعل الله يهديه، لأنه مسلم، شرب الخمر لا يخرجه عن الإسلام يكون عاصي قد أتى كبيرة عظيمة، وإن طلبت الفراق منه فلك العذر، لأن تهاونه بالصلاة في الجماعة وتعاطيه المسكر عيب كبير، فلك أن تخرجي إلى أهلك، وتطلبي الفراق من جهة المحكمة. أما إذا ترك الصلاة فتركها كفر، ليس لك البقاء معه، بل يجب أن تفارقيه، وأن تذهبي إلى أهلك، وأن تسعي في الفراق من طريق المحكمة، نسأل الله لنا وله الهداية. المقدم: اللهم آمين، أثابكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17239/حكم-الزوج-المتهاون-بالصلاة-والشارب-للمسكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78201.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":18222,"question":"تقول السائلة: هل تارك الصلاة هو الذي يصلي الجمعة فقط؟ أو يصلي بعض المرات، ولكن لا يجحد وجوب الصلاة، ولكنه يتركها تكاسلًا؟","title":"حكم تارك الصلاة تكاسلًا","answer":"الجواب: الصواب أنه يكفر بذلك، أما إذا جحد وجوبها كفر عند جميع أهل العلم، أما إذا تركها تكاسلًا الجمعة، أو غير الجمعة من الفرائض يكفر بذلك كفرًا أكبر على الصحيح من قولي العلماء؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ولأنها عمود الإسلام، هي أعظم الفرائض بعد الشهادتين، ولهذا يقول ﷺ: رأس الأمر الإسلام، وعموده الصلاة نسأل الله السلامة والعافية. المقدم: اللهم آمين حفظكم الله وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17273/حكم-تارك-الصلاة-تكاسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78214.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":18226,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع خليفة محمود جاد مصري الجنسية، ويعمل في بيشة، أخونا يقول: إنني لم أبدأ الصلاة إلا بعد سن العشرين، فماذا علي في المدة السابقة؟ جزاكم الله خيرًا.","title":"حكم من ترك الصلاة لسنوات ثم تاب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فليس عليك -يا أخي- إلا التوبة إلى الله  والندم على ما فعلت من الترك، والله  يقول: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، وترك الصلاة كفر، وإنما علاجه بالتوبة، فإذا تاب الرجل من ذلك أو المرأة من ذلك كفى ولا قضاء؛ لقول الله : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] وقوله ﷺ: الإسلام يهدم ما كان قبله، والتوبة تجب ما كان قبلها. فاحمد الله -يا أخي- على الهداية، واسأله الثبات، واندم على ما مضى من تقصيرك، والتزم التوبة النصوح، واستكثر من الخير والعمل الصالح، وأبشر بالخير والعاقبة الحميدة. نسأل الله لنا ولك الثبات على الحق. نعم.","link":"https://binbaz.org.sa/fatwas/17269/حكم-من-ترك-الصلاة-لسنوات-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_857/nour_85701.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":18284,"question":"ما حكم العيش مع القريب الذي لا يؤدي الصلاة إلا بشكل متقطع، علمًا بأني أنصحه دائمًا بعدم ترك الصلاة والمحافظة عليها، ولكن لا يستجيب لي أحيانًا؟","title":"حكم السكن مع القريب الذي لا يصلي أحيانًا","answer":"الجواب: هذا فيه تفصيل: إذا كان الذي يعيش مع تارك الصلاة مطلقًا أو في بعض الأحيان، إذا كان الذي يعيش معه له القوة عليه، وله القدرة عليه، بالنصيحة والتوجيه ولا يخشى من شره، فلا مانع من إقامته معه، والاستمرار في نصيحته، وتوجيهه إلى الخير، والأخذ على يده ونحو ذلك من أسباب هدايته وصلاحه، مع بيان كراهته لعمله، وغضبه على ذلك، وإظهاره له الكراهة لعمله، والهجرة لما هو عليه من الباطل، بأن يتغير عليهم وتكون معاملته مثل معاملة من يكره عمله ومن لا يرضى عمله، ومن يرجو هدايته، فإذا كانت الإقامة .... مصلحة شرعية ولدعوته كالوالد مع ولده، والأم مع ولدها، والأخ الكبير مع أخيه الصغير، لعله يهتدي، فهذا يرجى فيه الخير. أما إذا كان المقيم يخشى من هذا التارك للصلاة؛ لأنه أكبر منه، أو لأنه ... عليه، أو لأنه زين له الباطل، ويدعوه إلى عمله السيئ، فينبغي له الخروج من ذلك وعدم الإقامة معه لئلا يضره ولئلا يجره إلى باطله. ثم أمر آخر، وهو أن الإنسان الذي يقيم عند تارك الصلاة أو عند من يتعاطى شيئًا من الكفر له حالان: حالة يكون يستطيع الخروج لأي مكان وعنده ...","link":"https://binbaz.org.sa/fatwas/17333/حكم-السكن-مع-القريب-الذي-لا-يصلي-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_911/nour_91103.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":18374,"question":"رسالة بعث بها أخونا: عبد الله حمود يسأل ويقول: إذا كان الشخص يؤمن بالله، وملائكته، وكتبه ورسله، واليوم الآخر، وبالقدر خيره وشره، ومات وهو تارك للصلاة كسلًا، هل هو مخلد في النار أم لا؟ نرجو الإجابة جزاكم الله خيرًا.","title":"حكم ترك الصلاة تكاسلًا","answer":"الجواب: سبق في السؤال السابق: أن من ترك الصلاة تهاونًا، فقد اختلف فيه العلماء، هل هو كافر كفرًا أكبر أم كفرًا أصغر؟ وسبق أنه كافر كفرًا أكبر في الصحيح من قولي العلماء، وإذا كان كفره أكبر؛ فهو إذا ما كان ذلك يكون حكمه حكم الكفار مخلدًا في النار كسائر الكفرة. وقد قال الله  في كتابه العظيم لما سئل عن النار عن أسباب دخولهم النار، أجابوا بأنهم لم يكونوا من المصلين، قال تعالى: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42-43]، ما قالوا: كنا من الجاحدين، قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:43]، فدل على أن عدم الصلاة من أسباب دخولهم النار نعوذ بالله من ذلك. فيجب على المؤمن أن يحذر هذا العمل السيئ، وأن يصلي كما أمره الله، وأن يحذر هذا التساهل الذي يحصل لمن اعتقد بزعم أنه كفر أصغر حتى ولو كان كفر أصغر، الواجب الحذر من جميع ما حرم الله  فكيف لو قد: سمي كفرًا؟ فإن الواجب يكون الحذر منه أكثر من غيره، وإذا كان تركها كفرًا أكبر فالأمر أعظم وأعظم، وهذا هو الصواب: أنه كفر أكبر؛ لما تقدم في قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، رواه مسلم في الصحيح. وقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، خرجه الإمام أحمد، وأهل السنن بإسناد صحيح عن بريدة  وهناك أدلة أخرى دالة على ذلك، وفي هذه الآية الكريمة، وهي قوله تعالى: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ ۝ وَلَمْ نَكُ نُطْعِمُ الْمِسْكِينَ ۝ وَكُنَّا نَخُوضُ مَعَ الْخَائِضِينَ ۝ وَكُنَّا نُكَذِّبُ بِيَوْمِ الدِّينِ ۝ حَتَّى أَتَانَا الْيَقِينُ [المدثر:42-47]، فجعل تارك الصلاة مع هؤلاء، فدل ذلك على أنه كفر أكبر؛ لأن الشك في الدين والخوض فيه على سبيل الشك والريب، وهكذا التكذيب بيوم الدين -بيوم القيامة- كله كفر أكبر نعوذ بالله. فيجب على المؤمن أن يحذر ترك الصلاة مطلقًا، أما إن جحد وجوبها، فالأمر أعظم فإنه كافر بالإجماع نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17441/حكم-ترك-الصلاة-تكاسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_862/nour_86202.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":18384,"question":"تقول السائلة: هل صلاة الصبح فرض أم نفل؟ ومتى وقتها؟ أرجو الإيضاح في ذلك جزاكم الله خيرًا.","title":"حكم صلاة الفجر ووقتها","answer":"الجواب: صلاة الفجر أحد الفرائض الخمس، إحدى الفرائض الخمس بإجماع المسلمين، يجب على كل مكلف وعلى كل مكلفة أداء الصلوات الخمس: الفجر ثنتين، والظهر أربع ركعات، والعصر أربع ركعات، والمغرب ثلاث ركعات، والعشاء أربع ركعات، يجب على جميع المكلفين من الرجال والنساء المسلمين، يجب عليهم أن يصلوا هذه الصلوات الخمس بطمأنينة وإخلاص لله. يصلي الفجر ركعتين، يقرأ الفاتحة وما تيسر معها في الأولى ثم يركع ويطمئن، ثم يرفع ويعتدل ويطمئن، ثم يسجد سجدتين، ويطمئن فيهما، ويقول فيها: سبحان ربي الأعلى، ويقول في الركوع: سبحان ربي العظيم، ويجلس بين السجدتين ويطمئن ويقول: رب اغفر لي.. رب اغفر لي، ويطمئن ويعتدل بعد الركوع وهو واقف مطمئن بعد الركوع قبل أن يسجد، ثم الركعة الثانية كذلك في الفجر، ثم يجلس ويقرأ التحيات المعروفة، ثم بعد قراءة التحيات والصلاة على النبي ﷺ، يتعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ، ويدعو بما تيسر من الدعاء، ومن ذلك اللهم أعني على ذكرك، وشكرك وحسن عبادتك، ثم يسلم تسليمتين: السلام عليكم ورحمة الله عن يمينه، السلام عليكم ورحمة الله عن يساره. وفي الظهر أربع ركعات، يصلي ركعتين بالفاتحة، وما تيسر معها، ثم يجلس للتشهد الأول يقرأ التحيات إلى الشهادتين، وإذا صلى على النبي ﷺ يكون أفضل، ثم يقوم يأتي بالركعة الثالثة والرابعة. والعصر كذلك، والعشاء كذلك أربع ركعات، أما المغرب فثلاث، يصلي ركعتين ويجلس في التشهد الأول، ثم يقوم ويأتي بركعة ثالثة، ويجلس للتشهد الأخير بعد الصلاة على النبي والدعاء يسلم المغرب هكذا. إلا المسافر فإنه يصلي الظهر ركعتين، والعصر ركعتين، والعشاء ركعتين قصرًا، إذا كان مسافرًا، فإنه يصلي الظهر ركعتين يقصرها، والعصر ركعتين، والعشاء ركعتين، أما الفجر فعلى حالها في السفر والحضر، وهكذا المغرب على حالها في السفر والحضر. والواجب على كل مكلف أن يتعلم ويتفقه في الدين، هذا هو الواجب؛ لأنهم خلقوا لعبادة الله، الله يقول سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ[الذاريات:56] والصلوات من هذه العبادة الذي أنت مخلوق لها، فيجب أن تتعلم ويجب على المرأة أن تتعلم، وتسأل أهل العلم حتى تفقه دين الله، وحتى تكون على بينة، وهكذا الرجل يقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين ويقول ﷺ: من دل على خير فله مثل أجر فاعله ويقول عليه الصلاة والسلام: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة. وأنا أنصح بسماع إذاعة القرآن فيها علم، إذاعة القرآن فيها نور على الدرب للعلماء، فيها محاضرات وندوات علمية مفيدة، أنصح جميع إخواني وأخواتي في الله أن يستمعوا لإذاعة القرآن، ويستفيدوا منها، وأن يسألوا أهل العلم عما أشكل عليهم من طريق الهاتف .. التلفون، أو من طريق المكاتبة، لا بد من التفقه في الدين، لا بد من السؤال، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا على هذا التوجيه المبارك سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17464/حكم-صلاة-الفجر-ووقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78408.mp3","categories":["حكم الصلاة وأهميتها","وقت الصلاة"]},{"id":18396,"question":"بسبب دراسة الطب تركت عائلتي -والدي- وأنا الآن أعيش في بيت أخي، وهذا الأخ هداه الله لا يحرص على أداء الصلاة، ولا أقول: إنه لا يصلي، فإنني أراه أحيانًا يؤديها، ولكن الملاحظ عليه بصفة عامة هو عدم الاهتمام بهذا الركن العظيم، علمًا بأنني لا أستطيع نصحه بسبب فارق السن ولأسباب أخرى.فهل يجوز لي أن أستمر في العيش معه لمواصلة الدراسة والتي بقي على تخرجي منها حوالي ثلاث سنوات إن شاء الله؟ أم علي أن أبحث عن سكن آخر كسكن الجامعة -مثلاً-؟أم علي أن أترك الدراسة وأعود إلى أهلي؟ أرجو إرشادي وإخراجي من حيرتي، وجزاكم الله خيرًا.","title":"كيفية التعامل مع الأخ الكبير التارك للصلاة","answer":"الجواب: إن الواجب عليك أن تنصحيه وإن كنت أصغر منه، فإن الله جل وعلا يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، هذا واجب الجميع، المؤمنين والمؤمنات، وليس في هذا فرق بين الكبير والصغير، فعليك أن تنصحي أخاك وأن تخوفيه من الله ؛ لأن الصلاة عمود الإسلام ومن تركها كفر، كما قال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، خرجه الإمام أحمد وأهل السنن بإسناد صحيح، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، خرجه الإمام مسلم في صحيحه، وقال أيضاً عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله، خرجه الإمام أحمد وغيره بإسناد صحيح عن معاذ . والأحاديث في هذا كثيرة، والقرآن الكريم فيه من ذلك الآيات الكثيرة، كقوله سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، قوله : وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43]، وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ [البينة:5]، فعليك أن تنصحيه وأن تبيني له إنكارك عليه هذا العمل لعله يهتدي بأسبابك فيكن لك مثل أجوره. والرجل ينصح المرأة والمرأة تنصح الرجل وإن اختلفا في السن، ولاسيما هو أخوك فله حق عليك من جهة واجب الدين ومن جهة واجب الرحم، فإن استقام فالحمد لله، وإلا فنصيحتي لك أن لا تبقي عنده لئلا يضرك، ولئلا تبتلي بالتأسي به فيقسو قلبك، فنصيحتي لك أن تنتقلي إلى السكن الجامعي إذا تيسر ذلك وإلا فترك الدراسة، ولا تبقي عند رجل يتهاون بالصلاة ولا يرفع بها رأسًا، فإن هذا يضرك في دينك وربما يسبب لك شرًا عظيمًا وعاقبة وخيمة، نسأل الله لك التوفيق وحسن العاقبة ولأخيك الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17491/كيفية-التعامل-مع-الاخ-الكبير-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86306.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":18425,"question":"تقول: إن لديها أخ لا يصلي ولا يصوم وعمره خمس وعشرون سنة، وهو من يوم أن بلغ وهو لا يعرف الصلاة ولا الصوم، فهل يجوز أن نأكل معه؟وهل يجوز أن أخطب له زوجة تصلي؛ عسى أن تعينه على العودة إلى دينه؟ أم نخطب له زوجة مثله لا تصلي؟ وهل وهو خال لبناتي يجوز لهن أن يكشفن عليه؟ وجهونا جزاكم الله خيرًا.","title":"حكم إعانة تارك الصلاة على الزواج","answer":"الجواب: عليكم أن تنصحوه؛ لأن هذا منكر عظيم، فعليكم أن تنصحوه لعل الله يهديه بأسبابكم؛ لأن ترك الصلاة كفر، كفر أكبر لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، فالواجب أن ينصح وأن يوجه إلى الخير، فإن لم يستجب يرفع أمره إلى المحكمة إلى ولاة الأمور حتى يستتاب فإن تاب وإلا قتل. أما الكشف له فلا بأس؛ لأنه محرم ولو كان كافرًا، محرم لأخواته وبنات أخيه وبنات أخته هو محرم، لكن يجب أن يهجر وأن يشدد عليه، إذا لم ينفع فيه الكلام الطيب يجب أن يهجر ويبين له الكراهة لعمله والمقت لعمله وأنه أتى منكرًا عظيمًا لعل الله يهديه بأسباب ذلك. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا. بالنسبة للخطبة له، يريدون أن يزوجوه فيزوجوه مصلية أو تاركة صلاة؟ الشيخ: لا ما يجوز يتزوج مصلية؛ لأنه ما يحل لها تتزوجه، المصلية لا يحل لها أن تتزوج بإنسان لا يصلي، بل عليه أن يتوب إلى الله ، وينبغي أن يترك حتى لعل الله يمن عليه بالتوبة، ولا يغرر به أحد؛ لأن التي لا تصلي قد يزيدها شرًا، إذا كانت لا تصلي تحل له التي ما تصلي مثله كافرة مثله، تحل له، لكن كونه يُساعد في ذلك قد يضرها هي أيضًا، قد يزيدها شرًّا إلى شرها. نعم. المقدم: إذًا يتأنى في موضوع الزواج ... الشيخ: التأني أولى، التأني أولى حتى لعل الله يهديه، لعله يرجع إلى الصواب. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17504/حكم-اعانة-تارك-الصلاة-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73307.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":18503,"question":"إذا كان هناك شخص - يقول السائل- من أحد أقاربنا لا يصلي، فهل يجوز لنا أن نأكل من ماله؟ وهل نستجيب لدعوته إذا دعانا في المناسبات؟","title":"حكم الأكل من مال الذي لا يصلي","answer":"الجواب: الذي لا يصلي يستحق الهجر، ينبغي أن يهجر، ينصح ويوجه إلى الخير ويؤمر بطاعة الله، فإذا أصر ولم يصل يهجر يستحق الهجر؛ لأنه ترك أمرًا عظيمًا، ترك واجبًا عظيمًا؛ فإن الصلاة عمود الإسلام، والواجب أن يصلي في المسجد مع الناس، فإذا تساهل بذلك وجب هجره، وإن تركها كفر نسأل الله العافية يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ويقول عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر. وإن صلاها في البيت عصى، كالمعصية؛ لأن الواجب أن يصليها مع الناس في المسجد إلا المعذور كالمريض؛ لقول النبي ﷺ: من سمع النداء فلم يأتِ فلا صلاة له إلا من عذر، قيل لابن عباس: ما هو العذر؟ قال: خوف أو مرض»، وفي الصحيح: «أن رجل أعمى قال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب هذا أعمى ليس له قائد يقوده ومع هذا قال له: أجب، يعني: التمس من يقودك وأجب إلى الصلاة في المسجد، فحضورها في المسجد واجب، وترك ذلك معصية، أما تركها بالكلية، كونه ما يصلي هذا كفر أكبر أعوذ بالله على الصحيح من أقوال العلماء وإن لم يجحد وجوبها، أما من جحد وجوبها كفر عند الجميع نسأل الله العافية. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17603/حكم-الاكل-من-مال-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78608.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":18667,"question":"يسألن عن شخص كان يصلي، ولكنه كان يترك الصلاة أحيانًا، ويتابع أحيانًا أخرى، لكنه الآن -ولله الحمد والشكر- مداوم على الصلاة وبانتظام، هل عليه أن يقضي ما فاته من تلك الصلوات، أم التوبة تكفيه؟جزاكم الله خيرًا.","title":"كيف يقضي مَن كان يترك الصلاة أحيانًا؟","answer":"الجواب: التوبة تكفيه، والحمد لله، وليس عليه قضاء؛ لقول الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] وقول النبي ﷺ: التوبة تجب ما قبلها وقوله -عليه الصلاة والسلام-: التائب من الذنب كمن لا ذنب له. ترك الصلاة كفر، والتوبة تجب ذلك، وتمحو ذلك، والحمد لله، إذا تاب توبة صادقة، بالندم على الماضي، والمحافظة على الصلاة، والعزم الصادق ألا يعود، فالله يعفو عنه...، ليس عليه قضاء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17778/كيف-يقضي-من-كان-يترك-الصلاة-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73507.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":18714,"question":"أيضًا بقي لها سؤال واحد شيخ عبد العزيز، تشكو فيه من شباب تعرفهم، تقول: إنهم عصاة، ولا يصلون، وتذكر أيضًا بعض سيئاتهم، وهم محارمها، ويسكنون معها في نفس المنزل، وترجو منكم توجيهها كيف تتصرف؟","title":"كيف تعامل المرأة محارمها التاركين للصلاة؟","answer":"الجواب: الواجب نصيحتهم، وتحذيرهم مما حرم الله، وإخبارهم بأن الصلاة عمود الإسلام، وأن تركها كفر أكبر في أصح قولي العلماء، وإن لم يجحدوا وجوبها، مع وجوب التحرز منهم، والحذر من شرهم؛ لأن من عصى الله، وترك الصلاة لا يؤمن شره. فنوصيك -أيتها الأخت في الله- أن تحذري شرهم، وإذا تيسر لك فراقهم، والانتقال عنهم إلى بيت آخر، إلى أمك، أو أخ صالح، أو عم صالح، أو خال صالح، فهو أسلم لك من هؤلاء، فإن كنت مضطرة إلى البقاء معهم، فاحذريهم، واحذري شرهم، مع دوام النصيحة والتوجيه إلى الخير، وتخويفهم من الله  واستعيني على ذلك أيضًا بأهل الخير من أقاربك حتى ينصحوهم، نسأل الله لنا ولهم الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17780/كيف-تعامل-المراة-محارمها-التاركين-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92002.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة","قضايا المرأة"]},{"id":18738,"question":"تقول أختنا: إنها تعرف إحدى النساء، واكتشفت أنها لا تصلي إلا في رمضان، وتسأل: هل تستمر معها كصديقة لها، أو تقاطعها؟","title":"حكم صحبة تارك الصلاة","answer":"الجواب: الواجب نصيحتها، وتعليمها ما ينفعها، وإفهامها أن الصلاة فرض دائمًا، في رمضان وفي غيره، وأنها عمود الإسلام، وأنها واجبة على المرأة المكلفة أن تصليها، وأن تحافظ عليها كالرجل، في رمضان أو في غيره، وأن تركها للصلاة في غير رمضان كفر أكبر -نعوذ بالله- كما قال النبي -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، وقال -عليه الصلاة والسلام-: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله. فالصلاة عمود الإسلام، وأعظم أركانه بعد الشهادتين، فالتي لا تصلي كالرجل الذي لا يصلي سواءً بسواء، كلاهما كافر، حتى يتوبا إلى الله، ويرجعا من عملهما السيئ، فإن هداها الله، واستجابت لك؛ وتابت إلى الله، فلا مانع من اتخاذها صديقة، والبقاء على صحبتها. أما إن أصرت على ترك الصلاة فهي كافرة؛ ويجب عليك أن تعاديها في الله، وأن تقاطعيها، وأن لا تقربيها بالكلية، لا تجيبي دعوتها، ولا تدعيها إلى زيارتك، ولو زارتك لا تقابليها، ولا تسلمي عليها، حتى ترجع عما هي عليه من الباطل، وحتى تتوب إلى الله ؛ لأن عملها عظيم، عظيم النكارة، عظيم الشر، عملها كفر -نسأل الله العافية والسلامة- والمسلم واجبه النصيحة لإخوانه في الله، وأخواته في الله، فإذا كانت لا تقبل النصيحة، ولا تنتفع بالنصيحة؛ وجبت المقاطعة، نسأل الله لنا ولها الهداية، ونسأل الله لك التوفيق في نصيحتها. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17881/حكم-صحبة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87508.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":18770,"question":"السائلة تقول في هذا السؤال -سماحة الشيخ-: ما حكم الشرع في نظركم في المرأة التي تصلي وزوجها لا يصلي، وهي متمسكة بالصلاة مع العلم بأنها بذلت مجهودًا كبيرًا في إقناعه ليصلي، ولكنه لا يركع ولا ركعة واحدة، لديها أطفال منه، وهي تؤمل في ذلك خير، فماذا توجهونها؟ مأجورين.","title":"حكم بقاء المرأة مع زوج تارك للصلاة","answer":"الجواب: الذي لا يصلي يعتبر كافرًا، نسأل الله العافية، هذا هو أصح قولي العلماء في الموضوع؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة أخرجه مسلم في الصحيح؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر فالصلاة عمود الإسلام، فالذي لا يصلي لا خير فيه، ولا يعتبر مسلمًا، وعليها أن تفارقه، ولا تمكنه من نفسها، عليها أن تفارقه، وتمنعه من نفسها، وتذهب إلى أهلها، حتى يتوب إلى الله، وحتى يسلم، ويدع عمله السيئ، هذا هو الصواب، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17898/حكم-بقاء-المراة-مع-زوج-تارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79104.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":18819,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: أخوكم في الله (م. م. ع) أخونا يسأل ويقول: إذا كان للإنسان المسلم أخ أو أخت تاركة للصلاة بالكلية، وقدم ما يلزم من النصح، ولكن دون جدوى، فهل يجوز له أن يلجأ إلى أسلوب المقاطعة؟ وما هو حدود معاملة تارك الصلاة لو كان ذا قرابة في ديننا الحنيف؟أفيدوني، جزاكم الله خيرًا.","title":"كيفية التعامل مع الأقارب التاركين للصلاة","answer":"الجواب: إذا ترك الأخ أو الأخت أو غيرهما من الأقارب الصلاة، فالواجب النصيحة والتوجيه والصبر على ذلك؛ فإن أجاب من ترك الصلاة وهداه الله وتاب، فالحمد لله، وإلا وجبت مقاطعته وهجره، فلا تستجاب دعوته من وليمة ولا غيرها، ولا يدعى لوليمة، ولا يسلم عليه، ولا يرد عليه السلام، حتى يتوب إلى الله؛ لأن جريمته عظيمة، وهي ردة عن الإسلام في أصح قولي العلماء. ترك الصلاة، والتعمد لذلك ردة عن الإسلام؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر ولأحاديث أخرى جاءت في المعنى، والله يقول سبحانه عن أهل النار: مَا سَلَكَكُمْ فِي سَقَرَ  ۝  قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42-43]، فبدؤوا أعمال الخبث التي دخلوا بها النار بدؤوها بترك الصلاة، نسأل الله العافية. فالواجب على المؤمن مع أقربائه إذا تركوا الصلاة أن ينصحهم، وأن يوجههم إلى الخير، وأن يوجه أيضًا بعض إخوانه الطيبين إلى أن ينصحوهم ويوجهوهم؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. فالتعاون على البر والتقوى من أهم المهمات، فإن هداهم الله سبحانه وتابوا، فالحمد لله، وإلا وجبت مقاطعتهم وهجرتهم حتى يستقيموا ويتوبوا، هذا هو الواجب على المسلمين إلا الوالدين، فالوالدان لهما شأن آخر؛ لأن الله قال سبحانه في حق الوالدين الكافرين، قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا[لقمان:15] فالوالدن لهما حق عظيم، ولو كانا كافرين، يصبر عليهما، ويحسن إليهما، ويرفق بهما، ويدعوهما إلى الله، لعل الله يهديهما بأسبابه، ولا يعجل، ولو استمرا في الكفر عليه أن ينصحهما، وأن يوجههما إلى الخير، ويستعين على ذلك بمن يرى من أقاربه وإخوانه وأحبابه لعل الله يهديهما بأسبابه. فلو استمرا على الكفر لم يقطع النصيحة، ولم يقطع الإحسان، بل يستمر في نصيحته وإحسانه حتى يسلما، أو يموتا، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17952/كيفية-التعامل-مع-الاقارب-التاركين-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92106.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":18829,"question":"السائل (ن. المنصور الفرعة) يقول: امرأة كبيرة في السن تصلي فروضًا وتترك أخرى، وإذا صلت يكون عليها نجاسة، وتفوت بعض الأشياء، هل يلحقها شيء في ذلك؟","title":"حكم من تخل ببعض الفرائض وبالطهارة لكبر سنها","answer":"الجواب: إذا كان عقلها قد اختل ما عليها شيء ما هي مكلفة، إذا كان هذا بسبب عقلها اختل ما عليها شيء، أما إذا كان لا ما هو بعقلها معها لأنها قد تنسى شيئًا يبين لها إذا كانت عاقلة تفهم، أما إذا كان قد اختل عقلها لكبر سن أو لمرض، أو ما أشبه ذلك، فالله -جل وعلا- رفع عنها القلم، يقول النبي ﷺ: رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن الصغير حتى يبلغ، وعن المجنون حتى يفيق ومن كان عقله مختل مثل المجنون سواء، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ. لعل لكم سماحة الشيخ كلمة توجيهية للأبناء والبنات في العناية بوالديهم عند كبر سنهم وعجزهم؛ لأن الملاحظ أن بعض الأولاد والبنات يهملون والديهم في كبر السن يا شيخ. الشيخ: الواجب على البنين والبنات تقوى الله في هذا، وأن يحسنوا إلى والديهم، وأن يصبروا، قد صبر الوالدان عليهم في صغرهم، وربياهم وأحسنا إليهم، فالواجب على الأولاد أن يتقوا الله في الوالدين، وأن يحسنوا إليهما، وأن يصبروا على ما قد يقع من التعب لمرضهما، أو اختلال عقلهما لا بد من الصبر، الله يقول -جل وعلا-: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا[الإسراء:23-24]، ويقول -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ[لقمان:14]. فالواجب الصبر على الوالدين، والإحسان إليهما، وتحمل ما قد يقع من الأذى، وفي الحديث: رضا الله في رضا الوالدين، وسخط الله في سخط الوالدين ويقول النبي ﷺ: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله، قال: الإشراك بالله، وعقوق الوالدين جعل عقوق الوالدين قرين الشرك، وفي الحديث الصحيح يقول ﷺ: من الكبائر شتم الرجل والديه قيل: يا رسول الله، وهل يسب الرجل والديه؟ قال: نعم يسب أبا الرجل فيسب أباه، ويسب أمه فيسب أمه فإذا كان سبه للناس سبًا لوالديه لأنهم يسبون والديه إذا سب والديهم فكيف إذا سبهما، وأساء إليهما الأمر أعظم، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17999/حكم-من-تخل-ببعض-الفراىض-وبالطهارة-لكبر-سنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79205.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":18832,"question":"يقول هذا السائل من السودان سماحة الشيخ: في الحديث: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له البعض من الناس يذهب لقبر أحد الأشخاص كأن يكون شيخًا، ويطلب منه كذا وكذا، هل يجوز ذلك؟ وما حكم من يفعل ذلك في الشرع؟ وكيف ندعو للميت من منطلق هذا الحديث ابن صالح يدعو له كيف ندعو بعد الممات؟جزاكم الله خيرًا.","title":"حكم دعاء الموتى من دون الله","answer":"الجواب: تقول: اللهم اغفر لأبي، اللهم اغفر له، اللهم ارحمه، اللهم نجه من النار ، ونحو ذلك، هذا الدعاء له.  أما دعاء الميت، والتوجه إلى الميت تقول له: يا فلان انصرني، أو أنا في حسبك، أو أغثني هذا الشرك الأكبر، أو اشفع لي، أو أنا في جوارك، أو ما أشبه ذلك هذا الشرك الأكبر، هذا فعل المشركين مع اللات والعزى، ومع أصنامهم، وهذا فعل المشركين مع الشيخ عبد القادر الجيلاني، ومع البدوي، ومع الحسين، ما يجوز هذا. لا يقل: يا سيدي فلان انصرني، أو أنا في حسبك، أو أنا في جوارك، أو اشفع لي، هذا ما يقال للميت يقال للحي، يقول للحي: اشفع لي، ادع الله لي؛ ما يخالف الحي، تقول: ادع الله ليغفر لي، ادع الله أن يرحمني، هذا لا بأس. أما الميت تقول له: يا فلان، يا شيخ عبد القادر، أو يا حسين، أو يا ست زينب، أو يا فلان -وهو ميت- ادع الله لي، هذا ما يجوز؛ لأنه غير قادر، لا يستطيع شيء، أو اشفع لي؛ هذا توسل بميت لا يقدر، كالذي يقول للصنم: انصرني، أو اشفع لي، جماد لا قدرة له على شيء، فسؤال الأموات، والاستغاثة بالأموات، والتشفع بالأموات؛ هذا هو عمل المشركين وهذا هو المنكر، ولا يجوز، بل هو من الشرك الأكبر، نسأل الله العافية، نعم. ومثله الغائبون يا ملائكة الله، يا جبريل، يا ميكائيل، أو يا جن الفلانيين، يا جن الظهران، يا جن الحسا، يا جن أمريكا، يا جن مصر، أو يا جني الفلاني، كل هذا من الشرك الأكبر، وقد ذم الله بعض المشركين في هذا، قال عنهم: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا[الجن:6] يعني: زادوهم شرًا وبلاء، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17982/حكم-دعاء-الموتى-من-دون-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79202.mp3","categories":["حكم الصلاة وأهميتها","شروح الحديث","نواقض الإسلام"]},{"id":18978,"question":"له سؤال لعله يوضح جانبًا آخر من جوانب حياته، فيسأل سماحة الشيخ ويقول: في فترة شبابي تمر علينا بعض الأيام فلا نصلي فيها الفروض، الأيام كثيرة سامحنا الله وإياكم، ولقد قرأت في إحدى الصحف بأنه لا بد من قضائها رغم فوات المدة عليها؛ وذلك بعد الصلوات المفروضة، أنا الآن الحمد لله أصلي جميع الفروض، وفي أوقاتها، دلوني على الجواب الصحيح.جزاكم الله خيرًا.","title":"حكم قضاء الصلاة لمن تاب من تركها","answer":"الجواب: الواجب التوبة من ذلك، وليس عليها قضاء، هذا هو الصحيح من قولي العلماء؛ لأن ترك الصلاة كفر، والكفر لا يزول إلا بالتوبة، فإذا ترك الإنسان الصلاة، ثم تاب، فإنه لا قضاء عليه، هذا هو المختار، وهو الصواب، وليس عليك شيء -إن شاء الله- إلا التوبة، فعليك التوبة الصادقة، والندم على ما مضى منك، والعزم ألا تعود في ذلك، والاستكثار من الحسنات، والأعمال الصالحات، كما قال الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]. والتوبة تجب ما كان قبلهاكما قاله النبي -عليه الصلاة والسلام- نسأل الله أن يمنحنا وإياك التوبة الصادقة، وأن يعيذنا وإياك والمسلمين من نزغات الشيطان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18126/حكم-قضاء-الصلاة-لمن-تاب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92502.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":18981,"question":"رسالة وصلت إلى البرنامج من السودان، وباعثتها إحدى الأخوات المستمعات، تقول (س. م. أ) أختنا لها ثلاثة أسئلة:في سؤالها الأول تقول: لي جدة كبيرة السن لا تستطيع الوضوء بحجة الرطوبة في رجليها، وتترك الصلاة بحجة عدم الوضوء، رغم أننا بينا لها التيمم وكيفيته؟أفيدونا جزاكم الله خيرًا.","title":"حكم ترك الصلاة للكبير في السن والمريض","answer":"الجواب: الواجب على المريض وعلى كبير السن مثل الواجب على غيرهما مع الاستطاعة، فعليهما الاستنجاء أو الاستجمار، عما يخرج من السبيلين، وعليهما الوضوء الشرعي، وعليهما الغسل إذا حصل جنابة، كل هذا معروف في الشرع المطهر، ومن عجز عن الوضوء لمرض يمنعه من ذلك، أو عجز يمنعه من ذلك، وتيسر من يوضئه وجب ذلك، وإن تعسر هذا وهذا تيمم بأن يقرب له التراب في إناء، أو في منديل أو بأشياء يضرب التراب بيديه، ويمسح بهما وجهه وكفيه، بنية الغسل من الجنابة، أو بنية الحدث الأصغر. أما ما يتعلق بالسبيلين فيكفي أن يمسحهما بالمناديل أو باللبن أو نحو ذلك، حتى ينقيهما، ولا يلزم الماء إن استنجى بالماء فالحمد لله، وإن لم يستنج بالماء كفاه أن يستجمر بالحجارة باللبن بالخرق حتى ينقي المحل، بمسحات ثلاث أو أكثر، لا بد من ثلاث مسحات، أو أكثر حتى ينقى المحل من الأذى، من الغائط والبول، وإذا فعل ذلك يتوضأ وضوء الصلاة بعد ذلك يتمضمض ويستنشق إلى آخره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18130/حكم-ترك-الصلاة-للكبير-في-السن-والمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92504.mp3","categories":["صلاة المريض","حكم الصلاة وأهميتها"]},{"id":19079,"question":"ننتقل بعد هذا إلى سؤال وصل إلى البرنامج من الأردن من أحد الإخوة المستمعين من هناك، يسأل سؤال عن امرأة تصلي، وتصوم، وصاحبة طاعة؛ إلا أنها مع رجل لا يصلي، كيف تتصرف مثل هذه المرأة؟ جزاكم الله خيرًا.","title":"حكم بقاء المرأة مع زوج لا يصلي","answer":"الجواب: إذا كان الزوج لا يصلي فالواجب عليها تركه، والذهاب إلى أهلها؛ لأن ترك الصلاة جريمة عظيمة، ومنكر عظيم، بل كفر أكبر في أصح قولي العلماء، وإن لم يجحد وجوب الصلاة، أما إن جحد وجوبها؛ فإنه يكون كافرًا بإجماع المسلمين، ليس فيه نزاع بين أهل العلم. وإنما النزاع فيما إذا تركها مع إقراره بأنها واجبة عليه، ولكن حمله الكسل، والتشاغل بالأمور الدنيا؛ فهذا هو محل النزاع. والصواب أنه يكفر بذلك؛ لقول النبي ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه رحمه الله، عن جابر بن عبد الله الأنصاري، وخرج أحمد رحمه الله، وأهل السنن بإسناد صحيح عن بريدة  عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. في أحاديث أخرى تدل على المعنى. فالواجب على كل مسلم أن يتقي الله، وأن يحافظ على الصلاة في وقتها، وأن يؤديها في الجماعة أيضًا كما شرع الله، وأن يحذر التهاون بها. ومتى تركها الإنسان فإن الزوجة يحرم عليها البقاء معه وهي مسلمة مصلية، لا تبقى معه، هذا هو الصواب، وهذا هو أرجح القولين، ومتى تاب تاب الله عليه، متى تاب وثبتت توبته أمكن الإصلاح بينه وبين زوجته. وهكذا كل من يتعاطى مكفرًا يخرجه من الإسلام يفرق بينه وبين زوجته المسلمة، حتى يعود إلى الإسلام، وحتى يتوب وبعد هذا ينظر في مراجعته لها، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18254/حكم-بقاء-المراة-مع-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79702.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":19231,"question":"المستمع سعيد بن عبد الحميد أحمد بعث يسأل ويقول: لي صديق تارك للصلاة، وقد قدمت له النصيحة ولم يستجب بل قابل ذلك بالقطيعة بيني وبينه، فما هو توجيهكم لي؟ جزاكم الله خيرًا.","title":"الواجب تجاه تارك الصلاة","answer":"الجواب: قد أحسنت فيما فعلت، وأديت الواجب في النصيحة، والواجب أن يهجر هو، فإذا قطعك فأنت تقطعه أيضًا؛ لأنه هو يستحق الهجر، قد هجر النبي ﷺ ثلاثة من الصحابة لما تأخروا عن غزوة تبوك بغير عذر، فالذي يتأخر عن الصلاة ولا يصلي من باب أولى؛ لأن ترك الصلاة كفر أكبر، فالواجب هجره إذا لم يقبل النصيحة، ورفع أمره إلى ولي الأمر إذا كان في بلاد تحكم بالإسلام رفع أمره إلى ولي الأمر حتى يعاقب بما يستحق، وحتى يستتاب، فإن تاب وإلا وجب قتله إذا ترك الصلاة؛ لأن الله يقول سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدل على أن الذي لا يؤدي الصلاة لا يخلى سبيله بل يرفع أمره إلى ولي الأمر، إلى المحكمة، إلى الهيئة هيئة الأمر بالمعروف والنهي عن المنكر؛ حتى تنظر في أمره، وأنت قد أديت ما عليك بنصيحته وتوجيهه إلى الخير. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18417/الواجب-تجاه-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73804.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":19259,"question":"رسالة من أحد الإخوة المستمعين آثر عدم ذكر اسمه، عرضنا له مجموعة من الأسئلة في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد يقول: إن بعض الأقارب لا يصلون، هل زيارتهم ومجاملتهم واجبة؛ علمًا أننا ننصحهم، ولكنهم يحاولون الهرب من الموضوع، ولا يتأثرون؟ وجهونا جزاكم الله خيرًا.","title":"ما كيفية معاملة مَن لا يصلي أو يفعل المنكر؟","answer":"الجواب: إذا كان قريبك، أو جارك؛ لا يصلي فالواجب نصيحته منك ومن إخوانك تنصحونه بالكلام الطيب، والتخويف من الله، وأن الصلاة عمود الإسلام، وأن تركها كفر بالله  أكبر، على الصحيح من أقوال العلماء، وإن لم يجحد وجوبها. فالصلاة عمود الإسلام، وفيها الخير العظيم، والأجر الكبير، فعليك أن تنصح قريبك أو جارك، وتجتهد في ذلك منك ومن إخوانك؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى[المائدة:2] فإذا كان معك بعض إخوانك تكون النصيحة أكثر وأجدى، فإن أبوا ولم يقبلوا استحقوا الهجر؛ يجب هجرهم عند جمع من أهل العلم. وقال جماعة: يستحب هجرهم، فبكل حال هجرهم مشروع إلا إذا رأيت أن الاتصال بهم بين وقت وآخر للدعوة أنفع فلا بأس للدعوة إلى الله والإرشاد والنصيحة لعلهم يهتدون. وهكذا من تعرفه من جيرانك يتساهل يظهر شرب الخمر، أو يعامل بالربا، أو تعرف منه منكرًا آخر قد أظهره وبيَّنه للناس، ولم يبال، ولم يستح؛ يجب نصحه وتوجيهه إلى الخير، وتخويفه من الله  منك ومن بعض إخوانك تعاونوا على البر والتقوى، إذا كانت النصيحة من اثنين أو ثلاثة يكون أنفع لعله يتأثر، وتكرارها عليه كذلك لعله يستجيب. فإن أصر ولم يبال استحق أن يهجر كما هجر النبي ﷺ ثلاثة من الصحابة: كعب بن مالك وصاحباه هجرهم النبي ﷺ خمسين ليلة؛ لأنهم تخلفوا عن غزوة تبوك بغير عذر شرعي، وقد أمرهم بالغزو عليه الصلاة والسلام استنفرهم. فإذا كان الصحابة إذا حصل منهم معصية يهجرون فغيرهم من باب أولى، في المعصية الظاهرة أما الذي بينه وبين ربه الله الذي يعلمها  المستورة، لكن المقصود المعصية الظاهرة كترك الصلاة، والتعامل بالربا، وشرب الخمر علانية وما أشبه ذلك يستحق الهجر على ذلك إلا أن يستجيب ويهتدي فالحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18453/ما-كيفية-معاملة-من-لا-يصلي-او-يفعل-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_800/nour_80004.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":19289,"question":"سماحة الشيخ عبد العزيز بن باز، السلام عليكم ورحمة الله وبركاته.. أما بعد:نرجو من سماحتكم أن تقولوا لنا رأيكم في مسألة احترنا فيها بسبب تعدد الآراء وهي: يقول الرسول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ويقول عليه الصلاة والسلام: بين الرجل وبين الشرك والكفر ترك الصلاة، فنرجو من سماحتكم أن توضحوا لنا معنى كلمة الكفر، ومتى يعد المرء كافرًا، وهل المقصود من الحديث أن تارك الصلاة يعتبر كافرًا إذا تركها تكاسلًا وخمولًا؟ أم إذا تركها جحودًا وإنكارًا؟ أم إذا تركها بأي حال من الأحوال؟ أفتونا في ذلك جزاكم الله خيرًا، أخوكم في الله حازم كمال ، الكويت .","title":"ما القول الراجح في حكم تارك الصلاة؟","answer":"الجواب: ترك الصلاة من أعظم الجرائم، ومن أعظم الكبائر؛ لأن الصلاة عمود الإسلام؛ ولأنها أعظم الأركان بعد الشهادتين، فإن تركها جاحدًا لوجوبها، أو مستهزئًا بها.. ساخرًا بها، ولو فعلها فهذا يكون كافرًا بإجماع المسلمين، ويكون مرتدًا عن الإسلام إذا تركها جاحدًا لوجوبها أو استهزأ بها وسخر منها، فإن هذا يعتبر كافرًا كفرًا أكبر ومرتدًا عن الإسلام بإجماع المسلمين. أما إذا تركها تكاسلًا وتساهلًا، وهو يعلم أنها واجبة وليس ساخرًا بها ولا مستهزئًا بها، ولكنه يحترمها ولكنه ربما تركها في بعض الأوقات تساهلًا وتكاسلًا كما يفعل بعض الناس في صلاة الفجر لا يصليها، وربما ترك صلاة العصر أو صلاة العشاء أو نحو ذلك، فهذا فيه خلاف بين أهل العلم، فمن أهل العلم من قال: إنه يكون كافرًا كفرًا أكبر، ويحتج بالحديثين الذين ذكرتهما أيها السائل، وهما حديثان صحيحان عن النبي عليه الصلاة والسلام، أحدهما قوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، خرجه الإمام أحمد بن حنبل في المسند بإسناد جيد، وخرجه أيضًا أبو داود و الترمذي و النسائي و ابن ماجه وآخرون بإسناد صحيح عن بريدة بن الحصيب الأسلمي ، عن النبي عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. والحديث الثاني قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، خرجه الإمام مسلم في صحيحه عن جابر بن عبد الله رضي الله تعالى عنهما عن النبي عليه الصلاة والسلام. قالوا: والكفر إذا عرف فهو الكفر الأكبر، وهكذا الشرك إذا عرف فهو الشرك الأكبر، فمعنى: بين الرجل وبين الوقوع في الكفر الأكبر والشرك الأكبر تركه الصلاة، وهذا يعم من تركها جاحدًا ومن تركها متكاسلًا، وهذا القول هو الصواب وهو الأصح من قولي العلماء، أن من تركها تكاسلًا يكون كافرًا كفرًا أكبر، ويدل على هذا أيضًا الحديث الثالث وهو قوله ﷺ لما سئل عن الأمراء الذين يخلون بالدين بعده عليه الصلاة والسلام، قال للناس: إنه سيلي عليكم أمراء، فتعرفون وتنكرون، قالوا: يا رسول الله! أفلا نقاتلهم؟ قال: لا، إلا أن تروا كفرًا بواحًا، عندكم من الله فيه برهان، هكذا جاء في الحديث الصحيح في الصحيحين، وفي رواية قال: ما أقاموا فيكم الصلاة فدل على أن ترك الصلاة وعدم إقامتها يعتبر من الكفر البواح، الذي يوجب القيام على الوالي إذا ترك ذلك، ويعتبر بذلك كافرًا كفرًا بواحًا، يجب أن يقام عليه من المسلمين حتى يولى غيره على المسلمين. فالمقصود أن ترك الصلاة على الأصح يعتبر كفرًا بواحًا. وذهب آخرون من أهل العلم إلى تأويل هذين الحديثين وأن المراد كفر دون كفر، وشرك دون شرك، وأنه لا يكفر بذلك إلا إذا جحد وجوبها أو استهزأ بها، بل يكون عاصيًا، وقد أتى جريمة عظيمة وكبيرة عظيمة، ولكن لا يكون كافرًا كفرًا أكبر، وهذا هو المعروف من مذهب مالك والشافعي وأبي حنيفة و جماعة، ولكن القول الأول أصح وأصوب وأقرب للدليل. فالواجب على كل مسلم أن يحذر ذلك، وأن يستقيم على أداء الصلاة، وأن لا تمنعه وظيفته أو شهواته من إقامة الصلاة في وقتها، بل يجب أن يحذر ذلك، وكذلك لا يجوز له أن يطاوع جلساء السوء في ذلك، بل يجب أن يحذر ذلك وأن يكون قويًا على جلساء السوء يأمرهم بالصلاة ويعينهم عليها، وإذا تركوا فارقهم وخالفهم وأداها في وقتها، فهذه نصيحتي لكل مسلم، فليتق الله كل مسلم، وليحذر ترك الصلاة، فإن تركها من أعظم الجرائم بل تركها كفر أكبر في أصح قولي العلماء، بسببه لا يجوز له أن تبقى معه زوجته المسلمة، بل عليها أن تفارقه، وأن تمتنع منه حتى يتوب إلى الله  من ترك الصلاة. رزق الله الجميع العافية والهداية. المقدم: اللهم آمين. إذًا إذا أذن لي سماحة الشيخ في ملخص للإجابة: من تركها تكاسلًا وتهاونًا فهو  كافر؟\nالشيخ: نعم كفر أكبر في الصحيح.. في أصح قولي العلماء.\nالمقدم: كمن تركها جاحدًا لوجوبها ؟\nالشيخ: كمن تركها جاحدًا، لكن من تركها جاحدًا هذا بالإجماع.\nالمقدم: من تركها جاحدًا ...\nالشيخ: فقد أجمع المسلمون على أنه كافر كفرًا أكبر، لكن من تركها تكاسلًا وهو يعلم أنها واجبة، ويعترف أنها واجبة، ولكن يحمله الكسل والتهاون وقلة المبالاة على تركها فهذا هو الذي فيه الخلاف، والصواب أنه يكون كافرًا كفرًا أكبر للأحاديث التي سمعت في الجواب . نعم .\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم، وهدى المسلمين إلى صلاح دينهم.\nالشيخ: آمين .. آمين .. آمين.","link":"https://binbaz.org.sa/fatwas/18485/ما-القول-الراجح-في-حكم-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89303.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":19332,"question":"علمنا من حلقات البرنامج أن تارك الصلاة مطلقًا يعد كافرًا خارجًا عن الملة على الصحيح من الأقوال، فهل يحرم علينا أكل شيء مما ذبحه تارك الصلاة؟","title":"هل تجوز ذبيحة تارك الصلاة؟","answer":"الجواب: نعم، هذا مقتضى الحكم بتكفيره، فإن ذبيحة الكافر محرمة إلا أهل الكتاب وهم اليهود والنصارى خاصة، أما المرتد بترك الصلاة، أو بسب الدين، أو بالاستهزاء بالدين، أو بجحد وجوب الصلاة، أو بجحد وجوب الصيام رمضان، أو بغير هذا من نواقض الإسلام هذا حكمه حكم الوثنيين، بل أشد من الوثنيين، لا تؤكل ذبيحته إذا ذبح ذبيحة تكون حرامًا؛ لأنه مرتد ليس من جنس أهل الكتاب، بل المرتد فوق أهل الكتاب في الكفر فهو من جنس الوثنيين، ومن جنس المجوس لا تؤكل ذبيحته.","link":"https://binbaz.org.sa/fatwas/18539/هل-تجوز-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_897/nour_89703.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":19360,"question":"إذا ابتليت المرأة برجل لا يصلي، فهل تمتنع عنه؟ أم كيف تتصرف؟ علمًا بأن لديها جمع من الأطفال، وهي صابرة على ذلكم الحال من أجل الأطفال؟","title":"حكم مَن ابتليت بزوج تارك للصلاة","answer":"الجواب: ترك الصلاة من أعظم الكبائر والجرائم، إذا كان يقر بوجوبها، ويعلم وجوبها، ويؤمن به، إما إن كان يجحد وجوبها، ولا يؤمن به؛ فهذا كافر عند جميع أهل العلم، ولا يجوز للمسلمة البقاء معه، ولا يحل لها تمكينه من نفسها؛ لأنه كافر مرتد عند جميع العلماء. أما إن كان يتركها تهاونًا وكسلًا، ولكنه يؤمن بأنها حق، وأنها فريضة؛ فهذا محل خلاف بين أهل العلم هل يكفر كفرًا أكبر، أم يكون كفره كفرًا أصغر؛ على قولين لأهل العلم، والراجح من القولين: أنه يكون كافرًا كفرًا أكبر؛ لأن الصلاة عمود الإسلام، وهي أعظم الأركان بعد الشهادتين. وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، عن بريدة بن الحصيب ، وفي صحيح مسلم رحمه الله عن جابر بن عبد الله الأنصاري رضي الله تعالى عنهما عن النبي عليه الصلاة والسلام أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فهذا يدل على أنه يكون كافرًا كفرًا أكبر، ولو لم يجحد الوجوب، ولهذا القول أدلة أخرى كلها تدل على أنه كافر كفرًا أكبر، كفرًا أكبر إذا تركها تهاونًا وهو يقر بوجوبها. ومن ذلك ما جاء في الأحاديث الصحيحة عن النبي ﷺ أنه قال لما سئل عن الأئمة الذين توجد منهم بعض المعاصي قال له السائل: أفنقاتلهم؟ قال: لا. ما أقاموا فيكم الصلاة وفي الرواية الأخرى: إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان فجعل ترك الصلاة كفرًا بواحًا يحل مقاتلة ولاة الأمور. فالمقصود أن الواجب على المسلمين أن يحافظوا على الصلاة، وأن يؤدوها كما أمر الله، وأن يحذروا الكسل عنها، وأنهم متى تركوها جحدًا لوجوبها صار التارك كافرًا بالإجماع، وإن تركها كسلًا وتهاونًا صار كافرًا كفرًا أكبر في أصح قولي العلماء، تبين منه امرأته، ولا يحل له الاتصال بها، ولا يحل لها تمكينه من نفسها حتى يتوب إلى الله من ترك الصلاة. نسأل الله لجميع المسلمين الهداية والتوفيق، كما نسأله سبحانه أن يبصرهم في دينهم، وأن يعينهم على أداء الواجب، وأن يعيذهم من شرور النفس، وسيئات العمل. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18575/حكم-من-ابتليت-بزوج-تارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_942/nour_94203.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":19441,"question":"يقول عن نفسه: كنت لا أصلي ولكن الآن والحمد لله أنا محافظ على الصلاة وعندما كان أهلي يحثوني على الصلاة كنت أقول لهم حسب ما يصف نفسه (إنه كافر) ولكن ندمت عليها بعد أن هداني الله، فهل لي توبة؟ أفيدوني أفادكم الله.","title":"من وَصْف نفسه بالكفر هل له توبة؟","answer":"الجواب: نعم كل ذنب له توبة حتى الشرك الأكبر، فعليك التوبة إلى الله  والندم على ما مضى منك والعزم الصادق ألا تعود والله يتوب على من تاب سبحانه، والحمد لله الذي من عليك بالتوبة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18675/من-وصف-نفسه-بالكفر-هل-له-توبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93804.mp3","categories":["حكم الصلاة وأهميتها","قضاء الصيام","الرقائق"]},{"id":19461,"question":"هل إذا كان لك أخ أو أخت لا يصلي إلا في رمضان ونصحته عدة مرات في الصلاة، ولكنه لم يقبل النصيحة إذا قاطعته ولم تعد تكلمه ولا تزوره في بيته، ولا ترد عليه السلام، وكان أكبر منك بعدة سنوات، هل يعتبر ذلك قطيعة للرحم أم لا جزاكم الله خيرًا؟","title":"حكم هجر تارك الصلاة","answer":"الجواب: هذا هو المشروع، وهذا هو الهجر المشروع، وليس بقطيعة، بل هذا من إنكار المنكر ومن الجهاد في سبيل الله، فهجران أهل المعاصي أمر مشروع، وإذا نصحته واجتهدت، ومع هذا لم ينفع فيه فهو كافر بهذا الترك ترك الصلاة كفر أكبر، وهو يستحق الهجر والابتعاد عنه والقطيعة له حتى يتوب، نسأل الله السلامة والعافية.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18708/حكم-هجر-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74021.mp3","categories":["حكم الصلاة وأهميتها"]},{"id":19537,"question":"هذه رسالة وصلت من الجزائر العاصمة الأخت (ج.ب) تقول في هذا  امرأة تبلغ من العمر خمسين سنة، ولم تصل طيلة حياتها أبدًا حتى يومنا هذا، ولم تقض ما أفطرت من رمضان أثناء الحيض أبدًا، ماذا يجب عليها أن تفعل إذا أرادت التوبة، وهل تصوم جميع تلك السنين التي أفطرتها من رمضان أثناء الحيض ولم تقض مع العلم بأنها لم تكن تصلي وما تزال لا تصلي حتى الآن، وهذه المرأة قريبة لأمي، وجارة لنا في نفس الوقت، كيف ننصحها لكي تتوب إلى الله؛ لأننا نصحناها عدة مرات بدون جدوى، لقد نصحناها برفق، وبالتي هي أحسن هل نكون بريئين من ذمتها إذا لم تتوب، وجهوها مأجورين؟","title":"حكم القريب الذي لا يصلي رغم نصحه","answer":"الجواب: الواجب نصيحتها وإخبارها بأنها إذا تابت تاب الله عليها، عليها التوبة مما مضى، ويسقط عنها الصوم، والصلاة الماضي، عليها التوبة الصادقة بالندم على ما مضى، والإقلاع من ذلك، والعزم أن لا تعود في ذلك، مع الضراعة إلى الله، وسؤاله أن يقبل منها توبتها، وعليها أن تصلي، وتصوم بعد التوبة، إلا في وقت الحيض فالله أسقط عنها الصلاة، فإذا جاء الحيض فلا صلاة عليها، وإذا جاء الحيض في رمضان أفطرت وقضت. فالواجب أن تعلموها وأن ترشدوها، وأن تنصحوها، ومن تاب تاب الله عليه يقول الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا[التحريم:8] ويقول جل وعلا في كتابه العزيز: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ[النور:31] ويقول النبي ﷺ: التائب من الذنب كمن لا ذنب له، فإذا تابت عفا الله عنها، وليس عليها قضاء لا للصلاة، ولا للصوم، عليها التوبة فقط، ولا قضاء عليها، وعليها أن تجتهد في المستقبل في المحافظة على الصلوات، والصيام. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18789/حكم-القريب-الذي-لا-يصلي-رغم-نصحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94622.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":19567,"question":"بالنسبة - يقول السائل - عن صلاة الأولاد دون العاشرة: هل على الوالدين إثم إذا لم يلتزموا في هذه الصلاة؟","title":"إذا لم يلتزم الأولاد الذين دون العشر بالصلاة هل يأثم الوالدان؟","answer":"الجواب: يأمرونهم بها فقط، ولا إثم عليهم، فإذا بلغوا عشرًا وجب أمرهم، وتأديبهم حتى يصلوا، أما دون العشر ما فوق السابعة ودون العشر فالمشروع الأمر فقط، إذا بلغ سبعًا يؤمر ولا يضرب، فإذا بلغ عشرًا فأكثر يضرب عليها. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18830/اذا-لم-يلتزم-الاولاد-الذين-دون-العشر-بالصلاة-هل-ياثم-الوالدان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94719.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":19663,"question":"تقول سماحة الشيخ: امرأة تصلي وتصوم وعندها أولاد والزوج لا يصلي، ونصحته عدة مرات، ولكنه لم يستجب ماذا تعمل؟ هل يجوز لها أن تبقى معه؟","title":"ماذا يجب على المرأة إذا كان زوجها لا يصلي؟","answer":"الجواب: ليس لها أن تبقى معه، بل عليها أن تفارقه، وليس لها أن تمكنه من نفسها، وعليها أن تطلب الفراق ولو من المحكمة، يجب عليها أن تفارقه، وأن تذهب إلى أهلها، وهي أولى بأولادها منه الصغار، ولا يجوز لها البقاء معه؛ لأن من ترك الصلاة كفر، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة نسأل الله العافية. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18952/ماذا-يجب-على-المراة-اذا-كان-زوجها-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95017.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]}]
